// Best-effort "click a result → open its module page" map, keyed by `module`.
// Deliberately incomplete: a handful of modules (poles, purchase_requests, timber,
// production) have no single matching NAV page (they're split across several
// daily-log pages on this desktop app) — those results simply render unclickable,
// same tradeoff the mobile app made rather than guessing wrong.
const SEARCH_MODULE_PAGE = {
  sales: 'sales', deliveries: 'deliveries', dispatch: 'dispatch',
  stock_transfers: 'stock-transfers', inventory: 'stock-items',
  workshop: 'warehouses', machines: 'machines', fuel: 'machine-fuel',
  material_requests: 'material-requests', labour: 'casual-requests',
  customers: 'customers', products: 'products', vehicles: 'vehicles',
  users: 'users', audit_logs: 'audit', change_requests: 'changes', notifications: 'notifications',
};
// Reports results carry a fixed `id` (weekly-perf, bi, ceo-overview, …) instead of
// a per-record id — map by id, not by module, straight to the matching NAV page.
const SEARCH_REPORT_PAGE = {
  'weekly-perf': 'weekly-perf', 'weekly-cost': 'weekly-cost', executive: 'executive',
  bi: 'bi', epm: 'epm', 'ceo-overview': 'ceo',
};
// Inverse of SEARCH_MODULE_PAGE, used to default Global Search's scope to
// whichever module the currently-active page represents ("Context Search").
const PAGE_TO_SEARCH_MODULE = Object.fromEntries(
  Object.entries(SEARCH_MODULE_PAGE).map(([mod, page]) => [page, mod])
);

