// Modules where the list page itself IS the natural destination (no
// per-record edit view to open, and none is needed) — plain page navigation.
// Reports results already point straight at their own dashboard page, which
// is the exact destination, not a list to search within.
const SEARCH_MODULE_PAGE_ONLY = new Set(['notifications', 'reports']);
// Everything else has a page but no general "view/edit this record" control
// (dispatch/stock_transfers/material_requests/change_requests/labour/fuel/
// products/audit_logs are approval-workflow or read-only tables with only
// create/approve/reject overlays) — falls back to a read-only preview overlay
// built from the result's own fields, same tradeoff as the mobile app makes.

function $(id) {
  return document.getElementById(id);
}

function downloadCsv(content, filename) {
  const blob = new Blob([content], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

function show(el, on) {
  el.style.display = on ? '' : 'none';
}

function setActivePage(id) {
  CURRENT_PAGE = id;
  document.querySelectorAll('.page').forEach((p) => p.classList.remove('active'));
  const el = $(`page-${id}`);
  if (el) el.classList.add('active');

  document.querySelectorAll('.ni').forEach((n) => n.classList.remove('active'));
  const ni = $(`ni-${id}`);
  if (ni) ni.classList.add('active');
}

function soStatusBadge(status) {
  const map = {
    Pending: 'ba', Confirmed: 'bb', Dispatched: 'bp',
    'In Progress': 'bp', 'Partially Delivered': 'ca',
    'Fully Delivered': 'bg', Delivered: 'bg',
    'Closed (Short)': 'bt', Cancelled: 'br'
  };
  return `<span class="badge ${map[status] || 'ba'}">${status || 'Pending'}</span>`;
}

function roleLabel(role) {
  const map = {
    admin:                   'System Admin',
    ceo:                     'CEO',
    operations:              'Operations Manager',
    sales:                   'Sales Manager',
    finance:                 'Finance Manager',
    logistics:               'Logistics Manager',
    supervisor:              'Supervisor',
    'logistics-officer':     'Logistics Officer',
    storekeeper:             'Workshop Storekeeper',
    'storekeeper-assistant': 'Storekeeper Assistant',
    mechanician:             'Mechanician',
    'harvesting-leader':     'Harvesting Leader',
    'sawmill-leader':        'Sawmill Leader',
    'poles-leader':          'Poles Production Leader',
    'vat-leader':            'Value-Added Timber Leader',
    'harvesting-supervisor': 'Harvesting Supervisor',
    'sawmill-supervisor':    'Sawmill Supervisor',
    'poles-supervisor':      'Poles Supervisor',
    'vat-supervisor':        'Value-Added Production Supervisor',
    'sales-staff':           'Workshop Sales Staff',
    'showroom-staff':        'Showroom Sales Staff',
    'procurement-officer':   'Procurement Officer',
    'procurement-manager':   'Procurement Manager',
    'department-manager':    'Department Manager',
  };
  return map[role] || role;
}

function roleOptionHtml(role) {
  return `<option value="${role}">${roleLabel(role)}</option>`;
}

function pageTitle(pageId) {
  const item = NAV.find((x) => x.id === pageId);
  return item?.label || pageId;
}

function renderPermissionCheckboxes(selected = []) {
  const grpHdr = (label) => `<div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:var(--g-soft);margin:10px 0 4px;padding-top:6px;border-top:1px solid var(--bdr)">${label}</div>`;
  const chk = (id, label) => `
    <label style="display:flex;align-items:center;gap:.5rem;margin-bottom:.4rem;cursor:pointer;font-size:12.5px">
      <input type="checkbox" class="perm-checkbox" value="${id}" ${selected.includes(id)?'checked':''} style="width:14px;height:14px;accent-color:var(--g-soft)">
      ${label || pageTitle(id)}
    </label>`;

  return [
    grpHdr('Overview'),
    chk('dashboard'), chk('ceo', 'CEO Overview'),

    grpHdr('Production'),
    chk('daily-harvest',      'Harvesting Daily'),
    chk('sawmill-dashboard',  'Sawmill Dashboard'),
    chk('daily-timber',       'Timber Daily'),
    chk('daily-poles',        'Poles Daily'),
    chk('value-added-production', 'Value-Added Production'),
    chk('machine-logs',       'Machine Daily Logs'),

    grpHdr('Forestry'),
    chk('timber-inventory'), chk('compartments'), chk('log-transport'),

    grpHdr('Labour'),
    chk('casual-requests', 'Labour Requests'), chk('casuals'), chk('attendance'),

    grpHdr('Workshop & Stock'),
    chk('workshop-overview', 'Workshop Overview'), chk('warehouses', 'Workshops'),
    chk('stock-items', 'Stock Catalog'), chk('inventory', 'Inventory'),
    chk('stock-movements', 'Stock Movements'), chk('stock-transfers', 'Stock Transfers'), chk('material-requests', 'Material Requests'),
    chk('inventory-loss-reports', 'Inventory Loss Reports'),

    grpHdr('Fleet & Machines'),
    chk('machines', 'Machine Registry'), chk('machine-fuel', 'Fuel Logs (Machines)'),
    chk('machine-kpi', 'KPI Performance'), chk('vehicles', 'Vehicle Fleet'),
    // Stabilization Phase 4 — these three backend permission keys (granted
    // via db/migrate.js's grantMaintenanceJobsPermissions and used throughout
    // data.js's maintenance-job functions) had no checkbox here, so a role's
    // access to them could only ever be set by a one-time migration, never
    // through this editor.
    chk('machine-maintenance', 'Maintenance Schedule'), chk('maintenance-jobs', 'Maintenance Jobs'),
    chk('maintenance-oversight', 'Maintenance Oversight'),

    grpHdr('Logistics'),
    chk('logistics-dashboard', 'Logistics Dashboard'), chk('deliveries', 'Delivery Orders'),
    chk('dispatch'), chk('transport', 'Transport Carriers'), chk('transport-jobs', 'Transport Jobs'),
    // Phase 1 naming fix — was grouped under "Commercial" and labeled "Legacy
    // Logistics" despite living in the Logistics NAV section; moved here and
    // renamed to match its actual on-page title.
    chk('logistics', 'Spare Parts & Materials'),

    grpHdr('Commercial'),
    chk('sales', 'Sales Orders'), chk('products', 'Product Catalog'), chk('showroom', 'Showroom'),

    grpHdr('Reports'),
    chk('weekly-cost'), chk('weekly-perf'), chk('monthly', 'Monthly Dashboard'),
    chk('kpi', 'KPI Scorecard'), chk('sage', 'Sage Reconciliation'),

    grpHdr('Procurement'),
    chk('procurement-dashboard', 'Procurement Dashboard'), chk('procurement-suppliers', 'Suppliers'),
    chk('procurement-requisitions', 'Requisitions'), chk('procurement-rfq', 'RFQ / Quotations'),
    chk('procurement-orders', 'Purchase Orders'), chk('procurement-goods-receipt', 'Goods Receipt'),
    chk('procurement-invoices', 'Invoices & Payments'), chk('procurement-reports', 'Procurement Reports'),

    grpHdr('System'),
    chk('users'), chk('changes', 'Change Requests'), chk('notifications'),
    chk('audit', 'Audit Trail'), chk('export', 'Exports'),
  ].join('');
}

function shortName(name) {
  const parts = String(name || '').trim().split(/\s+/).filter(Boolean);
  if (!parts.length) return 'UF';
  const a = parts[0][0] || 'U';
  const b = parts[1]?.[0] || (parts[0][1] || 'F');
  return (a + b).toUpperCase();
}

function updateBadge() {
  const b = $('nbadge');
  if (!b) return;
  if (STORAGE.unread > 0) {
    b.style.display = 'flex';
    b.textContent = STORAGE.unread > 99 ? '99+' : String(STORAGE.unread);
  } else {
    b.style.display = 'none';
    b.textContent = '';
  }
}

function startNotificationPoll() {
  if (_pollTimer) return;
  _pollTimer = setInterval(async () => {
    try {
      const r = await UFCL.notificationsPoll();
      if (r?.ok && typeof r.unread === 'number' && r.unread !== STORAGE.unread) {
        STORAGE.unread = r.unread;
        updateBadge();
      }
      if (CURRENT_PAGE === 'notifications') {
        const scrollEl = $('notif-scroll');
        const top = scrollEl ? scrollEl.scrollTop : 0;
        await _loadNotifItems();
        const newScroll = $('notif-scroll');
        if (newScroll) newScroll.scrollTop = top;
      }
      if (CURRENT_PAGE === 'secgov' && Date.now() - _secGovLastLoad >= 5 * 60_000) {
        await renderSecGovDashboard();
      }
      if (CURRENT_PAGE === 'executive' && Date.now() - _execLastLoad >= 5 * 60_000) {
        await renderExecutiveDashboard();
      }
      if (CURRENT_PAGE === 'bi' && Date.now() - _biLastLoad >= 5 * 60_000) {
        await renderBI();
      }
      if (CURRENT_PAGE === 'automation' && Date.now() - _autoLastLoad >= 5 * 60_000) {
        await renderAutomationCenter();
      }
      if (CURRENT_PAGE === 'epm' && Date.now() - _epmLastLoad >= 5 * 60_000) {
        await renderEPM();
      }
    } catch (_) {}
  }, 60_000);
}

function stopNotificationPoll() {
  if (_pollTimer) { clearInterval(_pollTimer); _pollTimer = null; }
}

function sectionsFromNav(list) {
  const secs = [];
  for (const n of list) if (!secs.includes(n.sec)) secs.push(n.sec);
  return secs;
}

function buildSidebar(allowedPages) {
  const allowed = new Set(Array.isArray(allowedPages) ? allowedPages : []);
  const secs = sectionsFromNav(NAV);
  let html = '';
  for (const s of secs) {
    const items = NAV.filter((x) => x.sec === s);
    const visible = items.filter((it) => allowed.has(it.id));
    if (!visible.length) continue;
    html += `<div class="nsec">${s}</div>`;
    for (const n of visible) {
      html += `<div class="ni" id="ni-${n.id}" role="button">
        <i class="ti ${n.icon}"></i><span>${n.label}</span>
      </div>`;
    }
  }
  $('sidebar').innerHTML = html;
  NAV.forEach((n) => {
    const el = $(`ni-${n.id}`);
    if (el) el.onclick = () => showPage(n.id);
  });
}

// Enterprise UI/UX Standardization Phase 3 — Escape-to-close is wired once
// here rather than per screen, so all 136+ existing openOverlay() call sites
// benefit immediately. The handler reference is tracked so a repeated
// openOverlay() call (without an intervening closeOverlay()) swaps it
// instead of stacking a second document-level listener.
let _overlayEscHandler = null;

function openOverlay(title, subtitle, bodyHtml, onSave, extraClass = '') {
  const o = $('overlay');
  o.innerHTML = `
    <div class="ow ${extraClass}">
      <div class="owh">
        <h3><i class="ti ti-edit"></i>${title}</h3>
        <button type="button" class="bs1" id="ovClose" aria-label="Close dialog"><i class="ti ti-x"></i>Close</button>
      </div>
      <div class="owc">
        ${subtitle ? `<div class="psub" style="margin-bottom:.75rem">${subtitle}</div>` : ''}
        <div class="lerr" id="ovErr" role="alert"></div>
        ${bodyHtml}
      </div>
    </div>`;
  o.style.display = 'flex';
  $('ovClose').onclick = closeOverlay;
  const cancelBtn = $('ovCancel');
  if (cancelBtn) cancelBtn.onclick = closeOverlay;
  const saveBtn = $('ovSave');
  if (saveBtn) saveBtn.onclick = async () => {
    const errEl = $('ovErr');
    if (errEl) { errEl.style.display = 'none'; errEl.textContent = ''; }
    await onSave?.();
  };

  if (_overlayEscHandler) document.removeEventListener('keydown', _overlayEscHandler);
  _overlayEscHandler = (e) => { if (e.key === 'Escape') closeOverlay(); };
  document.addEventListener('keydown', _overlayEscHandler);
}

function closeOverlay() {
  const o = $('overlay');
  o.style.display = 'none';
  o.innerHTML = '';
  if (_overlayEscHandler) { document.removeEventListener('keydown', _overlayEscHandler); _overlayEscHandler = null; }
}

// Enterprise UI/UX Standardization Phase 1, Workstream B — shared KPI-tile
// renderer. Produces the exact `.mc` markup ~70 render* functions already
// hand-type inline (230+ times); this is a drop-in for new/touched code, not
// a forced rewrite of every existing card. `trend` accepts pre-rendered HTML
// (e.g. the output of a local trendBadge() helper) rather than recomputing
// trend logic itself, so callers keep full control of their own trend rules.
// For click-through tiles, pass `id` (wire `$(id).onclick = ...` after the
// innerHTML assignment, same convention every dynamic element in this file
// already follows) or `cls`/`data` for the querySelectorAll-group delegation
// pattern several dashboards already use (e.g. `.mj-kpi-link[data-status]`).
function kpiTileHtml({ icon, label, value, valueColor = '', valueStyle = '', borderColor = '', sub = '', subCls = '', trend = '', cls = '', id = '', data = {} }) {
  const dataAttrs = Object.entries(data).map(([k, v]) => ` data-${k}="${v}"`).join('');
  const clickable = !!(id || Object.keys(data).length);
  return `<div class="mc${cls ? ' ' + cls : ''}"${id ? ` id="${id}"` : ''}${dataAttrs} style="${borderColor ? `border-top:3px solid ${borderColor};` : ''}${clickable ? 'cursor:pointer' : ''}">
    <div class="mclbl">${icon ? `<i class="ti ${icon}" style="margin-right:4px"></i>` : ''}${label}</div>
    <div class="mcval" style="${valueColor ? `color:${valueColor};` : ''}${valueStyle}">${value}</div>
    ${trend ? `<div class="mcsub">${trend}</div>` : (sub ? `<div class="mcsub${subCls ? ' ' + subCls : ''}">${sub}</div>` : '')}
  </div>`;
}

// Enterprise UI/UX Standardization Phase 1, Workstream D — shared Alerts
// banner. Generalizes the ad-hoc `.lerr` error banner (styles.css) and the
// hand-typed amber "pending approvals" banner duplicated at ~4 call sites
// into one helper covering all 4 severities, reusing the same color tokens
// the badge palette already uses so Alerts stay visually consistent with
// everything else. Dismiss uses a plain inline DOM handler (no global
// function reference needed) — consistent with the small inline-onclick
// patterns already used elsewhere in this file (e.g. event.stopPropagation()
// on table checkboxes).
const ALERT_META = {
  critical: { bg: 'var(--red-l)',   border: 'rgba(220,38,38,.25)',  color: '#991B1B', icon: 'ti-alert-triangle' },
  warning:  { bg: 'var(--amber-l)', border: 'rgba(217,119,6,.25)',  color: '#92400E', icon: 'ti-alert-circle' },
  info:     { bg: 'var(--blue-l)',  border: 'rgba(29,78,216,.25)',  color: 'var(--blue)', icon: 'ti-info-circle' },
  success:  { bg: 'var(--g-light)', border: 'rgba(30,95,54,.2)',    color: 'var(--g-dark)', icon: 'ti-circle-check' },
};
function alertHtml(type, message, dismissible = false) {
  const m = ALERT_META[type] || ALERT_META.info;
  return `<div class="ent-alert" style="display:flex;align-items:center;gap:.625rem;padding:.75rem 1rem;background:${m.bg};border:1px solid ${m.border};border-radius:7px;margin-bottom:1.25rem;font-size:13px;color:${m.color}">
    <i class="ti ${m.icon}" style="font-size:16px;flex-shrink:0"></i>
    <span style="flex:1">${message}</span>
    ${dismissible ? `<i class="ti ti-x" style="cursor:pointer;flex-shrink:0;opacity:.6" onclick="this.closest('.ent-alert').remove()"></i>` : ''}
  </div>`;
}

// Timber Lifecycle Phase 1 (Workstream 2) — the ONE reusable Resolution
// Engine modal, shared by Harvest Waste and Production Offcuts (the two
// callers pass their own sourceType/sourceId/maxVolume; nothing here is
// specific to either). destination list matches the brief's own fixed
// enumeration exactly.
async function openResolutionModal(sourceType, sourceId, maxVolume, onDone) {
  const whRes = await UFCL.warehousesList(STORAGE.user.id, null);
  const warehouses = whRes.ok ? (whRes.rows || whRes.warehouses || []) : [];
  openOverlay(
    'Resolve waste',
    `${{ harvest_waste: 'Harvest waste', rejected_timber: 'Rejected timber', showroom_damage: 'Damaged stock' }[sourceType] || 'Production offcut'} #${sourceId} — up to ${maxVolume} units outstanding`,
    `
      <div class="frow">
        <div class="fg"><label>Destination *</label><select id="res-dest">
          <option value="Firewood">Firewood</option>
          <option value="Scrap Sale">Scrap Sale</option>
          <option value="Internal Use">Internal Use</option>
          <option value="Disposal">Disposal</option>
          <option value="Other">Other</option>
        </select></div>
        <div class="fg"><label>Volume</label><input type="number" id="res-volume" value="${maxVolume}" readonly style="background:var(--bg2);cursor:default"></div>
      </div>
      <p style="font-size:11px;color:var(--t3);margin:-.25rem 0 .75rem">Resolves the full outstanding quantity — a partial resolution would leave the remainder untracked, so this engine requires the whole amount to go to one destination.</p>
      <div class="frow" id="res-detail-row" style="display:none">
        <div class="fg"><label>Destination detail *</label><input type="text" id="res-detail" placeholder="Describe the destination"></div>
      </div>
      <div class="frow" id="res-stock-row" style="display:none">
        <div class="fg"><label>Location *</label><select id="res-warehouse"><option value="">— Select —</option>${warehouses.map(w => `<option value="${w.id}">${w.name}</option>`).join('')}</select></div>
        <div class="fg"><label>Unit cost (RWF, optional)</label><input type="number" id="res-cost" min="0"></div>
      </div>
      <div class="frow full"><div class="fg"><label>Notes</label><textarea id="res-notes" rows="2"></textarea></div></div>
      <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-recycle" style="font-size:13px;vertical-align:-1px"></i> Resolve</button><button class="bs1" id="ovCancel">Cancel</button></div>
    `,
    async () => {
      const destination = $('res-dest').value;
      const volume = maxVolume;
      const payload = { source_type: sourceType, source_id: sourceId, destination, volume, notes: $('res-notes').value.trim() || undefined };
      if (destination === 'Other') {
        const detail = $('res-detail').value.trim();
        if (!detail) return showOverlayError('Destination detail is required for "Other".');
        payload.destination_detail = detail;
      }
      if (['Firewood', 'Scrap Sale', 'Internal Use'].includes(destination)) {
        const wid = $('res-warehouse').value;
        if (!wid) return showOverlayError('A location is required for this destination.');
        payload.warehouse_id = Number(wid);
        const cost = $('res-cost').value;
        if (cost) payload.unit_cost = Number(cost);
      }
      const r = await UFCL.resolutionCreate(STORAGE.user.id, payload);
      if (!r.ok) return showOverlayError(r.error || 'Failed to resolve.');
      closeOverlay();
      showToast('Resolved successfully.', 'success');
      if (onDone) onDone();
    }
  );
  setTimeout(() => {
    const destSel = $('res-dest'), detailRow = $('res-detail-row'), stockRow = $('res-stock-row');
    const toggle = () => {
      const d = destSel.value;
      detailRow.style.display = d === 'Other' ? '' : 'none';
      stockRow.style.display = ['Firewood', 'Scrap Sale', 'Internal Use'].includes(d) ? '' : 'none';
    };
    destSel.onchange = toggle;
    toggle();
  }, 30);
}

// Remediation Phase 3 — resolutionsList (data.js:9267) was built with a full
// governed, workshop-isolated read query but had zero UI callers on either
// platform; once a waste/rejection/damage record was marked "Resolved" (see
// the badges at, e.g., line ~3499), the actual resolution — where the
// material went, cost, notes, who resolved it — became permanently invisible
// in the UI even though the backend always stored it. This read-only history
// view reuses the existing resolution engine exactly as instructed (no new
// table, no new query beyond what resolutionsList already runs) and is
// opened from each of the 4 existing "Resolve" call sites below.
async function openResolutionHistoryModal(sourceType) {
  const label = { harvest_waste: 'Harvest Waste', rejected_timber: 'Rejected Timber',
    production_offcut: 'Production Offcuts', showroom_damage: 'Damaged Stock' }[sourceType] || 'Resolutions';
  const res = await UFCL.resolutionsList(STORAGE.user.id, sourceType);
  const rows = res.ok ? (res.rows || []) : [];
  openOverlay(`Resolution History — ${label}`, null, `
    ${!res.ok ? `<div class="lerr" style="display:block">${res.error}</div>` : ''}
    <div class="tw"><table class="dt" style="font-size:12px">
      <thead><tr><th>Date</th><th>Destination</th><th>Volume</th><th>Location</th><th>Notes</th><th>Resolved by</th></tr></thead>
      <tbody>${rows.length ? rows.map(r => `<tr>
        <td style="white-space:nowrap">${new Date(r.resolved_at).toLocaleDateString()}</td>
        <td>${r.destination}${r.destination_detail ? ' — ' + r.destination_detail : ''}</td>
        <td style="font-family:var(--fm)">${Number(r.volume).toLocaleString()}${r.stock_item_name ? ' ' + r.stock_item_name : ''}</td>
        <td style="color:var(--t3)">${r.warehouse_name || '—'}</td>
        <td style="color:var(--t3);max-width:220px">${r.notes || '—'}</td>
        <td>${r.resolved_by_name || '—'}</td>
      </tr>`).join('') : '<tr><td colspan="6" style="text-align:center;color:var(--t3);padding:2rem">No resolutions recorded yet.</td></tr>'}</tbody>
    </table></div>
    <div class="brow">
      <button class="bs1" id="resHistExport"><i class="ti ti-download"></i> Export CSV</button>
      <button class="bs1" id="ovCancel">Close</button>
    </div>`, null);
  // ERP Final Enterprise Hardening Phase — Reporting Completion (Priority 6):
  // resolutionsList had no export path anywhere.
  const exportBtn = document.getElementById('resHistExport');
  if (exportBtn) exportBtn.onclick = () => {
    if (!rows.length) { showToast('No resolutions to export.', 'error'); return; }
    const header = 'Date,Destination,Volume,Location,Notes,Resolved By';
    const csv = [header, ...rows.map(r => [
      new Date(r.resolved_at).toLocaleDateString(),
      `"${(r.destination + (r.destination_detail ? ' — ' + r.destination_detail : '')).replace(/"/g, '""')}"`,
      `${r.volume}${r.stock_item_name ? ' ' + r.stock_item_name : ''}`,
      `"${(r.warehouse_name || '').replace(/"/g, '""')}"`, `"${(r.notes || '').replace(/"/g, '""')}"`,
      `"${(r.resolved_by_name || '').replace(/"/g, '""')}"`,
    ].join(','))].join('\n');
    downloadCsv(csv, `resolution-history-${label.toLowerCase().replace(/\s+/g,'-')}-${new Date().toISOString().slice(0,10)}.csv`);
  };
}

// Timber Lifecycle Phase 1 (Workstream 1) — generalized attachments widget.
// Reused wherever a record supports attachments (currently Harvest Waste;
// Production Offcuts could adopt it the same way later). File picking/
// upload/download all proxy through Electron's attachments:* IPC handlers
// (mobile-api holds the actual bytes — see mobile-api/routes/attachments.js).
async function renderAttachmentsPanel(containerId, entityType, entityId) {
  const el = $(containerId);
  if (!el) return;
  const res = await UFCL.attachmentsList(STORAGE.user.id, entityType, entityId);
  const files = res.ok ? res.rows : [];
  el.innerHTML = `
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.4rem">
      <span style="font-size:11px;font-weight:700;color:var(--t3);text-transform:uppercase;letter-spacing:.03em">Attachments</span>
      <button class="bs1" id="att-add-btn" style="font-size:11px;padding:3px 8px"><i class="ti ti-paperclip"></i> Attach file</button>
    </div>
    ${files.length ? files.map(f => `
      <div style="display:flex;align-items:center;justify-content:space-between;padding:.3rem 0;border-bottom:1px solid var(--bdr);font-size:12px">
        <span><i class="ti ti-file"></i> ${f.original_filename} <span style="color:var(--t3)">(${((f.file_size||0)/1024).toFixed(0)} KB)</span></span>
        <button class="bs1 att-download" data-id="${f.id}" data-name="${f.original_filename}" style="font-size:11px;padding:2px 8px"><i class="ti ti-download"></i></button>
      </div>`).join('') : `<div style="font-size:12px;color:var(--t3)">No attachments yet.</div>`}
  `;
  $('att-add-btn').onclick = async () => {
    const pick = await UFCL.srmDocumentsPickFile();
    if (!pick.ok) return;
    const r = await UFCL.attachmentsUpload(STORAGE.user.id, entityType, entityId, pick.filePath);
    if (!r.ok) return showToast(r.error || 'Upload failed', 'error');
    showToast('Attachment uploaded.', 'success');
    renderAttachmentsPanel(containerId, entityType, entityId);
  };
  el.querySelectorAll('.att-download').forEach(btn => {
    btn.onclick = () => UFCL.attachmentsDownload(STORAGE.user.id, Number(btn.dataset.id), btn.dataset.name);
  });
}

// Enterprise UI/UX Standardization Phase 3 — generic confirmation dialog,
// generalizing confirmDelete()'s pattern for non-delete verbs (Approve/
// Reject/Dispatch/Close/...). Before this helper, each of the 15+ Approve/
// Reject/Dispatch/Close confirmations in this file hand-rolled its own
// openOverlay() wrapper markup and button row independently — most of them
// also collect one optional/required field (a reason, notes), so `extraHtml`
// lets the caller inject that without losing the shared wrapper; the caller
// still owns reading/validating its own field(s) in `onConfirm`, same as
// every one of those call sites already does today.
function confirmAction({ title, message, confirmLabel = 'Confirm', danger = false, icon = 'ti-check', extraHtml = '', onConfirm }) {
  openOverlay(title, null, `
    <p style="color:var(--t1);margin-bottom:1rem">${message}</p>
    ${extraHtml}
    <div class="brow">
      <button class="bp1" id="ovSave" style="${danger ? 'background:var(--red);border-color:var(--red)' : ''}"><i class="ti ${icon}"></i>${confirmLabel}</button>
      <button class="bs1" id="ovCancel">Cancel</button>
    </div>`, onConfirm);

  // Enterprise UI/UX Standardization Phase 3 — Enter-to-submit, scoped to
  // single-line <input> fields only (not <textarea>, where Enter must keep
  // inserting a newline). Built once here so every confirmAction() call
  // benefits, rather than wiring it per call site.
  const ow = document.querySelector('#overlay .ow');
  if (ow) ow.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' && e.target.tagName === 'INPUT') { e.preventDefault(); $('ovSave')?.click(); }
  });
}

// Enterprise UI/UX Standardization Phase 3 — shared empty-state table row.
// Before this helper, ~124 "No X yet"/"No X match" sites in this file were
// each hand-typed in one of 3 inconsistent tiers (bare text / icon+text /
// plain <p>). `subtitle` covers the "what can I do next" hint the brief
// asks for; icon defaults to a generic inbox glyph but callers should pass
// something more specific where one already existed.
function emptyRowHtml({ colspan, icon = 'ti-inbox', title, subtitle = '' }) {
  return `<tr><td colspan="${colspan}" style="text-align:center;color:var(--t3);padding:2.5rem 1rem">
    <i class="ti ${icon}" style="font-size:1.75rem;display:block;margin-bottom:.5rem;opacity:.35"></i>
    <div>${title}</div>
    ${subtitle ? `<div style="font-size:12px;margin-top:.25rem">${subtitle}</div>` : ''}
  </td></tr>`;
}

function confirmDelete(label, onConfirm) {
  openOverlay('Confirm delete', null, `
    <p style="color:var(--t1);margin-bottom:.5rem">${label}</p>
    <p style="color:var(--red);font-size:13px;margin-bottom:1.25rem"><i class="ti ti-alert-triangle"></i> This cannot be undone.</p>
    <div class="brow">
      <button class="bp1" id="ovSave" style="background:var(--red);border-color:var(--red)"><i class="ti ti-trash"></i>Delete</button>
      <button class="bs1" id="ovCancel">Cancel</button>
    </div>`, onConfirm);
}

// Soft-delete confirmation — requires reason + typing "DELETE"
function confirmDeleteSoft(label, onConfirm) {
  const ovId = 'ovSoftDel';
  openOverlay('Move to Trash', null, `
    <p style="color:var(--t1);margin-bottom:.5rem">${label}</p>
    <div style="background:rgba(245,158,11,.08);border:1px solid rgba(245,158,11,.3);border-radius:6px;padding:.75rem;margin-bottom:1rem;font-size:13px;color:var(--amber,#f59e0b)">
      <i class="ti ti-info-circle"></i>
      This record will be moved to Trash and can be restored by an authorized user within 30 days.
    </div>
    <label style="font-size:12px;color:var(--t3);display:block;margin-bottom:.25rem">Reason for deletion <span style="color:var(--red)">*</span></label>
    <textarea id="softDelReason" rows="3" style="width:100%;box-sizing:border-box;padding:.5rem .75rem;border-radius:6px;border:1px solid var(--border);background:var(--bg2);color:var(--t1);font-size:13px;resize:vertical;margin-bottom:.75rem" placeholder="Describe why this record should be deleted…"></textarea>
    <label style="font-size:12px;color:var(--t3);display:block;margin-bottom:.25rem">Type <strong>DELETE</strong> to confirm <span style="color:var(--red)">*</span></label>
    <input id="softDelConfirm" type="text" autocomplete="off" style="width:100%;box-sizing:border-box;padding:.5rem .75rem;border-radius:6px;border:1px solid var(--border);background:var(--bg2);color:var(--t1);font-size:13px;margin-bottom:1.25rem" placeholder="DELETE">
    <div class="brow">
      <button id="${ovId}" class="bp1" style="background:var(--red);border-color:var(--red);opacity:.4;cursor:not-allowed" disabled>
        <i class="ti ti-trash"></i>Move to Trash
      </button>
      <button class="bs1" id="ovCancel">Cancel</button>
    </div>`, null);

  const btn = document.getElementById(ovId);
  const reasonEl = document.getElementById('softDelReason');
  const confirmEl = document.getElementById('softDelConfirm');

  function checkReady() {
    const ready = reasonEl.value.trim().length > 0 && confirmEl.value.trim() === 'DELETE';
    btn.disabled = !ready;
    btn.style.opacity = ready ? '1' : '.4';
    btn.style.cursor = ready ? 'pointer' : 'not-allowed';
  }
  reasonEl.addEventListener('input', checkReady);
  confirmEl.addEventListener('input', checkReady);

  btn.addEventListener('click', () => {
    const reason = reasonEl.value.trim();
    closeOverlay();
    onConfirm(reason);
  });
}

// ── Supervisor approval helpers ───────────────────────────────────────────────

function isSupervisor() {
  return STORAGE.user?.role === 'supervisor';
}

function canApproveEdits() {
  return ['admin', 'ceo', 'operations', 'logistics'].includes(STORAGE.user?.role);
}

// Inserts a pending-approvals panel at the top of a page container for managers.
// entityTypes: array of entity_type strings this page is responsible for.
async function insertPendingPanel(pageEl, entityTypes, onReviewed) {
  if (!canApproveEdits()) return;
  const res = await UFCL.pendingEditsList(STORAGE.user.id);
  if (!res.ok) return;
  const pending = (res.rows || []).filter(r =>
    entityTypes.includes(r.entity_type) && r.status === 'Pending'
  );
  if (!pending.length) return;

  const panel = document.createElement('div');
  panel.style.cssText = 'margin-bottom:1.25rem';
  panel.innerHTML = `
    <div style="border:1px solid rgba(245,158,11,.3);border-radius:8px;overflow:hidden">
      <div style="display:flex;align-items:center;gap:.625rem;padding:.75rem 1.25rem;background:rgba(245,158,11,.07);border-bottom:1px solid rgba(245,158,11,.2)">
        <i class="ti ti-clock" style="color:var(--amber);font-size:16px"></i>
        <span style="font-weight:600;font-size:13px;color:var(--amber)">${pending.length} pending approval${pending.length > 1 ? 's' : ''} from supervisor${pending.length > 1 ? 's' : ''}</span>
      </div>
      <div class="tw"><table class="dt">
        <thead><tr><th>Supervisor</th><th>Request</th><th>Item</th><th>Submitted</th><th>Review</th></tr></thead>
        <tbody>
          ${pending.map(p => `<tr>
            <td style="font-weight:500">${p.submitted_by_name || '—'}</td>
            <td><span class="badge ${p.action_type === 'delete' ? 'br' : 'ba'}">${p.action_type === 'delete' ? 'Delete' : 'Edit'}</span></td>
            <td style="font-weight:500">${p.entity_ref || p.entity_type + ' #' + p.entity_id}</td>
            <td style="font-size:12px;color:var(--t3)">${p.submitted_at}</td>
            <td style="white-space:nowrap;display:flex;gap:4px">
              <button class="bp1 pa-approve" data-id="${p.id}" style="padding:4px 10px;font-size:12px"><i class="ti ti-check"></i>Approve</button>
              <button class="bs1 pa-reject"  data-id="${p.id}" style="padding:4px 10px;font-size:12px;color:var(--red)"><i class="ti ti-x"></i>Reject</button>
            </td>
          </tr>`).join('')}
        </tbody>
      </table></div>
    </div>`;
  pageEl.prepend(panel);

  panel.querySelectorAll('.pa-approve').forEach(btn => {
    btn.onclick = () => {
      const pending = (res.rows || []).find(p => String(p.id) === btn.dataset.id);
      const ref = pending ? (pending.entity_ref || `${pending.entity_type} #${pending.entity_id}`) : 'this record';
      openOverlay('Approve Request', null, `
        <div style="margin-bottom:1rem">
          <p style="font-size:14px;font-weight:600;color:var(--t1);margin-bottom:.5rem">You are about to approve this change request.</p>
          <ul style="margin:.5rem 0 0 1rem;font-size:13px;color:var(--t3);line-height:1.8">
            <li>The requested changes will be applied immediately.</li>
            <li>This action will be recorded in the audit log.</li>
          </ul>
        </div>
        <div style="background:rgba(34,197,94,.08);border:1px solid rgba(34,197,94,.25);border-radius:6px;padding:.75rem 1rem;font-size:13px;color:var(--t2);margin-bottom:1.25rem">
          <strong>Record:</strong> ${ref}
        </div>
        <div class="fg" style="margin-bottom:1.25rem">
          <label>Approval comments (optional)</label>
          <input id="pa-notes" type="text" placeholder="Add any comments…">
        </div>
        <div class="brow">
          <button class="bp1" id="ovSave" style="background:var(--green,#22c55e);border-color:var(--green,#22c55e)"><i class="ti ti-check"></i>Approve</button>
          <button class="bs1" id="ovCancel">Cancel</button>
        </div>`,
        async () => {
          const notes = $('pa-notes')?.value?.trim() || null;
          const r = await UFCL.pendingEditsReview(STORAGE.user.id, btn.dataset.id, 'Approved', notes);
          if (!r.ok) { showOverlayError(r.error); return; }
          showOverlaySuccess('Request approved and changes applied.'); await onReviewed();
        });
    };
  });

  panel.querySelectorAll('.pa-reject').forEach(btn => {
    btn.onclick = () => {
      const pending = (res.rows || []).find(p => String(p.id) === btn.dataset.id);
      const ref = pending ? (pending.entity_ref || `${pending.entity_type} #${pending.entity_id}`) : 'this record';
      openOverlay('Reject Request', null, `
        <div style="margin-bottom:1rem">
          <p style="font-size:14px;font-weight:600;color:var(--t1);margin-bottom:.5rem">You are about to reject this request.</p>
          <p style="font-size:13px;color:var(--t3)">No changes will be applied. The requester will be notified with your reason.</p>
        </div>
        <div style="background:rgba(239,68,68,.06);border:1px solid rgba(239,68,68,.2);border-radius:6px;padding:.75rem 1rem;font-size:13px;color:var(--t2);margin-bottom:1rem">
          <strong>Record:</strong> ${ref}
        </div>
        <div class="fg" style="margin-bottom:1.25rem">
          <label>Reason for rejection <span style="color:var(--red)">*</span></label>
          <textarea id="rej-reason" rows="3" style="width:100%;box-sizing:border-box;padding:.5rem .75rem;border-radius:6px;border:1px solid var(--border);background:var(--bg2);color:var(--t1);font-size:13px;resize:vertical" placeholder="Explain why this request is being rejected…"></textarea>
        </div>
        <div class="brow">
          <button class="bp1" id="ovSave" style="background:var(--red);border-color:var(--red)"><i class="ti ti-x"></i>Reject</button>
          <button class="bs1" id="ovCancel">Cancel</button>
        </div>`,
        async () => {
          const reason = $('rej-reason')?.value?.trim();
          if (!reason) { showOverlayError('Reason is required'); return; }
          const r = await UFCL.pendingEditsReview(STORAGE.user.id, btn.dataset.id, 'Rejected', reason);
          if (!r.ok) { showOverlayError(r.error); return; }
          showOverlaySuccess('Request rejected. The requester has been notified.'); await onReviewed();
        });
    };
  });
}

function canManageTrash() {
  return ['admin', 'ceo', 'operations'].includes(STORAGE.user?.role);
}

// Inserts a pending-deletion-requests panel for managers to approve/reject.
async function insertDeletionPanel(pageEl, entityTypes, onReviewed) {
  if (!canManageTrash()) return;
  const res = await UFCL.deletionRequestsList(STORAGE.user.id);
  if (!res.ok) return;
  const pending = (res.rows || []).filter(r =>
    entityTypes.includes(r.entity_type) && r.status === 'pending'
  );
  if (!pending.length) return;

  const panel = document.createElement('div');
  panel.style.cssText = 'margin-bottom:1.25rem';
  panel.innerHTML = `
    <div style="border:1px solid rgba(239,68,68,.3);border-radius:8px;overflow:hidden">
      <div style="display:flex;align-items:center;gap:.625rem;padding:.75rem 1.25rem;background:rgba(239,68,68,.07);border-bottom:1px solid rgba(239,68,68,.2)">
        <i class="ti ti-trash" style="color:var(--red);font-size:16px"></i>
        <span style="font-weight:600;font-size:13px;color:var(--red)">${pending.length} pending deletion request${pending.length > 1 ? 's' : ''}</span>
      </div>
      <div class="tw"><table class="dt">
        <thead><tr><th>Requested By</th><th>Record</th><th>Reason</th><th>Submitted</th><th>Review</th></tr></thead>
        <tbody>
          ${pending.map(p => `<tr>
            <td style="font-weight:500">${p.requested_by_name || '—'}</td>
            <td style="font-weight:500">${p.entity_ref || p.entity_type + ' #' + p.record_id}</td>
            <td style="font-size:12px;color:var(--t3)">${p.deletion_reason || '—'}</td>
            <td style="font-size:12px;color:var(--t3)">${p.requested_at}</td>
            <td style="white-space:nowrap;display:flex;gap:4px">
              <button class="bp1 dr-approve" data-id="${p.id}" style="padding:4px 10px;font-size:12px;background:var(--red);border-color:var(--red)"><i class="ti ti-check"></i>Approve</button>
              <button class="bs1 dr-reject"  data-id="${p.id}" style="padding:4px 10px;font-size:12px;color:var(--t2)"><i class="ti ti-x"></i>Reject</button>
            </td>
          </tr>`).join('')}
        </tbody>
      </table></div>
    </div>`;
  pageEl.prepend(panel);

  panel.querySelectorAll('.dr-approve').forEach(btn => {
    btn.onclick = () => {
      const req = pending.find(p => String(p.id) === btn.dataset.id);
      const ref = req ? (req.entity_ref || `${req.entity_type} #${req.record_id}`) : 'this record';
      const who = req?.requested_by_name || 'the requester';
      openOverlay('Approve Deletion Request', null, `
        <div style="margin-bottom:1rem">
          <p style="font-size:14px;font-weight:600;color:var(--t1);margin-bottom:.5rem">You are about to approve this deletion request.</p>
          <ul style="margin:.5rem 0 0 1rem;font-size:13px;color:var(--t3);line-height:1.8">
            <li>The record will be moved to Trash immediately.</li>
            <li>It can be restored within 30 days from the Trash page.</li>
            <li>This action will be recorded in the audit log.</li>
          </ul>
        </div>
        <div style="background:rgba(239,68,68,.06);border:1px solid rgba(239,68,68,.2);border-radius:6px;padding:.75rem 1rem;font-size:13px;color:var(--t2);margin-bottom:.75rem">
          <div><strong>Record:</strong> ${ref}</div>
          <div style="margin-top:.25rem"><strong>Requested by:</strong> ${who}</div>
          ${req?.deletion_reason ? `<div style="margin-top:.25rem"><strong>Reason given:</strong> ${req.deletion_reason}</div>` : ''}
        </div>
        <div class="fg" style="margin-bottom:1.25rem">
          <label>Approval comments (optional)</label>
          <input id="dr-appr-notes" type="text" placeholder="Add any comments for the requester…">
        </div>
        <div class="brow">
          <button class="bp1" id="ovSave" style="background:var(--red);border-color:var(--red)"><i class="ti ti-check"></i>Approve — Move to Trash</button>
          <button class="bs1" id="ovCancel">Cancel</button>
        </div>`,
        async () => {
          const notes = $('dr-appr-notes')?.value?.trim() || null;
          const r = await UFCL.deletionRequestApprove(STORAGE.user.id, btn.dataset.id, notes);
          if (!r.ok) { showOverlayError(r.error); return; }
          showOverlaySuccess('Deletion approved. Record moved to Trash.'); await onReviewed();
        });
    };
  });

  panel.querySelectorAll('.dr-reject').forEach(btn => {
    btn.onclick = () => {
      const req = pending.find(p => String(p.id) === btn.dataset.id);
      const ref = req ? (req.entity_ref || `${req.entity_type} #${req.record_id}`) : 'this record';
      openOverlay('Reject Deletion Request', null, `
        <div style="margin-bottom:1rem">
          <p style="font-size:14px;font-weight:600;color:var(--t1);margin-bottom:.5rem">You are about to reject this request.</p>
          <p style="font-size:13px;color:var(--t3)">No changes will be applied. The record will remain active and the requester will be notified with your reason.</p>
        </div>
        <div style="background:rgba(239,68,68,.06);border:1px solid rgba(239,68,68,.2);border-radius:6px;padding:.75rem 1rem;font-size:13px;color:var(--t2);margin-bottom:1rem">
          <strong>Record:</strong> ${ref}
        </div>
        <div class="fg" style="margin-bottom:1.25rem">
          <label>Reason for rejection <span style="color:var(--red)">*</span></label>
          <textarea id="dr-rej-reason" rows="3" style="width:100%;box-sizing:border-box;padding:.5rem .75rem;border-radius:6px;border:1px solid var(--border);background:var(--bg2);color:var(--t1);font-size:13px;resize:vertical" placeholder="Explain why this deletion request is being rejected…"></textarea>
        </div>
        <div class="brow">
          <button class="bp1" id="ovSave"><i class="ti ti-x"></i>Reject</button>
          <button class="bs1" id="ovCancel">Cancel</button>
        </div>`,
        async () => {
          const notes = $('dr-rej-reason')?.value?.trim();
          if (!notes) { showOverlayError('Reason is required'); return; }
          const r = await UFCL.deletionRequestReject(STORAGE.user.id, btn.dataset.id, notes);
          if (!r.ok) { showOverlayError(r.error); return; }
          showOverlaySuccess('Rejection recorded. The requester has been notified.'); await onReviewed();
        });
    };
  });
}

function showOverlayError(msg) {
  const el = $('ovErr');
  if (!el) return;
  el.textContent = msg;
  el.style.cssText = '';
  el.style.display = 'block';
}

function showOverlaySuccess(msg) {
  const el = $('ovErr');
  if (!el) return;
  el.textContent = msg;
  el.style.background = 'var(--g-light)';
  el.style.color = 'var(--g-dark)';
  el.style.borderColor = 'rgba(30,95,54,.25)';
  el.style.display = 'block';
  setTimeout(closeOverlay, 1800);
}

// A governed action (edit/delete) was submitted for approval rather than
// applied immediately — distinct amber treatment so this reads as "in
// progress," not a failure. Reuses the existing amber design tokens
// (var(--amber)/var(--amber-l)) already used by the pending-approval panels.
function showOverlayPending(msg) {
  const el = $('ovErr');
  if (!el) return;
  el.textContent = msg;
  el.style.background = 'var(--amber-l)';
  el.style.color = 'var(--amber)';
  el.style.borderColor = 'rgba(217,119,6,.3)';
  el.style.display = 'block';
  setTimeout(closeOverlay, 2600);
}

// Shared outcome handler for every mutating action that can be blocked by the
// time-gated governance engine (applyGovernance). Returns true if it already
// displayed a message and the caller should stop; false if res.ok and the
// caller should proceed with its own success handling. Fixes the "undefined"
// bug where res.pendingApproval results (which have no .error field) were
// passed straight to showOverlayError.
function handleGovernanceResult(res) {
  if (res.ok) return false;
  if (res.pendingApproval) { showOverlayPending(res.message || 'This action requires manager approval.'); return true; }
  showOverlayError(res.error || 'Action failed.');
  return true;
}

// Same as handleGovernanceResult, but for actions triggered directly from a
// list row (no overlay open) — e.g. an inline status-change dropdown.
function handleGovernanceResultToast(res) {
  if (res.ok) return false;
  if (res.pendingApproval) { showToast(res.message || 'This action requires manager approval.', 'pending'); return true; }
  showToast(res.error || 'Action failed.', 'error');
  return true;
}

async function bootstrap() {
  console.log('[renderer] bootstrap: calling getBootstrap');
  const res = await UFCL.getBootstrap(STORAGE.user.id);
  console.log('[renderer] bootstrap: getBootstrap returned', res);
  if (!res.ok) throw new Error(res.error || 'Bootstrap failed');
  STORAGE.approved = res.approved || { monthly: false };
  STORAGE.unread = res.unreadNotifications || 0;
  updateBadge();
  startNotificationPoll();

  $('uname2').textContent = res.user.name;
  $('urole').textContent = roleLabel(res.user.role);
  $('uav').textContent = shortName(res.user.name);
  const pages = Array.isArray(res.userPages) && res.userPages.length ? res.userPages : (res.rolePages?.[res.user.role] || []);
  STORAGE.pages = pages;
  buildSidebar(pages);

  // default route per user-specific permissions or role permissions
  const first = pages[0] || 'dashboard';
  console.log('[renderer] bootstrap: showing first page', first);
  await showPage(first);
}

