// ── Phase 7 — Business Intelligence helpers ────────────────────────────────────
function _svgSparkline(vals, { w = 80, h = 26, color = '#2E8B57' } = {}) {
  if (!vals || vals.length < 2) return '';
  const max   = Math.max(...vals, 1);
  const min   = Math.min(...vals, 0);
  const range = max - min || 1;
  const pts   = vals.map((v, i) => {
    const x = (i / (vals.length - 1)) * w;
    const y = h - 2 - ((v - min) / range) * (h - 4);
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  }).join(' ');
  return `<svg viewBox="0 0 ${w} ${h}" style="width:${w}px;height:${h}px;display:block;overflow:visible">
    <polyline points="${pts}" fill="none" stroke="${color}" stroke-width="1.5"
      stroke-linejoin="round" stroke-linecap="round" opacity=".8"/>
  </svg>`;
}

// `labelOverride` (Phase 3C) lets callers with their own tier vocabulary
// (e.g. supplier scoring's Excellent/Good/Average/High Risk, different cut
// points than this gauge's original Excellent/Good/Warning/Critical bands)
// show their own label without duplicating this component. Optional and
// defaults to the original behavior — every existing caller is unaffected.
function _svgGauge(score, labelOverride) {
  const R  = 72, cx = 90, cy = 90;
  const arc = Math.PI * R;
  const dash = (score / 100) * arc;
  const col  = score >= 90 ? '#2E8B57' : score >= 75 ? '#1D4ED8' : score >= 60 ? '#D97706' : '#DC2626';
  const lbl  = labelOverride || (score >= 90 ? 'Excellent' : score >= 75 ? 'Good' : score >= 60 ? 'Warning' : 'Critical');
  return `<svg viewBox="0 0 180 110" style="width:100%;max-width:240px;display:block;margin:0 auto">
    <path d="M${cx-R},${cy} A${R},${R} 0 0,1 ${cx+R},${cy}"
          fill="none" stroke="#E5E7EB" stroke-width="14" stroke-linecap="round"/>
    <path d="M${cx-R},${cy} A${R},${R} 0 0,1 ${cx+R},${cy}"
          fill="none" stroke="${col}" stroke-width="14" stroke-linecap="round"
          stroke-dasharray="${dash.toFixed(1)},${arc.toFixed(1)}"/>
    <text x="${cx}" y="${cy - 6}" text-anchor="middle"
          font-family="DM Sans,sans-serif" font-size="30" font-weight="700" fill="${col}">${score}</text>
    <text x="${cx}" y="${cy + 13}" text-anchor="middle"
          font-family="DM Sans,sans-serif" font-size="11" font-weight="600" fill="#6B7280">${lbl}</text>
  </svg>`;
}

function _svgForecast(hist, fcst, { h = 90, ch = '#2E8B57', cf = '#94A3B8' } = {}) {
  const all = [...hist, ...fcst];
  if (!all.length) return `<div class="bi-nod"><i class="ti ti-info-circle"></i> No data available</div>`;
  const max = Math.max(...all, 1);
  const W = 280, pd = 8, total = all.length;
  const ptX = (i) => pd + (i / (total - 1 || 1)) * (W - pd * 2);
  const ptY = (v) => h - pd - (v / max) * (h - pd * 2);
  const hp  = hist.map((v, i) => `${ptX(i).toFixed(1)},${ptY(v).toFixed(1)}`).join(' ');
  const fb  = hist.length - 1;
  const fp  = [hist.at(-1) ?? fcst[0], ...fcst].map((v, i) =>
    `${ptX(fb + i).toFixed(1)},${ptY(v).toFixed(1)}`).join(' ');
  const dvX = hist.length > 0 ? ptX(hist.length - 1).toFixed(1) : (W / 2).toFixed(1);
  return `<svg viewBox="0 0 ${W} ${h}" preserveAspectRatio="none"
      style="width:100%;height:${h}px;display:block;overflow:visible">
    ${hist.length > 1 ? `<polyline points="${hp}" fill="none" stroke="${ch}" stroke-width="2"
        stroke-linejoin="round" stroke-linecap="round"/>` : ''}
    ${fcst.length ? `
    <line x1="${dvX}" y1="${pd}" x2="${dvX}" y2="${h - pd}"
          stroke="#CBD5E1" stroke-width="1" stroke-dasharray="3,2"/>
    <polyline points="${fp}" fill="none" stroke="${cf}" stroke-width="2"
        stroke-dasharray="5,3" stroke-linejoin="round" stroke-linecap="round"/>` : ''}
  </svg>`;
}

function _biSevCls(sev) {
  return { critical: 'bi-crit', high: 'bi-high', medium: 'bi-med', low: 'bi-low' }[sev] || 'bi-low';
}

function exportBiCSV() {
  if (!_biData) return;
  const d   = _biData;
  const q   = v => `"${String(v ?? '').replace(/"/g, '""')}"`;
  const row = (...cols) => cols.map(q).join(',');
  const lines = [
    row('UFCL Business Intelligence Report', new Date().toLocaleString()),
    '',
    row('COMPANY HEALTH SCORE', d.health.score, d.health.grade),
    '',
    row('HEALTH DEDUCTIONS'),
    row('Category', 'Points Deducted'),
    ...d.health.breakdown.map(b => row(b.label, b.pts)),
    '',
    row('RISKS'),
    row('Severity', 'Module', 'Title', 'Detail'),
    ...d.risks.map(r => row(r.severity, r.module, r.title, r.detail)),
    '',
    row('RECOMMENDATIONS'),
    row('Priority', 'Module', 'Title', 'Description', 'Suggested Action'),
    ...d.recommendations.map(r => row(r.priority, r.module, r.title, r.description, r.action)),
    '',
    row('STOCK DEPLETION FORECAST'),
    row('Item', 'Category', 'Current Stock', 'UOM', 'Avg Daily', 'Days Until Depletion'),
    ...(d.predictions.stockShortages || []).map(s =>
      row(s.name, s.category, s.current_stock, s.uom, s.avg_daily_consumption, s.days_until_depletion ?? 'Below Min')),
    '',
    row('HARVEST COMPLETION FORECAST'),
    row('Compartment', 'Sub', 'Species', 'Volume m3', 'Harvested', 'Remaining', 'Rate/Day', 'Est Days', '% Complete'),
    ...(d.predictions.harvestForecast || []).map(h =>
      row(h.compt_name, h.sub_name || '', h.species || '', h.volume_m3, h.total_harvested,
          h.est_remaining, h.rate_per_day, h.days_to_complete ?? 'N/A', (h.pct_complete || 0) + '%')),
    '',
    row('GOVERNANCE SNAPSHOT'),
    row('Metric', 'Value'),
    row('Failed Logins (24h)',       d.govRisk.failed_logins_24h  ?? 0),
    row('Governance Overrides (24h)', d.govRisk.priv_overrides_24h ?? 0),
    row('Failed Workflow Jobs',      d.govRisk.failed_jobs        ?? 0),
    row('Total Pending Approvals',   d.govRisk.total_pending      ?? 0),
    row('Stalled >48h',              d.govRisk.stalled_48h        ?? 0),
    row('Delayed Deliveries',        d.govRisk.delayed_deliveries ?? 0),
  ];
  UFCL.biExport(STORAGE.user.id, {
    csv:      lines.join('\r\n'),
    filename: `ufcl_bi_report_${new Date().toISOString().slice(0, 10)}.csv`,
  }).then(r => { if (r?.ok) showToast(`Saved: ${r.filePath}`, 'success'); });
}

async function renderBI() {
  _biLastLoad = Date.now();
  const el = $('page-bi');
  el.innerHTML = `<div class="ptitle"><i class="ti ti-chart-line"></i> Business Intelligence</div>
    <div class="card" style="padding:32px;text-align:center">
      <i class="ti ti-loader-2 spin"></i> Running predictive analytics…</div>`;

  const res = await UFCL.biDashboard(STORAGE.user.id);
  if (!res?.ok) {
    el.innerHTML = `<div class="ptitle"><i class="ti ti-chart-line"></i> Business Intelligence</div>
      <div class="card" style="padding:24px;color:var(--red)">
        <i class="ti ti-alert-circle"></i> ${res?.error || 'Load failed'}</div>`;
    return;
  }
  _biData = res;
  const { health, predictions, forecasts, risks, recommendations, govRisk, stockAnomalies } = res;
  const sec = new Set(res.sections || ['health','stock','fuel','machines','workshop','harvest','sales','governance','recommendations','charts']);
  const ts = new Date().toLocaleString();

  // ── Section 1: Health Score ───────────────────────────────────────────────
  const gauge   = _svgGauge(health.score);
  const bkdHtml = health.breakdown.length
    ? health.breakdown.map(b =>
        `<div class="bi-bkd-row"><i class="ti ${b.icon}"></i><span>${b.label}</span><b>−${b.pts}</b></div>`
      ).join('')
    : `<div class="bi-bkd-row" style="color:var(--t3)">
         <i class="ti ti-circle-check"></i><span>No deductions — all systems healthy</span><b>0</b></div>`;

  // ── Section 2: Prediction Cards with sparklines ───────────────────────────
  const fuelZ   = Number(predictions.fuelAnomaly?.z_score)    || 0;
  const fuelPct = Number(predictions.fuelAnomaly?.pct_change) || 0;
  const fuelSev = fuelZ > 2 ? 'critical' : fuelZ > 1.5 ? 'high' : fuelZ > 0.8 ? 'medium' : 'low';
  const fuelTxt = fuelZ > 1.5
    ? `${Math.abs(fuelPct).toFixed(1)}% ${fuelPct > 0 ? 'above' : 'below'} baseline`
    : `Z-score ${fuelZ.toFixed(2)} — normal range`;

  const critSt = (predictions.stockShortages || []).filter(s => s.days_until_depletion != null && s.days_until_depletion <= 7);
  const stSev  = critSt.length > 0 ? 'critical'
    : (predictions.stockShortages || []).filter(s => s.days_until_depletion != null && s.days_until_depletion <= 14).length ? 'high'
    : (predictions.stockShortages || []).length ? 'medium' : 'low';
  const stTxt  = (predictions.stockShortages || []).length
    ? `${predictions.stockShortages.length} item(s) at risk — ${critSt.length} critical`
    : 'All items adequately stocked';
  const stSpk  = _svgSparkline(
    (predictions.stockShortages || []).slice(0, 10).map(s => s.days_until_depletion ?? 30).reverse(),
    { color: critSt.length ? '#DC2626' : '#D97706' }
  );

  const overdueM = (predictions.machineAlerts || []).filter(m => Number(m.days_overdue) > 0);
  const macSev   = overdueM.some(m => Number(m.days_overdue) > 14) ? 'critical'
    : overdueM.length ? 'high'
    : (predictions.machineAlerts || []).length ? 'medium' : 'low';
  const macTxt   = overdueM.length
    ? `${overdueM.length} overdue · ${(predictions.efficiencyDecline || []).length} declining`
    : (predictions.machineAlerts || []).length
    ? `${predictions.machineAlerts.length} due within 14 days`
    : 'All machines on schedule';
  const macSpk = _svgSparkline(
    (predictions.efficiencyDecline || []).map(m => Number(m.avg_eff) || 0),
    { color: '#EA580C' }
  );

  const sReg   = predictions.salesRegression || {};
  const sAvg   = Number(sReg.avg_daily) || 0;
  const sR2    = Number(sReg.r2) || 0;
  const sTrend = sAvg > 0 ? (Number(sReg.slope) / sAvg) * 100 : 0;
  const sSev   = sTrend < -10 ? 'high' : sTrend < -5 ? 'medium' : 'low';
  const sTxt   = sR2 > 0.05
    ? `${sTrend >= 0 ? '+' : ''}${sTrend.toFixed(1)}%/day · R²=${sR2.toFixed(2)}`
    : 'Insufficient regression data';
  const sSpk   = _svgSparkline(
    (forecasts.sales30d || []).slice(-14).map(r => Number(r.revenue)),
    { color: sTrend >= 0 ? '#2E8B57' : '#DC2626' }
  );
  const sTIcon = sTrend > 2 ? 'ti-trending-up bi-trend-up'
    : sTrend < -2 ? 'ti-trending-down bi-trend-down' : 'ti-minus bi-trend-flat';

  const wReg   = predictions.workshopRegression || {};
  const wAvg   = Number(wReg.total_avg) || 0;
  const wTrend = wAvg > 0 ? (Number(wReg.total_slope) / wAvg) * 100 : 0;
  const wSev   = wTrend < -15 ? 'critical' : wTrend < -5 ? 'high' : 'low';
  const wTxt   = wAvg > 0
    ? `${wTrend >= 0 ? '+' : ''}${wTrend.toFixed(1)}%/wk · avg ${wAvg.toFixed(0)} u/wk`
    : 'No production data';
  const wSpk   = _svgSparkline(
    (forecasts.wkTrend || []).map(r => Number(r.timber) + Number(r.poles)),
    { color: wTrend >= 0 ? '#7C3AED' : '#EA580C' }
  );
  const wTIcon = wTrend > 2 ? 'ti-trending-up bi-trend-up'
    : wTrend < -2 ? 'ti-trending-down bi-trend-down' : 'ti-minus bi-trend-flat';

  const actH    = (predictions.harvestForecast || []).filter(h => Number(h.rate_per_day) > 0);
  const behH    = actH.filter(h => h.days_to_complete !== null && h.days_to_complete > 90);
  const hSev    = behH.length > 0 ? 'medium' : 'low';
  const hTxt    = actH.length
    ? `${actH.length} active · ${behH.length} behind schedule`
    : 'No active harvest operations';
  const hSpk    = _svgSparkline(
    (predictions.harvestForecast || []).slice(0, 8).map(h => Number(h.pct_complete)),
    { color: '#2E8B57' }
  );
  const hAvgPct = actH.length
    ? Math.round(actH.reduce((s, h) => s + Number(h.pct_complete), 0) / actH.length) : 0;

  const _conf = (n, max) => {
    const level = n >= max ? 3 : n >= max / 2 ? 2 : n > 0 ? 1 : 0;
    return Array.from({ length: 3 }, (_, i) =>
      `<span class="bi-conf-dot${i < level ? ' on' : ''}"></span>`).join('');
  };

  const predCards = [
    sec.has('stock')    && { icon: 'ti-package',          sev: stSev,  label: 'Stock Forecast',      val: stTxt,  spk: stSpk,
      trend: '', trendTxt: `${(predictions.stockShortages||[]).length} items monitored`,
      conf: _conf((predictions.stockShortages||[]).length, 10) },
    sec.has('fuel')     && { icon: 'ti-droplet',          sev: fuelSev, label: 'Fuel Forecast',      val: fuelTxt, spk: '',
      trend: fuelPct > 2 ? 'ti-trending-up bi-trend-down' : fuelPct < -2 ? 'ti-trending-down bi-trend-up' : 'ti-minus bi-trend-flat',
      trendTxt: fuelPct !== 0 ? `${fuelPct > 0 ? '+' : ''}${fuelPct.toFixed(1)}% vs prior` : 'No change',
      conf: _conf(Math.min(3, Math.round((predictions.fuelAnomaly?.data_points||0)/20)), 3) },
    sec.has('machines') && { icon: 'ti-settings-2',       sev: macSev, label: 'Maintenance Forecast', val: macTxt, spk: macSpk,
      trend: overdueM.length ? 'ti-alert-triangle bi-trend-down' : 'ti-circle-check bi-trend-up',
      trendTxt: `${overdueM.length} overdue`,
      conf: _conf((predictions.machineAlerts||[]).length, 5) },
    sec.has('sales')    && { icon: 'ti-chart-line',       sev: sSev,   label: 'Sales Forecast',      val: sTxt,   spk: sSpk,
      trend: sTIcon, trendTxt: sTrend !== 0 ? `${sTrend > 0 ? '+' : ''}${sTrend.toFixed(1)}%/day` : 'Stable',
      conf: _conf(Math.round(sR2 * 10), 10) },
    sec.has('workshop') && { icon: 'ti-building-factory', sev: wSev,   label: 'Workshop Forecast',   val: wTxt,   spk: wSpk,
      trend: wTIcon, trendTxt: wTrend !== 0 ? `${wTrend > 0 ? '+' : ''}${wTrend.toFixed(1)}%/wk` : 'Stable',
      conf: _conf(wReg.n || 0, 8) },
    sec.has('harvest')  && { icon: 'ti-trees',            sev: hSev,   label: 'Harvest Forecast',    val: hTxt,   spk: hSpk,
      trend: actH.length ? 'ti-plant bi-trend-up' : 'ti-minus bi-trend-flat',
      trendTxt: actH.length ? `${hAvgPct}% avg done` : 'No data',
      conf: _conf(actH.length, 5) },
  ].filter(Boolean).map(c => `
    <div class="bi-pcard bi-pcard--${c.sev}">
      <div style="display:flex;justify-content:space-between;align-items:flex-start">
        <div class="bi-pcard-icon"><i class="ti ${c.icon}"></i></div>
        <span class="bi-badge ${_biSevCls(c.sev)}">${c.sev.toUpperCase()}</span>
      </div>
      <div class="bi-pcard-label" style="margin-top:6px">${c.label}</div>
      <div class="bi-pcard-val" style="margin-top:3px">${c.val}</div>
      ${c.spk ? `<div class="bi-sparkline-wrap">${c.spk}</div>` : ''}
      ${c.trend ? `<div class="bi-trend-row"><i class="ti ${c.trend}" style="font-size:12px"></i><span>${c.trendTxt}</span></div>` : ''}
      <div class="bi-conf" title="Data confidence">${c.conf}</div>
    </div>`).join('');

  // ── Section 3: Risk Cards ─────────────────────────────────────────────────
  const gv  = govRisk;
  const _riskCard = (mod, icon, sev, score, count, desc) => {
    const scoreColor = sev === 'critical' ? '#DC2626' : sev === 'high' ? '#EA580C'
      : sev === 'medium' ? '#D97706' : '#22C55E';
    return `<div class="bi-risk-card bi-risk-card--${sev}">
      <div class="bi-risk-card-hdr">
        <div class="bi-risk-card-icon"><i class="ti ${icon}"></i></div>
        <span class="bi-risk-card-mod">${mod}</span>
        <span class="bi-badge ${_biSevCls(sev)}">${sev.toUpperCase()}</span>
      </div>
      <div class="bi-risk-score" style="color:${scoreColor}">${score}</div>
      <div class="bi-risk-score-bar">
        <div class="bi-risk-score-fill" style="width:${Math.min(100,score)}%;background:${scoreColor}"></div>
      </div>
      <div class="bi-risk-card-desc">${desc}</div>
      ${count != null ? `<div class="bi-risk-card-count"><i class="ti ti-list-details"></i> ${count} record(s) affected</div>` : ''}
    </div>`;
  };

  const fuelScore = Math.min(100, Math.round(Math.max(0, Math.abs(fuelZ) - 0.5) * 20));
  const stScore   = Math.min(100, (predictions.stockShortages||[]).length * 8);
  const stFuelSev = fuelZ > 2 ? 'critical' : fuelZ > 1.5 ? 'high' : fuelZ > 0.8 ? 'medium' : 'low';
  const macScore  = Math.min(100, overdueM.length * 15 + (predictions.efficiencyDecline||[]).length * 10);
  const macSevC   = overdueM.some(m => Number(m.days_overdue) > 14) ? 'critical'
    : overdueM.length > 2 ? 'high' : overdueM.length > 0 ? 'medium' : 'low';
  const delCount  = Number(gv.delayed_deliveries) || 0;
  const delSev    = delCount > 5 ? 'critical' : delCount > 2 ? 'high' : delCount > 0 ? 'medium' : 'low';
  const wfCount   = Number(gv.failed_jobs) || 0;
  const wfSev     = wfCount > 10 ? 'critical' : wfCount > 5 ? 'high' : wfCount > 0 ? 'medium' : 'low';
  const secCount  = Number(gv.failed_logins_24h) || 0;
  const secSev    = secCount >= 20 ? 'critical' : secCount >= 10 ? 'high' : secCount >= 3 ? 'medium' : 'low';
  const govCount  = Number(gv.priv_overrides_24h) || 0;
  const govStall  = Number(gv.stalled_48h) || 0;
  const govSev    = govCount > 3 ? 'critical' : govCount > 0 ? 'high' : govStall > 3 ? 'medium' : govStall > 0 ? 'medium' : 'low';
  const govScore  = Math.min(100, govCount * 15 + govStall * 5);

  const riskCardsHtml = [
    sec.has('fuel') && _riskCard('Fuel', 'ti-droplet', stFuelSev,
      fuelScore, null,
      fuelZ > 1.5 ? `${Math.abs(fuelPct).toFixed(1)}% ${fuelPct > 0 ? 'above' : 'below'} baseline (Z=${fuelZ.toFixed(2)})` : `Z-score ${fuelZ.toFixed(2)} — normal range`),
    sec.has('stock') && _riskCard('Stock', 'ti-package', stSev,
      stScore, (predictions.stockShortages||[]).length, stTxt),
    sec.has('machines') && _riskCard('Machines', 'ti-settings-2', macSevC,
      macScore, overdueM.length + (predictions.efficiencyDecline||[]).length,
      overdueM.length ? `${overdueM.length} overdue · ${(predictions.efficiencyDecline||[]).length} efficiency decline(s)` : 'No overdue maintenance'),
    (sec.has('machines') || sec.has('workshop') || sec.has('harvest')) && _riskCard('Logistics', 'ti-truck', delSev,
      Math.min(100, delCount * 12), delCount,
      delCount ? `${delCount} delivery order(s) past due date` : 'All deliveries on schedule'),
    sec.has('governance') && _riskCard('Workflow', 'ti-alert-triangle', wfSev,
      Math.min(100, wfCount * 8), wfCount,
      wfCount ? `${wfCount} workflow job(s) in failed state` : 'All workflow jobs healthy'),
    sec.has('governance') && _riskCard('Security', 'ti-lock', secSev,
      Math.min(100, secCount * 3), secCount,
      secCount ? `${secCount} failed login attempt(s) in last 24h` : 'No unusual login activity'),
    sec.has('governance') && _riskCard('Governance', 'ti-shield-exclamation', govSev,
      govScore, govCount + govStall,
      govCount ? `${govCount} privileged override(s) in 24h · ${govStall} stalled approval(s)` : `${govStall} stalled approval(s) >48h`),
  ].filter(Boolean).join('');

  // ── Section 4: Recommendations ───────────────────────────────────────────
  const recHtml = recommendations.length
    ? recommendations.slice(0, 12).map(r => `
        <div class="bi-rec-card">
          <div class="bi-rec-card-icon"><i class="ti ${r.icon || 'ti-bulb'}"></i></div>
          <div class="bi-rec-card-body">
            <div class="bi-rec-card-meta">
              <span class="bi-badge ${_biSevCls(r.priority)}">${(r.priority||'low').toUpperCase()}</span>
              <span class="bi-mod-chip">${r.module || ''}</span>
            </div>
            <div class="bi-rec-card-title">${r.title || r.description}</div>
            <div class="bi-rec-card-desc">${r.description}</div>
            ${r.action ? `<div class="bi-rec-card-action"><i class="ti ti-arrow-right" style="font-size:11px"></i>${r.action}</div>` : ''}
          </div>
        </div>`).join('')
    : `<div class="bi-nod"><i class="ti ti-circle-check"></i> No recommendations — company health is strong</div>`;

  // ── Section 5: Forecast Charts ────────────────────────────────────────────
  const salesHistVals  = (forecasts.sales30d || []).map(r => Number(r.revenue));
  const salesChartHtml = _svgForecast(salesHistVals, (forecasts.salesForecast || []).slice(0, 15), {
    h: 110, ch: '#2E8B57', cf: '#94A3B8',
  });
  const sfcstAvg   = (forecasts.salesForecast || []).length
    ? Math.round((forecasts.salesForecast).reduce((a, b) => a + b, 0) / forecasts.salesForecast.length) : 0;
  const sDateLbls  = _clabels(forecasts.sales30d || [], 'day', 6);

  const wkHistVals  = (forecasts.wkTrend || []).map(r => Number(r.timber) + Number(r.poles));
  const wkChartHtml = _svgForecast(wkHistVals, forecasts.wkForecast || [], {
    h: 110, ch: '#7C3AED', cf: '#94A3B8',
  });
  const wfcstAvg = (forecasts.wkForecast || []).length
    ? Math.round((forecasts.wkForecast).reduce((a, b) => a + b, 0) / forecasts.wkForecast.length) : 0;

  // ── Section 6: Risk Timeline ──────────────────────────────────────────────
  const tlItems = [];
  if (secCount > 0)
    tlItems.push({ sev: secSev, mod: 'Security', icon: 'ti-lock',
      text: `${secCount} failed login attempt(s) in last 24h` });
  if (govCount > 0)
    tlItems.push({ sev: govSev, mod: 'Governance', icon: 'ti-shield-exclamation',
      text: `${govCount} privileged override(s) recorded in last 24h` });
  if (wfCount > 0)
    tlItems.push({ sev: wfSev, mod: 'Workflow', icon: 'ti-alert-triangle',
      text: `${wfCount} workflow job(s) in failed state — attention required` });
  if (govStall > 0)
    tlItems.push({ sev: 'medium', mod: 'Approvals', icon: 'ti-clock-off',
      text: `${govStall} approval request(s) stalled >48h — SLA breached` });
  for (const sm of (stockAnomalies || []).slice(0, 3))
    tlItems.push({ sev: Number(sm.z_score) > 3 ? 'high' : 'medium', mod: 'Stock', icon: 'ti-arrows-exchange',
      text: `Abnormal movement: ${sm.item_name} — qty ${sm.quantity} (${sm.movement_type}), Z=${Number(sm.z_score).toFixed(1)}` });
  for (const m of overdueM.slice(0, 3))
    tlItems.push({ sev: Number(m.days_overdue) > 14 ? 'critical' : 'high', mod: 'Machines', icon: 'ti-settings-2',
      text: `${m.machine_code} ${m.name} — ${m.maintenance_type} is ${m.days_overdue} day(s) overdue` });
  if (delCount > 0)
    tlItems.push({ sev: delSev, mod: 'Logistics', icon: 'ti-truck',
      text: `${delCount} delivery order(s) past due date` });

  const dotCls = { critical: 'bi-tl-dot-crit', high: 'bi-tl-dot-high', medium: 'bi-tl-dot-med', low: 'bi-tl-dot-low' };
  const tlHtml = tlItems.length
    ? tlItems.map(t => `
        <div class="bi-tl-item">
          <span class="bi-tl-dot ${dotCls[t.sev] || ''}"></span>
          <span class="bi-tl-mod"><i class="ti ${t.icon}"></i> ${t.mod}</span>
          <span class="bi-tl-text">${t.text}</span>
          <span class="bi-tl-sev"><span class="bi-badge ${_biSevCls(t.sev)}">${t.sev.toUpperCase()}</span></span>
        </div>`).join('')
    : `<div class="bi-nod"><i class="ti ti-circle-check"></i> No risk events in current data window</div>`;

  // ── Section 7: Data Tables ────────────────────────────────────────────────
  const stockTableHtml = (predictions.stockShortages || []).length
    ? `<table class="bi-tbl"><thead><tr>
        <th>Item</th><th>Stock</th><th>Avg/Day</th><th>Days Left</th>
      </tr></thead><tbody>${(predictions.stockShortages || []).slice(0, 8).map(s => {
        const d   = s.days_until_depletion;
        const cls = d != null ? (d <= 7 ? 'bi-crit' : d <= 14 ? 'bi-high' : 'bi-med') : 'bi-med';
        return `<tr>
          <td>${s.name}</td>
          <td>${s.current_stock} <span style="color:var(--t4);font-size:10px">${s.uom}</span></td>
          <td style="color:var(--t3)">${Number(s.avg_daily_consumption).toFixed(1)}/d</td>
          <td><span class="bi-badge ${cls}">${d != null ? d + 'd' : 'Below Min'}</span></td>
        </tr>`;
      }).join('')}</tbody></table>`
    : `<div class="bi-nod"><i class="ti ti-circle-check"></i> All items adequately stocked</div>`;

  const harvTableHtml = (predictions.harvestForecast || []).length
    ? `<table class="bi-tbl"><thead><tr>
        <th>Compartment</th><th>Species</th><th>Progress</th><th>Est. Days</th>
      </tr></thead><tbody>${(predictions.harvestForecast || []).slice(0, 8).map(h => {
        const cls = h.days_to_complete !== null
          ? (h.days_to_complete > 120 ? 'bi-high' : h.days_to_complete > 90 ? 'bi-med' : 'bi-low')
          : 'bi-low';
        return `<tr>
          <td>${h.compt_name}${h.sub_name ? ` <span style="color:var(--t4);font-size:10px">${h.sub_name}</span>` : ''}</td>
          <td style="color:var(--t3)">${h.species || '—'}</td>
          <td><div class="bi-bar-wrap">
            <div class="bi-bar"><div class="bi-bar-fill" style="width:${h.pct_complete}%;background:#2E8B57"></div></div>
            <span style="font-size:10px;color:var(--t3)">${h.pct_complete}%</span>
          </div></td>
          <td><span class="bi-badge ${cls}">${h.days_to_complete !== null ? h.days_to_complete + 'd' : '—'}</span></td>
        </tr>`;
      }).join('')}</tbody></table>`
    : `<div class="bi-nod"><i class="ti ti-info-circle"></i> No active harvest compartments</div>`;

  // ── Section 8: KPI Summary panels ────────────────────────────────────────
  const machineKpi = (predictions.machineAlerts || []).slice(0, 5).map((m, i) => {
    const eff = Number(m.recent_eff_pct) || 0;
    const pc  = Math.min(100, eff);
    const bc  = eff < 50 ? '#DC2626' : eff < 75 ? '#D97706' : '#2E8B57';
    return `<div class="bi-kpi-item">
      <span class="bi-kpi-rank">${i + 1}</span>
      <span class="bi-kpi-label">${m.machine_code} <span style="color:var(--t4)">${m.name}</span></span>
      <div class="bi-kpi-pbar-wrap"><div class="bi-kpi-pbar" style="width:${pc}%;background:${bc}"></div></div>
      <span class="bi-kpi-val">${eff > 0 ? eff.toFixed(0) + '%' : '—'}</span>
    </div>`;
  }).join('') || `<div class="bi-nod" style="padding:10px 14px"><i class="ti ti-info-circle"></i> No data</div>`;

  const harvestKpi = [...(predictions.harvestForecast || [])]
    .sort((a, b) => Number(b.total_harvested) - Number(a.total_harvested))
    .slice(0, 5).map((h, i) => {
      const vol = Number(h.volume_m3) || 1;
      const pct = Math.min(100, Math.round((Number(h.total_harvested) / vol) * 100));
      return `<div class="bi-kpi-item">
        <span class="bi-kpi-rank">${i + 1}</span>
        <span class="bi-kpi-label">${h.compt_name}</span>
        <div class="bi-kpi-pbar-wrap"><div class="bi-kpi-pbar" style="width:${pct}%"></div></div>
        <span class="bi-kpi-val">${Number(h.total_harvested).toLocaleString()} m³</span>
      </div>`;
    }).join('') || `<div class="bi-nod" style="padding:10px 14px"><i class="ti ti-info-circle"></i> No active compartments</div>`;

  const govKpi = [
    { label: 'Failed Logins (24h)',    val: gv.failed_logins_24h  || 0, c: Number(gv.failed_logins_24h) >= 10 ? '#DC2626' : Number(gv.failed_logins_24h) >= 3 ? '#EA580C' : '#22C55E' },
    { label: 'Gov. Overrides (24h)',   val: gv.priv_overrides_24h || 0, c: Number(gv.priv_overrides_24h) > 0 ? '#EA580C' : '#22C55E' },
    { label: 'Failed Jobs',            val: gv.failed_jobs        || 0, c: Number(gv.failed_jobs) > 5 ? '#DC2626' : Number(gv.failed_jobs) > 0 ? '#EA580C' : '#22C55E' },
    { label: 'Pending Approvals',      val: gv.total_pending      || 0, c: Number(gv.total_pending) > 10 ? '#D97706' : '#22C55E' },
    { label: 'Stalled >48h',           val: gv.stalled_48h        || 0, c: Number(gv.stalled_48h) > 0 ? '#D97706' : '#22C55E' },
    { label: 'Delayed Deliveries',     val: gv.delayed_deliveries || 0, c: Number(gv.delayed_deliveries) > 0 ? '#D97706' : '#22C55E' },
  ].map((g, i) => `<div class="bi-kpi-item">
    <span class="bi-kpi-rank">${i + 1}</span>
    <span class="bi-kpi-label">${g.label}</span>
    <span class="bi-kpi-val" style="color:${g.c};font-size:13px">${g.val}</span>
  </div>`).join('');

  // ── Stock anomalies sub-block ─────────────────────────────────────────────
  const anomalyHtml = (stockAnomalies || []).length
    ? `<div class="bi-ph" style="margin-top:14px;margin-bottom:6px">
         <i class="ti ti-arrows-exchange"></i> Abnormal Stock Movements (7d)
         <span class="bi-risk-count">${stockAnomalies.length}</span>
       </div>
       ${(stockAnomalies || []).slice(0, 5).map(sm => `
         <div class="bi-anomaly-row">
           <i class="ti ti-alert-circle" style="color:#EA580C;flex-shrink:0"></i>
           <span>${sm.item_name}</span>
           <b>Qty ${sm.quantity}</b>
           <span class="bi-badge bi-high">Z=${Number(sm.z_score).toFixed(1)}</span>
         </div>`).join('')}`
    : '';

  // ── Assemble ──────────────────────────────────────────────────────────────
  el.innerHTML = `
    <div class="ex-header">
      <div>
        <div class="ptitle"><i class="ti ti-chart-line"></i> Business Intelligence Center</div>
        <div class="psub">Statistical forecasting · Anomaly detection · Risk scoring — live PostgreSQL data · No external AI</div>
      </div>
      <div class="ex-actions">
        <span class="ex-ts" id="bi-ts">Updated: ${ts}</span>
        <button class="ibtn" id="bi-refresh" title="Refresh"><i class="ti ti-refresh"></i></button>
        <button class="ibtn" id="bi-export"  title="Export CSV"><i class="ti ti-file-download"></i></button>
        <button class="ibtn" id="bi-print"   title="Print / PDF"><i class="ti ti-printer"></i></button>
      </div>
    </div>

    <!-- Health + Predictions -->
    <div class="bi-row2a">
      <div class="card bi-health-card">
        <div class="bi-ph" style="margin-bottom:2px"><i class="ti ti-activity-heartbeat"></i> Company Health Score</div>
        ${gauge}
        <div class="bi-refresh-ts">${ts}</div>
        <div class="bi-bkd" style="margin-top:10px">${bkdHtml}</div>
      </div>
      <div class="bi-pred-grid">${predCards}</div>
    </div>

    <!-- Risk Radar Cards -->
    ${riskCardsHtml ? `
    <div class="bi-section-hdr">
      <i class="ti ti-radar-2"></i> Risk Radar
      <span class="bi-risk-count">${risks.length} active</span>
    </div>
    <div class="bi-risk-cards">${riskCardsHtml}</div>` : ''}

    <!-- Recommendations -->
    ${sec.has('recommendations') ? `
    <div class="card" style="margin-bottom:16px">
      <div class="bi-ph">
        <i class="ti ti-bulb"></i> ${sec.has('governance') ? 'Executive' : 'Operational'} Recommendations
        <span style="margin-left:auto;font-size:10px;color:var(--t4)">${recommendations.length} action item(s)</span>
      </div>
      <div>${recHtml}</div>
    </div>` : ''}

    <!-- Forecast Charts (sales + workshop) -->
    ${sec.has('charts') ? `
    <div class="bi-row2">
      ${sec.has('sales') ? `<div class="card">
        <div class="bi-ph"><i class="ti ti-chart-line"></i> Sales Revenue — 30d History + 30d Forecast</div>
        ${salesChartHtml}
        ${(forecasts.sales30d||[]).length > 5 ? `<div class="ex-clabels">${sDateLbls}</div>` : ''}
        <div class="bi-legend">
          <span><span class="bi-dot" style="background:#2E8B57"></span>Historical (30d)</span>
          <span><span class="bi-dot bi-dot--dash"></span>Forecast (30d)</span>
        </div>
        ${sfcstAvg ? `<div class="bi-stat-note">30d projected avg: <strong>${_fmtCur(sfcstAvg)}/day</strong> · R²=${sR2.toFixed(2)}</div>` : ''}
      </div>` : ''}
      ${sec.has('workshop') ? `<div class="card">
        <div class="bi-ph"><i class="ti ti-building-factory"></i> Workshop Output — 12-Week History + 4-Week Forecast</div>
        ${wkChartHtml}
        <div class="bi-legend">
          <span><span class="bi-dot" style="background:#7C3AED"></span>Historical (12 wk)</span>
          <span><span class="bi-dot bi-dot--dash"></span>Forecast (4 wk)</span>
        </div>
        ${wfcstAvg ? `<div class="bi-stat-note">4-week avg: <strong>${wfcstAvg} units/week</strong> · ${wTrend >= 0 ? '+' : ''}${wTrend.toFixed(1)}%/wk trend</div>` : ''}
      </div>` : ''}
    </div>` : ''}

    <!-- Risk Timeline -->
    ${(sec.has('recommendations') || sec.has('governance')) && tlItems.length ? `
    <div class="card" style="margin-bottom:16px">
      <div class="bi-ph">
        <i class="ti ti-timeline"></i> Risk &amp; Event Timeline
        <span style="margin-left:auto;font-size:10px;color:var(--t4)">Current snapshot — critical first</span>
      </div>
      <div class="bi-timeline">${tlHtml}</div>
    </div>` : ''}

    <!-- Data Tables: Stock + Harvest -->
    ${(sec.has('stock') || sec.has('harvest')) ? `
    <div class="bi-row2">
      ${sec.has('stock') ? `<div class="card">
        <div class="bi-ph"><i class="ti ti-package"></i> Stock Depletion Forecast</div>
        ${stockTableHtml}
      </div>` : ''}
      ${sec.has('harvest') ? `<div class="card">
        <div class="bi-ph"><i class="ti ti-trees"></i> Harvest Completion Forecast</div>
        ${harvTableHtml}
      </div>` : ''}
    </div>` : ''}

    <!-- Machine Efficiency + Governance Snapshot -->
    ${(sec.has('machines') || sec.has('governance')) ? `
    <div class="bi-row2">
      ${sec.has('machines') ? `<div class="card">
        <div class="bi-ph"><i class="ti ti-trending-down"></i> Declining Machine Efficiency</div>
        ${(predictions.efficiencyDecline||[]).length
          ? `<table class="bi-tbl"><thead><tr>
              <th>Machine</th><th>Avg Eff</th><th>Trend/Week</th><th>Weeks Obs.</th>
             </tr></thead><tbody>${(predictions.efficiencyDecline||[]).map(m => `<tr>
               <td>${m.machine_code} <span style="color:var(--t3)">${m.name}</span></td>
               <td>${Number(m.avg_eff).toFixed(1)}%</td>
               <td style="color:#DC2626;font-weight:600"><i class="ti ti-trending-down"></i> ${Number(m.eff_slope).toFixed(1)}%</td>
               <td style="color:var(--t3)">${m.weeks}w</td>
             </tr>`).join('')}</tbody></table>`
          : `<div class="bi-nod"><i class="ti ti-circle-check"></i> No declining efficiency detected</div>`}
      </div>` : ''}
      ${sec.has('governance') ? `<div class="card">
        <div class="bi-ph"><i class="ti ti-shield-lock"></i> Governance &amp; Security Snapshot</div>
        <div class="bi-stat-grid">
          ${[
            { label: 'Failed Logins (24h)',  val: gv.failed_logins_24h  || 0, cls: Number(gv.failed_logins_24h) >= 10 ? 'bi-crit-txt' : Number(gv.failed_logins_24h) >= 3 ? 'bi-high-txt' : '' },
            { label: 'Gov. Overrides (24h)', val: gv.priv_overrides_24h || 0, cls: Number(gv.priv_overrides_24h) > 0 ? 'bi-high-txt' : '' },
            { label: 'Failed Jobs',          val: gv.failed_jobs        || 0, cls: Number(gv.failed_jobs) > 5 ? 'bi-crit-txt' : Number(gv.failed_jobs) > 0 ? 'bi-high-txt' : '' },
            { label: 'Pending Approvals',    val: gv.total_pending      || 0, cls: '' },
            { label: 'Stalled >48h',         val: gv.stalled_48h        || 0, cls: Number(gv.stalled_48h) > 0 ? 'bi-med-txt' : '' },
            { label: 'Delayed Deliveries',   val: gv.delayed_deliveries || 0, cls: Number(gv.delayed_deliveries) > 0 ? 'bi-med-txt' : '' },
          ].map(g => `<div class="bi-stat-item"><span>${g.label}</span><b class="${g.cls}">${g.val}</b></div>`).join('')}
        </div>
        ${anomalyHtml}
      </div>` : ''}
    </div>` : ''}

    <!-- KPI Summary panels -->
    ${(sec.has('machines') || sec.has('harvest') || sec.has('governance')) ? `
    <div class="bi-kpi-row">
      ${sec.has('machines') ? `<div class="bi-kpi-panel">
        <div class="bi-kpi-ph"><i class="ti ti-settings-2"></i> Machine Performance (14d avg eff)</div>
        ${machineKpi}
      </div>` : ''}
      ${sec.has('harvest') ? `<div class="bi-kpi-panel">
        <div class="bi-kpi-ph"><i class="ti ti-trees"></i> Top Harvest Compartments</div>
        ${harvestKpi}
      </div>` : ''}
      ${sec.has('governance') ? `<div class="bi-kpi-panel">
        <div class="bi-kpi-ph"><i class="ti ti-shield-check"></i> Governance KPIs</div>
        ${govKpi}
      </div>` : ''}
    </div>` : ''}`;

  $('bi-refresh').onclick = () => renderBI();
  $('bi-export').onclick  = () => exportBiCSV();
  $('bi-print').onclick   = () => window.print();
}

async function renderSecGovDashboard() {
  _secGovLastLoad = Date.now();
  const container = $('page-secgov');
  container.innerHTML = `<div class="ptitle">Security &amp; Governance</div><div class="psub">Loading…</div>`;

  const res = await UFCL.secGovDashboard(STORAGE.user.id);
  if (!res.ok) return renderDenied('secgov', res.error);

  const kpi   = res.kpi           || {};
  const appr  = res.approvals     || {};
  const notif = res.notifCounts   || {};
  const sec   = res.securityEvents || [];
  const wf    = res.workflowHealth || [];
  const feed  = res.auditFeed      || [];

  const now = new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });

  // ── KPI cards ───────────────────────────────────────────────────────────────
  const kpiHtml = `
    <div class="sg-grid4">
      <div class="sg-kpi${kpi.failedLogins    > 0 ? ' sg-kpi-red'   : ''}">
        <div class="sg-kpi-n">${kpi.failedLogins}</div>
        <div class="sg-kpi-l">Failed Logins</div>
        <div class="sg-kpi-s">Last 24 hours</div>
      </div>
      <div class="sg-kpi${kpi.privOverrides   > 0 ? ' sg-kpi-amber' : ''}">
        <div class="sg-kpi-n">${kpi.privOverrides}</div>
        <div class="sg-kpi-l">Privileged Overrides</div>
        <div class="sg-kpi-s">Last 24 hours</div>
      </div>
      <div class="sg-kpi${kpi.pendingApprovals > 0 ? ' sg-kpi-amber' : ' sg-kpi-green'}">
        <div class="sg-kpi-n">${kpi.pendingApprovals}</div>
        <div class="sg-kpi-l">Pending Approvals</div>
        <div class="sg-kpi-s">Edit &amp; deletion requests</div>
      </div>
      <div class="sg-kpi${kpi.workflowFailures > 0 ? ' sg-kpi-red'  : ' sg-kpi-green'}">
        <div class="sg-kpi-n">${kpi.workflowFailures}</div>
        <div class="sg-kpi-l">Workflow Failures</div>
        <div class="sg-kpi-s">Permanently failed jobs</div>
      </div>
    </div>`;

  // ── Unread notification counts ─────────────────────────────────────────────
  const notifHtml = `
    <div class="sg-notif-row">
      <div class="sg-notif-box">
        <div class="ndot nd-red"   style="width:9px;height:9px;flex-shrink:0"></div>
        <div><div class="sg-notif-n" style="color:var(--red)">${notif.security}</div><div class="sg-notif-l">Security Alerts</div></div>
      </div>
      <div class="sg-notif-box">
        <div class="ndot nd-amber" style="width:9px;height:9px;flex-shrink:0"></div>
        <div><div class="sg-notif-n" style="color:var(--amber)">${notif.approval}</div><div class="sg-notif-l">Approval Alerts</div></div>
      </div>
      <div class="sg-notif-box">
        <div class="ndot nd-blue"  style="width:9px;height:9px;flex-shrink:0"></div>
        <div><div class="sg-notif-n" style="color:var(--blue)">${notif.system}</div><div class="sg-notif-l">System Alerts</div></div>
      </div>
    </div>`;

  // ── Security events table ───────────────────────────────────────────────────
  const secRows = sec.length === 0
    ? `<div style="padding:2rem;text-align:center;color:var(--t3);font-size:13px"><i class="ti ti-shield-check" style="font-size:24px;display:block;margin-bottom:.5rem;opacity:.3"></i>No security events in the last period.</div>`
    : sec.map(e => {
        const [lbl, cls] = e.action_type === 'privileged_override' ? ['OVERRIDE','sg-bd-amber']
                         : e.action_type === 'login_denied'        ? ['DENIED',  'sg-bd-amber']
                         : ['FAILED', 'sg-bd-red'];
        return `<div class="sg-row">
          <div class="sg-col-time">${e.time}</div>
          <div class="sg-col-user" title="${e.username}">${e.username || '—'}</div>
          <span class="sg-badge ${cls}">${lbl}</span>
          <div class="sg-col-action" title="${e.action}">${e.action}</div>
        </div>`;
      }).join('');

  // ── Approval overview ────────────────────────────────────────────────────────
  const avgStr = appr.avgHours != null ? `${appr.avgHours} h` : '—';
  const apprHtml = `
    <div class="sg-stat-row"><span class="sg-stat-l">Leader-level pending</span><strong class="sg-stat-v">${appr.leaderPending}</strong></div>
    <div class="sg-stat-row"><span class="sg-stat-l">Manager-level pending</span><strong class="sg-stat-v">${appr.managerPending}</strong></div>
    <div class="sg-stat-row"><span class="sg-stat-l">Escalated requests</span><strong class="sg-stat-v${appr.escalated > 0 ? ' sg-stat-alert' : ''}">${appr.escalated}</strong></div>
    <div class="sg-stat-row"><span class="sg-stat-l">Total pending</span><strong class="sg-stat-v">${kpi.pendingApprovals}</strong></div>
    <div class="sg-stat-row" style="border-bottom:none"><span class="sg-stat-l">Avg approval time (30 d)</span><strong class="sg-stat-v">${avgStr}</strong></div>`;

  // ── Workflow health ──────────────────────────────────────────────────────────
  const wfRows = wf.length === 0
    ? `<div style="padding:2rem;text-align:center;color:var(--t3);font-size:13px"><i class="ti ti-circle-check" style="font-size:24px;display:block;margin-bottom:.5rem;opacity:.3"></i>No active or failed jobs.</div>`
    : wf.map(j => {
        const st  = (j.status === 'pending' && j.attempts > 0) ? 'retrying' : j.status;
        const cls = st === 'failed' ? 'sg-bd-red' : st === 'retrying' ? 'sg-bd-amber' : 'sg-bd-blue';
        const err = j.last_error ? `<div style="color:var(--red);font-size:11px;margin-top:2px;white-space:normal">${j.last_error.slice(0, 90)}</div>` : '';
        return `<div class="sg-row">
          <div class="sg-col-time">${j.created_fmt || '—'}</div>
          <div class="sg-col-user">#${j.id} ${j.type}</div>
          <span class="sg-badge ${cls}">${st}</span>
          <div class="sg-col-action">${j.attempts}/${j.max_attempts} attempts${err}</div>
        </div>`;
      }).join('');

  // ── Audit feed ───────────────────────────────────────────────────────────────
  function auditTag(row) {
    const at  = (row.action_type || '').toLowerCase();
    const mod = (row.module      || '').toLowerCase();
    if (['login_failed','login_denied','privileged_override'].includes(at) || mod === 'auth')
      return ['SECURITY',   'sg-bd-red'];
    if (['approve','reject','create_request'].includes(at) || ['governance','pending_edits'].includes(mod))
      return ['GOVERNANCE', 'sg-bd-amber'];
    if (mod === 'workflow')
      return ['WORKFLOW',   'sg-bd-blue'];
    return ['OPERATIONS', 'sg-bd-green'];
  }

  const feedRows = feed.length === 0
    ? `<div style="padding:2rem;text-align:center;color:var(--t3);font-size:13px">No audit events.</div>`
    : feed.map(e => {
        const [lbl, cls] = auditTag(e);
        return `<div class="sg-row">
          <div class="sg-col-time">${e.time}</div>
          <div class="sg-col-user" title="${e.full_name || e.username}">${e.username || '—'}</div>
          <span class="sg-badge ${cls}">${lbl}</span>
          <div class="sg-col-action" title="${e.action}">${e.action}</div>
        </div>`;
      }).join('');

  // ── Assemble ─────────────────────────────────────────────────────────────────
  container.innerHTML = `
    <div style="display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:1rem">
      <div>
        <div class="ptitle" style="margin-bottom:0">Security &amp; Governance</div>
        <div class="psub">Real-time security, governance, and workflow monitoring.</div>
      </div>
      <div style="display:flex;align-items:center;gap:.5rem;padding-top:.25rem;flex-shrink:0">
        <span style="font-size:11px;color:var(--t4)">Updated ${now}</span>
        <button id="sg-refresh" class="bs1" style="padding:4px 10px;font-size:12px"><i class="ti ti-refresh"></i> Refresh</button>
      </div>
    </div>

    ${kpiHtml}
    ${notifHtml}

    <div style="display:grid;grid-template-columns:1fr 1fr;gap:.75rem;margin-bottom:.875rem">
      <div class="sg-panel" style="margin-bottom:0">
        <div class="sg-ph"><span>Security Events</span><em>latest 25</em></div>
        ${secRows}
      </div>
      <div class="sg-panel" style="margin-bottom:0">
        <div class="sg-ph"><span>Approval Overview</span><em>edit &amp; deletion requests</em></div>
        ${apprHtml}
      </div>
    </div>

    <div class="sg-panel">
      <div class="sg-ph"><span>Workflow Health</span><em>failed · retrying · processing</em></div>
      ${wfRows}
    </div>

    <div class="sg-panel">
      <div class="sg-ph"><span>Audit Activity</span><em>latest 50 events</em></div>
      ${feedRows}
    </div>`;

  $('sg-refresh').onclick = () => renderSecGovDashboard();
}

async function renderNotifications() {
  _NOTIF.page = 0;
  const container = $('page-notifications');

  const catChips = ['', 'security', 'approval', 'workflow', 'system', 'audit'].map(v => {
    const lbl    = v === '' ? 'All Categories' : v[0].toUpperCase() + v.slice(1);
    const active = (!_NOTIF.filters.category && v === '') || _NOTIF.filters.category === v;
    return `<button class="nchip${active ? ' active' : ''}" data-fcat="${v}">${lbl}</button>`;
  }).join('');

  const typeChips = [['', 'All Types'], ['red', '● Red'], ['amber', '● Amber'], ['green', '● Green']].map(([v, l]) => {
    const active = (!_NOTIF.filters.type && v === '') || _NOTIF.filters.type === v;
    return `<button class="nchip${active ? ' active' : ''}" data-ftype="${v}">${l}</button>`;
  }).join('');

  container.innerHTML = `
    <div class="ptitle">Notifications</div>
    <div class="psub">System alerts, security events, and approval workflows.</div>

    <div class="nstats">
      <div class="nstat-box"><div class="nstat-n" id="ns-unread">—</div><div class="nstat-l">Unread</div></div>
      <div class="nstat-box nstat-red"><div class="nstat-n" id="ns-security">—</div><div class="nstat-l">Security</div></div>
      <div class="nstat-box nstat-amber"><div class="nstat-n" id="ns-approval">—</div><div class="nstat-l">Approval</div></div>
      <div class="nstat-box nstat-blue"><div class="nstat-n" id="ns-system">—</div><div class="nstat-l">System</div></div>
    </div>

    <div class="npanel" style="margin-bottom:0;border-radius:var(--r-lg) var(--r-lg) 0 0">
      <div class="nhead">
        <span>Filters</span>
        <div style="display:flex;gap:6px;align-items:center">
          <button id="notif-clear" style="background:none;border:1px solid var(--border2);border-radius:var(--r-sm);font-size:11px;padding:3px 9px;cursor:pointer;font-family:var(--ff);color:var(--t3)">Clear filters</button>
          <button id="notif-mark-all" class="appbtn" style="padding:4px 12px;font-size:12px">Mark all read</button>
        </div>
      </div>
      <div class="nfilterbar">${catChips}</div>
      <div class="nfilterbar">${typeChips}</div>
      <div class="nfilterbar" style="border-bottom:none">
        <input id="notif-search" type="text" placeholder="Search title or body…" value="${_NOTIF.filters.search || ''}"
          style="flex:1;min-width:160px;border:1px solid var(--border2);border-radius:var(--r-sm);padding:5px 10px;font-size:12px;background:var(--surf);color:var(--t1);font-family:var(--ff);outline:none">
        <input id="notif-from" type="date" value="${_NOTIF.filters.fromDate || ''}"
          style="border:1px solid var(--border2);border-radius:var(--r-sm);padding:5px 8px;font-size:12px;background:var(--surf);color:var(--t1);font-family:var(--ff);outline:none">
        <input id="notif-to" type="date" value="${_NOTIF.filters.toDate || ''}"
          style="border:1px solid var(--border2);border-radius:var(--r-sm);padding:5px 8px;font-size:12px;background:var(--surf);color:var(--t1);font-family:var(--ff);outline:none">
      </div>
    </div>

    <div id="notif-list-wrap">
      <div style="text-align:center;padding:2rem;color:var(--t3);font-size:13px">Loading…</div>
    </div>`;

  container.querySelectorAll('[data-fcat]').forEach(btn => {
    btn.onclick = () => {
      _NOTIF.filters.category = btn.dataset.fcat || null;
      _NOTIF.page = 0;
      container.querySelectorAll('[data-fcat]').forEach(b =>
        b.classList.toggle('active', b.dataset.fcat === btn.dataset.fcat));
      _loadNotifItems();
    };
  });

  container.querySelectorAll('[data-ftype]').forEach(btn => {
    btn.onclick = () => {
      _NOTIF.filters.type = btn.dataset.ftype || null;
      _NOTIF.page = 0;
      container.querySelectorAll('[data-ftype]').forEach(b =>
        b.classList.toggle('active', b.dataset.ftype === btn.dataset.ftype));
      _loadNotifItems();
    };
  });

  $('notif-search').oninput = () => {
    clearTimeout(_searchTimer);
    _searchTimer = setTimeout(() => {
      _NOTIF.filters.search = $('notif-search').value.trim() || null;
      _NOTIF.page = 0;
      _loadNotifItems();
    }, 300);
  };

  $('notif-from').onchange = () => {
    _NOTIF.filters.fromDate = $('notif-from').value || null;
    _NOTIF.page = 0;
    _loadNotifItems();
  };
  $('notif-to').onchange = () => {
    _NOTIF.filters.toDate = $('notif-to').value || null;
    _NOTIF.page = 0;
    _loadNotifItems();
  };

  $('notif-clear').onclick = () => {
    _NOTIF.filters = {};
    _NOTIF.page = 0;
    renderNotifications();
  };

  $('notif-mark-all').onclick = async () => {
    const r = await UFCL.notificationsMarkAllRead(STORAGE.user.id);
    if (r.ok) {
      STORAGE.unread = r.unread ?? 0;
      updateBadge();
      await _loadNotifItems();
    }
  };

  await _loadNotifItems();
}

async function _loadNotifItems() {
  const wrap = $('notif-list-wrap');
  if (!wrap) return;

  const res = await UFCL.notificationsList(STORAGE.user.id, {
    type:     _NOTIF.filters.type     || undefined,
    category: _NOTIF.filters.category || undefined,
    search:   _NOTIF.filters.search   || undefined,
    fromDate: _NOTIF.filters.fromDate || undefined,
    toDate:   _NOTIF.filters.toDate   || undefined,
    page:     _NOTIF.page,
    limit:    50,
  });

  if (!res.ok) {
    wrap.innerHTML = `<div style="text-align:center;padding:2rem;color:var(--red);font-size:13px">Failed to load: ${res.error || 'Error'}</div>`;
    return;
  }

  STORAGE.unread = res.unread ?? 0;
  updateBadge();

  const rows    = res.rows    || [];
  const total   = res.total   || 0;
  const page    = res.page    || 0;
  const hasMore = res.hasMore || false;

  const ns  = $('ns-unread');   if (ns)  ns.textContent  = STORAGE.unread;
  const nss = $('ns-security'); if (nss) nss.textContent = rows.filter(r => !r.read && r.category === 'security').length;
  const nsa = $('ns-approval'); if (nsa) nsa.textContent = rows.filter(r => !r.read && r.category === 'approval').length;
  const nsm = $('ns-system');   if (nsm) nsm.textContent = rows.filter(r => !r.read && r.category === 'system').length;

  const catCls  = { security: 'ncat-security', approval: 'ncat-approval', workflow: 'ncat-workflow', system: 'ncat-system', audit: 'ncat-audit' };
  const typeDot = t => t === 'red' ? 'nd-red' : t === 'amber' ? 'nd-amber' : t === 'blue' ? 'nd-blue' : 'nd-green';
  const hasFilters = Object.values(_NOTIF.filters).some(v => v != null && v !== '');

  const itemsHtml = rows.length === 0
    ? `<div style="text-align:center;padding:3rem 1rem;color:var(--t3);font-size:13px">
         <i class="ti ti-bell-off" style="font-size:28px;display:block;margin-bottom:.5rem;opacity:.3"></i>
         No notifications${hasFilters ? ' match your filters' : ''}.
       </div>`
    : rows.map(n => {
        const cat    = n.category ? `<span class="ncat ${catCls[n.category] || 'ncat-system'}">${n.category}</span>` : '';
        const direct = n.direct   ? `<span style="font-size:10px;background:rgba(99,102,241,.12);color:#6366f1;padding:1px 6px;border-radius:10px;font-weight:600;margin-left:4px">For you</span>` : '';
        const rel    = (n.related_module || n.related_id)
          ? `<div class="nrelated"><i class="ti ti-corner-right-down" style="font-size:10px"></i>${n.related_module ? `<strong>${n.related_module}</strong>` : ''}${n.related_id ? `&nbsp;·&nbsp;${n.related_id}` : ''}</div>`
          : '';
        const markBtn = n.read ? '' : `<button class="bs1" style="padding:3px 9px;font-size:11px;flex-shrink:0" data-mr="${n.id}">Mark read</button>`;
        // ERP Enterprise Completion Phase 5 (Workstream 5) — clickable only
        // when related_module is present, so non-actionable notifications
        // (no related record) keep their exact prior appearance/behavior.
        const linkable = !!n.related_module;
        return `<div class="nitem ${n.read ? '' : 'unread'}${linkable ? ' nitem-linkable' : ''}" id="nn-${n.id}"
          ${linkable ? `data-nid="${n.id}" data-nmodule="${n.related_module}" data-nrelid="${n.related_id || ''}" style="cursor:pointer"` : ''}>
          <div class="ndot ${typeDot(n.type)}" style="margin-top:3px;flex-shrink:0"></div>
          <div style="flex:1;min-width:0">
            <div class="ntxt"><strong>${n.title}</strong>${cat}${direct}
              <div style="color:var(--t3);margin-top:2px;line-height:1.5">${n.body}</div>${rel}
            </div>
            <div class="ntime">${n.time}</div>
          </div>
          ${markBtn}
        </div>`;
      }).join('');

  const start = page * 50 + 1;
  const end   = Math.min(page * 50 + rows.length, total);
  const pager = total > 50
    ? `<div class="npager">
         <button class="nchip" id="notif-prev" ${page === 0 ? 'disabled' : ''}>← Prev</button>
         <span style="font-size:12px;color:var(--t3)">${start}–${end} of ${total}</span>
         <button class="nchip" id="notif-next" ${!hasMore ? 'disabled' : ''}>Next →</button>
       </div>`
    : '';

  wrap.innerHTML = `
    <div class="npanel" style="border-radius:0 0 var(--r-lg) var(--r-lg);border-top:none">
      <div class="nhead"><span>${total} notification${total !== 1 ? 's' : ''}${hasFilters ? ' (filtered)' : ''}</span></div>
      <div id="notif-scroll">${itemsHtml}</div>
    </div>${pager}`;

  wrap.querySelectorAll('[data-mr]').forEach(b => {
    b.onclick = async (e) => {
      e.stopPropagation(); // don't also trigger the row's own deep-link click below
      const r = await UFCL.notificationsMarkRead(STORAGE.user.id, Number(b.dataset.mr));
      if (r.ok) {
        STORAGE.unread = r.unread ?? 0;
        updateBadge();
        await _loadNotifItems();
      }
    };
  });

  // ERP Enterprise Completion Phase 5 (Workstream 5/9) — clicking a linkable
  // row marks it read (reusing the exact same call as the button above) and
  // navigates via the routing registry. Read-state behavior is otherwise
  // completely unchanged — this only adds a second way to reach mark-read.
  wrap.querySelectorAll('.nitem-linkable').forEach(el => {
    el.onclick = async () => {
      const id = Number(el.dataset.nid);
      const relId = el.dataset.nrelid ? Number(el.dataset.nrelid) : null;
      await UFCL.notificationsMarkRead(STORAGE.user.id, id);
      await navigateToNotification(el.dataset.nmodule, relId);
    };
  });

  const prevBtn = $('notif-prev');
  const nextBtn = $('notif-next');
  if (prevBtn) prevBtn.onclick = () => { _NOTIF.page = Math.max(0, page - 1); _loadNotifItems(); };
  if (nextBtn) nextBtn.onclick = () => { _NOTIF.page = page + 1; _loadNotifItems(); };
}

// ── Notification Deep Linking (ERP Enterprise Completion Phase 5) ──────────────
// Centralized routing registry (Workstream 4) — one place mapping a
// notification's related_module to where it opens, instead of scattering
// navigation logic per notification row. Every `open` function below already
// exists, is already globally callable, already fetches through the same
// authorized backend function the module's own page uses, and already shows
// its own graceful error state (showOverlayError) if the record can't be
// loaded — this registry adds zero new authorization logic of its own; it is
// pure navigation, exactly matching Workstream 14's "server remains
// authoritative" requirement. Modules absent from this map (including the
// generic 'procurement' fallback and the escalation engine's 'Governance'/
// 'Security'/'System' alerts, which aren't about one record) resolve to "no
// linked page available" — never a wrong page, per Workstream 5.
//
// 'material-requests' is intentionally page-only: openMaterialRequestDetailOverlay
// is declared inside renderMaterialRequests()'s own closure (not a global
// function like the others), so the specific record can't be auto-opened
// from here without a larger refactor — out of this phase's minimal-footprint
// scope (documented in the Phase 5 completion report, not silently dropped).
// 'rejection_holds'/'resolution_records' can originate from either Sawmill or
// VAT (the shared engine, per Phase 3's audit) — routed to Sawmill's
// dashboard as the more common producer; documented as an acknowledged
// imprecision, not a wrong-module bug.
//
// ERP UI/UX Completion Phase 8 (Workstream 12) — audited the full set of
// relatedModule values data.js actually emits against this registry. Two
// more belong in the same "intentionally page-only" class as
// material-requests, for the identical reason (no reusable global
// open-by-id function exists, and for 'sales' no detail overlay exists at
// all): 'sales' (relatedId: sales order id) and 'deliveries' (relatedId:
// delivery order id). Building either is new feature work, out of scope
// for this phase's fix-what's-broken mandate — not silently dropped.
const NOTIFICATION_ROUTES = {
  'stock_transfers':          { page: 'stock-transfers',          open: (id) => openStockTransferDetailOverlay(id) },
  'maintenance_jobs':         { page: 'maintenance-jobs',         open: (id) => openMaintenanceJobDetailOverlay(id) },
  'procurement-requisitions': { page: 'procurement-requisitions', open: (id) => openRequisitionDetailOverlay(id) },
  'procurement-orders':       { page: 'procurement-orders',       open: (id) => openPoDetailOverlay(id) },
  'procurement-invoices':     { page: 'procurement-invoices',     open: (id) => openInvoiceDetailOverlay(id) },
  'procurement-rfq':          { page: 'procurement-rfq',          open: (id) => openRfqDetailOverlay(id) },
  'procurement-suppliers':    { page: 'procurement-suppliers',    open: (id) => openSupplierManageOverlay(id, '', 'overview') },
  'material-requests':        { page: 'material-requests' },
  'rejection_holds':          { page: 'sawmill-dashboard' },
  'resolution_records':       { page: 'sawmill-dashboard' },
  'harvest_waste':            { page: 'daily-harvest' },
  'showroom_damage_reports':  { page: 'showroom' },
  // Pole Production Phase 2 — page-only (the pending-QC queue is right there
  // on the Daily Poles page, no per-record open function needed), same
  // "intentionally page-only" class as material-requests above.
  'purchased_pole_qc':        { page: 'daily-poles' },
  // ERP Enterprise Cross-Department Verification — maintenance-overdue
  // escalations route here (relatedId is a machine id); page-only since no
  // per-record "open machine detail" overlay function exists, same class as
  // material-requests above.
  'machines':                 { page: 'machines' },
  // ERP Final Enterprise Completion Gate — dispatchCreate's notification was
  // malformed at the source (no relatedModule/relatedId at all) until this
  // phase's fix; page-only since no per-record "open dispatch request"
  // overlay function exists, same class as material-requests above.
  'dispatch':                 { page: 'dispatch' },
  // HR Enterprise Phase 1 — casualLabourRequestsReview's new approval/
  // rejection notification; page-only, same class as material-requests
  // above (no per-record "open request" overlay function exists).
  'casual-requests':          { page: 'casual-requests' },
  // ERP Remaining Departments Completion Program — 'governance' (pushed by
  // autoRequestEdit/autoRequestDelete, data.js — a routine, high-frequency
  // notification fired every time a restricted user's edit/delete is queued
  // for approval) had NO entry here at all, unlike mobile's own
  // notificationRouting.ts, which already special-cases it to the root
  // Governance screen. Every such notification on desktop always showed "No
  // linked page available", regardless of relatedId. Routes to the existing
  // Security & Governance page (nav id 'secgov'), where pending approvals
  // are already reviewed.
  'governance':               { page: 'secgov' },
  // Master Professionalization Phase C1 — upgraded from page-only to a real
  // per-record deep link now that openSalesOrderDetailOverlay exists (it
  // didn't when this was first added as page-only — see the ERP UI/UX
  // Completion Phase 8 comment this replaces).
  'sales':                    { page: 'sales', open: (id) => openSalesOrderDetailOverlay(Number(id)) },
  'deliveries':               { page: 'deliveries' },
  // Backs ENTITY_ESCALATION_MODULE.security (data.js) — a system-wide
  // failed-login alert (relatedId is the literal string '_global', not a
  // per-record id); page-only to Audit Log, where the underlying
  // login_failed events are actually listed.
  'audit':                    { page: 'audit' },
  // ERP Final Enterprise Hardening Phase (Priority 5) — closed 3 more
  // automation-engine 'module' literals (stock_low/fuel_anomaly/
  // harvest_behind rules in data.js's _autoAct calls) that previously used
  // capitalized strings matching no routing key at all. Same page-only class
  // as material-requests/machines above — no per-record open function exists
  // for a stock item, a vehicle, or a compartment.
  'stock':                    { page: 'stock-items' },
  'fuel':                     { page: 'vehicles' },
  'harvest':                  { page: 'compartments' },
  // Payroll Enterprise Phase 2 — notifyPayrollEvent's relatedModule for every
  // event (submitted/stage-approved/approved/rejected/returned/closed,
  // adjustment approved/rejected); page-only, same class as
  // material-requests/machines above (a payroll period has no per-record
  // detail overlay reachable from a bare id — the Payroll page's own
  // periods-list-then-click-in flow is the only entry point).
  'payroll':                  { page: 'payroll' },
};

async function navigateToNotification(relatedModule, relatedId) {
  const route = relatedModule ? NOTIFICATION_ROUTES[relatedModule] : null;
  if (!route) { showToast('No linked page available for this notification.', 'info'); return; }
  await showPage(route.page);
  if (route.open && relatedId) {
    try { await route.open(relatedId); }
    catch (e) { showOverlayError(e?.message || 'Could not open the linked record.'); }
  }
}

// ── Global Search ──────────────────────────────────────────────────────────────
// Cross-module search — mirrors mobile/src/screens/search/GlobalSearchScreen.tsx.
// Overview mode shows a capped preview grouped by module (server-side, via
// data.globalSearch); "See all" switches to deep mode (one module, paginated).

// Opens Global Search fresh, defaulting its scope to whichever module the
// current page represents ("Context Search") — the searchBtn click and the
// Ctrl+K shortcut are the only two entry points that should ever do this;
// showPage('search') on its own (e.g. the refresh button while already on the
// search page) deliberately does NOT reset state, see the 'search' case in
// showPage()'s switch.
function openGlobalSearch() {
  if (CURRENT_PAGE !== 'search') _SEARCH.returnPage = CURRENT_PAGE;
  const contextModule = PAGE_TO_SEARCH_MODULE[CURRENT_PAGE] || null;
  setActivePage('search');
  renderGlobalSearch(contextModule);
}

// Lightweight hook point for Global Search analytics — intentionally a no-op
// beyond logging until a real analytics pipeline is wired up (see the mobile
// app's utils/searchAnalytics.ts for the same pattern).
function trackSearchEvent(event, payload) {
  console.log('[search-analytics]', event, payload);
}

// ── Recent / favorite searches (localStorage) ──────────────────────────────────
// Same local-only, fail-soft, capped-list pattern as the mobile app's
// AsyncStorage-backed equivalents (utils/storage.ts) — never sent to the server.
const GS_RECENT_KEY = 'ufcl_gs_recent_searches';
const GS_FAVORITES_KEY = 'ufcl_gs_favorite_searches';
const GS_RECENT_MAX = 10;
const GS_FAVORITES_MAX = 20;

function _gsLoadRecent() {
  try { return JSON.parse(localStorage.getItem(GS_RECENT_KEY) || '[]'); } catch { return []; }
}
function _gsSaveRecent(query) {
  const q = (query || '').trim();
  if (!q) return _gsLoadRecent();
  try {
    const next = [q, ...(_gsLoadRecent().filter((s) => s.toLowerCase() !== q.toLowerCase()))].slice(0, GS_RECENT_MAX);
    localStorage.setItem(GS_RECENT_KEY, JSON.stringify(next));
    return next;
  } catch { return _gsLoadRecent(); }
}
function _gsRemoveRecent(query) {
  try {
    const next = _gsLoadRecent().filter((s) => s.toLowerCase() !== query.toLowerCase());
    localStorage.setItem(GS_RECENT_KEY, JSON.stringify(next));
    return next;
  } catch { return _gsLoadRecent(); }
}
function _gsClearRecent() {
  try { localStorage.removeItem(GS_RECENT_KEY); } catch { /* non-fatal */ }
}

function _gsLoadFavorites() {
  try { return JSON.parse(localStorage.getItem(GS_FAVORITES_KEY) || '[]'); } catch { return []; }
}
function _gsSaveFavorite(query, filters) {
  const q = (query || '').trim();
  if (!q) return _gsLoadFavorites();
  try {
    const entry = { id: `${Date.now()}`, query: q, filters, savedAt: new Date().toISOString() };
    const next = [entry, ...(_gsLoadFavorites().filter((f) => f.query.toLowerCase() !== q.toLowerCase()))].slice(0, GS_FAVORITES_MAX);
    localStorage.setItem(GS_FAVORITES_KEY, JSON.stringify(next));
    return next;
  } catch { return _gsLoadFavorites(); }
}
function _gsRemoveFavorite(id) {
  try {
    const next = _gsLoadFavorites().filter((f) => f.id !== id);
    localStorage.setItem(GS_FAVORITES_KEY, JSON.stringify(next));
    return next;
  } catch { return _gsLoadFavorites(); }
}

function _escHtml(s) {
  return String(s == null ? '' : s).replace(/[&<>"']/g, (c) => (
    { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]
  ));
}

// ── Saved Filters (localStorage) ────────────────────────────────────────────
// Enterprise UI/UX Standardization Phase 3 — generic, reusable across any
// procFilterBarHtml() screen, modeled directly on the recent/favorite-
// searches pattern above (capped, JSON, fail-soft, keyed so multiple
// screens each keep their own presets under one shared mechanism instead of
// inventing their own storage shape). Reference implementation applied to
// Procurement Requisitions only this phase — see the Guide for rollout to
// other screens.
const SAVED_FILTERS_MAX = 10;
function _sfKey(screenKey) { return `ufcl_saved_filters_${screenKey}`; }
function loadSavedFilters(screenKey) {
  try { return JSON.parse(localStorage.getItem(_sfKey(screenKey)) || '[]'); } catch { return []; }
}
function saveFilterPreset(screenKey, name, filterValues) {
  const n = (name || '').trim();
  if (!n) return loadSavedFilters(screenKey);
  try {
    const entry = { id: `${Date.now()}`, name: n, filterValues, savedAt: new Date().toISOString() };
    const next = [entry, ...loadSavedFilters(screenKey).filter((f) => f.name.toLowerCase() !== n.toLowerCase())].slice(0, SAVED_FILTERS_MAX);
    localStorage.setItem(_sfKey(screenKey), JSON.stringify(next));
    return next;
  } catch { return loadSavedFilters(screenKey); }
}
function removeFilterPreset(screenKey, id) {
  try {
    const next = loadSavedFilters(screenKey).filter((f) => f.id !== id);
    localStorage.setItem(_sfKey(screenKey), JSON.stringify(next));
    return next;
  } catch { return loadSavedFilters(screenKey); }
}
function savedFiltersBarHtml(screenKey) {
  const presets = loadSavedFilters(screenKey);
  if (!presets.length) return `<div class="frow" style="align-items:center;gap:.5rem;margin-bottom:.75rem" id="sf-bar-${screenKey}">
    <button type="button" class="bs1" id="sf-save-${screenKey}" style="font-size:11px;padding:3px 10px"><i class="ti ti-bookmark-plus"></i>Save current filters</button>
  </div>`;
  return `<div class="frow" style="align-items:center;gap:.4rem;margin-bottom:.75rem;flex-wrap:wrap" id="sf-bar-${screenKey}">
    <span style="font-size:11px;color:var(--t3);font-weight:600;text-transform:uppercase;letter-spacing:.04em">Saved:</span>
    ${presets.map((p) => `<button type="button" class="bs1 sf-apply" data-id="${p.id}" style="font-size:11px;padding:3px 8px">${_escHtml(p.name)}<i class="ti ti-x sf-remove" data-id="${p.id}" role="button" tabindex="0" aria-label="Remove ${_escHtml(p.name)} filter preset" style="margin-left:5px;opacity:.5"></i></button>`).join('')}
    <button type="button" class="bs1" id="sf-save-${screenKey}" style="font-size:11px;padding:3px 10px"><i class="ti ti-bookmark-plus"></i>Save current</button>
  </div>`;
}
// Wires a rendered savedFiltersBarHtml(screenKey) — apply/remove/save. `getValues`
// reads the current filter control values; `setValues` applies a preset's
// saved values back onto the controls and re-runs the screen's own filter/
// render logic (the caller's `onApply`, e.g. `() => renderRows(currentFiltered())`).
function wireSavedFiltersBar(screenKey, { getValues, setValues, onApply }) {
  const bar = $(`sf-bar-${screenKey}`);
  if (!bar) return;
  bar.querySelectorAll('.sf-apply').forEach((btn) => {
    btn.onclick = (e) => {
      if (e.target.closest('.sf-remove')) return;
      const preset = loadSavedFilters(screenKey).find((p) => p.id === btn.dataset.id);
      if (preset) { setValues(preset.filterValues); onApply(); }
    };
  });
  bar.querySelectorAll('.sf-remove').forEach((icon) => {
    icon.onclick = (e) => {
      e.stopPropagation();
      removeFilterPreset(screenKey, icon.dataset.id);
      bar.outerHTML = savedFiltersBarHtml(screenKey);
      wireSavedFiltersBar(screenKey, { getValues, setValues, onApply });
    };
  });
  const saveBtn = $(`sf-save-${screenKey}`);
  if (saveBtn) saveBtn.onclick = () => {
    confirmAction({
      title: 'Save Current Filters',
      message: 'Give this filter combination a name so you can reapply it later.',
      confirmLabel: 'Save',
      icon: 'ti-bookmark-plus',
      extraHtml: `<div class="fg"><label>Preset name</label><input id="sf-name" type="text" placeholder="e.g. My pending items" maxlength="40"></div>`,
      onConfirm: async () => {
        const name = $('sf-name')?.value?.trim();
        if (!name) { showOverlayError('A name is required.'); return; }
        saveFilterPreset(screenKey, name, getValues());
        closeOverlay();
        showToast('Filter preset saved.', 'success');
        const newBar = savedFiltersBarHtml(screenKey);
        const el = $(`sf-bar-${screenKey}`);
        if (el) { el.outerHTML = newBar; wireSavedFiltersBar(screenKey, { getValues, setValues, onApply }); }
      },
    });
  };
}

// ── Recently Viewed (localStorage) ──────────────────────────────────────────
// Enterprise UI/UX Standardization Phase 3 — same capped/JSON/fail-soft
// architecture as Saved Filters and the Global Search recent-searches
// pattern above. Reference implementation wired into Requisitions only —
// call pushRecentlyViewed() from a detail-overlay open, render
// recentlyViewedWidgetHtml() on the corresponding list screen.
const RECENTLY_VIEWED_MAX = 8;
function _rvKey(recordType) { return `ufcl_recently_viewed_${recordType}`; }
function loadRecentlyViewed(recordType) {
  try { return JSON.parse(localStorage.getItem(_rvKey(recordType)) || '[]'); } catch { return []; }
}
function pushRecentlyViewed(recordType, id, label) {
  try {
    const entry = { id, label, viewedAt: new Date().toISOString() };
    const next = [entry, ...loadRecentlyViewed(recordType).filter((r) => r.id !== id)].slice(0, RECENTLY_VIEWED_MAX);
    localStorage.setItem(_rvKey(recordType), JSON.stringify(next));
    return next;
  } catch { return loadRecentlyViewed(recordType); }
}
function recentlyViewedWidgetHtml(recordType, title = 'Recently Viewed') {
  const items = loadRecentlyViewed(recordType);
  if (!items.length) return '';
  return `<div class="card" style="margin-bottom:1.25rem" id="rv-widget-${recordType}">
    <h3 style="margin:0 0 .5rem;font-size:13px"><i class="ti ti-history"></i> ${title}</h3>
    <div class="frow" style="flex-wrap:wrap;gap:.4rem">
      ${items.map((it) => `<button type="button" class="bs1 rv-item" data-id="${it.id}" style="font-size:11px;padding:3px 10px">${_escHtml(it.label)}</button>`).join('')}
    </div>
  </div>`;
}
function wireRecentlyViewedWidget(recordType, onOpen) {
  const widget = $(`rv-widget-${recordType}`);
  if (!widget) return;
  widget.querySelectorAll('.rv-item').forEach((btn) => {
    btn.onclick = () => onOpen(btn.dataset.id);
  });
}

function _searchStatusClass(status) {
  const s = String(status || '').toLowerCase();
  if (['active', 'approved', 'confirmed', 'completed', 'delivered', 'quality_checked'].some((w) => s.includes(w))) return 'bg';
  if (['rejected', 'cancelled', 'inactive', 'denied', 'failed'].some((w) => s.includes(w))) return 'br';
  if (['pending', 'in progress', 'partial', 'in_transit'].some((w) => s.includes(w))) return 'ba';
  return 'bp';
}

function _searchTargetPage(r) {
  if (r.module === 'reports') return SEARCH_REPORT_PAGE[r.id];
  // daily_logs has no single destination page — Timber/Poles production logs
  // have their own page, everything else (harvest, or no workshop) lands on
  // Daily Harvest. Needs the full cached result (workshop_type), not just id.
  if (r.module === 'production') {
    return r.workshop_type === 'Timber' ? 'daily-timber'
      : r.workshop_type === 'Poles' ? 'daily-poles'
      : 'daily-harvest';
  }
  return SEARCH_MODULE_PAGE[r.module];
}

function _searchResultRow(r) {
  const targetPage = _searchTargetPage(r);
  const label = SEARCH_MODULE_LABEL[r.module] || r.module;
  const statusHtml = r.status
    ? `<span class="badge ${_searchStatusClass(r.status)}" style="margin-left:8px">${_escHtml(r.status)}</span>`
    : '';
  const dateStr = r.created_at ? new Date(r.created_at).toLocaleDateString() : '';
  return `<div class="nitem" data-gs-module="${r.module}" data-gs-id="${_escHtml(r.id)}"
      style="cursor:${targetPage ? 'pointer' : 'default'}" ${targetPage ? `title="Open in ${_escHtml(label)}"` : ''}>
    <div class="ndot nd-blue" style="margin-top:5px;flex-shrink:0"></div>
    <div style="flex:1;min-width:0">
      <div class="ntxt"><strong>${_escHtml(r.title)}</strong>${statusHtml}
        ${r.subtitle ? `<div style="color:var(--t2);margin-top:2px">${_escHtml(r.subtitle)}</div>` : ''}
        ${r.description ? `<div style="color:var(--t3);margin-top:1px;font-size:12px">${_escHtml(r.description)}</div>` : ''}
      </div>
      <div class="ntime">${dateStr}</div>
    </div>
    ${targetPage ? '<i class="ti ti-chevron-right" style="color:var(--t4);flex-shrink:0"></i>' : ''}
  </div>`;
}

// Read-only fallback for modules with no general "view/edit this record"
// control (see SEARCH_MODULE_EDIT_SELECTOR/SEARCH_MODULE_PAGE_ONLY above) —
// reuses the app's existing modal system rather than guessing at a screen
// that isn't there, same tradeoff the mobile app's SearchResultDetailSheet makes.
function _openSearchResultOverlay(r) {
  const label = SEARCH_MODULE_LABEL[r.module] || r.module;
  const statusHtml = r.status
    ? `<span class="badge ${_searchStatusClass(r.status)}" style="margin-left:8px">${_escHtml(r.status)}</span>` : '';
  const dateStr = r.created_at ? new Date(r.created_at).toLocaleDateString() : '';
  openOverlay(
    _escHtml(r.title || label),
    label,
    `
      ${statusHtml ? `<div style="margin-bottom:8px">${statusHtml}</div>` : ''}
      ${r.subtitle ? `<div style="color:var(--t2);margin-bottom:6px">${_escHtml(r.subtitle)}</div>` : ''}
      ${r.description ? `<div style="color:var(--t3);font-size:13px;margin-bottom:6px">${_escHtml(r.description)}</div>` : ''}
      ${dateStr ? `<div style="color:var(--t4);font-size:12px">${dateStr}</div>` : ''}
      <div style="margin-top:12px;padding-top:10px;border-top:1px solid var(--border);color:var(--t3);font-size:12px;font-style:italic">
        A dedicated view for this record isn't available yet — this is a preview of what search already knows.
      </div>
    `
  );
}

// 'production' spans three different pages/edit-button classes by workshop
// type — same daily_logs table, no single selector like the other tier-1
// modules, so it needs its own per-row resolution instead of a flat map entry.
function _productionEditSelector(r) {
  return r.workshop_type === 'Timber' ? `.dl-edit[data-id="${r.id}"]`
    : r.workshop_type === 'Poles' ? `.pl-edit[data-id="${r.id}"]`
    : `.hv-edit[data-id="${r.id}"]`;
}

function _wireSearchResultClicks(wrap) {
  wrap.querySelectorAll('[data-gs-module]').forEach((el) => {
    const mod = el.dataset.gsModule;
    const id  = el.dataset.gsId;
    // Look up the full cached result first — production's routing/edit-button
    // both depend on workshop_type, which only exists on the cached object,
    // never on the DOM's data attributes.
    const cached = (_SEARCH.lastResults || []).find((x) => String(x.module) === mod && String(x.id) === id);
    const r = cached || { module: mod, id };
    const target = _searchTargetPage(r);
    if (!target) return;
    el.onclick = () => {
      trackSearchEvent('result_selected', { module: mod, id });
      if (_SEARCH.q.trim()) _gsSaveRecent(_SEARCH.q.trim());
      const editSelector = mod === 'production' ? _productionEditSelector(r)
        : SEARCH_MODULE_EDIT_SELECTOR[mod] ? SEARCH_MODULE_EDIT_SELECTOR[mod](id)
        : null;
      if (editSelector) {
        showPage(target);
        // Let the target page's own renderX() finish painting its rows before
        // looking for this specific record's Edit button.
        setTimeout(() => {
          const btn = document.querySelector(editSelector);
          if (btn) btn.click();
        }, 250);
      } else if (SEARCH_MODULE_PAGE_ONLY.has(mod)) {
        showPage(target);
      } else {
        _openSearchResultOverlay(cached || { module: mod, id, title: id, subtitle: null, description: null, status: null, created_at: null });
      }
    };
  });
}

function _renderSearchOverview(results, moduleCounts) {
  const byModule = new Map();
  results.forEach((r) => {
    if (!byModule.has(r.module)) byModule.set(r.module, []);
    byModule.get(r.module).push(r);
  });

  return Array.from(byModule.entries()).map(([mod, items]) => {
    const total = moduleCounts[mod] ?? items.length;
    const label = SEARCH_MODULE_LABEL[mod] || mod;
    const icon  = SEARCH_MODULE_ICON[mod] || 'ti-file-text';
    const rowsHtml = items.map((r) => _searchResultRow(r)).join('');
    const seeAll = total > items.length
      ? `<button class="nchip" data-seeall="${mod}" style="margin-top:8px">See all ${total} in ${_escHtml(label)} →</button>`
      : '';
    return `<div class="card" style="margin-bottom:10px;padding:0">
      <div style="display:flex;align-items:center;gap:8px;padding:.75rem 1rem;border-bottom:1px solid var(--border);font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--t3)">
        <i class="ti ${icon}"></i>${_escHtml(label)}
      </div>
      ${rowsHtml}
      ${seeAll ? `<div style="padding:0 1rem .75rem">${seeAll}</div>` : ''}
    </div>`;
  }).join('');
}

function _renderSearchDeep(results, total) {
  const mod   = _SEARCH.filters.module;
  const label = SEARCH_MODULE_LABEL[mod] || mod;
  const limit = 20;
  const page  = _SEARCH.page;
  const start = total === 0 ? 0 : page * limit + 1;
  const end   = Math.min(page * limit + results.length, total);
  const hasNext = end < total;
  const rowsHtml = results.map((r) => _searchResultRow(r)).join('');
  const pagerLabel = `${start}–${end} of ${total}`;

  return `
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px">
      <button class="bs1" id="gs-back" style="font-size:12px"><i class="ti ti-arrow-left"></i> All results</button>
      <span style="font-size:12px;color:var(--t3)">${_escHtml(label)} — ${pagerLabel}</span>
    </div>
    <div class="card" style="padding:0">${rowsHtml}</div>
    <div class="npager">
      <button class="nchip" id="gs-prev" ${page === 0 ? 'disabled' : ''}>← Prev</button>
      <span style="font-size:12px;color:var(--t3)">${pagerLabel}</span>
      <button class="nchip" id="gs-next" ${!hasNext ? 'disabled' : ''}>Next →</button>
    </div>`;
}

// ── Landing state: favorites, recent searches, suggested modules ──────────────
// Shown only in overview scope with no query yet — context/browse mode (a
// module already pinned, see _SEARCH.filters.module) skips straight to real
// results (possibly a "browse this module" empty-query request) instead.

function _gsIsFavorited() {
  const q = _SEARCH.q.trim();
  return q.length > 0 && _gsLoadFavorites().some((f) => f.query.toLowerCase() === q.toLowerCase());
}

function _gsPlaceholder() {
  const mod = _SEARCH.filters.module;
  return mod ? `Search ${SEARCH_MODULE_LABEL[mod] || mod}…` : 'Search everywhere…';
}

function _gsScopeToggleHtml() {
  if (!_SEARCH.contextModule) return '';
  const ctxLabel = SEARCH_MODULE_LABEL[_SEARCH.contextModule] || _SEARCH.contextModule;
  const isContext = _SEARCH.scope === 'context';
  return `
    <div style="display:flex;gap:8px;margin-bottom:12px">
      <button class="nchip ${isContext ? 'active' : ''}" id="gs-scope-context">Search ${_escHtml(ctxLabel)}</button>
      <button class="nchip ${!isContext ? 'active' : ''}" id="gs-scope-everywhere">Search Everywhere</button>
    </div>`;
}

function _gsLandingHtml() {
  const recent = _gsLoadRecent();
  const favorites = _gsLoadFavorites();
  const pages = STORAGE.pages || [];
  const hasProductionPage = ['daily-harvest', 'daily-timber', 'daily-poles'].some((p) => pages.includes(p));
  const allowedModules = Object.keys(SEARCH_MODULE_LABEL)
    .filter((mod) => mod !== 'reports')
    .filter((mod) => mod === 'production' ? hasProductionPage : pages.includes(SEARCH_MODULE_PAGE[mod]));

  const favHtml = favorites.length ? `
    <div style="font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--t3);padding:12px 16px 6px">Favorite searches</div>
    ${favorites.map((f) => `
      <div class="nitem" style="cursor:pointer" data-gs-fav="${f.id}">
        <i class="ti ti-star-filled" style="color:var(--amber);margin-top:3px;flex-shrink:0"></i>
        <div style="flex:1;min-width:0"><div class="ntxt">${_escHtml(f.query)}</div>${f.filters && f.filters.module ? `<div class="ntime">${_escHtml(SEARCH_MODULE_LABEL[f.filters.module] || f.filters.module)}</div>` : ''}</div>
        <button data-gs-fav-remove="${f.id}" style="background:none;border:none;cursor:pointer;color:var(--t3);flex-shrink:0"><i class="ti ti-x"></i></button>
      </div>`).join('')}` : '';

  const recentHtml = recent.length ? `
    <div style="display:flex;align-items:center;justify-content:space-between;padding:12px 16px 6px">
      <span style="font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--t3)">Recent searches</span>
      <button class="bs1" id="gs-clear-recent" style="font-size:11px;padding:2px 8px">Clear</button>
    </div>
    ${recent.map((q) => `
      <div class="nitem" style="cursor:pointer" data-gs-recent="${_escHtml(q)}">
        <i class="ti ti-clock-hour-4" style="color:var(--t4);margin-top:3px;flex-shrink:0"></i>
        <div style="flex:1;min-width:0" class="ntxt">${_escHtml(q)}</div>
        <button data-gs-recent-remove="${_escHtml(q)}" style="background:none;border:none;cursor:pointer;color:var(--t3);flex-shrink:0"><i class="ti ti-x"></i></button>
      </div>`).join('')}` : '';

  const moduleHtml = `
    <div style="font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.05em;color:var(--t3);padding:12px 16px 8px">Browse a module</div>
    <div style="display:flex;flex-wrap:wrap;gap:8px;padding:0 16px 16px">
      ${allowedModules.map((mod) => `
        <button class="nchip" data-gs-browse="${mod}"><i class="ti ${SEARCH_MODULE_ICON[mod]}" style="margin-right:4px"></i>${_escHtml(SEARCH_MODULE_LABEL[mod])}</button>
      `).join('')}
    </div>`;

  return `<div class="card" style="padding:0">${favHtml}${recentHtml}${moduleHtml}</div>`;
}

function _gsWireLanding(wrap) {
  wrap.querySelectorAll('[data-gs-recent]').forEach((el) => {
    el.onclick = () => {
      _SEARCH.q = el.dataset.gsRecent;
      _SEARCH.page = 0;
      renderGlobalSearch();
    };
  });
  wrap.querySelectorAll('[data-gs-recent-remove]').forEach((el) => {
    el.onclick = (e) => { e.stopPropagation(); _gsRemoveRecent(el.dataset.gsRecentRemove); _loadSearchResults(); };
  });
  const clearRecentBtn = $('gs-clear-recent');
  if (clearRecentBtn) clearRecentBtn.onclick = () => { _gsClearRecent(); _loadSearchResults(); };

  wrap.querySelectorAll('[data-gs-fav]').forEach((el) => {
    el.onclick = () => {
      const fav = _gsLoadFavorites().find((f) => f.id === el.dataset.gsFav);
      if (!fav) return;
      _SEARCH.q = fav.query;
      _SEARCH.filters = { ...fav.filters };
      _SEARCH.mode = fav.filters.module ? 'deep' : 'overview';
      _SEARCH.page = 0;
      renderGlobalSearch();
    };
  });
  wrap.querySelectorAll('[data-gs-fav-remove]').forEach((el) => {
    el.onclick = (e) => { e.stopPropagation(); _gsRemoveFavorite(el.dataset.gsFavRemove); _loadSearchResults(); };
  });

  wrap.querySelectorAll('[data-gs-browse]').forEach((el) => {
    el.onclick = () => {
      _SEARCH.filters.module = el.dataset.gsBrowse;
      _SEARCH.mode = 'deep';
      _SEARCH.q = '';
      _SEARCH.page = 0;
      renderGlobalSearch();
    };
  });
}

async function _loadSearchResults() {
  const wrap = $('gs-results');
  if (!wrap) return;

  const trimmed = _SEARCH.q.trim();

  if (_SEARCH.mode === 'overview' && trimmed.length < 2) {
    wrap.innerHTML = _gsLandingHtml();
    _gsWireLanding(wrap);
    return;
  }

  wrap.innerHTML = `<div style="text-align:center;padding:2rem;color:var(--t3);font-size:13px">Searching…</div>`;

  const res = await UFCL.globalSearch(STORAGE.user.id, {
    q:          _SEARCH.q.trim(),
    module:     _SEARCH.filters.module     || undefined,
    status:     _SEARCH.filters.status     || undefined,
    department: _SEARCH.filters.department || undefined,
    createdBy:  _SEARCH.filters.createdBy  || undefined,
    fromDate:   _SEARCH.filters.fromDate   || undefined,
    toDate:     _SEARCH.filters.toDate     || undefined,
    sort:       _SEARCH.filters.sort       || undefined,
    page:       _SEARCH.page,
    limit:      20,
  });

  if (!res.ok) {
    wrap.innerHTML = `<div style="text-align:center;padding:2rem;color:var(--red);font-size:13px">Search failed: ${_escHtml(res.error || 'Error')}</div>`;
    return;
  }

  const results      = res.results      || [];
  const total        = res.total        || 0;
  const moduleCounts = res.moduleCounts || {};
  _SEARCH.lastResults = results;

  if (results.length === 0) {
    const emptyMsg = trimmed
      ? `No results for "${_escHtml(trimmed)}".`
      : `No ${_escHtml(SEARCH_MODULE_LABEL[_SEARCH.filters.module] || '')} records yet.`;
    wrap.innerHTML = `<div style="text-align:center;padding:3rem 1rem;color:var(--t3);font-size:13px">
      <i class="ti ti-mood-empty" style="font-size:28px;display:block;margin-bottom:.5rem;opacity:.3"></i>
      ${emptyMsg}
    </div>`;
    return;
  }

  wrap.innerHTML = _SEARCH.mode === 'deep'
    ? _renderSearchDeep(results, total)
    : _renderSearchOverview(results, moduleCounts);

  _wireSearchResultClicks(wrap);

  if (_SEARCH.mode === 'deep') {
    const backBtn = $('gs-back');
    // No "back to overview" when this IS the context-search base state (the
    // scope toggle above is the escape hatch there) — only relevant when the
    // user drilled into a module from the Everywhere grouped overview.
    if (backBtn) show(backBtn, !(_SEARCH.contextModule && _SEARCH.filters.module === _SEARCH.contextModule));
    if (backBtn) backBtn.onclick = () => {
      _SEARCH.mode = 'overview';
      _SEARCH.filters.module = undefined;
      _SEARCH.page = 0;
      _loadSearchResults();
    };
    const prevBtn = $('gs-prev');
    const nextBtn = $('gs-next');
    if (prevBtn) prevBtn.onclick = () => { _SEARCH.page = Math.max(0, _SEARCH.page - 1); _loadSearchResults(); };
    if (nextBtn) nextBtn.onclick = () => { _SEARCH.page = _SEARCH.page + 1; _loadSearchResults(); };
  } else {
    wrap.querySelectorAll('[data-seeall]').forEach((btn) => {
      btn.onclick = () => {
        _SEARCH.mode = 'deep';
        _SEARCH.filters.module = btn.dataset.seeall;
        _SEARCH.page = 0;
        _loadSearchResults();
      };
    });
  }
}

// contextModule is only passed the moment search is opened (icon click / Ctrl+K)
// — omit it on internal re-renders (scope toggle, favorites, clear filters,
// browse-a-module) so they don't clobber whatever scope the user is already in.
async function renderGlobalSearch(contextModule) {
  if (contextModule !== undefined) {
    _SEARCH.contextModule = contextModule || null;
    _SEARCH.scope = contextModule ? 'context' : 'everywhere';
    _SEARCH.mode = contextModule ? 'deep' : 'overview';
    _SEARCH.filters = contextModule ? { module: contextModule } : {};
    _SEARCH.q = '';
    _SEARCH.page = 0;
  }

  $('page-search').innerHTML = `
    <div class="ptitle">Global Search</div>
    <div class="psub">Search across every module you have access to — sales orders, deliveries, customers, vehicles, machines, and more.</div>

    ${_gsScopeToggleHtml()}

    <div class="card" style="margin-bottom:12px">
      <div style="display:flex;flex-wrap:wrap;gap:10px;align-items:flex-end">
        <div class="fg" style="min-width:260px;flex:2 1 260px">
          <label>Search</label>
          <div style="display:flex;gap:6px">
            <input type="text" id="gs-q" placeholder="${_escHtml(_gsPlaceholder())}" value="${_escHtml(_SEARCH.q)}" style="flex:1">
            <button id="gs-star" title="${_gsIsFavorited() ? 'Remove favorite' : 'Save as favorite'}"
              style="border:1px solid var(--border2);border-radius:var(--r-sm);background:var(--surf);width:34px;cursor:pointer;display:${_SEARCH.q.trim() ? 'block' : 'none'}">
              <i class="ti ${_gsIsFavorited() ? 'ti-star-filled' : 'ti-star'}" style="color:${_gsIsFavorited() ? 'var(--amber)' : 'var(--t3)'}"></i>
            </button>
          </div>
        </div>
        <div class="fg" style="min-width:140px;flex:0 1 auto">
          <label>Status</label>
          <input type="text" id="gs-status" placeholder="e.g. Pending" value="${_escHtml(_SEARCH.filters.status || '')}">
        </div>
        <div class="fg" style="min-width:140px;flex:0 1 auto">
          <label>Department</label>
          <input type="text" id="gs-dept" placeholder="e.g. Logistics" value="${_escHtml(_SEARCH.filters.department || '')}">
        </div>
        <div class="fg" style="min-width:140px;flex:0 1 auto">
          <label>Created by</label>
          <input type="text" id="gs-createdby" placeholder="Staff name" value="${_escHtml(_SEARCH.filters.createdBy || '')}">
        </div>
        <div class="fg" style="min-width:115px;flex:0 1 auto">
          <label>From date</label>
          <input type="date" id="gs-from" value="${_escHtml(_SEARCH.filters.fromDate || '')}">
        </div>
        <div class="fg" style="min-width:115px;flex:0 1 auto">
          <label>To date</label>
          <input type="date" id="gs-to" value="${_escHtml(_SEARCH.filters.toDate || '')}">
        </div>
        <div class="fg" style="min-width:135px;flex:0 1 auto">
          <label>Sort</label>
          <select id="gs-sort">
            <option value="newest" ${(!_SEARCH.filters.sort || _SEARCH.filters.sort === 'newest') ? 'selected' : ''}>Newest</option>
            <option value="oldest" ${_SEARCH.filters.sort === 'oldest' ? 'selected' : ''}>Oldest</option>
            <option value="relevance" ${_SEARCH.filters.sort === 'relevance' ? 'selected' : ''}>Relevance</option>
            <option value="alphabetical" ${_SEARCH.filters.sort === 'alphabetical' ? 'selected' : ''}>Alphabetical</option>
          </select>
        </div>
        <button class="bs1" id="gs-clear" style="height:34px">Clear filters</button>
      </div>
    </div>

    <div id="gs-results"></div>`;

  const qEl = $('gs-q');
  qEl.focus();
  qEl.selectionStart = qEl.selectionEnd = qEl.value.length;

  qEl.oninput = () => {
    clearTimeout(_gsDebounce);
    const val = qEl.value;
    _gsDebounce = setTimeout(() => {
      _SEARCH.q = val.trim();
      _SEARCH.page = 0;
      // Everywhere scope: typing always starts a fresh grouped search. Context
      // scope: keep the module pinned — typing just narrows within it.
      if (_SEARCH.scope === 'everywhere') {
        _SEARCH.mode = 'overview';
        _SEARCH.filters.module = undefined;
      }
      trackSearchEvent('search_executed', { module: _SEARCH.filters.module || 'everywhere' });
      const starBtn = $('gs-star');
      if (starBtn) {
        starBtn.style.display = _SEARCH.q ? 'block' : 'none';
        starBtn.title = _gsIsFavorited() ? 'Remove favorite' : 'Save as favorite';
        const icon = starBtn.querySelector('i');
        icon.className = `ti ${_gsIsFavorited() ? 'ti-star-filled' : 'ti-star'}`;
        icon.style.color = _gsIsFavorited() ? 'var(--amber)' : 'var(--t3)';
      }
      _loadSearchResults();
    }, 300);
  };

  $('gs-star').onclick = () => {
    const q = _SEARCH.q.trim();
    if (!q) return;
    if (_gsIsFavorited()) {
      const match = _gsLoadFavorites().find((f) => f.query.toLowerCase() === q.toLowerCase());
      if (match) _gsRemoveFavorite(match.id);
    } else {
      _gsSaveFavorite(q, { ..._SEARCH.filters });
    }
    renderGlobalSearch();
  };

  const scopeContextBtn = $('gs-scope-context');
  if (scopeContextBtn) scopeContextBtn.onclick = () => {
    _SEARCH.scope = 'context';
    _SEARCH.mode = 'deep';
    _SEARCH.filters = { module: _SEARCH.contextModule };
    _SEARCH.q = '';
    _SEARCH.page = 0;
    renderGlobalSearch();
  };
  const scopeEverywhereBtn = $('gs-scope-everywhere');
  if (scopeEverywhereBtn) scopeEverywhereBtn.onclick = () => {
    _SEARCH.scope = 'everywhere';
    _SEARCH.mode = 'overview';
    _SEARCH.filters = {};
    _SEARCH.q = '';
    _SEARCH.page = 0;
    renderGlobalSearch();
  };

  ['gs-status', 'gs-dept', 'gs-createdby'].forEach((id) => {
    const key = { 'gs-status': 'status', 'gs-dept': 'department', 'gs-createdby': 'createdBy' }[id];
    $(id).oninput = () => {
      clearTimeout(_gsDebounce);
      const val = $(id).value;
      _gsDebounce = setTimeout(() => {
        _SEARCH.filters[key] = val.trim() || undefined;
        _SEARCH.page = 0;
        trackSearchEvent('filter_applied', { [key]: _SEARCH.filters[key] });
        _loadSearchResults();
      }, 300);
    };
  });

  $('gs-from').onchange = () => { _SEARCH.filters.fromDate = $('gs-from').value || undefined; _SEARCH.page = 0; _loadSearchResults(); };
  $('gs-to').onchange   = () => { _SEARCH.filters.toDate   = $('gs-to').value   || undefined; _SEARCH.page = 0; _loadSearchResults(); };
  $('gs-sort').onchange = () => { _SEARCH.filters.sort     = $('gs-sort').value || undefined; _loadSearchResults(); };

  $('gs-clear').onclick = () => {
    _SEARCH.filters = _SEARCH.scope === 'context' ? { module: _SEARCH.contextModule } : {};
    _SEARCH.page = 0;
    renderGlobalSearch();
  };

  await _loadSearchResults();
}

async function renderAudit(filters = {}) {
  const res = await UFCL.auditList(STORAGE.user.id, filters);
  if (!res.ok) return renderDenied('audit', res.error);
  const rows      = res.rows      || [];
  const modules   = res.modules   || [];
  const workshops = res.workshops || [];
  const total     = res.total ?? rows.length;
  const page      = res.page ?? 0;
  const pageSize  = res.pageSize ?? 100;
  const sortBy    = filters.sortBy  || 'created_at';
  const sortDir   = filters.sortDir || 'desc';

  const sel = (id, val, opts) =>
    `<select id="${id}" style="height:32px;font-size:12px">${
      opts.map(o => `<option value="${o}" ${val===o?'selected':''}>${o}</option>`).join('')
    }</select>`;

  const moduleOpts    = ['All', ...modules];
  const typeOpts      = ['All','login','login_failed','login_denied','create','update','delete',
                          'submit','approve','reject','cancel','issue_po','receive_goods','match_invoice','approve_payment',
                          // Phase 3B: 'blacklist'/'unblacklist' are historical values written before
                          // procurementSupplierToggleBlacklist was rewritten to delegate to
                          // procurementSupplierSetStatus; 'status_change' is what it writes now;
                          // 'delete_blocked' logs a rejected delete attempt. All were previously
                          // write-only/unfilterable in this dropdown — see SUPPLIER_VENDOR_PHASE3B docs.
                          'blacklist','unblacklist','status_change','delete_blocked'];
  const roleOpts      = ['All','admin','ceo','operations','sales','sales-staff','finance',
                          'logistics','logistics-officer','supervisor','storekeeper',
                          'storekeeper-assistant','mechanician','harvesting-leader',
                          'sawmill-leader','poles-leader','vat-leader',
                          'harvesting-supervisor','sawmill-supervisor',
                          'poles-supervisor','vat-supervisor',
                          'procurement-officer','procurement-manager','department-manager'];

  const typeBadge = t => {
    if (!t) return '<span style="color:var(--t3);font-size:10px">—</span>';
    const cls = {login:'bg',login_failed:'br',login_denied:'ba',create:'bp',update:'ba',delete:'br',
      blacklist:'br',unblacklist:'bg',status_change:'ba',delete_blocked:'br'}[t] || 'bp';
    return `<span class="badge ${cls}" style="font-size:10px">${t.replace('_',' ')}</span>`;
  };

  $('page-audit').innerHTML = `
    <div class="ptitle">Audit Trail</div>
    <div class="psub">Complete record of every action, login attempt, and data change across desktop and mobile.</div>

    <div class="card" style="margin-bottom:12px">
      <div style="display:flex;flex-wrap:wrap;gap:10px;align-items:flex-end">
        <div class="fg" style="min-width:120px;flex:0 1 auto">
          <label style="font-size:11px">Module</label>
          ${sel('af-module', filters.module||'All', moduleOpts)}
        </div>
        <div class="fg" style="min-width:130px;flex:0 1 auto">
          <label style="font-size:11px">Action type</label>
          ${sel('af-type', filters.actionType||'All', typeOpts)}
        </div>
        <div class="fg" style="min-width:150px;flex:0 1 auto">
          <label style="font-size:11px">Role</label>
          ${sel('af-role', filters.roleFilter||'All', roleOpts)}
        </div>
        ${workshops.length ? `<div class="fg" style="min-width:150px;flex:0 1 auto">
          <label style="font-size:11px">Workshop</label>
          <select id="af-workshop" style="height:32px;font-size:12px">
            <option value="All" ${!filters.workshopFilter||filters.workshopFilter==='All'?'selected':''}>All</option>
            ${workshops.map(w => `<option value="${w.id}" ${String(filters.workshopFilter)===String(w.id)?'selected':''}>${w.name}</option>`).join('')}
          </select>
        </div>` : ''}
        <div class="fg" style="min-width:115px;flex:0 1 auto">
          <label style="font-size:11px">From date</label>
          <input type="date" id="af-from" value="${filters.fromDate||''}" style="height:32px;font-size:12px">
        </div>
        <div class="fg" style="min-width:115px;flex:0 1 auto">
          <label style="font-size:11px">To date</label>
          <input type="date" id="af-to" value="${filters.toDate||''}" style="height:32px;font-size:12px">
        </div>
        <div class="fg" style="min-width:180px;flex:1 1 180px">
          <label style="font-size:11px">Search user / action</label>
          <input type="text" id="af-search" value="${filters.search||''}" placeholder="type to filter…" style="height:32px;font-size:12px">
        </div>
        <button class="bp1" id="af-apply" style="height:32px;padding:0 14px;font-size:12px"><i class="ti ti-filter"></i>Apply</button>
        <button class="bs1" id="af-clear"  style="height:32px;padding:0 10px;font-size:12px">Clear</button>
        <button class="bs1" id="af-export" style="height:32px;padding:0 10px;font-size:12px"><i class="ti ti-file-spreadsheet"></i>Export Excel</button>
      </div>
      <div style="margin-top:8px;font-size:12px;color:var(--t3);display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px">
        <span>Showing <strong>${rows.length}</strong> of <strong>${total}</strong> record${total!==1?'s':''} (page ${page+1} of ${Math.max(1, Math.ceil(total/pageSize))}) · click a row to see before/after values</span>
        <span style="display:flex;gap:6px">
          <button class="bs1" id="af-prev" ${page<=0?'disabled':''} style="height:26px;padding:0 10px;font-size:11px">&larr; Prev</button>
          <button class="bs1" id="af-next" ${(page+1)*pageSize>=total?'disabled':''} style="height:26px;padding:0 10px;font-size:11px">Next &rarr;</button>
        </span>
      </div>
    </div>

    <div class="card">
      <div class="tw">
        <table class="dt" id="audit-table">
          <thead>
            <tr>
              <th style="width:140px;cursor:pointer" data-sort-col="created_at">Time ${sortBy==='created_at'?(sortDir==='asc'?'▲':'▼'):''}</th>
              <th>User</th>
              <th style="width:110px;cursor:pointer" data-sort-col="role">Role ${sortBy==='role'?(sortDir==='asc'?'▲':'▼'):''}</th>
              <th style="width:85px;cursor:pointer" data-sort-col="module">Module ${sortBy==='module'?(sortDir==='asc'?'▲':'▼'):''}</th>
              <th style="width:115px;cursor:pointer" data-sort-col="action_type">Type ${sortBy==='action_type'?(sortDir==='asc'?'▲':'▼'):''}</th>
              <th>Action</th>
              ${workshops.length ? '<th style="width:100px">Workshop</th>' : ''}
              <th style="width:115px">IP Address</th>
            </tr>
          </thead>
          <tbody>
            ${rows.map((r, i) => {
              const displayName = r.full_name || r.user_name || r.username || '—';
              const hasDetail = r.before_values || r.after_values || r.reason;
              return `<tr class="audit-row" data-idx="${i}" style="cursor:${hasDetail?'pointer':'default'}${hasDetail?' background-color:transparent':''}" title="${hasDetail?'Click to expand details':''}">
                <td style="font-family:var(--fm);font-size:11px;color:var(--t3);white-space:nowrap">${r.time}</td>
                <td>
                  <div style="font-size:13px">${displayName}</div>
                  ${r.username && r.username !== displayName ? `<div style="font-size:10px;color:var(--t3)">@${r.username}</div>` : ''}
                </td>
                <td><span class="badge bp" style="font-size:10px">${r.role||'—'}</span></td>
                <td style="font-size:11px;color:var(--t3)">${r.module||'—'}</td>
                <td>${typeBadge(r.action_type)}</td>
                <td style="font-size:12px">${r.action}</td>
                ${workshops.length ? `<td style="font-size:11px;color:var(--t3)">${r.workshop_name||'Company-wide'}</td>` : ''}
                <td style="font-family:var(--fm);font-size:10px;color:var(--t3)">${r.ip_address||'—'}</td>
              </tr>
              ${hasDetail ? `<tr class="audit-detail" id="audit-detail-${i}" style="display:none">
                <td colspan="${workshops.length ? 8 : 7}" style="padding:0 12px 10px">
                  <div style="padding:10px 14px;background:var(--bg2);border-radius:6px;font-family:var(--fm);font-size:11px;display:flex;gap:24px;flex-wrap:wrap">
                    ${r.before_values ? `<div>
                      <div style="font-weight:600;margin-bottom:4px;color:var(--t2)">Before</div>
                      <pre style="margin:0;color:var(--t3);white-space:pre-wrap;max-width:420px;font-size:11px">${JSON.stringify(r.before_values,null,2)}</pre>
                    </div>` : ''}
                    ${r.after_values ? `<div>
                      <div style="font-weight:600;margin-bottom:4px;color:var(--t2)">After</div>
                      <pre style="margin:0;color:var(--t3);white-space:pre-wrap;max-width:420px;font-size:11px">${JSON.stringify(r.after_values,null,2)}</pre>
                    </div>` : ''}
                    ${r.reason ? `<div>
                      <div style="font-weight:600;margin-bottom:4px;color:var(--t2)">Reason</div>
                      <div style="color:var(--t3)">${r.reason}</div>
                    </div>` : ''}
                  </div>
                </td>
              </tr>` : ''}`;
            }).join('')}
          </tbody>
        </table>
      </div>
    </div>
  `;

  const currentFilters = () => ({
    module:         $('af-module').value,
    actionType:     $('af-type').value,
    roleFilter:     $('af-role').value,
    workshopFilter: $('af-workshop') ? $('af-workshop').value : undefined,
    fromDate:       $('af-from').value  || undefined,
    toDate:         $('af-to').value    || undefined,
    search:         $('af-search').value.trim() || undefined,
    sortBy, sortDir,
  });
  $('af-apply').onclick = () => renderAudit({ ...currentFilters(), page: 0, pageSize });
  $('af-clear').onclick = () => renderAudit({});
  $('af-prev').onclick  = () => renderAudit({ ...filters, page: page - 1 });
  $('af-next').onclick  = () => renderAudit({ ...filters, page: page + 1 });

  document.querySelectorAll('#audit-table [data-sort-col]').forEach(th => {
    th.onclick = () => {
      const col = th.dataset.sortCol;
      const newDir = (sortBy === col && sortDir === 'desc') ? 'asc' : 'desc';
      renderAudit({ ...currentFilters(), sortBy: col, sortDir: newDir, page: 0, pageSize });
    };
  });

  $('af-export').onclick = async () => {
    showToast('Generating Excel export…', 'info');
    const exportRes = await UFCL.auditExportExcel(STORAGE.user.id, currentFilters());
    if (!exportRes.ok) { showToast(exportRes.error || 'Could not generate export.', 'error'); return; }
    const byteChars = atob(exportRes.base64);
    const byteNumbers = new Array(byteChars.length);
    for (let i = 0; i < byteChars.length; i++) byteNumbers[i] = byteChars.charCodeAt(i);
    const blob = new Blob([new Uint8Array(byteNumbers)], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = exportRes.filename;
    document.body.appendChild(a); a.click(); a.remove();
    URL.revokeObjectURL(url);
    showToast(`Exported ${exportRes.rowCount} row(s) to ${exportRes.filename}.`, 'success');
  };

  document.querySelectorAll('.audit-row').forEach(row => {
    row.addEventListener('click', () => {
      const detail = $(`audit-detail-${row.dataset.idx}`);
      if (detail) detail.style.display = detail.style.display === 'none' ? '' : 'none';
    });
  });
}

async function renderChanges() {
  const res = await UFCL.changesList(STORAGE.user.id);
  if (!res.ok) return renderDenied('changes', res.error);
  const rows = res.rows || [];
  $('page-changes').innerHTML = `
    <div class="ptitle">Change requests</div>
    <div class="psub">Submit and review change requests.</div>
    <div class="card">
      <h3><i class="ti ti-send"></i>Submit request</h3>
      <div class="frow">
        <div class="fg"><label>Record type</label><select id="cr-type"><option>Production Log</option><option>Sales Order</option><option>Inventory</option><option>Logistics</option></select></div>
        <div class="fg"><label>Record reference</label><input type="text" id="cr-ref" placeholder="e.g. Log 28 Nov 2024"></div>
      </div>
      <div class="frow full"><div class="fg"><label>Request details</label><textarea id="cr-text" placeholder="Describe what should be changed and why..."></textarea></div></div>
      <div class="brow"><button class="bp1" id="cr-submit"><i class="ti ti-send"></i>Submit request</button></div>
    </div>
    <div class="card">
      <h3><i class="ti ti-table"></i>Requests</h3>
      <div class="tw">
        <table class="dt">
          <thead><tr><th>ID</th><th>Type</th><th>Ref</th><th>By</th><th>Date</th><th>Status</th>${res.isMgr ? '<th>Manager</th>' : ''}</tr></thead>
          <tbody>
            ${rows
              .map((c) => {
                const badge = c.status === 'Approved' ? 'bg' : c.status === 'Rejected' ? 'br' : 'ba';
                return `<tr>
                  <td style="font-family:var(--fm)">${c.id}</td>
                  <td>${c.record_type}</td>
                  <td style="color:var(--t3)">${c.record_ref}</td>
                  <td>${c.by || '—'}</td>
                  <td style="font-family:var(--fm);color:var(--t3)">${c.created}</td>
                  <td><span class="badge ${badge}">${c.status}</span></td>
                  ${
                    res.isMgr
                      ? `<td>${
                          c.status === 'Pending'
                            ? `<button class="bp1" style="padding:3px 9px;font-size:11px;margin-right:4px" data-ap="${c.id}"><i class="ti ti-check" style="font-size:11px"></i>Approve</button>
                               <button class="bdanger" style="padding:3px 8px" data-rj="${c.id}"><i class="ti ti-x" style="font-size:11px"></i>Reject</button>`
                            : `<span style="font-size:11px;color:var(--t3)">${(c.response || '—').slice(0, 40)}${(c.response || '').length > 40 ? '…' : ''}</span>`
                        }</td>`
                      : ''
                  }
                </tr>`;
              })
              .join('')}
          </tbody>
        </table>
      </div>
    </div>
  `;
  $('cr-submit').onclick = async () => {
    const payload = { record_type: $('cr-type').value, record_ref: $('cr-ref').value, request_text: $('cr-text').value };
    const r = await UFCL.changesCreate(STORAGE.user.id, payload);
    if (!r.ok) return alert(r.error || 'Submit failed');
    await renderChanges();
  };
  document.querySelectorAll('[data-ap]').forEach((b) => {
    b.onclick = async () => {
      const id = Number(b.dataset.ap);
      const resp = prompt('Approval note (optional):') || '';
      const r = await UFCL.changesReview(STORAGE.user.id, id, 'Approved', resp);
      if (!r.ok) return alert(r.error || 'Failed');
      await renderChanges();
    };
  });
  document.querySelectorAll('[data-rj]').forEach((b) => {
    b.onclick = async () => {
      const id = Number(b.dataset.rj);
      const resp = prompt('Rejection reason:') || '';
      const r = await UFCL.changesReview(STORAGE.user.id, id, 'Rejected', resp);
      if (!r.ok) return alert(r.error || 'Failed');
      await renderChanges();
    };
  });
}

async function renderMonthly() {
  const month = new Date().toISOString().slice(0, 7);
  const res = await UFCL.monthlyDashboard(STORAGE.user.id, month);
  if (!res.ok) return renderDenied('monthly', res.error);

  const { production = {}, sales = {}, expenses = [], totalExpenses = 0, approval = {} } = res;
  const timberWastePct = Number(production.timber_units) > 0
    ? ((Number(production.timber_waste) / Number(production.timber_units)) * 100).toFixed(1)
    : '0.0';
  const polesWastePct = Number(production.poles_units) > 0
    ? ((Number(production.poles_waste) / Number(production.poles_units)) * 100).toFixed(1)
    : '0.0';

  $('page-monthly').innerHTML = `
    <div class="ptitle">Monthly Dashboard</div>
    <div class="psub">Production, sales and financial summary for ${res.month}.</div>
    ${
      STORAGE.user.role === 'ceo'
        ? approval.approved
          ? `<div class="appbar"><p><i class="ti ti-circle-check" style="font-size:14px;vertical-align:-2px;margin-right:4px"></i>Report approved by CEO</p><span>Signed off</span></div>`
          : `<div class="appbar"><p>Monthly report for ${res.month} — pending your approval</p><span>Awaiting CEO sign-off</span><button class="appbtn" id="apprBtn">Approve &amp; sign off</button></div>`
        : `<div class="appbar" style="background:var(--surf);border-color:var(--border)"><p style="color:var(--t3)">Approval status</p><span style="color:var(--t4)">${approval.approved ? 'Approved by CEO' : 'Pending CEO approval'}</span></div>`
    }
    <div class="cards">
      <div class="mc"><div class="mclbl">Timber produced</div><div class="mcval">${Number(production.timber_units || 0).toLocaleString()}</div><div class="mcsub cg"><i class="ti ti-package"></i>units</div></div>
      <div class="mc"><div class="mclbl">Poles produced</div><div class="mcval">${Number(production.poles_units || 0).toLocaleString()}</div><div class="mcsub cg"><i class="ti ti-package"></i>units</div></div>
      <div class="mc"><div class="mclbl">Timber waste rate</div><div class="mcval">${timberWastePct}%</div><div class="mcsub ${Number(timberWastePct) > 10 ? 'cr' : 'ca'}"><i class="ti ti-alert-triangle"></i>waste</div></div>
      <div class="mc"><div class="mclbl">Poles waste rate</div><div class="mcval">${polesWastePct}%</div><div class="mcsub ${Number(polesWastePct) > 10 ? 'cr' : 'ca'}"><i class="ti ti-alert-triangle"></i>waste</div></div>
      <div class="mc"><div class="mclbl">Downtime</div><div class="mcval">${Number(production.downtime_hours || 0).toFixed(1)}h</div><div class="mcsub ca"><i class="ti ti-clock"></i>total</div></div>
      <div class="mc"><div class="mclbl">Log days</div><div class="mcval">${Number(production.log_days || 0)}</div><div class="mcsub bp"><i class="ti ti-calendar"></i>days</div></div>
    </div>
    <div class="cards" style="margin-top:12px">
      <div class="mc"><div class="mclbl">Sales orders</div><div class="mcval">${Number(sales.order_count || 0)}</div><div class="mcsub bp"><i class="ti ti-shopping-cart"></i>orders</div></div>
      <div class="mc"><div class="mclbl">Units sold</div><div class="mcval">${Number(sales.total_qty || 0).toLocaleString()}</div><div class="mcsub cg"><i class="ti ti-package"></i>units</div></div>
      <div class="mc"><div class="mclbl">Revenue</div><div class="mcval">RWF ${Number(sales.total_revenue || 0).toLocaleString()}</div><div class="mcsub cg"><i class="ti ti-coin"></i>month</div></div>
      <div class="mc"><div class="mclbl">Total expenses</div><div class="mcval">RWF ${Number(totalExpenses).toLocaleString()}</div><div class="mcsub cr"><i class="ti ti-cash"></i>month</div></div>
    </div>
    <div class="card">
      <h3><i class="ti ti-cash"></i>Monthly expenses by category</h3>
      <div class="tw">
        <table class="dt">
          <thead><tr><th>Category</th><th>Total (RWF)</th><th>Share</th></tr></thead>
          <tbody>
            ${expenses.length
              ? expenses.map((e) => {
                  const share = totalExpenses ? ((e.total / totalExpenses) * 100).toFixed(1) : '0.0';
                  return `<tr>
                    <td>${e.category}</td>
                    <td style="font-family:var(--fm)">${Number(e.total).toLocaleString()}</td>
                    <td>
                      <div style="display:flex;align-items:center;gap:8px">
                        <div style="background:var(--bg2);border-radius:4px;height:8px;width:80px;overflow:hidden">
                          <div style="background:var(--blue);height:100%;width:${share}%"></div>
                        </div>
                        ${share}%
                      </div>
                    </td>
                  </tr>`;
                }).join('') + `<tr style="font-weight:600;border-top:2px solid var(--bdr)"><td>Total</td><td style="font-family:var(--fm)">RWF ${Number(totalExpenses).toLocaleString()}</td><td>100%</td></tr>`
              : '<tr><td colspan="3" style="text-align:center;color:var(--t3);padding:1.5rem">No expense data for this month</td></tr>'}
          </tbody>
        </table>
      </div>
    </div>
  `;

  const b = $('apprBtn');
  if (b) {
    b.onclick = async () => {
      const r = await UFCL.monthlyApprove(STORAGE.user.id, res.month);
      if (!r.ok) return alert(r.error || 'Approve failed');
      STORAGE.approved.monthly = true;
      await renderMonthly();
    };
  }
}

async function renderUsers() {
    const [userRes, roleRes] = await Promise.all([UFCL.usersList(STORAGE.user.id), UFCL.rolesList(STORAGE.user.id)]);
    if (!userRes.ok) return renderDenied('users', userRes.error);
    const rows = userRes.rows || [];
    const roles = (roleRes.ok && roleRes.rows) || [];
    const workshops = userRes.workshops || [];

    const activeCount = rows.filter((u) => u.active).length;
    const customCount = rows.filter((u) => (u.user_permissions || []).length || (u.user_responsibilities || []).length).length;

    $('page-users').innerHTML = `
      <div class="ptitle">Users & Roles</div>
      <div class="psub">Manage accounts, assign roles, and control individual access.</div>

      <div class="cards">
        <div class="mc"><div class="mclbl">Total accounts</div><div class="mcval">${rows.length}</div><div class="mcsub cg"><i class="ti ti-users"></i>accounts</div></div>
        <div class="mc"><div class="mclbl">Active</div><div class="mcval">${activeCount}</div><div class="mcsub cg"><i class="ti ti-circle-check"></i>users</div></div>
        <div class="mc"><div class="mclbl">Inactive</div><div class="mcval">${rows.length - activeCount}</div><div class="mcsub ${rows.length - activeCount > 0 ? 'cr' : 'cg'}"><i class="ti ti-circle-x"></i>users</div></div>
        <div class="mc"><div class="mclbl">Custom overrides</div><div class="mcval">${customCount}</div><div class="mcsub bp"><i class="ti ti-shield-check"></i>users</div></div>
      </div>

      <div class="card">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem">
          <h3 style="margin-bottom:0"><i class="ti ti-users"></i>Accounts</h3>
          <button class="appbtn" id="newUser"><i class="ti ti-plus" style="font-size:12px;vertical-align:-1px"></i> New user</button>
        </div>
        <div class="tw">
          <table class="dt">
            <thead><tr><th>Username</th><th>Name</th><th>Role</th><th>Department</th><th>Workshop</th><th>Override</th><th>Status</th><th>Created</th><th>Actions</th></tr></thead>
            <tbody>
              ${rows.map((u) => `<tr>
                <td style="font-family:var(--fm);font-weight:500">${u.username}</td>
                <td>${u.name}</td>
                <td><span class="badge bt">${roleLabel(u.role)}</span></td>
                <td>${u.department || '<span style="color:var(--t3)">—</span>'}</td>
                <td>${u.workshop_name ? `<span class="badge bg" style="font-size:11px"><i class="ti ti-building-warehouse" style="font-size:10px"></i> ${u.workshop_name}</span>` : '<span style="color:var(--t3)">—</span>'}</td>
                <td>${((u.user_permissions || []).length || (u.user_responsibilities || []).length) ? '<span class="badge bb">Custom</span>' : '<span style="color:var(--t3)">—</span>'}</td>
                <td><span class="badge ${u.active ? 'bg' : 'br'}">${u.active ? 'Active' : 'Inactive'}</span></td>
                <td style="color:var(--t3)">${u.created}</td>
                <td style="white-space:nowrap">
                  <button type="button" class="bs1" data-resp="${u.id}"><i class="ti ti-shield-lock" style="font-size:12px;vertical-align:-1px"></i> Permissions</button>
                  <button type="button" class="bs1" data-edit="${u.id}"><i class="ti ti-pencil" style="font-size:12px;vertical-align:-1px"></i> Edit</button>
                  <button type="button" class="bs1" data-reset="${u.id}"><i class="ti ti-key" style="font-size:12px;vertical-align:-1px"></i> Reset PW</button>
                  ${STORAGE.user.role === 'admin' && Number(u.id) !== Number(STORAGE.user.id)
                    ? `<button type="button" class="bs1" data-delete="${u.id}" style="color:var(--red)"><i class="ti ti-trash" style="font-size:12px;vertical-align:-1px"></i> Delete</button>`
                    : ''}
                </td>
              </tr>`).join('')}
            </tbody>
          </table>
        </div>
      </div>

      <div class="card">
        <h3><i class="ti ti-shield-check"></i>Role definitions</h3>
        <p style="color:var(--t3);margin-bottom:1rem">Default page access and responsibilities per role. Override per individual via the Permissions button.</p>
        <div class="tw">
          <table class="dt">
            <thead><tr><th>Role</th><th>Description</th><th>Pages</th><th>Default responsibilities</th><th></th></tr></thead>
            <tbody>
              ${roles.map((r) => `<tr>
                <td><span class="badge bt" style="font-family:var(--fm)">${roleLabel(r.role)}</span></td>
                <td style="color:var(--t2)">${r.description || '<span style="color:var(--t3)">—</span>'}</td>
                <td>${(r.permissions || []).length ? `<span class="badge bb">${(r.permissions || []).length} pages</span>` : '<span style="color:var(--t3)">—</span>'}</td>
                <td>${(r.responsibilities || []).length
                  ? `<ul style="margin:0;padding-left:1.1rem;color:var(--t2);font-size:12px">${(r.responsibilities || []).map((item) => `<li style="margin-bottom:2px">${item}</li>`).join('')}</ul>`
                  : '<span style="color:var(--t3)">—</span>'}</td>
                <td><button type="button" class="bs1" data-role="${r.role}">Edit</button></td>
              </tr>`).join('')}
            </tbody>
          </table>
        </div>
      </div>
    `;

    // Build role dropdown from live DB data so new roles appear automatically.
    // Preferred display order: management → operational leaders → workshop staff.
    const ROLE_ORDER = [
      'admin', 'ceo', 'operations', 'logistics', 'sales', 'finance',
      'supervisor', 'logistics-officer',
      'storekeeper', 'storekeeper-assistant', 'mechanician',
      'harvesting-leader', 'sawmill-leader', 'poles-leader', 'vat-leader',
      'sales-staff', 'showroom-staff',
    ];
    const knownRoleSlugs = roles.map((r) => r.role);
    const ordered = [
      ...ROLE_ORDER.filter((r) => knownRoleSlugs.includes(r)),
      ...knownRoleSlugs.filter((r) => !ROLE_ORDER.includes(r)).sort(),
    ];
    const roleOptions = ordered.map(roleOptionHtml).join('');

    const departmentOptions = ['', 'Administration', 'Finance', 'Logistics', 'Operations', 'Sales']
      .map((dept) => `<option value="${dept}">${dept || '— None —'}</option>`)
      .join('');

    // Maps each role to its default department for auto-suggestion.
    const ROLE_DEPT = {
      admin: 'Administration', ceo: 'Administration',
      finance: 'Finance',
      logistics: 'Logistics', 'logistics-officer': 'Logistics',
      storekeeper: 'Logistics', 'storekeeper-assistant': 'Logistics', mechanician: 'Logistics',
      operations: 'Operations', supervisor: 'Operations',
      'harvesting-leader': 'Operations', 'sawmill-leader': 'Operations',
      'poles-leader': 'Operations', 'vat-leader': 'Operations',
      sales: 'Sales', 'sales-staff': 'Sales', 'showroom-staff': 'Sales',
    };

    const workshopOpts = `<option value="">None (all workshops)</option>` +
      workshops.map(w => `<option value="${w.id}">${w.name}</option>`).join('');

    const nu = $('newUser');
    if (nu)
      nu.onclick = () => {
        openOverlay(
          'Create user',
          'Enter username, name, role and temporary password.',
          `
        <div class="frow">
          <div class="fg"><label>Username</label><input type="text" id="u-username" placeholder="username"></div>
          <div class="fg"><label>Name</label><input type="text" id="u-name" placeholder="Full name"></div>
        </div>
        <div class="frow">
          <div class="fg"><label>Role</label><select id="u-role">${roleOptions}</select></div>
          <div class="fg"><label>Department <span style="color:var(--t3);font-weight:400">(auto-filled from role)</span></label><select id="u-department">${departmentOptions}</select></div>
        </div>
        <div class="fg"><label>Workshop assignment <span style="color:var(--t3);font-weight:400">(optional — restricts user to one workshop)</span></label>
          <select id="u-workshop">${workshopOpts}</select>
        </div>
        <div class="frow">
          <div class="fg"><label>Password</label><input type="password" id="u-pass" placeholder="temporary password" value="UFCL@1234"></div>
        </div>
        <div class="brow"><button type="button" class="bp1" id="ovSave">Create</button><button type="button" class="bs1" id="ovCancel">Cancel</button></div>
        `,
          async () => {
            const payload = {
              username: $('u-username').value,
              name: $('u-name').value,
              role: $('u-role').value,
              department: $('u-department').value || null,
              password: $('u-pass').value,
              workshop_id: $('u-workshop').value || null
            };
            const r = await UFCL.usersCreate(STORAGE.user.id, payload);
            if (!r.ok) return showOverlayError(r.error || 'Failed to create user.');
            closeOverlay();
            await renderUsers();
          }
        );
        setTimeout(() => {
          const roleEl = $('u-role');
          const deptEl = $('u-department');
          if (roleEl && deptEl) {
            roleEl.addEventListener('change', () => {
              const suggested = ROLE_DEPT[roleEl.value];
              if (suggested) deptEl.value = suggested;
            });
          }
        }, 10);
      };

    $('page-users').querySelectorAll('[data-edit]').forEach((b) => {
      b.onclick = async () => {
        const id = Number(b.dataset.edit);
        const u = rows.find((x) => Number(x.id) === id);
        if (!u) return;
        openOverlay(
          'Edit user',
          `Edit ${u.username}`,
          `
          <div class="frow">
            <div class="fg"><label>Name</label><input type="text" id="eu-name" value="${u.name}"></div>
            <div class="fg"><label>Role</label><select id="eu-role">${roleOptions}</select></div>
            <div class="fg"><label>Department</label><select id="eu-department">${departmentOptions}</select></div>
          </div>
          <div class="fg"><label>Workshop assignment <span style="color:var(--t3);font-weight:400">(restricts user to one workshop's stock)</span></label>
            <select id="eu-workshop">${workshopOpts}</select>
          </div>
          <div class="frow"><div class="fg"><label>Status</label><select id="eu-active"><option value="true">Active</option><option value="false">Inactive</option></select></div></div>
          <div class="brow"><button type="button" class="bp1" id="ovSave">Save</button><button type="button" class="bs1" id="ovCancel">Cancel</button></div>
          `,
          async () => {
            const payload = {
              name: $('eu-name').value,
              role: $('eu-role').value,
              department: $('eu-department').value || null,
              active: $('eu-active').value === 'true',
              workshop_id: $('eu-workshop').value || null
            };
            const r = await UFCL.usersUpdate(STORAGE.user.id, id, payload);
            if (!r.ok) return showOverlayError(r.error || 'Failed to update user.');
            closeOverlay();
            await renderUsers();
          }
        );
        setTimeout(() => {
          const sel = $('eu-role');
          if (sel) sel.value = u.role;
          const dep = $('eu-department');
          if (dep) dep.value = u.department || '';
          const sa = $('eu-active');
          if (sa) sa.value = u.active ? 'true' : 'false';
          const ew = $('eu-workshop');
          if (ew) ew.value = u.workshop_id || '';
          // auto-suggest department when role is changed during edit
          if (sel && dep) {
            sel.addEventListener('change', () => {
              const suggested = ROLE_DEPT[sel.value];
              if (suggested) dep.value = suggested;
            });
          }
        }, 10);
      };
    });

    $('page-users').querySelectorAll('[data-reset]').forEach((b) => {
      b.onclick = async () => {
        const id = Number(b.dataset.reset);
        openOverlay(
          'Reset password',
          'Set a temporary password for this user.',
          `
            <div class="frow"><div class="fg"><label>New password</label><input type="password" id="rp-pass" placeholder="temporary password"></div></div>
            <div class="brow"><button type="button" class="bp1" id="ovSave">Reset</button><button type="button" class="bs1" id="ovCancel">Cancel</button></div>
          `,
          async () => {
            const pw = $('rp-pass').value;
            const r = await UFCL.usersResetPassword(STORAGE.user.id, id, pw || undefined);
            if (!r.ok) return showOverlayError(r.error || 'Failed to reset password.');
            showOverlaySuccess('Password reset successfully.');
          }
        );
      };
    });

    $('page-users').querySelectorAll('[data-delete]').forEach((b) => {
      b.onclick = async () => {
        const id = Number(b.dataset.delete);
        const u = rows.find((x) => Number(x.id) === id);
        if (!u) return;
        openOverlay(
          'Delete User Account',
          'This action cannot be undone. Please review the details below before confirming.',
          `
          <div style="background:#fff5f5;border:1px solid #feb2b2;border-radius:6px;padding:12px 16px;margin-bottom:14px;font-size:13px;color:#742a2a;line-height:1.5">
            <i class="ti ti-alert-triangle" style="color:#e53e3e;margin-right:6px;vertical-align:-1px"></i>
            The account will be permanently deactivated. All records and data created by this user will be preserved.
          </div>
          <div style="border:1px solid var(--border);border-radius:6px;padding:12px 16px;margin-bottom:16px;font-size:13px;line-height:1.8">
            <div><strong>Username:</strong> ${u.username}</div>
            <div><strong>Name:</strong> ${u.name}</div>
            <div><strong>Role:</strong> ${roleLabel(u.role)}</div>
            ${u.workshop_name ? `<div><strong>Workshop:</strong> ${u.workshop_name}</div>` : ''}
          </div>
          <div class="brow">
            <button type="button" class="bp1" id="ovSave" style="background:var(--red);border-color:var(--red)"><i class="ti ti-trash" style="font-size:12px;vertical-align:-1px"></i> Confirm Delete</button>
            <button type="button" class="bs1" id="ovCancel">Cancel</button>
          </div>
          `,
          async () => {
            const r = await UFCL.usersDelete(STORAGE.user.id, id);
            if (!r.ok) return showOverlayError(r.error || 'Failed to delete user.');
            closeOverlay();
            await renderUsers();
          }
        );
      };
    });

    $('page-users').querySelectorAll('[data-resp]').forEach((b) => {
      b.onclick = async () => {
        const id = Number(b.dataset.resp);
        const u = rows.find((x) => Number(x.id) === id);
        if (!u) return;
        const roleEntry = roles.find((x) => x.role === u.role);
        const roleResps = (roleEntry && roleEntry.responsibilities) || [];
        const roleRespHtml = roleResps.length
          ? `<div style="padding:.625rem .75rem;background:var(--surf);border:1px solid var(--border);border-radius:var(--r-sm)">${roleResps.map((item) => `<div style="display:flex;align-items:flex-start;gap:6px;padding:3px 0;font-size:12px;color:var(--t2)"><i class="ti ti-point-filled" style="font-size:8px;margin-top:4px;color:var(--t3);flex-shrink:0"></i>${item}</div>`).join('')}</div>`
          : `<span style="color:var(--t3);font-size:12px">No default responsibilities defined for this role.</span>`;
        const actingRoleOptions = roles
          .filter((x) => x.role !== u.role)
          .map((x) => `<option value="${x.role}">${roleLabel(x.role)}</option>`)
          .join('');
        openOverlay(
          'User permissions',
          `Manage page access and custom responsibilities for <strong>${u.username}</strong>. Custom settings override role defaults.`,
          `
            <div class="frow">
              <div class="fg"><label>User</label><input type="text" disabled value="${u.username}"></div>
              <div class="fg"><label>Assigned role</label><input type="text" disabled value="${roleLabel(u.role)}"></div>
            </div>
            <div class="frow full"><div class="fg"><label>Page permissions</label><div id="ur-permissions" style="max-height:260px;overflow:auto;padding:.75rem;border:1px solid var(--border);border-radius:var(--r-sm)">${renderPermissionCheckboxes(u.user_permissions || [])}</div></div></div>
            <div style="background:var(--g-light);border:1px solid rgba(30,95,54,.18);border-radius:var(--r-sm);padding:.625rem .875rem;margin-bottom:.75rem">
              <div style="font-size:11px;font-weight:600;color:var(--g-dark);text-transform:uppercase;letter-spacing:.05em;margin-bottom:.45rem"><i class="ti ti-replace" style="vertical-align:-2px;margin-right:4px"></i>Acting role import</div>
              <div style="font-size:12px;color:var(--g-soft);margin-bottom:.625rem">Copy responsibilities and permissions from another role into this user's custom settings — without changing their assigned role.</div>
              <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
                <select id="ur-acting-role" style="flex:1;min-width:160px;padding:7px 10px;font-size:13px;font-family:var(--ff);border:1px solid var(--border2);border-radius:var(--r-sm);background:var(--surf);color:var(--t1)"><option value="">— Select a role to copy from —</option>${actingRoleOptions}</select>
                <button type="button" class="bs1" id="ur-import-resp"><i class="ti ti-file-import" style="font-size:12px;vertical-align:-1px"></i> Import responsibilities</button>
                <button type="button" class="bs1" id="ur-import-perms"><i class="ti ti-shield-plus" style="font-size:12px;vertical-align:-1px"></i> Import permissions</button>
              </div>
            </div>
            <div class="frow full"><div class="fg"><label>Role default responsibilities <span style="font-weight:400;color:var(--t3);text-transform:none;letter-spacing:0">— ${roleLabel(u.role)} defaults</span></label>${roleRespHtml}</div></div>
            <div class="frow full"><div class="fg"><label>Custom responsibilities <span style="font-weight:400;color:var(--t3);text-transform:none;letter-spacing:0">— specific to this user</span></label><textarea id="ur-resp" rows="5" placeholder="One responsibility per line…">${(u.user_responsibilities || []).join('\n')}</textarea></div></div>
            <div class="brow"><button type="button" class="bp1" id="ovSave">Save</button><button type="button" class="bs1" id="ovCancel">Cancel</button></div>
          `,
          async () => {
            const selectedPermissions = Array.from(document.querySelectorAll('#ur-permissions input.perm-checkbox:checked')).map((input) => input.value);
            const payload = {
              permissions: selectedPermissions,
              responsibilities: $('ur-resp').value
                .split(/\r?\n/)
                .map((item) => item.trim())
                .filter(Boolean)
            };
            const r = await UFCL.usersUpdate(STORAGE.user.id, id, payload);
            if (!r.ok) return showOverlayError(r.error || 'Failed to save permissions.');
            closeOverlay();
            await renderUsers();
          }
        );

        const getActingRole = () => {
          const sel = $('ur-acting-role');
          if (!sel || !sel.value) return null;
          return roles.find((x) => x.role === sel.value) || null;
        };

        const importRespBtn = $('ur-import-resp');
        if (importRespBtn) importRespBtn.onclick = () => {
          const entry = getActingRole();
          if (!entry) return;
          const incoming = (entry.responsibilities || []).join('\n');
          const current = $('ur-resp').value.trim();
          $('ur-resp').value = current ? `${current}\n${incoming}` : incoming;
        };

        const importPermsBtn = $('ur-import-perms');
        if (importPermsBtn) importPermsBtn.onclick = () => {
          const entry = getActingRole();
          if (!entry) return;
          (entry.permissions || []).forEach((pageId) => {
            const cb = document.querySelector(`#ur-permissions input.perm-checkbox[value="${pageId}"]`);
            if (cb) cb.checked = true;
          });
        };
      };
    });

    $('page-users').querySelectorAll('[data-role]').forEach((b) => {
      b.onclick = async () => {
        const role = b.dataset.role;
        const entry = roles.find((x) => x.role === role);
        if (!entry) return;
        openOverlay(
          `Edit ${roleLabel(entry.role)} role`,
          'Update description, permissions, and responsibilities for this role.',
          `
          <div class="frow full"><div class="fg"><label>Description</label><input type="text" id="rr-desc" value="${entry.description || ''}"></div></div>
          <div class="frow full"><div class="fg"><label>Permissions</label><div id="rr-permissions" style="max-height:260px;overflow:auto;padding:.75rem;border:1px solid var(--border);border-radius:var(--r-sm)">${renderPermissionCheckboxes(entry.permissions || [])}</div></div></div>
          <div class="frow full"><div class="fg"><label>Responsibilities</label><textarea id="rr-resp" rows="5" placeholder="One responsibility per line…">${(entry.responsibilities || []).join('\n')}</textarea></div></div>
          <div class="brow"><button type="button" class="bp1" id="ovSave">Save</button><button type="button" class="bs1" id="ovCancel">Cancel</button></div>
`,
          async () => {
            const selectedPermissions = Array.from(document.querySelectorAll('#rr-permissions input.perm-checkbox:checked')).map((input) => input.value);
            const payload = {
              description: $('rr-desc').value,
              permissions: selectedPermissions,
              responsibilities: $('rr-resp').value
                .split(/\r?\n/)
                .map((item) => item.trim())
                .filter(Boolean)
            };
            const r = await UFCL.rolesUpdate(STORAGE.user.id, role, payload);
            if (!r.ok) return showOverlayError(r.error || 'Failed to save role.');
            closeOverlay();
            await renderUsers();
          }
        );
      };
    });
  }

// Phase 2 — Inventory Dashboard. Reuses the exact Executive KPI/Operational
// Widget/enterprise-table-toolkit pattern already proven for Workshop's own
// dashboard (same _lgdWidget helper, same .mc card family, same
// procFilterBarHtml/wireSortableTable toolkit) — no new visual language.
async function renderInventory() {
  const [res, dashRes, intelRes] = await Promise.all([
    UFCL.inventoryList(STORAGE.user.id, WORKSHOP_FILTER),
    UFCL.inventoryDashboard(STORAGE.user.id, WORKSHOP_FILTER),
    UFCL.inventoryIntelligence(STORAGE.user.id, WORKSHOP_FILTER),
  ]);
  if (!res.ok) return renderDenied('inventory', res.error);
  const d = dashRes.ok ? dashRes : {};
  const iq = intelRes.ok ? intelRes : {};

  const rows = res.rows || [];
  rows.forEach(r => {
    const out = Number(r.stock) === 0;
    const low = Number(r.stock) <= Number(r.min_stock);
    r._statusLabel = out ? 'Out of stock' : low ? 'Reorder' : 'OK';
  });
  const invState = { search: '', status: '' };
  const invSort = { key: null, dir: 'asc' };
  function invFiltered() {
    return applyProcListFilters(rows, {
      search: invState.search, searchFields: ['name', 'sku', 'category'],
      status: invState.status, statusField: '_statusLabel',
    });
  }

  $('page-inventory').innerHTML = `
    ${workshopBannerHtml(res.warehouses, res.user_workshop_id)}
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;margin-bottom:1rem">
      <div>
        <div class="ptitle"><i class="ti ti-layout-dashboard" style="color:var(--g-soft)"></i> Inventory Dashboard</div>
        <div class="psub">Live stock levels, transfers, requests, and exceptions across all spare parts and materials.</div>
      </div>
      <button class="bs1" id="invExport" style="flex-shrink:0"><i class="ti ti-file-download"></i>Export report</button>
    </div>

    <div style="font-weight:600;font-size:13px;color:var(--t1);margin:1rem 0 .75rem"><i class="ti ti-dashboard" style="color:var(--g-soft)"></i> Executive KPIs</div>
    <div class="cards" style="margin-bottom:1.25rem">
      ${kpiTileHtml({ label: 'Total items', value: d.totalItems || 0, sub: '<i class="ti ti-stack"></i>tracked', subCls: 'cg', cls: 'inv-kpi-link', data: { filter: '' } })}
      ${kpiTileHtml({ label: 'Inventory value', value: Math.round(d.totalValue || 0).toLocaleString(), valueStyle: 'font-size:18px', sub: '<i class="ti ti-coin"></i>RWF at cost', subCls: 'bp', cls: 'inv-kpi-link', data: { filter: '' } })}
      ${kpiTileHtml({ label: 'Available stock', value: (d.availableStock || 0).toLocaleString(), sub: '<i class="ti ti-package"></i>units on hand', subCls: 'cg', cls: 'inv-kpi-link', data: { filter: '' } })}
      ${kpiTileHtml({ label: 'In transit', value: (d.reservedStock || 0).toLocaleString(), sub: '<i class="ti ti-truck"></i>on approved transfers', subCls: 'bp', cls: 'inv-kpi-link', data: { page: 'stock-transfers' } })}
      ${kpiTileHtml({ label: 'Low stock', value: d.lowStockCount || 0, valueColor: d.lowStockCount > 0 ? 'var(--amber)' : '', sub: '<i class="ti ti-alert-triangle"></i>items', subCls: d.lowStockCount > 0 ? 'ca' : 'cg', cls: 'inv-kpi-link', data: { filter: 'Reorder' } })}
      ${kpiTileHtml({ label: 'Out of stock', value: d.outOfStockCount || 0, valueColor: d.outOfStockCount > 0 ? 'var(--red)' : '', sub: '<i class="ti ti-alert-circle"></i>items', subCls: d.outOfStockCount > 0 ? 'cr' : 'cg', cls: 'inv-kpi-link', data: { filter: 'Out of stock' } })}
      ${kpiTileHtml({ label: 'Goods received', value: d.goodsReceivedThisMonth || 0, sub: '<i class="ti ti-package-import"></i>this month', subCls: 'cg' })}
      ${kpiTileHtml({ label: 'Transfers pending', value: d.transfersPending || 0, valueColor: d.transfersPending > 0 ? 'var(--amber)' : '', sub: '<i class="ti ti-arrows-exchange"></i>awaiting approval', subCls: d.transfersPending > 0 ? 'ca' : 'cg', cls: 'inv-kpi-link', data: { page: 'stock-transfers' } })}
      ${kpiTileHtml({ label: 'Material requests', value: d.materialRequestsPending || 0, valueColor: d.materialRequestsPending > 0 ? 'var(--amber)' : '', sub: '<i class="ti ti-clipboard-list"></i>pending', subCls: d.materialRequestsPending > 0 ? 'ca' : 'cg', cls: 'inv-kpi-link', data: { page: 'material-requests' } })}
      ${kpiTileHtml({ label: 'Adjustments', value: d.adjustmentsThisMonth || 0, sub: '<i class="ti ti-adjustments"></i>this month', subCls: 'cg', cls: 'inv-kpi-link', data: { page: 'stock-movements' } })}
      ${kpiTileHtml({ label: 'Consumption', value: (d.consumptionThisMonth || 0).toLocaleString(), sub: '<i class="ti ti-arrow-up-circle"></i>units this month', subCls: 'cg', cls: 'inv-kpi-link', data: { page: 'stock-movements' } })}
      ${kpiTileHtml({ label: 'Turnover', value: `${d.turnoverRatio || 0}×`, sub: '<i class="ti ti-refresh"></i>this month', subCls: 'bp' })}
    </div>

    <div style="font-weight:600;font-size:13px;color:var(--t1);margin-bottom:.75rem"><i class="ti ti-list-details" style="color:var(--g-soft)"></i> Operational Widgets</div>
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:1rem;margin-bottom:1.5rem">
      ${_lgdWidget('Low Stock Alerts', 'ti-alert-triangle', (d.lowStockAlerts||[]).map(r=>({label:r.name, sub:r.category, badge:`${r.total_stock}/${r.min_stock}`, warn:true})), 'No low stock alerts.')}
      ${_lgdWidget('Pending Transfers', 'ti-arrows-exchange', (d.pendingTransfers||[]).map(r=>({label:r.item_name, sub:`${r.from_workshop||'—'} → ${r.to_workshop||'—'}`, badge:r.requested_qty, warn:true})), 'No pending transfers.')}
      ${_lgdWidget('Goods Receipts Awaiting', 'ti-package-import', (d.goodsReceiptsAwaiting||[]).map(r=>({label:r.po_number, sub:r.supplier_name||'—', badge:'Partial', warn:true})), 'Nothing awaiting receipt.')}
      ${_lgdWidget('Material Requests Awaiting', 'ti-clipboard-list', (d.materialRequestsAwaiting||[]).map(r=>({label:r.item_name, sub:r.workshop_name||'—', badge:r.priority, warn:r.priority==='urgent'})), 'No requests waiting.')}
      ${_lgdWidget('Fast Moving Items', 'ti-trending-up', (d.fastMovingItems||[]).map(r=>({label:r.name, sub:`${r.moved} ${r.uom} moved`, badge:'Fast'})), 'No movement data yet this month.')}
      ${_lgdWidget('Slow Moving Items', 'ti-trending-down', (d.slowMovingItems||[]).map(r=>({label:r.name, sub:r.category, badge:`${r.total_stock} on hand`, warn:true})), 'No slow-moving items detected.')}
      ${_lgdWidget('Recently Updated', 'ti-history', (d.recentlyUpdated||[]).map(r=>({label:r.item_name, sub:`${r.movement_type} · ${r.created_by||'—'}`, badge:r.created_at})), 'No recent movements.')}
      ${_lgdWidget('Stock Exceptions', 'ti-exclamation-circle', (d.stockExceptions||[]).map(r=>({label:r.name, sub:r.exception_type, badge:r.total_stock, warn:true})), 'No exceptions.')}
    </div>

    <!-- Phase 3 — Operational Intelligence: trends, top-moving items,
         aging, health, and forecasting. Reuses the existing shared SVG
         chart helpers (_svgBar/_svgLine) and _lgdWidget — no new charting
         mechanism, no new calculation engine. -->
    <div style="font-weight:600;font-size:13px;color:var(--t1);margin-bottom:.75rem"><i class="ti ti-chart-dots" style="color:var(--g-soft)"></i> Operational Intelligence</div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:1rem;margin-bottom:1.25rem">
      <div class="card">
        <h3 style="margin:0 0 .75rem"><i class="ti ti-chart-line"></i> Consumption Trend <span style="font-size:11px;font-weight:400;color:var(--t3)">· last 6 months</span></h3>
        ${_svgBar(iq.consumptionTrendMonths||[], 'value', { color: 'var(--red)' })}
        <div style="display:flex;justify-content:space-between;margin-top:.4rem;font-size:10px;color:var(--t3)">${(iq.consumptionTrendMonths||[]).map(m=>`<span>${m.month.slice(5)}</span>`).join('')}</div>
      </div>
      <div class="card">
        <h3 style="margin:0 0 .75rem"><i class="ti ti-chart-line"></i> Receiving Trend <span style="font-size:11px;font-weight:400;color:var(--t3)">· last 6 months</span></h3>
        ${_svgBar(iq.receivingTrendMonths||[], 'value', { color: 'var(--green)' })}
        <div style="display:flex;justify-content:space-between;margin-top:.4rem;font-size:10px;color:var(--t3)">${(iq.receivingTrendMonths||[]).map(m=>`<span>${m.month.slice(5)}</span>`).join('')}</div>
      </div>
      <div class="card">
        <h3 style="margin:0 0 .75rem"><i class="ti ti-chart-line"></i> Inventory Trend <span style="font-size:11px;font-weight:400;color:var(--t3)">· net receiving − consumption</span></h3>
        ${_svgLine(iq.inventoryTrendMonths||[], 'value', { color: 'var(--blue)' })}
        <div style="display:flex;justify-content:space-between;margin-top:.4rem;font-size:10px;color:var(--t3)">${(iq.inventoryTrendMonths||[]).map(m=>`<span>${m.month.slice(5)}</span>`).join('')}</div>
      </div>
      <div class="card">
        <h3 style="margin:0 0 .75rem"><i class="ti ti-chart-line"></i> Transfer Trend <span style="font-size:11px;font-weight:400;color:var(--t3)">· requests per month</span></h3>
        ${_svgBar(iq.transferTrendMonths||[], 'value', { color: 'var(--purple)' })}
        <div style="display:flex;justify-content:space-between;margin-top:.4rem;font-size:10px;color:var(--t3)">${(iq.transferTrendMonths||[]).map(m=>`<span>${m.month.slice(5)}</span>`).join('')}</div>
      </div>
      <div class="card">
        <h3 style="margin:0 0 .75rem"><i class="ti ti-chart-line"></i> Adjustment Trend <span style="font-size:11px;font-weight:400;color:var(--t3)">· corrections per month</span></h3>
        ${_svgBar(iq.adjustmentTrendMonths||[], 'value', { color: 'var(--amber)' })}
        <div style="display:flex;justify-content:space-between;margin-top:.4rem;font-size:10px;color:var(--t3)">${(iq.adjustmentTrendMonths||[]).map(m=>`<span>${m.month.slice(5)}</span>`).join('')}</div>
      </div>
      <div class="card">
        <h3 style="margin:0 0 .75rem"><i class="ti ti-heart-rate-monitor"></i> Inventory Health</h3>
        <div style="display:grid;grid-template-columns:repeat(2,1fr);gap:.6rem">
          <div style="background:var(--bg2);border-radius:6px;padding:.5rem .7rem"><div style="font-size:10px;color:var(--t3);text-transform:uppercase">Healthy</div><div style="font-size:18px;font-weight:700;color:var(--green)">${iq.health?.healthy||0}</div></div>
          <div style="background:var(--bg2);border-radius:6px;padding:.5rem .7rem"><div style="font-size:10px;color:var(--t3);text-transform:uppercase">Low</div><div style="font-size:18px;font-weight:700;color:var(--amber)">${iq.health?.low||0}</div></div>
          <div style="background:var(--bg2);border-radius:6px;padding:.5rem .7rem"><div style="font-size:10px;color:var(--t3);text-transform:uppercase">Critical</div><div style="font-size:18px;font-weight:700;color:var(--red)">${iq.health?.critical||0}</div></div>
          <div style="background:var(--bg2);border-radius:6px;padding:.5rem .7rem"><div style="font-size:10px;color:var(--t3);text-transform:uppercase">Inactive</div><div style="font-size:18px;font-weight:700;color:var(--t3)">${iq.health?.inactive||0}</div></div>
          <div style="background:var(--bg2);border-radius:6px;padding:.5rem .7rem"><div style="font-size:10px;color:var(--t3);text-transform:uppercase">Fast-moving</div><div style="font-size:18px;font-weight:700;color:var(--blue)">${iq.health?.fastMoving||0}</div></div>
          <div style="background:var(--bg2);border-radius:6px;padding:.5rem .7rem"><div style="font-size:10px;color:var(--t3);text-transform:uppercase">Slow-moving</div><div style="font-size:18px;font-weight:700;color:var(--purple)">${iq.health?.slowMoving||0}</div></div>
        </div>
      </div>
    </div>

    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:1rem;margin-bottom:1.25rem">
      ${_lgdWidget('Most Consumed Items', 'ti-arrow-up-circle', (iq.mostConsumedItems||[]).map(r=>({label:r.name, sub:`${r.total} ${r.uom} · 90d`, badge:'Top'})), 'No consumption data yet.')}
      ${_lgdWidget('Most Requested Items', 'ti-clipboard-list', (iq.mostRequestedItems||[]).map(r=>({label:r.name, sub:`${r.requests} request(s) · 90d`, badge:'Top'})), 'No request data yet.')}
      ${_lgdWidget('Most Transferred Items', 'ti-arrows-exchange', (iq.mostTransferredItems||[]).map(r=>({label:r.name, sub:`${r.transfers} transfer(s), ${r.qty} ${r.uom} · 90d`, badge:'Top'})), 'No transfer data yet.')}
      ${_lgdWidget('Inventory Aging', 'ti-clock-hour-4', (iq.agingItems||[]).map(r=>({label:r.name, sub:r.category, badge:`${r.days_idle}d idle`, warn:r.days_idle>=60})), 'No aging data.')}
    </div>

    <div class="card" style="margin-bottom:1.25rem">
      <h3 style="margin:0 0 .75rem"><i class="ti ti-telescope"></i> Inventory Forecast <span style="font-size:11px;font-weight:400;color:var(--t3)">· ${iq.forecast?.basis || 'estimate based on recent activity'}</span></h3>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:.75rem;margin-bottom:1rem">
        <div style="background:var(--bg2);border-radius:6px;padding:.6rem .75rem"><div style="font-size:10px;color:var(--t3);text-transform:uppercase">Expected consumption</div><div style="font-size:18px;font-weight:700">${(iq.forecast?.expectedConsumption||0).toLocaleString()}</div><div style="font-size:11px;color:var(--t3)">units next month</div></div>
        <div style="background:var(--bg2);border-radius:6px;padding:.6rem .75rem"><div style="font-size:10px;color:var(--t3);text-transform:uppercase">Expected receiving</div><div style="font-size:18px;font-weight:700">${(iq.forecast?.expectedReceiving||0).toLocaleString()}</div><div style="font-size:11px;color:var(--t3)">units next month</div></div>
        <div style="background:var(--bg2);border-radius:6px;padding:.6rem .75rem"><div style="font-size:10px;color:var(--t3);text-transform:uppercase">Expected transfers</div><div style="font-size:18px;font-weight:700">${iq.forecast?.expectedTransfers||0}</div><div style="font-size:11px;color:var(--t3)">requests next month</div></div>
        <div style="background:var(--bg2);border-radius:6px;padding:.6rem .75rem"><div style="font-size:10px;color:var(--t3);text-transform:uppercase">Expected inventory level</div><div style="font-size:18px;font-weight:700">${(iq.forecast?.expectedInventoryLevel||0).toLocaleString()}</div><div style="font-size:11px;color:var(--t3)">units, end of next month</div></div>
      </div>
      <div style="font-size:12px;font-weight:700;color:var(--t3);margin-bottom:.5rem;text-transform:uppercase;letter-spacing:.03em">Reorder Watch List</div>
      ${(iq.reorderWatchList||[]).length ? `
      <div class="tw"><table class="tbl">
        <thead><tr><th>Item</th><th>Stock</th><th>Days remaining</th><th>Risk</th></tr></thead>
        <tbody>${iq.reorderWatchList.map(r => `<tr>
          <td style="font-weight:500">${r.name}</td>
          <td style="font-family:var(--fm)">${r.total_stock} ${r.uom}</td>
          <td style="font-family:var(--fm);${r.days_remaining<=7?'color:var(--red);font-weight:700':'color:var(--amber)'}">${r.days_remaining}</td>
          <td><span class="badge ${r.riskLevel==='Critical'?'br':'ba'}">${r.riskLevel}</span></td>
        </tr>`).join('')}</tbody>
      </table></div>` : '<p style="color:var(--t3);font-size:12px;margin:0">No items projected to run out within 30 days at current consumption rates.</p>'}
    </div>

    ${procFilterBarHtml({
      searchId: 'inv-search', searchPlaceholder: 'Search name, SKU, category…',
      statusId: 'inv-status-filter', statusOptions: ['OK', 'Reorder', 'Out of stock'],
      clearId: 'inv-clear',
    })}
    <div class="card" style="padding:0">
      <div style="display:flex;align-items:center;justify-content:space-between;padding:1rem 1.25rem;border-bottom:1px solid var(--bdr)">
        <h3 style="margin:0"><i class="ti ti-stack"></i>Full stock register</h3>
        <span id="inv-count-label" style="font-size:12px;color:var(--t3)">${rows.length} item${rows.length!==1?'s':''}</span>
      </div>
      <div class="tw">
        <table class="tbl" id="inv-table">
          <thead><tr>
            <th data-sort-key="category">Category</th><th data-sort-key="name">Name</th><th data-sort-key="sku">SKU</th>
            <th data-sort-key="stock">Stock</th><th data-sort-key="min_stock">Min</th><th>UoM</th>
            <th data-sort-key="unit_cost">Unit cost (RWF)</th><th>Stock value (RWF)</th><th data-sort-key="_statusLabel">Status</th>
          </tr></thead>
          <tbody id="inv-tbody"></tbody>
        </table>
      </div>
    </div>
  `;

  function renderInvRows(list) {
    const tbody = $('inv-tbody');
    if (!list.length) {
      tbody.innerHTML = '<tr><td colspan="9" style="text-align:center;color:var(--t3);padding:3rem"><i class="ti ti-stack" style="font-size:2rem;display:block;margin-bottom:.5rem;opacity:.35"></i>No items match these filters.</td></tr>';
      $('inv-count-label').textContent = '0 items';
      return;
    }
    $('inv-count-label').textContent = `${list.length} item${list.length!==1?'s':''}`;
    tbody.innerHTML = list.map((r) => {
      const low = Number(r.stock) <= Number(r.min_stock);
      const out = Number(r.stock) === 0;
      const stockVal = Number(r.stock) * Number(r.unit_cost);
      return `<tr>
        <td><span class="badge bt">${r.category}</span></td>
        <td style="font-weight:500">${r.name}</td>
        <td style="font-family:var(--fm);color:var(--t3)">${r.sku || '—'}</td>
        <td style="${out?'color:var(--red);font-weight:700':low?'color:var(--amber);font-weight:600':''}">${r.stock}</td>
        <td style="color:var(--t3)">${r.min_stock}</td>
        <td>${r.uom}</td>
        <td style="font-family:var(--fm)">${Number(r.unit_cost).toLocaleString()}</td>
        <td style="font-family:var(--fm)">${Math.round(stockVal).toLocaleString()}</td>
        <td><span class="badge ${out?'br':low?'ba':'bg'}">${r._statusLabel}</span></td>
      </tr>`;
    }).join('');
  }

  renderInvRows(invFiltered());
  wireSortableTable($('inv-table'), invSort, invFiltered, renderInvRows);
  $('inv-search').oninput = (e) => { invState.search = e.target.value; renderInvRows(invFiltered()); };
  $('inv-status-filter').onchange = (e) => { invState.status = e.target.value; renderInvRows(invFiltered()); };
  $('inv-clear').onclick = () => { invState.search=''; invState.status=''; $('inv-search').value=''; $('inv-status-filter').value=''; renderInvRows(invFiltered()); };

  $('page-inventory').querySelectorAll('.inv-kpi-link').forEach(el => {
    el.onclick = () => {
      if (el.dataset.page) { showPage(el.dataset.page); return; }
      invState.status = el.dataset.filter;
      $('inv-status-filter').value = el.dataset.filter;
      renderInvRows(invFiltered());
      $('inv-table').scrollIntoView({ behavior: 'smooth', block: 'start' });
    };
  });

  $('invExport').onclick = async () => {
    const lines = [
      ['UFCL Inventory — Dashboard Report', new Date().toLocaleString()],
      [],
      ['Executive KPIs', ''],
      ['Total items', d.totalItems||0], ['Inventory value (RWF)', Math.round(d.totalValue||0)],
      ['Available stock', d.availableStock||0], ['In transit', d.reservedStock||0],
      ['Low stock', d.lowStockCount||0], ['Out of stock', d.outOfStockCount||0],
      ['Goods received this month', d.goodsReceivedThisMonth||0], ['Transfers pending', d.transfersPending||0],
      ['Material requests pending', d.materialRequestsPending||0], ['Adjustments this month', d.adjustmentsThisMonth||0],
      ['Consumption this month', d.consumptionThisMonth||0], ['Turnover', d.turnoverRatio||0],
      [],
      ['Inventory Health', ''],
      ['Healthy', iq.health?.healthy||0], ['Low', iq.health?.low||0], ['Critical', iq.health?.critical||0],
      ['Inactive', iq.health?.inactive||0], ['Fast-moving', iq.health?.fastMoving||0], ['Slow-moving', iq.health?.slowMoving||0],
      [],
      ['Forecast (next month, estimate)', ''],
      ['Expected consumption', iq.forecast?.expectedConsumption||0], ['Expected receiving', iq.forecast?.expectedReceiving||0],
      ['Expected transfers', iq.forecast?.expectedTransfers||0], ['Expected inventory level', iq.forecast?.expectedInventoryLevel||0],
      [],
      ['Consumption Trend — Month', 'Units'], ...(iq.consumptionTrendMonths||[]).map(m => [m.month, m.value]),
      [], ['Receiving Trend — Month', 'Units'], ...(iq.receivingTrendMonths||[]).map(m => [m.month, m.value]),
      [], ['Transfer Trend — Month', 'Requests'], ...(iq.transferTrendMonths||[]).map(m => [m.month, m.value]),
      [], ['Adjustment Trend — Month', 'Count'], ...(iq.adjustmentTrendMonths||[]).map(m => [m.month, m.value]),
      [], ['Reorder Watch List — Item', 'Stock', 'Days Remaining', 'Risk'], ...(iq.reorderWatchList||[]).map(r => [r.name, `${r.total_stock} ${r.uom}`, r.days_remaining, r.riskLevel]),
      [], ['Most Consumed — Item', 'Qty (90d)'], ...(iq.mostConsumedItems||[]).map(r => [r.name, r.total]),
      [], ['Most Requested — Item', 'Requests (90d)'], ...(iq.mostRequestedItems||[]).map(r => [r.name, r.requests]),
      [], ['Most Transferred — Item', 'Transfers (90d)'], ...(iq.mostTransferredItems||[]).map(r => [r.name, r.transfers]),
      [],
      ['Category', 'Name', 'SKU', 'Stock', 'Min', 'UoM', 'Unit cost (RWF)', 'Status'],
      ...rows.map(r => [r.category, r.name, r.sku||'', r.stock, r.min_stock, r.uom, r.unit_cost, r._statusLabel]),
    ];
    const csv = lines.map(row => row.map(c => `"${String(c ?? '').replace(/"/g, '""')}"`).join(',')).join('\r\n');
    const filename = `inventory_dashboard_${new Date().toISOString().slice(0, 10)}.csv`;
    const res2 = await UFCL.execExport(STORAGE.user.id, { csv, filename });
    if (!res2?.ok && res2?.error !== undefined) showToast('Export cancelled or failed', 'error');
  };

  bindWorkshopBanner(renderInventory);
}

async function renderSage() {
  const month = new Date().toISOString().slice(0, 7);

  $('page-sage').innerHTML = `
    <div class="ptitle">Sage Reconciliation</div>
    <div class="psub">Review and export monthly expense data for Sage accounting reconciliation.</div>
    <div class="card">
      <h3><i class="ti ti-refresh"></i>Select month</h3>
      <div class="frow">
        <div class="fg"><label>Month</label><input type="month" id="sage-month" value="${month}"></div>
      </div>
      <div class="brow" style="margin-top:.75rem">
        <button class="bp1" id="sageLoad"><i class="ti ti-refresh"></i>Load data</button>
        <button class="bs1" id="sageExport" disabled><i class="ti ti-file-export"></i>Export to Sage CSV</button>
      </div>
    </div>
    <div id="sage-panel"></div>
  `;

  let lastSummary = [];
  let lastTotals = {};
  let lastMonth = month;

  async function loadSage() {
    const m = $('sage-month').value || month;
    lastMonth = m;
    const res = await UFCL.weeklyCost(STORAGE.user.id);
    if (!res.ok) return alert(res.error || 'Failed to load data');

    const { summary = [], totals = {}, weekNumber } = res;
    lastSummary = summary;
    lastTotals = totals;

    $('sage-panel').innerHTML = `
      <div class="card">
        <h3><i class="ti ti-table"></i>Expense summary — ${m} (current week: ${weekNumber})</h3>
        <div class="tw">
          <table class="dt">
            <thead><tr><th>Category</th><th>This week (RWF)</th><th>Month to date (RWF)</th><th>Budget (RWF)</th><th>Variance</th><th>Reconciliation</th></tr></thead>
            <tbody>
              ${summary.map((cat) => `<tr>
                <td>${cat.name}</td>
                <td style="font-family:var(--fm)">${Number(cat.week_amount || 0).toLocaleString()}</td>
                <td style="font-family:var(--fm)">${Number(cat.month_amount || 0).toLocaleString()}</td>
                <td style="font-family:var(--fm)">${Number(cat.budget || 0).toLocaleString()}</td>
                <td style="color:${cat.variance > 5 ? 'var(--red)' : cat.variance > 0 ? 'var(--amber)' : 'var(--green)'}">${Number(cat.variance || 0).toFixed(1)}%</td>
                <td><span class="badge ${cat.status === 'red' ? 'br' : cat.status === 'amber' ? 'ba' : 'bg'}">${cat.status === 'red' ? 'Review needed' : cat.status === 'amber' ? 'Monitor' : 'Clear'}</span></td>
              </tr>`).join('')}
              <tr style="font-weight:600;border-top:2px solid var(--bdr)">
                <td>Total</td>
                <td style="font-family:var(--fm)">RWF ${Number(totals.week || 0).toLocaleString()}</td>
                <td style="font-family:var(--fm)">RWF ${Number(totals.month || 0).toLocaleString()}</td>
                <td style="font-family:var(--fm)">RWF ${Number(totals.budget || 0).toLocaleString()}</td>
                <td>${Number(totals.variance || 0).toFixed(1)}%</td>
                <td></td>
              </tr>
            </tbody>
          </table>
        </div>
      </div>
    `;
    const expBtn = $('sageExport');
    if (expBtn) expBtn.disabled = false;
  }

  $('sageLoad').onclick = loadSage;
  $('sageExport').onclick = () => {
    if (!lastSummary.length) return;
    const lines = ['Category,Week Amount (RWF),Month to Date (RWF),Budget (RWF),Variance %,Status'];
    for (const cat of lastSummary) {
      lines.push(`"${cat.name}",${cat.week_amount || 0},${cat.month_amount || 0},${cat.budget || 0},${Number(cat.variance || 0).toFixed(1)},${cat.status}`);
    }
    lines.push(`Total,${lastTotals.week || 0},${lastTotals.month || 0},${lastTotals.budget || 0},${Number(lastTotals.variance || 0).toFixed(1)},`);
    downloadCsv(lines.join('\n'), `sage-reconciliation-${lastMonth}.csv`);
  };

  await loadSage();
}

// ── Warehouses ────────────────────────────────────────────────────────────────

// ── Logistics Dashboard ───────────────────────────────────────────────────────

async function renderLogisticsDashboard() {
  const pg = $('page-logistics-dashboard');
  pg.innerHTML = `<div style="padding:2rem;color:var(--t3);font-size:13px"><i class="ti ti-loader-2" style="font-size:18px;animation:spin 1s linear infinite"></i> Loading…</div>`;

  const res = await UFCL.logisticsDashboard(STORAGE.user.id);
  if (!res.ok) return renderDenied('logistics-dashboard', res.error);

  const { workshops, lowStock, recentMovements, monthTotals } = res;
  const {
    deliveryStatusCounts = [], dispatchStatusCounts = [], transportJobStatusCounts = [],
    fleetStatusCounts = [], vehiclesInUse = 0, fuelThisMonth = { total_liters: 0, total_cost: 0, log_count: 0 },
    pendingActions = { dispatchApprovals: 0, editRequests: 0 },
    // Phase 3 — Enterprise Operations Dashboard
    deliveriesToday = 0, deliveriesThisWeek = 0,
    delayedDeliveriesCount = 0, delayedTransportJobsCount = 0,
    delayedDeliveries = [], delayedTransportJobs = [],
    activeDriversCount = 0, fleetActiveCount = 0, fleetUtilizationPct = 0, vehicleAvailability = 0,
    workshopAlertsCount = 0, workshopAlerts = [],
    todaysDeliveries = [], todaysTransportJobs = [],
    activeDeliveries = [], vehiclesOnRoute = [], vehiclesWaiting = [], priorityDeliveries = [],
  } = res;
  const totalItems  = workshops.reduce((s, w) => s + Number(w.item_count || 0), 0);
  const totalValue  = workshops.reduce((s, w) => s + Number(w.stock_value || 0), 0);
  const totalQty    = workshops.reduce((s, w) => s + Number(w.total_qty || 0), 0);
  const isRestricted = !!res.user_workshop_id;

  const cntOf = (list, status) => Number((list.find(r => r.status === status) || {}).cnt || 0);
  const totalPendingActions = Number(pendingActions.dispatchApprovals || 0) + Number(pendingActions.editRequests || 0);
  const totalDeliveries = deliveryStatusCounts.reduce((s, r) => s + Number(r.cnt || 0), 0);
  const totalDispatch = dispatchStatusCounts.reduce((s, r) => s + Number(r.cnt || 0), 0);
  const totalTransportJobs = transportJobStatusCounts.reduce((s, r) => s + Number(r.cnt || 0), 0);
  const transportSpend = transportJobStatusCounts.reduce((s, r) => s + Number(r.total_cost || 0), 0);
  const fleetTotal = fleetStatusCounts.reduce((s, r) => s + Number(r.cnt || 0), 0);

  const movTypeColor = t => ({ in:'var(--green)', out:'var(--red)', adjustment:'var(--amber)', transfer:'#1D4ED8', return:'var(--g-soft)' }[t] || 'var(--t3)');
  const movTypeBadge = t => {
    const cls = { in:'bg', out:'br', adjustment:'ba', transfer:'bb', return:'bt' }[t] || 'bt';
    return `<span class="badge ${cls}">${t}</span>`;
  };

  const thisMonth = monthTotals.reduce((acc, r) => { acc[r.movement_type] = r; return acc; }, {});

  // Phase C9 — live permission audit found several roles that hold
  // 'logistics-dashboard' (storekeeper, logistics-officer, and even
  // 'logistics' itself for transport-jobs) do NOT hold every drill-down
  // target's own page permission — same pattern as the Executive/Procurement
  // dashboards (Phases C7/C8). Only render a tile clickable for a viewer who
  // actually holds the destination's permission.
  const _pages = STORAGE.pages || [];
  const dpAttr = (target) => _pages.includes(target) ? `data-page="${target}"` : '';

  pg.innerHTML = `
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:1rem">
      <div class="ptitle"><i class="ti ti-chart-pie-2" style="color:var(--g-soft)"></i> Logistics Dashboard</div>
      <button class="bs1" id="lgd-export" style="flex-shrink:0"><i class="ti ti-file-download"></i>Export report</button>
    </div>
    <div class="psub">${isRestricted
      ? `Showing data for your assigned workshop: <strong>${workshops[0]?.name || ''}</strong>.`
      : 'Cross-workshop stock overview — all workshops, stock levels, movements, and low-stock alerts.'
    }</div>

    <!-- Phase 3 — Executive KPIs: operations command-center strip -->
    <!-- Phase C9 — each tile with a real, single-page destination navigates
         there via the shared [data-page] wiring below (same pattern as
         Executive/Procurement dashboards, Phases C7/C8). "Pending approvals"
         combines two different sources (dispatch approvals + generic edit
         requests) with no single owning page, and "Active drivers" has no
         dedicated page — both deliberately left non-interactive rather than
         guessing a destination. -->
    <div style="font-weight:600;font-size:13px;color:var(--t1);margin:1rem 0 .75rem"><i class="ti ti-dashboard" style="color:var(--g-soft)"></i> Executive KPIs</div>
    <div class="cards" style="margin-bottom:1.25rem">
      <div class="mc" ${dpAttr('deliveries')}><div class="mclbl">Deliveries today</div><div class="mcval">${deliveriesToday}</div><div class="mcsub cg"><i class="ti ti-truck-delivery"></i>scheduled</div></div>
      <div class="mc" ${dpAttr('deliveries')}><div class="mclbl">Deliveries this week</div><div class="mcval">${deliveriesThisWeek}</div><div class="mcsub cg"><i class="ti ti-calendar-week"></i>scheduled</div></div>
      <div class="mc" ${dpAttr('dispatch')}><div class="mclbl">Pending dispatches</div><div class="mcval" style="${cntOf(dispatchStatusCounts,'Pending')>0?'color:var(--amber)':''}">${cntOf(dispatchStatusCounts,'Pending')}</div><div class="mcsub ${cntOf(dispatchStatusCounts,'Pending')>0?'ca':'cg'}"><i class="ti ti-clock"></i>awaiting approval</div></div>
      <div class="mc" ${dpAttr('dispatch')}><div class="mclbl">Completed dispatches</div><div class="mcval">${cntOf(dispatchStatusCounts,'Dispatched')}</div><div class="mcsub cg"><i class="ti ti-circle-check"></i>dispatched</div></div>
      <div class="mc" ${dpAttr('deliveries')}><div class="mclbl">Delayed deliveries</div><div class="mcval" style="${delayedDeliveriesCount>0?'color:var(--red)':''}">${delayedDeliveriesCount}</div><div class="mcsub ${delayedDeliveriesCount>0?'cr':'cg'}"><i class="ti ti-alert-triangle"></i>past due date</div></div>
      <div class="mc" ${dpAttr('transport-jobs')}><div class="mclbl">Transport jobs</div><div class="mcval">${totalTransportJobs}</div><div class="mcsub cg"><i class="ti ti-truck-loading"></i>all statuses</div></div>
      <div class="mc" ${dpAttr('vehicles')}><div class="mclbl">Fleet utilization</div><div class="mcval">${fleetUtilizationPct}%</div><div class="mcsub bp"><i class="ti ti-gauge"></i>${vehiclesInUse} of ${fleetActiveCount} active</div></div>
      <div class="mc" ${dpAttr('vehicles')}><div class="mclbl">Vehicle availability</div><div class="mcval">${vehicleAvailability}</div><div class="mcsub cg"><i class="ti ti-car"></i>ready now</div></div>
      <div class="mc" ${dpAttr('vehicles')}><div class="mclbl">Under maintenance</div><div class="mcval" style="${cntOf(fleetStatusCounts,'In Maintenance')>0?'color:var(--amber)':''}">${cntOf(fleetStatusCounts,'In Maintenance')}</div><div class="mcsub ${cntOf(fleetStatusCounts,'In Maintenance')>0?'ca':'cg'}"><i class="ti ti-tool"></i>vehicles</div></div>
      <div class="mc" ${dpAttr('machine-fuel')}><div class="mclbl">Fuel this month</div><div class="mcval" style="font-size:18px">${Number(fuelThisMonth.total_liters||0).toLocaleString()} L</div><div class="mcsub ca"><i class="ti ti-gas-station"></i>${Math.round(Number(fuelThisMonth.total_cost||0)).toLocaleString()} RWF</div></div>
      <div class="mc"><div class="mclbl">Active drivers</div><div class="mcval">${activeDriversCount}</div><div class="mcsub cg"><i class="ti ti-steering-wheel"></i>assigned</div></div>
      <div class="mc" ${dpAttr('inventory')}><div class="mclbl">Inventory alerts</div><div class="mcval" style="${lowStock.length>0?'color:var(--red)':''}">${lowStock.length}</div><div class="mcsub ${lowStock.length>0?'cr':'cg'}"><i class="ti ti-alert-triangle"></i>low stock</div></div>
      <div class="mc" ${dpAttr('vehicles')}><div class="mclbl">Workshop alerts</div><div class="mcval" style="${workshopAlertsCount>0?'color:var(--amber)':''}">${workshopAlertsCount}</div><div class="mcsub ${workshopAlertsCount>0?'ca':'cg'}"><i class="ti ti-alert-circle"></i>maintenance due</div></div>
      <div class="mc"><div class="mclbl">Pending approvals</div><div class="mcval" style="${totalPendingActions>0?'color:var(--amber)':''}">${totalPendingActions}</div><div class="mcsub ${totalPendingActions>0?'ca':'cg'}"><i class="ti ti-hourglass"></i>need review</div></div>
    </div>

    <!-- Warehouse & Stock Summary (Phase 1/2, pre-existing) -->
    <div class="cards" style="margin-bottom:1.25rem">
      <div class="mc" style="border-top:3px solid var(--g-soft)">
        <div class="mclbl">Workshops</div>
        <div class="mcval" style="color:var(--g-dark)">${workshops.length}</div>
        <div class="mcsub cg"><i class="ti ti-building-warehouse"></i>${workshops.filter(w=>w.active).length} active</div>
      </div>
      <div class="mc" style="border-top:3px solid #1D4ED8">
        <div class="mclbl">Unique items in stock</div>
        <div class="mcval">${totalItems.toLocaleString()}</div>
        <div class="mcsub cg"><i class="ti ti-package"></i>${totalQty.toLocaleString()} total units</div>
      </div>
      <div class="mc" style="border-top:3px solid var(--amber)">
        <div class="mclbl">Stock value</div>
        <div class="mcval" style="font-size:18px">K ${totalValue.toLocaleString('en', {minimumFractionDigits:0, maximumFractionDigits:0})}</div>
        <div class="mcsub cg"><i class="ti ti-currency-dollar"></i>all workshops</div>
      </div>
      <div class="mc" style="border-top:3px solid var(--red)">
        <div class="mclbl">Low stock alerts</div>
        <div class="mcval" style="color:${lowStock.length > 0 ? 'var(--red)' : 'var(--green)'}">${lowStock.length}</div>
        <div class="mcsub ${lowStock.length > 0 ? 'cr' : 'cg'}"><i class="ti ti-alert-triangle"></i>items at/below minimum</div>
      </div>
    </div>

    <!-- This month movement totals -->
    <div class="cards" style="margin-bottom:1.25rem">
      ${['in','out','transfer','adjustment'].map(t => {
        const m = thisMonth[t] || { cnt: 0, total_qty: 0 };
        const labels = { in:'Stock In', out:'Stock Out', transfer:'Transfers', adjustment:'Adjustments' };
        return `<div class="mc">
          <div class="mclbl">${labels[t]} this month</div>
          <div class="mcval" style="color:${movTypeColor(t)}">${Number(m.cnt || 0)}</div>
          <div class="mcsub cg"><i class="ti ti-arrows-exchange"></i>${Number(m.total_qty || 0).toLocaleString()} units</div>
        </div>`;
      }).join('')}
    </div>

    <!-- Phase 2 — Pending Actions banner -->
    ${totalPendingActions > 0 ? `<div style="display:flex;align-items:center;gap:.625rem;padding:.75rem 1rem;background:rgba(245,158,11,.07);border:1px solid rgba(245,158,11,.25);border-radius:7px;margin-bottom:1.25rem;font-size:13px;color:var(--amber)">
      <i class="ti ti-clock" style="font-size:16px;flex-shrink:0"></i>
      <strong style="margin-right:.25rem">${totalPendingActions} pending action${totalPendingActions>1?'s':''}</strong>
      ${pendingActions.dispatchApprovals ? `— ${pendingActions.dispatchApprovals} dispatch request${pendingActions.dispatchApprovals>1?'s':''} awaiting approval` : ''}
      ${pendingActions.editRequests ? `${pendingActions.dispatchApprovals?', ':'— '}${pendingActions.editRequests} edit/delete request${pendingActions.editRequests>1?'s':''} awaiting review` : ''}.
    </div>` : ''}

    <!-- Phase 2 — Operational KPI cards: Delivery / Dispatch / Transport Jobs / Fleet -->
    <div style="font-weight:600;font-size:13px;color:var(--t1);margin-bottom:.75rem"><i class="ti ti-gauge" style="color:var(--g-soft)"></i> Operational Overview</div>
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:1rem;margin-bottom:1.5rem">
      <div class="card" style="padding:1rem">
        <div style="font-weight:700;font-size:13px;margin-bottom:.6rem"><i class="ti ti-truck-delivery"></i> Delivery Status <span style="float:right;color:var(--t3);font-weight:500">${totalDeliveries} total</span></div>
        ${['Pending','Assigned','In Transit','POD Recorded','Failed'].map(s => `<div class="frow" style="justify-content:space-between;font-size:12px;padding:3px 0"><span style="color:var(--t3)">${s}</span><strong>${cntOf(deliveryStatusCounts,s)}</strong></div>`).join('')}
      </div>
      <div class="card" style="padding:1rem">
        <div style="font-weight:700;font-size:13px;margin-bottom:.6rem"><i class="ti ti-send"></i> Dispatch Summary <span style="float:right;color:var(--t3);font-weight:500">${totalDispatch} total</span></div>
        ${['Pending','Approved','Dispatched','Rejected'].map(s => `<div class="frow" style="justify-content:space-between;font-size:12px;padding:3px 0"><span style="color:var(--t3)">${s}</span><strong style="${s==='Pending'&&cntOf(dispatchStatusCounts,s)>0?'color:var(--amber)':''}">${cntOf(dispatchStatusCounts,s)}</strong></div>`).join('')}
      </div>
      <div class="card" style="padding:1rem">
        <div style="font-weight:700;font-size:13px;margin-bottom:.6rem"><i class="ti ti-truck-loading"></i> Transport Jobs <span style="float:right;color:var(--t3);font-weight:500">${totalTransportJobs} total</span></div>
        ${['Scheduled','In Transit','Completed','Cancelled'].map(s => `<div class="frow" style="justify-content:space-between;font-size:12px;padding:3px 0"><span style="color:var(--t3)">${s}</span><strong>${cntOf(transportJobStatusCounts,s)}</strong></div>`).join('')}
        <div class="frow" style="justify-content:space-between;font-size:12px;padding:5px 0 0;margin-top:4px;border-top:1px solid var(--bdr)"><span style="color:var(--t3)">Total spend</span><strong style="font-family:var(--fm)">${Math.round(transportSpend).toLocaleString()} RWF</strong></div>
      </div>
      <div class="card" style="padding:1rem">
        <div style="font-weight:700;font-size:13px;margin-bottom:.6rem"><i class="ti ti-car"></i> Fleet Intelligence <span style="float:right;color:var(--t3);font-weight:500">${fleetTotal} vehicles</span></div>
        ${['Active','In Maintenance','Inactive'].map(s => `<div class="frow" style="justify-content:space-between;font-size:12px;padding:3px 0"><span style="color:var(--t3)">${s}</span><strong>${cntOf(fleetStatusCounts,s)}</strong></div>`).join('')}
        <div class="frow" style="justify-content:space-between;font-size:12px;padding:5px 0 0;margin-top:4px;border-top:1px solid var(--bdr)"><span style="color:var(--t3)">Utilization</span><strong>${fleetUtilizationPct}%</strong></div>
        <div class="frow" style="justify-content:space-between;font-size:12px;padding:3px 0"><span style="color:var(--t3)">On a delivery now</span><strong>${vehiclesInUse}</strong></div>
        <div class="frow" style="justify-content:space-between;font-size:12px;padding:3px 0"><span style="color:var(--t3)">Available now</span><strong>${vehicleAvailability}</strong></div>
        <div class="frow" style="justify-content:space-between;font-size:12px;padding:3px 0"><span style="color:var(--t3)">Maintenance due (7d)</span><strong style="${workshopAlertsCount>0?'color:var(--amber)':''}">${workshopAlertsCount}</strong></div>
      </div>
      <div class="card" style="padding:1rem">
        <div style="font-weight:700;font-size:13px;margin-bottom:.6rem"><i class="ti ti-gas-station"></i> Fuel Overview <span style="float:right;color:var(--t3);font-weight:500">this month</span></div>
        <div class="frow" style="justify-content:space-between;font-size:12px;padding:3px 0"><span style="color:var(--t3)">Logs recorded</span><strong>${Number(fuelThisMonth.log_count||0)}</strong></div>
        <div class="frow" style="justify-content:space-between;font-size:12px;padding:3px 0"><span style="color:var(--t3)">Total liters</span><strong>${Number(fuelThisMonth.total_liters||0).toLocaleString()}</strong></div>
        <div class="frow" style="justify-content:space-between;font-size:12px;padding:3px 0"><span style="color:var(--t3)">Total cost</span><strong style="font-family:var(--fm)">${Math.round(Number(fuelThisMonth.total_cost||0)).toLocaleString()} RWF</strong></div>
        <div class="frow" style="justify-content:space-between;font-size:12px;padding:5px 0 0;margin-top:4px;border-top:1px solid var(--bdr)"><span style="color:var(--t3)">Avg cost / liter</span><strong style="font-family:var(--fm)">${Number(fuelThisMonth.total_liters||0)>0?Math.round(Number(fuelThisMonth.total_cost)/Number(fuelThisMonth.total_liters)).toLocaleString():'—'} RWF</strong></div>
      </div>
    </div>

    <!-- Phase 3 — Operational Widgets: what needs attention right now -->
    <div style="font-weight:600;font-size:13px;color:var(--t1);margin-bottom:.75rem"><i class="ti ti-list-details" style="color:var(--g-soft)"></i> Operational Widgets</div>
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:1rem;margin-bottom:1.5rem">
      ${_lgdWidget("Today's Schedule", 'ti-calendar', [...todaysDeliveries.map(d=>({label:d.order_number, sub:d.driver_name||'—', badge:d.status})), ...todaysTransportJobs.map(j=>({label:j.job_number, sub:j.carrier_type, badge:j.status}))], 'Nothing scheduled for today.')}
      ${_lgdWidget('Active Deliveries', 'ti-truck-delivery', activeDeliveries.map(d=>({label:d.order_number, sub:d.driver_name||'—', badge:d.status})), 'No deliveries in progress.')}
      ${_lgdWidget('Vehicles on Route', 'ti-map-pin', vehiclesOnRoute.map(v=>({label:v.registration, sub:v.driver_name||'—', badge:v.order_number})), 'No vehicles currently on route.')}
      ${_lgdWidget('Vehicles Waiting', 'ti-parking', vehiclesWaiting.map(v=>({label:v.registration, sub:v.driver_name||'Unassigned', badge:'Available'})), 'No vehicles currently available.')}
      ${_lgdWidget('Delayed Jobs', 'ti-alert-triangle', [...delayedDeliveries.map(d=>({label:d.order_number, sub:'Due '+d.delivery_date, badge:d.status, warn:true})), ...delayedTransportJobs.map(j=>({label:j.job_number, sub:'Due '+j.job_date, badge:j.status, warn:true}))], 'Nothing overdue.')}
      ${_lgdWidget('Priority Deliveries', 'ti-flag', priorityDeliveries.map(d=>({label:d.order_number, sub:d.driver_name||'—', badge:d.is_delayed?'Overdue':'Due today', warn:d.is_delayed})), 'No urgent deliveries.')}
      ${_lgdWidget('Stock Warnings', 'ti-alert-circle', lowStock.map(s=>({label:s.name, sub:s.warehouse_name||'—', badge:`${s.total_stock}/${s.min_stock}`, warn:true})), 'No stock warnings.')}
      ${_lgdWidget('Workshop Notifications', 'ti-tool', workshopAlerts.map(m=>({label:m.vehicle_registration, sub:m.maintenance_type, badge:m.next_due_date, warn:true})), 'No maintenance due soon.')}
    </div>

    <!-- Per-workshop cards -->
    <div style="font-weight:600;font-size:13px;color:var(--t1);margin-bottom:.75rem"><i class="ti ti-building-warehouse" style="color:var(--g-soft)"></i> Workshop Stock Summary</div>
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:1rem;margin-bottom:1.5rem">
      ${workshops.length ? workshops.map(w => {
        const val = Number(w.stock_value || 0);
        return `<div style="background:var(--surf);border:1px solid var(--bdr);border-radius:10px;padding:1.25rem;border-top:3px solid var(--g-soft)">
          <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:.5rem;margin-bottom:.875rem">
            <div>
              <div style="font-weight:700;font-size:15px;color:var(--g-dark)">${w.name}</div>
              <div style="font-size:11px;color:var(--t3);margin-top:2px"><i class="ti ti-map-pin" style="font-size:10px"></i> ${w.location || 'No location'}</div>
            </div>
            <span class="badge ${w.active ? 'bg' : 'br'}">${w.active ? 'Active' : 'Inactive'}</span>
          </div>
          <div style="display:grid;grid-template-columns:1fr 1fr;gap:.75rem">
            <div style="background:var(--bg2);border-radius:6px;padding:.625rem">
              <div style="font-size:10px;color:var(--t3);text-transform:uppercase;letter-spacing:.04em">Items</div>
              <div style="font-weight:700;font-family:var(--fm);font-size:18px;color:var(--t1)">${Number(w.item_count || 0)}</div>
            </div>
            <div style="background:var(--bg2);border-radius:6px;padding:.625rem">
              <div style="font-size:10px;color:var(--t3);text-transform:uppercase;letter-spacing:.04em">Total units</div>
              <div style="font-weight:700;font-family:var(--fm);font-size:18px;color:var(--t1)">${Number(w.total_qty || 0).toLocaleString()}</div>
            </div>
          </div>
          <div style="margin-top:.75rem;padding:.5rem .625rem;background:var(--g-light);border-radius:6px;border:1px solid rgba(30,95,54,.15)">
            <div style="font-size:10px;color:var(--g-dark);text-transform:uppercase;letter-spacing:.04em">Stock value</div>
            <div style="font-weight:700;font-family:var(--fm);color:var(--g-dark)">K ${val.toLocaleString('en',{minimumFractionDigits:2,maximumFractionDigits:2})}</div>
          </div>
        </div>`;
      }).join('')
      : `<div style="grid-column:1/-1;text-align:center;padding:2rem;color:var(--t3)">No workshops found.</div>`}
    </div>

    <!-- Low stock alerts -->
    ${lowStock.length ? `
    <div class="card" style="padding:0;margin-bottom:1.25rem">
      <div style="display:flex;align-items:center;gap:.625rem;padding:.875rem 1.25rem;background:rgba(239,68,68,.05);border-bottom:1px solid rgba(239,68,68,.15);border-radius:8px 8px 0 0">
        <i class="ti ti-alert-triangle" style="color:var(--red)"></i>
        <span style="font-weight:600;font-size:13px;color:var(--red)">${lowStock.length} low-stock alert${lowStock.length > 1 ? 's' : ''}</span>
      </div>
      <div class="tw"><table class="dt">
        <thead><tr><th>Item</th><th>Category</th><th>Workshop</th><th>Current stock</th><th>Minimum</th><th>UOM</th></tr></thead>
        <tbody>
          ${lowStock.map(r => `<tr>
            <td style="font-weight:600">${r.name}</td>
            <td><span class="badge bt">${r.category}</span></td>
            <td style="color:var(--t3)">${r.warehouse_name || '—'}</td>
            <td style="font-family:var(--fm);font-weight:700;color:var(--red)">${r.total_stock}</td>
            <td style="font-family:var(--fm);color:var(--t3)">${r.min_stock}</td>
            <td style="color:var(--t3)">${r.uom}</td>
          </tr>`).join('')}
        </tbody>
      </table></div>
    </div>` : ''}

    <!-- Recent movements -->
    <div class="card" style="padding:0">
      <div style="padding:.875rem 1.25rem;border-bottom:1px solid var(--bdr)">
        <h3 style="margin:0"><i class="ti ti-arrows-exchange"></i>Recent stock movements</h3>
      </div>
      <div class="tw"><table class="dt">
        <thead><tr><th>Date/Time</th><th>Item</th><th>Workshop</th><th>Type</th><th>Qty</th><th>By</th></tr></thead>
        <tbody>
          ${recentMovements.length ? recentMovements.map(r => `<tr>
            <td style="font-size:12px;color:var(--t3);font-family:var(--fm)">${r.created_at}</td>
            <td style="font-weight:500">${r.item_name}<br><span style="font-size:11px;color:var(--t3)">${r.category}</span></td>
            <td style="color:var(--t3);font-size:12px">${r.workshop_name || '—'}</td>
            <td>${movTypeBadge(r.movement_type)}</td>
            <td style="font-family:var(--fm);font-weight:600">${Number(r.quantity)} ${r.uom}</td>
            <td style="color:var(--t3);font-size:12px">${r.created_by || '—'}</td>
          </tr>`).join('')
          : emptyRowHtml({ colspan: 6, icon: 'ti-arrows-exchange', title: 'No movements yet.' })}
        </tbody>
      </table></div>
    </div>`;

  pg.querySelectorAll('[data-page]').forEach(el => { el.onclick = () => showPage(el.dataset.page); });

  // Phase 2 — genuine operational report export (native save dialog, same
  // convention as every other Reports page in the app).
  $('lgd-export').onclick = async () => {
    const lines = [
      ['UFCL Logistics — Operational Report', new Date().toLocaleString()],
      [],
      ['Executive KPIs', ''],
      ['Deliveries today', deliveriesToday], ['Deliveries this week', deliveriesThisWeek],
      ['Pending dispatches', cntOf(dispatchStatusCounts,'Pending')], ['Completed dispatches', cntOf(dispatchStatusCounts,'Dispatched')],
      ['Delayed deliveries', delayedDeliveriesCount], ['Delayed transport jobs', delayedTransportJobsCount],
      ['Transport jobs (all statuses)', totalTransportJobs],
      ['Fleet utilization %', fleetUtilizationPct], ['Vehicle availability', vehicleAvailability],
      ['Vehicles under maintenance', cntOf(fleetStatusCounts,'In Maintenance')],
      ['Active drivers', activeDriversCount],
      ['Inventory alerts', lowStock.length], ['Workshop alerts', workshopAlertsCount],
      ['Pending approvals (total)', totalPendingActions],
      [],
      ['Delivery Status', 'Count'], ...deliveryStatusCounts.map(r => [r.status, r.cnt]),
      [], ['Dispatch Status', 'Count'], ...dispatchStatusCounts.map(r => [r.status, r.cnt]),
      [], ['Transport Job Status', 'Count', 'Total Cost (RWF)'], ...transportJobStatusCounts.map(r => [r.status, r.cnt, r.total_cost]),
      [], ['Fleet Status', 'Count'], ...fleetStatusCounts.map(r => [r.status, r.cnt]),
      ['Vehicles currently on a delivery', vehiclesInUse],
      [], ['Fuel this month — logs', fuelThisMonth.log_count], ['Fuel this month — liters', fuelThisMonth.total_liters], ['Fuel this month — cost (RWF)', fuelThisMonth.total_cost],
      [], ['Pending dispatch approvals', pendingActions.dispatchApprovals], ['Pending edit/delete requests', pendingActions.editRequests],
      [], ['Delayed Delivery Order #', 'Due Date', 'Status', 'Driver'], ...delayedDeliveries.map(r => [r.order_number, r.delivery_date, r.status, r.driver_name||'']),
      [], ['Delayed Transport Job #', 'Due Date', 'Status'], ...delayedTransportJobs.map(r => [r.job_number, r.job_date, r.status]),
      [], ['Workshop Alert — Vehicle', 'Maintenance Type', 'Due Date'], ...workshopAlerts.map(r => [r.vehicle_registration, r.maintenance_type, r.next_due_date]),
      [], ['Workshop', 'Items', 'Total Qty', 'Stock Value (RWF)'], ...workshops.map(w => [w.name, w.item_count, w.total_qty, w.stock_value]),
      [], ['Low Stock Item', 'Category', 'Workshop', 'Current Stock', 'Minimum', 'UoM'], ...lowStock.map(r => [r.name, r.category, r.warehouse_name||'', r.total_stock, r.min_stock, r.uom]),
    ];
    const csv = lines.map(row => row.map(c => `"${String(c ?? '').replace(/"/g, '""')}"`).join(',')).join('\r\n');
    const filename = `logistics_operational_report_${new Date().toISOString().slice(0, 10)}.csv`;
    const res2 = await UFCL.execExport(STORAGE.user.id, { csv, filename });
    if (!res2?.ok && res2?.error !== undefined) showToast('Export cancelled or failed', 'error');
  };
}

// ── Workshop Overview ─────────────────────────────────────────────────────────

const WORKSHOP_TYPE_ICONS = {
  'Sawmill Workshop':            'ti-cut',
  'Logging Equipment Workshop':  'ti-trees',
  'Vehicle Workshop':            'ti-truck',
  'Pole Treatment Workshop':     'ti-flame',
  'Electrical Workshop':         'ti-bolt',
  'Central Warehouse':           'ti-building-warehouse',
};

async function renderWorkshopOverview() {
  const res = await UFCL.workshopOverview(STORAGE.user.id);
  if (!res.ok) return renderDenied('workshop-overview', res.error);
  const canApprove = ['admin','ceo','operations','logistics','supervisor'].includes(STORAGE.user?.role);

  const priorityBadge = p => p==='urgent'?`<span class="badge br" style="font-size:10px">Urgent</span>`:p==='high'?`<span class="badge ba" style="font-size:10px">High</span>`:`<span class="badge bg" style="font-size:10px">Normal</span>`;

  // Phase 2 — Executive KPIs + Operational Widgets, mirroring the Logistics
  // Dashboard redesign pattern exactly (same _lgdWidget helper, same .mc
  // card family — no new visual language).
  const {
    totalMachines = 0, availableMachines = 0, activeMaintenanceCount = 0, machineAvailabilityPct = 0,
    scheduledMaintenanceCount = 0, overdueMaintenanceCount = 0, fuelConsumedThisMonth = 0, downtimeHoursThisMonth = 0,
    workshopCostsThisMonth = 0, todaysMaintenance = [], upcomingMaintenance = [], overdueMaintenanceList = [],
    equipmentAlerts = [], fleetAlerts = [], workshopNotifications = [],
    // Phase 3
    workshopUtilizationPct = 0, maintenanceThisMonthCount = 0, costTrendMonths = [], maintenanceTrendMonths = [],
  } = res;
  const materialRequestsPendingCount = (res.pendingRequests || []).length;
  const totalPendingApprovals = materialRequestsPendingCount + (res.pendingTransfers || []).length;

  $('page-workshop-overview').innerHTML = `
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:1rem">
      <div class="ptitle"><i class="ti ti-layout-dashboard" style="color:var(--g-soft)"></i> Workshop Dashboard</div>
      <button class="bs1" id="wsd-export" style="flex-shrink:0"><i class="ti ti-file-download"></i>Export report</button>
    </div>
    <div class="psub">Live view across all workshops — stock, machines, maintenance, and material requests.</div>

    <!-- Phase 2 — Executive KPIs -->
    <div style="font-weight:600;font-size:13px;color:var(--t1);margin:1rem 0 .75rem"><i class="ti ti-dashboard" style="color:var(--g-soft)"></i> Executive KPIs</div>
    <div class="cards" style="margin-bottom:1.25rem">
      <div class="mc"><div class="mclbl">Machines</div><div class="mcval">${totalMachines}</div><div class="mcsub cg"><i class="ti ti-settings-2"></i>registered</div></div>
      <div class="mc"><div class="mclbl">Machines available</div><div class="mcval" style="color:var(--green)">${availableMachines}</div><div class="mcsub cg"><i class="ti ti-circle-check"></i>ready for use</div></div>
      <div class="mc"><div class="mclbl">Active maintenance</div><div class="mcval" style="${activeMaintenanceCount>0?'color:var(--amber)':''}">${activeMaintenanceCount}</div><div class="mcsub ${activeMaintenanceCount>0?'ca':'cg'}"><i class="ti ti-tool"></i>in progress</div></div>
      <div class="mc"><div class="mclbl">Scheduled maintenance</div><div class="mcval">${scheduledMaintenanceCount}</div><div class="mcsub cg"><i class="ti ti-calendar"></i>next 7 days</div></div>
      <div class="mc"><div class="mclbl">Overdue maintenance</div><div class="mcval" style="${overdueMaintenanceCount>0?'color:var(--red)':''}">${overdueMaintenanceCount}</div><div class="mcsub ${overdueMaintenanceCount>0?'cr':'cg'}"><i class="ti ti-alert-triangle"></i>past due</div></div>
      <div class="mc"><div class="mclbl">Maintenance this month</div><div class="mcval">${maintenanceThisMonthCount}</div><div class="mcsub cg"><i class="ti ti-checkbox"></i>completed</div></div>
      <div class="mc"><div class="mclbl">Workshop utilization</div><div class="mcval">${workshopUtilizationPct}%</div><div class="mcsub bp"><i class="ti ti-chart-bar"></i>hours worked vs downtime</div></div>
      <div class="mc"><div class="mclbl">Fuel this month</div><div class="mcval" style="font-size:18px">${fuelConsumedThisMonth.toLocaleString()} L</div><div class="mcsub ca"><i class="ti ti-gas-station"></i>machine logs</div></div>
      <div class="mc"><div class="mclbl">Machine availability</div><div class="mcval">${machineAvailabilityPct}%</div><div class="mcsub bp"><i class="ti ti-gauge"></i>${availableMachines} of ${totalMachines} available</div></div>
      <div class="mc"><div class="mclbl">Downtime this month</div><div class="mcval" style="${downtimeHoursThisMonth>0?'color:var(--amber)':''}">${downtimeHoursThisMonth.toLocaleString()}</div><div class="mcsub ${downtimeHoursThisMonth>0?'ca':'cg'}"><i class="ti ti-clock-x"></i>hours</div></div>
      <div class="mc"><div class="mclbl">Material requests</div><div class="mcval" style="${materialRequestsPendingCount>0?'color:var(--amber)':''}">${materialRequestsPendingCount}</div><div class="mcsub ${materialRequestsPendingCount>0?'ca':'cg'}"><i class="ti ti-clipboard-list"></i>pending</div></div>
      ${res.financeVisibility ? `<div class="mc"><div class="mclbl">Workshop costs</div><div class="mcval" style="font-size:18px">${workshopCostsThisMonth.toLocaleString()}</div><div class="mcsub ca"><i class="ti ti-coin"></i>RWF · parts this month</div></div>
      <div class="mc"><div class="mclbl">Maintenance costs</div><div class="mcval" style="font-size:18px">${res.financeVisibility.maintenanceCostThisMonth.toLocaleString()}</div><div class="mcsub ca"><i class="ti ti-currency-dollar"></i>RWF · this month</div></div>` : ''}
    </div>

    ${totalPendingApprovals > 0 ? `<div style="display:flex;align-items:center;gap:.625rem;padding:.75rem 1rem;background:rgba(245,158,11,.07);border:1px solid rgba(245,158,11,.25);border-radius:7px;margin-bottom:1.25rem;font-size:13px;color:var(--amber)">
      <i class="ti ti-clock" style="font-size:16px;flex-shrink:0"></i>
      <strong style="margin-right:.25rem">${totalPendingApprovals} pending action${totalPendingApprovals>1?'s':''}</strong>
      ${materialRequestsPendingCount ? `— ${materialRequestsPendingCount} material request${materialRequestsPendingCount>1?'s':''}` : ''}
      ${(res.pendingTransfers||[]).length ? `${materialRequestsPendingCount?', ':'— '}${res.pendingTransfers.length} stock transfer${res.pendingTransfers.length>1?'s':''}` : ''} awaiting approval.
    </div>` : ''}

    <!-- Phase 2 — Operational Widgets -->
    <div style="font-weight:600;font-size:13px;color:var(--t1);margin-bottom:.75rem"><i class="ti ti-list-details" style="color:var(--g-soft)"></i> Operational Widgets</div>
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:1rem;margin-bottom:1.5rem">
      ${_lgdWidget("Today's Maintenance", 'ti-calendar', todaysMaintenance.map(s=>({label:s.machine_code+' — '+s.machine_name, sub:s.maintenance_type, badge:'Today', warn:true})), 'Nothing scheduled for today.')}
      ${_lgdWidget('Upcoming Maintenance', 'ti-calendar-time', upcomingMaintenance.map(s=>({label:s.machine_code+' — '+s.machine_name, sub:s.maintenance_type, badge:new Date(s.next_due).toLocaleDateString('en-GB')})), 'Nothing due in the next 7 days.')}
      ${_lgdWidget('Overdue Jobs', 'ti-alert-triangle', overdueMaintenanceList.map(s=>({label:s.machine_code+' — '+s.machine_name, sub:s.maintenance_type, badge:new Date(s.next_due).toLocaleDateString('en-GB'), warn:true})), 'Nothing overdue.')}
      ${_lgdWidget('Material Requests Waiting', 'ti-clipboard-list', (res.pendingRequests||[]).map(r=>({label:r.item_name, sub:r.workshop_name||'—', badge:r.priority, warn:r.priority==='urgent'})), 'No requests waiting.')}
      ${_lgdWidget('Low Stock Alerts', 'ti-alert-circle', (res.lowStock||[]).map(s=>({label:s.name, sub:s.warehouse_name||'—', badge:`${s.total_stock}/${s.min_stock}`, warn:true})), 'No low stock alerts.')}
      ${_lgdWidget('Equipment Alerts', 'ti-tool', equipmentAlerts.map(m=>({label:m.machine_code+' — '+m.name, sub:m.status, badge:m.status, warn:true})), 'No equipment issues.')}
      ${res.financeVisibility ? _lgdWidget('Fleet Alerts', 'ti-truck', fleetAlerts.map(v=>({label:v.vehicle_registration, sub:v.maintenance_type, badge:v.next_due_date, warn:true})), 'No vehicle maintenance due soon.') : ''}
      ${res.financeVisibility ? _lgdWidget('Workshop Notifications', 'ti-bell', workshopNotifications.map(n=>({label:n.action, sub:(n.full_name||n.username||'System')+' · '+new Date(n.created_at).toLocaleString(), badge:n.action_type||''})), 'No recent activity.') : ''}
    </div>

    <!-- Phase 3 — Operational Intelligence trends, reusing the existing
         shared inline-SVG chart helpers (_svgLine/_svgBar) rather than a
         new charting mechanism. -->
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:1rem;margin-bottom:1.25rem">
      <div class="card">
        <h3 style="margin:0 0 .75rem"><i class="ti ti-chart-line"></i> Maintenance Trend <span style="font-size:11px;font-weight:400;color:var(--t3)">· last 6 months, completed jobs</span></h3>
        ${_svgBar(maintenanceTrendMonths, 'cnt', { color: 'var(--g-soft)' })}
        <div style="display:flex;justify-content:space-between;margin-top:.4rem;font-size:10px;color:var(--t3)">
          ${maintenanceTrendMonths.map(m => `<span>${m.month.slice(5)}</span>`).join('')}
        </div>
      </div>
      ${res.financeVisibility ? `
      <div class="card">
        <h3 style="margin:0 0 .75rem"><i class="ti ti-chart-line"></i> Cost Trend <span style="font-size:11px;font-weight:400;color:var(--t3)">· last 6 months, RWF</span></h3>
        ${_svgLine(costTrendMonths, 'total', { color: 'var(--amber)' })}
        <div style="display:flex;justify-content:space-between;margin-top:.4rem;font-size:10px;color:var(--t3)">
          ${costTrendMonths.map(m => `<span>${m.month.slice(5)}</span>`).join('')}
        </div>
      </div>` : ''}
    </div>

    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:1rem;margin:1.25rem 0">
      ${res.workshops.map(w => {
        const ic = WORKSHOP_TYPE_ICONS[w.workshop_type] || 'ti-building-warehouse';
        return `
        <div style="background:var(--surf);border:1px solid var(--bdr);border-radius:10px;padding:1.25rem;border-top:3px solid var(--g-soft)">
          <div style="display:flex;align-items:center;gap:.6rem;margin-bottom:.9rem">
            <span style="width:32px;height:32px;border-radius:8px;background:var(--g-soft);display:flex;align-items:center;justify-content:center;flex-shrink:0"><i class="ti ${ic}" style="color:#fff;font-size:15px"></i></span>
            <div>
              <div style="font-weight:700;font-size:14px;color:var(--t1)">${w.name}</div>
              <div style="font-size:11px;color:var(--t3)">${w.workshop_type||'Workshop'} ${w.location?'· '+w.location:''}</div>
            </div>
          </div>
          <div style="display:grid;grid-template-columns:1fr 1fr;gap:.6rem">
            <div style="background:var(--bg2);border-radius:6px;padding:.6rem .75rem">
              <div style="font-size:10px;color:var(--t3);text-transform:uppercase;letter-spacing:.06em">Machines</div>
              <div style="font-size:18px;font-weight:700;font-family:var(--fm)">${w.machine_count}</div>
              <div style="font-size:11px;color:var(--green)">${w.machines_available} available</div>
            </div>
            <div style="background:var(--bg2);border-radius:6px;padding:.6rem .75rem">
              <div style="font-size:10px;color:var(--t3);text-transform:uppercase;letter-spacing:.06em">Stock Value</div>
              <div style="font-size:16px;font-weight:700;font-family:var(--fm)">${Number(w.stock_value).toLocaleString()}</div>
              <div style="font-size:11px;color:var(--t3)">RWF · ${w.item_count} items</div>
            </div>
          </div>
          ${w.machines_maintenance>0?`<div style="margin-top:.6rem;font-size:11.5px;color:var(--amber);display:flex;align-items:center;gap:.35rem"><i class="ti ti-tool"></i>${w.machines_maintenance} machine${w.machines_maintenance>1?'s':''} under maintenance</div>`:''}
        </div>`;
      }).join('') || '<div style="color:var(--t3);padding:2rem;text-align:center">No workshops found.</div>'}
    </div>

    ${res.financeVisibility ? `
    <div class="card" style="margin-bottom:1rem">
      <h3 style="margin:0 0 .75rem"><i class="ti ti-currency-dollar"></i> Maintenance Cost — This Month</h3>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:.75rem">
        <div style="background:var(--bg2);border-radius:6px;padding:.6rem .75rem">
          <div style="font-size:10px;color:var(--t3);text-transform:uppercase;letter-spacing:.06em">Total Cost</div>
          <div style="font-size:18px;font-weight:700;font-family:var(--fm)">${res.financeVisibility.maintenanceCostThisMonth.toLocaleString()}</div>
          <div style="font-size:11px;color:var(--t3)">RWF · ${res.financeVisibility.maintenanceRecordCountThisMonth} record${res.financeVisibility.maintenanceRecordCountThisMonth!==1?'s':''}</div>
        </div>
        ${res.financeVisibility.maintenanceCostByType.slice(0,4).map(t => `
        <div style="background:var(--bg2);border-radius:6px;padding:.6rem .75rem">
          <div style="font-size:10px;color:var(--t3);text-transform:uppercase;letter-spacing:.06em">${t.type}</div>
          <div style="font-size:16px;font-weight:700;font-family:var(--fm)">${t.total.toLocaleString()}</div>
          <div style="font-size:11px;color:var(--t3)">RWF · ${t.count} record${t.count!==1?'s':''}</div>
        </div>`).join('')}
      </div>
      ${!res.financeVisibility.maintenanceCostByType.length ? '<p style="color:var(--t3);font-size:12px;margin:.5rem 0 0">No maintenance records logged this month.</p>' : ''}
    </div>` : ''}

    ${res.pendingTransfers.length ? `
    <div class="card" style="margin-bottom:1rem;padding:0">
      <div style="padding:.9rem 1.25rem;border-bottom:1px solid var(--bdr);display:flex;align-items:center;justify-content:space-between">
        <h3 style="margin:0;color:var(--amber)"><i class="ti ti-arrows-exchange"></i> Pending Transfers <span style="font-size:12px;font-weight:500;background:rgba(245,158,11,.12);color:var(--amber);padding:2px 8px;border-radius:10px;margin-left:.4rem">${res.pendingTransfers.length}</span></h3>
      </div>
      <table class="tbl">
        <thead><tr><th>Item</th><th>From</th><th>To</th><th>Qty</th><th>Requested</th><th>By</th>${canApprove?'<th></th>':''}</tr></thead>
        <tbody>
          ${res.pendingTransfers.map(t=>`
          <tr>
            <td>${t.item_name}<br><span style="font-size:11px;color:var(--t3)">${t.uom}</span></td>
            <td>${t.from_workshop||'—'}</td>
            <td>${t.to_workshop||'—'}</td>
            <td><strong>${t.quantity}</strong></td>
            <td style="font-size:12px;color:var(--t3)">${t.created_at}</td>
            <td style="font-size:12px">${t.requested_by||'—'}</td>
            ${canApprove?`<td style="white-space:nowrap">
              <button class="bs1 tr-approve" data-id="${t.id}" style="color:var(--green);padding:4px 8px;font-size:12px"><i class="ti ti-check"></i>Approve</button>
              <button class="bs1 tr-reject" data-id="${t.id}" style="color:var(--red);padding:4px 8px;font-size:12px"><i class="ti ti-x"></i>Reject</button>
            </td>`:''}
          </tr>`).join('')}
        </tbody>
      </table>
    </div>` : ''}

    ${res.pendingRequests.length ? `
    <div class="card" style="margin-bottom:1rem;padding:0">
      <div style="padding:.9rem 1.25rem;border-bottom:1px solid var(--bdr);display:flex;align-items:center;justify-content:space-between">
        <h3 style="margin:0;color:var(--blue)"><i class="ti ti-clipboard-list"></i> Pending Material Requests <span style="font-size:12px;font-weight:500;background:rgba(59,130,246,.12);color:var(--blue);padding:2px 8px;border-radius:10px;margin-left:.4rem">${res.pendingRequests.length}</span></h3>
      </div>
      <table class="tbl">
        <thead><tr><th>Item</th><th>Workshop</th><th>Qty</th><th>Priority</th><th>Reason</th><th>Requested</th>${canApprove?'<th></th>':''}</tr></thead>
        <tbody>
          ${res.pendingRequests.map(r=>`
          <tr>
            <td>${r.item_name}<br><span style="font-size:11px;color:var(--t3)">${r.uom}</span></td>
            <td>${r.workshop_name||'—'}</td>
            <td><strong>${r.requested_qty}</strong></td>
            <td>${priorityBadge(r.priority)}</td>
            <td style="font-size:12px;color:var(--t3);max-width:180px">${r.reason||'—'}</td>
            <td style="font-size:12px;color:var(--t3)">${r.requested_at}<br>${r.requested_by||'—'}</td>
            ${canApprove?`<td style="white-space:nowrap">
              <button class="bs1 mr-approve" data-id="${r.id}" style="color:var(--green);padding:4px 8px;font-size:12px"><i class="ti ti-check"></i>Approve</button>
              <button class="bs1 mr-reject" data-id="${r.id}" style="color:var(--red);padding:4px 8px;font-size:12px"><i class="ti ti-x"></i>Reject</button>
            </td>`:''}
          </tr>`).join('')}
        </tbody>
      </table>
    </div>` : ''}

    ${!res.pendingTransfers.length && !res.pendingRequests.length ? '<div style="padding:.75rem 0;font-size:13px;color:var(--green);display:flex;align-items:center;gap:.5rem"><i class="ti ti-circle-check"></i>No pending transfers or requests.</div>' : ''}

    ${res.lowStock.length ? `
    <div class="card" style="padding:0">
      <div style="padding:.9rem 1.25rem;border-bottom:1px solid var(--bdr)">
        <h3 style="margin:0;color:var(--red)"><i class="ti ti-alert-triangle"></i> Low Stock Alerts <span style="font-size:12px;font-weight:500;background:rgba(239,68,68,.1);color:var(--red);padding:2px 8px;border-radius:10px;margin-left:.4rem">${res.lowStock.length}</span></h3>
      </div>
      <table class="tbl">
        <thead><tr><th>Item</th><th>Workshop</th><th>In Stock</th><th>Min Stock</th></tr></thead>
        <tbody>
          ${res.lowStock.map(r=>`
          <tr>
            <td>${r.name}<br><span style="font-size:11px;color:var(--t3)">${r.category} · ${r.uom}</span></td>
            <td>${r.warehouse_name||'—'}</td>
            <td style="color:var(--red);font-weight:700">${r.total_stock}</td>
            <td style="color:var(--t3)">${r.min_stock}</td>
          </tr>`).join('')}
        </tbody>
      </table>
    </div>` : ''}
  `;

  if (canApprove) {
    // Phase 1 (Inventory consolidation) — now approves via the dedicated
    // stock_transfers lifecycle (UFCL.stockTransfersApprove), not the
    // retired stock_movements shortcut. An approved transfer here still
    // needs Dispatch + Receive on the Stock Transfers page before stock
    // actually moves — that's the authoritative lifecycle's own design
    // (vehicle-assigned dispatch), not a shortcut this widget bypasses.
    document.querySelectorAll('.tr-approve').forEach(btn => {
      btn.onclick = async () => {
        const res2 = await UFCL.stockTransfersApprove(STORAGE.user.id, Number(btn.dataset.id), 'approve', null);
        if (!res2.ok) return alert(res2.error);
        renderWorkshopOverview();
      };
    });
    document.querySelectorAll('.tr-reject').forEach(btn => {
      btn.onclick = async () => {
        const reason = prompt('Rejection reason (optional):') ?? '';
        const res2 = await UFCL.stockTransfersApprove(STORAGE.user.id, Number(btn.dataset.id), 'reject', reason);
        if (!res2.ok) return alert(res2.error);
        renderWorkshopOverview();
      };
    });
    document.querySelectorAll('.mr-approve').forEach(btn => {
      btn.onclick = () => openWorkshopOverviewApprove(btn.dataset.id);
    });
    document.querySelectorAll('.mr-reject').forEach(btn => {
      btn.onclick = async () => {
        const notes = prompt('Rejection reason (optional):') ?? '';
        const res2 = await UFCL.materialRequestsApprove(STORAGE.user.id, Number(btn.dataset.id), 'reject', null, notes, null);
        if (!res2.ok) return alert(res2.error);
        renderWorkshopOverview();
      };
    });
  }

  // Approving a request requires a source workshop to issue stock from
  // (materialRequestsApprove errors without one) — mirrors openApproveOverlay
  // on the dedicated Material Requests page, scoped down for this dashboard
  // widget (no bulk qty edit, just source/destination + notes).
  function openWorkshopOverviewApprove(idStr) {
    const r = (res.pendingRequests || []).find(x => String(x.id) === String(idStr));
    const needsDest = !r || !r.workshop_id;
    const wshOpts = (res.workshops || []).map(w => `<option value="${w.id}">${w.name}</option>`).join('');
    openOverlay('Approve Request', null, `
      <div class="fg"><label>Source Workshop (to issue from) *</label><select id="wsd-appr-src"><option value="">— Select —</option>${wshOpts}</select></div>
      ${needsDest ? `<div class="fg"><label>Destination Workshop (to receive) *</label><select id="wsd-appr-dest"><option value="">— Select —</option>${wshOpts}</select></div>` : ''}
      <div class="fg"><label>Notes</label><input id="wsd-appr-notes" type="text" placeholder="Optional notes"></div>
      <div class="brow"><button class="bp1" id="ovSave" style="background:var(--green)"><i class="ti ti-check"></i>Confirm Approve</button><button class="bs1" id="ovCancel">Cancel</button></div>
    `, async () => {
      const src = $('wsd-appr-src').value;
      if (!src) { showOverlayError('A source workshop is required.'); return; }
      const dest = needsDest ? $('wsd-appr-dest').value : null;
      if (needsDest && !dest) { showOverlayError('A destination workshop is required.'); return; }
      const res2 = await UFCL.materialRequestsApprove(
        STORAGE.user.id, Number(idStr), 'approve', null, $('wsd-appr-notes').value.trim(), src, dest || null
      );
      if (!res2.ok) { showOverlayError(res2.error); return; }
      showOverlaySuccess('Request approved — a stock transfer was created and is ready for dispatch.');
      await renderWorkshopOverview();
    });
  }

  // Phase 2 — genuine operational report export, same native-save-dialog
  // convention as every other Reports/Dashboard page in the app.
  $('wsd-export').onclick = async () => {
    const lines = [
      ['UFCL Workshop — Operational Report', new Date().toLocaleString()],
      [],
      ['Executive KPIs', ''],
      ['Machines', totalMachines], ['Available machines', availableMachines],
      ['Active maintenance', activeMaintenanceCount], ['Machine availability %', machineAvailabilityPct],
      ['Scheduled maintenance (7d)', scheduledMaintenanceCount], ['Overdue maintenance', overdueMaintenanceCount],
      ['Fuel this month (L)', fuelConsumedThisMonth], ['Downtime this month (hrs)', downtimeHoursThisMonth],
      ['Material requests pending', materialRequestsPendingCount],
      ['Workshop utilization %', workshopUtilizationPct], ['Maintenance completed this month', maintenanceThisMonthCount],
      ...(res.financeVisibility ? [['Workshop costs this month (RWF)', workshopCostsThisMonth], ['Maintenance costs this month (RWF)', res.financeVisibility.maintenanceCostThisMonth]] : []),
      [],
      ['Workshop', 'Machines', 'Available', 'Under maintenance', 'Stock value (RWF)'],
      ...res.workshops.map(w => [w.name, w.machine_count, w.machines_available, w.machines_maintenance, w.stock_value]),
      [], ['Overdue Maintenance — Machine', 'Type', 'Next Due'], ...overdueMaintenanceList.map(s => [s.machine_code+' — '+s.machine_name, s.maintenance_type, s.next_due]),
      [], ['Upcoming Maintenance — Machine', 'Type', 'Next Due'], ...upcomingMaintenance.map(s => [s.machine_code+' — '+s.machine_name, s.maintenance_type, s.next_due]),
      [], ['Equipment Alert — Machine', 'Status'], ...equipmentAlerts.map(m => [m.machine_code+' — '+m.name, m.status]),
      [], ['Pending Material Request — Item', 'Workshop', 'Qty', 'Priority'], ...(res.pendingRequests||[]).map(r => [r.item_name, r.workshop_name||'', r.requested_qty, r.priority]),
      [], ['Low Stock — Item', 'Workshop', 'Stock', 'Minimum'], ...(res.lowStock||[]).map(s => [s.name, s.warehouse_name||'', s.total_stock, s.min_stock]),
      [], ['Maintenance Trend — Month', 'Completed'], ...maintenanceTrendMonths.map(m => [m.month, m.cnt]),
      ...(res.financeVisibility ? [[], ['Cost Trend — Month', 'Total (RWF)'], ...costTrendMonths.map(m => [m.month, m.total])] : []),
    ];
    const csv = lines.map(row => row.map(c => `"${String(c ?? '').replace(/"/g, '""')}"`).join(',')).join('\r\n');
    const filename = `workshop_operational_report_${new Date().toISOString().slice(0, 10)}.csv`;
    const res2 = await UFCL.execExport(STORAGE.user.id, { csv, filename });
    if (!res2?.ok && res2?.error !== undefined) showToast('Export cancelled or failed', 'error');
  };
}

// ── Workshops ─────────────────────────────────────────────────────────────────

async function renderWarehouses() {
  const res = await UFCL.warehousesList(STORAGE.user.id, WORKSHOP_FILTER);
  if (!res.ok) return renderDenied('warehouses', res.error);
  const rows = res.rows || [];
  const isRestricted = !!res.user_workshop_id;
  const canManage = ['admin', 'ceo', 'operations', 'logistics'].includes(STORAGE.user?.role);

  const whActive = rows.filter(r=>r.active).length;
  const whCap    = rows.reduce((s,r)=>s+Number(r.capacity||0),0);

  // Phase 2 — search toolkit over the card grid (no status dropdown here;
  // Active/Inactive is already visible as a badge per card).
  const whState = { search: '' };
  function whFiltered() {
    if (!whState.search.trim()) return rows;
    const q = whState.search.trim().toLowerCase();
    return rows.filter(r => (r.name||'').toLowerCase().includes(q) || (r.location||'').toLowerCase().includes(q) || (r.workshop_type||'').toLowerCase().includes(q));
  }

  $('page-warehouses').innerHTML = `
    ${workshopBannerHtml(res.allWarehouses, res.user_workshop_id)}
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;margin-bottom:1.5rem">
      <div>
        <div class="ptitle"><i class="ti ti-building-warehouse" style="color:var(--g-soft)"></i> Workshops</div>
        <div class="psub">${isRestricted ? `You are assigned to: <strong>${rows[0]?.name || 'your workshop'}</strong>. Only your workshop data is shown.` : 'Manage workshops — independent stock locations. Assign users to a workshop so they only see that workshop\'s stock.'}</div>
      </div>
      ${canManage ? `<div style="display:flex;gap:.5rem;flex-shrink:0">
        <button class="bp1" id="whQuickUser"><i class="ti ti-user-plus"></i>Add workshop user</button>
        <button class="appbtn" id="whAdd"><i class="ti ti-plus" style="font-size:12px"></i> Add workshop</button>
      </div>` : ''}
    </div>
    <div class="cards" style="margin-bottom:1.25rem">
      <div class="mc" style="border-top:3px solid var(--g-soft)"><div class="mclbl">Workshops</div><div class="mcval">${rows.length}</div><div class="mcsub cg"><i class="ti ti-building-warehouse"></i>total</div></div>
      <div class="mc"><div class="mclbl">Active</div><div class="mcval" style="color:var(--green)">${whActive}</div><div class="mcsub cg"><i class="ti ti-circle-check"></i>in use</div></div>
      <div class="mc"><div class="mclbl">Inactive</div><div class="mcval">${rows.length-whActive}</div><div class="mcsub ca"><i class="ti ti-circle-x"></i>offline</div></div>
      <div class="mc"><div class="mclbl">Total capacity</div><div class="mcval">${whCap.toLocaleString()}</div><div class="mcsub cg"><i class="ti ti-database"></i>units</div></div>
    </div>
    ${rows.length > 1 ? `<div style="margin-bottom:1rem"><div class="filter-search" style="max-width:340px"><i class="ti ti-search"></i><input id="wh-search" type="text" placeholder="Search name, location, type…"></div></div>` : ''}
    <div id="wh-grid" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:1rem"></div>
  `;

  function renderWhGrid(list) {
    $('wh-grid').innerHTML = list.length ? list.map(r => `
        <div class="wh-card" data-id="${r.id}" style="cursor:pointer;background:var(--surf);border:1px solid var(--bdr);border-radius:10px;padding:1.25rem;display:flex;flex-direction:column;gap:.75rem;border-top:3px solid var(--g-soft)">
          <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:.5rem">
            <div>
              <div style="font-weight:700;font-size:16px;color:var(--g-dark)">${r.name}</div>
              ${r.workshop_type?`<div style="font-size:11px;color:var(--g-soft);font-weight:600;margin-top:2px"><i class="ti ${WORKSHOP_TYPE_ICONS[r.workshop_type]||'ti-building-warehouse'}" style="font-size:10px"></i> ${r.workshop_type}</div>`:''}
              <div style="font-size:12px;color:var(--t3);margin-top:3px"><i class="ti ti-map-pin" style="font-size:11px"></i> ${r.location||'No location set'}</div>
            </div>
            <span class="badge ${r.active?'bg':'br'}">${r.active?'Active':'Inactive'}</span>
          </div>
          <div style="display:flex;gap:1.5rem">
            <div><div style="font-size:11px;color:var(--t3);text-transform:uppercase;letter-spacing:.04em">Capacity</div><div style="font-weight:600;font-family:var(--fm)">${r.capacity?Number(r.capacity).toLocaleString()+'  units':'—'}</div></div>
          </div>
          ${r.notes?`<div style="font-size:12px;color:var(--t3);padding:.5rem .75rem;background:var(--bg2);border-radius:5px">${r.notes}</div>`:''}
          <div style="display:flex;gap:.5rem;margin-top:auto;padding-top:.25rem;border-top:1px solid var(--bdr)">
            <button class="bs1 wh-view" data-id="${r.id}" style="flex:1;justify-content:center"><i class="ti ti-eye"></i>Details</button>
            ${canManage ? `<button class="bs1 wh-edit" data-id="${r.id}"><i class="ti ti-edit"></i></button>
            <button class="bs1 wh-del" data-id="${r.id}" style="color:var(--red);padding:6px 10px"><i class="ti ti-trash"></i></button>` : ''}
          </div>
        </div>`).join('')
      : `<div style="grid-column:1/-1;text-align:center;padding:3rem;color:var(--t3)"><i class="ti ti-building-warehouse" style="font-size:2rem;display:block;margin-bottom:.5rem;opacity:.35"></i>${rows.length ? 'No workshops match this search.' : 'No workshops yet. Click <strong>Add workshop</strong> to create your first location.'}</div>`;

    document.querySelectorAll('.wh-view').forEach(btn => {
      btn.onclick = (e) => { e.stopPropagation(); const r = rows.find(x=>String(x.id)===btn.dataset.id); if (r) openWarehouseDetailOverlay(r); };
    });
  }

  // Phase 2 — detail overlay + History tab, reusing the same generic
  // per-record history lookup every other consolidated Inventory page uses.
  function openWarehouseDetailOverlay(r) {
    openOverlay('Workshop', r.name, `
      <div class="frow" style="margin-bottom:10px"><span class="badge ${r.active?'bg':'br'}">${r.active?'Active':'Inactive'}</span> ${r.workshop_type?`<span class="badge bt">${r.workshop_type}</span>`:''}</div>
      <div class="card" style="padding:12px 14px;margin-bottom:12px;background:var(--bg2)">
        <div class="frow" style="flex-wrap:wrap;gap:1.25rem;font-size:13px">
          <div><strong>Location</strong><br>${r.location||'—'}</div>
          <div><strong>Capacity</strong><br>${r.capacity?Number(r.capacity).toLocaleString()+' units':'—'}</div>
        </div>
        ${r.notes?`<div style="margin-top:.6rem;font-size:12px;color:var(--t3)">${r.notes}</div>`:''}
      </div>
      <div style="font-size:12px;font-weight:700;color:var(--t3);margin-bottom:6px;text-transform:uppercase;letter-spacing:.03em">History</div>
      <div id="wh-detail-history" style="margin-bottom:14px"></div>
      <div class="brow">
        ${canManage ? `<button class="bs1" id="whd-edit"><i class="ti ti-edit"></i>Edit</button>` : ''}
        <button class="bs1" id="ovCancel">Close</button>
      </div>`, null);
    _loadLogisticsHistoryInto('wh-detail-history', 'warehouses', r.id);
    setTimeout(() => { const ed = $('whd-edit'); if (ed) ed.onclick = () => { closeOverlay(); openWarehouseEditOverlay(r.id); }; }, 30);
  }

  renderWhGrid(whFiltered());
  if ($('wh-search')) $('wh-search').oninput = (e) => { whState.search = e.target.value; renderWhGrid(whFiltered()); };

  function openWarehouseEditOverlay(idStr) {
    const row = rows.find(r => String(r.id) === String(idStr));
    if (!row) return;
    const WTYPE_OPTS2 = ['Sawmill Workshop','Logging Equipment Workshop','Vehicle Workshop','Pole Treatment Workshop','Electrical Workshop','Central Warehouse'].map(t=>`<option value="${t}" ${row.workshop_type===t?'selected':''}>${t}</option>`).join('');
    openOverlay('Edit Workshop', row.name, `
      <div class="frow">
        <div class="fg"><label>Name *</label><input id="whe-name" type="text" value="${row.name}"></div>
        <div class="fg"><label>Workshop Type</label><select id="whe-type"><option value="">— Select type —</option>${WTYPE_OPTS2}</select></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Location</label><input id="whe-location" type="text" value="${row.location||''}"></div>
        <div class="fg"><label>Capacity</label><input id="whe-cap" type="number" min="0" value="${row.capacity||''}"></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Notes</label><input id="whe-notes" type="text" value="${row.notes||''}"></div>
        <div class="fg"><label>Status</label>
          <select id="whe-active"><option value="true" ${row.active?'selected':''}>Active</option><option value="false" ${!row.active?'selected':''}>Inactive</option></select>
        </div>
      </div>
      <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Save</button>
      <button class="bs1" id="ovCancel">Cancel</button></div>`, async () => {
      const res2 = await UFCL.warehousesUpdate(STORAGE.user.id, row.id, {
        name: $('whe-name').value.trim(),
        workshop_type: $('whe-type').value || null,
        location: $('whe-location').value.trim(),
        capacity: $('whe-cap').value,
        notes: $('whe-notes').value.trim(),
        active: $('whe-active').value === 'true'
      });
      if (!res2.ok) { showOverlayError(res2.error); return; }
      showOverlaySuccess('Workshop updated.');
      await renderWarehouses();
    });
  }

  if (canManage) {
    const WTYPE_OPTS = ['Sawmill Workshop','Logging Equipment Workshop','Vehicle Workshop','Pole Treatment Workshop','Electrical Workshop','Central Warehouse'].map(t=>`<option value="${t}">${t}</option>`).join('');
    $('whAdd').onclick = () => openOverlay('Add Workshop', null, `
      <div class="frow">
        <div class="fg"><label>Workshop name *</label><input id="wh-name" type="text" placeholder="e.g. Gatare Workshop"></div>
        <div class="fg"><label>Workshop Type</label><select id="wh-type"><option value="">— Select type —</option>${WTYPE_OPTS}</select></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Location</label><input id="wh-location" type="text" placeholder="Site or address"></div>
        <div class="fg"><label>Capacity (units)</label><input id="wh-cap" type="number" min="0" placeholder="0"></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Notes</label><input id="wh-notes" type="text"></div>
      </div>
      <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Save</button>
      <button class="bs1" id="ovCancel">Cancel</button></div>`, async () => {
      const res2 = await UFCL.warehousesCreate(STORAGE.user.id, {
        name: $('wh-name').value.trim(),
        workshop_type: $('wh-type').value || null,
        location: $('wh-location').value.trim(),
        capacity: $('wh-cap').value,
        notes: $('wh-notes').value.trim()
      });
      if (!res2.ok) { showOverlayError(res2.error); return; }
      showOverlaySuccess('Workshop added.');
      await renderWarehouses();
    });

    const workshopOpts = rows.map(r => `<option value="${r.id}">${r.name}</option>`).join('');
    $('whQuickUser').onclick = () => openOverlay('Register Workshop User', 'Quickly add a user with access limited to one workshop.', `
      <div class="frow">
        <div class="fg"><label>Full name *</label><input id="wu-name" type="text" placeholder="Full name"></div>
        <div class="fg"><label>Username *</label><input id="wu-user" type="text" placeholder="Login username"></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Password *</label><input id="wu-pass" type="password" value="UFCL@1234" placeholder="Initial password"></div>
        <div class="fg"><label>Role</label>
          <select id="wu-role">
            <option value="storekeeper">Storekeeper</option>
            <option value="supervisor">Supervisor</option>
            <option value="logistics">Logistics Manager</option>
          </select>
        </div>
      </div>
      <div class="fg"><label>Assign to workshop *</label>
        <select id="wu-workshop"><option value="">— select workshop —</option>${workshopOpts}</select>
      </div>
      <div class="fg"><label>Department</label><input id="wu-dept" type="text" placeholder="e.g. Logistics, Forestry"></div>
      <div style="font-size:12px;color:var(--t3);padding:.625rem .75rem;background:var(--bg2);border-radius:6px;margin-bottom:.75rem">
        <i class="ti ti-info-circle" style="color:var(--amber)"></i>
        This user will <strong>only</strong> see stock and movements from the assigned workshop.
        The storekeeper role sees all workshops regardless of assignment.
      </div>
      <div class="brow">
        <button class="bp1" id="ovSave"><i class="ti ti-user-plus"></i>Register user</button>
        <button class="bs1" id="ovCancel">Cancel</button>
      </div>`,
      async () => {
        const r2 = await UFCL.usersCreate(STORAGE.user.id, {
          name:        $('wu-name').value.trim(),
          username:    $('wu-user').value.trim(),
          password:    $('wu-pass').value,
          role:        $('wu-role').value,
          department:  $('wu-dept').value.trim() || null,
          workshop_id: $('wu-workshop').value || null
        });
        if (!r2.ok) { showOverlayError(r2.error); return; }
        showOverlaySuccess('Workshop user registered.');
      });

    document.querySelectorAll('.wh-del').forEach(btn => {
      btn.onclick = () => {
        const r = rows.find(x => x.id === btn.dataset.id);
        if (!r) return;
        confirmDelete(`Delete workshop <strong>${r.name}</strong>? All stock levels in this workshop will also be removed.`, async () => {
          const res2 = await UFCL.warehousesDelete(STORAGE.user.id, r.id);
          if (!res2.ok) { showOverlayError(res2.error); return; }
          showOverlaySuccess('Workshop deleted.'); await renderWarehouses();
        });
      };
    });

    document.querySelectorAll('.wh-edit').forEach(btn => {
      btn.onclick = () => openWarehouseEditOverlay(btn.dataset.id);
    });
  }
  bindWorkshopBanner(renderWarehouses);
}

// ── Stock Catalog ─────────────────────────────────────────────────────────────

// Stock categories are loaded from DB; this is only used as a fallback for new installs
const STOCK_CATEGORIES_DEFAULT = ['Timber', 'Poles', 'Fuel', 'Spare Parts', 'Tools', 'Packaging', 'Raw Materials', 'Other'];

async function renderStockItems() {
  const res = await UFCL.stockItemsList(STORAGE.user.id, WORKSHOP_FILTER);
  if (!res.ok) return renderDenied('stock-items', res.error);
  const rows = res.rows || [];
  const warehouses = res.warehouses || [];
  const categories = res.categories || [];

  // managers (no workshop assignment) see per-warehouse breakdown when no filter is active
  const isManager = !res.user_workshop_id;
  const showBreakdown = isManager && !WORKSHOP_FILTER && warehouses.length > 0;

  // 'stock-movements' permission controls whether consumption can be recorded
  const canConsume = (STORAGE.pages || []).includes('stock-movements');
  // resolved warehouse for consumption: restricted users → their shop; managers with filter → filter; else user picks
  const defaultWhId = res.user_workshop_id || (WORKSHOP_FILTER ? Number(WORKSHOP_FILTER) : null);
  const defaultWhName = defaultWhId ? (warehouses.find(w => w.id === defaultWhId)?.name || '') : '';

  const lowRows = rows.filter(r => r.total_stock <= Number(r.min_stock));
  const totalValue = rows.reduce((s,r) => s + Number(r.total_stock) * Number(r.unit_cost), 0);

  const catTotals = {};
  for (const r of rows) {
    catTotals[r.category] = (catTotals[r.category] || 0) + 1;
  }

  // Dynamic column headers: one column per warehouse + Total, or single Stock column
  const whHeaders = showBreakdown
    ? warehouses.map(w => `<th style="text-align:center;white-space:nowrap;font-size:11px">${w.name}</th>`).join('') + '<th data-sort-key="total_stock" style="text-align:center">Total</th>'
    : '<th data-sort-key="total_stock">Stock</th>';
  const tableColCount = 10 + (showBreakdown ? warehouses.length + 1 : 1);

  // Phase 2 — enterprise table toolkit (search/filter/sort/bulk), same
  // pattern already proven for Spare Parts & Materials (renderLogistics),
  // Machine Registry, and Material Requests.
  rows.forEach(r => {
    const low = r.total_stock <= Number(r.min_stock);
    const out = r.total_stock === 0;
    const over = r.max_stock && r.total_stock > Number(r.max_stock);
    r._statusLabel = out ? 'Out of stock' : low ? 'Reorder' : over ? 'Overstock' : 'OK';
  });
  const siState = { search: '', status: '' };
  const siSort = { key: null, dir: 'asc' };
  function siFiltered() {
    return applyProcListFilters(rows, {
      search: siState.search, searchFields: ['name', 'sku', 'category'],
      status: siState.status, statusField: '_statusLabel',
    });
  }
  const canManageItems = (STORAGE.pages || []).includes('stock-items');

  $('page-stock-items').innerHTML = `
    ${workshopBannerHtml(res.warehouses, res.user_workshop_id)}
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;margin-bottom:1.5rem">
      <div>
        <div class="ptitle">Stock Catalog</div>
        <div class="psub">Maintain your master item list with categories, costs, and warehouse-level stock tracking.</div>
      </div>
      <div style="display:flex;gap:.5rem;flex-shrink:0">
        <button class="bs1" id="siExport" style="white-space:nowrap"><i class="ti ti-file-download"></i>Export</button>
        <button class="bs1" id="siManageCats" style="white-space:nowrap"><i class="ti ti-tag"></i>Manage categories</button>
        <button class="bp1" id="siAdd" style="white-space:nowrap"><i class="ti ti-plus"></i>Add item</button>
      </div>
    </div>
    ${categories.length === 0 ? alertHtml('info', `No custom categories yet — click <strong style="margin:0 .25rem">Manage categories</strong> to define your own before adding items.`) : ''}
    <div class="cards" style="margin-bottom:1.25rem">
      <div class="mc"><div class="mclbl">Total SKUs</div><div class="mcval">${rows.length}</div><div class="mcsub cg"><i class="ti ti-package"></i>catalog</div></div>
      <div class="mc"><div class="mclbl">Alerts</div><div class="mcval" style="${lowRows.length>0?'color:var(--red)':''}">${lowRows.length}</div><div class="mcsub ${lowRows.length>0?'cr':'cg'}"><i class="ti ti-alert-triangle"></i>low stock</div></div>
      <div class="mc"><div class="mclbl">Stock value (RWF)</div><div class="mcval">${Math.round(totalValue).toLocaleString()}</div><div class="mcsub bp"><i class="ti ti-coin"></i>at cost</div></div>
      <div class="mc"><div class="mclbl">Categories</div><div class="mcval">${Object.keys(catTotals).length}</div><div class="mcsub cg"><i class="ti ti-tag"></i>types</div></div>
    </div>
    ${lowRows.length ? alertHtml('critical', `<strong style="margin-right:.25rem">${lowRows.length} item${lowRows.length>1?'s':''}</strong> require reorder — check minimum stock levels.`) : ''}
    ${procFilterBarHtml({
      searchId: 'si-search', searchPlaceholder: 'Search name, SKU, category…',
      statusId: 'si-status-filter', statusOptions: ['OK', 'Reorder', 'Out of stock', 'Overstock'],
      clearId: 'si-clear',
    })}
    ${canManageItems ? `<div class="bulk-bar" id="si-bulk-bar" style="display:none">
      <span id="si-bulk-count">0 selected</span>
      <button class="bs1" id="si-bulk-deactivate"><i class="ti ti-eye-off"></i>Deactivate selected</button>
    </div>` : ''}
    <div class="card" style="padding:0">
      <div style="display:flex;align-items:center;justify-content:space-between;padding:1rem 1.25rem;border-bottom:1px solid var(--bdr)">
        <h3 style="margin:0"><i class="ti ti-package"></i>Item register</h3>
        <span id="si-count-label" style="font-size:12px;color:var(--t3)">${rows.length} item${rows.length!==1?'s':''}</span>
      </div>
      <div class="tw"><table class="tbl" id="si-table">
        <thead><tr>
          ${canManageItems ? '<th style="width:28px"><input type="checkbox" id="si-select-all"></th>' : ''}
          <th data-sort-key="category">Category</th><th data-sort-key="name">Name</th><th data-sort-key="sku">SKU</th><th>UoM</th>${whHeaders}
          <th>Min / Max</th><th data-sort-key="unit_cost">Unit cost (RWF)</th><th>Value (RWF)</th><th data-sort-key="_statusLabel">Status</th><th>Actions</th>
        </tr></thead>
        <tbody id="si-tbody"></tbody>
      </table></div>
    </div>`;

  function itemForm(r) {
    const catListOpts = categories.length
      ? categories.map(c => `<option value="${c.name}">`).join('')
      : STOCK_CATEGORIES_DEFAULT.map(c => `<option value="${c}">`).join('');
    return `
      <datalist id="si-cat-list">${catListOpts}</datalist>
      <div class="frow">
        <div class="fg">
          <label>Category *</label>
          <input id="si-cat" type="text" list="si-cat-list" value="${r ? r.category : ''}" placeholder="Select or type a category" autocomplete="off">
        </div>
        <div class="fg"><label>Name *</label><input id="si-name" type="text" value="${r?r.name:''}" placeholder="Item name"></div>
      </div>
      <div class="frow">
        <div class="fg"><label>SKU</label><input id="si-sku" type="text" value="${r?r.sku||'':''}" placeholder="Stock keeping unit"></div>
        <div class="fg"><label>Unit of measure *</label><input id="si-uom" type="text" value="${r?r.uom:''}" placeholder="e.g. pcs, kg, litres"></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Unit cost (RWF)</label><input id="si-cost" type="number" min="0" value="${r?r.unit_cost:0}"></div>
        <div class="fg"><label>Min stock</label><input id="si-min" type="number" min="0" value="${r?r.min_stock:0}"></div>
        <div class="fg"><label>Max stock</label><input id="si-max" type="number" min="0" value="${r&&r.max_stock?r.max_stock:''}"></div>
      </div>
      <div class="fg"><label>Notes</label><input id="si-notes" type="text" value="${r?r.notes||'':''}"></div>
      <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Save</button><button class="bs1" id="ovCancel">Cancel</button></div>`;
  }

  $('siAdd').onclick = () => openOverlay('Add stock item', null, itemForm(null), async () => {
    const res2 = await UFCL.stockItemsCreate(STORAGE.user.id, {
      category: $('si-cat').value,
      name: $('si-name').value.trim(),
      sku: $('si-sku').value.trim(),
      uom: $('si-uom').value.trim(),
      unit_cost: $('si-cost').value,
      min_stock: $('si-min').value,
      max_stock: $('si-max').value
    });
    if (!res2.ok) { showOverlayError(res2.error); return; }
    showOverlaySuccess('Item added.');
    await renderStockItems();
  });

  function deleteStockItem(idStr) {
    const r = rows.find(x => String(x.id) === String(idStr));
    if (!r) return;
    confirmDeleteSoft(`Delete stock item <strong>${r.name}</strong>?`, async (reason) => {
      const res2 = await UFCL.stockItemsDelete(STORAGE.user.id, r.id, reason);
      // Stock & Inventory Phase 4 (audit finding H-12) — was a plain
      // showOverlayError, which rendered a blank/undefined message when
      // governance deferred this delete for approval instead of denying it
      // (res2.error is unset on a pendingApproval response) — same fix
      // already applied at 17 other call sites via this helper.
      if (handleGovernanceResult(res2)) return;
      showOverlaySuccess('Stock item deleted.'); await renderStockItems();
    });
  }

  function openStockItemEditOverlay(idStr) {
    const row = rows.find(r => String(r.id) === String(idStr));
    if (!row) return;
    openOverlay('Edit stock item', row.name, itemForm(row), async () => {
      const res2 = await UFCL.stockItemsUpdate(STORAGE.user.id, row.id, {
        category: $('si-cat').value,
        name: $('si-name').value.trim(),
        sku: $('si-sku').value.trim(),
        uom: $('si-uom').value.trim(),
        unit_cost: $('si-cost').value,
        min_stock: $('si-min').value,
        max_stock: $('si-max').value,
        active: true
      });
      // Stock & Inventory Phase 4 (audit finding H-12) — same fix as
      // deleteStockItem above.
      if (handleGovernanceResult(res2)) return;
      showOverlaySuccess('Item updated.');
      await renderStockItems();
    });
  }

  function openStockItemUseOverlay(idStr) {
    const r = rows.find(x => String(x.id) === String(idStr));
    if (!r) return;
    const itemName = r.name, uom = r.uom, inStock = Number(r.total_stock);
    const whDropdown = !defaultWhId && warehouses.length
      ? `<div class="fg"><label>Workshop *</label><select id="su-wh">${warehouses.map(w=>`<option value="${w.id}">${w.name}</option>`).join('')}</select></div>`
      : `<div class="fg"><label>Workshop</label><input type="text" value="${defaultWhName}" readonly style="background:var(--bg2);cursor:default"></div>`;
    const today = new Date().toISOString().slice(0, 10);
    openOverlay(`Record Consumption — ${itemName}`, null, `
      <div style="display:flex;align-items:center;gap:.75rem;padding:.65rem 1rem;background:var(--bg2);border-radius:8px;margin-bottom:1rem;font-size:13px">
        <i class="ti ti-package" style="color:var(--t3);font-size:18px"></i>
        <span>Current stock: <strong style="${inStock===0?'color:var(--red)':inStock<=5?'color:var(--amber)':''}">${inStock} ${uom}</strong></span>
      </div>
      <div class="frow">
        <div class="fg"><label>Date</label><input id="su-date" type="date" value="${today}"></div>
        <div class="fg"><label>Quantity consumed (${uom}) *</label><input id="su-qty" type="number" min="1" step="1" placeholder="0"></div>
      </div>
      <div class="frow">
        ${whDropdown}
        <div class="fg"><label>Notes</label><input id="su-notes" type="text" placeholder="Who used it, purpose, etc."></div>
      </div>
      <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Record</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
    async () => {
      const qty = Number(document.getElementById('su-qty')?.value || 0);
      if (!qty || qty <= 0) { showOverlayError('Enter a quantity greater than zero.'); return; }
      const warehouseId = defaultWhId || ($('su-wh') ? Number($('su-wh').value) : null);
      if (!warehouseId) { showOverlayError('Select a workshop.'); return; }
      const dateVal = document.getElementById('su-date')?.value || today;
      const notesVal = document.getElementById('su-notes')?.value.trim() || '';
      const ref = `Consumption ${dateVal}`;
      const r2 = await UFCL.stockMovementsCreate(STORAGE.user.id, {
        item_id: r.id, movement_type: 'out', quantity: qty,
        warehouse_id: warehouseId, reference: ref, notes: notesVal
      });
      if (!r2.ok) { showOverlayError(r2.error); return; }
      showOverlaySuccess(`${qty} ${uom} of ${itemName} recorded as consumed.`);
      await renderStockItems();
    });
  }

  // Phase 2 — detail overlay + History tab, same pattern as every other
  // consolidated Inventory page (module 'stock_catalog', wired in Phase 1).
  function openStockItemDetailOverlay(r) {
    // Enterprise UI/UX Standardization Phase 2 — .smo-tabs conversion (was a
    // flat single-scroll overlay). Overview/History match the Guide's
    // recommended tab vocabulary; there's no separate "Details" content
    // beyond what Overview already shows, so it's not a padded-out 3rd tab.
    const TAB_META = {
      overview: { label: 'Overview', icon: 'ti-info-circle' },
      history: { label: 'History', icon: 'ti-history' },
    };
    openOverlay('Stock item', r.name, `
      <div class="smo-tabs" id="sid-tabs">
        ${Object.entries(TAB_META).map(([t, m]) => `<button type="button" class="smo-tab ${t==='overview'?'active':''}" data-tab="${t}"><i class="ti ${m.icon}"></i>${m.label}</button>`).join('')}
      </div>
      <div id="sid-body"></div>
      <div class="brow" style="margin-top:1rem">
        ${canManageItems ? `<button class="bs1" id="sid-edit"><i class="ti ti-edit"></i>Edit</button>` : ''}
        ${canConsume ? `<button class="bs1" id="sid-use" style="color:var(--amber)"><i class="ti ti-minus"></i>Use</button>` : ''}
        <button class="bs1" id="ovCancel">Close</button>
      </div>`, null);

    function renderOverviewTab(body) {
      body.innerHTML = `
        <div class="frow" style="margin-bottom:10px"><span class="badge ${r._statusLabel==='OK'?'bg':r._statusLabel==='Overstock'?'ba':'br'}">${r._statusLabel}</span> <span class="badge bt">${r.category}</span></div>
        <div class="card" style="padding:12px 14px;margin-bottom:12px;background:var(--bg2)">
          <div class="frow" style="flex-wrap:wrap;gap:1.25rem;font-size:13px">
            <div><strong>SKU</strong><br>${r.sku||'—'}</div>
            <div><strong>UoM</strong><br>${r.uom}</div>
            <div><strong>Total stock</strong><br>${r.total_stock}</div>
            <div><strong>Min / Max</strong><br>${r.min_stock} / ${r.max_stock||'∞'}</div>
            <div><strong>Unit cost</strong><br>${Number(r.unit_cost).toLocaleString()} RWF</div>
            <div><strong>Stock value</strong><br>${Math.round(r.total_stock*Number(r.unit_cost)).toLocaleString()} RWF</div>
          </div>
        </div>
      `;
    }
    function renderHistoryTab(body) {
      body.innerHTML = `<div id="si-detail-history"></div>`;
      _loadLogisticsHistoryInto('si-detail-history', 'stock_catalog', r.id);
    }
    function loadTab(tab) {
      const body = $('sid-body');
      if (tab === 'overview') return renderOverviewTab(body);
      if (tab === 'history') return renderHistoryTab(body);
    }
    document.querySelectorAll('#sid-tabs .smo-tab').forEach(btn => {
      btn.onclick = () => {
        document.querySelectorAll('#sid-tabs .smo-tab').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        loadTab(btn.dataset.tab);
      };
    });
    loadTab('overview');

    setTimeout(() => {
      const ed = $('sid-edit'); if (ed) ed.onclick = () => { closeOverlay(); openStockItemEditOverlay(r.id); };
      const us = $('sid-use'); if (us) us.onclick = () => { closeOverlay(); openStockItemUseOverlay(r.id); };
    }, 30);
  }

  function renderSiRows(list) {
    const tbody = $('si-tbody');
    if (!list.length) {
      tbody.innerHTML = `<tr><td colspan="${tableColCount}" style="text-align:center;color:var(--t3);padding:3rem"><i class="ti ti-package" style="font-size:2rem;display:block;margin-bottom:.5rem;opacity:.35"></i>${rows.length ? 'No items match these filters.' : 'No items yet. Click <strong>Add item</strong> to build your catalog.'}</td></tr>`;
      $('si-count-label').textContent = '0 items';
      return;
    }
    $('si-count-label').textContent = `${list.length} item${list.length!==1?'s':''}`;
    tbody.innerHTML = list.map(r => {
      const low = r._statusLabel === 'Reorder' || r._statusLabel === 'Out of stock';
      const out = r._statusLabel === 'Out of stock';
      const over = r._statusLabel === 'Overstock';
      const cls = out||low ? 'br' : over ? 'ba' : 'bg';
      const whb = r.wh_breakdown || {};
      const stockCells = showBreakdown
        ? warehouses.map(w => {
            const qty = Number(whb[String(w.id)] || 0);
            const isOut = qty === 0;
            const isLow = qty <= Number(r.min_stock);
            return `<td style="text-align:center;${isOut?'color:var(--red);font-weight:700':isLow?'color:var(--amber);font-weight:600':''}">${qty}</td>`;
          }).join('') + `<td style="text-align:center;font-weight:700;${out?'color:var(--red)':low?'color:var(--amber)':''}">${r.total_stock}</td>`
        : `<td style="${out?'color:var(--red);font-weight:700':low?'color:var(--amber);font-weight:600':''}">${r.total_stock}</td>`;
      return `<tr>
        ${canManageItems ? `<td><input type="checkbox" class="si-row-check" data-id="${r.id}"></td>` : ''}
        <td><span class="badge bt">${r.category}</span></td>
        <td style="font-weight:500">${r.name}</td>
        <td style="font-family:var(--fm);color:var(--t3)">${r.sku||'—'}</td>
        <td>${r.uom}</td>
        ${stockCells}
        <td style="font-family:var(--fm);color:var(--t3)">${r.min_stock} / ${r.max_stock||'∞'}</td>
        <td style="font-family:var(--fm)">${Number(r.unit_cost).toLocaleString()}</td>
        <td style="font-family:var(--fm)">${Math.round(r.total_stock*Number(r.unit_cost)).toLocaleString()}</td>
        <td><span class="badge ${cls}">${r._statusLabel}</span></td>
        <td style="white-space:nowrap">
          <button class="bs1 si-view" data-id="${r.id}" title="View details"><i class="ti ti-eye"></i></button>
          ${canConsume ? `<button class="bs1 si-use" data-id="${r.id}" style="color:var(--amber)"><i class="ti ti-minus"></i></button>` : ''}
          ${canManageItems ? `<button class="bs1 si-edit" data-id="${r.id}"><i class="ti ti-edit"></i></button>
          <button class="bs1 si-del" data-id="${r.id}" style="color:var(--red)"><i class="ti ti-trash"></i></button>` : ''}
        </td>
      </tr>`;
    }).join('');
    wireSiRowActions();
  }

  function wireSiRowActions() {
    document.querySelectorAll('.si-view').forEach(btn => {
      btn.onclick = () => { const r = rows.find(x=>String(x.id)===btn.dataset.id); if (r) openStockItemDetailOverlay(r); };
    });
    document.querySelectorAll('.si-use').forEach(btn => { btn.onclick = () => openStockItemUseOverlay(btn.dataset.id); });
    document.querySelectorAll('.si-edit').forEach(btn => { btn.onclick = () => openStockItemEditOverlay(btn.dataset.id); });
    document.querySelectorAll('.si-del').forEach(btn => { btn.onclick = () => deleteStockItem(btn.dataset.id); });
    document.querySelectorAll('.si-row-check').forEach(cb => { cb.onchange = updateSiBulkBar; });
  }

  function updateSiBulkBar() {
    const bar = $('si-bulk-bar');
    if (!bar) return;
    const checked = document.querySelectorAll('.si-row-check:checked');
    bar.style.display = checked.length ? 'flex' : 'none';
    if (checked.length) $('si-bulk-count').textContent = `${checked.length} selected`;
  }

  renderSiRows(siFiltered());
  wireSortableTable($('si-table'), siSort, siFiltered, renderSiRows);
  $('si-search').oninput = (e) => { siState.search = e.target.value; renderSiRows(siFiltered()); };
  $('si-status-filter').onchange = (e) => { siState.status = e.target.value; renderSiRows(siFiltered()); };
  $('si-clear').onclick = () => { siState.search=''; siState.status=''; $('si-search').value=''; $('si-status-filter').value=''; renderSiRows(siFiltered()); };
  $('siExport').onclick = () => {
    const csv = ['Name,SKU,Category,UoM,Total stock,Min stock,Max stock,Unit cost,Stock value,Status'];
    for (const r of siFiltered())
      csv.push(`"${r.name}","${r.sku || ''}","${r.category}",${r.uom},${r.total_stock},${r.min_stock},${r.max_stock || ''},${Number(r.unit_cost)},${Math.round(r.total_stock * Number(r.unit_cost))},${r._statusLabel}`);
    downloadCsv(csv.join('\n'), 'stock-catalog.csv');
  };

  if ($('si-select-all')) {
    $('si-select-all').onchange = (e) => {
      document.querySelectorAll('.si-row-check').forEach(cb => { cb.checked = e.target.checked; });
      updateSiBulkBar();
    };
  }
  if ($('si-bulk-deactivate')) {
    $('si-bulk-deactivate').onclick = () => {
      const ids = Array.from(document.querySelectorAll('.si-row-check:checked')).map(cb => cb.dataset.id);
      if (!ids.length) return;
      confirmDelete(`Deactivate ${ids.length} selected item${ids.length>1?'s':''}? They will no longer appear in active lists.`, async () => {
        for (const id of ids) {
          const row = rows.find(x => String(x.id) === id);
          if (!row) continue;
          await UFCL.stockItemsUpdate(STORAGE.user.id, row.id, {
            category: row.category, name: row.name, sku: row.sku, uom: row.uom,
            unit_cost: row.unit_cost, min_stock: row.min_stock, max_stock: row.max_stock,
            active: false
          });
        }
        showOverlaySuccess(`${ids.length} item${ids.length>1?'s':''} deactivated.`);
        await renderStockItems();
      });
    };
  }

  bindWorkshopBanner(renderStockItems);

  $('siManageCats').onclick = () => {
    function catManagerHtml(cats) {
      const list = cats.length
        ? cats.map(c => `
            <div style="display:flex;align-items:center;justify-content:space-between;padding:.45rem .75rem;border-radius:6px;background:var(--bg2);margin-bottom:.35rem">
              <span style="font-weight:500">${c.name}</span>
              <button class="bs1 sc-del" data-id="${c.id}" style="color:var(--red);padding:2px 8px;font-size:11px"><i class="ti ti-trash"></i></button>
            </div>`).join('')
        : `<div style="color:var(--t3);font-size:13px;padding:.5rem 0">No categories yet. Add your first one below.</div>`;
      return `
        <div style="margin-bottom:1rem">${list}</div>
        <div class="frow" style="gap:.5rem;align-items:flex-end">
          <div class="fg"><label>New category name</label><input id="sc-new-name" type="text" placeholder="e.g. Lubricants, Safety Gear…"></div>
          <button class="bp1" id="sc-add-btn" style="flex-shrink:0;margin-bottom:0"><i class="ti ti-plus"></i>Add</button>
        </div>`;
    }

    async function openCatManager() {
      const r2 = await UFCL.stockCategoriesList(STORAGE.user.id);
      const cats = r2.ok ? r2.rows : [];
      openOverlay('Manage Stock Categories', null, catManagerHtml(cats), null);

      document.querySelectorAll('.sc-del').forEach(btn => {
        btn.onclick = async () => {
          const r3 = await UFCL.stockCategoriesDelete(STORAGE.user.id, btn.dataset.id);
          if (!r3.ok) { showOverlayError(r3.error); return; }
          openCatManager();
        };
      });

      const addBtn = document.getElementById('sc-add-btn');
      if (addBtn) addBtn.onclick = async () => {
        const name = document.getElementById('sc-new-name')?.value.trim();
        if (!name) return;
        const r3 = await UFCL.stockCategoriesCreate(STORAGE.user.id, name);
        if (!r3.ok) { showOverlayError(r3.error); return; }
        openCatManager();
      };
    }

    openCatManager();
  };

  // Phase 1 (Inventory consolidation) — Stock Catalog and Spare Parts &
  // Materials now share the same 'stock_item' governance identity (both
  // write stock_catalog); surfacing pending requests here too so a manager
  // reviewing either page sees the same single set of outstanding requests.
  await insertPendingPanel($('page-stock-items'), ['stock_item'], renderStockItems);
  await insertDeletionPanel($('page-stock-items'), ['stock_item'], renderStockItems);
}

// ── Stock Movements ───────────────────────────────────────────────────────────

async function renderStockMovements() {
  const res = await UFCL.stockMovementsList(STORAGE.user.id, WORKSHOP_FILTER);
  if (!res.ok) return renderDenied('stock-movements', res.error);
  const rows = res.rows || [];
  const items = res.items || [];
  const warehouses = res.warehouses || [];

  const typeBadge = (t, approval) => {
    const map = { in:'bg', out:'br', adjustment:'ba', transfer:'bp', transfer_in:'bp', transfer_out:'bp', return:'bb', loss:'br' };
    const badge = `<span class="badge ${map[t]||'bt'}">${t}</span>`;
    if (t==='transfer' && approval==='pending') return badge + `<span class="badge ba" style="font-size:10px;margin-left:3px">pending</span>`;
    if (t==='transfer' && approval==='approved') return badge + `<span class="badge bg" style="font-size:10px;margin-left:3px">approved</span>`;
    if (t==='transfer' && approval==='rejected') return badge + `<span class="badge br" style="font-size:10px;margin-left:3px">rejected</span>`;
    return badge;
  };

  // Phase 2 — enterprise table toolkit (search/filter/sort), same pattern
  // as every other consolidated Inventory page.
  rows.forEach(r => { r._typeLabel = r.movement_type; });
  const smState = { search: '', status: '' };
  const smSort = { key: null, dir: 'asc' };
  function smFiltered() {
    return applyProcListFilters(rows, {
      search: smState.search, searchFields: ['item_name', 'category', 'reference', 'created_by'],
      status: smState.status, statusField: '_typeLabel',
    });
  }

  $('page-stock-movements').innerHTML = `
    ${workshopBannerHtml(res.warehouses, res.user_workshop_id)}
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;margin-bottom:1.5rem">
      <div>
        <div class="ptitle">Stock Movements</div>
        <div class="psub">Full audit trail of every stock in, out, adjustment, and return. Deleting a movement automatically reverses the stock level. To move stock between warehouses, use the Stock Transfers page.</div>
      </div>
      <button class="bp1" id="smAdd" style="flex-shrink:0;white-space:nowrap"><i class="ti ti-plus"></i>Record movement</button>
    </div>
    <div class="cards" style="margin-bottom:1.25rem">
      <div class="mc"><div class="mclbl">Total entries</div><div class="mcval">${rows.length}</div><div class="mcsub cg"><i class="ti ti-arrows-exchange"></i>last 100</div></div>
      <div class="mc"><div class="mclbl">Stock In</div><div class="mcval">${rows.filter(r=>r.movement_type==='in').length}</div><div class="mcsub cg"><i class="ti ti-arrow-down-circle"></i>receipts</div></div>
      <div class="mc"><div class="mclbl">Stock Out</div><div class="mcval">${rows.filter(r=>r.movement_type==='out').length}</div><div class="mcsub cr"><i class="ti ti-arrow-up-circle"></i>issues</div></div>
      <div class="mc"><div class="mclbl">Adjustments</div><div class="mcval">${rows.filter(r=>r.movement_type==='adjustment').length}</div><div class="mcsub ca"><i class="ti ti-adjustments"></i>corrections</div></div>
      <div class="mc"><div class="mclbl">Losses</div><div class="mcval" style="${rows.filter(r=>r.movement_type==='loss').length>0?'color:var(--red)':''}">${rows.filter(r=>r.movement_type==='loss').length}</div><div class="mcsub ${rows.filter(r=>r.movement_type==='loss').length>0?'cr':''}"><i class="ti ti-alert-triangle"></i>transfer shortfalls</div></div>
    </div>
    ${procFilterBarHtml({
      searchId: 'sm-search', searchPlaceholder: 'Search item, category, reference, recorded by…',
      statusId: 'sm-status-filter', statusOptions: ['in', 'out', 'adjustment', 'return', 'transfer', 'loss'],
      clearId: 'sm-clear',
    })}
    <div class="card" style="padding:0">
      <div style="display:flex;align-items:center;justify-content:space-between;padding:1rem 1.25rem;border-bottom:1px solid var(--bdr)">
        <h3 style="margin:0"><i class="ti ti-arrows-exchange"></i>Movement log</h3>
        <span id="sm-count-label" style="font-size:12px;color:var(--t3)">${rows.length} entr${rows.length!==1?'ies':'y'}</span>
      </div>
      <div class="tw"><table class="tbl" id="sm-table">
        <thead><tr>
          <th data-sort-key="created_at">Date</th><th data-sort-key="item_name">Item</th><th data-sort-key="category">Category</th>
          <th data-sort-key="_typeLabel">Type</th><th data-sort-key="quantity">Qty</th><th>Unit Price</th><th>Total Value</th>
          <th>From warehouse</th><th>To warehouse</th><th>Reference</th><th data-sort-key="created_by">Recorded by</th><th></th>
        </tr></thead>
        <tbody id="sm-tbody"></tbody>
      </table></div>
    </div>`;

  function renderSmRows(list) {
    const tbody = $('sm-tbody');
    if (!list.length) {
      tbody.innerHTML = `<tr><td colspan="12" style="text-align:center;color:var(--t3);padding:3rem"><i class="ti ti-arrows-exchange" style="font-size:2rem;display:block;margin-bottom:.5rem;opacity:.35"></i>${rows.length ? 'No movements match these filters.' : 'No movements recorded yet.'}</td></tr>`;
      $('sm-count-label').textContent = '0 entries';
      return;
    }
    $('sm-count-label').textContent = `${list.length} entr${list.length!==1?'ies':'y'}`;
    tbody.innerHTML = list.map(r=>`<tr>
      <td style="white-space:nowrap;color:var(--t3);font-size:12px">${r.created_at}</td>
      <td style="font-weight:500">${r.item_name}</td>
      <td><span class="badge bt">${r.category}</span></td>
      <td>${typeBadge(r.movement_type, r.approval_status)}</td>
      <td style="font-family:var(--fm);font-weight:600">${r.quantity} <span style="color:var(--t3);font-weight:400">${r.uom}</span></td>
      <td style="font-family:var(--fm);color:var(--t3)">${r.unit_cost != null ? Number(r.unit_cost).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}) : '—'}</td>
      <td style="font-family:var(--fm);font-weight:500">${r.unit_cost != null ? Number(r.total_value).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}) : '—'}</td>
      <td>${r.warehouse_name||'—'}</td>
      <td>${r.to_warehouse_name||'—'}</td>
      <td style="font-family:var(--fm);color:var(--t3)">${r.movement_type==='loss' ? (r.loss_reason||'—') : (r.reference||'—')}</td>
      <td>${r.created_by||'—'}</td>
      <td style="white-space:nowrap">
        <button class="bs1 sm-view" data-id="${r.id}" title="View details"><i class="ti ti-eye"></i></button>
        ${r.transfer_id ? `<button class="bs1 sm-view-transfer" data-transfer-id="${r.transfer_id}" style="color:var(--purple);padding:3px 8px" title="View source Stock Transfer"><i class="ti ti-arrows-right-left"></i></button>` : ''}
        <button class="bs1 sm-del" data-id="${r.id}" style="color:var(--red);padding:3px 8px" title="Delete &amp; reverse"><i class="ti ti-trash"></i></button>
      </td>
    </tr>`).join('');
    wireSmRowActions();
  }

  function deleteStockMovement(idStr) {
    const r = rows.find(x => String(x.id) === String(idStr));
    if (!r) return;
    if (isSupervisor()) {
      confirmDeleteSoft(`Submit delete request for stock movement <strong>${r.movement_type}</strong> (${r.quantity} ${r.uom} of ${r.item_name})? A manager must approve before it is moved to Trash.`, async (reason) => {
        const r2 = await UFCL.deletionRequestCreate(STORAGE.user.id, 'stock_movements', r.id, 'stock_movement', `${r.movement_type} — ${r.item_name}`, reason);
        if (!r2.ok) { showOverlayError(r2.error); return; }
        showOverlaySuccess('Deletion request submitted for approval.'); await renderStockMovements();
      });
    } else {
      confirmDeleteSoft(`Move stock movement <strong>${r.movement_type}</strong> (${r.quantity} ${r.uom} of ${r.item_name}) to Trash? Stock level will be reversed.`, async (reason) => {
        const res2 = await UFCL.stockMovementsDelete(STORAGE.user.id, r.id, reason);
        // Stock & Inventory Phase 4 (audit finding H-12) — same fix as
        // deleteStockItem/openStockItemEditOverlay above.
        if (handleGovernanceResult(res2)) return;
        showOverlaySuccess('Movement moved to Trash and stock level reversed.'); await renderStockMovements();
      });
    }
  }

  // Phase 2 — detail overlay + History tab (module 'stock_movements', wired
  // in Phase 1). A stock movement has no separate "edit" identity — the
  // overlay is read-focused, matching how Machine KPI's history drill-down
  // works for computed/append-only records.
  function openStockMovementDetailOverlay(r) {
    openOverlay('Stock movement', `${r.item_name}`, `
      <div class="frow" style="margin-bottom:10px">${typeBadge(r.movement_type, r.approval_status)} <span class="badge bt">${r.category}</span></div>
      <div class="card" style="padding:12px 14px;margin-bottom:12px;background:var(--bg2)">
        <div class="frow" style="flex-wrap:wrap;gap:1.25rem;font-size:13px">
          <div><strong>Quantity</strong><br>${r.quantity} ${r.uom}</div>
          <div><strong>Unit price</strong><br>${r.unit_cost != null ? Number(r.unit_cost).toLocaleString() : '—'}</div>
          <div><strong>Total value</strong><br>${r.unit_cost != null ? Number(r.total_value).toLocaleString() : '—'}</div>
          <div><strong>From warehouse</strong><br>${r.warehouse_name||'—'}</div>
          <div><strong>To warehouse</strong><br>${r.to_warehouse_name||'—'}</div>
          <div><strong>Reference</strong><br>${r.reference||'—'}</div>
          <div><strong>Recorded by</strong><br>${r.created_by||'—'}</div>
          <div><strong>Date</strong><br>${r.created_at}</div>
        </div>
        ${r.notes?`<div style="margin-top:.6rem;font-size:12px;color:var(--t3)">${r.notes}</div>`:''}
      </div>
      <div style="font-size:12px;font-weight:700;color:var(--t3);margin-bottom:6px;text-transform:uppercase;letter-spacing:.03em">History</div>
      <div id="sm-detail-history" style="margin-bottom:14px"></div>
      <div class="brow"><button class="bs1" id="ovCancel">Close</button></div>`, null);
    _loadLogisticsHistoryInto('sm-detail-history', 'stock_movements', r.id);
  }

  function wireSmRowActions() {
    document.querySelectorAll('.sm-view').forEach(btn => {
      btn.onclick = () => { const r = rows.find(x=>String(x.id)===btn.dataset.id); if (r) openStockMovementDetailOverlay(r); };
    });
    document.querySelectorAll('.sm-view-transfer').forEach(btn => {
      btn.onclick = async () => {
        setActivePage('stock-transfers');
        await renderStockTransfers();
        openStockTransferDetailOverlay(Number(btn.dataset.transferId));
      };
    });
    document.querySelectorAll('.sm-del').forEach(btn => { btn.onclick = () => deleteStockMovement(btn.dataset.id); });
  }

  renderSmRows(smFiltered());
  wireSortableTable($('sm-table'), smSort, smFiltered, renderSmRows);
  $('sm-search').oninput = (e) => { smState.search = e.target.value; renderSmRows(smFiltered()); };
  $('sm-status-filter').onchange = (e) => { smState.status = e.target.value; renderSmRows(smFiltered()); };
  $('sm-clear').onclick = () => { smState.search=''; smState.status=''; $('sm-search').value=''; $('sm-status-filter').value=''; renderSmRows(smFiltered()); };

  $('smAdd').onclick = () => {
    const itemOpts = items.map(i=>`<option value="${i.id}" data-cost="${i.default_unit_cost||0}">${i.name} (${i.category}) — stock: ${i.total_stock} ${i.uom}</option>`).join('');
    const whOpts = warehouses.map(w=>`<option value="${w.id}">${w.name}</option>`).join('');
    openOverlay('Record stock movement', null, `
      <div class="frow">
        <div class="fg"><label>Item *</label><select id="sm-item">${itemOpts||'<option>No items</option>'}</select></div>
        <div class="fg"><label>Movement type *</label>
          <select id="sm-type">
            <option value="in">Stock In</option>
            <option value="out">Stock Out</option>
            <option value="adjustment">Adjustment (set quantity)</option>
            <option value="return">Return</option>
          </select>
        </div>
      </div>
      <div class="frow">
        <div class="fg"><label>Quantity *</label><input id="sm-qty" type="number" min="1" placeholder="0"></div>
        <div class="fg"><label>Unit Price</label><input id="sm-cost" type="number" min="0" step="0.01" placeholder="Price per unit"></div>
        <div class="fg"><label>Warehouse</label><select id="sm-wh">${whOpts||'<option value="">No warehouses</option>'}</select></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Reference</label><input id="sm-ref" type="text" placeholder="PO#, invoice, etc."></div>
        <div class="fg"><label id="sm-notes-label">Notes</label><input id="sm-notes" type="text"></div>
      </div>
      <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Save</button><button class="bs1" id="ovCancel">Cancel</button></div>`, async () => {
      const type = $('sm-type').value;
      const notesVal = $('sm-notes').value.trim();
      if (type === 'adjustment' && !notesVal) { showOverlayError('A reason is required for stock adjustments.'); return; }
      // Stock & Inventory Phase 3 (Priority 4/5) — adjustments now require
      // manager approval instead of writing stock_levels immediately;
      // routed to the new request-creation endpoint, everything else
      // (in/out/return) is unchanged.
      if (type === 'adjustment') {
        if (!$('sm-wh').value) { showOverlayError('A warehouse is required for adjustments.'); return; }
        const res2 = await UFCL.stockAdjustmentRequestCreate(STORAGE.user.id, {
          item_id: $('sm-item').value,
          quantity: $('sm-qty').value,
          warehouse_id: $('sm-wh').value,
          reference: $('sm-ref').value.trim(),
          notes: notesVal
        });
        if (!res2.ok) { showOverlayError(res2.error); return; }
        showOverlaySuccess('Adjustment request submitted — awaiting manager approval.');
        await renderStockMovements();
        return;
      }
      const res2 = await UFCL.stockMovementsCreate(STORAGE.user.id, {
        item_id: $('sm-item').value,
        movement_type: type,
        quantity: $('sm-qty').value,
        unit_cost: $('sm-cost').value || null,
        warehouse_id: $('sm-wh').value || null,
        reference: $('sm-ref').value.trim(),
        notes: notesVal
      });
      if (!res2.ok) { showOverlayError(res2.error); return; }
      showOverlaySuccess('Movement recorded.');
      await renderStockMovements();
    });
    // Auto-fill unit price from catalog when item changes
    const smItem = $('sm-item');
    const smCost = $('sm-cost');
    if (smItem && smCost) {
      const fillCost = () => {
        const opt = smItem.options[smItem.selectedIndex];
        if (opt) smCost.value = opt.dataset.cost || '';
      };
      fillCost();
      smItem.onchange = fillCost;
    }
    // Phase 2 (Stock Adjustments) — flag Notes as required only for the
    // adjustment type, the same reason-code discipline every other
    // governed mutation in this app already carries.
    const smType = $('sm-type');
    const smNotesLabel = $('sm-notes-label');
    const smQty = $('sm-qty');
    const updateNotesRequired = () => {
      const isAdj = smType.value === 'adjustment';
      smNotesLabel.textContent = isAdj ? 'Reason *' : 'Notes';
      // Stock & Inventory Phase 3 — adjustment quantity is the target
      // ("set to"), which can legitimately be 0 (e.g. a recount finds
      // nothing left); every other type is a positive delta.
      smQty.min = isAdj ? '0' : '1';
    };
    updateNotesRequired();
    smType.onchange = updateNotesRequired;
  };
  bindWorkshopBanner(renderStockMovements);
  // Stock & Inventory Phase 3 (Priority 4/5/16) — stock adjustments now go
  // through the same pending_edits approval engine every other governed
  // edit in this app uses; same insertPendingPanel call every other page
  // with a governed entity type already makes (renderStockMovements had
  // none before this phase, since there was nothing to approve here).
  await insertPendingPanel($('page-stock-movements'), ['stock_adjustment'], renderStockMovements);
  await insertDeletionPanel($('page-stock-movements'), ['stock_movement'], renderStockMovements);
}

// ── Stock Transfers ───────────────────────────────────────────────────────────

// Inventory Integrity Phase 1 — the standardized discrepancy reason
// categories, mirrors DISCREPANCY_REASONS in db/services/data.js (server is
// the source of validation truth; this is just the picker's option list).
const DISCREPANCY_REASONS = [
  'Loss in Transit', 'Damaged During Transport', 'Short Shipment', 'Theft',
  'Write-off', 'Manual Count Adjustment', 'Expired Material', 'Other',
];

// Enterprise UI/UX Standardization Phase 1, Workstream A — shared Stock
// Transfer status registry (was two hand-typed duplicate maps: one here,
// one in renderStockTransfers' local statusBadge). The list view abbreviates
// "Partially Received" to "Partial" for column width, so it derives its own
// meta from the base one rather than being a silent third copy.
const STOCK_TRANSFER_STATUS_META = {
  pending:                    { cls: 'ba', label: 'Pending' },
  approved:                   { cls: 'bg', label: 'Approved' },
  in_transit:                 { cls: 'bp', label: 'In Transit' },
  partially_received:         { cls: 'ba', label: 'Partially Received' },
  completed:                  { cls: 'bg', label: 'Completed' },
  completed_with_discrepancy: { cls: 'br', label: 'Completed (Short)' },
  rejected:                   { cls: 'br', label: 'Rejected' },
  cancelled:                  { cls: 'br', label: 'Cancelled' },
};
const STOCK_TRANSFER_LIST_STATUS_META = { ...STOCK_TRANSFER_STATUS_META, partially_received: { cls: 'ba', label: 'Partial' } };
function stockTransferStatusBadge(s, list) {
  return badgeHtml(list ? STOCK_TRANSFER_LIST_STATUS_META : STOCK_TRANSFER_STATUS_META, s, { cls: 'bt', label: s });
}

// Material Request UI/UX redesign — extracted from the Stock Transfers
// page's row-detail handler (previously inline, only reachable from that
// page) so the Material Requests "Linked Transfer" view can open the exact
// same detail overlay instead of building a second, duplicate one.
async function openStockTransferDetailOverlay(transferId) {
  const res2 = await UFCL.stockTransfersDispatchHistory(STORAGE.user.id, transferId);
  if (!res2.ok) { showOverlayError(res2.error || 'Could not load transfer details.'); return; }
  const t = res2.transfer;
  const dispList = res2.dispatches || [];

  // Enterprise UI/UX Standardization Phase 2 — .smo-tabs conversion (was a
  // flat single-scroll overlay). Overview/History match the Guide's
  // recommended vocabulary; "Dispatch Events" is a module-specific third
  // tab, the same way Vehicle's overlay has module-specific tabs beyond
  // Overview/History (Fuel, Assignments).
  const TAB_META = {
    overview: { label: 'Overview', icon: 'ti-info-circle' },
    dispatch: { label: 'Dispatch Events', icon: 'ti-truck' },
    history: { label: 'History', icon: 'ti-history' },
  };
  openOverlay(
    `Transfer #${transferId} — Details`,
    t ? `${t.item_name} | ${t.from_warehouse_name} → ${t.to_warehouse_name}` : '',
    `
    <div class="smo-tabs" id="std-tabs">
      ${Object.entries(TAB_META).map(([tab, m]) => `<button type="button" class="smo-tab ${tab==='overview'?'active':''}" data-tab="${tab}"><i class="ti ${m.icon}"></i>${m.label}</button>`).join('')}
    </div>
    <div id="std-body"></div>
    <div class="brow" style="margin-top:1rem">
      <button class="bs1" id="ovCancel">Close</button>
    </div>
    `
  );

  function renderOverviewTab(body) {
    body.innerHTML = `
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:.5rem 1.5rem;background:var(--bg2);border-radius:6px;padding:.875rem 1rem;margin-bottom:1.25rem;font-size:13px">
      <div><span style="color:var(--t3)">Transfer ID:</span> <strong>#${t ? t.id : transferId}</strong></div>
      <div><span style="color:var(--t3)">Status:</span> ${t ? stockTransferStatusBadge(t.status) : '<span class="badge bt">—</span>'}</div>
      <div><span style="color:var(--t3)">Item:</span> <strong>${t ? t.item_name : '—'}</strong></div>
      <div><span style="color:var(--t3)">UOM:</span> ${t ? t.uom : '—'}</div>
      <div><span style="color:var(--t3)">From:</span> ${t ? t.from_warehouse_name : '—'}</div>
      <div><span style="color:var(--t3)">To:</span> ${t ? t.to_warehouse_name : '—'}</div>
      <div><span style="color:var(--t3)">Qty Approved:</span> <strong>${t ? t.requested_qty : '—'}</strong></div>
      <div><span style="color:var(--t3)">Qty Dispatched:</span> <strong style="color:var(--purple)">${t ? t.dispatched_qty : '—'}</strong></div>
      <div><span style="color:var(--t3)">Qty Received:</span> <strong style="color:var(--green)">${t ? t.received_qty : '—'}</strong></div>
      <div><span style="color:var(--t3)">Requested by:</span> ${t ? (t.requested_by||'—') : '—'}</div>
      ${t && t.approved_by ? `<div><span style="color:var(--t3)">Approved by:</span> ${t.approved_by}</div>` : ''}
      ${t && t.approved_at ? `<div><span style="color:var(--t3)">Approved at:</span> ${t.approved_at}</div>` : ''}
      ${t && t.transfer_ref && t.transfer_ref.startsWith('MAT-REQ-') ? `<div><span style="color:var(--t3)">Origin:</span> <span class="badge bt">Material Request ${t.transfer_ref.replace('MAT-REQ-','#')}</span></div>` : ''}
    </div>
    ${t && t.status === 'completed_with_discrepancy' ? alertHtml('critical', `Closed with shortage: ${t.discrepancy_qty || 0} ${t.uom} short${t.discrepancy_notes ? `<br><span style="font-size:12px">${t.discrepancy_notes}</span>` : ''}`) : ''}
    `;
  }

  function renderDispatchTab(body) {
    body.innerHTML = `
    <h4 style="margin:0 0 .75rem;font-size:13px;color:var(--t2)"><i class="ti ti-truck"></i> Dispatch Events (${dispList.length})</h4>
    ${dispList.length ? `
      <div class="tw" style="max-height:280px">
      <table class="dt" style="font-size:12px">
        <thead><tr><th>#</th><th>Date &amp; Time</th><th>Qty</th><th>Vehicle</th><th>Driver</th><th>Reference</th><th>Recorded by</th><th>Notes</th></tr></thead>
        <tbody>
          ${dispList.map((d, i) => `<tr>
            <td style="color:var(--t3)">${i+1}</td>
            <td style="font-family:var(--fm);white-space:nowrap">${d.dispatched_at}</td>
            <td style="font-family:var(--fm);font-weight:600;color:var(--purple)">${d.qty}</td>
            <td>${d.registration ? d.registration + (d.vehicle_label ? ' — ' + d.vehicle_label : '') : '—'}</td>
            <td>${d.driver_name || '—'}</td>
            <td style="color:var(--t3)">${d.reference || '—'}</td>
            <td style="color:var(--t3)">${d.dispatched_by_name || '—'}</td>
            <td style="color:var(--t3)">${d.notes || '—'}</td>
          </tr>`).join('')}
        </tbody>
      </table>
      </div>
    ` : '<div style="text-align:center;padding:2rem;color:var(--t3)"><i class="ti ti-truck" style="font-size:1.5rem;display:block;margin-bottom:.5rem;opacity:.35"></i>No dispatch events recorded yet.</div>'}
    `;
  }

  function renderHistoryTab(body) {
    body.innerHTML = `<div id="st-detail-history"></div>`;
    _loadLogisticsHistoryInto('st-detail-history', 'stock_transfers', transferId);
  }

  function loadTab(tab) {
    const body = $('std-body');
    if (tab === 'overview') return renderOverviewTab(body);
    if (tab === 'dispatch') return renderDispatchTab(body);
    if (tab === 'history') return renderHistoryTab(body);
  }
  document.querySelectorAll('#std-tabs .smo-tab').forEach(btn => {
    btn.onclick = () => {
      document.querySelectorAll('#std-tabs .smo-tab').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      loadTab(btn.dataset.tab);
    };
  });
  loadTab('overview');
}

async function renderStockTransfers() {
  const res = await UFCL.stockTransfersList(STORAGE.user.id, WORKSHOP_FILTER);
  if (!res.ok) return renderDenied('stock-transfers', res.error);
  const rows = res.rows || [];
  const items = res.items || [];
  const warehouses = res.warehouses || [];
  const vehicles = res.vehicles || [];

  const canApprove = ['admin', 'ceo', 'operations', 'logistics'].includes(STORAGE.user?.role);
  // Stabilization Phase 4 (P-3) — 'logistics-officer' added to canAct: it
  // holds the backend 'stock-transfers' permission (db/migrate.js) that every
  // stockTransfers* function gates on uniformly (no separate approve-vs-act
  // distinction exists server-side — that split is this desktop screen's own
  // convention), but was excluded from acting (create/dispatch/receive) on
  // either platform. canApprove is left unchanged — no finding questioned
  // desktop's existing approve-vs-act split, so it isn't touched here.
  // Stock & Inventory Phase 4 (audit finding M-16) — showroom-staff/
  // vat-leader/vat-supervisor all hold the backend 'stock-transfers'
  // permission every stockTransfers* function gates on, but this hardcoded
  // list excluded them from the act buttons (create/dispatch/receive) with
  // no backend-side restriction to match — a hidden button, not real
  // enforcement (the same M-15 gap mobile-api's ACT_ROLES had). Widened to
  // match the actual granted permission, consistent with canAct's own
  // established convention above.
  const canAct = ['admin', 'ceo', 'operations', 'logistics', 'logistics-officer', 'supervisor', 'storekeeper', 'showroom-staff', 'vat-leader', 'vat-supervisor'].includes(STORAGE.user?.role);

  const statusBadge = (s) => stockTransferStatusBadge(s, true);

  const progressBar = (dispatched, received, requested) => {
    const dispPct = Math.min(100, Math.round((dispatched / requested) * 100));
    const recvPct = Math.min(100, Math.round((received / requested) * 100));
    return `
      <div style="font-size:11px;color:var(--t3);margin-bottom:2px">
        <span style="color:var(--t2)">Dispatched:</span> ${dispatched}/${requested}
        &nbsp;|&nbsp;
        <span style="color:var(--t2)">Received:</span> ${received}/${requested}
      </div>
      <div style="background:var(--bdr);border-radius:3px;height:5px;position:relative;overflow:hidden;width:100%;min-width:80px">
        <div style="background:var(--g-soft);opacity:.45;position:absolute;left:0;top:0;height:100%;width:${dispPct}%"></div>
        <div style="background:var(--g-dark);position:absolute;left:0;top:0;height:100%;width:${recvPct}%"></div>
      </div>`;
  };
  const STATUS_LABELS = { pending:'Pending', approved:'Approved', in_transit:'In Transit', partially_received:'Partial', completed:'Completed', completed_with_discrepancy:'Completed (Short)', rejected:'Rejected', cancelled:'Cancelled' };

  // Phase 2 — enterprise table toolkit (search/filter/sort/bulk-approve),
  // same pattern as every other consolidated Inventory page.
  rows.forEach(r => { r._statusLabel = STATUS_LABELS[r.status] || r.status; });
  const stState = { search: '', status: '' };
  const stSort = { key: null, dir: 'asc' };
  function stFiltered() {
    return applyProcListFilters(rows, {
      search: stState.search, searchFields: ['item_name', 'category', 'reference', 'requested_by', 'from_warehouse_name', 'to_warehouse_name'],
      status: stState.status, statusField: '_statusLabel',
    });
  }

  $('page-stock-transfers').innerHTML = `
    ${workshopBannerHtml(res.warehouses, res.user_workshop_id)}
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;margin-bottom:1.5rem">
      <div>
        <div class="ptitle">Stock Transfers</div>
        <div class="psub">Move stock between workshops. Each transfer goes through Request → Approval → Dispatch → Receipt before completion.</div>
      </div>
      <div style="display:flex;gap:.5rem;flex-shrink:0">
        <button class="bs1" id="st-export"><i class="ti ti-file-spreadsheet"></i>Export Excel</button>
        ${canAct ? `<button class="bp1" id="stAdd" style="white-space:nowrap"><i class="ti ti-plus"></i>New transfer request</button>` : ''}
      </div>
    </div>
    <div class="cards" style="margin-bottom:1.25rem">
      <div class="mc"><div class="mclbl">Total</div><div class="mcval">${rows.length}</div><div class="mcsub cg"><i class="ti ti-arrows-right-left"></i>all time</div></div>
      <div class="mc"><div class="mclbl">Pending Approval</div><div class="mcval">${rows.filter(r=>r.status==='pending').length}</div><div class="mcsub ca"><i class="ti ti-clock"></i>awaiting review</div></div>
      <div class="mc"><div class="mclbl">In Transit</div><div class="mcval">${rows.filter(r=>['approved','in_transit','partially_received'].includes(r.status)).length}</div><div class="mcsub cp"><i class="ti ti-truck"></i>active</div></div>
      <div class="mc"><div class="mclbl">Completed</div><div class="mcval">${rows.filter(r=>r.status==='completed').length}</div><div class="mcsub cg"><i class="ti ti-circle-check"></i>fulfilled</div></div>
    </div>
    ${procFilterBarHtml({
      searchId: 'st-search', searchPlaceholder: 'Search item, category, reference, warehouse…',
      statusId: 'st-status-filter', statusOptions: Object.values(STATUS_LABELS).filter((v,i,a)=>a.indexOf(v)===i),
      clearId: 'st-clear',
    })}
    ${canApprove ? `<div class="bulk-bar" id="st-bulk-bar" style="display:none">
      <span id="st-bulk-count">0 selected</span>
      <button class="bs1" id="st-bulk-approve" style="margin-left:.5rem"><i class="ti ti-check"></i>Approve selected</button>
    </div>` : ''}
    <div class="card" style="padding:0">
      <div style="display:flex;align-items:center;justify-content:space-between;padding:1rem 1.25rem;border-bottom:1px solid var(--bdr)">
        <h3 style="margin:0"><i class="ti ti-arrows-right-left"></i>Transfer log</h3>
        <span id="st-count-label" style="font-size:12px;color:var(--t3)">${rows.length} entr${rows.length!==1?'ies':'y'}</span>
      </div>
      <div class="tw"><table class="tbl" id="st-table">
        <thead><tr>
          ${canApprove ? '<th style="width:28px"><input type="checkbox" id="st-select-all"></th>' : ''}
          <th data-sort-key="reference">Ref / Date</th><th data-sort-key="item_name">Item</th><th data-sort-key="from_warehouse_name">From</th>
          <th data-sort-key="to_warehouse_name">To</th><th data-sort-key="requested_qty">Qty</th><th>Progress</th>
          <th data-sort-key="_statusLabel">Status</th><th data-sort-key="requested_by">Requested by</th><th></th>
        </tr></thead>
        <tbody id="st-tbody"></tbody>
      </table></div>
    </div>`;

  function renderStRows(list) {
    const tbody = $('st-tbody');
    if (!list.length) {
      tbody.innerHTML = `<tr><td colspan="9" style="text-align:center;color:var(--t3);padding:3rem"><i class="ti ti-arrows-right-left" style="font-size:2rem;display:block;margin-bottom:.5rem;opacity:.35"></i>${rows.length ? 'No transfers match these filters.' : 'No transfers recorded yet.'}</td></tr>`;
      $('st-count-label').textContent = '0 entries';
      return;
    }
    $('st-count-label').textContent = `${list.length} entr${list.length!==1?'ies':'y'}`;
    tbody.innerHTML = list.map(r => `<tr>
      ${canApprove ? `<td>${r.status==='pending' ? `<input type="checkbox" class="st-row-check" data-id="${r.id}">` : ''}</td>` : ''}
      <td style="white-space:nowrap">
        <div style="font-family:var(--fm);font-size:12px;color:var(--t3)">${r.reference || '—'}</div>
        <div style="font-size:11px;color:var(--t3)">${r.requested_at}</div>
        ${r.reference && r.reference.startsWith('MAT-REQ-') ? `<span class="badge bt" style="font-size:9px;margin-top:2px;display:inline-block">Material Request</span>` : ''}
      </td>
      <td style="font-weight:500">${r.item_name}<div style="font-size:11px;color:var(--t3)">${r.category}</div></td>
      <td>${r.from_warehouse_name}</td>
      <td>${r.to_warehouse_name}</td>
      <td style="font-family:var(--fm);font-weight:600">${r.requested_qty} <span style="color:var(--t3);font-weight:400">${r.uom}</span></td>
      <td style="min-width:130px">${progressBar(r.dispatched_qty, r.received_qty, r.requested_qty)}</td>
      <td>${statusBadge(r.status)}${r.status==='rejected'&&r.rejection_reason?`<div style="font-size:11px;color:var(--red);margin-top:2px">${r.rejection_reason}</div>`:''}${r.status==='completed_with_discrepancy'&&r.discrepancy_qty?`<div style="font-size:11px;color:var(--red);margin-top:2px">${r.discrepancy_qty} ${r.uom} short${r.discrepancy_notes?': '+r.discrepancy_notes:''}</div>`:''}</td>
      <td style="font-size:12px;color:var(--t3)">${r.requested_by||'—'}</td>
      <td style="white-space:nowrap">
        ${canApprove && r.status==='pending' ? `
          <button class="bs1 st-approve" data-id="${r.id}" style="color:var(--green);padding:3px 7px;font-size:11px" title="Approve"><i class="ti ti-check"></i></button>
          <button class="bs1 st-reject" data-id="${r.id}" style="color:var(--red);padding:3px 7px;font-size:11px" title="Reject"><i class="ti ti-x"></i></button>
        ` : ''}
        ${canAct && ['approved','in_transit'].includes(r.status) && r.dispatched_qty < r.requested_qty ? `
          <button class="bs1 st-dispatch" data-id="${r.id}" data-remaining="${r.requested_qty - r.dispatched_qty}" data-item="${r.item_name}" data-uom="${r.uom}" style="color:var(--purple);padding:3px 7px;font-size:11px" title="Record Dispatch"><i class="ti ti-truck"></i></button>
        ` : ''}
        ${canAct && ['in_transit','partially_received'].includes(r.status) && r.received_qty < r.dispatched_qty ? `
          <button class="bs1 st-receive" data-id="${r.id}" data-intransit="${r.dispatched_qty - r.received_qty}" data-item="${r.item_name}" data-uom="${r.uom}" style="color:var(--green);padding:3px 7px;font-size:11px" title="Record Receipt"><i class="ti ti-package-import"></i></button>
        ` : ''}
        ${canAct && ['approved','in_transit','partially_received'].includes(r.status) && r.received_qty < r.requested_qty ? `
          <button class="bs1 st-discrepancy" data-id="${r.id}" data-item="${r.item_name}" data-uom="${r.uom}" data-shortfall="${r.requested_qty - r.received_qty}" data-requested="${r.requested_qty}" data-dispatched="${r.dispatched_qty}" data-received="${r.received_qty}" style="color:var(--red);padding:3px 7px;font-size:11px" title="Close with shortage/damage"><i class="ti ti-alert-triangle"></i></button>
        ` : ''}
        <button class="bs1 st-detail" data-id="${r.id}" style="padding:3px 7px;font-size:11px;color:var(--t3)" title="View details"><i class="ti ti-eye"></i></button>
      </td>
    </tr>`).join('');
    wireStRowActions();
  }

  function updateStBulkBar() {
    const bar = $('st-bulk-bar');
    if (!bar) return;
    const checked = document.querySelectorAll('.st-row-check:checked');
    bar.style.display = checked.length ? 'flex' : 'none';
    if (checked.length) $('st-bulk-count').textContent = `${checked.length} selected`;
  }

  if ($('stAdd')) {
    $('stAdd').onclick = () => {
      const itemOpts = items.map(i => `<option value="${i.id}">${i.name} (${i.category}) — stock: ${i.total_stock} ${i.uom}</option>`).join('');
      const whOpts = warehouses.map(w => `<option value="${w.id}">${w.name}</option>`).join('');
      openOverlay('New Transfer Request', 'Request will be sent for approval before dispatch', `
        <div class="fg"><label>Item *</label><select id="st-item">${itemOpts || '<option>No items</option>'}</select></div>
        <div class="frow">
          <div class="fg"><label>From warehouse *</label><select id="st-from">${whOpts || '<option value="">No warehouses</option>'}</select></div>
          <div class="fg"><label>To warehouse *</label><select id="st-to">${whOpts || '<option value="">No warehouses</option>'}</select></div>
        </div>
        <div class="frow">
          <div class="fg"><label>Quantity *</label><input id="st-qty" type="number" min="1" placeholder="0"></div>
          <div class="fg"><label>Reference</label><input id="st-ref" type="text" placeholder="PO#, transfer ref…"></div>
        </div>
        <div class="fg"><label>Notes</label><input id="st-notes" type="text"></div>
        <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Submit request</button><button class="bs1" id="ovCancel">Cancel</button></div>
      `, async () => {
        if (Number($('st-from').value) === Number($('st-to').value)) { showOverlayError('Source and destination warehouses must be different'); return; }
        const r2 = await UFCL.stockTransfersCreate(STORAGE.user.id, {
          item_id: $('st-item').value,
          from_warehouse_id: $('st-from').value,
          to_warehouse_id: $('st-to').value,
          requested_qty: $('st-qty').value,
          reference: $('st-ref').value.trim(),
          notes: $('st-notes').value.trim()
        });
        if (!r2.ok) { showOverlayError(r2.error); return; }
        showOverlaySuccess('Transfer request submitted.');
        await renderStockTransfers();
      });
    };
  }

  // Phase 2 — row action handlers are re-wired after every renderStRows()
  // call, since rows now re-render on search/filter/sort instead of being
  // static HTML built once. Logic below is otherwise unchanged from Phase 1.
  function wireStRowActions() {
  document.querySelectorAll('.st-approve').forEach(btn => {
    btn.onclick = async () => {
      btn.disabled = true;
      const r2 = await UFCL.stockTransfersApprove(STORAGE.user.id, Number(btn.dataset.id), 'approve', null);
      if (!r2.ok) { showOverlayError(r2.error); btn.disabled = false; return; }
      showOverlaySuccess('Transfer approved.');
      await renderStockTransfers();
    };
  });

  document.querySelectorAll('.st-reject').forEach(btn => {
    btn.onclick = () => confirmAction({
      title: 'Reject Transfer',
      message: 'You are about to reject this stock transfer request.',
      confirmLabel: 'Reject',
      danger: true,
      icon: 'ti-x',
      extraHtml: `<div class="fg"><label>Reason for rejection</label><input id="st-rej-reason" type="text" placeholder="Optional reason"></div>`,
      onConfirm: async () => {
        const r2 = await UFCL.stockTransfersApprove(STORAGE.user.id, Number(btn.dataset.id), 'reject', $('st-rej-reason').value.trim());
        if (!r2.ok) { showOverlayError(r2.error); return; }
        showOverlaySuccess('Transfer rejected.');
        await renderStockTransfers();
      },
    });
  });

  document.querySelectorAll('.st-dispatch').forEach(btn => {
    btn.onclick = () => {
      const transferId = Number(btn.dataset.id);
      const remaining  = Number(btn.dataset.remaining);
      const uom        = btn.dataset.uom;
      const transfer   = rows.find(x => Number(x.id) === transferId);

      const vehOpts = vehicles.length
        ? vehicles.map(v => `<option value="${v.id}">${v.registration}${v.label ? ' — ' + v.label : ''}</option>`).join('')
        : '<option value="" disabled>No active vehicles — register vehicles first</option>';

      const nowLocal = (() => {
        const d = new Date();
        const pad = n => String(n).padStart(2, '0');
        return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
      })();

      openOverlay('Record Dispatch', `Item: ${btn.dataset.item}`, `
        <div class="frow">
          <div class="fg" style="flex:2">
            <label>Vehicle <span style="color:var(--red)">*</span></label>
            <select id="std-vehicle">
              <option value="">— Select vehicle —</option>
              ${vehOpts}
            </select>
          </div>
          <div class="fg">
            <label>Driver name</label>
            <input id="std-driver" type="text" placeholder="Driver (optional)">
          </div>
        </div>
        <div class="frow">
          <div class="fg">
            <label>Dispatch date &amp; time <span style="color:var(--red)">*</span></label>
            <input id="std-datetime" type="datetime-local" value="${nowLocal}">
          </div>
          <div class="fg">
            <label>Quantity dispatched <span style="color:var(--red)">*</span></label>
            <input id="std-qty" type="number" min="1" max="${remaining}" placeholder="Max: ${remaining} ${uom}">
          </div>
        </div>
        <div class="frow">
          <div class="fg"><label>Waybill / Reference</label><input id="std-ref" type="text" placeholder="Waybill #, note…"></div>
          <div class="fg"><label>Notes / Comments</label><input id="std-notes" type="text"></div>
        </div>
        <div class="brow">
          <button class="bp1" id="ovSave"><i class="ti ti-truck"></i> Record Dispatch</button>
          <button class="bs1" id="ovCancel">Cancel</button>
        </div>
      `, async () => {
        const vehicleId = $('std-vehicle').value;
        if (!vehicleId) { showOverlayError('A vehicle must be selected before dispatch can be recorded.'); return; }
        const qtyVal = $('std-qty').value;
        if (!qtyVal || Number(qtyVal) <= 0) { showOverlayError('Please enter a valid dispatch quantity.'); return; }
        if (Number(qtyVal) > remaining) { showOverlayError(`Quantity cannot exceed ${remaining} ${uom}.`); return; }
        const selectedVehicle = vehicles.find(v => Number(v.id) === Number(vehicleId));
        const r2 = await UFCL.stockTransfersDispatch(STORAGE.user.id, transferId, {
          qty:          qtyVal,
          vehicle_id:   vehicleId,
          driver_name:  $('std-driver').value.trim() || null,
          dispatched_at: $('std-datetime').value ? new Date($('std-datetime').value).toISOString() : null,
          reference:    $('std-ref').value.trim() || null,
          notes:        $('std-notes').value.trim() || null,
        });
        if (!r2.ok) { showOverlayError(r2.error); return; }
        const d = r2.dispatch;
        const vehicleLabel = selectedVehicle
          ? `${selectedVehicle.registration}${selectedVehicle.label ? ' — ' + selectedVehicle.label : ''}`
          : '—';
        openOverlay('Dispatch Recorded', null, `
          <div style="display:flex;align-items:center;gap:.75rem;background:rgba(16,185,129,.08);border:1px solid rgba(16,185,129,.3);border-radius:6px;padding:.875rem 1rem;margin-bottom:1.25rem">
            <i class="ti ti-circle-check" style="font-size:1.5rem;color:var(--green);flex-shrink:0"></i>
            <div>
              <div style="font-weight:600;color:var(--green)">Dispatch successfully recorded</div>
              <div style="font-size:12px;color:var(--t3);margin-top:2px">Stock has been deducted from the source warehouse</div>
            </div>
          </div>
          <table style="width:100%;font-size:13px;border-collapse:collapse">
            <tbody>
              <tr style="border-bottom:1px solid var(--bdr)"><td style="padding:6px 0;color:var(--t3);width:45%">Transfer ID</td><td style="padding:6px 0;font-weight:500">#${transferId}</td></tr>
              <tr style="border-bottom:1px solid var(--bdr)"><td style="padding:6px 0;color:var(--t3)">Item</td><td style="padding:6px 0;font-weight:500">${transfer ? transfer.item_name + ' (' + transfer.uom + ')' : '—'}</td></tr>
              <tr style="border-bottom:1px solid var(--bdr)"><td style="padding:6px 0;color:var(--t3)">Source Warehouse</td><td style="padding:6px 0">${transfer ? transfer.from_warehouse_name : '—'}</td></tr>
              <tr style="border-bottom:1px solid var(--bdr)"><td style="padding:6px 0;color:var(--t3)">Destination Warehouse</td><td style="padding:6px 0">${transfer ? transfer.to_warehouse_name : '—'}</td></tr>
              <tr style="border-bottom:1px solid var(--bdr)"><td style="padding:6px 0;color:var(--t3)">Qty Approved</td><td style="padding:6px 0;font-family:var(--fm)">${transfer ? transfer.requested_qty + ' ' + uom : '—'}</td></tr>
              <tr style="border-bottom:1px solid var(--bdr)"><td style="padding:6px 0;color:var(--t3)">Qty Dispatched (this trip)</td><td style="padding:6px 0;font-family:var(--fm);font-weight:600;color:var(--purple)">${d.qty} ${uom}</td></tr>
              <tr style="border-bottom:1px solid var(--bdr)"><td style="padding:6px 0;color:var(--t3)">Assigned Vehicle</td><td style="padding:6px 0">${vehicleLabel}</td></tr>
              <tr style="border-bottom:1px solid var(--bdr)"><td style="padding:6px 0;color:var(--t3)">Driver</td><td style="padding:6px 0">${d.driver_name || '—'}</td></tr>
              <tr style="border-bottom:1px solid var(--bdr)"><td style="padding:6px 0;color:var(--t3)">Dispatch Date &amp; Time</td><td style="padding:6px 0;font-family:var(--fm)">${d.dispatched_at}</td></tr>
              <tr style="border-bottom:1px solid var(--bdr)"><td style="padding:6px 0;color:var(--t3)">Recorded By</td><td style="padding:6px 0">${d.dispatched_by}</td></tr>
              <tr style="border-bottom:1px solid var(--bdr)"><td style="padding:6px 0;color:var(--t3)">Status</td><td style="padding:6px 0"><span class="badge bp">In Transit</span></td></tr>
              <tr><td style="padding:6px 0;color:var(--t3)">Notes</td><td style="padding:6px 0">${d.notes || '—'}</td></tr>
            </tbody>
          </table>
          <div class="brow" style="margin-top:1.25rem">
            <button class="bs1" id="ovCancel">Close</button>
          </div>
        `);
        await renderStockTransfers();
      });

      setTimeout(() => {
        const vSel = $('std-vehicle');
        const driverIn = $('std-driver');
        if (vSel && driverIn) {
          vSel.addEventListener('change', () => {
            const v = vehicles.find(x => Number(x.id) === Number(vSel.value));
            if (v && v.driver_assigned && !driverIn.value) driverIn.value = v.driver_assigned;
          });
        }
      }, 10);
    };
  });

  document.querySelectorAll('.st-detail').forEach(btn => {
    btn.onclick = () => openStockTransferDetailOverlay(Number(btn.dataset.id));
  });

  document.querySelectorAll('.st-receive').forEach(btn => {
    btn.onclick = () => openOverlay('Record Receipt', `Receiving: ${btn.dataset.item}`, `
      <div class="frow">
        <div class="fg"><label>Quantity received *</label><input id="st-rqty" type="number" min="1" max="${btn.dataset.intransit}" placeholder="Max: ${btn.dataset.intransit} ${btn.dataset.uom}"></div>
        <div class="fg"><label>In transit</label><input type="text" value="${btn.dataset.intransit} ${btn.dataset.uom}" disabled style="background:var(--bg2);color:var(--t3)"></div>
      </div>
      <div class="fg"><label>Notes</label><input id="st-rnotes" type="text"></div>
      <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-package-import"></i>Confirm receipt</button><button class="bs1" id="ovCancel">Cancel</button></div>
    `, async () => {
      const r2 = await UFCL.stockTransfersReceive(STORAGE.user.id, Number(btn.dataset.id), $('st-rqty').value, $('st-rnotes').value.trim());
      if (!r2.ok) { showOverlayError(r2.error); return; }
      showOverlaySuccess(r2.completed ? 'Transfer completed — all items received.' : 'Receipt recorded — stock added to destination.');
      await renderStockTransfers();
    });
  });

  document.querySelectorAll('.st-discrepancy').forEach(btn => {
    btn.onclick = () => openOverlay('Close With Shortage / Damage', `Item: ${btn.dataset.item}`, `
      <div class="card" style="padding:10px 12px;margin-bottom:10px;background:var(--bg2)">
        <div class="frow" style="flex-wrap:wrap;gap:1rem;font-size:12px">
          <div><strong>Dispatched</strong><br>${btn.dataset.dispatched} ${btn.dataset.uom}</div>
          <div><strong>Received</strong><br>${btn.dataset.received} ${btn.dataset.uom}</div>
          <div><strong>Difference</strong><br><span style="color:var(--red);font-weight:600">${btn.dataset.shortfall} ${btn.dataset.uom}</span></div>
        </div>
      </div>
      <div class="fg" style="color:var(--red);font-size:12px">This finalizes the transfer now — ${btn.dataset.shortfall} ${btn.dataset.uom} will be recorded as never delivered, and a matching inventory movement will be created so the missing quantity is fully explained on the ledger.</div>
      <div class="fg"><label>Movement Type *</label><select id="st-disc-reason">${DISCREPANCY_REASONS.map(r => `<option value="${r}">${r}</option>`).join('')}</select></div>
      <div class="fg"><label>Reason *</label><input id="st-disc-notes" type="text" placeholder="e.g. 5 bags damaged in transit, source out of stock…"></div>
      <div class="brow"><button class="bp1" id="ovSave" style="background:var(--red)"><i class="ti ti-alert-triangle"></i>Close transfer</button><button class="bs1" id="ovCancel">Cancel</button></div>
    `, async () => {
      const notes = $('st-disc-notes').value.trim();
      const lossReason = $('st-disc-reason').value;
      if (!notes) { showOverlayError('A reason is required.'); return; }
      const r2 = await UFCL.stockTransfersReportDiscrepancy(STORAGE.user.id, Number(btn.dataset.id), notes, lossReason);
      if (!r2.ok) { showOverlayError(r2.error); return; }
      closeOverlay();
      openOverlay('Inventory Movement Recorded', `Transfer #${btn.dataset.id}`, `
        <div class="card" style="padding:10px 12px;background:var(--bg2)">
          <div class="frow" style="flex-wrap:wrap;gap:1rem;font-size:13px">
            <div><strong>Movement #</strong><br>${r2.movementId}</div>
            <div><strong>Type</strong><br>${lossReason}</div>
            <div><strong>Quantity</strong><br>${r2.discrepancyQty} ${btn.dataset.uom}</div>
            <div><strong>Reference Transfer</strong><br>#${btn.dataset.id}</div>
            <div><strong>Status</strong><br><span class="badge bg">Approved</span></div>
          </div>
        </div>
        <div class="brow" style="margin-top:1rem">
          <button class="bp1" id="ovDiscViewMv"><i class="ti ti-arrows-exchange"></i>View Inventory Movement</button>
          <button class="bs1" id="ovCancel">Close</button>
        </div>
      `, null);
      $('ovDiscViewMv').onclick = async () => {
        closeOverlay();
        await renderStockMovements();
        $('sm-status-filter').value = 'loss';
        $('sm-status-filter').dispatchEvent(new Event('change'));
      };
      await renderStockTransfers();
    });
  });

  document.querySelectorAll('.st-row-check').forEach(cb => { cb.onchange = updateStBulkBar; });
  } // end wireStRowActions

  renderStRows(stFiltered());
  wireSortableTable($('st-table'), stSort, stFiltered, renderStRows);
  $('st-search').oninput = (e) => { stState.search = e.target.value; renderStRows(stFiltered()); };
  $('st-status-filter').onchange = (e) => { stState.status = e.target.value; renderStRows(stFiltered()); };
  $('st-clear').onclick = () => { stState.search=''; stState.status=''; $('st-search').value=''; $('st-status-filter').value=''; renderStRows(stFiltered()); };
  $('st-export').onclick = () => _logisticsExportExcel('stock-transfers', {});

  if ($('st-select-all')) {
    $('st-select-all').onchange = (e) => {
      document.querySelectorAll('.st-row-check').forEach(cb => { cb.checked = e.target.checked; });
      updateStBulkBar();
    };
  }
  if ($('st-bulk-approve')) {
    $('st-bulk-approve').onclick = async () => {
      const ids = Array.from(document.querySelectorAll('.st-row-check:checked')).map(cb => Number(cb.dataset.id));
      if (!ids.length) return;
      for (const id of ids) {
        await UFCL.stockTransfersApprove(STORAGE.user.id, id, 'approve', null);
      }
      showOverlaySuccess(`${ids.length} transfer${ids.length>1?'s':''} approved.`);
      await renderStockTransfers();
    };
  }

  bindWorkshopBanner(renderStockTransfers);
}

// ── Material Requests ─────────────────────────────────────────────────────────

// UI/UX redesign — Material Request answers one question ("what does my
// department need"). Everything about *how* it physically moves (source
// warehouse, dispatch, vehicle, driver, receiving, discrepancy) lives only
// in Stock Transfer and is surfaced here read-only via "Linked Transfer" /
// openStockTransferDetailOverlay — never re-implemented.
const MR_STAGE_LIST = ['Submitted', 'Approved', 'Transfer Created', 'In Transit', 'Received', 'Completed'];
function _mrNum(id) { return `MR-${String(id).padStart(6, '0')}`; }
function _mrStage(r) {
  if (r.status === 'rejected') return 'Rejected';
  if (r.status === 'pending') return 'Submitted';
  if (!r.transfer_status) return 'Approved';
  if (r.transfer_status === 'approved') return 'Transfer Created';
  if (r.transfer_status === 'in_transit') return 'In Transit';
  if (r.transfer_status === 'partially_received') return 'Received';
  if (r.transfer_status === 'completed' || r.transfer_status === 'completed_with_discrepancy') return 'Completed';
  return 'Approved';
}
function _mrNeededByFmt(v) {
  if (!v) return null;
  const d = new Date(v);
  return `${String(d.getDate()).padStart(2,'0')}/${String(d.getMonth()+1).padStart(2,'0')}/${d.getFullYear()}`;
}
function _mrOverdue(r) {
  if (!r.needed_by || ['completed', 'rejected'].includes(r.status)) return false;
  const today = new Date(); today.setHours(0,0,0,0);
  return new Date(r.needed_by) < today;
}
function _mrTransferBadge(r) {
  if (!r.transfer_id) return '<span style="font-size:11px;color:var(--t3)">—</span>';
  const labels = { approved:'Transfer Created', in_transit:'In Transit', partially_received:'Partial', completed:'Completed', completed_with_discrepancy:'Completed (Short)' };
  const map = { approved:'bg', in_transit:'bp', partially_received:'ba', completed:'bg', completed_with_discrepancy:'br' };
  return `<button type="button" class="bs1 mr-view-transfer" data-transfer-id="${r.transfer_id}" style="padding:2px 8px;font-size:11px"><span class="badge ${map[r.transfer_status]||'bt'}">${labels[r.transfer_status]||r.transfer_status||'—'}</span></button>`;
}

const MATERIAL_REQUEST_STATUS_META = {
  pending:   { cls: 'ba', label: 'Pending' },
  approved:  { cls: 'bg', label: 'Approved' },
  completed: { cls: 'bg', label: 'Completed' },
};
async function renderMaterialRequests() {
  const res = await UFCL.materialRequestsList(STORAGE.user.id, WORKSHOP_FILTER);
  if (!res.ok) return renderDenied('material-requests', res.error);

  const rows = res.rows || [];
  const isRestricted = !!res.user_workshop_id;
  const canApprove = ['admin','ceo','operations','logistics','supervisor'].includes(STORAGE.user?.role);
  const itemOpts = (res.items||[]).map(i => `<option value="${i.id}" data-stock="${i.total_stock}" data-uom="${i.uom}">[${i.category}] ${i.name} (${i.uom}) — available: ${i.total_stock}</option>`).join('');
  const wshOpts = (res.workshops||[]).map(w => `<option value="${w.id}">${w.name}</option>`).join('');

  // Any status other than pending/approved/completed falls back to "Rejected"
  // (matches this closure's pre-existing behavior — not changed by this pass).
  const statusBadge = s => badgeHtml(MATERIAL_REQUEST_STATUS_META, s, { cls: 'br', label: 'Rejected' });
  const priBadge = p => p==='urgent'?`<span class="badge br" style="font-size:10px">Urgent</span>`:p==='high'?`<span class="badge ba" style="font-size:10px">High</span>`:`<span class="badge bt" style="font-size:10px">Normal</span>`;

  const pending = rows.filter(r=>r.status==='pending').length;
  const approved = rows.filter(r=>r.status==='approved').length;
  const completed = rows.filter(r=>r.status==='completed').length;
  const transferCreated = rows.filter(r=>r.transfer_status==='approved').length;
  const inTransit = rows.filter(r=>['in_transit','partially_received'].includes(r.transfer_status)).length;
  const overdue = rows.filter(_mrOverdue).length;
  const urgent = rows.filter(r=>r.priority==='urgent' && !['completed','rejected'].includes(r.status)).length;
  // Recent Activity — reuses the already-fetched, already-sorted (newest
  // first) rows; no second query, per "do not duplicate Stock Transfer
  // dashboards, only summarize Material Request activity".
  const recentActivity = rows.slice(0, 8).map(r => ({
    label: `${_mrNum(r.id)} — ${r.item_name}`,
    sub: `${r.workshop_name||'—'} · ${r.requested_qty} ${r.uom}`,
    badge: _mrStage(r), warn: r.status==='pending' || _mrOverdue(r),
  }));

  // Phase 2 — enterprise table toolkit (search/filter/sort/bulk).
  const mrState = { search: '', status: '', selected: new Set() };
  const mrSort = { key: null, dir: 'asc' };
  function mrFiltered() {
    return applyProcListFilters(rows, {
      search: mrState.search, searchFields: ['item_name', 'workshop_name', 'reason', 'requested_by'],
      status: mrState.status, statusField: 'status',
    });
  }

  $('page-material-requests').innerHTML = `
    ${workshopBannerHtml(res.workshops, res.user_workshop_id)}
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;margin-bottom:1.5rem">
      <div>
        <div class="ptitle"><i class="ti ti-clipboard-list" style="color:var(--g-soft)"></i> Material Requests</div>
        <div class="psub">${isRestricted?'Request materials for your workshop and track their progress.':'Review, approve, and track material requests from all workshops.'}</div>
      </div>
      <div style="display:flex;gap:.5rem">
        <button class="bs1" id="mr-export"><i class="ti ti-file-spreadsheet"></i>Export Excel</button>
        <button class="bp1" id="mrAdd"><i class="ti ti-plus"></i>New request</button>
      </div>
    </div>
    <div class="cards" style="margin-bottom:1.25rem">
      <div class="mc"><div class="mclbl">Pending</div><div class="mcval" style="${pending>0?'color:var(--amber)':''}">${pending}</div><div class="mcsub ca"><i class="ti ti-clock"></i>awaiting review</div></div>
      <div class="mc"><div class="mclbl">Approved</div><div class="mcval" style="color:var(--green)">${approved}</div><div class="mcsub cg"><i class="ti ti-circle-check"></i>authorized</div></div>
      <div class="mc"><div class="mclbl">Transfer Created</div><div class="mcval">${transferCreated}</div><div class="mcsub bp"><i class="ti ti-arrows-right-left"></i>awaiting dispatch</div></div>
      <div class="mc"><div class="mclbl">In Transit</div><div class="mcval">${inTransit}</div><div class="mcsub bp"><i class="ti ti-truck"></i>on the way</div></div>
      <div class="mc"><div class="mclbl">Completed</div><div class="mcval" style="color:var(--green)">${completed}</div><div class="mcsub cg"><i class="ti ti-package"></i>received</div></div>
      <div class="mc"><div class="mclbl">Overdue</div><div class="mcval" style="${overdue>0?'color:var(--red)':''}">${overdue}</div><div class="mcsub ${overdue>0?'cr':''}"><i class="ti ti-calendar-exclamation"></i>past needed-by</div></div>
      <div class="mc"><div class="mclbl">Urgent</div><div class="mcval" style="${urgent>0?'color:var(--red)':''}">${urgent}</div><div class="mcsub ${urgent>0?'cr':''}"><i class="ti ti-alert-triangle"></i>high priority</div></div>
      <div class="mc"><div class="mclbl">Total</div><div class="mcval">${rows.length}</div><div class="mcsub cg"><i class="ti ti-clipboard-list"></i>all requests</div></div>
    </div>
    ${_lgdWidget('Recent Activity', 'ti-activity', recentActivity, 'No recent activity.')}
    <div style="height:1.25rem"></div>
    ${procFilterBarHtml({
      searchId: 'mr-search', searchPlaceholder: 'Search item, workshop, reason, requester…',
      statusId: 'mr-status-filter', statusOptions: ['pending', 'approved', 'completed', 'rejected'],
      clearId: 'mr-clear',
    })}
    ${canApprove ? `<div id="mr-bulk-bar" class="bulk-bar" style="display:none">
      <span id="mr-bulk-count">0 selected</span>
      <button type="button" class="bs1" id="mr-bulk-approve" style="margin-left:.5rem"><i class="ti ti-check"></i>Approve selected</button>
      <button type="button" class="bs1" id="mr-bulk-clear" style="margin-left:auto">Clear selection</button>
    </div>` : ''}
    <div class="card" style="padding:0">
      <div style="padding:.9rem 1.25rem;border-bottom:1px solid var(--bdr);display:flex;align-items:center;justify-content:space-between">
        <h3 style="margin:0"><i class="ti ti-clipboard-list"></i> Request Log</h3>
        <span id="mr-count-label" style="font-size:12px;color:var(--t3)">${rows.length} request${rows.length!==1?'s':''}</span>
      </div>
      <div class="tw"><table class="tbl" id="mr-table">
        <thead><tr>
          ${canApprove ? '<th style="width:28px"><input type="checkbox" id="mr-select-all"></th>' : ''}
          <th data-sort-key="id">Request #</th><th data-sort-key="requested_at">Date</th>
          <th data-sort-key="workshop_name">Workshop</th><th data-sort-key="requested_by">Requester</th>
          <th>Items</th><th data-sort-key="priority">Priority</th><th data-sort-key="status">Status</th>
          <th data-sort-key="needed_by">Needed By</th><th>Linked Transfer</th><th>Actions</th>
        </tr></thead>
        <tbody id="mr-tbody"></tbody>
      </table></div>
    </div>
  `;

  function renderMrRows(list) {
    const tbody = $('mr-tbody');
    const cols = (canApprove?1:0) + 10;
    if (!list.length) {
      tbody.innerHTML = `<tr><td colspan="${cols}" style="text-align:center;color:var(--t3);padding:3rem">No requests match these filters.</td></tr>`;
      $('mr-count-label').textContent = '0 requests';
      return;
    }
    $('mr-count-label').textContent = `${list.length} request${list.length!==1?'s':''}`;
    tbody.innerHTML = list.map(r=>`
    <tr>
      ${canApprove ? `<td onclick="event.stopPropagation()"><input type="checkbox" class="mr-chk" data-id="${r.id}" ${r.status==='pending'?'':'disabled'} ${mrState.selected.has(String(r.id))?'checked':''}></td>` : ''}
      <td style="font-family:var(--fm);font-size:12px;font-weight:600">${_mrNum(r.id)}</td>
      <td style="font-size:11px;color:var(--t3)">${r.requested_at}</td>
      <td style="font-size:12px">${r.workshop_name||'—'}</td>
      <td style="font-size:12px;color:var(--t3)">${r.requested_by||'—'}</td>
      <td>${r.item_name}<br><span style="font-size:11px;color:var(--t3)">${r.requested_qty} ${r.uom}${r.approved_qty ? ` · approved ${r.approved_qty}` : ''}</span></td>
      <td>${priBadge(r.priority)}</td>
      <td>${statusBadge(r.status)}${_mrOverdue(r) ? `<div style="font-size:10px;color:var(--red);margin-top:2px"><i class="ti ti-calendar-exclamation"></i> Overdue</div>` : ''}</td>
      <td style="font-size:12px;${_mrOverdue(r)?'color:var(--red);font-weight:600':'color:var(--t3)'}">${_mrNeededByFmt(r.needed_by) || '—'}</td>
      <td>${_mrTransferBadge(r)}</td>
      <td style="white-space:nowrap">
        <button class="bs1 mr-view" data-id="${r.id}" title="View details"><i class="ti ti-eye"></i></button>
        ${canApprove && r.status==='pending' ? `
          <button class="bs1 mr-appr" data-id="${r.id}" data-qty="${r.requested_qty}" style="color:var(--green);padding:4px 8px;font-size:12px;margin-left:4px"><i class="ti ti-check"></i>Approve</button>
          <button class="bs1 mr-rej" data-id="${r.id}" style="color:var(--red);padding:4px 8px;font-size:12px;margin-left:4px"><i class="ti ti-x"></i>Reject</button>
        ` : ''}
      </td>
    </tr>`).join('');
    wireMrRowActions();
  }

  function wireMrRowActions() {
    document.querySelectorAll('.mr-view').forEach(btn => {
      btn.onclick = () => { const r = rows.find(x=>String(x.id)===btn.dataset.id); if (r) openMaterialRequestDetailOverlay(r); };
    });
    document.querySelectorAll('.mr-view-transfer').forEach(btn => {
      btn.onclick = (e) => { e.stopPropagation(); openStockTransferDetailOverlay(Number(btn.dataset.transferId)); };
    });
    document.querySelectorAll('.mr-chk').forEach(chk => {
      chk.onchange = () => {
        const id = chk.dataset.id;
        if (chk.checked) mrState.selected.add(id); else mrState.selected.delete(id);
        updateMrBulkBar();
      };
    });
    if (canApprove) {
      document.querySelectorAll('.mr-appr').forEach(btn => { btn.onclick = () => openApproveOverlay(btn.dataset.id, btn.dataset.qty); });
      document.querySelectorAll('.mr-rej').forEach(btn => { btn.onclick = () => openRejectOverlay(btn.dataset.id); });
    }
  }

  function updateMrBulkBar() {
    if (!canApprove) return;
    const n = mrState.selected.size;
    $('mr-bulk-bar').style.display = n > 0 ? 'flex' : 'none';
    $('mr-bulk-count').textContent = `${n} selected`;
  }

  // Manager-only action — still lives on Material Requests (approving the
  // *request* is what authorizes the transfer), but everything it produces
  // (the transfer itself, dispatch, receiving) is then owned exclusively by
  // Stock Transfer. See MATERIAL_REQUEST_UI_UX_REDESIGN_REPORT.md §4.
  function openApproveOverlay(idStr, reqQty) {
    const r = rows.find(x => String(x.id) === String(idStr));
    const needsDest = !r || !r.workshop_id;
    openOverlay('Approve Request', null, `
      <div class="frow">
        <div class="fg"><label>Approved Quantity</label><input id="appr-qty" type="number" min="1" value="${reqQty}"></div>
        <div class="fg"><label>Source Workshop (to issue from) *</label><select id="appr-src"><option value="">— Select —</option>${wshOpts}</select></div>
      </div>
      ${needsDest ? `<div class="fg"><label>Destination Workshop (to receive) *</label><select id="appr-dest"><option value="">— Select —</option>${wshOpts}</select></div>` : ''}
      <div class="fg"><label>Notes</label><input id="appr-notes" type="text" placeholder="Optional notes"></div>
      <div class="brow"><button class="bp1" id="ovSave" style="background:var(--green)"><i class="ti ti-check"></i>Confirm Approve</button><button class="bs1" id="ovCancel">Cancel</button></div>
    `, async () => {
      const src = $('appr-src').value;
      if (!src) { showOverlayError('A source workshop is required.'); return; }
      const dest = needsDest ? $('appr-dest').value : null;
      if (needsDest && !dest) { showOverlayError('A destination workshop is required.'); return; }
      const res2 = await UFCL.materialRequestsApprove(
        STORAGE.user.id, Number(idStr), 'approve',
        $('appr-qty').value, $('appr-notes').value.trim(), src, dest || null
      );
      if (!res2.ok) { showOverlayError(res2.error); return; }
      showOverlaySuccess('Request approved — a stock transfer was created and is ready for dispatch.');
      await renderMaterialRequests();
    });
  }

  function openRejectOverlay(idStr) {
    openOverlay('Reject Request', null, `
      <div class="fg"><label>Rejection Reason *</label><input id="rej-notes" type="text" placeholder="Explain why this request is rejected"></div>
      <div class="brow"><button class="bp1" id="ovSave" style="background:var(--red)"><i class="ti ti-x"></i>Confirm Reject</button><button class="bs1" id="ovCancel">Cancel</button></div>
    `, async () => {
      const notes = $('rej-notes').value.trim();
      if (!notes) { showOverlayError('Rejection reason is required.'); return; }
      const res2 = await UFCL.materialRequestsApprove(STORAGE.user.id, Number(idStr), 'reject', null, notes, null);
      if (!res2.ok) { showOverlayError(res2.error); return; }
      showOverlaySuccess('Request rejected.');
      await renderMaterialRequests();
    });
  }

  // Tabbed detail overlay (Overview / Items / Linked Transfer / History) —
  // reuses the same .smo-tabs/.smo-tab visual language already established
  // by the Supplier profile overlay, not a new tab component.
  function openMaterialRequestDetailOverlay(r) {
    const TAB_META = {
      overview: { label: 'Overview', icon: 'ti-info-circle' },
      items: { label: 'Items', icon: 'ti-package' },
      transfer: { label: 'Linked Transfer', icon: 'ti-arrows-right-left' },
      history: { label: 'History', icon: 'ti-history' },
    };
    openOverlay(`Material Request ${_mrNum(r.id)}`, null, `
      <div class="smo-tabs" id="mrd-tabs">
        ${Object.entries(TAB_META).map(([t, m]) => `<button type="button" class="smo-tab ${t==='overview'?'active':''}" data-tab="${t}"><i class="ti ${m.icon}"></i>${m.label}</button>`).join('')}
      </div>
      <div id="mrd-body"></div>
      <div class="brow" style="margin-top:1rem">
        ${canApprove && r.status==='pending' ? `
          <button class="bp1" id="mrd-approve" style="background:var(--green)"><i class="ti ti-check"></i>Approve</button>
          <button class="bs1" id="mrd-reject" style="color:var(--red)"><i class="ti ti-x"></i>Reject</button>
        ` : ''}
        <button class="bs1" id="ovCancel">Close</button>
      </div>`, null);

    function renderOverviewTab(body) {
      body.innerHTML = `
        <div class="frow" style="margin-bottom:10px">${statusBadge(r.status)} ${priBadge(r.priority)}</div>
        <div class="card" style="padding:12px 14px;margin-bottom:12px;background:var(--bg2)">
          <div class="frow" style="flex-wrap:wrap;gap:1.25rem;font-size:13px">
            <div><strong>Request #</strong><br>${_mrNum(r.id)}</div>
            <div><strong>Request Date</strong><br>${r.requested_at}</div>
            <div><strong>Workshop</strong><br>${r.workshop_name||'—'}</div>
            <div><strong>Requested by</strong><br>${r.requested_by||'—'}</div>
            <div><strong>Needed by</strong><br>${_mrNeededByFmt(r.needed_by) || '—'}${_mrOverdue(r) ? ' <span style="color:var(--red)">(overdue)</span>' : ''}</div>
            ${r.reviewed_by ? `<div><strong>Reviewed by</strong><br>${r.reviewed_by}</div>` : ''}
          </div>
          <div style="margin-top:8px;font-size:13px"><strong>Purpose / Business Justification:</strong> ${r.reason||'—'}</div>
          ${r.review_notes ? `<div style="margin-top:4px;font-size:13px"><strong>Review notes:</strong> ${r.review_notes}</div>` : ''}
        </div>
        <div style="font-size:12px;font-weight:700;color:var(--t3);margin-bottom:6px;text-transform:uppercase;letter-spacing:.03em">Approval Progress</div>
        <div>${_statusTimelineHtml(MR_STAGE_LIST, _mrStage(r), ['Rejected'])}</div>
      `;
    }

    function renderItemsTab(body) {
      body.innerHTML = `
        <div class="tw"><table class="dt">
          <thead><tr><th>Item</th><th>Category</th><th>Available Stock</th><th>Qty Requested</th><th>Unit</th></tr></thead>
          <tbody>
            <tr>
              <td style="font-weight:500">${r.item_name}</td>
              <td>${r.category}</td>
              <td style="color:var(--t3)">read-only — see Stock Catalog</td>
              <td style="font-family:var(--fm);font-weight:600">${r.approved_qty || r.requested_qty}${r.approved_qty && r.approved_qty !== r.requested_qty ? ` <span style="color:var(--t3);font-weight:400;font-size:11px">(requested ${r.requested_qty})</span>` : ''}</td>
              <td>${r.uom}</td>
            </tr>
          </tbody>
        </table></div>
        <p style="font-size:11px;color:var(--t3);margin-top:8px">One item per request in the current data model. Stock is never adjusted from this screen — quantities only change once the linked Stock Transfer is dispatched and received.</p>
      `;
    }

    async function renderTransferTab(body) {
      if (!r.transfer_id) {
        body.innerHTML = `<div style="text-align:center;padding:2rem;color:var(--t3)"><i class="ti ti-arrows-right-left" style="font-size:1.5rem;display:block;margin-bottom:.5rem;opacity:.35"></i>No Stock Transfer yet — this request has not been approved.</div>`;
        return;
      }
      body.innerHTML = `<p style="color:var(--t3);font-size:12px">Loading…</p>`;
      const res2 = await UFCL.stockTransfersDispatchHistory(STORAGE.user.id, r.transfer_id);
      if (!res2.ok || !res2.transfer) { body.innerHTML = `<p style="color:var(--red);font-size:12px">Could not load the linked transfer.</p>`; return; }
      const t = res2.transfer;
      const disp = (res2.dispatches || [])[res2.dispatches.length - 1] || null;
      const labels = { pending:'Pending', approved:'Approved', in_transit:'In Transit', partially_received:'Partially Received', completed:'Completed', completed_with_discrepancy:'Completed (Short)', rejected:'Rejected', cancelled:'Cancelled' };
      const map = { pending:'ba', approved:'bg', in_transit:'bp', partially_received:'ba', completed:'bg', completed_with_discrepancy:'br', rejected:'br', cancelled:'br' };
      body.innerHTML = `
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:.5rem 1.5rem;background:var(--bg2);border-radius:6px;padding:.875rem 1rem;margin-bottom:1.25rem;font-size:13px">
          <div><span style="color:var(--t3)">Transfer Number:</span> <strong>#${t.id}</strong></div>
          <div><span style="color:var(--t3)">Transfer Status:</span> <span class="badge ${map[t.status]||'bt'}">${labels[t.status]||t.status}</span></div>
          <div><span style="color:var(--t3)">Source Warehouse:</span> ${t.from_warehouse_name}</div>
          <div><span style="color:var(--t3)">Destination Workshop:</span> ${t.to_warehouse_name}</div>
          <div><span style="color:var(--t3)">Vehicle:</span> ${disp && disp.registration ? disp.registration + (disp.vehicle_label ? ' — ' + disp.vehicle_label : '') : '—'}</div>
          <div><span style="color:var(--t3)">Driver:</span> ${disp ? (disp.driver_name || '—') : '—'}</div>
          <div><span style="color:var(--t3)">Dispatch Date:</span> ${disp ? disp.dispatched_at : '—'}</div>
          <div><span style="color:var(--t3)">Received Qty:</span> ${t.received_qty} / ${t.requested_qty}</div>
        </div>
        ${t.status === 'completed_with_discrepancy' ? `
        <div style="background:rgba(239,68,68,.08);border:1px solid rgba(239,68,68,.3);border-radius:6px;padding:.75rem 1rem;margin-bottom:1.25rem">
          <div style="font-weight:600;color:var(--red);font-size:13px"><i class="ti ti-alert-triangle"></i> Closed with shortage: ${t.discrepancy_qty || 0} ${t.uom} short</div>
          ${t.discrepancy_notes ? `<div style="font-size:12px;color:var(--t2);margin-top:4px">${t.discrepancy_notes}</div>` : ''}
        </div>` : ''}
        <button type="button" class="bs1" id="mrd-view-transfer"><i class="ti ti-eye"></i> View Transfer (full dispatch/receive log)</button>
        <p style="font-size:11px;color:var(--t3);margin-top:10px">Dispatch, transportation, and receiving are managed entirely on the Stock Transfers page — this is a read-only summary.</p>
      `;
      const vt = $('mrd-view-transfer'); if (vt) vt.onclick = () => openStockTransferDetailOverlay(t.id);
    }

    function renderHistoryTab(body) {
      body.innerHTML = `<div id="mrd-history"></div>`;
      _loadLogisticsHistoryInto('mrd-history', 'material-requests', r.id);
    }

    function loadTab(tab) {
      const body = $('mrd-body');
      if (tab === 'overview') return renderOverviewTab(body);
      if (tab === 'items') return renderItemsTab(body);
      if (tab === 'transfer') return renderTransferTab(body);
      if (tab === 'history') return renderHistoryTab(body);
    }
    document.querySelectorAll('#mrd-tabs .smo-tab').forEach(btn => {
      btn.onclick = () => {
        document.querySelectorAll('#mrd-tabs .smo-tab').forEach(b => b.classList.remove('active'));
        btn.classList.add('active');
        loadTab(btn.dataset.tab);
      };
    });
    loadTab('overview');

    setTimeout(() => {
      const ap = $('mrd-approve'); if (ap) ap.onclick = () => { closeOverlay(); openApproveOverlay(r.id, r.requested_qty); };
      const rj = $('mrd-reject'); if (rj) rj.onclick = () => { closeOverlay(); openRejectOverlay(r.id); };
    }, 30);
  }

  renderMrRows(mrFiltered());
  wireSortableTable($('mr-table'), mrSort, mrFiltered, renderMrRows);
  $('mr-search').oninput = (e) => { mrState.search = e.target.value; renderMrRows(mrFiltered()); };
  $('mr-status-filter').onchange = (e) => { mrState.status = e.target.value; renderMrRows(mrFiltered()); };
  $('mr-clear').onclick = () => { mrState.search=''; mrState.status=''; $('mr-search').value=''; $('mr-status-filter').value=''; renderMrRows(mrFiltered()); };
  if (canApprove) {
    $('mr-select-all').onchange = (e) => {
      const list = mrFiltered().filter(r => r.status === 'pending');
      if (e.target.checked) list.forEach(r => mrState.selected.add(String(r.id)));
      else list.forEach(r => mrState.selected.delete(String(r.id)));
      renderMrRows(mrFiltered());
      updateMrBulkBar();
    };
    $('mr-bulk-clear').onclick = () => { mrState.selected.clear(); renderMrRows(mrFiltered()); updateMrBulkBar(); };
    $('mr-bulk-approve').onclick = () => {
      // Business Process Review — bulk approval now needs one common source
      // workshop up front (each approval creates its own Stock Transfer).
      // Requests with no destination workshop of their own can't be safely
      // bulk-approved (there's no way to pick a different destination per
      // row here), so they're skipped and reported.
      const ids = Array.from(mrState.selected);
      const skippable = ids.filter(id => { const r = rows.find(x => String(x.id) === id); return !r || !r.workshop_id; });
      openOverlay('Bulk Approve Requests', `${ids.length} selected`, `
        ${skippable.length ? `<div class="fg" style="color:var(--amber);font-size:12px">${skippable.length} selected request(s) have no destination workshop and will be skipped.</div>` : ''}
        <div class="fg"><label>Source Workshop (to issue from) *</label><select id="bulk-appr-src"><option value="">— Select —</option>${wshOpts}</select></div>
        <div class="brow"><button class="bp1" id="ovSave" style="background:var(--green)"><i class="ti ti-check"></i>Approve selected</button><button class="bs1" id="ovCancel">Cancel</button></div>
      `, async () => {
        const src = $('bulk-appr-src').value;
        if (!src) { showOverlayError('A source workshop is required.'); return; }
        let okCount = 0, skipCount = 0;
        for (const id of ids) {
          const r = rows.find(x => String(x.id) === id);
          if (!r || !r.workshop_id) { skipCount++; continue; }
          const r2 = await UFCL.materialRequestsApprove(STORAGE.user.id, Number(id), 'approve', r.requested_qty, null, src, null);
          if (r2.ok) okCount++;
        }
        showOverlaySuccess(`${okCount} request${okCount!==1?'s':''} approved.${skipCount ? ` ${skipCount} skipped (no destination workshop).` : ''}`);
        mrState.selected.clear();
        await renderMaterialRequests();
      });
    };
  }

  // Redesigned create screen — Section 1 (Request Information, auto fields +
  // priority + needed-by + purpose) and Section 2 (Requested Items, a
  // single-row enterprise item table showing available stock read-only).
  // Attachments are deferred (no file/photo upload framework exists
  // anywhere in this codebase yet — see report §5) to a plain optional
  // reference/notes field rather than inventing new upload infrastructure.
  $('mr-export').onclick = () => _logisticsExportExcel('material-requests', {});
  $('mrAdd').onclick = () => {
    const today = new Date();
    const todayFmt = `${String(today.getDate()).padStart(2,'0')}/${String(today.getMonth()+1).padStart(2,'0')}/${today.getFullYear()}`;
    openOverlay('New Material Request', 'What materials does your department need?', `
      <div style="font-size:12px;font-weight:700;color:var(--t3);margin-bottom:8px;text-transform:uppercase;letter-spacing:.03em">Request Information</div>
      <div class="frow" style="flex-wrap:wrap;gap:1rem;background:var(--bg2);border-radius:6px;padding:10px 12px;margin-bottom:12px;font-size:12px">
        <div><span style="color:var(--t3)">Request #</span><br><strong>Assigned on submit</strong></div>
        <div><span style="color:var(--t3)">Request Date</span><br><strong>${todayFmt}</strong></div>
        <div><span style="color:var(--t3)">Requesting Workshop</span><br><strong>${isRestricted ? ((res.workshops||[]).find(w=>String(w.id)===String(res.user_workshop_id))?.name || 'Your workshop') : 'Select below'}</strong></div>
        <div><span style="color:var(--t3)">Requested By</span><br><strong>${STORAGE.user?.name || '—'}</strong></div>
      </div>
      <div class="frow">
        ${!isRestricted?`<div class="fg"><label>Requesting Workshop</label><select id="mr-wsh"><option value="">— All / not workshop-specific —</option>${wshOpts}</select></div>`:''}
        <div class="fg"><label>Priority</label>
          <select id="mr-pri">
            <option value="normal">Normal</option>
            <option value="high">High</option>
            <option value="urgent">Urgent</option>
          </select>
        </div>
        <div class="fg"><label>Needed By</label><input id="mr-needed" type="date"></div>
      </div>
      <div class="fg"><label>Purpose / Business Justification</label><input id="mr-reason" type="text" placeholder="Why is this item needed?"></div>

      <div style="font-size:12px;font-weight:700;color:var(--t3);margin:16px 0 8px;text-transform:uppercase;letter-spacing:.03em">Requested Items</div>
      <div class="tw"><table class="dt">
        <thead><tr><th>Item</th><th>Category</th><th>Available Stock</th><th>Qty Requested</th><th>Unit</th></tr></thead>
        <tbody><tr>
          <td style="min-width:220px"><select id="mr-item" style="width:100%"><option value="">— Select item —</option>${itemOpts}</select></td>
          <td id="mr-item-cat" style="color:var(--t3)">—</td>
          <td id="mr-item-stock" style="color:var(--t3)">—</td>
          <td style="width:100px"><input id="mr-qty" type="number" min="1" placeholder="0" style="width:100%"></td>
          <td id="mr-item-uom" style="color:var(--t3)">—</td>
        </tr></tbody>
      </table></div>

      <div style="font-size:12px;font-weight:700;color:var(--t3);margin:16px 0 8px;text-transform:uppercase;letter-spacing:.03em">Attachments <span style="text-transform:none;font-weight:400">(optional)</span></div>
      <div class="fg"><input id="mr-attach-ref" type="text" placeholder="Reference to a document/photo/specification (e.g. a file name or ticket #)"></div>

      <div class="brow" style="margin-top:1rem"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Submit request</button><button class="bs1" id="ovCancel">Cancel</button></div>
    `, async () => {
      const attachRef = $('mr-attach-ref').value.trim();
      const reason = $('mr-reason').value.trim();
      const res2 = await UFCL.materialRequestsCreate(STORAGE.user.id, {
        item_id: $('mr-item').value,
        requested_qty: $('mr-qty').value,
        workshop_id: document.getElementById('mr-wsh')?.value || null,
        priority: $('mr-pri').value,
        needed_by: $('mr-needed').value || null,
        reason: attachRef ? `${reason}${reason ? ' — ' : ''}Ref: ${attachRef}` : reason,
      });
      if (!res2.ok) { showOverlayError(res2.error); return; }
      showOverlaySuccess('Request submitted.');
      await renderMaterialRequests();
    });
    const itemSel = $('mr-item');
    itemSel.onchange = () => {
      const opt = itemSel.options[itemSel.selectedIndex];
      const item = (res.items||[]).find(i => String(i.id) === itemSel.value);
      $('mr-item-cat').textContent = item ? item.category : '—';
      $('mr-item-stock').textContent = item ? `${item.total_stock} ${item.uom}` : '—';
      $('mr-item-uom').textContent = item ? item.uom : '—';
    };
  };

  bindWorkshopBanner(renderMaterialRequests);
}

// ── Vehicles ──────────────────────────────────────────────────────────────────

function vehicleStatusBadge(s) {
  const map = { Active: 'bg', 'In Maintenance': 'ba', Inactive: 'br' };
  return `<span class="badge ${map[s]||'bt'}">${s}</span>`;
}

// Fleet & Equipment Phase 2 — Executive Operational Dashboard, reused verbatim
// as the "Fleet Register" list's own KPI/widget header (matching how
// Inventory's Phase 2 dashboard was built directly into its existing list
// page rather than a new nav entry). `_lgdWidget`/`_svgBar` etc. are the
// same shared components already used by Inventory/Workshop's dashboards.
function _fleetKpiCardsHtml(kpi) {
  return `<div class="cards" style="margin-bottom:1.25rem">
    <div class="mc"><div class="mclbl">Total Vehicles</div><div class="mcval">${kpi.totalVehicles}</div><div class="mcsub cg"><i class="ti ti-truck"></i>fleet</div></div>
    <div class="mc"><div class="mclbl">Active Vehicles</div><div class="mcval">${kpi.activeVehicles}</div><div class="mcsub cg"><i class="ti ti-circle-check"></i>operational</div></div>
    <div class="mc"><div class="mclbl">Vehicles Maintenance</div><div class="mcval" style="${kpi.vehiclesInMaintenance>0?'color:var(--amber)':''}">${kpi.vehiclesInMaintenance}</div><div class="mcsub ${kpi.vehiclesInMaintenance>0?'ca':'cg'}"><i class="ti ti-tool"></i>off-road</div></div>
    <div class="mc"><div class="mclbl">Out of Service</div><div class="mcval" style="${kpi.vehiclesOutOfService>0?'color:var(--red)':''}">${kpi.vehiclesOutOfService}</div><div class="mcsub ${kpi.vehiclesOutOfService>0?'cr':''}"><i class="ti ti-circle-x"></i>inactive</div></div>
    <div class="mc"><div class="mclbl">Total Machines</div><div class="mcval">${kpi.totalMachines}</div><div class="mcsub cg"><i class="ti ti-settings-2"></i>registry</div></div>
    <div class="mc"><div class="mclbl">Active Machines</div><div class="mcval">${kpi.activeMachines}</div><div class="mcsub cg"><i class="ti ti-circle-check"></i>available/running</div></div>
    <div class="mc"><div class="mclbl">Fuel This Month (L)</div><div class="mcval">${Math.round(kpi.fuelLitersThisMonth).toLocaleString()}</div><div class="mcsub bp"><i class="ti ti-gas-station"></i>vehicles + machines</div></div>
    <div class="mc"><div class="mclbl">Fuel Cost This Month</div><div class="mcval">${Math.round(kpi.fuelCostThisMonth).toLocaleString()}</div><div class="mcsub bp"><i class="ti ti-currency-dollar"></i>RWF, vehicles</div></div>
    <div class="mc"><div class="mclbl">Maintenance Cost</div><div class="mcval">${Math.round(kpi.maintenanceCostThisMonth).toLocaleString()}</div><div class="mcsub bp"><i class="ti ti-tool"></i>RWF this month</div></div>
    <div class="mc"><div class="mclbl">Open Maintenance Jobs</div><div class="mcval" style="${kpi.openMaintenanceJobs>0?'color:var(--amber)':''}">${kpi.openMaintenanceJobs}</div><div class="mcsub ${kpi.openMaintenanceJobs>0?'ca':'cg'}"><i class="ti ti-calendar-due"></i>due ≤14 days</div></div>
    <div class="mc"><div class="mclbl">Available Fleet</div><div class="mcval">${kpi.availableFleetPct}%</div><div class="mcsub cg"><i class="ti ti-gauge"></i>vehicles active</div></div>
    <div class="mc"><div class="mclbl">Fleet Utilization</div><div class="mcval">${kpi.utilizationPct}%</div><div class="mcsub cg"><i class="ti ti-chart-bar"></i>vehicles + machines</div></div>
  </div>`;
}

function _fleetWidgetsHtml(w) {
  const dateItem = (label, sub, badge, warn) => ({ label, sub, badge, warn });
  return `<div class="cards" style="grid-template-columns:repeat(auto-fit,minmax(260px,1fr));margin-bottom:1.25rem">
    ${_lgdWidget('Vehicles Needing Maintenance', 'ti-alert-triangle',
      w.vehiclesNeedingMaintenance.map(r => dateItem(r.registration, 'Next due', r.next_due ? new Date(r.next_due).toLocaleDateString('en-GB') : '—', true)),
      'No vehicles due for maintenance in the next 14 days.')}
    ${_lgdWidget('Machines Requiring Attention', 'ti-settings-2',
      w.machinesRequiringAttention.map(r => dateItem(`${r.machine_code} — ${r.name}`, r.status, r.status, true)),
      'No machines under maintenance or breakdown.')}
    ${_lgdWidget('Recent Fuel Activity', 'ti-gas-station',
      w.recentFuelActivity.map(r => dateItem(r.ref, r.kind === 'vehicle' ? `${r.liters}L${r.total_cost ? ' · RWF ' + Math.round(r.total_cost).toLocaleString() : ''}` : `${r.quantity}L (machine)`, r.log_date)),
      'No fuel activity recorded.')}
    ${_lgdWidget('Recent Maintenance', 'ti-tool',
      w.recentMaintenance.map(r => dateItem(r.ref, `${r.maintenance_type}${r.cost ? ' · RWF ' + Math.round(r.cost).toLocaleString() : ''}`, r.maintenance_date)),
      'No maintenance recorded yet.')}
    ${_lgdWidget('Assigned Vehicles', 'ti-steering-wheel',
      w.assignedVehicles.map(r => dateItem(r.registration, 'Driver assigned', r.driver_assigned)),
      'No vehicles currently show a driver assignment.')}
    ${_lgdWidget('Pending Approvals', 'ti-clock',
      w.pendingApprovals.map(r => dateItem(r.entity_ref || r.entity_type, r.kind === 'edit' ? 'Edit request' : 'Deletion request', r.required_level, true)),
      'No Fleet approvals pending.')}
    ${_lgdWidget('Recent Operational Activity', 'ti-activity',
      w.recentActivity.map(r => dateItem(r.action, `${r.full_name || '—'} · ${r.role}`, new Date(r.created_at).toLocaleDateString('en-GB'))),
      'No recent Fleet activity.')}
  </div>`;
}

// Fleet & Equipment Phase 3 — Operational Intelligence: trend charts, top
// lists, forecasting-style estimates, and cross-department visibility.
// Reuses the existing shared SVG chart helpers (_svgBar) and _lgdWidget —
// no new charting mechanism, no new calculation engine, matching the exact
// composition pattern established by Inventory's own Phase 3 section.
function _fleetIntelligenceHtml(iq) {
  if (!iq) return '';
  const t = iq.trends || {};
  const monthLabels = (rows) => `<div style="display:flex;justify-content:space-between;margin-top:.4rem;font-size:10px;color:var(--t3)">${(rows||[]).map(m=>`<span>${m.month.slice(5)}</span>`).join('')}</div>`;
  return `
    <div style="font-weight:600;font-size:13px;color:var(--t1);margin-bottom:.75rem"><i class="ti ti-chart-dots" style="color:var(--g-soft)"></i> Operational Intelligence</div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:1rem;margin-bottom:1.25rem">
      <div class="card">
        <h3 style="margin:0 0 .75rem"><i class="ti ti-chart-line"></i> Maintenance Events <span style="font-size:11px;font-weight:400;color:var(--t3)">· last 6 months</span></h3>
        ${_svgBar(t.maintenanceMonths||[], 'count', { color: 'var(--amber)' })}
        ${monthLabels(t.maintenanceMonths)}
      </div>
      <div class="card">
        <h3 style="margin:0 0 .75rem"><i class="ti ti-chart-line"></i> Maintenance Cost <span style="font-size:11px;font-weight:400;color:var(--t3)">· RWF, last 6 months</span></h3>
        ${_svgBar(t.maintenanceMonths||[], 'cost', { color: 'var(--purple)' })}
        ${monthLabels(t.maintenanceMonths)}
      </div>
      <div class="card">
        <h3 style="margin:0 0 .75rem"><i class="ti ti-chart-line"></i> Fuel Usage <span style="font-size:11px;font-weight:400;color:var(--t3)">· litres, vehicles + machines</span></h3>
        ${_svgBar(t.fuelMonths||[], 'liters', { color: 'var(--blue)' })}
        ${monthLabels(t.fuelMonths)}
      </div>
      <div class="card">
        <h3 style="margin:0 0 .75rem"><i class="ti ti-chart-line"></i> Fuel Cost <span style="font-size:11px;font-weight:400;color:var(--t3)">· RWF, vehicles</span></h3>
        ${_svgBar(t.fuelMonths||[], 'cost', { color: 'var(--green)' })}
        ${monthLabels(t.fuelMonths)}
      </div>
      <div class="card">
        <h3 style="margin:0 0 .75rem"><i class="ti ti-tool"></i> Maintenance Snapshot</h3>
        <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:.6rem">
          <div style="background:var(--bg2);border-radius:6px;padding:.5rem .7rem"><div style="font-size:10px;color:var(--t3);text-transform:uppercase">Completed</div><div style="font-size:18px;font-weight:700;color:var(--green)">${iq.maintenance?.completedThisMonth||0}</div><div style="font-size:11px;color:var(--t3)">this month</div></div>
          <div style="background:var(--bg2);border-radius:6px;padding:.5rem .7rem"><div style="font-size:10px;color:var(--t3);text-transform:uppercase">Upcoming</div><div style="font-size:18px;font-weight:700;color:var(--amber)">${(iq.maintenance?.upcoming||[]).length}</div><div style="font-size:11px;color:var(--t3)">next 30 days</div></div>
          <div style="background:var(--bg2);border-radius:6px;padding:.5rem .7rem"><div style="font-size:10px;color:var(--t3);text-transform:uppercase">Overdue</div><div style="font-size:18px;font-weight:700;color:var(--red)">${(iq.maintenance?.overdue||[]).length}</div><div style="font-size:11px;color:var(--t3)">past due date</div></div>
        </div>
      </div>
      <div class="card">
        <h3 style="margin:0 0 .75rem"><i class="ti ti-report-money"></i> Total Operating Cost <span style="font-size:11px;font-weight:400;color:var(--t3)">· this month</span></h3>
        <div style="font-size:26px;font-weight:700">RWF ${Math.round(iq.costSummary?.totalOperatingCostThisMonth||0).toLocaleString()}</div>
        <div style="font-size:11px;color:var(--t3);margin-top:.25rem">Maintenance + vehicle fuel cost combined.</div>
      </div>
    </div>

    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:1rem;margin-bottom:1.25rem">
      ${_lgdWidget('Most Utilized Vehicles', 'ti-road', (iq.vehicleIntelligence?.mostUtilized||[]).map(r=>({label:r.registration, sub:`${Number(r.estimatedKm).toLocaleString()} km · est., 180d`, badge:'Top'})), 'Not enough odometer readings yet to estimate utilization.')}
      ${_lgdWidget('Least Utilized Vehicles', 'ti-parking', (iq.vehicleIntelligence?.leastUtilized||[]).map(r=>({label:r.registration, sub:`${Number(r.estimatedKm).toLocaleString()} km · est., 180d`, badge:'Low'})), 'Not enough odometer readings yet to estimate utilization.')}
      ${_lgdWidget('Highest Maintenance Frequency', 'ti-tool', (iq.vehicleIntelligence?.highestMaintenanceFrequency||[]).map(r=>({label:r.registration, sub:'180 days', badge:`${r.cnt}×`, warn:r.cnt>=3})), 'No maintenance activity in the last 180 days.')}
      ${_lgdWidget('Highest Fuel Consumers', 'ti-gas-station', (iq.fuel?.topConsumers||[]).map(r=>({label:r.registration, sub:`RWF ${Math.round(r.cost).toLocaleString()} · 90d`, badge:`${Math.round(r.liters)}L`})), 'No fuel activity in the last 90 days.')}
      ${_lgdWidget('Recently Inactive Vehicles', 'ti-alert-circle', (iq.vehicleIntelligence?.recentlyInactive||[]).map(r=>({label:r.registration, sub:'Active status, no fuel/maintenance in 60 days', badge:'Idle', warn:true})), 'No active vehicles look idle right now.')}
      ${_lgdWidget('Assets Requiring Attention', 'ti-alert-triangle', (iq.vehicleIntelligence?.attentionRequired||[]).map(r=>({label:r.registration, sub:r.reason, badge:'Attention', warn:true})), 'Nothing requires management attention right now.')}
    </div>

    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:1rem;margin-bottom:1.25rem">
      ${_lgdWidget('Fuel Usage by Department', 'ti-building', (iq.fuel?.byDepartment||[]).map(r=>({label:r.department, sub:'90 days', badge:`${Math.round(r.liters)}L`})), 'No department field recorded on recent fuel activity.')}
      ${_lgdWidget('Top Dispatched Vehicles', 'ti-truck-delivery', (iq.crossDepartment?.topDispatchedVehicles||[]).map(r=>({label:r.registration, sub:`${r.deliveries} deliveries · 90d`, badge:r.qty})), 'No dispatch activity in the last 90 days.')}
      <div class="card">
        <h3 style="margin:0 0 .5rem"><i class="ti ti-building-warehouse"></i> Workshop Maintenance</h3>
        <div style="font-size:26px;font-weight:700">${iq.crossDepartment?.workshopMaintenanceThisMonth||0}</div>
        <div style="font-size:11px;color:var(--t3);margin-top:.25rem">Machine maintenance events completed this month (Workshop).</div>
      </div>
    </div>
  `;
}

// Fleet & Equipment Phase 2 (Priority 3) — professional tabbed vehicle
// detail overlay, reusing the exact `.smo-tabs`/`.smo-tab` pattern already
// established by the Supplier profile overlay and Material Requests' own
// detail overlay. Read-only — all mutation still happens through the
// existing edit/fuel/maintenance forms, unchanged.
function openVehicleDetailOverlay(r) {
  const TAB_META = {
    overview: { label: 'Overview', icon: 'ti-info-circle' },
    maintenance: { label: 'Maintenance', icon: 'ti-tool' },
    fuel: { label: 'Fuel', icon: 'ti-gas-station' },
    assignments: { label: 'Assignments', icon: 'ti-steering-wheel' },
    history: { label: 'Audit History', icon: 'ti-history' },
  };
  openOverlay(r.registration, r.ownership_type || 'Company Car', `
    <div class="smo-tabs" id="vhd-tabs">
      ${Object.entries(TAB_META).map(([t, m]) => `<button type="button" class="smo-tab ${t==='overview'?'active':''}" data-tab="${t}"><i class="ti ${m.icon}"></i>${m.label}</button>`).join('')}
    </div>
    <div id="vhd-body"></div>
    <div class="brow" style="margin-top:1rem"><button class="bs1" id="ovCancel">Close</button></div>
  `, null, 'ow-wide');

  function renderOverviewTab(body) {
    body.innerHTML = `
      <div class="frow" style="margin-bottom:10px">${vehicleStatusBadge(r.status)} <span class="badge ${r.ownership_type==='Third-Party Car'?'bb':'bg'}">${r.ownership_type||'Company Car'}</span></div>
      <div class="card" style="padding:12px 14px;margin-bottom:12px;background:var(--bg2)">
        <div class="frow" style="flex-wrap:wrap;gap:1.25rem;font-size:13px">
          <div><strong>Plate</strong><br>${r.registration}</div>
          <div><strong>Category</strong><br>${r.vehicle_category||'—'}</div>
          <div><strong>Make / Model</strong><br>${[r.make,r.model].filter(Boolean).join(' ')||'—'}</div>
          <div><strong>Year</strong><br>${r.year||'—'}</div>
          <div><strong>Fuel Type</strong><br>${r.fuel_type||'—'}</div>
          <div><strong>Chassis / VIN</strong><br>${r.chassis_vin||'—'}</div>
          <div><strong>Engine No.</strong><br>${r.engine_number||'—'}</div>
          <div><strong>Odometer</strong><br>${r.odometer_reading ? Number(r.odometer_reading).toLocaleString()+' km' : '—'}</div>
        </div>
      </div>
      <div class="card" style="padding:12px 14px;margin-bottom:12px;background:var(--bg2)">
        <div style="font-size:12px;font-weight:700;color:var(--t3);margin-bottom:8px;text-transform:uppercase;letter-spacing:.03em">Registration &amp; Compliance</div>
        <div class="frow" style="flex-wrap:wrap;gap:1.25rem;font-size:13px">
          <div><strong>Insurance Expiry</strong><br>${r.insurance_expiry ? new Date(r.insurance_expiry).toLocaleDateString('en-GB') : '—'}</div>
          <div><strong>Road License Expiry</strong><br>${r.road_license_expiry ? new Date(r.road_license_expiry).toLocaleDateString('en-GB') : '—'}</div>
          <div><strong>Inspection Expiry</strong><br>${r.inspection_expiry ? new Date(r.inspection_expiry).toLocaleDateString('en-GB') : '—'}</div>
          <div><strong>Asset Code</strong><br>${r.asset_code||'—'}</div>
          <div><strong>Purchase Date</strong><br>${r.purchase_date ? new Date(r.purchase_date).toLocaleDateString('en-GB') : '—'}</div>
          <div><strong>Purchase Cost</strong><br>${r.purchase_cost ? 'RWF '+Number(r.purchase_cost).toLocaleString() : '—'}</div>
        </div>
      </div>
      <div class="card" style="padding:12px 14px;background:var(--bg2)">
        <div style="font-size:12px;font-weight:700;color:var(--t3);margin-bottom:8px;text-transform:uppercase;letter-spacing:.03em">Lifetime Totals</div>
        <div class="frow" style="flex-wrap:wrap;gap:1.25rem;font-size:13px">
          <div><strong>Total Fuel Cost</strong><br>RWF ${Math.round(r.total_fuel_cost||0).toLocaleString()}</div>
          <div><strong>Total Fuel (L)</strong><br>${Math.round(r.total_liters||0).toLocaleString()}</div>
          <div><strong>Maintenance Records</strong><br>${r.maintenance_count||0}</div>
        </div>
      </div>`;
  }

  async function renderMaintenanceTab(body) {
    body.innerHTML = `<p style="color:var(--t3);font-size:12px">Loading…</p>`;
    const res2 = await UFCL.maintenanceList(STORAGE.user.id, r.id);
    const list = res2.ok ? (res2.rows || []) : [];
    const totalCost = list.reduce((s,m)=>s+Number(m.cost||0),0);
    const upcoming = list.filter(m => m.next_due_date).sort((a,b)=> a.next_due_date.localeCompare(b.next_due_date))[0];
    body.innerHTML = `
      <div class="frow" style="gap:1.5rem;margin-bottom:12px;font-size:13px">
        <div><strong>Total spend</strong><br>RWF ${Math.round(totalCost).toLocaleString()}</div>
        <div><strong>Records</strong><br>${list.length}</div>
        <div><strong>Next due</strong><br>${upcoming ? upcoming.next_due_date : '—'}</div>
      </div>
      <div class="tw"><table class="dt" style="font-size:12px">
        <thead><tr><th>Date</th><th>Type</th><th>Description</th><th>Cost (RWF)</th><th>Next due</th><th>Performed by</th><th></th></tr></thead>
        <tbody>${list.length ? list.map(m => `<tr>
          <td style="white-space:nowrap">${m.maintenance_date}</td>
          <td>${m.maintenance_type}</td>
          <td style="color:var(--t3)">${m.description||'—'}</td>
          <td style="font-family:var(--fm)">${m.cost ? Math.round(m.cost).toLocaleString() : '—'}</td>
          <td>${m.next_due_date||'—'}</td>
          <td style="color:var(--t3)">${m.performed_by||'—'}</td>
          <td style="white-space:nowrap">
            <button class="bs1 mnt-edit" data-id="${m.id}" aria-label="Edit maintenance record from ${m.maintenance_date}" style="padding:2px 6px"><i class="ti ti-edit"></i></button>
            <button class="bs1 mnt-del" data-id="${m.id}" data-date="${m.maintenance_date}" aria-label="Delete maintenance record from ${m.maintenance_date}" style="padding:2px 6px;color:var(--red)"><i class="ti ti-trash"></i></button>
          </td>
        </tr>`).join('') : '<tr><td colspan="7" style="text-align:center;color:var(--t3);padding:2rem">No maintenance records yet.</td></tr>'}</tbody>
      </table></div>`;
    // Stabilization Phase 5 (F-16) — maintenanceUpdate had backend/IPC wiring
    // with zero UI caller; records could be created but never corrected.
    // Remediation Phase 2 — maintenanceDelete had the same gap (wired, no
    // caller); added here reusing the same governed confirmDeleteSoft pattern
    // vehiclesDelete already uses on this same overlay.
    body.querySelectorAll('.mnt-del').forEach(btn => {
      btn.onclick = () => {
        confirmDeleteSoft(`Delete maintenance record from <strong>${btn.dataset.date}</strong>?`, async (reason) => {
          const res2 = await UFCL.maintenanceDelete(STORAGE.user.id, Number(btn.dataset.id), reason);
          if (handleGovernanceResultToast(res2)) return;
          showToast('Maintenance record deleted.', 'success');
          await renderMaintenanceTab(body);
        });
      };
    });
    body.querySelectorAll('.mnt-edit').forEach(btn => {
      btn.onclick = () => {
        const m = list.find(x => String(x.id) === btn.dataset.id);
        if (!m) return;
        openOverlay('Edit maintenance record', null, `
          <div class="frow">
            <div class="fg"><label>Date *</label><input id="mr-e-date" type="date" value="${m.maintenance_date}"></div>
            <div class="fg"><label>Type *</label>
              <select id="mr-e-type">
                ${['Scheduled','Corrective','Inspection'].map(t=>`<option value="${t}" ${m.maintenance_type===t?'selected':''}>${t}</option>`).join('')}
              </select>
            </div>
          </div>
          <div class="fg"><label>Description *</label><input id="mr-e-desc" type="text" value="${(m.description||'').replace(/"/g,'&quot;')}"></div>
          <div class="frow">
            <div class="fg"><label>Cost (RWF)</label><input id="mr-e-cost" type="number" min="0" value="${m.cost||''}"></div>
            <div class="fg"><label>Next due date</label><input id="mr-e-next" type="date" value="${m.next_due_date||''}"></div>
            <div class="fg"><label>Performed by</label><input id="mr-e-by" type="text" value="${(m.performed_by||'').replace(/"/g,'&quot;')}"></div>
          </div>
          <div class="fg"><label>Notes</label><input id="mr-e-notes" type="text" value="${(m.notes||'').replace(/"/g,'&quot;')}"></div>
          <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Save</button><button class="bs1" id="ovCancel">Cancel</button></div>`, async () => {
          const res2 = await UFCL.maintenanceUpdate(STORAGE.user.id, m.id, {
            maintenance_type: $('mr-e-type').value,
            description: $('mr-e-desc').value.trim(),
            cost: $('mr-e-cost').value || null,
            maintenance_date: $('mr-e-date').value,
            next_due_date: $('mr-e-next').value || null,
            performed_by: $('mr-e-by').value.trim() || null,
            notes: $('mr-e-notes').value.trim(),
          });
          if (handleGovernanceResult(res2)) return;
          showOverlaySuccess('Maintenance record updated.');
          await renderMaintenanceTab(body);
        });
      };
    });
  }

  async function renderFuelTab(body) {
    body.innerHTML = `<p style="color:var(--t3);font-size:12px">Loading…</p>`;
    const res2 = await UFCL.fuelLogsList(STORAGE.user.id, r.id);
    const list = res2.ok ? (res2.rows || []) : [];
    const totalLiters = list.reduce((s,f)=>s+Number(f.liters||0),0);
    const totalCost = list.reduce((s,f)=>s+Number(f.total_cost||0),0);
    body.innerHTML = `
      <div class="frow" style="gap:1.5rem;margin-bottom:12px;font-size:13px">
        <div><strong>Total fuel</strong><br>${Math.round(totalLiters).toLocaleString()} L</div>
        <div><strong>Total cost</strong><br>RWF ${Math.round(totalCost).toLocaleString()}</div>
        <div><strong>Entries</strong><br>${list.length}</div>
      </div>
      <div class="tw"><table class="dt" style="font-size:12px">
        <thead><tr><th>Date</th><th>Litres</th><th>Cost / L</th><th>Total (RWF)</th><th>Odometer</th><th>Notes</th><th></th></tr></thead>
        <tbody>${list.length ? list.map(f => `<tr>
          <td style="white-space:nowrap">${f.log_date}</td>
          <td style="font-family:var(--fm)">${f.liters}</td>
          <td style="font-family:var(--fm)">${f.cost_per_liter ? Math.round(f.cost_per_liter).toLocaleString() : '—'}</td>
          <td style="font-family:var(--fm);font-weight:600">${f.total_cost ? Math.round(f.total_cost).toLocaleString() : '—'}</td>
          <td>${f.odometer ? Number(f.odometer).toLocaleString()+' km' : '—'}</td>
          <td style="color:var(--t3)">${f.notes||'—'}</td>
          <td><button class="bs1 fl-del" data-id="${f.id}" data-date="${f.log_date}" aria-label="Delete fuel log from ${f.log_date}" style="padding:2px 6px;color:var(--red)"><i class="ti ti-trash"></i></button></td>
        </tr>`).join('') : '<tr><td colspan="7" style="text-align:center;color:var(--t3);padding:2rem">No fuel logs yet.</td></tr>'}</tbody>
      </table></div>`;
    // Remediation Phase 2 — fuelLogsDelete had backend/IPC wiring (governed,
    // matching maintenanceDelete/vehiclesDelete on this same overlay) with no
    // UI caller; fuel logs could be created but never removed.
    body.querySelectorAll('.fl-del').forEach(btn => {
      btn.onclick = () => {
        confirmDeleteSoft(`Delete fuel log from <strong>${btn.dataset.date}</strong>?`, async (reason) => {
          const res2 = await UFCL.fuelLogsDelete(STORAGE.user.id, Number(btn.dataset.id), reason);
          if (handleGovernanceResultToast(res2)) return;
          showToast('Fuel log deleted.', 'success');
          await renderFuelTab(body);
        });
      };
    });
  }

  function renderAssignmentsTab(body) {
    // No assignment-history table exists (confirmed in the Phase 1 audit) —
    // this shows the vehicle's current assignment fields only, honestly
    // labeled as a snapshot rather than fabricating a change history that
    // doesn't exist in the data.
    body.innerHTML = `
      <div class="card" style="padding:12px 14px;margin-bottom:12px;background:var(--bg2)">
        <div style="font-size:12px;font-weight:700;color:var(--t3);margin-bottom:8px;text-transform:uppercase;letter-spacing:.03em">Current Assignment</div>
        <div class="frow" style="flex-wrap:wrap;gap:1.25rem;font-size:13px">
          <div><strong>Department</strong><br>${r.department||'—'}</div>
          <div><strong>Driver Assigned</strong><br>${r.driver_assigned||'—'}</div>
          <div><strong>Assigned Project / Site</strong><br>${r.assigned_project||'—'}</div>
        </div>
      </div>
      ${r.ownership_type === 'Third-Party Car' ? `
      <div class="card" style="padding:12px 14px;margin-bottom:12px;background:var(--bg2)">
        <div style="font-size:12px;font-weight:700;color:var(--t3);margin-bottom:8px;text-transform:uppercase;letter-spacing:.03em">Owner &amp; Driver (Third-Party)</div>
        <div class="frow" style="flex-wrap:wrap;gap:1.25rem;font-size:13px">
          <div><strong>Owner</strong><br>${r.owner_name||'—'}</div>
          <div><strong>Owner Phone</strong><br>${r.owner_phone||'—'}</div>
          <div><strong>Driver Name</strong><br>${r.driver_name||'—'}</div>
          <div><strong>Driver Phone</strong><br>${r.driver_phone||'—'}</div>
          <div><strong>Driver License</strong><br>${r.driver_license_number||'—'}</div>
          <div><strong>License Expiry</strong><br>${r.driver_license_expiry ? new Date(r.driver_license_expiry).toLocaleDateString('en-GB') : '—'}</div>
        </div>
      </div>` : ''}
      <p style="font-size:11px;color:var(--t3)">This is the vehicle's current assignment only — no assignment-change history is tracked yet.</p>`;
  }

  function renderHistoryTab(body) {
    body.innerHTML = `<div id="vhd-history"></div>`;
    _loadLogisticsHistoryInto('vhd-history', 'vehicles', r.id);
  }

  function loadTab(tab) {
    const body = $('vhd-body');
    if (tab === 'overview') return renderOverviewTab(body);
    if (tab === 'maintenance') return renderMaintenanceTab(body);
    if (tab === 'fuel') return renderFuelTab(body);
    if (tab === 'assignments') return renderAssignmentsTab(body);
    if (tab === 'history') return renderHistoryTab(body);
  }
  document.querySelectorAll('#vhd-tabs .smo-tab').forEach(btn => {
    btn.onclick = () => {
      document.querySelectorAll('#vhd-tabs .smo-tab').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      loadTab(btn.dataset.tab);
    };
  });
  loadTab('overview');
}

async function renderVehicles() {
  const [res, compRes, dashRes, intelRes] = await Promise.all([
    UFCL.vehiclesList(STORAGE.user.id),
    UFCL.transportCompaniesDropdown(STORAGE.user.id),
    UFCL.fleetDashboard(STORAGE.user.id),
    UFCL.fleetIntelligence(STORAGE.user.id),
  ]);
  if (!res.ok) return renderDenied('vehicles', res.error);
  const rows = res.rows || [];
  const tpCompanies = compRes?.rows || [];
  const dash = dashRes?.ok ? dashRes : null;
  const iq = intelRes?.ok ? intelRes : null;

  const insExpiredCount = rows.filter(r => r.insurance_expiry && new Date(r.insurance_expiry) < new Date()).length;

  // Phase 2 — enterprise table toolkit (search/filter/sort/bulk), matching
  // the pattern already established across Procurement/Logistics/Workshop/
  // Inventory and (this session) Machines' own registry page.
  const vState = { search: '', status: '', selected: new Set() };
  const vSort = { key: null, dir: 'asc' };
  function vFiltered() {
    return applyProcListFilters(rows, {
      search: vState.search, searchFields: ['registration', 'make', 'model', 'vehicle_category', 'driver_assigned', 'driver_name', 'owner_name'],
      status: vState.status, statusField: 'status',
    });
  }

  $('page-vehicles').innerHTML = `
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;margin-bottom:1.5rem">
      <div>
        <div class="ptitle">Fleet Dashboard</div>
        <div class="psub">Vehicles &amp; machines at a glance — fuel, maintenance, utilization, and the full fleet register.</div>
      </div>
      <div style="display:flex;gap:.5rem;flex-shrink:0">
        ${dash ? `<button class="bs1" id="vExport" style="white-space:nowrap"><i class="ti ti-file-download"></i>Export report</button>` : ''}
        <button class="bp1" id="vAdd" style="white-space:nowrap"><i class="ti ti-plus"></i>Register vehicle</button>
      </div>
    </div>
    ${dash ? _fleetKpiCardsHtml(dash.kpi) : ''}
    ${dash ? _fleetWidgetsHtml(dash.widgets) : ''}
    ${iq ? _fleetIntelligenceHtml(iq) : ''}
    ${insExpiredCount>0?`<div style="display:flex;align-items:center;gap:.625rem;padding:.75rem 1rem;background:rgba(239,68,68,.07);border:1px solid rgba(239,68,68,.2);border-radius:7px;margin-bottom:1.25rem;font-size:13px;color:var(--red)"><i class="ti ti-id-off" style="font-size:16px;flex-shrink:0"></i><strong style="margin-right:.25rem">${insExpiredCount} vehicle${insExpiredCount>1?'s':''}</strong> with expired insurance — update before dispatching.</div>`:''}
    ${procFilterBarHtml({
      searchId: 'v-search', searchPlaceholder: 'Search plate, make, model, category, driver, owner…',
      statusId: 'v-status-filter', statusOptions: ['Active', 'In Maintenance', 'Inactive'],
      clearId: 'v-clear',
    })}
    <div id="v-bulk-bar" class="bulk-bar" style="display:none">
      <span id="v-bulk-count">0 selected</span>
      <button type="button" class="bs1" id="v-bulk-del" style="margin-left:.5rem;color:var(--red)"><i class="ti ti-trash"></i>Move selected to Trash</button>
      <button type="button" class="bs1" id="v-bulk-clear" style="margin-left:auto">Clear selection</button>
    </div>
    <div class="card" style="padding:0">
      <div style="display:flex;align-items:center;justify-content:space-between;padding:1rem 1.25rem;border-bottom:1px solid var(--bdr)">
        <h3 style="margin:0"><i class="ti ti-truck"></i>Fleet register</h3>
        <span id="v-count-label" style="font-size:12px;color:var(--t3)">${rows.length} vehicle${rows.length!==1?'s':''}</span>
      </div>
      <div class="tw"><table class="dt" id="v-table">
        <thead><tr>
          <th style="width:28px"><input type="checkbox" id="v-select-all"></th>
          <th data-sort-key="registration">Plate</th><th data-sort-key="ownership_type">Ownership</th>
          <th data-sort-key="vehicle_category">Category</th><th data-sort-key="make">Make / Model</th>
          <th data-sort-key="status">Status</th><th data-sort-key="insurance_expiry">Insurance expiry</th>
          <th data-sort-key="road_license_expiry">Road Lic. expiry</th><th data-sort-key="total_fuel_cost">Fuel cost (RWF)</th>
          <th>Actions</th>
        </tr></thead>
        <tbody id="v-tbody"></tbody>
      </table></div>
    </div>`;

  function renderVehicleRows(list) {
    const tbody = $('v-tbody');
    if (!list.length) {
      tbody.innerHTML = `<tr><td colspan="10" style="text-align:center;color:var(--t3);padding:3rem"><i class="ti ti-truck" style="font-size:2rem;display:block;margin-bottom:.5rem;opacity:.35"></i>${rows.length ? 'No vehicles match these filters.' : 'No vehicles registered yet. Click <strong>Register vehicle</strong> to add one.'}</td></tr>`;
      $('v-count-label').textContent = '0 vehicles';
      return;
    }
    $('v-count-label').textContent = `${list.length} vehicle${list.length!==1?'s':''}`;
    tbody.innerHTML = list.map(r=>{
      const insExpiry  = r.insurance_expiry  ? new Date(r.insurance_expiry)  : null;
      const roadExpiry = r.road_license_expiry ? new Date(r.road_license_expiry) : null;
      const now = new Date();
      const soon = 30*24*60*60*1000;
      const fmtDate = (d) => d ? d.toLocaleDateString('en-GB') : '—';
      const dateCls = (d) => d && d < now ? 'color:var(--red);font-weight:600' : d && (d-now)<soon ? 'color:var(--amber);font-weight:500' : '';
      return `<tr>
        <td onclick="event.stopPropagation()"><input type="checkbox" class="v-chk" data-id="${r.id}" ${vState.selected.has(String(r.id))?'checked':''}></td>
        <td style="font-weight:700;font-family:var(--fm)">${r.registration}</td>
        <td><span class="badge ${r.ownership_type==='Third-Party Car'?'bb':'bg'}" style="font-size:10px">${r.ownership_type||'Company Car'}</span></td>
        <td>${r.vehicle_category||'—'}</td>
        <td>${[r.make,r.model].filter(Boolean).join(' ')||'—'}</td>
        <td>${vehicleStatusBadge(r.status)}</td>
        <td style="${dateCls(insExpiry)}">${fmtDate(insExpiry)}</td>
        <td style="${dateCls(roadExpiry)}">${fmtDate(roadExpiry)}</td>
        <td style="font-family:var(--fm)">${Math.round(r.total_fuel_cost||0).toLocaleString()}</td>
        <td style="white-space:nowrap;display:flex;gap:4px">
          <button class="bs1 v-view" data-id="${r.id}" title="View details"><i class="ti ti-eye"></i></button>
          <button class="bs1 v-fuel" data-id="${r.id}" data-reg="${r.registration}" title="Log fuel"><i class="ti ti-gas-station"></i></button>
          <button class="bs1 v-maint" data-id="${r.id}" data-reg="${r.registration}" title="Add maintenance"><i class="ti ti-tool"></i></button>
          <button class="bs1 v-edit" data-id="${r.id}" title="Edit"><i class="ti ti-edit"></i></button>
          <button class="bs1 v-del" data-id="${r.id}" style="color:var(--red)" title="Delete"><i class="ti ti-trash"></i></button>
        </td>
      </tr>`;
    }).join('');
    wireVehicleRowActions();
  }

  const VEHICLE_CATEGORIES = ['Pickup','Truck','Van','Bus','Lorry','Motorcycle','Excavator','Tractor','Other'];
  const FUEL_TYPES   = ['Diesel','Petrol','Electric','Hybrid'];
  const PAY_METHODS  = ['Monthly','Weekly','Per Trip','Per Day','Fixed Contract'];

  function vehicleForm(r, companies = []) {
    const own = r?.ownership_type || 'Company Car';
    const isC = own !== 'Third-Party Car';
    const catOpts  = VEHICLE_CATEGORIES.map(c=>`<option value="${c}" ${r?.vehicle_category===c?'selected':''}>${c}</option>`).join('');
    const statOpts = ['Active','In Maintenance','Inactive'].map(s=>`<option value="${s}" ${(r?.status||'Active')===s?'selected':''}>${s}</option>`).join('');
    const fuelOpts = FUEL_TYPES.map(f=>`<option value="${f}" ${r?.fuel_type===f?'selected':''}>${f}</option>`).join('');
    const payOpts  = PAY_METHODS.map(p=>`<option value="${p}" ${r?.payment_method===p?'selected':''}>${p}</option>`).join('');
    const d = k => r&&r[k] ? new Date(r[k]).toISOString().slice(0,10) : '';
    const v = k => r ? (r[k]||'') : '';
    const fileInput = (id, cur) => {
      const fname = cur ? cur.split(/[\\/]/).pop() : '';
      return `<input id="${id}" type="file" accept=".pdf,.jpg,.jpeg,.png,.doc,.docx" style="font-size:12px;width:100%">
        ${fname ? `<div style="font-size:11px;color:var(--g-soft);margin-top:3px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="${cur}"><i class="ti ti-paperclip" style="font-size:10px"></i> ${fname}</div>` : ''}
        <input type="hidden" id="${id}-cur" value="${cur||''}">`;
    };
    const sh = (lbl,ic='ti-chevron-right') =>
      `<div style="margin:1.1rem 0 .45rem;font-size:10.5px;font-weight:700;color:var(--g-dark);text-transform:uppercase;letter-spacing:.09em;border-bottom:1px solid var(--bdr);padding-bottom:.3rem;display:flex;align-items:center;gap:.35rem"><i class="ti ${ic}" style="font-size:12px"></i>${lbl}</div>`;
    const ownBtn = (id,label,icon,active) =>
      `<button type="button" id="${id}" style="flex:1;padding:.45rem;border:2px solid ${active?'var(--g-soft)':'var(--bdr)'};border-radius:7px;background:${active?'var(--g-soft)':'transparent'};color:${active?'#fff':'var(--t2)'};font-weight:600;font-size:12.5px;cursor:pointer;transition:.15s"><i class="ti ${icon}"></i> ${label}</button>`;

    return `
      <div class="frow">
        <div class="fg"><label>Vehicle Category *</label><select id="v-category"><option value="">— Select —</option>${catOpts}</select></div>
      </div>
      <div class="fg" style="margin-bottom:1rem">
        <label>Vehicle Ownership Type *</label>
        <div style="display:flex;gap:.5rem;margin-top:.4rem">
          ${ownBtn('v-own-company','Company Car','ti-building',isC)}
          ${ownBtn('v-own-third','Third-Party Car','ti-user-check',!isC)}
        </div>
      </div>

      <div id="v-sec-a" style="display:${isC?'block':'none'}">
        ${sh('Vehicle Information','ti-car')}
        <div class="frow three">
          <div class="fg"><label>Plate Number *</label><input id="v-reg" type="text" value="${v('registration')}" placeholder="RAB 123A"></div>
          <div class="fg"><label>Vehicle Type</label><input id="v-type" type="text" value="${v('vehicle_type')}" placeholder="Truck, Van…"></div>
          <div class="fg"><label>Make</label><input id="v-make" type="text" value="${v('make')}" placeholder="Toyota"></div>
        </div>
        <div class="frow three">
          <div class="fg"><label>Model</label><input id="v-model" type="text" value="${v('model')}" placeholder="Hilux"></div>
          <div class="fg"><label>Year</label><input id="v-year" type="number" value="${v('year')}" placeholder="2022" min="1990" max="2035"></div>
          <div class="fg"><label>Fuel Type</label><select id="v-fuel"><option value="">—</option>${fuelOpts}</select></div>
        </div>
        <div class="frow three">
          <div class="fg"><label>Chassis / VIN Number</label><input id="v-chassis" type="text" value="${v('chassis_vin')}"></div>
          <div class="fg"><label>Engine Number</label><input id="v-engine" type="text" value="${v('engine_number')}"></div>
          <div class="fg"><label>Odometer Reading (km)</label><input id="v-odometer" type="number" value="${v('odometer_reading')}" min="0"></div>
        </div>
        ${sh('Asset Information','ti-file-invoice')}
        <div class="frow three">
          <div class="fg"><label>Asset Code</label><input id="v-asset-code" type="text" value="${v('asset_code')}"></div>
          <div class="fg"><label>Purchase Date</label><input id="v-purchase-date" type="date" value="${d('purchase_date')}"></div>
          <div class="fg"><label>Purchase Cost (RWF)</label><input id="v-purchase-cost" type="number" value="${v('purchase_cost')}" min="0"></div>
        </div>
        <div class="frow three">
          <div class="fg"><label>Department Assigned</label><input id="v-dept" type="text" value="${v('department')}"></div>
          <div class="fg"><label>Driver Assigned</label><input id="v-driver-assigned" type="text" value="${v('driver_assigned')}"></div>
          <div class="fg"><label>Vehicle Status</label><select id="v-status">${statOpts}</select></div>
        </div>
        ${sh('Compliance','ti-shield-check')}
        <div class="frow three">
          <div class="fg"><label>Insurance Expiry</label><input id="v-ins" type="date" value="${d('insurance_expiry')}"></div>
          <div class="fg"><label>Road License Expiry</label><input id="v-road-lic" type="date" value="${d('road_license_expiry')}"></div>
          <div class="fg"><label>Inspection Expiry</label><input id="v-inspection" type="date" value="${d('inspection_expiry')}"></div>
        </div>
        ${sh('Documents','ti-paperclip')}
        <div class="frow three">
          <div class="fg"><label>Registration Card</label>${fileInput('v-doc-reg', v('doc_registration_card'))}</div>
          <div class="fg"><label>Insurance Certificate</label>${fileInput('v-doc-ins', v('doc_insurance_cert'))}</div>
          <div class="fg"><label>Vehicle Photos</label>${fileInput('v-doc-photos', v('doc_photos'))}</div>
        </div>
        <div class="fg"><label>Notes</label><input id="v-notes" type="text" value="${v('notes')}"></div>
      </div>

      <div id="v-sec-b" style="display:${!isC?'block':'none'}">
        ${sh('Owner Information','ti-user')}
        <div class="frow three">
          <div class="fg"><label>Owner Name *</label>
            <select id="v-owner-name">
              <option value="">— Select company —</option>
              ${companies.map(c=>`<option value="${c.name}" ${r?.owner_name===c.name?'selected':''}>${c.name}</option>`).join('')}
              <option value="__other__" ${r?.owner_name && !companies.find(c=>c.name===r?.owner_name)?'selected':''}>Other / enter manually</option>
            </select>
            <input id="v-owner-name-other" type="text" placeholder="Enter owner name" style="margin-top:5px;display:${r?.owner_name && !companies.find(c=>c.name===r?.owner_name) ? 'block' : 'none'}" value="${r?.owner_name && !companies.find(c=>c.name===r?.owner_name) ? v('owner_name') : ''}">
          </div>
          <div class="fg"><label>Owner Type</label>
            <select id="v-owner-type">
              <option value="">—</option>
              <option value="Individual" ${r?.owner_type==='Individual'?'selected':''}>Individual</option>
              <option value="Company" ${r?.owner_type==='Company'?'selected':''}>Company</option>
            </select>
          </div>
          <div class="fg"><label>National ID / Company Reg No.</label><input id="v-owner-id" type="text" value="${v('owner_id_number')}"></div>
        </div>
        <div class="frow three">
          <div class="fg"><label>Phone Number</label><input id="v-owner-phone" type="text" value="${v('owner_phone')}"></div>
          <div class="fg"><label>Email Address</label><input id="v-owner-email" type="email" value="${v('owner_email')}"></div>
          <div class="fg"><label>Physical Address</label><input id="v-owner-address" type="text" value="${v('owner_address')}"></div>
        </div>
        ${sh('Vehicle Information','ti-car')}
        <div class="frow three">
          <div class="fg"><label>Plate Number *</label><input id="v-reg-b" type="text" value="${v('registration')}" placeholder="RAB 123A"></div>
          <div class="fg"><label>Vehicle Type</label><input id="v-type-b" type="text" value="${v('vehicle_type')}" placeholder="Truck, Van…"></div>
          <div class="fg"><label>Make</label><input id="v-make-b" type="text" value="${v('make')}" placeholder="Toyota"></div>
        </div>
        <div class="frow three">
          <div class="fg"><label>Model</label><input id="v-model-b" type="text" value="${v('model')}" placeholder="Hilux"></div>
          <div class="fg"><label>Year</label><input id="v-year-b" type="number" value="${v('year')}" placeholder="2022" min="1990" max="2035"></div>
          <div class="fg"><label>Chassis / VIN Number</label><input id="v-chassis-b" type="text" value="${v('chassis_vin')}"></div>
        </div>
        <div class="frow">
          <div class="fg"><label>Fuel Type</label><select id="v-fuel-b"><option value="">—</option>${fuelOpts}</select></div>
        </div>
        ${sh('Contract Information','ti-file-description')}
        <div class="frow three">
          <div class="fg"><label>Contract Number</label><input id="v-contract-num" type="text" value="${v('contract_number')}"></div>
          <div class="fg"><label>Contract Start Date</label><input id="v-contract-start" type="date" value="${d('contract_start_date')}"></div>
          <div class="fg"><label>Contract End Date</label><input id="v-contract-end" type="date" value="${d('contract_end_date')}"></div>
        </div>
        <div class="frow three">
          <div class="fg"><label>Payment Rate (RWF)</label><input id="v-pay-rate" type="number" value="${v('payment_rate')}" min="0"></div>
          <div class="fg"><label>Payment Method</label><select id="v-pay-method"><option value="">—</option>${payOpts}</select></div>
          <div class="fg"><label>Assigned Project / Site</label><input id="v-project" type="text" value="${v('assigned_project')}"></div>
        </div>
        ${sh('Driver Information','ti-steering-wheel')}
        <div class="frow">
          <div class="fg"><label>Driver Name</label><input id="v-drv-name" type="text" value="${v('driver_name')}"></div>
          <div class="fg"><label>Driver Phone</label><input id="v-drv-phone" type="text" value="${v('driver_phone')}"></div>
        </div>
        <div class="frow">
          <div class="fg"><label>Driver License Number</label><input id="v-drv-lic" type="text" value="${v('driver_license_number')}"></div>
          <div class="fg"><label>License Expiry Date</label><input id="v-drv-lic-exp" type="date" value="${d('driver_license_expiry')}"></div>
        </div>
        ${sh('Compliance','ti-shield-check')}
        <div class="frow three">
          <div class="fg"><label>Insurance Expiry</label><input id="v-ins-b" type="date" value="${d('insurance_expiry')}"></div>
          <div class="fg"><label>Road License Expiry</label><input id="v-road-lic-b" type="date" value="${d('road_license_expiry')}"></div>
          <div class="fg"><label>Inspection Expiry</label><input id="v-inspection-b" type="date" value="${d('inspection_expiry')}"></div>
        </div>
        <div class="fg"><label>Vehicle Status</label><select id="v-status-b">${statOpts}</select></div>
        ${sh('Documents','ti-paperclip')}
        <div class="frow three">
          <div class="fg"><label>Vehicle Registration Card</label>${fileInput('v-doc-reg-b', v('doc_registration_card'))}</div>
          <div class="fg"><label>Owner ID / Company Certificate</label>${fileInput('v-doc-owner-id', v('doc_owner_id'))}</div>
          <div class="fg"><label>Insurance Certificate</label>${fileInput('v-doc-ins-b', v('doc_insurance_cert'))}</div>
        </div>
        <div class="frow">
          <div class="fg"><label>Contract Agreement</label>${fileInput('v-doc-contract', v('doc_contract'))}</div>
          <div class="fg"><label>Vehicle Photos</label>${fileInput('v-doc-photos-b', v('doc_photos'))}</div>
        </div>
        <div class="fg"><label>Notes</label><input id="v-notes-b" type="text" value="${v('notes')}"></div>
      </div>
      <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Save</button><button class="bs1" id="ovCancel">Cancel</button></div>`;
  }

  function bindVehicleOwnershipToggle() {
    const secA = document.getElementById('v-sec-a');
    const secB = document.getElementById('v-sec-b');
    const btnC = document.getElementById('v-own-company');
    const btnT = document.getElementById('v-own-third');
    if (!btnC || !btnT) return;
    const activate = (isCompany) => {
      secA.style.display = isCompany ? 'block' : 'none';
      secB.style.display = isCompany ? 'none'  : 'block';
      [btnC, btnT].forEach((b, i) => {
        const on = isCompany ? i===0 : i===1;
        b.style.background    = on ? 'var(--g-soft)' : 'transparent';
        b.style.borderColor   = on ? 'var(--g-soft)' : 'var(--bdr)';
        b.style.color         = on ? '#fff' : 'var(--t2)';
      });
    };
    btnC.onclick = () => activate(true);
    btnT.onclick = () => activate(false);
    const ownerSel = document.getElementById('v-owner-name');
    const ownerOther = document.getElementById('v-owner-name-other');
    if (ownerSel && ownerOther) {
      ownerSel.addEventListener('change', () => {
        ownerOther.style.display = ownerSel.value === '__other__' ? 'block' : 'none';
      });
    }
  }

  function collectVehiclePayload() {
    const secB = document.getElementById('v-sec-b');
    const isThird = secB && secB.style.display !== 'none';
    const g = id => { const el = document.getElementById(id); return el ? el.value.trim() : ''; };
    const getFile = id => {
      const el = document.getElementById(id);
      if (el && el.files && el.files.length > 0) return el.files[0].path || el.files[0].name || '';
      const cur = document.getElementById(id + '-cur');
      return cur ? cur.value : '';
    };
    if (!isThird) {
      return {
        ownership_type: 'Company Car',
        vehicle_category: g('v-category'),
        registration: g('v-reg'), vehicle_type: g('v-type'), make: g('v-make'),
        model: g('v-model'), year: g('v-year') || null, fuel_type: g('v-fuel') || null,
        chassis_vin: g('v-chassis'), engine_number: g('v-engine'),
        odometer_reading: g('v-odometer') || null,
        asset_code: g('v-asset-code'), purchase_date: g('v-purchase-date') || null,
        purchase_cost: g('v-purchase-cost') || null, department: g('v-dept'),
        driver_assigned: g('v-driver-assigned'),
        status: g('v-status') || 'Active',
        insurance_expiry: g('v-ins') || null, road_license_expiry: g('v-road-lic') || null,
        inspection_expiry: g('v-inspection') || null,
        doc_registration_card: getFile('v-doc-reg'), doc_insurance_cert: getFile('v-doc-ins'),
        doc_photos: getFile('v-doc-photos'), notes: g('v-notes'),
      };
    }
    return {
      ownership_type: 'Third-Party Car',
      vehicle_category: g('v-category'),
      owner_name: (g('v-owner-name') === '__other__' ? g('v-owner-name-other') : g('v-owner-name')) || null, owner_type: g('v-owner-type') || null,
      owner_id_number: g('v-owner-id'), owner_phone: g('v-owner-phone'),
      owner_email: g('v-owner-email'), owner_address: g('v-owner-address'),
      registration: g('v-reg-b'), vehicle_type: g('v-type-b'), make: g('v-make-b'),
      model: g('v-model-b'), year: g('v-year-b') || null, chassis_vin: g('v-chassis-b'),
      fuel_type: g('v-fuel-b') || null,
      contract_number: g('v-contract-num'),
      contract_start_date: g('v-contract-start') || null, contract_end_date: g('v-contract-end') || null,
      payment_rate: g('v-pay-rate') || null, payment_method: g('v-pay-method') || null,
      assigned_project: g('v-project'),
      driver_name: g('v-drv-name'), driver_phone: g('v-drv-phone'),
      driver_license_number: g('v-drv-lic'), driver_license_expiry: g('v-drv-lic-exp') || null,
      insurance_expiry: g('v-ins-b') || null, road_license_expiry: g('v-road-lic-b') || null,
      inspection_expiry: g('v-inspection-b') || null,
      status: g('v-status-b') || 'Active',
      doc_registration_card: getFile('v-doc-reg-b'), doc_owner_id: getFile('v-doc-owner-id'),
      doc_insurance_cert: getFile('v-doc-ins-b'), doc_contract: getFile('v-doc-contract'),
      doc_photos: getFile('v-doc-photos-b'), notes: g('v-notes-b'),
    };
  }

  $('vAdd').onclick = () => {
    openOverlay('Register vehicle', null, vehicleForm(null, tpCompanies), async () => {
      const p = collectVehiclePayload();
      if (!p.registration) { showOverlayError('Plate number is required.'); return; }
      const res2 = await UFCL.vehiclesCreate(STORAGE.user.id, p);
      if (!res2.ok) { showOverlayError(res2.error); return; }
      showOverlaySuccess('Vehicle registered.');
      await renderVehicles();
    });
    bindVehicleOwnershipToggle();
  };

  // Phase 2 — row action handlers are re-wired after every renderVehicleRows()
  // call, since rows now re-render on search/filter/sort instead of being
  // built once as static HTML. Logic below is otherwise unchanged from Phase 1.
  function wireVehicleRowActions() {
  document.querySelectorAll('.v-view').forEach(btn => {
    btn.onclick = () => { const r = rows.find(x => String(x.id) === btn.dataset.id); if (r) openVehicleDetailOverlay(r); };
  });

  document.querySelectorAll('.v-chk').forEach(chk => {
    chk.onchange = () => {
      const id = chk.dataset.id;
      if (chk.checked) vState.selected.add(id); else vState.selected.delete(id);
      updateVehicleBulkBar();
    };
  });

  document.querySelectorAll('.v-edit').forEach(btn => {
    btn.onclick = () => {
      const row = rows.find(r => r.id === btn.dataset.id);
      if (!row) return;
      openOverlay('Edit vehicle', row.registration, vehicleForm(row, tpCompanies), async () => {
        const p = collectVehiclePayload();
        if (!p.registration) { showOverlayError('Plate number is required.'); return; }
        const res2 = await UFCL.vehiclesUpdate(STORAGE.user.id, row.id, p);
        // Fleet & Equipment Phase 1 — vehiclesUpdate is now governed and can
        // return a pendingApproval response with no .error field; the plain
        // `showOverlayError(res2.error)` used here previously would have
        // shown "undefined" for that case.
        if (handleGovernanceResult(res2)) return;
        showOverlaySuccess('Vehicle updated.');
        await renderVehicles();
      });
      bindVehicleOwnershipToggle();
    };
  });

  document.querySelectorAll('.v-del').forEach(btn => {
    btn.onclick = () => {
      const r = rows.find(x => x.id === btn.dataset.id);
      if (!r) return;
      // Fleet & Equipment Phase 1 — vehiclesDelete is now a governed
      // soft-delete (moves to Trash, restorable within 30 days; fuel logs
      // and maintenance records are preserved, not removed) instead of an
      // ungoverned hard delete — matches every other governed Fleet table's
      // own confirmDeleteSoft + handleGovernanceResultToast pattern.
      confirmDeleteSoft(`Move vehicle <strong>${r.registration}</strong> to Trash? Fuel logs and maintenance history are preserved.`, async (reason) => {
        const res2 = await UFCL.vehiclesDelete(STORAGE.user.id, r.id, reason);
        if (handleGovernanceResultToast(res2)) return;
        showToast('Vehicle moved to Trash.', 'success');
        await renderVehicles();
      });
    };
  });

  document.querySelectorAll('.v-fuel').forEach(btn => {
    btn.onclick = () => {
      const vid = btn.dataset.id;
      const reg = btn.dataset.reg;
      openOverlay('Log fuel', reg, `
        <div class="frow">
          <div class="fg"><label>Date *</label><input id="fl-date" type="date" value="${new Date().toISOString().slice(0,10)}"></div>
          <div class="fg"><label>Litres *</label><input id="fl-liters" type="number" min="0.1" step="0.1" placeholder="0.0"></div>
        </div>
        <div class="frow">
          <div class="fg"><label>Cost per litre (RWF)</label><input id="fl-cpl" type="number" min="0" placeholder="0"></div>
          <div class="fg"><label>Odometer (km)</label><input id="fl-odo" type="number" min="0" placeholder="0"></div>
        </div>
        <div class="fg"><label>Notes</label><input id="fl-notes" type="text"></div>
        <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Save</button><button class="bs1" id="ovCancel">Cancel</button></div>`, async () => {
        const liters = Number($('fl-liters').value);
        const cpl = Number($('fl-cpl').value || 0);
        const res2 = await UFCL.fuelLogsCreate(STORAGE.user.id, {
          vehicle_id: vid,
          liters,
          cost_per_liter: cpl || null,
          total_cost: liters * cpl || null,
          odometer: $('fl-odo').value || null,
          log_date: $('fl-date').value,
          notes: $('fl-notes').value.trim()
        });
        if (!res2.ok) { showOverlayError(res2.error); return; }
        showOverlaySuccess('Fuel log saved.');
        await renderVehicles();
      });
    };
  });

  document.querySelectorAll('.v-maint').forEach(btn => {
    btn.onclick = () => {
      const vid = btn.dataset.id;
      const reg = btn.dataset.reg;
      openOverlay('Add maintenance record', reg, `
        <div class="frow">
          <div class="fg"><label>Date *</label><input id="mr-date" type="date" value="${new Date().toISOString().slice(0,10)}"></div>
          <div class="fg"><label>Type *</label>
            <select id="mr-type"><option value="Scheduled">Scheduled</option><option value="Corrective">Corrective</option><option value="Inspection">Inspection</option></select>
          </div>
        </div>
        <div class="fg"><label>Description *</label><input id="mr-desc" type="text" placeholder="What was done?"></div>
        <div class="frow">
          <div class="fg"><label>Cost (RWF)</label><input id="mr-cost" type="number" min="0" placeholder="0"></div>
          <div class="fg"><label>Next due date</label><input id="mr-next" type="date"></div>
          <div class="fg"><label>Performed by</label><input id="mr-by" type="text" placeholder="Name or garage"></div>
        </div>
        <div class="fg"><label>Notes</label><input id="mr-notes" type="text"></div>
        <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Save</button><button class="bs1" id="ovCancel">Cancel</button></div>`, async () => {
        const res2 = await UFCL.maintenanceCreate(STORAGE.user.id, {
          vehicle_id: vid,
          maintenance_type: $('mr-type').value,
          description: $('mr-desc').value.trim(),
          cost: $('mr-cost').value || null,
          maintenance_date: $('mr-date').value,
          next_due_date: $('mr-next').value || null,
          performed_by: $('mr-by').value.trim() || null,
          notes: $('mr-notes').value.trim()
        });
        if (!res2.ok) { showOverlayError(res2.error); return; }
        showOverlaySuccess('Maintenance record saved.');
        await renderVehicles();
      });
    };
  });
  } // end wireVehicleRowActions

  function updateVehicleBulkBar() {
    const n = vState.selected.size;
    $('v-bulk-bar').style.display = n > 0 ? 'flex' : 'none';
    $('v-bulk-count').textContent = `${n} selected`;
  }

  renderVehicleRows(vFiltered());
  wireSortableTable($('v-table'), vSort, vFiltered, renderVehicleRows);
  $('v-search').oninput = (e) => { vState.search = e.target.value; renderVehicleRows(vFiltered()); };
  $('v-status-filter').onchange = (e) => { vState.status = e.target.value; renderVehicleRows(vFiltered()); };
  $('v-clear').onclick = () => { vState.search=''; vState.status=''; $('v-search').value=''; $('v-status-filter').value=''; renderVehicleRows(vFiltered()); };
  $('v-select-all').onchange = (e) => {
    const list = vFiltered();
    if (e.target.checked) list.forEach(r => vState.selected.add(String(r.id)));
    else list.forEach(r => vState.selected.delete(String(r.id)));
    renderVehicleRows(list);
    updateVehicleBulkBar();
  };
  $('v-bulk-clear').onclick = () => { vState.selected.clear(); renderVehicleRows(vFiltered()); updateVehicleBulkBar(); };
  $('v-bulk-del').onclick = () => {
    const ids = Array.from(vState.selected);
    if (!ids.length) return;
    confirmDeleteSoft(`Move ${ids.length} selected vehicle${ids.length!==1?'s':''} to Trash? Fuel logs and maintenance history are preserved.`, async (reason) => {
      let okCount = 0, blockedCount = 0;
      for (const id of ids) {
        const r2 = await UFCL.vehiclesDelete(STORAGE.user.id, Number(id), reason);
        if (r2.ok) okCount++; else if (r2.pendingApproval) blockedCount++;
      }
      showToast(`${okCount} vehicle${okCount!==1?'s':''} moved to Trash.${blockedCount ? ` ${blockedCount} submitted for approval.` : ''}`, 'success');
      vState.selected.clear();
      await renderVehicles();
    });
  };

  // Phase 2 (Priority 8) — reuses the exact execExport/CSV pattern already
  // established by Inventory's own dashboard export, not a new reporting
  // engine.
  if (dash) {
    $('vExport').onclick = async () => {
      const k = dash.kpi, w = dash.widgets;
      const lines = [
        ['UFCL Fleet & Equipment — Dashboard Report', new Date().toLocaleString()],
        [],
        ['Executive KPIs', ''],
        ['Total vehicles', k.totalVehicles], ['Active vehicles', k.activeVehicles],
        ['Vehicles in maintenance', k.vehiclesInMaintenance], ['Vehicles out of service', k.vehiclesOutOfService],
        ['Total machines', k.totalMachines], ['Active machines', k.activeMachines],
        ['Fuel this month (L)', Math.round(k.fuelLitersThisMonth)], ['Fuel cost this month (RWF)', Math.round(k.fuelCostThisMonth)],
        ['Maintenance cost this month (RWF)', Math.round(k.maintenanceCostThisMonth)], ['Open maintenance jobs', k.openMaintenanceJobs],
        ['Available fleet %', k.availableFleetPct], ['Fleet utilization %', k.utilizationPct],
        [],
        ['Vehicles Needing Maintenance — Vehicle', 'Next Due'], ...w.vehiclesNeedingMaintenance.map(r => [r.registration, r.next_due||'']),
        [], ['Machines Requiring Attention — Machine', 'Status'], ...w.machinesRequiringAttention.map(r => [`${r.machine_code} — ${r.name}`, r.status]),
        [], ['Recent Fuel Activity — Ref', 'Date'], ...w.recentFuelActivity.map(r => [r.ref, r.log_date]),
        [], ['Recent Maintenance — Vehicle', 'Type', 'Cost (RWF)', 'Date'], ...w.recentMaintenance.map(r => [r.ref, r.maintenance_type, r.cost||0, r.maintenance_date]),
        [],
        ...(iq ? [
          ['Operational Intelligence', ''],
          ['Maintenance completed this month', iq.maintenance?.completedThisMonth||0],
          ['Maintenance upcoming (30d)', (iq.maintenance?.upcoming||[]).length],
          ['Maintenance overdue', (iq.maintenance?.overdue||[]).length],
          ['Total operating cost this month (RWF)', Math.round(iq.costSummary?.totalOperatingCostThisMonth||0)],
          ['Workshop machine maintenance this month', iq.crossDepartment?.workshopMaintenanceThisMonth||0],
          [],
          ['Maintenance Trend — Month', 'Count', 'Cost (RWF)'], ...(iq.trends?.maintenanceMonths||[]).map(r => [r.month, r.count, Math.round(r.cost)]),
          [], ['Fuel Trend — Month', 'Litres', 'Cost (RWF)'], ...(iq.trends?.fuelMonths||[]).map(r => [r.month, Math.round(r.liters), Math.round(r.cost)]),
          [], ['Highest Fuel Consumers — Vehicle', 'Litres (90d)', 'Cost (RWF)'], ...(iq.fuel?.topConsumers||[]).map(r => [r.registration, Math.round(r.liters), Math.round(r.cost)]),
          [], ['Fuel by Department — Department', 'Litres (90d)'], ...(iq.fuel?.byDepartment||[]).map(r => [r.department, Math.round(r.liters)]),
          [], ['Most Utilized Vehicles — Vehicle', 'Est. km (180d)'], ...(iq.vehicleIntelligence?.mostUtilized||[]).map(r => [r.registration, Math.round(r.estimatedKm)]),
          [], ['Least Utilized Vehicles — Vehicle', 'Est. km (180d)'], ...(iq.vehicleIntelligence?.leastUtilized||[]).map(r => [r.registration, Math.round(r.estimatedKm)]),
          [], ['Highest Maintenance Frequency — Vehicle', 'Events (180d)'], ...(iq.vehicleIntelligence?.highestMaintenanceFrequency||[]).map(r => [r.registration, r.cnt]),
          [], ['Recently Inactive Vehicles — Vehicle'], ...(iq.vehicleIntelligence?.recentlyInactive||[]).map(r => [r.registration]),
          [], ['Assets Requiring Attention — Vehicle', 'Reason'], ...(iq.vehicleIntelligence?.attentionRequired||[]).map(r => [r.registration, r.reason]),
          [], ['Top Dispatched Vehicles — Vehicle', 'Deliveries (90d)', 'Qty Dispatched'], ...(iq.crossDepartment?.topDispatchedVehicles||[]).map(r => [r.registration, r.deliveries, r.qty]),
          [],
        ] : []),
        ['Plate', 'Ownership', 'Category', 'Make/Model', 'Status', 'Insurance Expiry', 'Fuel cost (RWF)'],
        ...vFiltered().map(r => [r.registration, r.ownership_type||'', r.vehicle_category||'', [r.make,r.model].filter(Boolean).join(' '), r.status, r.insurance_expiry||'', Math.round(r.total_fuel_cost||0)]),
      ];
      const csv = lines.map(row => row.map(c => `"${String(c ?? '').replace(/"/g, '""')}"`).join(',')).join('\r\n');
      const filename = `fleet_dashboard_${new Date().toISOString().slice(0, 10)}.csv`;
      const res2 = await UFCL.execExport(STORAGE.user.id, { csv, filename });
      if (!res2?.ok && res2?.error !== undefined) showToast('Export cancelled or failed', 'error');
    };
  }
}

// ── Deliveries ────────────────────────────────────────────────────────────────

async function renderDeliveries() {
  $('page-deliveries').innerHTML = `<div style="padding:2rem;color:var(--t3);font-size:13px"><i class="ti ti-loader-2" style="font-size:18px;animation:spin 1s linear infinite"></i> Loading…</div>`;
  const res = await UFCL.deliveriesList(STORAGE.user.id);
  if (!res.ok) return renderDenied('deliveries', res.error);
  const rows = res.rows || [];
  const vehicles = res.vehicles || [];
  const salesOrders = res.salesOrders || [];

  const statBadge = (s) => {
    const map = {
      Pending:'ba', Assigned:'bb', 'In Transit':'bp',
      Delivered:'bg', Failed:'br', 'POD Recorded':'bg'
    };
    return `<span class="badge ${map[s]||'ba'}">${s}</span>`;
  };

  // Phase 2 — enterprise table toolkit (search/filter/sort), reused from the
  // Procurement pages rather than a new implementation.
  const doState = { search: '', status: '', selected: new Set() };
  const doSort = { key: null, dir: 'asc' };
  function doFiltered() {
    return applyProcListFilters(rows, {
      search: doState.search, searchFields: ['order_number', 'sales_order_number', 'customer_name', 'driver_name', 'vehicle_registration'],
      status: doState.status, statusField: 'status',
    });
  }

  $('page-deliveries').innerHTML = `
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;margin-bottom:1.5rem">
      <div>
        <div class="ptitle">Delivery Orders</div>
        <div class="psub">Create delivery orders, assign drivers and vehicles, and record proof of delivery (POD) per trip. Partial deliveries and multi-trip fulfillment are supported.</div>
      </div>
      <div style="display:flex;gap:.5rem;flex-shrink:0">
        <button class="bs1" id="do-export"><i class="ti ti-file-spreadsheet"></i>Export Excel</button>
        <button class="bp1" id="doAdd" style="white-space:nowrap"><i class="ti ti-plus"></i>New delivery order</button>
      </div>
    </div>
    <div class="cards" style="margin-bottom:1.25rem">
      <div class="mc"><div class="mclbl">Total orders</div><div class="mcval">${rows.length}</div><div class="mcsub cg"><i class="ti ti-truck-delivery"></i>all time</div></div>
      <div class="mc"><div class="mclbl">Pending</div><div class="mcval">${rows.filter(r=>r.status==='Pending').length}</div><div class="mcsub ca"><i class="ti ti-clock"></i>awaiting dispatch</div></div>
      <div class="mc"><div class="mclbl">In transit</div><div class="mcval">${rows.filter(r=>r.status==='In Transit').length}</div><div class="mcsub bp"><i class="ti ti-truck"></i>on the road</div></div>
      <div class="mc"><div class="mclbl">POD recorded</div><div class="mcval">${rows.filter(r=>r.status==='POD Recorded').length}</div><div class="mcsub cg"><i class="ti ti-clipboard-check"></i>confirmed</div></div>
    </div>
    ${procFilterBarHtml({
      searchId: 'do-search', searchPlaceholder: 'Search order #, customer, driver, vehicle…',
      statusId: 'do-status-filter', statusOptions: ['Pending', 'Assigned', 'In Transit', 'Failed', 'POD Recorded'],
      clearId: 'do-clear',
    })}
    <div id="do-bulk-bar" class="bulk-bar" style="display:none">
      <span id="do-bulk-count">0 selected</span>
      <select id="do-bulk-status" class="filter-select" style="margin-left:.75rem">
        <option value="">Set status to…</option>
        ${['Pending', 'Assigned', 'In Transit', 'Failed'].map((s) => `<option value="${s}">${s}</option>`).join('')}
      </select>
      <button type="button" class="bs1" id="do-bulk-apply">Apply</button>
      <button type="button" class="bs1" id="do-bulk-clear" style="margin-left:auto">Clear selection</button>
    </div>
    <div class="card" style="padding:0">
      <div style="display:flex;align-items:center;justify-content:space-between;padding:1rem 1.25rem;border-bottom:1px solid var(--bdr)">
        <h3 style="margin:0"><i class="ti ti-truck-delivery"></i>Order log</h3>
        <span id="do-count-label" style="font-size:12px;color:var(--t3)">${rows.length} order${rows.length!==1?'s':''}</span>
      </div>
      <div class="tw"><table class="tbl" id="do-table">
        <thead><tr>
          <th style="width:28px"><input type="checkbox" id="do-select-all"></th>
          <th data-sort-key="order_number">Order #</th><th data-sort-key="sales_order_number">Sales order</th>
          <th data-sort-key="customer_name">Customer</th><th data-sort-key="driver_name">Driver</th>
          <th data-sort-key="vehicle_registration">Vehicle</th><th data-sort-key="delivery_date">Date</th>
          <th data-sort-key="qty_dispatched">Qty dispatched</th><th>POD result</th>
          <th data-sort-key="status">Status</th><th>Actions</th>
        </tr></thead>
        <tbody id="do-tbody"></tbody>
      </table></div>
    </div>`;

  function renderDoRows(list) {
    const tbody = $('do-tbody');
    if (!list.length) {
      tbody.innerHTML = `<tr><td colspan="11" style="text-align:center;color:var(--t3);padding:3rem"><i class="ti ti-truck-delivery" style="font-size:2rem;display:block;margin-bottom:.5rem;opacity:.35"></i>No delivery orders match these filters.</td></tr>`;
      $('do-count-label').textContent = '0 orders';
      return;
    }
    $('do-count-label').textContent = `${list.length} order${list.length !== 1 ? 's' : ''}`;
    tbody.innerHTML = list.map((r) => {
      const canPOD = r.status === 'In Transit' || r.status === 'Assigned';
      const canStatus = r.status !== 'POD Recorded';
      return `<tr class="do-row" data-id="${r.id}" style="cursor:pointer">
        <td onclick="event.stopPropagation()"><input type="checkbox" class="do-chk" data-id="${r.id}" ${doState.selected.has(String(r.id)) ? 'checked' : ''}></td>
        <td style="font-family:var(--fm);font-weight:700"><i class="ti ti-chevron-right do-expand-ic" style="font-size:11px;color:var(--t4);margin-right:4px"></i>${r.order_number}</td>
        <td style="font-family:var(--fm);color:var(--t3)">
          ${r.sales_order_number||'—'}
          ${r.so_price_tax_type==='Inclusive' ? '<span class="badge bg" style="font-size:10px;margin-left:4px"><i class="ti ti-truck-delivery"></i>incl.</span>' : ''}
        </td>
        <td style="font-weight:500">${r.customer_name||'—'}</td>
        <td>${r.driver_name||'—'}</td>
        <td style="font-family:var(--fm)">${r.vehicle_registration||'—'}</td>
        <td>${r.delivery_date||'—'}</td>
        <td style="text-align:center;font-family:var(--fm)">${r.qty_dispatched!=null ? r.qty_dispatched : '—'}</td>
        <td>
          ${r.status==='POD Recorded'
            ? `<span style="color:var(--green);font-weight:600">✓ ${r.qty_accepted??0}</span>${r.qty_rejected ? `<span style="color:var(--red);margin-left:4px">↩ ${r.qty_rejected}</span>` : ''}`
            : '<span style="color:var(--t3);font-size:12px">—</span>'}
        </td>
        <td>${statBadge(r.status)}</td>
        <td style="white-space:nowrap;display:flex;gap:4px;align-items:center" onclick="event.stopPropagation()">
          ${canStatus ? `<select class="do-status-sel" data-id="${r.id}" style="font-size:12px;padding:3px 6px;background:var(--bg2);border:1px solid var(--bdr);color:var(--t1);border-radius:4px">
            ${['Pending','Assigned','In Transit','Failed'].map(s=>`<option value="${s}" ${r.status===s?'selected':''}>${s}</option>`).join('')}
          </select>` : ''}
          ${canPOD ? `<button class="bs1 do-pod" data-id="${r.id}" title="Record POD" style="background:var(--green);color:#fff;border-color:var(--green)"><i class="ti ti-clipboard-check"></i></button>` : ''}
          <button class="bs1 do-view" data-id="${r.id}" title="View details"><i class="ti ti-eye"></i></button>
          <button class="bs1 do-edit" data-id="${r.id}"><i class="ti ti-edit"></i></button>
          <button class="bs1 do-del" data-id="${r.id}" style="color:var(--red)"><i class="ti ti-trash"></i></button>
        </td>
      </tr>
      <tr class="do-expand" data-parent="${r.id}" style="display:none"><td></td><td colspan="10" style="background:var(--bg2);font-size:12px;color:var(--t3);padding:.6rem 1rem">
        <strong>Route:</strong> ${r.route || '—'} &nbsp;|&nbsp; <strong>Notes:</strong> ${r.notes || '—'}
        ${r.status==='POD Recorded' ? `<br><strong>POD:</strong> ${r.qty_accepted??0} accepted${r.qty_rejected ? `, ${r.qty_rejected} rejected${r.rejection_reason ? ` (${r.rejection_reason})` : ''}` : ''}` : ''}
      </td></tr>`;
    }).join('');
    wireDoRowActions(list);
  }

  function wireDoRowActions(list) {
    document.querySelectorAll('.do-row').forEach((tr) => {
      tr.onclick = () => {
        const exp = document.querySelector(`.do-expand[data-parent="${tr.dataset.id}"]`);
        const ic = tr.querySelector('.do-expand-ic');
        if (!exp) return;
        const show = exp.style.display === 'none';
        exp.style.display = show ? '' : 'none';
        if (ic) ic.style.transform = show ? 'rotate(90deg)' : '';
      };
    });
    document.querySelectorAll('.do-chk').forEach((chk) => {
      chk.onchange = () => {
        const id = chk.dataset.id;
        if (chk.checked) doState.selected.add(id); else doState.selected.delete(id);
        updateDoBulkBar();
      };
    });
    document.querySelectorAll('.do-view').forEach((btn) => {
      btn.onclick = () => {
        const r = rows.find((x) => String(x.id) === btn.dataset.id);
        if (r) openDeliveryDetailOverlay(r);
      };
    });
    document.querySelectorAll('.do-status-sel').forEach(sel => {
      sel.onchange = async () => {
        const res2 = await UFCL.deliveriesUpdateStatus(STORAGE.user.id, Number(sel.dataset.id), sel.value);
        if (handleGovernanceResultToast(res2)) { sel.value = rows.find(r=>String(r.id)===sel.dataset.id)?.status||'Pending'; return; }
        showToast('Delivery status updated.', 'success');
        await renderDeliveries();
      };
    });
    document.querySelectorAll('.do-pod').forEach(btn => { btn.onclick = () => openDeliveryPodOverlay(btn.dataset.id); });
    document.querySelectorAll('.do-edit').forEach(btn => { btn.onclick = () => openDeliveryEditOverlay(btn.dataset.id); });
    document.querySelectorAll('.do-del').forEach(btn => { btn.onclick = () => deleteDeliveryOrder(btn.dataset.id); });
  }

  function updateDoBulkBar() {
    const n = doState.selected.size;
    $('do-bulk-bar').style.display = n > 0 ? 'flex' : 'none';
    $('do-bulk-count').textContent = `${n} selected`;
  }

  renderDoRows(doFiltered());
  wireSortableTable($('do-table'), doSort, doFiltered, renderDoRows);
  $('do-search').oninput = (e) => { doState.search = e.target.value; renderDoRows(doFiltered()); };
  $('do-status-filter').onchange = (e) => { doState.status = e.target.value; renderDoRows(doFiltered()); };
  $('do-clear').onclick = () => { doState.search = ''; doState.status = ''; $('do-search').value = ''; $('do-status-filter').value = ''; renderDoRows(doFiltered()); };
  $('do-select-all').onchange = (e) => {
    const list = doFiltered();
    if (e.target.checked) list.forEach((r) => doState.selected.add(String(r.id)));
    else list.forEach((r) => doState.selected.delete(String(r.id)));
    renderDoRows(list);
    updateDoBulkBar();
  };
  $('do-bulk-clear').onclick = () => { doState.selected.clear(); renderDoRows(doFiltered()); updateDoBulkBar(); };
  $('do-bulk-apply').onclick = async () => {
    const status = $('do-bulk-status').value;
    if (!status) { showToast('Choose a status first.', 'error'); return; }
    const ids = Array.from(doState.selected);
    let okCount = 0, blockedCount = 0;
    for (const id of ids) {
      const r2 = await UFCL.deliveriesUpdateStatus(STORAGE.user.id, Number(id), status);
      if (r2.ok) okCount++; else if (r2.pendingApproval) blockedCount++;
    }
    showToast(`${okCount} order${okCount!==1?'s':''} updated${blockedCount ? `, ${blockedCount} submitted for approval` : ''}.`, 'success');
    doState.selected.clear();
    await renderDeliveries();
  };

  $('do-export').onclick = () => _logisticsExportExcel('deliveries', {});
  $('doAdd').onclick = () => {
    const vOpts = vehicles.map(v=>`<option value="${v.id}">${v.registration}${v.make?' — '+v.make:''}</option>`).join('');
    const soOpts = `<option value="">— None —</option>` + salesOrders.map(s => {
      const rem = Number(s.qty_remaining ?? s.quantity);
      const disp = Number(s.qty_dispatched_total || 0);
      const label = `${s.order_number} — ${s.customer_name} | Ordered: ${Number(s.quantity).toLocaleString()}, Dispatched: ${disp.toLocaleString()}, Remaining: ${rem.toLocaleString()}${s.price_tax_type==='Inclusive'?' ✓ Transport incl.':''}`;
      return `<option value="${s.id}" data-incl="${s.price_tax_type==='Inclusive'?'1':''}" data-qty="${s.quantity}" data-rem="${rem}">${label}</option>`;
    }).join('');
    openOverlay('Create delivery order', null, `
      <div id="do-incl-banner" style="display:none;background:#ecfdf5;border:1px solid #6ee7b7;border-radius:8px;padding:10px 14px;margin-bottom:10px;font-size:13px;color:#065f46">
        <i class="ti ti-truck-delivery"></i> <strong>Transport included in sales price</strong> — the client's unit price already covers this delivery.
      </div>
      <div id="do-partial-banner" style="display:none;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;padding:10px 14px;margin-bottom:10px;font-size:13px;color:#92400e">
        <i class="ti ti-alert-triangle"></i> This sales order is partially fulfilled. Enter how many units you are dispatching in this trip.
      </div>
      <div class="frow">
        <div class="fg"><label>Driver name *</label><input id="do-driver" type="text" placeholder="Full name"></div>
        <div class="fg"><label>Vehicle</label><select id="do-vehicle">${vOpts||'<option>No vehicles</option>'}</select></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Sales order</label><select id="do-so">${soOpts}</select></div>
        <div class="fg"><label>Qty dispatched (this trip)</label><input id="do-qty" type="number" min="1" placeholder="e.g. 1750"></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Delivery date</label><input id="do-date" type="date"></div>
        <div class="fg"><label>Route</label><input id="do-route" type="text" placeholder="Origin → Destination"></div>
      </div>
      <div class="fg"><label>Notes</label><input id="do-notes" type="text"></div>
      <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Create</button><button class="bs1" id="ovCancel">Cancel</button></div>`, async () => {
      const res2 = await UFCL.deliveriesCreate(STORAGE.user.id, {
        driver_name: $('do-driver').value.trim(),
        vehicle_id: $('do-vehicle').value || null,
        sales_order_id: $('do-so').value || null,
        delivery_date: $('do-date').value || null,
        route: $('do-route').value.trim(),
        notes: $('do-notes').value.trim(),
        qty_dispatched: $('do-qty').value || null
      });
      if (!res2.ok) { showOverlayError(res2.error); return; }
      showOverlaySuccess('Delivery order created.');
      await renderDeliveries();
    });
    setTimeout(() => {
      const doSo       = $('do-so');
      const doBanner   = $('do-incl-banner');
      const doPartial  = $('do-partial-banner');
      if (doSo) {
        const check = () => {
          const sel = doSo.options[doSo.selectedIndex];
          if (doBanner) doBanner.style.display = sel?.dataset?.incl === '1' ? '' : 'none';
          const rem = Number(sel?.dataset?.rem || 0);
          const qty = Number(sel?.dataset?.qty || 0);
          if (doPartial) doPartial.style.display = (qty > 0 && rem < qty) ? '' : 'none';
        };
        doSo.addEventListener('change', check);
        check();
      }
    }, 30);
  };

  function openDeliveryPodOverlay(idStr) {
    const r = rows.find(x => String(x.id) === String(idStr));
    if (!r) return;
    openOverlay('Record Proof of Delivery', r.order_number, `
      <div style="background:#f0fdf4;border:1px solid #86efac;border-radius:8px;padding:10px 14px;margin-bottom:12px;font-size:13px">
        <strong>Sales order:</strong> ${r.sales_order_number||'—'} &nbsp;|&nbsp;
        <strong>Customer:</strong> ${r.customer_name||'—'}<br>
        <strong>Qty dispatched this trip:</strong> ${r.qty_dispatched!=null ? r.qty_dispatched : '—'}
        ${r.so_quantity ? ` &nbsp;|&nbsp; <strong>SO total:</strong> ${r.so_quantity} &nbsp;|&nbsp; <strong>SO remaining:</strong> ${r.qty_remaining??r.so_quantity}` : ''}
      </div>
      <div class="frow">
        <div class="fg"><label>Qty accepted by customer *</label><input id="pod-accepted" type="number" min="0" placeholder="Units accepted"></div>
        <div class="fg"><label>Qty rejected (auto-calculated)</label><input id="pod-rejected" type="number" readonly placeholder="0" style="background:var(--bg2);color:var(--t3)"></div>
      </div>
      <div class="fg"><label>Rejection reason (if any)</label><input id="pod-reason" type="text" placeholder="e.g. Size mismatch, quality issue..."></div>
      <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-clipboard-check"></i>Record POD</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
      async () => {
        const accepted = Number($('pod-accepted').value);
        const res2 = await UFCL.deliveriesRecordPOD(STORAGE.user.id, r.id, {
          qty_accepted: accepted,
          rejection_reason: $('pod-reason').value.trim() || null
        });
        if (!res2.ok) { showOverlayError(res2.error); return; }
        showOverlaySuccess('Proof of delivery recorded.');
        await renderDeliveries();
      });
    setTimeout(() => {
      const acc = $('pod-accepted');
      const rej = $('pod-rejected');
      if (acc && rej) {
        const dispatched = r.qty_dispatched || 0;
        acc.addEventListener('input', () => {
          const v = Number(acc.value) || 0;
          rej.value = Math.max(0, dispatched - v);
        });
      }
    }, 30);
  }

  function openDeliveryEditOverlay(idStr) {
    const r = rows.find(x => String(x.id) === String(idStr));
    if (!r) return;
    const vOpts = vehicles.map(v=>`<option value="${v.id}" ${r.vehicle_registration===v.registration?'selected':''}>${v.registration}</option>`).join('');
    openOverlay('Edit delivery order', r.order_number, `
      <div class="frow">
        <div class="fg"><label>Driver name *</label><input id="doe-driver" type="text" value="${r.driver_name||''}"></div>
        <div class="fg"><label>Vehicle</label><select id="doe-vehicle"><option value="">— None —</option>${vOpts}</select></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Qty dispatched</label><input id="doe-qty" type="number" min="1" value="${r.qty_dispatched||''}"></div>
        <div class="fg"><label>Delivery date</label><input id="doe-date" type="date" value="${r.delivery_date ? r.delivery_date.split('/').reverse().join('-') : ''}"></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Route</label><input id="doe-route" type="text" value="${r.route||''}"></div>
        <div class="fg"><label>Notes</label><input id="doe-notes" type="text" value="${r.notes||''}"></div>
      </div>
      <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Save</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
      async () => {
        const res2 = await UFCL.deliveriesUpdate(STORAGE.user.id, r.id, {
          driver_name: $('doe-driver').value.trim(),
          vehicle_id: $('doe-vehicle').value || null,
          delivery_date: $('doe-date').value || null,
          route: $('doe-route').value.trim(),
          notes: $('doe-notes').value.trim(),
          qty_dispatched: $('doe-qty').value || null
        });
        if (handleGovernanceResult(res2)) return;
        showOverlaySuccess('Delivery order updated.'); await renderDeliveries();
      });
  }

  function deleteDeliveryOrder(idStr) {
    const r = rows.find(x => String(x.id) === String(idStr));
    if (!r) return;
    confirmDeleteSoft(`Delete delivery order <strong>${r.order_number}</strong>? This will also remove any linked dispatch requests.`, async (reason) => {
      const res2 = await UFCL.deliveriesDelete(STORAGE.user.id, r.id, reason);
      if (handleGovernanceResult(res2)) return;
      showOverlaySuccess('Delivery order deleted.'); await renderDeliveries();
    });
  }

  // Phase 2 — detail overlay: status timeline + related-record facts + audit
  // history + contextual quick actions, mirroring openRequisitionDetailOverlay's
  // single-view (non-tabbed) structure.
  function openDeliveryDetailOverlay(r) {
    const canPOD = r.status === 'In Transit' || r.status === 'Assigned';
    const canStatus = r.status !== 'POD Recorded';
    openOverlay('Delivery order', r.order_number, `
      <div class="frow" style="margin-bottom:10px">${statBadge(r.status)}</div>
      <div class="card" style="padding:12px 14px;margin-bottom:12px;background:var(--bg2)">
        <div class="frow" style="flex-wrap:wrap;gap:1.25rem;font-size:13px">
          <div><strong>Sales order</strong><br>${r.sales_order_number||'—'}</div>
          <div><strong>Customer</strong><br>${r.customer_name||'—'}</div>
          <div><strong>Driver</strong><br>${r.driver_name||'—'}</div>
          <div><strong>Vehicle</strong><br>${r.vehicle_registration||'—'}</div>
          <div><strong>Date</strong><br>${r.delivery_date||'—'}</div>
          <div><strong>Qty dispatched</strong><br>${r.qty_dispatched!=null?r.qty_dispatched:'—'}</div>
        </div>
        <div style="margin-top:8px;font-size:13px"><strong>Route:</strong> ${r.route||'—'}</div>
        <div style="margin-top:4px;font-size:13px"><strong>Notes:</strong> ${r.notes||'—'}</div>
        ${r.status==='POD Recorded' ? `<div style="margin-top:8px;font-size:13px"><strong>POD result:</strong> <span style="color:var(--green)">✓ ${r.qty_accepted??0} accepted</span>${r.qty_rejected?` <span style="color:var(--red)">↩ ${r.qty_rejected} rejected</span>`:''}</div>` : ''}
      </div>
      <div style="font-size:12px;font-weight:700;color:var(--t3);margin-bottom:6px;text-transform:uppercase;letter-spacing:.03em">Status progression</div>
      <div style="margin-bottom:14px">${_statusTimelineHtml(['Pending','Assigned','In Transit','POD Recorded'], r.status, ['Failed'])}</div>
      <div style="font-size:12px;font-weight:700;color:var(--t3);margin-bottom:6px;text-transform:uppercase;letter-spacing:.03em">History</div>
      <div id="do-detail-history" style="margin-bottom:14px"></div>
      <div class="brow">
        ${canStatus ? `<button class="bs1" id="dd-status"><i class="ti ti-refresh"></i>Change status</button>` : ''}
        ${canPOD ? `<button class="bs1" id="dd-pod" style="background:var(--green);color:#fff;border-color:var(--green)"><i class="ti ti-clipboard-check"></i>Record POD</button>` : ''}
        <button class="bs1" id="dd-edit"><i class="ti ti-edit"></i>Edit</button>
        <button class="bs1" id="ovCancel">Close</button>
      </div>`, null);
    _loadLogisticsHistoryInto('do-detail-history', 'deliveries', r.id);
    setTimeout(() => {
      const st = $('dd-status'); if (st) st.onclick = () => { closeOverlay(); openDeliveryStatusOverlay(r); };
      const pod = $('dd-pod'); if (pod) pod.onclick = () => { closeOverlay(); openDeliveryPodOverlay(r.id); };
      const ed = $('dd-edit'); if (ed) ed.onclick = () => { closeOverlay(); openDeliveryEditOverlay(r.id); };
    }, 30);
  }

  // Stabilization Phase 5 (F-8) — "Change status" previously opened the Edit
  // overlay (driver/vehicle/qty/route/notes — no status field at all) instead
  // of actually changing status. deliveryOrdersUpdateStatus/UFCL.deliveriesUpdateStatus
  // already existed and worked (IPC wired in main.js), just never called from
  // any button. 'POD Recorded' is deliberately excluded — the backend itself
  // only accepts Pending/Assigned/In Transit/Failed here; POD has its own
  // dedicated flow (Record POD) that also captures accepted/rejected qty.
  function openDeliveryStatusOverlay(r) {
    const STATUSES = ['Pending', 'Assigned', 'In Transit', 'Failed'];
    openOverlay('Change Delivery Status', r.order_number, `
      <div class="fg"><label>New Status *</label>
        <select id="dd-new-status">
          ${STATUSES.map(s => `<option value="${s}" ${s === r.status ? 'selected' : ''}>${s}</option>`).join('')}
        </select>
      </div>
      <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Save</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
      async () => {
        const status = $('dd-new-status').value;
        const res2 = await UFCL.deliveriesUpdateStatus(STORAGE.user.id, r.id, status);
        if (handleGovernanceResult(res2)) return;
        showOverlaySuccess('Delivery status updated.');
        await renderDeliveries();
      });
  }

  // Phase 1 — surfaces edit/delete requests for delivery_order that were
  // previously created and escalated but never shown to any approver.
  await insertPendingPanel($('page-deliveries'), ['delivery_order', 'delivery_order_pod'], renderDeliveries);
  await insertDeletionPanel($('page-deliveries'), ['delivery_order'], renderDeliveries);
}

// ── Dispatch ──────────────────────────────────────────────────────────────────

async function renderDispatch() {
  $('page-dispatch').innerHTML = `<div style="padding:2rem;color:var(--t3);font-size:13px"><i class="ti ti-loader-2" style="font-size:18px;animation:spin 1s linear infinite"></i> Loading…</div>`;
  const res = await UFCL.dispatchList(STORAGE.user.id);
  if (!res.ok) return renderDenied('dispatch', res.error);
  const rows = res.rows || [];
  const pendingDeliveries = res.pendingDeliveries || [];

  const dsBadge = (s) => {
    const map = { Pending:'ba', Approved:'bg', Rejected:'br', Dispatched:'bp' };
    return `<span class="badge ${map[s]||'ba'}">${s}</span>`;
  };

  const canApprove = ['admin','ceo','logistics','operations'].includes(STORAGE.user.role);
  const dsPending = rows.filter(r=>r.status==='Pending').length;

  const dsState = { search: '', status: '', selected: new Set() };
  const dsSort = { key: null, dir: 'asc' };
  function dsFiltered() {
    return applyProcListFilters(rows, {
      search: dsState.search, searchFields: ['request_number', 'so_order_number', 'customer_name', 'delivery_order_number', 'driver_name', 'vehicle_registration'],
      status: dsState.status, statusField: 'status',
    });
  }

  $('page-dispatch').innerHTML = `
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;margin-bottom:1.5rem">
      <div>
        <div class="ptitle">Dispatch</div>
        <div class="psub">Review and authorise vehicle dispatch. Requests must be approved before a vehicle leaves the yard.</div>
      </div>
      <div style="display:flex;gap:.5rem;flex-shrink:0">
        <button class="bs1" id="ds-export"><i class="ti ti-file-spreadsheet"></i>Export Excel</button>
        <button class="bp1" id="dsAdd" style="white-space:nowrap"><i class="ti ti-plus"></i>New request</button>
      </div>
    </div>
    <div class="cards" style="margin-bottom:1.25rem">
      <div class="mc"><div class="mclbl">Awaiting approval</div><div class="mcval" style="${dsPending>0?'color:var(--amber)':''}">${dsPending}</div><div class="mcsub ${dsPending>0?'ca':'cg'}"><i class="ti ti-clock"></i>pending</div></div>
      <div class="mc"><div class="mclbl">Approved</div><div class="mcval">${rows.filter(r=>r.status==='Approved').length}</div><div class="mcsub cg"><i class="ti ti-circle-check"></i>ready</div></div>
      <div class="mc"><div class="mclbl">Dispatched</div><div class="mcval">${rows.filter(r=>r.status==='Dispatched').length}</div><div class="mcsub bp"><i class="ti ti-send"></i>in transit</div></div>
      <div class="mc"><div class="mclbl">Rejected</div><div class="mcval">${rows.filter(r=>r.status==='Rejected').length}</div><div class="mcsub cr"><i class="ti ti-x"></i>declined</div></div>
    </div>
    ${dsPending>0&&canApprove?`<div style="display:flex;align-items:center;gap:.625rem;padding:.75rem 1rem;background:rgba(245,158,11,.07);border:1px solid rgba(245,158,11,.25);border-radius:7px;margin-bottom:1.25rem;font-size:13px;color:var(--amber)"><i class="ti ti-clock" style="font-size:16px;flex-shrink:0"></i><strong style="margin-right:.25rem">${dsPending} request${dsPending>1?'s':''}</strong> awaiting your approval — see the queue below.</div>`:''}
    ${procFilterBarHtml({
      searchId: 'ds-search', searchPlaceholder: 'Search request #, customer, driver, vehicle…',
      statusId: 'ds-status-filter', statusOptions: ['Pending', 'Approved', 'Dispatched', 'Rejected'],
      clearId: 'ds-clear',
    })}
    ${canApprove ? `<div id="ds-bulk-bar" class="bulk-bar" style="display:none">
      <span id="ds-bulk-count">0 selected</span>
      <button type="button" class="bs1" id="ds-bulk-approve" style="margin-left:.5rem"><i class="ti ti-check"></i>Approve selected</button>
      <button type="button" class="bs1" id="ds-bulk-clear" style="margin-left:auto">Clear selection</button>
    </div>` : ''}
    <div class="card" style="padding:0">
      <div style="display:flex;align-items:center;justify-content:space-between;padding:1rem 1.25rem;border-bottom:1px solid var(--bdr)">
        <h3 style="margin:0"><i class="ti ti-send"></i>Dispatch queue</h3>
        <span id="ds-count-label" style="font-size:12px;color:var(--t3)">${rows.length} request${rows.length!==1?'s':''}</span>
      </div>
      <div class="tw"><table class="tbl" id="ds-table">
        <thead><tr>
          ${canApprove ? '<th style="width:28px"><input type="checkbox" id="ds-select-all"></th>' : ''}
          <th data-sort-key="request_number">Request #</th><th data-sort-key="so_order_number">Sales order</th>
          <th data-sort-key="customer_name">Customer</th><th data-sort-key="delivery_order_number">Delivery order</th>
          <th data-sort-key="driver_name">Driver</th><th data-sort-key="vehicle_registration">Vehicle</th>
          <th>Route</th><th data-sort-key="status">Status</th><th>Raised by</th><th>Approved by</th>
          <th data-sort-key="created_at">Date</th><th>Actions</th>
        </tr></thead>
        <tbody id="ds-tbody"></tbody>
      </table></div>
    </div>`;

  function renderDsRows(list) {
    const tbody = $('ds-tbody');
    const cols = canApprove ? 12 : 11;
    if (!list.length) {
      tbody.innerHTML = `<tr><td colspan="${cols}" style="text-align:center;color:var(--t3);padding:3rem"><i class="ti ti-send" style="font-size:2rem;display:block;margin-bottom:.5rem;opacity:.35"></i>No dispatch requests match these filters.</td></tr>`;
      $('ds-count-label').textContent = '0 requests';
      return;
    }
    $('ds-count-label').textContent = `${list.length} request${list.length!==1?'s':''}`;
    tbody.innerHTML = list.map(r=>`<tr${r.status==='Pending'?' style="background:rgba(245,158,11,.04)"':''}>
      ${canApprove ? `<td><input type="checkbox" class="ds-chk" data-id="${r.id}" ${r.status==='Pending' ? '' : 'disabled'} ${dsState.selected.has(String(r.id))?'checked':''}></td>` : ''}
      <td style="font-family:var(--fm);font-weight:700">${r.request_number}</td>
      <td style="font-family:var(--fm);color:#1D4ED8">${r.so_order_number||'—'}</td>
      <td style="font-weight:500">${r.customer_name||'—'}</td>
      <td style="font-family:var(--fm);color:var(--t3)">${r.delivery_order_number||'—'}</td>
      <td style="font-weight:500">${r.driver_name||'—'}</td>
      <td style="font-family:var(--fm)">${r.vehicle_registration||'—'}</td>
      <td>${r.route||'—'}</td>
      <td>${dsBadge(r.status)}</td>
      <td>${r.created_by||'—'}</td>
      <td>${r.approved_by||'—'}</td>
      <td style="color:var(--t3);font-size:12px;white-space:nowrap">${r.created_at}</td>
      <td style="white-space:nowrap;display:flex;gap:4px">
        <button class="bs1 ds-view" data-id="${r.id}" title="View details"><i class="ti ti-eye"></i></button>
        ${canApprove && r.status==='Pending' ? `
          <button class="bp1 ds-approve" data-id="${r.id}" style="padding:4px 10px;font-size:12px"><i class="ti ti-check"></i>Approve</button>
          <button class="bs1 ds-dispatch" data-id="${r.id}" style="padding:4px 10px;font-size:12px"><i class="ti ti-send"></i>Dispatch</button>
          <button class="bs1 ds-reject" data-id="${r.id}" style="padding:4px 10px;font-size:12px;color:var(--red)"><i class="ti ti-x"></i>Reject</button>
        ` : ''}
        ${canApprove ? `<button class="bs1 ds-del" data-id="${r.id}" style="padding:4px 8px;font-size:12px;color:var(--red)"><i class="ti ti-trash"></i></button>` : ''}
      </td>
    </tr>`).join('');
    wireDsRowActions();
  }

  function wireDsRowActions() {
    document.querySelectorAll('.ds-view').forEach(btn => {
      btn.onclick = () => { const r = rows.find(x=>String(x.id)===btn.dataset.id); if (r) openDispatchDetailOverlay(r); };
    });
    document.querySelectorAll('.ds-chk').forEach(chk => {
      chk.onchange = () => {
        const id = chk.dataset.id;
        if (chk.checked) dsState.selected.add(id); else dsState.selected.delete(id);
        updateDsBulkBar();
      };
    });
    document.querySelectorAll('.ds-approve').forEach(btn => { btn.onclick = () => reviewDispatch(btn.dataset.id, 'Approved'); });
    document.querySelectorAll('.ds-dispatch').forEach(btn => { btn.onclick = () => reviewDispatch(btn.dataset.id, 'Dispatched'); });
    document.querySelectorAll('.ds-reject').forEach(btn => { btn.onclick = () => rejectDispatch(btn.dataset.id); });
    document.querySelectorAll('.ds-del').forEach(btn => {
      btn.onclick = () => {
        confirmDelete(`Delete dispatch request <strong>#${btn.dataset.id}</strong>?`, async () => {
          const res2 = await UFCL.dispatchDelete(STORAGE.user.id, Number(btn.dataset.id));
          if (handleGovernanceResult(res2)) return;
          showOverlaySuccess('Dispatch request deleted.'); await renderDispatch();
        });
      };
    });
  }

  function updateDsBulkBar() {
    if (!canApprove) return;
    const n = dsState.selected.size;
    $('ds-bulk-bar').style.display = n > 0 ? 'flex' : 'none';
    $('ds-bulk-count').textContent = `${n} selected`;
  }

  async function reviewDispatch(id, status) {
    const res2 = await UFCL.dispatchReview(STORAGE.user.id, Number(id), status, null);
    if (!res2.ok) { showToast(res2.error || `Could not set status to ${status}`, 'error'); return; }
    showToast(status === 'Approved' ? 'Dispatch request approved.' : 'Marked as dispatched.', 'success');
    await renderDispatch();
  }

  function rejectDispatch(id) {
    confirmAction({
      title: 'Reject dispatch',
      message: 'You are about to reject this dispatch request.',
      confirmLabel: 'Reject',
      danger: true,
      icon: 'ti-x',
      extraHtml: `<div class="fg"><label>Reason for rejection</label><input id="ds-rej-notes" type="text" placeholder="Explain why…"></div>`,
      onConfirm: async () => {
        const res2 = await UFCL.dispatchReview(STORAGE.user.id, Number(id), 'Rejected', $('ds-rej-notes').value.trim());
        if (!res2.ok) { showOverlayError(res2.error); return; }
        showOverlaySuccess('Dispatch rejected.'); await renderDispatch();
      },
    });
  }

  // Phase 2 — detail overlay: status timeline + related-record facts + audit
  // history + contextual quick actions.
  function openDispatchDetailOverlay(r) {
    openOverlay('Dispatch request', r.request_number, `
      <div class="frow" style="margin-bottom:10px">${dsBadge(r.status)}</div>
      <div class="card" style="padding:12px 14px;margin-bottom:12px;background:var(--bg2)">
        <div class="frow" style="flex-wrap:wrap;gap:1.25rem;font-size:13px">
          <div><strong>Sales order</strong><br>${r.so_order_number||'—'}</div>
          <div><strong>Customer</strong><br>${r.customer_name||'—'}</div>
          <div><strong>Delivery order</strong><br>${r.delivery_order_number||'—'}</div>
          <div><strong>Driver</strong><br>${r.driver_name||'—'}</div>
          <div><strong>Vehicle</strong><br>${r.vehicle_registration||'—'}</div>
          <div><strong>Raised by</strong><br>${r.created_by||'—'}</div>
          <div><strong>Approved by</strong><br>${r.approved_by||'—'}</div>
          <div><strong>Date</strong><br>${r.created_at||'—'}</div>
        </div>
        <div style="margin-top:8px;font-size:13px"><strong>Route:</strong> ${r.route||'—'}</div>
        ${r.notes ? `<div style="margin-top:4px;font-size:13px"><strong>Notes:</strong> ${r.notes}</div>` : ''}
      </div>
      <div style="font-size:12px;font-weight:700;color:var(--t3);margin-bottom:6px;text-transform:uppercase;letter-spacing:.03em">Status progression</div>
      <div style="margin-bottom:14px">${_statusTimelineHtml(['Pending','Approved','Dispatched'], r.status, ['Rejected'])}</div>
      <div style="font-size:12px;font-weight:700;color:var(--t3);margin-bottom:6px;text-transform:uppercase;letter-spacing:.03em">History</div>
      <div id="ds-detail-history" style="margin-bottom:14px"></div>
      <div class="brow">
        ${canApprove && r.status==='Pending' ? `
          <button class="bp1" id="dsd-approve"><i class="ti ti-check"></i>Approve</button>
          <button class="bs1" id="dsd-dispatch"><i class="ti ti-send"></i>Dispatch</button>
          <button class="bs1" id="dsd-reject" style="color:var(--red)"><i class="ti ti-x"></i>Reject</button>
        ` : ''}
        <button class="bs1" id="ovCancel">Close</button>
      </div>`, null);
    _loadLogisticsHistoryInto('ds-detail-history', 'dispatch', r.id);
    setTimeout(() => {
      const ap = $('dsd-approve'); if (ap) ap.onclick = () => { closeOverlay(); reviewDispatch(r.id, 'Approved'); };
      const di = $('dsd-dispatch'); if (di) di.onclick = () => { closeOverlay(); reviewDispatch(r.id, 'Dispatched'); };
      const rj = $('dsd-reject'); if (rj) rj.onclick = () => { closeOverlay(); rejectDispatch(r.id); };
    }, 30);
  }

  renderDsRows(dsFiltered());
  wireSortableTable($('ds-table'), dsSort, dsFiltered, renderDsRows);
  $('ds-search').oninput = (e) => { dsState.search = e.target.value; renderDsRows(dsFiltered()); };
  $('ds-status-filter').onchange = (e) => { dsState.status = e.target.value; renderDsRows(dsFiltered()); };
  $('ds-clear').onclick = () => { dsState.search=''; dsState.status=''; $('ds-search').value=''; $('ds-status-filter').value=''; renderDsRows(dsFiltered()); };
  if (canApprove) {
    $('ds-select-all').onchange = (e) => {
      const list = dsFiltered().filter(r => r.status === 'Pending');
      if (e.target.checked) list.forEach(r => dsState.selected.add(String(r.id)));
      else list.forEach(r => dsState.selected.delete(String(r.id)));
      renderDsRows(dsFiltered());
      updateDsBulkBar();
    };
    $('ds-bulk-clear').onclick = () => { dsState.selected.clear(); renderDsRows(dsFiltered()); updateDsBulkBar(); };
    $('ds-bulk-approve').onclick = async () => {
      const ids = Array.from(dsState.selected);
      let okCount = 0;
      for (const id of ids) {
        const r2 = await UFCL.dispatchReview(STORAGE.user.id, Number(id), 'Approved', null);
        if (r2.ok) okCount++;
      }
      showToast(`${okCount} request${okCount!==1?'s':''} approved.`, 'success');
      dsState.selected.clear();
      await renderDispatch();
    };
  }

  $('ds-export').onclick = () => _logisticsExportExcel('dispatch', {});
  $('dsAdd').onclick = () => {
    const doOpts = pendingDeliveries.map(d=>`<option value="${d.id}">${d.order_number} — ${d.customer_name||d.driver_name||''}${d.so_order_number?' ('+d.so_order_number+')':''}</option>`).join('');
    openOverlay('New dispatch request', null, `
      <div class="fg"><label>Delivery order *</label><select id="ds-do">${doOpts||'<option>No assigned delivery orders</option>'}</select></div>
      <div class="fg"><label>Notes</label><input id="ds-notes" type="text" placeholder="Reason or instructions"></div>
      <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Submit</button><button class="bs1" id="ovCancel">Cancel</button></div>`, async () => {
      const res2 = await UFCL.dispatchCreate(STORAGE.user.id, {
        delivery_order_id: $('ds-do').value,
        notes: $('ds-notes').value.trim()
      });
      if (!res2.ok) { showOverlayError(res2.error); return; }
      showOverlaySuccess('Dispatch request submitted.');
      await renderDispatch();
    });
  };

  // Phase 1 — surfaces edit/delete requests for dispatch_request that were
  // previously created and escalated but never shown to any approver.
  await insertDeletionPanel($('page-dispatch'), ['dispatch_request'], renderDispatch);
}

// ── Third-Party Transport ─────────────────────────────────────────────────────

async function renderTransport() {
  $('page-transport').innerHTML = `<div style="padding:2rem;color:var(--t3);font-size:13px"><i class="ti ti-loader-2" style="font-size:18px;animation:spin 1s linear infinite"></i> Loading…</div>`;
  const res = await UFCL.transportJobsList(STORAGE.user.id);
  if (!res.ok) return renderDenied('transport', res.error);
  const jobs = res.rows || [];
  const companies = res.companies || [];
  const salesOrders = res.salesOrders || [];

  const jBadge = (s) => {
    const m = { Scheduled: 'ba', 'In Transit': 'bp', Completed: 'bg', Cancelled: 'br' };
    return `<span class="badge ${m[s] || 'ba'}">${s}</span>`;
  };

  const totalCost = jobs.reduce((s, j) => s + Number(j.cost || 0), 0);
  const activeCompanies = companies.length;

  companies.forEach(c => { c._statusLabel = c.active !== false ? 'Active' : 'Inactive'; });
  const tcState = { search: '', status: '', selected: new Set() };
  const tcSort = { key: null, dir: 'asc' };
  function tcFiltered() {
    return applyProcListFilters(companies, {
      search: tcState.search, searchFields: ['name', 'contact_person', 'phone', 'email'],
      status: tcState.status, statusField: '_statusLabel',
    });
  }

  $('page-transport').innerHTML = `
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;margin-bottom:1.5rem">
      <div>
        <div class="ptitle">Transport Carriers</div>
        <div class="psub">Register and manage external transport companies used for deliveries and log movements.</div>
      </div>
      <button class="bp1" id="tcAdd" style="flex-shrink:0"><i class="ti ti-building"></i>Add carrier</button>
    </div>
    <div class="cards" style="margin-bottom:1.25rem">
      <div class="mc"><div class="mclbl">Carriers</div><div class="mcval">${activeCompanies}</div><div class="mcsub cg"><i class="ti ti-building"></i>registered</div></div>
      <div class="mc"><div class="mclbl">Active</div><div class="mcval">${companies.filter(c=>c.active).length}</div><div class="mcsub cg"><i class="ti ti-circle-check"></i>active</div></div>
      <div class="mc"><div class="mclbl">Inactive</div><div class="mcval">${companies.filter(c=>!c.active).length}</div><div class="mcsub cr"><i class="ti ti-x"></i>inactive</div></div>
      <div class="mc"><div class="mclbl">Total spend (RWF)</div><div class="mcval">${Math.round(totalCost).toLocaleString()}</div><div class="mcsub ca"><i class="ti ti-coin"></i>all jobs</div></div>
    </div>
    ${procFilterBarHtml({
      searchId: 'tc-search', searchPlaceholder: 'Search company, contact, phone…',
      statusId: 'tc-status-filter', statusOptions: ['Active', 'Inactive'],
      clearId: 'tc-clear',
    })}
    <div id="tc-bulk-bar" class="bulk-bar" style="display:none">
      <span id="tc-bulk-count">0 selected</span>
      <button type="button" class="bs1" id="tc-bulk-activate"><i class="ti ti-circle-check"></i>Activate</button>
      <button type="button" class="bs1" id="tc-bulk-deactivate"><i class="ti ti-x"></i>Deactivate</button>
      <button type="button" class="bs1" id="tc-bulk-clear" style="margin-left:auto">Clear selection</button>
    </div>
    <div class="card" style="padding:0;margin-bottom:1.25rem">
      <div style="display:flex;align-items:center;justify-content:space-between;padding:1rem 1.25rem;border-bottom:1px solid var(--bdr)">
        <h3 style="margin:0"><i class="ti ti-building"></i>Registered carriers</h3>
        <span id="tc-count-label" style="font-size:12px;color:var(--t3)">${companies.length} carrier${companies.length!==1?'s':''}</span>
      </div>
      <div class="tw"><table class="tbl" id="tc-table">
        <thead><tr>
          <th style="width:28px"><input type="checkbox" id="tc-select-all"></th>
          <th data-sort-key="name">Company</th><th data-sort-key="contact_person">Contact person</th>
          <th data-sort-key="phone">Phone</th><th data-sort-key="rate_per_km">Rate / km (RWF)</th>
          <th data-sort-key="job_count">Jobs assigned</th><th data-sort-key="total_cost">Total paid (RWF)</th>
          <th data-sort-key="_statusLabel">Status</th><th>Actions</th>
        </tr></thead>
        <tbody id="tc-tbody"></tbody>
      </table></div>
    </div>
    `;

  // ── Add company ────────────────────────────────────────────────────────────
  function companyForm(c) {
    return `
      <div class="frow">
        <div class="fg"><label>Company name *</label><input id="tc-name" type="text" value="${c ? c.name : ''}" placeholder="e.g. Kigali Transport Ltd"></div>
        <div class="fg"><label>Contact person</label><input id="tc-contact" type="text" value="${c ? c.contact_person || '' : ''}" placeholder="Full name"></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Phone</label><input id="tc-phone" type="text" value="${c ? c.phone || '' : ''}" placeholder="+250 7XX XXX XXX"></div>
        <div class="fg"><label>Email</label><input id="tc-email" type="email" value="${c ? c.email || '' : ''}" placeholder="contact@company.com"></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Rate per km (RWF)</label><input id="tc-rate" type="number" min="0" value="${c ? c.rate_per_km || '' : ''}" placeholder="0"></div>
        <div class="fg"><label>Status</label><select id="tc-active">
          <option value="true"  ${!c || c.active !== false ? 'selected' : ''}>Active</option>
          <option value="false" ${c && c.active === false ? 'selected' : ''}>Inactive</option>
        </select></div>
      </div>
      <div class="frow">
        <div class="fg" style="flex:2"><label>Notes</label><input id="tc-notes" type="text" value="${c ? c.notes || '' : ''}"></div>
      </div>
      <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Save</button><button class="bs1" id="ovCancel">Cancel</button></div>`;
  }

  function renderTcRows(list) {
    const tbody = $('tc-tbody');
    if (!list.length) {
      tbody.innerHTML = '<tr><td colspan="9" style="text-align:center;color:var(--t3);padding:2rem"><i class="ti ti-building" style="font-size:1.75rem;display:block;margin-bottom:.5rem;opacity:.35"></i>No carriers match these filters.</td></tr>';
      $('tc-count-label').textContent = '0 carriers';
      return;
    }
    $('tc-count-label').textContent = `${list.length} carrier${list.length!==1?'s':''}`;
    tbody.innerHTML = list.map(c => `<tr>
      <td><input type="checkbox" class="tc-chk" data-id="${c.id}" ${tcState.selected.has(String(c.id))?'checked':''}></td>
      <td style="font-weight:600">${c.name}</td>
      <td>${c.contact_person||'—'}</td>
      <td>${c.phone||'—'}</td>
      <td style="font-family:var(--fm)">${c.rate_per_km?Number(c.rate_per_km).toLocaleString():'—'}</td>
      <td style="font-family:var(--fm)">${c.job_count}</td>
      <td style="font-family:var(--fm)">${Math.round(Number(c.total_cost||0)).toLocaleString()}</td>
      <td><span class="badge ${c.active?'bg':'br'}">${c.active?'Active':'Inactive'}</span></td>
      <td style="white-space:nowrap">
        <button class="bs1 tc-view" data-id="${c.id}" title="View details"><i class="ti ti-eye"></i></button>
        <button class="bs1 tc-edit" data-id="${c.id}"><i class="ti ti-edit"></i></button>
        <button class="bs1 tc-del" data-id="${c.id}" style="color:var(--red)"><i class="ti ti-trash"></i></button>
      </td>
    </tr>`).join('');
    wireTcRowActions();
  }

  function wireTcRowActions() {
    document.querySelectorAll('.tc-chk').forEach(chk => {
      chk.onchange = () => {
        const id = chk.dataset.id;
        if (chk.checked) tcState.selected.add(id); else tcState.selected.delete(id);
        updateTcBulkBar();
      };
    });
    document.querySelectorAll('.tc-view').forEach(btn => {
      btn.onclick = () => { const c = companies.find(x=>String(x.id)===btn.dataset.id); if (c) openCarrierDetailOverlay(c); };
    });
    document.querySelectorAll('.tc-edit').forEach(btn => { btn.onclick = () => openCarrierEditOverlay(btn.dataset.id); });
    document.querySelectorAll('.tc-del').forEach(btn => {
      btn.onclick = () => {
        const c = companies.find(x => String(x.id) === btn.dataset.id);
        if (!c) return;
        confirmDelete(`Delete transport company <strong>${c.name}</strong>?`, async () => {
          const res2 = await UFCL.transportCompaniesDelete(STORAGE.user.id, c.id);
          if (!res2.ok) { showOverlayError(res2.error); return; }
          showOverlaySuccess('Company deleted.'); await renderTransport();
        });
      };
    });
  }

  function updateTcBulkBar() {
    const n = tcState.selected.size;
    $('tc-bulk-bar').style.display = n > 0 ? 'flex' : 'none';
    $('tc-bulk-count').textContent = `${n} selected`;
  }

  async function setCarriersActive(ids, active) {
    let okCount = 0;
    for (const id of ids) {
      const c = companies.find(x => String(x.id) === String(id));
      if (!c) continue;
      const r = await UFCL.transportCompaniesUpdate(STORAGE.user.id, c.id, {
        name: c.name, contact_person: c.contact_person, phone: c.phone, email: c.email,
        rate_per_km: c.rate_per_km, notes: c.notes, active
      });
      if (r.ok) okCount++;
    }
    showToast(`${okCount} carrier${okCount!==1?'s':''} ${active?'activated':'deactivated'}.`, 'success');
    tcState.selected.clear();
    await renderTransport();
  }

  function openCarrierEditOverlay(idStr) {
    const c = companies.find(x => String(x.id) === String(idStr));
    if (!c) return;
    openOverlay('Edit transport company', c.name, companyForm(c), async () => {
      const r = await UFCL.transportCompaniesUpdate(STORAGE.user.id, c.id, {
        name: $('tc-name').value.trim(),
        contact_person: $('tc-contact').value.trim(),
        phone: $('tc-phone').value.trim(),
        email: $('tc-email').value.trim(),
        rate_per_km: $('tc-rate').value,
        notes: $('tc-notes').value.trim(),
        active: $('tc-active').value === 'true'
      });
      if (!r.ok) { showOverlayError(r.error); return; }
      showOverlaySuccess('Company updated.');
      await renderTransport();
    });
  }

  // Phase 2 — detail overlay: related facts + audit history + quick actions.
  function openCarrierDetailOverlay(c) {
    openOverlay('Transport carrier', c.name, `
      <div class="frow" style="margin-bottom:10px"><span class="badge ${c.active?'bg':'br'}">${c.active?'Active':'Inactive'}</span></div>
      <div class="card" style="padding:12px 14px;margin-bottom:12px;background:var(--bg2)">
        <div class="frow" style="flex-wrap:wrap;gap:1.25rem;font-size:13px">
          <div><strong>Contact person</strong><br>${c.contact_person||'—'}</div>
          <div><strong>Phone</strong><br>${c.phone||'—'}</div>
          <div><strong>Email</strong><br>${c.email||'—'}</div>
          <div><strong>Rate / km</strong><br>${c.rate_per_km?Number(c.rate_per_km).toLocaleString()+' RWF':'—'}</div>
          <div><strong>Jobs assigned</strong><br>${c.job_count}</div>
          <div><strong>Total paid</strong><br>${Math.round(Number(c.total_cost||0)).toLocaleString()} RWF</div>
        </div>
        ${c.notes ? `<div style="margin-top:8px;font-size:13px"><strong>Notes:</strong> ${c.notes}</div>` : ''}
      </div>
      <div style="font-size:12px;font-weight:700;color:var(--t3);margin-bottom:6px;text-transform:uppercase;letter-spacing:.03em">History</div>
      <div id="tc-detail-history" style="margin-bottom:14px"></div>
      <div class="brow">
        <button class="bs1" id="tcd-edit"><i class="ti ti-edit"></i>Edit</button>
        <button class="bs1" id="ovCancel">Close</button>
      </div>`, null);
    _loadLogisticsHistoryInto('tc-detail-history', 'transport', c.id);
    setTimeout(() => { const ed = $('tcd-edit'); if (ed) ed.onclick = () => { closeOverlay(); openCarrierEditOverlay(c.id); }; }, 30);
  }

  renderTcRows(tcFiltered());
  wireSortableTable($('tc-table'), tcSort, tcFiltered, renderTcRows);
  $('tc-search').oninput = (e) => { tcState.search = e.target.value; renderTcRows(tcFiltered()); };
  $('tc-status-filter').onchange = (e) => { tcState.status = e.target.value; renderTcRows(tcFiltered()); };
  $('tc-clear').onclick = () => { tcState.search=''; tcState.status=''; $('tc-search').value=''; $('tc-status-filter').value=''; renderTcRows(tcFiltered()); };
  $('tc-select-all').onchange = (e) => {
    const list = tcFiltered();
    if (e.target.checked) list.forEach(c => tcState.selected.add(String(c.id)));
    else list.forEach(c => tcState.selected.delete(String(c.id)));
    renderTcRows(list);
    updateTcBulkBar();
  };
  $('tc-bulk-clear').onclick = () => { tcState.selected.clear(); renderTcRows(tcFiltered()); updateTcBulkBar(); };
  $('tc-bulk-activate').onclick = () => setCarriersActive(Array.from(tcState.selected), true);
  $('tc-bulk-deactivate').onclick = () => setCarriersActive(Array.from(tcState.selected), false);

  $('tcAdd').onclick = () => openOverlay('Add transport company', null, companyForm(null), async () => {
    const r = await UFCL.transportCompaniesCreate(STORAGE.user.id, {
      name: $('tc-name').value.trim(),
      contact_person: $('tc-contact').value.trim(),
      phone: $('tc-phone').value.trim(),
      email: $('tc-email').value.trim(),
      rate_per_km: $('tc-rate').value,
      notes: $('tc-notes').value.trim(),
      active: $('tc-active').value === 'true'
    });
    if (!r.ok) { showOverlayError(r.error); return; }
    showOverlaySuccess('Company added.');
    await renderTransport();
  });
}

// ── Transport Jobs (standalone page) ─────────────────────────────────────────

async function renderTransportJobs() {
  $('page-transport-jobs').innerHTML = `<div style="padding:2rem;color:var(--t3);font-size:13px"><i class="ti ti-loader-2" style="font-size:18px;animation:spin 1s linear infinite"></i> Loading…</div>`;
  const res = await UFCL.transportJobsList(STORAGE.user.id);
  if (!res.ok) return renderDenied('transport-jobs', res.error);

  const jobs = res.rows || [];
  const companies = res.companies || [];
  const salesOrders = res.salesOrders || [];
  const vehicles = res.vehicles || [];

  const jBadge = s => {
    const m = { Scheduled: 'ba', 'In Transit': 'bp', Completed: 'bg', Cancelled: 'br' };
    return `<span class="badge ${m[s] || 'ba'}">${s}</span>`;
  };

  const totalCost = jobs.reduce((s, j) => s + Number(j.cost || 0), 0);
  jobs.forEach(j => { j._carrierLabel = j.carrier_type === 'Own Vehicle' ? 'Own Vehicle' : (j.company_name || ''); });

  const tjState = { search: '', status: '', carrier: '', selected: new Set() };
  const tjSort = { key: null, dir: 'asc' };
  function tjFiltered() {
    let list = applyProcListFilters(jobs, {
      search: tjState.search, searchFields: ['job_number', 'company_name', 'vehicle_registration', 'sales_order_number', 'customer_name', 'waybill_ref', 'origin', 'destination'],
      status: tjState.status, statusField: 'status',
    });
    if (tjState.carrier) list = list.filter(j => j._carrierLabel === tjState.carrier);
    return list;
  }
  const carrierOpts = [...new Set(jobs.filter(j=>j.carrier_type!=='Own Vehicle').map(j=>j.company_name).filter(Boolean))].sort();

  $('page-transport-jobs').innerHTML = `
    <style>@keyframes spin{to{transform:rotate(360deg)}}</style>
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;margin-bottom:1.5rem">
      <div>
        <div class="ptitle">Transport Jobs</div>
        <div class="psub">Log and track all third-party transport movements — deliveries, pickups, transfers, and returns.</div>
      </div>
      <div style="display:flex;gap:.5rem;flex-shrink:0">
        <button class="bs1" id="tj-export"><i class="ti ti-file-spreadsheet"></i>Export Excel</button>
        <button class="bp1" id="tjAdd" style="white-space:nowrap"><i class="ti ti-plus"></i>Log job</button>
      </div>
    </div>
    <div class="cards" style="margin-bottom:1.25rem">
      <div class="mc"><div class="mclbl">Total jobs</div><div class="mcval">${jobs.length}</div><div class="mcsub cg"><i class="ti ti-truck-loading"></i>last 100</div></div>
      <div class="mc"><div class="mclbl">Scheduled</div><div class="mcval">${jobs.filter(j=>j.status==='Scheduled').length}</div><div class="mcsub ca"><i class="ti ti-clock"></i>pending</div></div>
      <div class="mc"><div class="mclbl">In transit</div><div class="mcval">${jobs.filter(j=>j.status==='In Transit').length}</div><div class="mcsub bp"><i class="ti ti-truck"></i>active</div></div>
      <div class="mc"><div class="mclbl">Total spend (RWF)</div><div class="mcval">${Math.round(totalCost).toLocaleString()}</div><div class="mcsub ca"><i class="ti ti-coin"></i>all jobs</div></div>
    </div>
    ${procFilterBarHtml({
      searchId: 'tj-search', searchPlaceholder: 'Search job #, carrier, waybill, route…',
      statusId: 'tj-status-filter', statusOptions: ['Scheduled', 'In Transit', 'Completed', 'Cancelled'],
      clearId: 'tj-clear',
      extraHtml: `<select id="tj-co-filter" class="filter-select">
        <option value="">All carriers</option>
        <option value="Own Vehicle">Own vehicle</option>
        ${carrierOpts.map(n=>`<option value="${n}">${n}</option>`).join('')}
      </select>`,
    })}
    <div id="tj-bulk-bar" class="bulk-bar" style="display:none">
      <span id="tj-bulk-count">0 selected</span>
      <select id="tj-bulk-status" class="filter-select" style="margin-left:.75rem">
        <option value="">Set status to…</option>
        ${['Scheduled','In Transit','Completed','Cancelled'].map(s=>`<option value="${s}">${s}</option>`).join('')}
      </select>
      <button type="button" class="bs1" id="tj-bulk-apply">Apply</button>
      <button type="button" class="bs1" id="tj-bulk-clear" style="margin-left:auto">Clear selection</button>
    </div>
    <div class="card" style="padding:0">
      <div style="display:flex;align-items:center;justify-content:space-between;padding:1rem 1.25rem;border-bottom:1px solid var(--bdr)">
        <h3 style="margin:0"><i class="ti ti-truck-loading"></i>Job records</h3>
        <span id="tj-count-label" style="font-size:12px;color:var(--t3)">${jobs.length} job${jobs.length!==1?'s':''}</span>
      </div>
      <div class="tw"><table class="tbl" id="tj-table">
        <thead><tr>
          <th style="width:28px"><input type="checkbox" id="tj-select-all"></th>
          <th data-sort-key="job_number">Job #</th><th data-sort-key="job_date">Date</th>
          <th>Carrier type</th><th data-sort-key="_carrierLabel">Carrier / Vehicle</th>
          <th data-sort-key="job_type">Job type</th><th data-sort-key="sales_order_number">Sales order</th>
          <th>Origin → Destination</th><th data-sort-key="quantity">Qty</th>
          <th data-sort-key="waybill_ref">Waybill</th><th data-sort-key="cost">Cost (RWF)</th>
          <th data-sort-key="status">Status</th><th>Actions</th>
        </tr></thead>
        <tbody id="tj-tbody"></tbody>
      </table></div>
    </div>`;

  function renderTjRows(list) {
    const tbody = $('tj-tbody');
    if (!list.length) {
      tbody.innerHTML = '<tr><td colspan="13" style="text-align:center;color:var(--t3);padding:3rem"><i class="ti ti-truck-loading" style="font-size:2rem;display:block;margin-bottom:.5rem;opacity:.35"></i>No jobs match these filters.</td></tr>';
      $('tj-count-label').textContent = '0 jobs';
      return;
    }
    $('tj-count-label').textContent = `${list.length} job${list.length!==1?'s':''}`;
    tbody.innerHTML = list.map(j => {
      const carrierLabel = j.carrier_type === 'Own Vehicle'
        ? (j.vehicle_registration || '—') + (j.vehicle_make ? ` <span style="color:var(--t3);font-size:11px">${j.vehicle_make}${j.vehicle_model?' '+j.vehicle_model:''}</span>` : '')
        : (j.company_name || '—');
      return `<tr>
        <td><input type="checkbox" class="tj-chk" data-id="${j.id}" ${tjState.selected.has(String(j.id))?'checked':''}></td>
        <td style="font-family:var(--fm);font-weight:700">${j.job_number}</td>
        <td style="white-space:nowrap;color:var(--t3);font-size:12px">${j.job_date}</td>
        <td><span class="badge ${j.carrier_type==='Own Vehicle'?'bb':'bt'}">${j.carrier_type==='Own Vehicle'?'Own vehicle':'Third-party'}</span></td>
        <td style="font-weight:500">${carrierLabel}</td>
        <td><span class="badge bt">${j.job_type}</span></td>
        <td style="font-family:var(--fm)">${j.sales_order_number||'—'}${j.customer_name?`<div style="font-size:11px;color:var(--t3)">${j.customer_name}</div>`:''}</td>
        <td>${j.origin||'—'}${j.destination?` → ${j.destination}`:''}</td>
        <td style="font-family:var(--fm)">${j.quantity?Number(j.quantity).toLocaleString()+(j.uom?' '+j.uom:''):'—'}</td>
        <td style="font-family:var(--fm);color:var(--t3)">${j.waybill_ref||'—'}</td>
        <td style="font-family:var(--fm)">${j.cost?Number(j.cost).toLocaleString():'—'}</td>
        <td>${jBadge(j.status)}</td>
        <td style="white-space:nowrap;display:flex;gap:4px;align-items:center">
          <select class="tj-status-sel" data-id="${j.id}" style="font-size:12px;padding:3px 6px;background:var(--bg2);border:1px solid var(--bdr);color:var(--t1);border-radius:4px">
            ${['Scheduled','In Transit','Completed','Cancelled'].map(s=>`<option value="${s}" ${j.status===s?'selected':''}>${s}</option>`).join('')}
          </select>
          <button class="bs1 tj-view" data-id="${j.id}" title="View details" style="padding:3px 8px"><i class="ti ti-eye"></i></button>
          <button class="bs1 tj-edit" data-id="${j.id}" style="padding:3px 8px"><i class="ti ti-edit"></i></button>
          <button class="bs1 tj-del" data-id="${j.id}" style="padding:3px 8px;color:var(--red)"><i class="ti ti-trash"></i></button>
        </td>
      </tr>`;
    }).join('');
    wireTjRowActions();
  }

  function wireTjRowActions() {
    document.querySelectorAll('.tj-chk').forEach(chk => {
      chk.onchange = () => {
        const id = chk.dataset.id;
        if (chk.checked) tjState.selected.add(id); else tjState.selected.delete(id);
        updateTjBulkBar();
      };
    });
    document.querySelectorAll('.tj-view').forEach(btn => {
      btn.onclick = () => { const j = jobs.find(x=>String(x.id)===btn.dataset.id); if (j) openTransportJobDetailOverlay(j); };
    });
    document.querySelectorAll('.tj-status-sel').forEach(sel => {
      sel.onchange = async () => {
        const r = await UFCL.transportJobsUpdateStatus(STORAGE.user.id, Number(sel.dataset.id), sel.value);
        if (!r.ok) { showToast(r.error || 'Could not update status', 'error'); await renderTransportJobs(); return; }
        showToast('Transport job status updated.', 'success');
        await renderTransportJobs();
      };
    });
    document.querySelectorAll('.tj-edit').forEach(btn => { btn.onclick = () => openTransportJobEditOverlay(btn.dataset.id); });
    document.querySelectorAll('.tj-del').forEach(btn => {
      btn.onclick = () => {
        const j = jobs.find(x => String(x.id) === btn.dataset.id);
        if (!j) return;
        confirmDelete(`Delete transport job <strong>${j.job_number}</strong> (${j.company_name})?`, async () => {
          const res2 = await UFCL.transportJobsDelete(STORAGE.user.id, j.id);
          if (handleGovernanceResult(res2)) return;
          showOverlaySuccess('Transport job deleted.'); await renderTransportJobs();
        });
      };
    });
  }

  function updateTjBulkBar() {
    const n = tjState.selected.size;
    $('tj-bulk-bar').style.display = n > 0 ? 'flex' : 'none';
    $('tj-bulk-count').textContent = `${n} selected`;
  }

  // Phase 2 — detail overlay: status timeline + related facts + audit history.
  function openTransportJobDetailOverlay(j) {
    const carrierLabel = j.carrier_type === 'Own Vehicle' ? (j.vehicle_registration||'—') : (j.company_name||'—');
    openOverlay('Transport job', j.job_number, `
      <div class="frow" style="margin-bottom:10px">${jBadge(j.status)}</div>
      <div class="card" style="padding:12px 14px;margin-bottom:12px;background:var(--bg2)">
        <div class="frow" style="flex-wrap:wrap;gap:1.25rem;font-size:13px">
          <div><strong>Carrier</strong><br>${carrierLabel}</div>
          <div><strong>Job type</strong><br>${j.job_type}</div>
          <div><strong>Date</strong><br>${j.job_date}</div>
          <div><strong>Sales order</strong><br>${j.sales_order_number||'—'}</div>
          <div><strong>Quantity</strong><br>${j.quantity?Number(j.quantity).toLocaleString()+(j.uom?' '+j.uom:''):'—'}</div>
          <div><strong>Cost</strong><br>${j.cost?Number(j.cost).toLocaleString()+' RWF':'—'}</div>
          <div><strong>Waybill</strong><br>${j.waybill_ref||'—'}</div>
        </div>
        <div style="margin-top:8px;font-size:13px"><strong>Route:</strong> ${j.origin||'—'}${j.destination?` → ${j.destination}`:''}</div>
        ${j.notes ? `<div style="margin-top:4px;font-size:13px"><strong>Notes:</strong> ${j.notes}</div>` : ''}
      </div>
      <div style="font-size:12px;font-weight:700;color:var(--t3);margin-bottom:6px;text-transform:uppercase;letter-spacing:.03em">Status progression</div>
      <div style="margin-bottom:14px">${_statusTimelineHtml(['Scheduled','In Transit','Completed'], j.status, ['Cancelled'])}</div>
      <div style="font-size:12px;font-weight:700;color:var(--t3);margin-bottom:6px;text-transform:uppercase;letter-spacing:.03em">History</div>
      <div id="tj-detail-history" style="margin-bottom:14px"></div>
      <div class="brow">
        <button class="bs1" id="tjd-edit"><i class="ti ti-edit"></i>Edit</button>
        <button class="bs1" id="ovCancel">Close</button>
      </div>`, null);
    _loadLogisticsHistoryInto('tj-detail-history', 'transport-jobs', j.id);
    setTimeout(() => { const ed = $('tjd-edit'); if (ed) ed.onclick = () => { closeOverlay(); openTransportJobEditOverlay(j.id); }; }, 30);
  }

  renderTjRows(tjFiltered());
  wireSortableTable($('tj-table'), tjSort, tjFiltered, renderTjRows);
  $('tj-search').oninput = (e) => { tjState.search = e.target.value; renderTjRows(tjFiltered()); };
  $('tj-status-filter').onchange = (e) => { tjState.status = e.target.value; renderTjRows(tjFiltered()); };
  $('tj-co-filter').onchange = (e) => { tjState.carrier = e.target.value; renderTjRows(tjFiltered()); };
  $('tj-clear').onclick = () => {
    tjState.search=''; tjState.status=''; tjState.carrier='';
    $('tj-search').value=''; $('tj-status-filter').value=''; $('tj-co-filter').value='';
    renderTjRows(tjFiltered());
  };
  $('tj-select-all').onchange = (e) => {
    const list = tjFiltered();
    if (e.target.checked) list.forEach(j => tjState.selected.add(String(j.id)));
    else list.forEach(j => tjState.selected.delete(String(j.id)));
    renderTjRows(list);
    updateTjBulkBar();
  };
  $('tj-bulk-clear').onclick = () => { tjState.selected.clear(); renderTjRows(tjFiltered()); updateTjBulkBar(); };
  $('tj-bulk-apply').onclick = async () => {
    const status = $('tj-bulk-status').value;
    if (!status) { showToast('Choose a status first.', 'error'); return; }
    const ids = Array.from(tjState.selected);
    let okCount = 0;
    for (const id of ids) {
      const r = await UFCL.transportJobsUpdateStatus(STORAGE.user.id, Number(id), status);
      if (r.ok) okCount++;
    }
    showToast(`${okCount} job${okCount!==1?'s':''} updated.`, 'success');
    tjState.selected.clear();
    await renderTransportJobs();
  };

  $('tj-export').onclick = () => _logisticsExportExcel('transport-jobs', {});
  $('tjAdd').onclick = () => openTransportJobOverlay(companies, salesOrders, null, () => renderTransportJobs(), vehicles);

  function openTransportJobEditOverlay(idStr) {
      const j = jobs.find(x => String(x.id) === String(idStr));
      if (!j) return;
      const isOwn = j.carrier_type === 'Own Vehicle';
      const coOpts = companies.map(c => `<option value="${c.id}" ${j.company_name===c.name?'selected':''}>${c.name}</option>`).join('');
      const vhOpts = vehicles.map(v => `<option value="${v.id}" ${j.vehicle_registration===v.registration?'selected':''}>${v.registration}${v.make?' — '+v.make+(v.model?' '+v.model:''):''}</option>`).join('');
      const soOpts = `<option value="">— None —</option>` +
        salesOrders.map(s => `<option value="${s.id}" ${j.sales_order_number===s.order_number?'selected':''}>${s.order_number} — ${s.customer_name}</option>`).join('');
      openOverlay('Edit transport job', j.job_number, `
        <div style="display:flex;gap:0;margin-bottom:1.25rem;border:1px solid var(--bdr);border-radius:7px;overflow:hidden">
          <button id="tje-type-third" style="flex:1;padding:.5rem 1rem;font-size:13px;font-weight:600;border:none;cursor:pointer;background:${!isOwn?'var(--primary)':'var(--bg2)'};color:${!isOwn?'#fff':'var(--t2)'}">
            <i class="ti ti-building"></i> Third-party carrier
          </button>
          <button id="tje-type-own" style="flex:1;padding:.5rem 1rem;font-size:13px;font-weight:600;border:none;border-left:1px solid var(--bdr);cursor:pointer;background:${isOwn?'var(--primary)':'var(--bg2)'};color:${isOwn?'#fff':'var(--t2)'}">
            <i class="ti ti-truck"></i> Own vehicle
          </button>
        </div>
        <input type="hidden" id="tje-carrier-type" value="${j.carrier_type||'Third-party'}">
        <div id="tje-third-panel" style="${isOwn?'display:none':''}">
          <div class="fg" style="margin-bottom:.875rem"><label>Transport company *</label><select id="tje-co">${coOpts}</select></div>
        </div>
        <div id="tje-own-panel" style="${!isOwn?'display:none':''}">
          <div class="fg" style="margin-bottom:.875rem"><label>Vehicle *</label><select id="tje-vehicle">${vhOpts}</select></div>
        </div>
        <div class="frow">
          <div class="fg"><label>Date *</label><input id="tje-date" type="date" value="${j.job_date.split('/').reverse().join('-')}"></div>
          <div class="fg"><label>Job type</label><select id="tje-type">
            <option ${j.job_type==='Delivery'?'selected':''}>Delivery</option>
            <option ${j.job_type==='Pickup'?'selected':''}>Pickup</option>
            <option ${j.job_type==='Return'?'selected':''}>Return</option>
            <option ${j.job_type==='Transfer'?'selected':''}>Transfer</option>
          </select></div>
        </div>
        <div class="fg"><label>Linked sales order</label><select id="tje-so">${soOpts}</select></div>
        <div class="frow">
          <div class="fg"><label>Origin</label><input id="tje-origin" type="text" value="${j.origin||''}"></div>
          <div class="fg"><label>Destination</label><input id="tje-dest" type="text" value="${j.destination||''}"></div>
        </div>
        <div class="frow">
          <div class="fg"><label>Quantity</label><input id="tje-qty" type="number" min="0" value="${j.quantity||''}"></div>
          <div class="fg"><label>UoM</label><input id="tje-uom" type="text" value="${j.uom||'units'}"></div>
          <div class="fg"><label>Cost (RWF)</label><input id="tje-cost" type="number" min="0" value="${j.cost||''}"></div>
        </div>
        <div class="frow">
          <div class="fg"><label>Waybill ref</label><input id="tje-waybill" type="text" value="${j.waybill_ref||''}"></div>
          <div class="fg"><label>Notes</label><input id="tje-notes" type="text" value="${j.notes||''}"></div>
        </div>
        <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Save</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
        async () => {
          const ct = $('tje-carrier-type').value;
          const res2 = await UFCL.transportJobsUpdate(STORAGE.user.id, j.id, {
            carrier_type: ct,
            transport_company_id: ct === 'Third-party' ? $('tje-co').value : null,
            vehicle_id: ct === 'Own Vehicle' ? $('tje-vehicle').value : null,
            job_date: $('tje-date').value, job_type: $('tje-type').value,
            sales_order_id: $('tje-so').value || null,
            origin: $('tje-origin').value.trim(), destination: $('tje-dest').value.trim(),
            quantity: $('tje-qty').value || null, uom: $('tje-uom').value.trim(),
            cost: $('tje-cost').value || null, waybill_ref: $('tje-waybill').value.trim(),
            notes: $('tje-notes').value.trim()
          });
          if (handleGovernanceResult(res2)) return;
          showOverlaySuccess('Transport job updated.'); await renderTransportJobs();
        });
      setTimeout(() => {
        $('tje-type-third')?.addEventListener('click', () => {
          $('tje-carrier-type').value = 'Third-party';
          $('tje-third-panel').style.display = ''; $('tje-own-panel').style.display = 'none';
          $('tje-type-third').style.background = 'var(--primary)'; $('tje-type-third').style.color = '#fff';
          $('tje-type-own').style.background = 'var(--bg2)'; $('tje-type-own').style.color = 'var(--t2)';
        });
        $('tje-type-own')?.addEventListener('click', () => {
          $('tje-carrier-type').value = 'Own Vehicle';
          $('tje-third-panel').style.display = 'none'; $('tje-own-panel').style.display = '';
          $('tje-type-own').style.background = 'var(--primary)'; $('tje-type-own').style.color = '#fff';
          $('tje-type-third').style.background = 'var(--bg2)'; $('tje-type-third').style.color = 'var(--t2)';
        });
      }, 30);
  }

  // Phase 1 — surfaces edit/delete requests for transport_job that were
  // previously created and escalated but never shown to any approver.
  await insertPendingPanel($('page-transport-jobs'), ['transport_job'], renderTransportJobs);
  await insertDeletionPanel($('page-transport-jobs'), ['transport_job'], renderTransportJobs);
}

function openTransportJobOverlay(companies, salesOrders, prefillSalesOrderId, onDone, vehicles = [], prefillCarrierType = 'Third-party') {
  const coOpts = companies.map(c => `<option value="${c.id}">${c.name}${c.phone ? ' — ' + c.phone : ''}</option>`).join('');
  const vhOpts = vehicles.map(v => `<option value="${v.id}">${v.registration}${v.make ? ' — ' + v.make + (v.model ? ' ' + v.model : '') : ''}</option>`).join('');
  const soOpts = `<option value="">— None (standalone job) —</option>` +
    salesOrders.map(s => `<option value="${s.id}" data-incl="${s.price_tax_type==='Inclusive'?'1':''}" ${prefillSalesOrderId && Number(prefillSalesOrderId) === s.id ? 'selected' : ''}>${s.order_number} — ${s.customer_name} (${s.product_type} ${s.product_size}, qty ${s.quantity})${s.price_tax_type==='Inclusive'?' ✓ Transport incl.':''}</option>`).join('');

  const isOwn = prefillCarrierType === 'Own Vehicle';

  openOverlay('Log transport job', 'Record a transport movement using your own vehicle or a third-party carrier.', `
    <div style="display:flex;gap:0;margin-bottom:1.25rem;border:1px solid var(--bdr);border-radius:7px;overflow:hidden">
      <button id="tj-type-third" class="tj-carrier-tab${!isOwn?' active':''}" style="flex:1;padding:.6rem 1rem;font-size:13px;font-weight:600;border:none;cursor:pointer;background:${!isOwn?'var(--primary)':'var(--bg2)'};color:${!isOwn?'#fff':'var(--t2)'};transition:all .15s">
        <i class="ti ti-building"></i> Third-party carrier
      </button>
      <button id="tj-type-own" class="tj-carrier-tab${isOwn?' active':''}" style="flex:1;padding:.6rem 1rem;font-size:13px;font-weight:600;border:none;border-left:1px solid var(--bdr);cursor:pointer;background:${isOwn?'var(--primary)':'var(--bg2)'};color:${isOwn?'#fff':'var(--t2)'};transition:all .15s">
        <i class="ti ti-truck"></i> Own vehicle
      </button>
    </div>
    <input type="hidden" id="tj-carrier-type" value="${prefillCarrierType}">
    <div id="tj-third-panel" style="${isOwn?'display:none':''}">
      <div class="fg" style="margin-bottom:.875rem"><label>Transport company *</label>
        <select id="tj-co">${coOpts || '<option value="">No companies registered — add one in Transport Carriers</option>'}</select>
      </div>
    </div>
    <div id="tj-own-panel" style="${!isOwn?'display:none':''}">
      <div class="fg" style="margin-bottom:.875rem"><label>Vehicle *</label>
        <select id="tj-vehicle">${vhOpts || '<option value="">No active vehicles — add one in Vehicle Fleet</option>'}</select>
      </div>
    </div>
    <div id="tj-so-banner" style="display:none;background:#ecfdf5;border:1px solid #6ee7b7;border-radius:8px;padding:10px 14px;margin-bottom:10px;font-size:13px;color:#065f46">
      <i class="ti ti-truck-delivery"></i> <strong>Transport included in sales price</strong> — transport cost pre-set to 0. Update if you need to track a separate charge.
    </div>
    <div class="frow">
      <div class="fg"><label>Job date *</label><input id="tj-date" type="date" value="${new Date().toISOString().slice(0, 10)}"></div>
      <div class="fg"><label>Job type</label>
        <select id="tj-type">
          <option value="Delivery">Delivery</option>
          <option value="Pickup">Pickup</option>
          <option value="Return">Return</option>
          <option value="Transfer">Internal Transfer</option>
        </select>
      </div>
    </div>
    <div class="fg"><label>Linked sales order</label><select id="tj-so">${soOpts}</select></div>
    <div class="frow">
      <div class="fg"><label>Origin</label><input id="tj-origin" type="text" placeholder="Loading point / address"></div>
      <div class="fg"><label>Destination</label><input id="tj-dest" type="text" placeholder="Delivery address"></div>
    </div>
    <div class="frow">
      <div class="fg"><label>Quantity</label><input id="tj-qty" type="number" min="0" placeholder="0"></div>
      <div class="fg"><label>Unit</label><input id="tj-uom" type="text" value="units" placeholder="units, m³, kg"></div>
      <div class="fg"><label>Cost (RWF)</label><input id="tj-cost" type="number" min="0" placeholder="0"></div>
    </div>
    <div class="frow">
      <div class="fg"><label>Waybill / ref #</label><input id="tj-waybill" type="text" placeholder="External reference number"></div>
      <div class="fg"><label>Notes</label><input id="tj-notes" type="text"></div>
    </div>
    <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Save job</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
    async () => {
      const ct = $('tj-carrier-type').value;
      const r = await UFCL.transportJobsCreate(STORAGE.user.id, {
        carrier_type: ct,
        transport_company_id: ct === 'Third-party' ? $('tj-co').value : null,
        vehicle_id: ct === 'Own Vehicle' ? $('tj-vehicle').value : null,
        job_date: $('tj-date').value,
        job_type: $('tj-type').value,
        sales_order_id: $('tj-so').value || null,
        origin: $('tj-origin').value.trim(),
        destination: $('tj-dest').value.trim(),
        quantity: $('tj-qty').value || null,
        uom: $('tj-uom').value.trim(),
        cost: $('tj-cost').value || null,
        waybill_ref: $('tj-waybill').value.trim(),
        notes: $('tj-notes').value.trim()
      });
      if (!r.ok) { showOverlayError(r.error); return; }
      showOverlaySuccess(`Job ${r.jobNum} saved.`);
      await onDone();
    }
  );
  setTimeout(() => {
    // Carrier type toggle
    $('tj-type-third')?.addEventListener('click', () => {
      $('tj-carrier-type').value = 'Third-party';
      $('tj-third-panel').style.display = '';
      $('tj-own-panel').style.display = 'none';
      $('tj-type-third').style.background = 'var(--primary)'; $('tj-type-third').style.color = '#fff';
      $('tj-type-own').style.background = 'var(--bg2)'; $('tj-type-own').style.color = 'var(--t2)';
    });
    $('tj-type-own')?.addEventListener('click', () => {
      $('tj-carrier-type').value = 'Own Vehicle';
      $('tj-third-panel').style.display = 'none';
      $('tj-own-panel').style.display = '';
      $('tj-type-own').style.background = 'var(--primary)'; $('tj-type-own').style.color = '#fff';
      $('tj-type-third').style.background = 'var(--bg2)'; $('tj-type-third').style.color = 'var(--t2)';
    });
    // Sales order banner
    const tjSo = $('tj-so'), tjBanner = $('tj-so-banner'), tjCost = $('tj-cost'), tjNotes = $('tj-notes');
    const applyBanner = () => {
      const sel = tjSo?.options[tjSo.selectedIndex];
      const incl = sel?.dataset?.incl === '1';
      if (tjBanner) tjBanner.style.display = incl ? '' : 'none';
      if (incl && tjCost && !tjCost.value) tjCost.value = '0';
      if (incl && tjNotes && !tjNotes.value) tjNotes.value = 'Transport cost included in sales order price';
    };
    if (tjSo) { tjSo.addEventListener('change', applyBanner); applyBanner(); }
  }, 30);
}

// ── Timber Inventory ──────────────────────────────────────────────────────────

async function renderTimberInventory() {
  const res = await UFCL.timberInventoryList(STORAGE.user.id);
  if (!res.ok) return renderDenied('timber-inventory', res.error);
  const { stock, logs7 = [], harvestSummary = [], wasteRate, finishedTimberFlow = [],
           costing, reconciliation, timberProcessingReconciliation, productProfitability = [],
           inventoryValueByLocation = [] } = res;

  $('page-timber-inventory').innerHTML = `
    <div style="display:flex;align-items:flex-start;justify-content:space-between;flex-wrap:wrap;gap:.5rem;margin-bottom:.25rem">
      <div>
        <div class="ptitle">Timber Inventory</div>
        <div class="psub">Real-time view of all timber, poles, and production stock balances derived from daily production and sales.</div>
      </div>
      <!-- Sawmill Phase 1 (Workstream 5) — Cross-Navigation: move through the
           production pipeline (Sawmill → Inventory → Stock Transfer → Sales)
           without returning to the sidebar. -->
      <div style="display:flex;gap:.5rem;flex-wrap:wrap">
        <button class="bs1" onclick="showPage('daily-timber')"><i class="ti ti-axe"></i>Sawmill Production</button>
        <button class="bs1" onclick="showPage('stock-transfers')"><i class="ti ti-arrows-right-left"></i>Stock Transfer</button>
        <button class="bs1" onclick="showPage('sales')"><i class="ti ti-shopping-cart"></i>Sales</button>
      </div>
    </div>

    <div class="cards">
      <div class="mc"><div class="mclbl">Timber in stock</div><div class="mcval">${stock.timberStock.toLocaleString()}</div><div class="mcsub cg"><i class="ti ti-trees"></i>units</div></div>
      <div class="mc"><div class="mclbl">Poles in stock</div><div class="mcval">${stock.polesStock.toLocaleString()}</div><div class="mcsub bp"><i class="ti ti-align-center"></i>units</div></div>
      <div class="mc"><div class="mclbl">Timber produced</div><div class="mcval">${stock.timberProduced.toLocaleString()}</div><div class="mcsub cg"><i class="ti ti-hammer"></i>all time</div></div>
      <div class="mc"><div class="mclbl">Waste rate</div><div class="mcval">${wasteRate}%</div><div class="mcsub ${Number(wasteRate)>15?'cr':'ca'}"><i class="ti ti-recycle"></i>all time</div></div>
    </div>

    <!-- Sawmill Phase 1 (Workstream 4) — Inventory & Logistics Visibility.
         Reuses stock_levels/stock_transfers directly; no new operational
         states, just a clearer view of where catalogued Finished Timber/
         Poles output currently sits in the pipeline. -->
    <div class="card" style="margin-top:.5rem">
      <h3><i class="ti ti-map-pin"></i>Finished Timber Flow</h3>
      ${finishedTimberFlow.length ? `<div class="tw"><table class="dt">
        <thead><tr><th>Product</th><th>Ready for Sale (Gatare)</th><th>Ready for Transfer</th><th>In Transit</th><th>Available at Nyanza</th><th>Available at Showroom</th></tr></thead>
        <tbody>${finishedTimberFlow.map(r => `<tr>
          <td style="font-weight:500">${r.subType ? r.subType + ' ' : ''}${r.size}<div style="font-size:11px;color:var(--t3)">${r.type}</div></td>
          <td style="font-family:var(--fm);font-weight:600;color:${r.readyForSaleGatare>0?'var(--green)':'var(--t3)'}">${r.readyForSaleGatare.toLocaleString()}</td>
          <td style="font-family:var(--fm)">${r.readyForTransfer.toLocaleString()}</td>
          <td style="font-family:var(--fm);color:${r.inTransit>0?'var(--amber)':'var(--t3)'}">${r.inTransit.toLocaleString()}</td>
          <td style="font-family:var(--fm)">${r.availableAtNyanza.toLocaleString()}</td>
          <td style="font-family:var(--fm)">${r.availableAtShowroom.toLocaleString()}</td>
        </tr>`).join('')}</tbody>
      </table></div>` : `<p style="color:var(--t3);font-size:13px">No Finished Timber products are catalogued yet. Add a size in Product Catalog to start tracking it here.</p>`}
    </div>

    <!-- Sawmill Phase 2 (Workstream 2/4/5) — Enterprise reconciliation +
         cost/profitability, sourced from the same figures the Executive
         Dashboard's Sawmill panel reuses (single costing source, no
         duplicate engine). -->
    <div class="card" style="margin-top:.5rem">
      <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:.5rem;margin-bottom:.5rem">
        <h3 style="margin-bottom:0"><i class="ti ti-report-money"></i>Cost, Valuation &amp; Reconciliation</h3>
        <button class="sbtn" id="ti-export-csv"><i class="ti ti-table-export"></i> Export CSV</button>
      </div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:.75rem">
        ${reconciliation ? `<span class="badge ${reconciliation.reconciled ? 'bg' : 'br'}"><i class="ti ${reconciliation.reconciled ? 'ti-circle-check' : 'ti-alert-triangle'}"></i> Inventory ${reconciliation.reconciled ? 'reconciled' : `mismatch: ${reconciliation.mismatch} units (produced ${reconciliation.totalProduced} − sold ${reconciliation.totalSold} ≠ stock ${reconciliation.currentStock})`}</span>` : ''}
        ${timberProcessingReconciliation ? `<span class="badge ${timberProcessingReconciliation.reconciled ? 'bg' : 'bt'}" title="${timberProcessingReconciliation.note}"><i class="ti ti-info-circle"></i> Processing breakdown: ${timberProcessingReconciliation.breakdownSum}/${timberProcessingReconciliation.totalProduced} categorized</span>` : ''}
      </div>
      ${costing ? `
      <div class="cards" style="margin:0 0 .75rem">
        <div class="mc"><div class="mclbl">Inventory value</div><div class="mcval">${_fmtCur(costing.inventoryValue)}</div><div class="mcsub cg"><i class="ti ti-building-warehouse"></i>all locations</div></div>
        <div class="mc"><div class="mclbl">Production cost (mo.)</div><div class="mcval">${_fmtCur(costing.productionCostMonth)}</div><div class="mcsub bt"><i class="ti ti-hammer"></i>units × std. cost</div></div>
        <div class="mc"><div class="mclbl">Sales value (mo.)</div><div class="mcval">${_fmtCur(costing.salesValueMonth)}</div><div class="mcsub cg"><i class="ti ti-shopping-cart"></i>resolved orders</div></div>
        <div class="mc"><div class="mclbl">COGS (mo.)</div><div class="mcval">${_fmtCur(costing.cogsMonth)}</div><div class="mcsub bt"><i class="ti ti-receipt"></i>units sold × std. cost</div></div>
        <div class="mc"><div class="mclbl">Gross profit (mo.)</div><div class="mcval" style="color:${costing.grossProfitMonth>=0?'var(--green)':'var(--red)'}">${_fmtCur(costing.grossProfitMonth)}</div><div class="mcsub ${costing.grossProfitMonth>=0?'cg':'cr'}"><i class="ti ti-chart-line"></i>${costing.grossMarginPctMonth != null ? costing.grossMarginPctMonth + '% margin' : 'no sales yet'}</div></div>
      </div>
      ${costing.unresolvedSalesValueMonth > 0 ? `<div class="lerr" style="display:block">${_fmtCur(costing.unresolvedSalesValueMonth)} in sales this month has no matching Product Catalog item and is excluded from COGS/Gross Profit.</div>` : ''}
      ` : ''}
      <div class="tw">
        <table class="dt">
          <thead><tr><th>Product</th><th>Standard cost</th><th>Default price</th><th>Units sold (mo.)</th><th>Sales value (mo.)</th><th>COGS (mo.)</th><th>Gross profit (mo.)</th><th>Margin %</th></tr></thead>
          <tbody>${productProfitability.length ? productProfitability.map(p => `<tr>
            <td style="font-weight:500">${p.subType ? p.subType + ' ' : ''}${p.size}<div style="font-size:11px;color:var(--t3)">${p.type}</div></td>
            <td style="font-family:var(--fm)">${p.standardCost != null ? _fmtCur(p.standardCost) : '<span class="badge br">Not set</span>'}</td>
            <td style="font-family:var(--fm)">${p.defaultPrice != null ? _fmtCur(p.defaultPrice) : '<span class="badge br">Not set</span>'}</td>
            <td style="font-family:var(--fm)">${p.unitsSoldMonth.toLocaleString()}</td>
            <td style="font-family:var(--fm)">${_fmtCur(p.salesValueMonth)}</td>
            <td style="font-family:var(--fm)">${_fmtCur(p.cogsMonth)}</td>
            <td style="font-family:var(--fm);color:${p.grossProfitMonth>=0?'var(--green)':'var(--red)'}">${_fmtCur(p.grossProfitMonth)}</td>
            <td style="font-family:var(--fm)">${p.grossMarginPctMonth != null ? p.grossMarginPctMonth + '%' : '—'}</td>
          </tr>`).join('') : '<tr><td colspan="8" style="text-align:center;color:var(--t3);padding:1rem">No catalogued products yet.</td></tr>'}</tbody>
        </table>
      </div>
    </div>

    <div class="cards" style="margin-top:.5rem">
      <div class="card" style="flex:1;min-width:280px;margin:0">
        <h3><i class="ti ti-trees"></i>Timber stock breakdown</h3>
        <table class="dt">
          <thead><tr><th>Type</th><th>Produced</th><th>Sold</th><th>Stock</th></tr></thead>
          <tbody>
            <tr><td>Kiln-dried</td><td style="font-family:var(--fm)">${stock.kilnDriedProduced.toLocaleString()}</td><td style="font-family:var(--fm)">${stock.kilnDriedSold.toLocaleString()}</td><td style="font-family:var(--fm);font-weight:600;color:${stock.kilnDriedStock<=0?'var(--red)':'inherit'}">${stock.kilnDriedStock.toLocaleString()}</td></tr>
            <tr><td>CCA-treated</td><td style="font-family:var(--fm)">${stock.ccaTreatedProduced.toLocaleString()}</td><td style="font-family:var(--fm)">${stock.ccaTreatedSold.toLocaleString()}</td><td style="font-family:var(--fm);font-weight:600;color:${stock.ccaTreatedStock<=0?'var(--red)':'inherit'}">${stock.ccaTreatedStock.toLocaleString()}</td></tr>
            <tr><td>Untreated</td><td style="font-family:var(--fm)">${stock.untreatedProduced.toLocaleString()}</td><td style="font-family:var(--fm)">${stock.untreatedSold.toLocaleString()}</td><td style="font-family:var(--fm);font-weight:600;color:${stock.untreatedStock<=0?'var(--red)':'inherit'}">${stock.untreatedStock.toLocaleString()}</td></tr>
            <tr style="font-weight:600;border-top:2px solid var(--bdr)"><td>Total timber</td><td style="font-family:var(--fm)">${stock.timberProduced.toLocaleString()}</td><td style="font-family:var(--fm)">${stock.timberSold.toLocaleString()}</td><td style="font-family:var(--fm);color:${stock.timberStock<=0?'var(--red)':'var(--green)'}">${stock.timberStock.toLocaleString()}</td></tr>
            <tr><td>Poles</td><td style="font-family:var(--fm)">${stock.polesProduced.toLocaleString()}</td><td style="font-family:var(--fm)">${stock.polesSold.toLocaleString()}</td><td style="font-family:var(--fm);font-weight:600;color:${stock.polesStock<=0?'var(--red)':'inherit'}">${stock.polesStock.toLocaleString()}</td></tr>
          </tbody>
        </table>
      </div>
      <div class="card" style="flex:1;min-width:280px;margin:0">
        <h3><i class="ti ti-trees"></i>Harvest by species</h3>
        ${harvestSummary.length ? `<table class="dt">
          <thead><tr><th>Species</th><th>Total harvested</th><th>Harvest runs</th></tr></thead>
          <tbody>${harvestSummary.map(r=>`<tr>
            <td style="font-weight:500">${r.species}</td>
            <td style="font-family:var(--fm)">${Number(r.total).toLocaleString()}</td>
            <td style="font-family:var(--fm)">${r.harvests}</td>
          </tr>`).join('')}
          </tbody>
        </table>` : `<p style="color:var(--t3);font-size:13px">No harvest records yet. Add them from the Harvesting Daily page.</p>`}
      </div>
    </div>

    <div class="card">
      <h3><i class="ti ti-clipboard-list"></i>Last 7 production days</h3>
      <div class="tw"><table class="dt">
        <thead><tr><th>Date</th><th>Timber total</th><th>Kiln-dried</th><th>CCA-treated</th><th>Untreated</th><th>Timber waste</th><th>Poles</th><th>Pole waste</th><th>Downtime (h)</th><th>Supervisor</th></tr></thead>
        <tbody>${logs7.length ? logs7.map(r=>`<tr>
          <td style="font-weight:500;white-space:nowrap">${r.date}</td>
          <td style="font-family:var(--fm)">${r.timber_units}</td>
          <td style="font-family:var(--fm)">${r.timber_kiln_dried}</td>
          <td style="font-family:var(--fm)">${r.timber_cca_treated}</td>
          <td style="font-family:var(--fm)">${r.timber_untreated}</td>
          <td style="font-family:var(--fm);color:${Number(r.timber_waste)>0?'var(--amber)':''}">${r.timber_waste}</td>
          <td style="font-family:var(--fm)">${r.poles_units}</td>
          <td style="font-family:var(--fm);color:${Number(r.poles_waste)>0?'var(--amber)':''}">${r.poles_waste}</td>
          <td style="font-family:var(--fm);color:${Number(r.downtime_hours)>0?'var(--red)':''}">${Number(r.downtime_hours).toFixed(1)}</td>
          <td>${r.supervisor||'—'}</td>
        </tr>`).join('') : '<tr><td colspan="10" style="text-align:center;color:var(--t3);padding:1.5rem">No production logs in the last 7 days.</td></tr>'}
        </tbody>
      </table></div>
    </div>`;

  // Sawmill Phase 2 (Workstream 5) — reuses the app-wide downloadCsv()
  // pattern (see renderExport) rather than a new export mechanism.
  $('ti-export-csv').onclick = () => {
    const csv = [
      ['Product', 'Type', 'Standard Cost', 'Default Price', 'Units Sold (mo.)', 'Sales Value (mo.)', 'COGS (mo.)', 'Gross Profit (mo.)', 'Margin %'].join(','),
      ...productProfitability.map(p => [
        `"${(p.subType ? p.subType + ' ' : '') + p.size}"`, p.type,
        p.standardCost ?? '', p.defaultPrice ?? '', p.unitsSoldMonth,
        p.salesValueMonth, p.cogsMonth, p.grossProfitMonth, p.grossMarginPctMonth ?? '',
      ].join(',')),
    ].join('\n');
    downloadCsv(csv, `sawmill-cost-profitability-${new Date().toISOString().slice(0,10)}.csv`);
  };
}

function renderDenied(id, message) {
  $(`page-${id}`).innerHTML = `
    <div class="denied">
      <i class="ti ti-lock"></i>
      <h3>Access denied</h3>
      <p>${message || 'Your role does not have permission to view this page.'}</p>
    </div>
  `;
}

// ── Machine Registry ──────────────────────────────────────────────────────────

async function renderMachines() {
  $('page-machines').innerHTML = `<div style="padding:2rem;color:var(--t3);font-size:13px"><i class="ti ti-loader-2" style="font-size:18px;animation:spin 1s linear infinite"></i> Loading…</div>`;
  const res = await UFCL.machinesList(STORAGE.user.id);
  if (!res.ok) return renderDenied('machines', res.error);

  const rows = res.rows || [];
  const categories = res.categories || [];
  const workshops = res.workshops || [];
  const canManageCats = ['admin', 'ceo', 'operations', 'logistics'].includes(STORAGE.user?.role);
  const canRegister   = ['admin', 'ceo', 'logistics'].includes(STORAGE.user?.role);

  const statusCls = s => ({ Available:'bg', Running:'bb', Maintenance:'ba', Breakdown:'br' }[s] || 'bt');
  const byStatus = s => rows.filter(r => r.status === s).length;

  const catOpts = categories.map(c => `<option value="${c.id}">${c.name}</option>`).join('');

  // Phase 2 — enterprise table toolkit (search/filter/sort/bulk), reused
  // from the Procurement/Logistics pages rather than a new implementation.
  const mchState = { search: '', status: '', selected: new Set() };
  const mchSort = { key: null, dir: 'asc' };
  function mchFiltered() {
    return applyProcListFilters(rows, {
      search: mchState.search, searchFields: ['machine_code', 'name', 'plate_number', 'category_name', 'workshop_name'],
      status: mchState.status, statusField: 'status',
    });
  }

  $('page-machines').innerHTML = `
    <style>@keyframes spin{to{transform:rotate(360deg)}}</style>
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;margin-bottom:1.5rem">
      <div>
        <div class="ptitle">Machine Registry</div>
        <div class="psub">Manage machine profiles, specifications, operational status, and maintenance schedules.</div>
      </div>
      ${(canManageCats || canRegister) ? `
        <div style="display:flex;gap:.5rem;flex-shrink:0">
          ${canManageCats ? `<button class="bs1" id="mchManageCats" style="white-space:nowrap"><i class="ti ti-tag"></i>Manage categories</button>` : ''}
          ${canRegister ? `<button class="bp1" id="mchAdd" style="white-space:nowrap"><i class="ti ti-plus"></i>Register machine</button>` : ''}
        </div>` : ''}
    </div>
    <div class="cards" style="margin-bottom:1.25rem">
      <div class="mc"><div class="mclbl">Total Machines</div><div class="mcval">${rows.length}</div><div class="mcsub cg"><i class="ti ti-settings-2"></i>registered</div></div>
      <div class="mc"><div class="mclbl">Available</div><div class="mcval">${byStatus('Available')}</div><div class="mcsub cg"><i class="ti ti-circle-check"></i>ready</div></div>
      <div class="mc"><div class="mclbl">Running</div><div class="mcval">${byStatus('Running')}</div><div class="mcsub bp"><i class="ti ti-player-play"></i>active</div></div>
      <div class="mc"><div class="mclbl">Maintenance / Breakdown</div><div class="mcval" style="${(byStatus('Maintenance')+byStatus('Breakdown'))>0?'color:var(--amber)':''}">${byStatus('Maintenance')+byStatus('Breakdown')}</div><div class="mcsub ca"><i class="ti ti-tool"></i>offline</div></div>
    </div>
    ${procFilterBarHtml({
      searchId: 'mch-search', searchPlaceholder: 'Search code, name, plate, category, workshop…',
      statusId: 'mch-status-filter', statusOptions: ['Available', 'Running', 'Maintenance', 'Breakdown'],
      clearId: 'mch-clear',
    })}
    ${canRegister ? `<div id="mch-bulk-bar" class="bulk-bar" style="display:none">
      <span id="mch-bulk-count">0 selected</span>
      <select id="mch-bulk-status" class="filter-select" style="margin-left:.75rem">
        <option value="">Set status to…</option>
        ${['Available','Running','Maintenance','Breakdown'].map(s=>`<option value="${s}">${s}</option>`).join('')}
      </select>
      <button type="button" class="bs1" id="mch-bulk-apply">Apply</button>
      <button type="button" class="bs1" id="mch-bulk-clear" style="margin-left:auto">Clear selection</button>
    </div>` : ''}
    <div class="card" style="padding:0">
      <div style="display:flex;align-items:center;justify-content:space-between;padding:1rem 1.25rem;border-bottom:1px solid var(--bdr)">
        <h3 style="margin:0"><i class="ti ti-settings-2"></i>Machine register</h3>
        <span id="mch-count-label" style="font-size:12px;color:var(--t3)">${rows.length} machine${rows.length!==1?'s':''}</span>
      </div>
      <div class="tw"><table class="tbl" id="mch-table">
        <thead><tr>
          ${canRegister ? '<th style="width:28px"><input type="checkbox" id="mch-select-all"></th>' : ''}
          <th data-sort-key="machine_code">Code</th><th data-sort-key="name">Name</th>
          <th data-sort-key="plate_number">Plate/Fleet No.</th><th data-sort-key="category_name">Category</th>
          <th data-sort-key="workshop_name">Workshop</th><th data-sort-key="status">Status</th>
          <th data-sort-key="production_capacity">Capacity</th><th data-sort-key="fuel_consumption_rate">Fuel Rate</th>
          <th data-sort-key="next_maintenance">Next Maintenance</th><th>Actions</th>
        </tr></thead>
        <tbody id="mch-tbody"></tbody>
      </table></div>
    </div>`;

  function renderMchRows(list) {
    const tbody = $('mch-tbody');
    const cols = (canRegister ? 1 : 0) + 10;
    if (!list.length) {
      tbody.innerHTML = `<tr><td colspan="${cols}" style="text-align:center;color:var(--t3);padding:3rem"><i class="ti ti-settings-2" style="font-size:2rem;display:block;margin-bottom:.5rem;opacity:.35"></i>No machines match these filters.</td></tr>`;
      $('mch-count-label').textContent = '0 machines';
      return;
    }
    $('mch-count-label').textContent = `${list.length} machine${list.length!==1?'s':''}`;
    tbody.innerHTML = list.map(r => `<tr>
      ${canRegister ? `<td onclick="event.stopPropagation()"><input type="checkbox" class="mch-chk" data-id="${r.id}" ${mchState.selected.has(String(r.id))?'checked':''}></td>` : ''}
      <td style="font-family:var(--fm);font-weight:600">${r.machine_code}</td>
      <td style="font-weight:500">${r.name}</td>
      <td style="font-family:var(--fm);color:var(--g-dark)">${r.plate_number || '—'}</td>
      <td><span class="badge bt">${r.category_name}</span></td>
      <td style="font-size:12px;color:var(--g-soft)">${r.workshop_name||'<span style="color:var(--t3)">Unassigned</span>'}</td>
      <td><span class="badge ${statusCls(r.status)}">${r.status}</span></td>
      <td style="font-family:var(--fm)">${r.production_capacity ? Number(r.production_capacity).toLocaleString()+' '+r.capacity_unit+'/day' : '—'}</td>
      <td style="font-family:var(--fm)">${r.fuel_consumption_rate ? Number(r.fuel_consumption_rate)+' L/hr' : '—'}</td>
      <td style="${r.next_maintenance && new Date(r.next_maintenance) <= new Date() ? 'color:var(--red);font-weight:600' : 'color:var(--t3)'}">
        ${r.next_maintenance ? new Date(r.next_maintenance).toLocaleDateString('en-GB') : '—'}
      </td>
      <td style="white-space:nowrap">
        <button class="bs1 mch-view" data-id="${r.id}" title="View details" aria-label="View details for ${r.machine_code}"><i class="ti ti-eye"></i></button>
        ${canRegister ? `<button class="bs1 mch-edit" data-id="${r.id}" aria-label="Edit ${r.machine_code}" style="margin-left:4px"><i class="ti ti-edit"></i></button>
        <button class="bs1 mch-maint" data-id="${r.id}" title="Maintenance schedules" aria-label="Maintenance schedules for ${r.machine_code}" style="margin-left:4px"><i class="ti ti-calendar"></i></button>
        <button class="bs1 mch-archive" data-id="${r.id}" data-name="${r.name}" title="Archive machine" aria-label="Archive ${r.machine_code}" style="margin-left:4px;color:var(--red)"><i class="ti ti-archive"></i></button>` : ''}
      </td>
    </tr>`).join('');
    wireMchRowActions();
  }

  function wireMchRowActions() {
    document.querySelectorAll('.mch-chk').forEach(chk => {
      chk.onchange = () => {
        const id = chk.dataset.id;
        if (chk.checked) mchState.selected.add(id); else mchState.selected.delete(id);
        updateMchBulkBar();
      };
    });
    document.querySelectorAll('.mch-view').forEach(btn => {
      btn.onclick = () => { const r = rows.find(x=>String(x.id)===btn.dataset.id); if (r) openMachineDetailOverlay(r); };
    });
    document.querySelectorAll('.mch-edit').forEach(btn => { btn.onclick = () => openMachineEditOverlay(btn.dataset.id); });
    document.querySelectorAll('.mch-maint').forEach(btn => { btn.onclick = () => openMachineMaintOverlay(btn.dataset.id); });
    // Stabilization Phase 5 (F-19) — machinesDelete (a soft-deactivate,
    // active=false) has existed in the backend/IPC layer with no UI caller
    // on either platform; machines could never be archived once retired.
    document.querySelectorAll('.mch-archive').forEach(btn => {
      btn.onclick = () => {
        const id = btn.dataset.id;
        confirmAction({
          title: 'Archive Machine',
          message: `Archive "${btn.dataset.name}"? It will be removed from the active machine registry and its logs/history are preserved, but there is currently no way to reactivate it from this screen — this cannot be undone without direct database access.`,
          confirmLabel: 'Archive',
          danger: true,
          icon: 'ti-archive',
          onConfirm: async () => {
            const res = await UFCL.machinesDelete(STORAGE.user.id, Number(id));
            if (handleGovernanceResult(res)) return;
            showOverlaySuccess('Machine archived.');
            await renderMachines();
          },
        });
      };
    });
  }

  function updateMchBulkBar() {
    if (!canRegister) return;
    const n = mchState.selected.size;
    $('mch-bulk-bar').style.display = n > 0 ? 'flex' : 'none';
    $('mch-bulk-count').textContent = `${n} selected`;
  }

  function machineForm(r) {
    const catSel = `<option value="">— Select category —</option>` +
      categories.map(c => `<option value="${c.id}" ${r&&Number(r.category_id)===c.id?'selected':''}>${c.name}</option>`).join('');
    const statusOpts = ['Available','Running','Maintenance','Breakdown'].map(s => `<option value="${s}" ${r&&r.status===s?'selected':''}>${s}</option>`).join('');
    const wshOpts = workshops.map(w => `<option value="${w.id}" ${r&&Number(r.workshop_id)===w.id?'selected':''}>${w.name}${w.workshop_type?' ('+w.workshop_type+')':''}</option>`).join('');
    return `
      <div class="frow">
        <div class="fg"><label>Machine Code *</label><input id="mch-code" type="text" value="${r?r.machine_code:''}" placeholder="e.g. SW-001" ${r?'readonly':''}></div>
        <div class="fg"><label>Name *</label><input id="mch-name" type="text" value="${r?r.name:''}" placeholder="Machine name"></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Category *</label><select id="mch-cat">${catSel}</select></div>
        <div class="fg"><label>Assigned Workshop</label><select id="mch-workshop"><option value="">— Unassigned —</option>${wshOpts}</select></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Status</label><select id="mch-status">${statusOpts}</select></div>
        <div class="fg"><label>Plate / Fleet Number</label><input id="mch-plate" type="text" value="${r?r.plate_number||'':''}" placeholder="e.g. RAA 001A or FL-003"></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Production Capacity (per day)</label><input id="mch-cap" type="number" min="0" value="${r?r.production_capacity:0}"></div>
        <div class="fg"><label>Capacity Unit</label><input id="mch-capunit" type="text" value="${r?r.capacity_unit:'m³'}" placeholder="m³"></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Fuel Consumption (L/hr)</label><input id="mch-fuel" type="number" min="0" step="0.1" value="${r?r.fuel_consumption_rate:0}"></div>
        <div class="fg"><label>Fuel Type</label><select id="mch-fueltype"><option value="">— Select fuel type —</option>${['Diesel','Petroleum/Essence','DAT','Petrol','Chain Oil','Engine Oil'].map(f=>`<option value="${f}" ${r&&r.fuel_type===f?'selected':''}>${f}</option>`).join('')}</select></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Manufacturer</label><input id="mch-mfg" type="text" value="${r?r.manufacturer||'':''}"></div>
        <div class="fg"><label>Model</label><input id="mch-model" type="text" value="${r?r.model_number||'':''}"></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Serial Number</label><input id="mch-serial" type="text" value="${r?r.serial_number||'':''}"></div>
        <div class="fg"><label>Year Manufactured</label><input id="mch-year" type="number" min="1900" max="2099" value="${r&&r.year_manufactured?r.year_manufactured:''}"></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Date Acquired</label><input id="mch-acquired" type="date" value="${r&&r.date_acquired?String(r.date_acquired).slice(0,10):''}"></div>
        <div class="fg"><label>Notes</label><input id="mch-notes" type="text" value="${r?r.notes||'':''}"></div>
      </div>
      <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Save</button><button class="bs1" id="ovCancel">Cancel</button></div>`;
  }

  // Note: canRegister/canManageCats individually gate each button below via
  // $('mchAdd')/$('mchManageCats') null-checks (those elements only exist in
  // the DOM when the corresponding permission is true) — no outer gate
  // needed, and the view-only detail overlay below must stay reachable for
  // every viewer regardless of manage permissions.
  {
    if ($('mchAdd')) $('mchAdd').onclick = () => openOverlay('Register machine', null, machineForm(null), async () => {
      const r2 = await UFCL.machinesCreate(STORAGE.user.id, {
        machine_code: $('mch-code').value.trim(),
        name: $('mch-name').value.trim(),
        category_id: $('mch-cat').value,
        workshop_id: $('mch-workshop').value || null,
        status: $('mch-status').value,
        production_capacity: $('mch-cap').value,
        capacity_unit: $('mch-capunit').value.trim() || 'm³',
        fuel_consumption_rate: $('mch-fuel').value,
        fuel_type: $('mch-fueltype').value.trim(),
        manufacturer: $('mch-mfg').value.trim(),
        model_number: $('mch-model').value.trim(),
        serial_number: $('mch-serial').value.trim(),
        year_manufactured: $('mch-year').value || null,
        date_acquired: $('mch-acquired').value || null,
        plate_number: $('mch-plate').value.trim() || null,
        notes: $('mch-notes').value.trim()
      });
      if (!r2.ok) { showOverlayError(r2.error); return; }
      showOverlaySuccess('Machine registered.');
      await renderMachines();
    });

    if ($('mchManageCats')) $('mchManageCats').onclick = async () => {
      async function loadCats() {
        const res = await UFCL.machineCategoriesList(STORAGE.user.id);
        return res.ok ? (res.rows || []) : [];
      }

      function catRows(cats) {
        return cats.length
          ? cats.map(c => `<tr>
              <td style="font-weight:500">${c.name}</td>
              <td style="color:var(--t3);font-size:12px">${c.description || '—'}</td>
              <td style="white-space:nowrap">
                <button class="bs1 mcat-edit" data-id="${c.id}" data-name="${c.name.replace(/"/g,'&quot;')}" data-desc="${(c.description||'').replace(/"/g,'&quot;')}" style="margin-right:4px;padding:4px 8px;font-size:12px"><i class="ti ti-edit"></i>Edit</button>
                <button class="bs1 mcat-del" data-id="${c.id}" data-name="${c.name.replace(/"/g,'&quot;')}" style="color:var(--red);padding:4px 8px;font-size:12px"><i class="ti ti-trash"></i>Delete</button>
              </td>
            </tr>`).join('')
          : `<tr><td colspan="3" style="text-align:center;color:var(--t3);padding:1rem">No categories yet. Add one below.</td></tr>`;
      }

      function bindCatActions() {
        document.querySelectorAll('.mcat-del').forEach(btn => {
          btn.onclick = async () => {
            btn.disabled = true;
            try {
              const r2 = await UFCL.machineCategoriesDelete(STORAGE.user.id, Number(btn.dataset.id));
              if (!r2.ok) { showOverlayError(r2.error); btn.disabled = false; return; }
              await openCatOverlay();
            } catch (e) {
              showOverlayError(e?.message || 'Delete failed');
              btn.disabled = false;
            }
          };
        });

        document.querySelectorAll('.mcat-edit').forEach(btn => {
          btn.onclick = () => {
            const editArea = $('mcat-edit-area');
            if (!editArea) return;
            editArea.innerHTML = `
              <div style="background:var(--bg2);border:1px solid var(--bdr);border-radius:8px;padding:1rem;margin-bottom:1rem">
                <div style="font-weight:600;font-size:13px;margin-bottom:.625rem">Edit category</div>
                <div class="frow" style="gap:.625rem">
                  <div class="fg" style="flex:2"><label>Name *</label><input id="mcat-edit-name" type="text" value="${btn.dataset.name}"></div>
                  <div class="fg" style="flex:3"><label>Description</label><input id="mcat-edit-desc" type="text" value="${btn.dataset.desc}"></div>
                  <button class="bp1" id="mcat-save-btn" data-id="${btn.dataset.id}" style="flex-shrink:0;align-self:flex-end;margin-bottom:0"><i class="ti ti-check"></i>Save</button>
                  <button class="bs1" id="mcat-cancel-edit" style="flex-shrink:0;align-self:flex-end;margin-bottom:0">Cancel</button>
                </div>
              </div>`;
            $('mcat-cancel-edit').onclick = () => { editArea.innerHTML = ''; };
            $('mcat-save-btn').onclick = async () => {
              const catId = Number($('mcat-save-btn').dataset.id);
              const r2 = await UFCL.machineCategoriesUpdate(STORAGE.user.id, catId, {
                name: $('mcat-edit-name').value.trim(),
                description: $('mcat-edit-desc').value.trim()
              });
              if (!r2.ok) { showOverlayError(r2.error); return; }
              editArea.innerHTML = '';
              await openCatOverlay();
            };
          };
        });
      }

      async function openCatOverlay() {
        const cats = await loadCats();
        openOverlay('Manage machine categories', 'Add, rename, or remove categories used when registering machines.', `
          <div class="tw" style="margin-bottom:1.25rem"><table class="dt" style="min-width:0">
            <thead><tr><th>Name</th><th>Description</th><th></th></tr></thead>
            <tbody id="mcat-tbody">${catRows(cats)}</tbody>
          </table></div>
          <div id="mcat-edit-area"></div>
          <div style="border-top:1px solid var(--bdr);padding-top:1rem">
            <div style="font-weight:600;font-size:13px;margin-bottom:.625rem">Add new category</div>
            <div class="frow" style="gap:.625rem">
              <div class="fg" style="flex:2"><label>Category name *</label><input id="mcat-new-name" type="text" placeholder="e.g. Excavator, Bulldozer"></div>
              <div class="fg" style="flex:3"><label>Description</label><input id="mcat-new-desc" type="text" placeholder="Optional description"></div>
              <button class="bp1" id="mcat-add-btn" style="flex-shrink:0;align-self:flex-end;margin-bottom:0"><i class="ti ti-plus"></i>Add</button>
            </div>
          </div>
          <div class="brow"><button class="bs1" id="ovCancel">Close</button></div>`,
          async () => {}
        );
        $('mcat-add-btn').onclick = async () => {
          const name = $('mcat-new-name').value.trim();
          if (!name) { showOverlayError('Category name is required'); return; }
          const r2 = await UFCL.machineCategoriesCreate(STORAGE.user.id, {
            name,
            description: $('mcat-new-desc').value.trim() || null
          });
          if (!r2.ok) { showOverlayError(r2.error); return; }
          $('mcat-new-name').value = '';
          $('mcat-new-desc').value = '';
          await openCatOverlay();
        };
        bindCatActions();
        renderMachines();
      }

      await openCatOverlay();
    };

    function openMachineEditOverlay(idStr) {
      const row = rows.find(r => String(r.id) === String(idStr));
      if (!row) return;
      openOverlay('Edit machine', row.machine_code + ' — ' + row.name, machineForm(row), async () => {
        const r2 = await UFCL.machinesUpdate(STORAGE.user.id, row.id, {
          name: $('mch-name').value.trim(),
          category_id: $('mch-cat').value,
          workshop_id: $('mch-workshop').value || null,
          status: $('mch-status').value,
          production_capacity: $('mch-cap').value,
          capacity_unit: $('mch-capunit').value.trim() || 'm³',
          fuel_consumption_rate: $('mch-fuel').value,
          fuel_type: $('mch-fueltype').value.trim(),
          manufacturer: $('mch-mfg').value.trim(),
          model_number: $('mch-model').value.trim(),
          serial_number: $('mch-serial').value.trim(),
          year_manufactured: $('mch-year').value || null,
          date_acquired: $('mch-acquired').value || null,
          plate_number: $('mch-plate').value.trim() || null,
          notes: $('mch-notes').value.trim()
        });
        // Fleet & Equipment Phase 1 — machinesUpdate is governed and can
        // return a pendingApproval response with no .error field; the plain
        // showOverlayError(r2.error) here would have shown "undefined".
        if (handleGovernanceResult(r2)) return;
        showOverlaySuccess('Machine updated.');
        await renderMachines();
      });
    }

    async function openMachineMaintOverlay(idStr) {
      const row = rows.find(r => String(r.id) === String(idStr));
      if (!row) return;
      const mr = await UFCL.machineMaintList(STORAGE.user.id, row.id);
      const schedules = mr.ok ? (mr.rows || []) : [];
      const schedHtml = schedules.length
        ? schedules.map(s => `<tr>
            <td style="font-weight:500">${s.maintenance_type}</td>
            <td>${s.frequency_days}d</td>
            <td>${s.last_performed ? new Date(s.last_performed).toLocaleDateString('en-GB') : '—'}</td>
            <td style="${s.next_due && new Date(s.next_due)<=new Date()?'color:var(--red);font-weight:600':''}">${s.next_due ? new Date(s.next_due).toLocaleDateString('en-GB') : '—'}</td>
            <td>${s.estimated_hours}h</td>
            <td style="white-space:nowrap">
              <button class="bs1 ms-edit" data-id="${s.id}" style="padding:3px 7px;font-size:12px"><i class="ti ti-edit"></i></button>
              <button class="bs1 ms-del" data-id="${s.id}" style="padding:3px 7px;font-size:12px;color:var(--red)"><i class="ti ti-trash"></i></button>
            </td>
          </tr>`).join('')
        : `<tr><td colspan="6" style="text-align:center;color:var(--t3);padding:1rem">No schedules defined yet.</td></tr>`;
      openOverlay('Maintenance schedules', row.machine_code + ' — ' + row.name, `
        <div class="tw" style="margin-bottom:1rem"><table class="dt">
          <thead><tr><th>Type</th><th>Frequency</th><th>Last done</th><th>Next due</th><th>Est. hrs</th><th></th></tr></thead>
          <tbody>${schedHtml}</tbody>
        </table></div>
        <div id="ms-edit-area"></div>
        <div style="border-top:1px solid var(--bdr);padding-top:1rem;margin-top:.5rem">
          <div style="font-weight:600;font-size:13px;margin-bottom:.75rem">Add new schedule</div>
          <div class="frow">
            <div class="fg"><label>Type *</label><input id="ms-type" type="text" placeholder="e.g. Oil Change"></div>
            <div class="fg"><label>Frequency (days)</label><input id="ms-freq" type="number" min="1" value="30"></div>
          </div>
          <div class="frow">
            <div class="fg"><label>Last Performed</label><input id="ms-last" type="date"></div>
            <div class="fg"><label>Next Due</label><input id="ms-next" type="date"></div>
          </div>
          <div class="frow">
            <div class="fg"><label>Est. Hours</label><input id="ms-hours" type="number" min="0.5" step="0.5" value="1"></div>
            <div class="fg"><label>Notes</label><input id="ms-notes" type="text"></div>
          </div>
        </div>
        <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-plus"></i>Add schedule</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
        async () => {
          const r2 = await UFCL.machineMaintCreate(STORAGE.user.id, {
            machine_id: row.id,
            maintenance_type: $('ms-type').value.trim(),
            frequency_days: $('ms-freq').value || 30,
            last_performed: $('ms-last').value || null,
            next_due: $('ms-next').value || null,
            estimated_hours: $('ms-hours').value || 1,
            notes: $('ms-notes').value.trim()
          });
          if (!r2.ok) { showOverlayError(r2.error); return; }
          showOverlaySuccess('Schedule added.');
          await renderMachines();
        });
      setTimeout(() => {
        document.querySelectorAll('.ms-del').forEach(btn => {
          btn.onclick = () => {
            confirmDelete('Delete this maintenance schedule entry?', async () => {
              const r2 = await UFCL.machineMaintDelete(STORAGE.user.id, Number(btn.dataset.id));
              if (!r2.ok) { showOverlayError(r2.error); return; }
              showOverlaySuccess('Schedule deleted.');
              await openMachineMaintOverlay(idStr);
            });
          };
        });
        document.querySelectorAll('.ms-edit').forEach(btn => {
          btn.onclick = () => {
            const s = schedules.find(x => String(x.id) === btn.dataset.id);
            if (!s) return;
            const editArea = $('ms-edit-area');
            editArea.innerHTML = `
              <div style="background:var(--bg2);border:1px solid var(--bdr);border-radius:8px;padding:1rem;margin-bottom:1rem">
                <div style="font-weight:600;font-size:13px;margin-bottom:.625rem">Edit schedule</div>
                <div class="frow">
                  <div class="fg"><label>Type *</label><input id="mse-type" type="text" value="${s.maintenance_type}"></div>
                  <div class="fg"><label>Frequency (days)</label><input id="mse-freq" type="number" min="1" value="${s.frequency_days}"></div>
                </div>
                <div class="frow">
                  <div class="fg"><label>Last Performed</label><input id="mse-last" type="date" value="${s.last_performed?String(s.last_performed).slice(0,10):''}"></div>
                  <div class="fg"><label>Next Due</label><input id="mse-next" type="date" value="${s.next_due?String(s.next_due).slice(0,10):''}"></div>
                </div>
                <div class="frow">
                  <div class="fg"><label>Est. Hours</label><input id="mse-hours" type="number" min="0.5" step="0.5" value="${s.estimated_hours}"></div>
                  <div class="fg"><label>Notes</label><input id="mse-notes" type="text" value="${s.notes||''}"></div>
                </div>
                <div class="brow"><button class="bp1" id="mse-save">Save</button><button class="bs1" id="mse-cancel">Cancel</button></div>
              </div>`;
            $('mse-cancel').onclick = () => { editArea.innerHTML = ''; };
            $('mse-save').onclick = async () => {
              const r2 = await UFCL.machineMaintUpdate(STORAGE.user.id, s.id, {
                maintenance_type: $('mse-type').value.trim(),
                frequency_days: $('mse-freq').value || 30,
                last_performed: $('mse-last').value || null,
                next_due: $('mse-next').value || null,
                estimated_hours: $('mse-hours').value || 1,
                notes: $('mse-notes').value.trim()
              });
              if (!r2.ok) { showOverlayError(r2.error); return; }
              showOverlaySuccess('Schedule updated.');
              await openMachineMaintOverlay(idStr);
            };
          };
        });
      }, 30);
    }

    // Phase 2 — detail overlay: machine info + maintenance schedule summary +
    // audit history + quick actions, mirroring the Logistics detail-overlay
    // template.
    function openMachineDetailOverlay(r) {
      openOverlay('Machine', r.machine_code + ' — ' + r.name, `
        <div class="frow" style="margin-bottom:10px">${statusCls(r.status)?`<span class="badge ${statusCls(r.status)}">${r.status}</span>`:''} <span class="badge bt">${r.category_name}</span></div>
        <div class="card" style="padding:12px 14px;margin-bottom:12px;background:var(--bg2)">
          <div class="frow" style="flex-wrap:wrap;gap:1.25rem;font-size:13px">
            <div><strong>Plate/Fleet No.</strong><br>${r.plate_number||'—'}</div>
            <div><strong>Workshop</strong><br>${r.workshop_name||'Unassigned'}</div>
            <div><strong>Capacity</strong><br>${r.production_capacity?Number(r.production_capacity).toLocaleString()+' '+r.capacity_unit+'/day':'—'}</div>
            <div><strong>Fuel rate</strong><br>${r.fuel_consumption_rate?Number(r.fuel_consumption_rate)+' L/hr':'—'}</div>
            <div><strong>Manufacturer</strong><br>${r.manufacturer||'—'}</div>
            <div><strong>Model</strong><br>${r.model_number||'—'}</div>
            <div><strong>Serial number</strong><br>${r.serial_number||'—'}</div>
            <div><strong>Year</strong><br>${r.year_manufactured||'—'}</div>
            <div><strong>Next maintenance</strong><br><span style="${r.next_maintenance && new Date(r.next_maintenance)<=new Date()?'color:var(--red);font-weight:600':''}">${r.next_maintenance?new Date(r.next_maintenance).toLocaleDateString('en-GB'):'—'}</span></div>
          </div>
          ${r.notes ? `<div style="margin-top:8px;font-size:13px"><strong>Notes:</strong> ${r.notes}</div>` : ''}
        </div>
        <div style="font-size:12px;font-weight:700;color:var(--t3);margin-bottom:6px;text-transform:uppercase;letter-spacing:.03em">History</div>
        <div id="mch-detail-history" style="margin-bottom:14px"></div>
        <div class="brow">
          <button class="bs1" id="mchd-maint"><i class="ti ti-calendar"></i>Maintenance schedules</button>
          ${canRegister ? `<button class="bs1" id="mchd-edit"><i class="ti ti-edit"></i>Edit</button>` : ''}
          <button class="bs1" id="ovCancel">Close</button>
        </div>`, null);
      _loadLogisticsHistoryInto('mch-detail-history', 'machines', r.id);
      setTimeout(() => {
        const mt = $('mchd-maint'); if (mt) mt.onclick = () => { closeOverlay(); openMachineMaintOverlay(r.id); };
        const ed = $('mchd-edit'); if (ed) ed.onclick = () => { closeOverlay(); openMachineEditOverlay(r.id); };
      }, 30);
    }

    renderMchRows(mchFiltered());
    wireSortableTable($('mch-table'), mchSort, mchFiltered, renderMchRows);
    $('mch-search').oninput = (e) => { mchState.search = e.target.value; renderMchRows(mchFiltered()); };
    $('mch-status-filter').onchange = (e) => { mchState.status = e.target.value; renderMchRows(mchFiltered()); };
    $('mch-clear').onclick = () => { mchState.search=''; mchState.status=''; $('mch-search').value=''; $('mch-status-filter').value=''; renderMchRows(mchFiltered()); };
    if (canRegister) {
      $('mch-select-all').onchange = (e) => {
        const list = mchFiltered();
        if (e.target.checked) list.forEach(r => mchState.selected.add(String(r.id)));
        else list.forEach(r => mchState.selected.delete(String(r.id)));
        renderMchRows(list);
        updateMchBulkBar();
      };
      $('mch-bulk-clear').onclick = () => { mchState.selected.clear(); renderMchRows(mchFiltered()); updateMchBulkBar(); };
      $('mch-bulk-apply').onclick = async () => {
        const status = $('mch-bulk-status').value;
        if (!status) { showToast('Choose a status first.', 'error'); return; }
        const ids = Array.from(mchState.selected);
        let okCount = 0;
        for (const id of ids) {
          const row = rows.find(x => String(x.id) === id);
          if (!row) continue;
          const r2 = await UFCL.machinesUpdate(STORAGE.user.id, row.id, {
            name: row.name, category_id: row.category_id, workshop_id: row.workshop_id || null,
            status, production_capacity: row.production_capacity, capacity_unit: row.capacity_unit,
            fuel_consumption_rate: row.fuel_consumption_rate, fuel_type: row.fuel_type || '',
            manufacturer: row.manufacturer || '', model_number: row.model_number || '',
            serial_number: row.serial_number || '', year_manufactured: row.year_manufactured || null,
            date_acquired: row.date_acquired || null, plate_number: row.plate_number || '', notes: row.notes || '',
          });
          if (r2.ok) okCount++;
        }
        showToast(`${okCount} machine${okCount!==1?'s':''} updated.`, 'success');
        mchState.selected.clear();
        await renderMachines();
      };
    }
  }
}

// ── Machine Daily Logs ────────────────────────────────────────────────────────

async function renderMachineLogs(cid = 'page-machine-logs', selectedMonth = null) {
  $(cid).innerHTML = `<div style="padding:2rem;color:var(--t3);font-size:13px"><i class="ti ti-loader-2" style="font-size:18px;animation:spin 1s linear infinite"></i> Loading…</div>`;

  const today = new Date();
  const currentMonth = today.toISOString().slice(0, 7);

  // Build last 24 months for the picker
  const monthOpts = (() => {
    const opts = [`<option value="">All time</option>`];
    for (let i = 0; i < 24; i++) {
      const d = new Date(today.getFullYear(), today.getMonth() - i, 1);
      const val = d.toISOString().slice(0, 7);
      const lbl = d.toLocaleString('en-GB', { month: 'long', year: 'numeric' });
      opts.push(`<option value="${val}" ${selectedMonth === val ? 'selected' : ''}>${lbl}</option>`);
    }
    return opts.join('');
  })();

  const res = await UFCL.machineLogsList(STORAGE.user.id, null, selectedMonth || null, WORKSHOP_FILTER);
  if (!res.ok) return renderDenied('machine-logs', res.error);

  const rows = res.rows || [];
  const machines = res.machines || [];
  const itemCategories = res.itemCategories || [];
  const canDelete = ['admin', 'operations'].includes(STORAGE.user?.role);
  // P-9 (Stabilization Phase 1) — mechanician holds 'machine-logs' server-side
  // (db/migrate.js, machineLogsCreate's mustRole check) and mobile already
  // permits it; desktop's Add button was the only place excluding it.
  const canAdd = ['admin', 'operations', 'supervisor', 'mechanician'].includes(STORAGE.user?.role);
  const canManageCats = ['admin', 'operations', 'supervisor'].includes(STORAGE.user?.role);

  const totalHours = rows.reduce((s, r) => s + Number(r.hours_worked), 0);
  const totalDowntime = rows.reduce((s, r) => s + Number(r.downtime_hours), 0);
  const totalProduction = rows.reduce((s, r) => s + Number(r.daily_production), 0);
  const totalCapacity = rows.reduce((s, r) => s + Number(r.capacity_per_day), 0);
  const avgEfficiency = totalCapacity > 0 ? Math.round((totalProduction / totalCapacity) * 100) : 0;
  const periodLabel = selectedMonth
    ? new Date(selectedMonth + '-02').toLocaleString('en-GB', { month: 'long', year: 'numeric' })
    : 'All time';

  // Phase 2 — enterprise table toolkit layered on top of the existing
  // month picker (month narrows the server query; search/status are
  // client-side over that already-fetched period, same convention as
  // every other Phase-2-upgraded page).
  const mlState = { search: '', status: '' };
  const mlSort = { key: null, dir: 'asc' };
  rows.forEach(r => {
    const eff = Number(r.capacity_per_day) > 0 ? Math.round((Number(r.daily_production) / Number(r.capacity_per_day)) * 100) : null;
    r._effLabel = eff === null ? 'No target' : eff >= 90 ? 'On target' : eff >= 70 ? 'Below target' : 'Underperforming';
  });
  function mlFiltered() {
    return applyProcListFilters(rows, {
      search: mlState.search, searchFields: ['machine_code', 'machine_name', 'category_name', 'item_category', 'shift'],
      status: mlState.status, statusField: '_effLabel',
    });
  }

  $(cid).innerHTML = `
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;margin-bottom:1.5rem">
      <div>
        <div class="ptitle">Machine Daily Logs</div>
        <div class="psub">Log daily production, hours worked, downtime, fuel consumption, and item category for each machine.</div>
      </div>
      <div style="display:flex;gap:.5rem;flex-shrink:0;align-items:center">
        <select id="mlMonthFilter" style="font-size:13px;padding:6px 10px;border:1px solid var(--bdr);border-radius:6px;background:var(--bg);color:var(--t1);cursor:pointer">${monthOpts}</select>
        ${canManageCats ? `<button class="bs1" id="mlManageCats"><i class="ti ti-tag"></i>Categories</button>` : ''}
        ${canAdd ? `<button class="bp1" id="mlAdd"><i class="ti ti-plus"></i>Add log entry</button>` : ''}
      </div>
    </div>
    <div class="cards" style="margin-bottom:1.25rem">
      <div class="mc"><div class="mclbl">Entries — ${periodLabel}</div><div class="mcval">${rows.length}</div><div class="mcsub cg"><i class="ti ti-list-details"></i>${rows.length} record${rows.length!==1?'s':''}</div></div>
      <div class="mc"><div class="mclbl">Total Hours Worked</div><div class="mcval">${totalHours.toFixed(1)}</div><div class="mcsub cg"><i class="ti ti-clock"></i>productive hrs</div></div>
      <div class="mc"><div class="mclbl">Total Downtime</div><div class="mcval" style="${totalDowntime>0?'color:var(--amber)':''}">${totalDowntime.toFixed(1)}</div><div class="mcsub ca"><i class="ti ti-clock-x"></i>hrs</div></div>
      <div class="mc"><div class="mclbl">Avg Efficiency</div><div class="mcval" style="${avgEfficiency<75?'color:var(--amber)':'color:var(--green)'}">${avgEfficiency}%</div><div class="mcsub ${avgEfficiency>=75?'cg':'ca'}"><i class="ti ti-chart-line"></i>production vs capacity</div></div>
    </div>
    ${procFilterBarHtml({
      searchId: 'ml-search', searchPlaceholder: 'Search machine, category, shift…',
      statusId: 'ml-status-filter', statusOptions: ['On target', 'Below target', 'Underperforming', 'No target'],
      clearId: 'ml-clear',
    })}
    <div class="card" style="padding:0">
      <div style="display:flex;align-items:center;justify-content:space-between;padding:1rem 1.25rem;border-bottom:1px solid var(--bdr)">
        <h3 style="margin:0"><i class="ti ti-list-details"></i>Log entries — ${periodLabel}</h3>
        <span id="ml-count-label" style="font-size:12px;color:var(--t3)">${rows.length} entr${rows.length!==1?'ies':'y'}</span>
      </div>
      <div class="tw"><table class="tbl" id="ml-table">
        <thead><tr>
          <th data-sort-key="log_date">Date</th><th data-sort-key="machine_code">Machine</th>
          <th data-sort-key="category_name">Machine Cat.</th><th data-sort-key="item_category">Item Category</th>
          <th data-sort-key="shift">Shift</th><th data-sort-key="hours_worked">Hrs Worked</th>
          <th data-sort-key="downtime_hours">Downtime</th><th data-sort-key="daily_production">Production</th>
          <th data-sort-key="capacity_per_day">Capacity</th><th>Efficiency</th>
          <th data-sort-key="fuel_issued">Fuel Issued (L)</th><th data-sort-key="fuel_consumed">Fuel Consumed (L)</th>
          <th>Variance</th><th>Actions</th>
        </tr></thead>
        <tbody id="ml-tbody"></tbody>
      </table></div>
    </div>`;

  function renderMlRows(list) {
    const tbody = $('ml-tbody');
    if (!list.length) {
      tbody.innerHTML = `<tr><td colspan="14" style="text-align:center;color:var(--t3);padding:3rem"><i class="ti ti-list-details" style="font-size:2rem;display:block;margin-bottom:.5rem;opacity:.35"></i>No log entries match these filters.</td></tr>`;
      $('ml-count-label').textContent = '0 entries';
      return;
    }
    $('ml-count-label').textContent = `${list.length} entr${list.length!==1?'ies':'y'}`;
    tbody.innerHTML = list.map(r => {
      const eff = Number(r.capacity_per_day) > 0
        ? Math.round((Number(r.daily_production) / Number(r.capacity_per_day)) * 100)
        : null;
      const effCol = eff === null ? 'color:var(--t3)' : eff >= 90 ? 'color:var(--green);font-weight:600' : eff >= 70 ? 'color:var(--amber)' : 'color:var(--red);font-weight:600';
      const fIssued   = Number(r.fuel_issued   || 0);
      const fConsumed = Number(r.fuel_consumed  || 0);
      const fVar      = fIssued - fConsumed;
      const fVarCol   = Math.abs(fVar) < 0.05 ? 'color:var(--green)' : fVar > 0 ? 'color:var(--amber)' : 'color:var(--red)';
      const fVarTxt   = fIssued === 0 && fConsumed === 0 ? '—' : (fVar > 0 ? '+' : '') + fVar.toFixed(1);
      return `<tr>
        <td>${new Date(r.log_date+'T12:00:00').toLocaleDateString('en-GB')}${r.pending_deletion ? ' <span class="badge br" style="font-size:10px;vertical-align:middle">Pending Deletion</span>' : ''}</td>
        <td style="font-weight:500">${r.machine_code} — ${r.machine_name}</td>
        <td><span class="badge bt">${r.category_name}</span></td>
        <td>${r.item_category ? `<span class="badge bg" style="font-size:11px">${r.item_category}</span>` : '<span style="color:var(--t3)">—</span>'}</td>
        <td>${r.shift}</td>
        <td style="font-family:var(--fm)">${Number(r.hours_worked).toFixed(1)}</td>
        <td style="font-family:var(--fm);${Number(r.downtime_hours)>0?'color:var(--amber)':''}">${Number(r.downtime_hours).toFixed(1)}</td>
        <td style="font-family:var(--fm)">${Number(r.daily_production) > 0 ? Number(r.daily_production).toLocaleString() : '—'}</td>
        <td style="font-family:var(--fm);color:var(--t3)">${Number(r.capacity_per_day) > 0 ? Number(r.capacity_per_day).toLocaleString() : '—'}</td>
        <td style="font-family:var(--fm);${effCol}">${eff !== null ? eff+'%' : '—'}</td>
        <td style="font-family:var(--fm);color:var(--t3)">${fIssued > 0 ? fIssued.toFixed(1) : '—'}</td>
        <td style="font-family:var(--fm);font-weight:${fConsumed>0?'600':'400'}">${fConsumed > 0 ? fConsumed.toFixed(1) : '—'}</td>
        <td style="font-family:var(--fm);${fVarCol};font-size:12px">${fVarTxt}</td>
        <td style="white-space:nowrap">
          <button class="bs1 ml-view" data-id="${r.id}" title="View details"><i class="ti ti-eye"></i></button>
          ${canDelete ? `<button class="bs1 ml-edit" data-id="${r.id}" style="margin-left:4px"><i class="ti ti-edit"></i></button>
          <button class="bs1 ml-del" data-id="${r.id}" style="color:var(--red);margin-left:4px"><i class="ti ti-trash"></i></button>` : ''}
        </td>
      </tr>`;
    }).join('');
    wireMlRowActions();
  }

  function wireMlRowActions() {
    document.querySelectorAll('.ml-view').forEach(btn => {
      btn.onclick = () => { const r = rows.find(x=>String(x.id)===btn.dataset.id); if (r) openMachineLogDetailOverlay(r); };
    });
    document.querySelectorAll('.ml-edit').forEach(btn => { btn.onclick = () => openMachineLogEditOverlay(btn.dataset.id); });
    document.querySelectorAll('.ml-del').forEach(btn => { btn.onclick = () => deleteMachineLog(btn.dataset.id); });
  }

  document.getElementById('mlMonthFilter')?.addEventListener('change', e => {
    renderMachineLogs(cid, e.target.value || null);
  });

  function logForm(r) {
    const mOpts = machines.map(m => `<option value="${m.id}" ${r&&r.machine_id===m.id?'selected':''}>${m.machine_code} — ${m.name} (${m.category_name})</option>`).join('');
    const sOpts = ['Full Day','Day Shift','Night Shift'].map(s => `<option ${r&&r.shift===s?'selected':''}>${s}</option>`).join('');
    // Item category: default to the existing value (edit) or first category (new entry)
    const defaultCat = r?.item_category || (itemCategories[0]?.name || '');
    const catOpts = itemCategories.map(c =>
      `<option value="${c.name}" ${(r?r.item_category:defaultCat)===c.name?'selected':''}>${c.name}</option>`
    ).join('');
    return `
      <div class="frow">
        <div class="fg"><label>Machine *</label><select id="ml-machine" ${r?'disabled':''}>${mOpts}</select></div>
        <div class="fg"><label>Date *</label><input id="ml-date" type="date" value="${r?String(r.log_date).slice(0,10):today.toISOString().slice(0,10)}"></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Item Category *</label>
          <select id="ml-cat">
            ${catOpts || '<option value="">No categories yet</option>'}
          </select>
        </div>
        <div class="fg"><label>Shift</label><select id="ml-shift">${sOpts}</select></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Hours Worked</label><input id="ml-hours" type="number" min="0" step="0.25" value="${r?r.hours_worked:0}"></div>
        <div class="fg"><label>Downtime (hrs)</label><input id="ml-dt" type="number" min="0" step="0.25" value="${r?r.downtime_hours:0}"></div>
      </div>
      <div class="fg"><label>Downtime Reason</label><input id="ml-dtr" type="text" value="${r?r.downtime_reason||'':''}" placeholder="Reason if any"></div>
      <div class="frow">
        <div class="fg">
          <label>Fuel Consumed (L) <span id="ml-fuel-hint" style="font-weight:400;color:var(--t3);font-size:11px"></span></label>
          <input id="ml-fuel" type="number" min="0" step="0.1" value="${r?r.fuel_consumed:0}">
        </div>
        <div class="fg">
          <label>Fuel Issued (L) <span style="font-weight:400;color:var(--t3);font-size:11px">— from Fuel Logs</span></label>
          <input id="ml-fuel-issued" type="text" readonly placeholder="Loading…" style="background:var(--bg2);cursor:default">
        </div>
      </div>
      <div class="frow">
        <div class="fg"><label>Daily Production</label><input id="ml-prod" type="number" min="0" step="0.1" value="${r?r.daily_production:0}"></div>
        <div class="fg"><label>Capacity for Day</label><input id="ml-cap" type="number" min="0" step="0.1" value="${r?r.capacity_per_day:0}"></div>
      </div>
      <div class="fg"><label>Product Type</label><input id="ml-ptype" type="text" value="${r?r.product_type||'':''}" placeholder="e.g. Sawn Timber, Poles"></div>
      <div style="font-size:12px;color:var(--t3);font-weight:600;margin-bottom:.5rem;margin-top:.5rem">Log Loader fields <span style="font-weight:400">(fill if applicable)</span></div>
      <div class="frow">
        <div class="fg"><label>Logs Loaded (m³)</label><input id="ml-loaded" type="number" min="0" step="0.1" value="${r?r.logs_loaded:0}"></div>
        <div class="fg"><label>Logs Unloaded (m³)</label><input id="ml-unloaded" type="number" min="0" step="0.1" value="${r?r.logs_unloaded:0}"></div>
        <div class="fg"><label>Loading Trips</label><input id="ml-trips" type="number" min="0" value="${r?r.loading_trips:0}"></div>
      </div>
      <div class="fg"><label>Remarks</label><input id="ml-remarks" type="text" value="${r&&r.remarks?r.remarks:''}" placeholder="Any notes for this shift"></div>
      <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Save</button><button class="bs1" id="ovCancel">Cancel</button></div>`;
  }

  function collectLog() {
    return {
      machine_id: $('ml-machine').value,
      log_date: $('ml-date').value,
      item_category: $('ml-cat')?.value || null,
      shift: $('ml-shift').value,
      hours_worked: $('ml-hours').value,
      downtime_hours: $('ml-dt').value,
      downtime_reason: $('ml-dtr').value.trim() || null,
      daily_production: $('ml-prod').value,
      capacity_per_day: $('ml-cap').value,
      product_type: $('ml-ptype').value.trim() || null,
      fuel_consumed: $('ml-fuel').value,
      logs_loaded: $('ml-loaded').value,
      logs_unloaded: $('ml-unloaded').value,
      loading_trips: $('ml-trips').value,
      remarks: $('ml-remarks').value.trim() || null
    };
  }

  if (canManageCats) {
    $('mlManageCats')?.addEventListener('click', async () => {
      const catRes = await UFCL.machineLogCatsList(STORAGE.user.id);
      const cats = catRes.ok ? (catRes.rows || []) : [];
      const catTableRows = cats.length
        ? cats.map(c => `<tr>
            <td style="font-weight:500">${c.name}</td>
            <td><span class="badge ${c.active?'bg':'br'}">${c.active?'Active':'Inactive'}</span></td>
            <td><button class="bs1 cat-del" data-id="${c.id}" style="color:var(--red);padding:4px 8px;font-size:12px"><i class="ti ti-trash"></i></button></td>
          </tr>`).join('')
        : `<tr><td colspan="3" style="text-align:center;color:var(--t3);padding:1rem">No categories yet.</td></tr>`;

      openOverlay('Manage Item Categories', 'Create and remove item categories used in machine daily logs.', `
        <div class="tw" style="margin-bottom:1.25rem"><table class="dt" style="min-width:0">
          <thead><tr><th>Category name</th><th>Status</th><th></th></tr></thead>
          <tbody id="cat-table-body">${catTableRows}</tbody>
        </table></div>
        <div style="border-top:1px solid var(--bdr);padding-top:1rem">
          <div style="font-weight:600;font-size:13px;margin-bottom:.625rem">Add new category</div>
          <div class="frow" style="align-items:flex-end;gap:.625rem">
            <div class="fg" style="flex:1"><label>Category name *</label><input id="new-cat-name" type="text" placeholder="e.g. Bearings, Filters, Belts"></div>
            <button class="bp1" id="cat-add-btn" style="flex-shrink:0;margin-bottom:0"><i class="ti ti-plus"></i>Add</button>
          </div>
        </div>
        <div class="brow"><button class="bs1" id="ovCancel">Close</button></div>`,
        async () => {}
      );

      // Inline add handler (not using ovSave — it would close the overlay)
      $('cat-add-btn')?.addEventListener('click', async () => {
        const name = $('new-cat-name')?.value?.trim();
        if (!name) { showOverlayError('Category name is required'); return; }
        const r2 = await UFCL.machineLogCatsCreate(STORAGE.user.id, { name });
        if (!r2.ok) { showOverlayError(r2.error); return; }
        // Re-render category list inside overlay
        const updated = await UFCL.machineLogCatsList(STORAGE.user.id);
        const updatedCats = updated.ok ? (updated.rows || []) : [];
        const tbody = $('cat-table-body');
        if (tbody) tbody.innerHTML = updatedCats.map(c => `<tr>
          <td style="font-weight:500">${c.name}</td>
          <td><span class="badge ${c.active?'bg':'br'}">${c.active?'Active':'Inactive'}</span></td>
          <td><button class="bs1 cat-del" data-id="${c.id}" style="color:var(--red);padding:4px 8px;font-size:12px"><i class="ti ti-trash"></i></button></td>
        </tr>`).join('');
        if ($('new-cat-name')) $('new-cat-name').value = '';
        bindCatDelete();
        // Re-render the main page in background so new category is available
        renderMachineLogs(cid, selectedMonth);
      });

      function bindCatDelete() {
        document.querySelectorAll('.cat-del').forEach(btn => {
          btn.onclick = async () => {
            const r2 = await UFCL.machineLogCatsDelete(STORAGE.user.id, Number(btn.dataset.id));
            if (!r2.ok) { showOverlayError(r2.error); return; }
            btn.closest('tr').remove();
            renderMachineLogs(cid, selectedMonth);
          };
        });
      }
      bindCatDelete();
    });
  }

  async function refreshFuelIssued(fixedMachineId) {
    const machId = fixedMachineId || document.getElementById('ml-machine')?.value;
    const date   = document.getElementById('ml-date')?.value;
    const issuedEl = document.getElementById('ml-fuel-issued');
    const hintEl   = document.getElementById('ml-fuel-hint');
    if (!machId || !date || !issuedEl) return;
    const res = await UFCL.machineFuelIssuedLookup(STORAGE.user.id, machId, date);
    const issued = res.ok ? Number(res.issued || 0) : 0;
    issuedEl.value = issued > 0 ? issued.toFixed(1) + ' L' : '— (no Fuel Log entry)';
    if (hintEl) hintEl.textContent = issued > 0 ? `(issued: ${issued.toFixed(1)} L)` : '';
    return issued;
  }

  if (canAdd) {
    $('mlAdd').onclick = () => {
      openOverlay('Add machine log', null, logForm(null), async () => {
        const r2 = await UFCL.machineLogsCreate(STORAGE.user.id, collectLog());
        if (!r2.ok) { showOverlayError(r2.error); return; }
        showOverlaySuccess('Log entry saved.');
        await renderMachineLogs(cid, selectedMonth);
      });
      // Auto-lookup fuel issued when machine or date changes; pre-fill consumed if still 0
      async function onMachDateChange() {
        const issued = await refreshFuelIssued(null);
        const fuelEl = document.getElementById('ml-fuel');
        if (fuelEl && Number(fuelEl.value) === 0 && issued > 0) fuelEl.value = issued.toFixed(1);
      }
      document.getElementById('ml-machine')?.addEventListener('change', onMachDateChange);
      document.getElementById('ml-date')?.addEventListener('change', onMachDateChange);
      onMachDateChange();
    };
  }

  function openMachineLogEditOverlay(idStr) {
    const row = rows.find(r => String(r.id) === String(idStr));
    if (!row) return;
    openOverlay('Edit log entry', row.machine_code + ' · ' + new Date(row.log_date+'T12:00:00').toLocaleDateString('en-GB'), logForm(row), async () => {
      const payload = collectLog();
      if (isSupervisor()) {
        const r2 = await UFCL.pendingEditsCreate(STORAGE.user.id, {
          action_type: 'edit', entity_type: 'machine_daily_log',
          entity_id: row.id, entity_ref: `${row.machine_code} — ${new Date(row.log_date+'T12:00:00').toLocaleDateString('en-GB')}`, payload
        });
        if (!r2.ok) { showOverlayError(r2.error); return; }
        showOverlaySuccess('Change submitted for approval.'); closeOverlay(); await renderMachineLogs(cid, selectedMonth);
      } else {
        const r2 = await UFCL.machineLogsUpdate(STORAGE.user.id, row.id, payload);
        if (!r2.ok) { showOverlayError(r2.error); return; }
        showOverlaySuccess('Log updated.');
        await renderMachineLogs(cid, selectedMonth);
      }
    });
    // Show fuel issued for this machine+date; re-fetch if date is changed
    refreshFuelIssued(row.machine_id);
    document.getElementById('ml-date')?.addEventListener('change', () => refreshFuelIssued(row.machine_id));
  }

  function deleteMachineLog(idStr) {
    const row = rows.find(r => String(r.id) === String(idStr));
    if (!row) return;
    if (isSupervisor()) {
      confirmDeleteSoft(`Submit delete request for log <strong>${row.machine_code}</strong> on ${new Date(row.log_date+'T12:00:00').toLocaleDateString('en-GB')}? A manager must approve before it is moved to Trash.`, async (reason) => {
        const r2 = await UFCL.deletionRequestCreate(STORAGE.user.id, 'machine_daily_logs', row.id, 'machine_daily_log', `${row.machine_code} — ${new Date(row.log_date+'T12:00:00').toLocaleDateString('en-GB')}`, reason);
        if (!r2.ok) { showOverlayError(r2.error); return; }
        showOverlaySuccess('Deletion request submitted for approval.'); await renderMachineLogs(cid, selectedMonth);
      });
    } else {
      confirmDeleteSoft(`Move log for <strong>${row.machine_code}</strong> on ${new Date(row.log_date+'T12:00:00').toLocaleDateString('en-GB')} to Trash?`, async (reason) => {
        const r2 = await UFCL.machineLogsDelete(STORAGE.user.id, row.id, reason);
        if (!r2.ok) { showOverlayError(r2.error); return; }
        showOverlaySuccess('Entry moved to Trash.'); await renderMachineLogs(cid, selectedMonth);
      });
    }
  }

  // Phase 2 — detail overlay: log facts + audit history + quick actions.
  function openMachineLogDetailOverlay(r) {
    openOverlay('Machine log', r.machine_code + ' — ' + new Date(r.log_date+'T12:00:00').toLocaleDateString('en-GB'), `
      <div class="card" style="padding:12px 14px;margin-bottom:12px;background:var(--bg2)">
        <div class="frow" style="flex-wrap:wrap;gap:1.25rem;font-size:13px">
          <div><strong>Machine</strong><br>${r.machine_code} — ${r.machine_name}</div>
          <div><strong>Item category</strong><br>${r.item_category||'—'}</div>
          <div><strong>Shift</strong><br>${r.shift}</div>
          <div><strong>Hours worked</strong><br>${Number(r.hours_worked).toFixed(1)}</div>
          <div><strong>Downtime</strong><br>${Number(r.downtime_hours).toFixed(1)} hrs${r.downtime_reason?' — '+r.downtime_reason:''}</div>
          <div><strong>Production</strong><br>${Number(r.daily_production).toLocaleString()}</div>
          <div><strong>Fuel consumed</strong><br>${Number(r.fuel_consumed||0).toFixed(1)} L</div>
        </div>
        ${r.remarks ? `<div style="margin-top:8px;font-size:13px"><strong>Remarks:</strong> ${r.remarks}</div>` : ''}
      </div>
      <div style="font-size:12px;font-weight:700;color:var(--t3);margin-bottom:6px;text-transform:uppercase;letter-spacing:.03em">History</div>
      <div id="ml-detail-history" style="margin-bottom:14px"></div>
      <div class="brow">
        ${canDelete ? `<button class="bs1" id="mld-edit"><i class="ti ti-edit"></i>Edit</button>` : ''}
        <button class="bs1" id="ovCancel">Close</button>
      </div>`, null);
    _loadLogisticsHistoryInto('ml-detail-history', 'machine-logs', r.id);
    setTimeout(() => { const ed = $('mld-edit'); if (ed) ed.onclick = () => { closeOverlay(); openMachineLogEditOverlay(r.id); }; }, 30);
  }

  renderMlRows(mlFiltered());
  wireSortableTable($('ml-table'), mlSort, mlFiltered, renderMlRows);
  $('ml-search').oninput = (e) => { mlState.search = e.target.value; renderMlRows(mlFiltered()); };
  $('ml-status-filter').onchange = (e) => { mlState.status = e.target.value; renderMlRows(mlFiltered()); };
  $('ml-clear').onclick = () => { mlState.search=''; mlState.status=''; $('ml-search').value=''; $('ml-status-filter').value=''; renderMlRows(mlFiltered()); };

  await insertPendingPanel($(cid), ['machine_daily_log'], () => renderMachineLogs(cid, selectedMonth));
  await insertDeletionPanel($(cid), ['machine_daily_log'], () => renderMachineLogs(cid, selectedMonth));
}

// ── Machine KPI Performance ───────────────────────────────────────────────────

async function renderMachineKpi() {
  $('page-machine-kpi').innerHTML = `<div style="padding:2rem;color:var(--t3);font-size:13px"><i class="ti ti-loader-2" style="font-size:18px;animation:spin 1s linear infinite"></i> Loading…</div>`;

  const today = new Date();
  const defaultMonth = today.toISOString().slice(0, 7);
  const [perfRes, machRes] = await Promise.all([
    UFCL.machineKpiPerformance(STORAGE.user.id, defaultMonth),
    UFCL.machinesList(STORAGE.user.id)
  ]);
  if (!perfRes.ok) return renderDenied('machine-kpi', perfRes.ok === false ? perfRes.error : 'Access denied');

  const rows = perfRes.rows || [];
  const machines = machRes.ok ? (machRes.rows || []) : [];
  const canConfig = ['admin', 'operations', 'ceo'].includes(STORAGE.user?.role);

  const withTargets = rows.filter(r => r.kpiResults && r.kpiResults.length > 0);
  const avgAch = withTargets.filter(r => r.avgAchievement !== null);
  const overallAch = avgAch.length ? Math.round(avgAch.reduce((s,r)=>s+r.avgAchievement,0)/avgAch.length) : null;
  const avgUtil = rows.length ? Math.round(rows.reduce((s,r)=>s+Number(r.utilization_pct),0)/rows.length) : 0;
  const top = rows.reduce((best,r) => (!best || Number(r.utilization_pct)>Number(best.utilization_pct)) ? r : best, null);
  const underperf = rows.filter(r => r.avgAchievement !== null && r.avgAchievement < 75).length;

  const achColor = v => v === null ? '' : v >= 90 ? 'color:var(--green);font-weight:700' : v >= 75 ? 'color:var(--amber);font-weight:600' : 'color:var(--red);font-weight:700';
  const achBadge = v => v === null ? '<span style="color:var(--t3)">—</span>'
    : `<span class="badge ${v>=90?'bg':v>=75?'ba':'br'}">${v}%</span>`;

  // Phase 2 — search + sort toolkit over the already-fetched month's data.
  rows.forEach(r => { r._achLabel = r.avgAchievement===null ? 'No target' : r.avgAchievement>=90 ? 'On target' : r.avgAchievement>=75 ? 'Below target' : 'Underperforming'; });
  const kpiState = { search: '', status: '' };
  const kpiSort = { key: null, dir: 'asc' };
  function kpiFiltered() {
    return applyProcListFilters(rows, {
      search: kpiState.search, searchFields: ['machine_code', 'machine_name', 'category_name'],
      status: kpiState.status, statusField: '_achLabel',
    });
  }

  // Bar chart helper: utilization by machine
  function utilChart(data) {
    if (!data.length) return '<p style="color:var(--t3);font-size:12px">No data yet.</p>';
    const max = Math.max(...data.map(d => Number(d.utilization_pct)), 1);
    return data.map(d => {
      const pct = Math.round(Number(d.utilization_pct));
      const barW = Math.round((pct / max) * 100);
      const col = pct >= 85 ? '#22C55E' : pct >= 65 ? '#F59E0B' : '#EF4444';
      return `<div style="margin-bottom:8px">
        <div style="display:flex;justify-content:space-between;margin-bottom:2px">
          <span style="font-size:11px;color:var(--t2)">${d.machine_code}</span>
          <span style="font-size:11px;font-family:var(--fm);color:var(--t3)">${pct}%</span>
        </div>
        <div style="background:var(--surf);border-radius:3px;height:8px;overflow:hidden">
          <div style="background:${col};height:100%;width:${barW}%;border-radius:3px;transition:width .3s"></div>
        </div>
      </div>`;
    }).join('');
  }

  $('page-machine-kpi').innerHTML = `
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;margin-bottom:1.5rem">
      <div>
        <div class="ptitle">KPI Performance</div>
        <div class="psub">Track machine performance against KPI targets — utilisation, production efficiency, and achievement scoring.</div>
      </div>
      <div style="display:flex;align-items:center;gap:.75rem;flex-shrink:0">
        <div style="font-size:12px;color:var(--t3)">Month</div>
        <input type="month" id="kpi-month" value="${defaultMonth}" style="font-size:13px;padding:6px 10px;border:1px solid var(--bdr);border-radius:6px;background:var(--surf);color:var(--t1)">
        ${canConfig ? `<button class="bp1" id="kpiCfg"><i class="ti ti-adjustments"></i>Configure KPIs</button>` : ''}
      </div>
    </div>
    <div class="cards" style="margin-bottom:1.25rem">
      <div class="mc"><div class="mclbl">Avg KPI Achievement</div><div class="mcval" style="${achColor(overallAch)}">${overallAch !== null ? overallAch+'%' : '—'}</div><div class="mcsub ${overallAch===null?'':overallAch>=75?'cg':'cr'}"><i class="ti ti-target"></i>${defaultMonth}</div></div>
      <div class="mc"><div class="mclbl">Avg Utilization</div><div class="mcval" style="${achColor(avgUtil)}">${avgUtil}%</div><div class="mcsub ${avgUtil>=75?'cg':'ca'}"><i class="ti ti-clock"></i>all machines</div></div>
      <div class="mc"><div class="mclbl">Top Machine</div><div class="mcval" style="font-size:16px">${top ? top.machine_code : '—'}</div><div class="mcsub cg"><i class="ti ti-trophy"></i>${top ? Number(top.utilization_pct).toFixed(0)+'% util.' : 'no data'}</div></div>
      <div class="mc"><div class="mclbl">Below Target</div><div class="mcval" style="${underperf>0?'color:var(--red)':''}">${underperf}</div><div class="mcsub ${underperf>0?'cr':'cg'}"><i class="ti ti-alert-triangle"></i>machines <75% KPI</div></div>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1.25rem">
      <div class="card">
        <h3><i class="ti ti-chart-bar"></i>Utilization by machine</h3>
        ${utilChart(rows)}
      </div>
      <div class="card">
        <h3><i class="ti ti-list-details"></i>Production vs Capacity (${defaultMonth})</h3>
        ${rows.length ? rows.map(r => {
          const eff = Number(r.efficiency_pct);
          const col = eff >= 90 ? '#22C55E' : eff >= 70 ? '#F59E0B' : eff > 0 ? '#EF4444' : '#9CA3AF';
          return `<div style="margin-bottom:8px">
            <div style="display:flex;justify-content:space-between;margin-bottom:2px">
              <span style="font-size:11px;color:var(--t2)">${r.machine_code} <span style="color:var(--t3)">${r.category_name}</span></span>
              <span style="font-size:11px;font-family:var(--fm);color:var(--t3)">${Number(r.total_production).toLocaleString()} / ${Number(r.total_capacity).toLocaleString()}</span>
            </div>
            <div style="background:var(--surf);border-radius:3px;height:8px;overflow:hidden">
              <div style="background:${col};height:100%;width:${Math.min(eff,100)}%;border-radius:3px"></div>
            </div>
          </div>`;
        }).join('') : '<p style="color:var(--t3);font-size:12px">No production data for this month.</p>'}
      </div>
    </div>

    <!-- Phase 3 — Machine Intelligence: derived entirely from the same
         rows this page already fetched (utilization/downtime/efficiency
         per machine) — no new query, no duplicated KPI calculation. -->
    ${(() => {
      const withDowntime = rows.filter(r => Number(r.total_downtime) > 0)
        .sort((a,b) => Number(b.total_downtime) - Number(a.total_downtime)).slice(0, 5);
      const atRisk = rows.filter(r => Number(r.utilization_pct) < 50 && Number(r.total_downtime) > 10);
      return `
      <div class="card" style="margin-bottom:1.25rem">
        <h3><i class="ti ti-brain"></i>Machine Intelligence <span style="font-size:11px;font-weight:400;color:var(--t3)">· ${defaultMonth}</span></h3>
        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:1rem">
          <div>
            <div style="font-size:11px;color:var(--t3);text-transform:uppercase;letter-spacing:.06em;margin-bottom:.5rem">Highest downtime</div>
            ${withDowntime.length ? withDowntime.map(r => `
              <div style="display:flex;justify-content:space-between;align-items:center;padding:.35rem 0;border-bottom:1px solid var(--bdr)">
                <span style="font-size:12px;color:var(--t2)">${r.machine_code} <span style="color:var(--t3)">${r.machine_name}</span></span>
                <span style="font-size:12px;font-family:var(--fm);color:var(--red);font-weight:600">${Number(r.total_downtime).toFixed(1)}h</span>
              </div>`).join('') : '<p style="color:var(--t3);font-size:12px">No downtime logged this month.</p>'}
          </div>
          <div>
            <div style="font-size:11px;color:var(--t3);text-transform:uppercase;letter-spacing:.06em;margin-bottom:.5rem">Attention needed</div>
            ${atRisk.length ? atRisk.map(r => `
              <div style="display:flex;align-items:center;gap:.5rem;padding:.35rem 0;border-bottom:1px solid var(--bdr)">
                <i class="ti ti-alert-triangle" style="color:var(--red);font-size:14px;flex-shrink:0"></i>
                <span style="font-size:12px;color:var(--t2)">${r.machine_code} — low utilization (${Number(r.utilization_pct).toFixed(0)}%) with ${Number(r.total_downtime).toFixed(1)}h downtime</span>
              </div>`).join('') : '<p style="color:var(--green);font-size:12px"><i class="ti ti-circle-check"></i> No machines flagged this month.</p>'}
          </div>
        </div>
      </div>`;
    })()}
    ${procFilterBarHtml({
      searchId: 'kpi-search', searchPlaceholder: 'Search machine, category…',
      statusId: 'kpi-status-filter', statusOptions: ['On target', 'Below target', 'Underperforming', 'No target'],
      clearId: 'kpi-clear',
    })}
    <div class="card" style="padding:0">
      <div style="padding:1rem 1.25rem;border-bottom:1px solid var(--bdr)">
        <h3 style="margin:0"><i class="ti ti-target"></i>KPI achievement by machine — ${defaultMonth}</h3>
      </div>
      <div class="tw"><table class="tbl" id="kpi-table">
        <thead><tr>
          <th data-sort-key="machine_code">Machine</th><th data-sort-key="category_name">Category</th>
          <th data-sort-key="status">Status</th><th data-sort-key="utilization_pct">Util %</th>
          <th data-sort-key="efficiency_pct">Efficiency %</th><th data-sort-key="days_logged">Days Logged</th>
          <th data-sort-key="total_hours_worked">Total Hrs</th><th data-sort-key="avgAchievement">KPI Achievement</th>
          <th>Actions</th>
        </tr></thead>
        <tbody id="kpi-tbody"></tbody>
      </table></div>
    </div>`;

  function renderKpiRows(list) {
    const tbody = $('kpi-tbody');
    if (!list.length) {
      tbody.innerHTML = `<tr><td colspan="9" style="text-align:center;color:var(--t3);padding:3rem"><i class="ti ti-chart-line" style="font-size:2rem;display:block;margin-bottom:.5rem;opacity:.35"></i>No machines match these filters.</td></tr>`;
      return;
    }
    tbody.innerHTML = list.map(r => `<tr>
      <td style="font-weight:600;font-family:var(--fm)">${r.machine_code}<br><span style="font-size:11px;font-weight:400;font-family:inherit;color:var(--t3)">${r.machine_name}</span></td>
      <td><span class="badge bt">${r.category_name}</span></td>
      <td><span class="badge ${r.status==='Available'?'bg':r.status==='Running'?'bb':r.status==='Maintenance'?'ba':r.status==='Breakdown'?'br':'bt'}">${r.status}</span></td>
      <td style="${achColor(Number(r.utilization_pct))};font-family:var(--fm)">${Number(r.utilization_pct).toFixed(1)}%</td>
      <td style="${achColor(Number(r.efficiency_pct))};font-family:var(--fm)">${Number(r.efficiency_pct) > 0 ? Number(r.efficiency_pct).toFixed(1)+'%' : '—'}</td>
      <td style="font-family:var(--fm)">${r.days_logged}</td>
      <td style="font-family:var(--fm)">${Number(r.total_hours_worked).toFixed(1)}</td>
      <td>
        ${achBadge(r.avgAchievement)}
        ${r.kpiResults && r.kpiResults.length ? `<div style="margin-top:4px">${r.kpiResults.map(k =>
          `<div style="font-size:11px;color:var(--t3);display:flex;gap:4px;align-items:center">
            <span>${k.kpi_name}:</span>
            <span style="font-family:var(--fm)">${k.actual !== null ? Number(k.actual).toFixed(1)+' '+k.unit : '—'}</span>
            ${k.achievement !== null ? `<span style="color:${k.achievement>=90?'var(--green)':k.achievement>=75?'var(--amber)':'var(--red)'}">(${k.achievement}%)</span>` : ''}
          </div>`).join('')}
        </div>` : '<div style="font-size:11px;color:var(--t3);margin-top:3px">No KPI targets set</div>'}
      </td>
      <td style="white-space:nowrap">
        <button class="bs1 kpi-view" data-id="${r.machine_id}" title="View history"><i class="ti ti-eye"></i></button>
        ${canConfig ? `<button class="bs1 kpi-set" data-id="${r.machine_id}" data-name="${r.machine_code}" style="font-size:12px;padding:4px 8px;margin-left:4px"><i class="ti ti-target"></i>Set targets</button>` : ''}
      </td>
    </tr>`).join('');
    document.querySelectorAll('.kpi-view').forEach(btn => {
      btn.onclick = () => { const r = rows.find(x=>String(x.machine_id)===btn.dataset.id); if (r) openKpiHistoryOverlay(r); };
    });
  }

  // Phase 2 — machine's audit history, reusing the same generic per-record
  // lookup Machine Registry's detail overlay uses (module 'machines',
  // keyed by machine_id — KPI rows are computed aggregates, not their own
  // audit-logged records, so history is naturally scoped to the machine).
  function openKpiHistoryOverlay(r) {
    openOverlay('Machine history', r.machine_code + ' — ' + r.machine_name, `
      <div id="kpi-detail-history"></div>
      <div class="brow"><button class="bs1" id="ovCancel">Close</button></div>`, null);
    _loadLogisticsHistoryInto('kpi-detail-history', 'machines', r.machine_id);
  }

  renderKpiRows(kpiFiltered());
  wireSortableTable($('kpi-table'), kpiSort, kpiFiltered, renderKpiRows);
  $('kpi-search').oninput = (e) => { kpiState.search = e.target.value; renderKpiRows(kpiFiltered()); };
  $('kpi-status-filter').onchange = (e) => { kpiState.status = e.target.value; renderKpiRows(kpiFiltered()); };
  $('kpi-clear').onclick = () => { kpiState.search=''; kpiState.status=''; $('kpi-search').value=''; $('kpi-status-filter').value=''; renderKpiRows(kpiFiltered()); };

  // Month change → reload
  $('kpi-month').onchange = async () => {
    const m = $('kpi-month').value;
    if (!m) return;
    const nr = await UFCL.machineKpiPerformance(STORAGE.user.id, m);
    if (nr.ok) {
      // Re-render with new month (simple approach: rebuild the table section)
      await renderMachineKpi();
    }
  };

  // Set KPI targets overlay
  if (canConfig) {
    document.querySelectorAll('.kpi-set').forEach(btn => {
      btn.onclick = async () => {
        const machineId = Number(btn.dataset.id);
        const machName = btn.dataset.name;
        const month = $('kpi-month')?.value || defaultMonth;
        const tr = await UFCL.machineKpiTargetsList(STORAGE.user.id, machineId, month);
        if (!tr.ok) { alert(tr.error); return; }
        const kpiDefs = tr.kpiDefs || [];
        const existingTargets = tr.rows || [];
        const targetMap = Object.fromEntries(existingTargets.map(t => [t.kpi_id, t.target_value]));

        const kpiRows = kpiDefs.map(d => `
          <div class="frow" style="align-items:center;gap:.75rem;margin-bottom:.625rem">
            <div style="flex:2;font-size:13px;font-weight:500">${d.kpi_name} <span style="color:var(--t3);font-size:11px">(${d.unit})</span>${d.category_name?`<span class="badge bt" style="margin-left:4px;font-size:10px">${d.category_name}</span>`:''}</div>
            <div style="flex:1"><input class="kpi-target-val" data-kpi-id="${d.id}" type="number" min="0" step="0.1" value="${targetMap[d.id]||''}" placeholder="Target value" style="width:100%"></div>
          </div>`).join('');

        openOverlay('Set KPI Targets', `${machName} — ${month}`, `
          <div style="font-size:12px;color:var(--t3);margin-bottom:1rem">Enter monthly targets for each KPI. Leave blank to skip.</div>
          ${kpiRows}
          <div class="fg"><label>Reason / Note</label><input id="kpi-reason" type="text" placeholder="Why are these targets being updated?"></div>
          <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Save all targets</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
          async () => {
            const reason = $('kpi-reason')?.value?.trim() || null;
            const inputs = document.querySelectorAll('.kpi-target-val');
            let saved = 0;
            for (const inp of inputs) {
              if (!inp.value) continue;
              const r2 = await UFCL.machineKpiTargetsSave(STORAGE.user.id, {
                machine_id: machineId,
                kpi_id: Number(inp.dataset.kpiId),
                target_value: inp.value,
                effective_month: month,
                reason
              });
              if (!r2.ok) { showOverlayError(r2.error); return; }
              saved++;
            }
            showOverlaySuccess(`${saved} KPI target${saved!==1?'s':''} saved.`);
            await renderMachineKpi();
          });
      };
    });

    // Configure KPI definitions
    if ($('kpiCfg')) {
      // Remediation Phase 1 (F-04) — machineKpiDefinitionsUpdate/Delete had
      // full IPC/preload wiring but zero UI caller (definitions could be
      // created and listed but never fixed or retired). Added Edit/Delete
      // per row, reusing this overlay's own list/create pattern plus the
      // existing app-wide confirmDelete() helper.
      const openKpiDefsOverlay = async () => {
        const dr = await UFCL.machineKpiDefinitionsList(STORAGE.user.id);
        const defs = dr.ok ? dr.rows : [];
        const mc = machRes.ok ? (machRes.categories || []) : [];
        const catOpts = (selected) => `<option value="">All categories</option>` +
          mc.map(c => `<option value="${c.id}" ${String(selected)===String(c.id)?'selected':''}>${c.name}</option>`).join('');
        const defTable = defs.length
          ? defs.map(d => `<tr>
              <td>${d.kpi_name}</td><td style="font-family:var(--fm)">${d.kpi_code}</td><td>${d.unit||'—'}</td>
              <td>${d.category_name||'All'}</td><td>${d.higher_is_better?'Higher':'Lower'}</td><td>${d.weight}</td>
              <td style="white-space:nowrap"><button class="bs1 kd-edit" data-id="${d.id}" style="padding:3px 8px;font-size:11px"><i class="ti ti-edit"></i></button>
              <button class="bs1 kd-del" data-id="${d.id}" data-name="${String(d.kpi_name).replace(/"/g,'&quot;')}" style="padding:3px 8px;font-size:11px;color:var(--red)"><i class="ti ti-trash"></i></button></td>
            </tr>`).join('')
          : `<tr><td colspan="7" style="text-align:center;color:var(--t3);padding:1rem">No KPI definitions yet.</td></tr>`;
        openOverlay('Configure KPI Definitions', null, `
          <div class="tw" style="margin-bottom:1.25rem"><table class="dt">
            <thead><tr><th>Name</th><th>Code</th><th>Unit</th><th>Category</th><th>Direction</th><th>Weight</th><th></th></tr></thead>
            <tbody>${defTable}</tbody>
          </table></div>
          <div style="border-top:1px solid var(--bdr);padding-top:1rem">
            <div style="font-weight:600;font-size:13px;margin-bottom:.75rem">Add new KPI definition</div>
            <div class="frow">
              <div class="fg"><label>KPI Name *</label><input id="kd-name" type="text" placeholder="e.g. Daily Output"></div>
              <div class="fg"><label>KPI Code *</label><input id="kd-code" type="text" placeholder="e.g. daily_output"></div>
            </div>
            <div class="frow">
              <div class="fg"><label>Unit</label><input id="kd-unit" type="text" placeholder="m³, hrs, %"></div>
              <div class="fg"><label>Category (optional)</label><select id="kd-cat">${catOpts(null)}</select></div>
            </div>
            <div class="frow">
              <div class="fg"><label>Direction</label><select id="kd-dir"><option value="true">Higher is better</option><option value="false">Lower is better</option></select></div>
              <div class="fg"><label>Weight</label><input id="kd-weight" type="number" min="0.1" step="0.1" value="1.0"></div>
            </div>
          </div>
          <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-plus"></i>Add definition</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
          async () => {
            const r2 = await UFCL.machineKpiDefinitionsCreate(STORAGE.user.id, {
              kpi_name: $('kd-name').value.trim(),
              kpi_code: $('kd-code').value.trim(),
              unit: $('kd-unit').value.trim(),
              category_id: $('kd-cat').value || null,
              higher_is_better: $('kd-dir').value === 'true',
              weight: $('kd-weight').value || 1.0
            });
            if (!r2.ok) { showOverlayError(r2.error); return; }
            showOverlaySuccess('KPI definition added.');
            await renderMachineKpi();
          });

        document.querySelectorAll('.kd-edit').forEach(btn => {
          btn.onclick = () => {
            const d = defs.find(x => String(x.id) === btn.dataset.id);
            if (!d) return;
            openOverlay('Edit KPI Definition', d.kpi_name, `
              <div class="frow">
                <div class="fg"><label>KPI Name *</label><input id="kd-e-name" type="text" value="${String(d.kpi_name).replace(/"/g,'&quot;')}"></div>
                <div class="fg"><label>KPI Code *</label><input id="kd-e-code" type="text" value="${String(d.kpi_code).replace(/"/g,'&quot;')}"></div>
              </div>
              <div class="frow">
                <div class="fg"><label>Unit</label><input id="kd-e-unit" type="text" value="${d.unit||''}"></div>
                <div class="fg"><label>Category (optional)</label><select id="kd-e-cat">${catOpts(d.category_id)}</select></div>
              </div>
              <div class="frow">
                <div class="fg"><label>Direction</label><select id="kd-e-dir"><option value="true" ${d.higher_is_better?'selected':''}>Higher is better</option><option value="false" ${!d.higher_is_better?'selected':''}>Lower is better</option></select></div>
                <div class="fg"><label>Weight</label><input id="kd-e-weight" type="number" min="0.1" step="0.1" value="${d.weight}"></div>
              </div>
              <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Save Changes</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
              async () => {
                const r2 = await UFCL.machineKpiDefinitionsUpdate(STORAGE.user.id, d.id, {
                  kpi_name: $('kd-e-name').value.trim(),
                  kpi_code: $('kd-e-code').value.trim(),
                  unit: $('kd-e-unit').value.trim(),
                  category_id: $('kd-e-cat').value || null,
                  higher_is_better: $('kd-e-dir').value === 'true',
                  weight: $('kd-e-weight').value || 1.0
                });
                if (!r2.ok) { showOverlayError(r2.error); return; }
                showOverlaySuccess('KPI definition updated.');
                await openKpiDefsOverlay();
              });
          };
        });
        document.querySelectorAll('.kd-del').forEach(btn => {
          btn.onclick = () => {
            confirmDelete(`Delete KPI definition "${btn.dataset.name}"? Historical target/performance data referencing it is preserved.`, async () => {
              const r2 = await UFCL.machineKpiDefinitionsDelete(STORAGE.user.id, Number(btn.dataset.id));
              if (!r2.ok) { showOverlayError(r2.error); return; }
              showOverlaySuccess('KPI definition deleted.');
              await openKpiDefsOverlay();
            });
          };
        });
      };
      $('kpiCfg').onclick = openKpiDefsOverlay;
    }
  }
}

// ── Compartments ─────────────────────────────────────────────────────────────

async function renderCompartments() {
  $('page-compartments').innerHTML = `<div style="padding:2rem;color:var(--t3);font-size:13px"><i class="ti ti-loader-2" style="font-size:18px;animation:spin 1s linear infinite"></i> Loading…</div>`;
  const res = await UFCL.compartmentsList(STORAGE.user.id);
  if (!res.ok) return renderDenied('compartments', res.error);
  const rows = res.rows || [];
  const today = new Date().toISOString().split('T')[0];
  const totalArea = rows.reduce((s, r) => s + Number(r.area_ha || 0), 0);
  const totalVol  = rows.reduce((s, r) => s + Number(r.volume_m3 || 0), 0);
  const totalHarvVol = rows.reduce((s, r) => s + Number(r.volume_harvested_m3 || 0), 0);
  const activeCount = rows.filter(r => r.status === 'Active').length;

  $('page-compartments').innerHTML = `
    <div class="ptitle"><i class="ti ti-map-pin" style="color:var(--g-soft)"></i> Compartments</div>
    <div class="psub">Forest compartments (blocks). Each compartment has a calculated volume based on 219 m³/ha. Once fully harvested it is automatically marked Completed.</div>
    <div class="cards">
      <div class="mc" style="border-top:3px solid #2E8B57">
        <div class="mclbl">Active compartments</div>
        <div class="mcval" style="color:var(--green)">${activeCount}</div>
        <div class="mcsub cg"><i class="ti ti-map-pin"></i>${rows.length} total</div>
      </div>
      <div class="mc">
        <div class="mclbl">Total area</div>
        <div class="mcval">${totalArea.toFixed(1)} ha</div>
        <div class="mcsub cg"><i class="ti ti-trees"></i>all compartments</div>
      </div>
      <div class="mc">
        <div class="mclbl">Total standing volume</div>
        <div class="mcval">${totalVol.toFixed(1)} m³</div>
        <div class="mcsub cg"><i class="ti ti-cube"></i>@ 219 m³/ha</div>
      </div>
      <div class="mc">
        <div class="mclbl">Volume harvested</div>
        <div class="mcval" style="color:var(--green)">${totalHarvVol.toFixed(1)} m³</div>
        <div class="mcsub cg"><i class="ti ti-axe"></i>from felled trees</div>
      </div>
    </div>
    <div class="card">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem">
        <h3 style="margin-bottom:0"><i class="ti ti-map-pin"></i>Compartment list</h3>
        <button class="appbtn" id="newCompt"><i class="ti ti-plus" style="font-size:12px;vertical-align:-1px"></i> Add compartment</button>
      </div>
      <div class="tw"><table class="dt">
        <thead><tr><th>Name</th><th>Sub-name</th><th>Species</th><th>Area (ha)</th><th>Expected Volume (m³)</th><th>Harvested (m³)</th><th>Progress</th><th>Status</th><th>Date</th><th>Action</th></tr></thead>
        <tbody>
          ${rows.length === 0
            ? emptyRowHtml({ colspan: 10, icon: 'ti-map-pin', title: 'No compartments yet.', subtitle: 'Click "Add compartment" above to create one.' })
            : rows.map(r => {
                const pct = Number(r.volume_m3) > 0 ? Math.min(100, Math.round(Number(r.volume_harvested_m3) / Number(r.volume_m3) * 100)) : 0;
                const statusBadge = r.status === 'Active' ? '<span class="badge bg">Active</span>' : '<span class="badge ba">Completed</span>';
                return `<tr>
                  <td style="font-weight:600;color:var(--g-dark)">${r.compt_name}${r.pending_deletion ? ' <span class="badge br" style="font-size:10px;vertical-align:middle">Pending Deletion</span>' : ''}</td>
                  <td style="color:var(--t3)">${r.sub_name || '—'}</td>
                  <td><span class="badge bt">${r.species}</span></td>
                  <td style="font-family:var(--fm)">${Number(r.area_ha).toFixed(2)}</td>
                  <td style="font-family:var(--fm)">${Number(r.volume_m3).toFixed(1)}</td>
                  <td style="font-family:var(--fm);color:var(--green)">${Number(r.volume_harvested_m3 || 0).toFixed(1)}</td>
                  <td style="min-width:90px">
                    <div style="background:var(--bdr);border-radius:4px;height:8px;overflow:hidden">
                      <div style="background:var(--g-soft);height:100%;width:${pct}%;transition:width .3s"></div>
                    </div>
                    <div style="font-size:11px;color:var(--t3);margin-top:2px">${pct}%</div>
                  </td>
                  <td>${statusBadge}</td>
                  <td style="color:var(--t3)">${r.entry_date}</td>
                  <td style="white-space:nowrap">
                    <button class="bs1 compt-edit" data-id="${r.id}"><i class="ti ti-edit"></i>Edit</button>
                    <button class="bs1 compt-del" data-id="${r.id}" style="color:var(--red)"><i class="ti ti-trash"></i></button>
                  </td>
                </tr>`;
              }).join('')}
        </tbody>
      </table></div>
    </div>`;

  $('newCompt').onclick = () => openOverlay('Add Compartment', 'Volume is auto-calculated at 219 m³/ha', `
    <div class="frow">
      <div class="fg"><label>Entry date *</label><input type="date" id="cp-date" value="${today}"></div>
      <div class="fg"><label>User</label><input type="text" id="cp-user" value="${STORAGE.user.name}" readonly style="background:var(--surf)"></div>
    </div>
    <div class="frow">
      <div class="fg"><label>Compartment name *</label><input type="text" id="cp-name" placeholder="e.g. Compt A1"></div>
      <div class="fg"><label>Sub name <span style="color:var(--t3);font-weight:400">(optional)</span></label><input type="text" id="cp-sub" placeholder="e.g. Block 1, Sub A"></div>
    </div>
    <div class="frow">
      <div class="fg"><label>Species *</label><input type="text" id="cp-species" placeholder="e.g. Eucalyptus, Pine"></div>
      <div class="fg"><label>Area (ha) *</label><input type="number" id="cp-area" step="0.001" min="0.001" placeholder="0.000"></div>
    </div>
    <div class="fg" style="background:var(--g-light);border:1px solid rgba(30,95,54,.2);border-radius:6px;padding:.6rem .75rem;margin-bottom:.75rem">
      <div style="font-size:12px;color:var(--g-dark);font-weight:600">Calculated volume</div>
      <div id="cp-vol-preview" style="font-size:22px;font-weight:700;color:var(--g-soft);margin-top:4px">— m³</div>
      <div style="font-size:11px;color:var(--t3)">= Area (ha) × 219 m³/ha</div>
    </div>
    <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-device-floppy"></i>Save</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
    async () => {
      const r = await UFCL.compartmentsCreate(STORAGE.user.id, {
        entry_date: $('cp-date').value,
        compt_name: $('cp-name').value.trim(),
        sub_name: $('cp-sub').value.trim() || null,
        species: $('cp-species').value.trim(),
        area_ha: $('cp-area').value
      });
      if (!r.ok) { showOverlayError(r.error); return; }
      showOverlaySuccess('Compartment saved.'); await renderCompartments();
    }
  );
  const areaEl = document.getElementById('cp-area');
  const volPrev = document.getElementById('cp-vol-preview');
  if (areaEl && volPrev) {
    areaEl.oninput = () => {
      const v = Number(areaEl.value);
      volPrev.textContent = v > 0 ? (v * 219).toFixed(1) + ' m³' : '— m³';
    };
  }

  document.querySelectorAll('.compt-edit').forEach(btn => {
    btn.onclick = () => {
      const r = rows.find(x => x.id === btn.dataset.id);
      if (!r) return;
      const isoDate = r.entry_date.split('/').reverse().join('-');
      openOverlay('Edit Compartment', r.compt_name, `
        <div class="frow">
          <div class="fg"><label>Entry date *</label><input type="date" id="cp-date" value="${isoDate}"></div>
          <div class="fg"><label>Status</label><select id="cp-status"><option value="Active" ${r.status==='Active'?'selected':''}>Active</option><option value="Completed" ${r.status==='Completed'?'selected':''}>Completed</option></select></div>
        </div>
        <div class="frow">
          <div class="fg"><label>Compartment name *</label><input type="text" id="cp-name" value="${r.compt_name}"></div>
          <div class="fg"><label>Sub name</label><input type="text" id="cp-sub" value="${r.sub_name||''}"></div>
        </div>
        <div class="frow">
          <div class="fg"><label>Species *</label><input type="text" id="cp-species" value="${r.species}"></div>
          <div class="fg"><label>Area (ha) *</label><input type="number" id="cp-area" step="0.001" value="${r.area_ha}"></div>
        </div>
        <div class="fg" style="background:var(--g-light);border:1px solid rgba(30,95,54,.2);border-radius:6px;padding:.6rem .75rem;margin-bottom:.75rem">
          <div style="font-size:12px;color:var(--g-dark);font-weight:600">Volume (auto-calculated)</div>
          <div id="cp-vol-preview" style="font-size:22px;font-weight:700;color:var(--g-soft);margin-top:4px">${Number(r.area_ha) * 219} m³</div>
        </div>
        <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-device-floppy"></i>Save</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
        async () => {
          const payload = {
            entry_date: $('cp-date').value, compt_name: $('cp-name').value.trim(),
            sub_name: $('cp-sub').value.trim() || null, species: $('cp-species').value.trim(),
            area_ha: $('cp-area').value, status: $('cp-status').value
          };
          if (isSupervisor()) {
            const r2 = await UFCL.pendingEditsCreate(STORAGE.user.id, {
              action_type: 'edit', entity_type: 'compartment',
              entity_id: r.id, entity_ref: r.compt_name, payload
            });
            if (!r2.ok) { showOverlayError(r2.error); return; }
            showOverlaySuccess('Change submitted for approval.'); closeOverlay(); await renderCompartments();
          } else {
            const res2 = await UFCL.compartmentsUpdate(STORAGE.user.id, r.id, payload);
            if (!res2.ok) { showOverlayError(res2.error); return; }
            showOverlaySuccess('Compartment updated.'); await renderCompartments();
          }
        }
      );
      const aEl = document.getElementById('cp-area');
      const vEl = document.getElementById('cp-vol-preview');
      if (aEl && vEl) aEl.oninput = () => { const v = Number(aEl.value); vEl.textContent = v > 0 ? (v * 219).toFixed(1) + ' m³' : '— m³'; };
    };
  });

  document.querySelectorAll('.compt-del').forEach(btn => {
    btn.onclick = () => {
      const r = rows.find(x => x.id === btn.dataset.id);
      if (!r) return;
      if (isSupervisor()) {
        confirmDeleteSoft(`Submit delete request for compartment <strong>${r.compt_name}</strong>? A manager must approve before it is moved to Trash.`, async (reason) => {
          const r2 = await UFCL.deletionRequestCreate(STORAGE.user.id, 'compartments', r.id, 'compartment', r.compt_name, reason);
          if (!r2.ok) { showOverlayError(r2.error); return; }
          showOverlaySuccess('Deletion request submitted for approval.'); await renderCompartments();
        });
      } else {
        confirmDeleteSoft(`Move compartment <strong>${r.compt_name}</strong> to Trash? Associated harvest logs will be unlinked.`, async (reason) => {
          const res2 = await UFCL.compartmentsDelete(STORAGE.user.id, r.id, reason);
          if (!res2.ok) { showOverlayError(res2.error); return; }
          showOverlaySuccess('Compartment moved to Trash.'); await renderCompartments();
        });
      }
    };
  });

  await insertPendingPanel($('page-compartments'), ['compartment'], renderCompartments);
  await insertDeletionPanel($('page-compartments'), ['compartment'], renderCompartments);
}

// ── Log Transport ─────────────────────────────────────────────────────────────

async function renderLogTransport() {
  $('page-log-transport').innerHTML = `<div style="padding:2rem;color:var(--t3);font-size:13px"><i class="ti ti-loader-2" style="font-size:18px;animation:spin 1s linear infinite"></i> Loading…</div>`;
  const [res, comptsRes, vehRes, machRes, workshops] = await Promise.all([
    UFCL.logTransportList(STORAGE.user.id, WORKSHOP_FILTER),
    UFCL.compartmentsForDropdown(STORAGE.user.id),
    UFCL.vehiclesForTransport(STORAGE.user.id),
    UFCL.machinesForDropdown(STORAGE.user.id),
    fetchWorkshopsForBanner()
  ]);
  if (!res.ok) return renderDenied('log-transport', res.error);
  const rows = res.rows || [];
  const totals = res.totals || {};
  const compts = comptsRes.ok ? comptsRes.rows : [];
  const transportVehicles = vehRes.ok ? (vehRes.rows || []) : [];
  const allMachines = machRes.ok ? (machRes.rows || []) : [];
  const today = new Date().toISOString().split('T')[0];
  const logsM3 = (totals.totalLogsHarvested / 3.4).toFixed(1);
  const transportedM3 = (totals.totalLogsTransported / 3.4).toFixed(1);
  const remainingM3 = ((totals.remainingLogs) / 3.4).toFixed(1);

  $('page-log-transport').innerHTML = `
    <div class="ptitle"><i class="ti ti-truck-loading" style="color:var(--g-soft)"></i> Log Transport</div>
    <div class="psub">Track logs transported from forest to sawmill. Totals based on hand-rolled logs (transport-ready).</div>
    <div class="cards">
      <div class="mc" style="border-top:3px solid #2E8B57">
        <div class="mclbl">Total Logs (Hand-Rolled)</div>
        <div class="mcval" style="color:var(--green)">${totals.totalLogsHarvested.toLocaleString()}</div>
        <div class="mcsub cg"><i class="ti ti-truck-loading"></i>${logsM3} m³ · ready for transport</div>
      </div>
      <div class="mc" style="border-top:3px solid #1D4ED8">
        <div class="mclbl">Logs Transported</div>
        <div class="mcval" style="color:#1D4ED8">${totals.totalLogsTransported.toLocaleString()}</div>
        <div class="mcsub bp"><i class="ti ti-truck"></i>${transportedM3} m³ loaded</div>
      </div>
      <div class="mc" style="border-top:3px solid ${totals.remainingLogs < 0 ? '#DC2626' : '#D97706'}">
        <div class="mclbl">Remaining Logs</div>
        <div class="mcval" style="color:${totals.remainingLogs < 0 ? 'var(--red)' : 'var(--amber)'}">${totals.remainingLogs.toLocaleString()}</div>
        <div class="mcsub ca"><i class="ti ti-stack-2"></i>${remainingM3} m³ · hand-rolled − transported</div>
      </div>
      <div class="mc">
        <div class="mclbl">Hand-Rolled Volume</div>
        <div class="mcval">${totals.totalVolumeM3.toFixed(1)} m³</div>
        <div class="mcsub cg"><i class="ti ti-cube"></i>hand-rolled ÷ 3.4</div>
      </div>
    </div>
    <div class="card">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem">
        <h3 style="margin-bottom:0"><i class="ti ti-truck-loading"></i>Transport entries</h3>
        <button class="appbtn" id="newLT"><i class="ti ti-plus" style="font-size:12px;vertical-align:-1px"></i> Log transport</button>
      </div>
      <div class="tw"><table class="dt">
        <thead><tr><th>Date</th><th>Compartment</th><th>Sub name</th><th>Logs transported</th><th>Volume total (m³)</th><th>Tractor plate</th><th>Loggers no.</th><th>Notes</th><th>Logged by</th><th>Action</th></tr></thead>
        <tbody>
          ${rows.length === 0
            ? '<tr><td colspan="10" style="text-align:center;color:var(--t3);padding:2rem">No transport entries yet. Click "Log transport" to record a load.</td></tr>'
            : rows.map(r => `<tr>
                <td style="font-family:var(--fm);font-weight:500">${r.date_fmt}${r.pending_deletion ? ' <span class="badge br" style="font-size:10px;vertical-align:middle">Pending Deletion</span>' : ''}</td>
                <td style="font-weight:500;color:var(--g-dark)">${r.compt_name || '—'}</td>
                <td style="color:var(--t3)">${r.sub_name || '—'}</td>
                <td style="font-family:var(--fm);font-weight:600;color:#1D4ED8">${Number(r.qty_transported).toLocaleString()}</td>
                <td style="font-family:var(--fm);color:var(--green)">${(Number(r.qty_transported) / 3.4).toFixed(2)}</td>
                <td style="font-family:var(--fm);color:var(--t3)">${r.tractor_plate || '—'}</td>
                <td style="color:var(--t3)">${r.loggers_number || '—'}</td>
                <td style="color:var(--t3)">${r.notes || '—'}</td>
                <td>${r.logged_by_name || '—'}</td>
                <td style="white-space:nowrap">
                  <button class="bs1 lt-edit" data-id="${r.id}"><i class="ti ti-edit"></i></button>
                  <button class="bs1 lt-del" data-id="${r.id}" style="color:var(--red)"><i class="ti ti-trash"></i></button>
                </td>
              </tr>`).join('')}
        </tbody>
      </table></div>
    </div>`;
  prependWorkshopBanner($('page-log-transport'), workshops, () => renderLogTransport());

  $('newLT').onclick = () => {
    const wsPicker = workshopPickerHtml(workshops, 'lt-workshop');
    const comptOpts = compts.map(c => `<option value="${c.id}" data-sub="${c.sub_name||''}" data-species="${c.species}" data-status="${c.status}">${c.compt_name}${c.sub_name ? ' / '+c.sub_name : ''} [${c.status}]</option>`).join('');

    // Build vehicle options grouped by category
    const trucks   = transportVehicles.filter(v => v.vehicle_category === 'Truck');
    const tractors = transportVehicles.filter(v => v.vehicle_category === 'Tractor');
    const vehOptGroup = (label, list) => list.length
      ? `<optgroup label="${label}">${list.map(v =>
          `<option value="${v.registration}">${v.registration}${v.make ? ' — ' + v.make : ''}${v.model ? ' ' + v.model : ''}${v.driver_assigned ? ' [' + v.driver_assigned + ']' : ''}</option>`
        ).join('')}</optgroup>`
      : '';
    const vehOpts = vehOptGroup('Tractor', tractors) + vehOptGroup('Truck', trucks);

    // Build machine options grouped by category
    const machByCategory = {};
    allMachines.forEach(m => {
      if (!machByCategory[m.category_name]) machByCategory[m.category_name] = [];
      machByCategory[m.category_name].push(m);
    });
    const machOpts = Object.entries(machByCategory).map(([cat, list]) =>
      `<optgroup label="${cat}">${list.map(m =>
        `<option value="${m.machine_code}">${m.machine_code}${m.name ? ' — ' + m.name : ''}${m.plate_number ? ' [' + m.plate_number + ']' : ''}</option>`
      ).join('')}</optgroup>`
    ).join('');

    openOverlay('Log Transport Entry', 'Record logs transported from forest to sawmill', `
      ${wsPicker ? `<div class="frow">${wsPicker}</div>` : ''}
      <div class="frow">
        <div class="fg"><label>Date *</label><input type="date" id="lt-date" value="${today}"></div>
        <div class="fg"><label>User</label><input type="text" id="lt-user" value="${STORAGE.user.name}" readonly style="background:var(--surf)"></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Compartment</label><select id="lt-compt"><option value="">— Select compartment —</option>${comptOpts}</select></div>
        <div class="fg" id="lt-sub-row" style="display:none"><label>Sub name</label><select id="lt-sub"><option value="">—</option></select></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Logs transported *</label><input type="number" id="lt-qty" min="1" placeholder="0"></div>
        <div class="fg"><label>Volume total (auto m³)</label><input type="text" id="lt-vol" readonly style="background:var(--surf)" placeholder="0.00 m³"></div>
      </div>
      <div class="frow">
        <div class="fg">
          <label>Tractor / Truck plate number</label>
          ${vehOpts
            ? `<input type="text" id="lt-veh-search" placeholder="Search by plate, make, driver…" autocomplete="off" style="margin-bottom:4px">
               <select id="lt-tractor">
                 <option value="">— select vehicle —</option>
                 ${vehOpts}
               </select>`
            : `<input type="text" id="lt-tractor" placeholder="e.g. RAA 123B — no Truck/Tractor registered yet">`}
        </div>
        <div class="fg">
          <label>Loggers' number (Machine Registry)</label>
          ${machOpts
            ? `<input type="text" id="lt-mach-search" placeholder="Search by code, name…" autocomplete="off" style="margin-bottom:4px">
               <select id="lt-loggers">
                 <option value="">— select machine —</option>
                 ${machOpts}
               </select>`
            : `<input type="text" id="lt-loggers" placeholder="e.g. L-007 — no machines registered yet">`}
        </div>
      </div>
      <div class="fg"><label>Notes</label><input type="text" id="lt-notes" placeholder="Route, driver, additional details…"></div>
      <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-device-floppy"></i>Save</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
      async () => {
        const r = await UFCL.logTransportCreate(STORAGE.user.id, {
          transport_date:  $('lt-date').value,
          compt_id:        $('lt-compt').value || null,
          sub_name:        $('lt-sub')?.value || null,
          qty_transported: $('lt-qty').value,
          tractor_plate:   $('lt-tractor').value.trim() || null,
          loggers_number:  $('lt-loggers').value.trim() || null,
          notes:           $('lt-notes').value.trim() || null,
          workshop_id:     $('lt-workshop')?.value || null
        });
        if (!r.ok) { showOverlayError(r.error); return; }
        showOverlaySuccess('Transport entry saved.'); await renderLogTransport();
      }
    );

    // openOverlay is synchronous — wire all event listeners now
    const comptSel = document.getElementById('lt-compt');
    const subRow   = document.getElementById('lt-sub-row');
    const subSel   = document.getElementById('lt-sub');
    const qtyEl    = document.getElementById('lt-qty');
    const volEl    = document.getElementById('lt-vol');
    const searchEl  = document.getElementById('lt-veh-search');
    const vehSel    = document.getElementById('lt-tractor');
    const machSearchEl = document.getElementById('lt-mach-search');
    const machSel      = document.getElementById('lt-loggers');

    if (comptSel) {
      comptSel.onchange = () => {
        const opt = comptSel.options[comptSel.selectedIndex];
        const sub = opt?.dataset?.sub || '';
        if (sub && subRow && subSel) {
          subRow.style.display = '';
          subSel.innerHTML = `<option value="">—</option><option value="${sub}">${sub}</option>`;
        } else if (subRow) {
          subRow.style.display = 'none';
        }
      };
    }

    if (qtyEl && volEl) {
      qtyEl.oninput = () => {
        const v = Number(qtyEl.value);
        volEl.value = v > 0 ? (v / 3.4).toFixed(2) + ' m³' : '';
      };
    }

    // Live search filter helper (reused for both dropdowns)
    const wireSearch = (searchInput, selectEl) => {
      if (!searchInput || !selectEl) return;
      searchInput.addEventListener('input', () => {
        const q = searchInput.value.trim().toLowerCase();
        Array.from(selectEl.options).forEach(opt => {
          if (!opt.value) return;
          opt.style.display = !q || opt.textContent.toLowerCase().includes(q) ? '' : 'none';
        });
        const cur = selectEl.options[selectEl.selectedIndex];
        if (cur?.value && cur.style.display === 'none') selectEl.value = '';
      });
    };
    wireSearch(searchEl, vehSel);
    wireSearch(machSearchEl, machSel);
  };

  // Remediation Phase 2 — logTransportUpdate had backend/IPC wiring (fully
  // governed via applyGovernance, same as the delete path below) with no UI
  // caller on either platform; this session's earlier fix added the
  // pending-edit approval panel for log_transport but nothing could ever
  // populate it since edit itself was unreachable. Reuses the exact field
  // set/options already built for the "Log transport" create form above.
  document.querySelectorAll('.lt-edit').forEach(btn => {
    btn.onclick = () => {
      const r = rows.find(x => String(x.id) === btn.dataset.id);
      if (!r) return;
      const comptOpts = compts.map(c => `<option value="${c.id}" data-sub="${c.sub_name||''}" ${String(r.compt_id)===String(c.id)?'selected':''}>${c.compt_name}${c.sub_name ? ' / '+c.sub_name : ''} [${c.status}]</option>`).join('');
      openOverlay('Edit Log Transport Entry', r.date_fmt, `
        <div class="frow">
          <div class="fg"><label>Date *</label><input type="date" id="lte-date" value="${r.transport_date || ''}"></div>
          <div class="fg"><label>Logs transported *</label><input type="number" id="lte-qty" min="1" value="${r.qty_transported}"></div>
        </div>
        <div class="frow">
          <div class="fg"><label>Compartment</label><select id="lte-compt"><option value="">— Select compartment —</option>${comptOpts}</select></div>
          <div class="fg"><label>Sub name</label><input type="text" id="lte-sub" value="${r.sub_name || ''}"></div>
        </div>
        <div class="frow">
          <div class="fg"><label>Tractor / Truck plate number</label><input type="text" id="lte-tractor" value="${(r.tractor_plate||'').replace(/"/g,'&quot;')}"></div>
          <div class="fg"><label>Loggers' number</label><input type="text" id="lte-loggers" value="${(r.loggers_number||'').replace(/"/g,'&quot;')}"></div>
        </div>
        <div class="fg"><label>Notes</label><input type="text" id="lte-notes" value="${(r.notes||'').replace(/"/g,'&quot;')}"></div>
        <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Save Changes</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
        async () => {
          const res2 = await UFCL.logTransportUpdate(STORAGE.user.id, r.id, {
            transport_date:  $('lte-date').value,
            compt_id:        $('lte-compt').value || null,
            sub_name:        $('lte-sub').value.trim() || null,
            qty_transported: $('lte-qty').value,
            tractor_plate:   $('lte-tractor').value.trim() || null,
            loggers_number:  $('lte-loggers').value.trim() || null,
            notes:           $('lte-notes').value.trim() || null,
          });
          if (handleGovernanceResult(res2)) return;
          showOverlaySuccess('Transport entry updated.');
          await renderLogTransport();
        }
      );
    };
  });

  document.querySelectorAll('.lt-del').forEach(btn => {
    btn.onclick = () => {
      const r = rows.find(x => x.id === btn.dataset.id);
      if (isSupervisor()) {
        confirmDeleteSoft('Submit delete request for this transport entry? A manager must approve before it is moved to Trash.', async (reason) => {
          const ref = r ? `${r.compt_name || 'Transport'} — ${r.date_fmt}` : btn.dataset.id;
          const r2 = await UFCL.deletionRequestCreate(STORAGE.user.id, 'log_transport', btn.dataset.id, 'log_transport', ref, reason);
          if (!r2.ok) { showOverlayError(r2.error); return; }
          showOverlaySuccess('Deletion request submitted for approval.'); await renderLogTransport();
        });
      } else {
        confirmDeleteSoft('Move this transport entry to Trash?', async (reason) => {
          const res2 = await UFCL.logTransportDelete(STORAGE.user.id, btn.dataset.id, reason);
          if (!res2.ok) { showOverlayError(res2.error); return; }
          showOverlaySuccess('Entry moved to Trash.'); await renderLogTransport();
        });
      }
    };
  });

  await insertPendingPanel($('page-log-transport'), ['log_transport'], renderLogTransport);
  await insertDeletionPanel($('page-log-transport'), ['log_transport'], renderLogTransport);
}

// ── Nyanza Value-Added Production ────────────────────────────────────────────
// Nyanza Value-Added Production & Finished Products Completion Phase —
// replaces "Value-Added Timber" (single row = one same-size treatment entry,
// no real stock consumption) with a batch + input/output-lines model that
// can manufacture a genuinely different Product Catalog item. See
// db/migrate.js createNyanzaValueAddedProduction() for the schema/rationale.

function _vapInputRowHtml(idx, opts) {
  const optHtml = opts.length
    ? opts.map(o => `<option value="${o.stock_item_id}" data-avail="${o.available}">${o.name} — ${Number(o.available).toLocaleString()} ${o.uom || ''} available</option>`).join('')
    : '<option value="" disabled>No stock available at this workshop</option>';
  return `<div class="vap-input-row frow" data-idx="${idx}" style="align-items:flex-end;gap:.5rem">
    <div class="fg" style="flex:2;margin-bottom:.5rem"><label>${idx === 0 ? 'Input material *' : ''}</label><select class="vap-in-item">${optHtml}</select></div>
    <div class="fg" style="flex:1;margin-bottom:.5rem"><label>${idx === 0 ? 'Quantity *' : ''}</label><input class="vap-in-qty" type="number" min="1" placeholder="0"></div>
    <button type="button" class="bs1 vap-in-remove" style="margin-bottom:.5rem" title="Remove"><i class="ti ti-x"></i></button>
  </div>`;
}
function _vapOutputRowHtml(idx, products) {
  const optHtml = products.length
    ? products.map(p => `<option value="${p.id}">${p.type}${p.sub_type ? ' '+p.sub_type : ''} ${p.size}</option>`).join('')
    : '<option value="" disabled>No active products — add in Product Catalog first</option>';
  return `<div class="vap-output-row frow" data-idx="${idx}" style="align-items:flex-end;gap:.5rem">
    <div class="fg" style="flex:2;margin-bottom:.5rem"><label>${idx === 0 ? 'Output product *' : ''}</label><select class="vap-out-product">${optHtml}</select></div>
    <div class="fg" style="flex:1;margin-bottom:.5rem"><label>${idx === 0 ? 'Quantity *' : ''}</label><input class="vap-out-qty" type="number" min="1" placeholder="0"></div>
    <button type="button" class="bs1 vap-out-remove" style="margin-bottom:.5rem" title="Remove"><i class="ti ti-x"></i></button>
  </div>`;
}

async function renderValueAddedProduction(cid='page-value-added-production') {
  $(cid).innerHTML = `<div style="padding:2rem;color:var(--t3);font-size:13px"><i class="ti ti-loader-2" style="font-size:18px;animation:spin 1s linear infinite"></i> Loading…</div>`;
  const [res, productsRes, inputsRes, customersRes, workshops] = await Promise.all([
    UFCL.valueAddedProductionList(STORAGE.user.id, WORKSHOP_FILTER),
    UFCL.productsList(STORAGE.user.id, 'Active'),
    UFCL.valueAddedProductionAvailableInputs(STORAGE.user.id, WORKSHOP_FILTER),
    UFCL.customersList(STORAGE.user.id),
    fetchWorkshopsForBanner()
  ]);
  if (!res.ok) return renderDenied('value-added-production', res.error);
  const rows = res.rows || [];
  const activeProducts = productsRes.ok ? productsRes.rows : [];
  const availableInputs = inputsRes.ok ? inputsRes.rows : [];
  const customers = customersRes.ok ? (customersRes.rows || []).filter(c => c.active) : [];
  const today = new Date().toISOString().split('T')[0];

  const totalBatches = rows.length;
  const pendingQcCount = rows.reduce((s, r) => s + r.outputs.filter(o => o.status === 'pending_qc').length, 0);
  const totalOutputQty = rows.reduce((s, r) => s + r.outputs.reduce((s2, o) => s2 + Number(o.quantity), 0), 0);
  const totalAcceptedQty = rows.reduce((s, r) => s + r.outputs.reduce((s2, o) => s2 + Number(o.inspection_approved_qty || 0), 0), 0);

  $(cid).innerHTML = `
    <div class="ptitle"><i class="ti ti-certificate" style="color:var(--g-soft)"></i> Value-Added Production</div>
    <div class="psub">Consume timber (or other workshop stock) as input to manufacture finished products — timber treatment (Kiln-dried/CCA), pallets, crates, or any other Product Catalog item.</div>

    <div class="cards">
      <div class="mc"><div class="mclbl">Production batches</div><div class="mcval">${totalBatches.toLocaleString()}</div><div class="mcsub cg"><i class="ti ti-stack-2"></i>total</div></div>
      <div class="mc"><div class="mclbl">Pending QC</div><div class="mcval" style="color:var(--amber)">${pendingQcCount.toLocaleString()}</div><div class="mcsub ca"><i class="ti ti-clock"></i>output lines</div></div>
      <div class="mc"><div class="mclbl">Total output produced</div><div class="mcval" style="color:var(--green)">${totalOutputQty.toLocaleString()}</div><div class="mcsub cg"><i class="ti ti-trees"></i>all products</div></div>
      <div class="mc"><div class="mclbl">Accepted (posted to inventory)</div><div class="mcval">${totalAcceptedQty.toLocaleString()}</div><div class="mcsub cg"><i class="ti ti-check"></i>after QC</div></div>
    </div>

    <div class="card">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem">
        <h3 style="margin-bottom:0"><i class="ti ti-certificate"></i>Production batches</h3>
        <button class="appbtn" id="newVAP"><i class="ti ti-plus" style="font-size:12px;vertical-align:-1px"></i> New batch</button>
      </div>
      <div class="tw"><table class="dt">
        <thead><tr><th>Date</th><th>Type</th><th>Customer</th><th>Inputs</th><th>Outputs</th><th>Recorded by</th><th>Action</th></tr></thead>
        <tbody>
          ${rows.length === 0
            ? '<tr><td colspan="7" style="text-align:center;color:var(--t3);padding:2rem">No production batches yet. Click "New batch" to record one.</td></tr>'
            : rows.map(r => `<tr>
                <td style="font-family:var(--fm);font-weight:500">${r.date_fmt}${r.pending_deletion ? ' <span class="badge br" style="font-size:10px;vertical-align:middle">Pending Deletion</span>' : ''}</td>
                <td>${r.production_type || '<span style="color:var(--t3)">—</span>'}</td>
                <td>${r.customer_name || '<span style="color:var(--t3)">—</span>'}${r.order_reference ? `<div style="font-size:11px;color:var(--t3)">${r.order_reference}</div>` : ''}</td>
                <td style="font-size:12px">${r.inputs.map(i => `${i.stock_item_name} × ${Number(i.quantity).toLocaleString()}`).join('<br>') || '—'}</td>
                <td style="font-size:12px">${r.outputs.map(o => {
                  const label = `${o.type}${o.sub_type ? ' '+o.sub_type : ''} ${o.size} × ${Number(o.quantity).toLocaleString()}`;
                  const badge = o.status === 'inspected'
                    ? `<span class="badge bg">Inspected</span>${o.inspection_approved_qty != null ? ` <span style="color:var(--t3)">${o.inspection_approved_qty} ok / ${o.inspection_rejected_qty} rej</span>` : ''}`
                    : `<span class="badge bp">Pending QC</span> <button class="bs1 vap-inspect" data-id="${o.id}" data-qty="${o.quantity}" data-label="${label}" style="font-size:10px;padding:2px 5px"><i class="ti ti-circle-check"></i></button>`;
                  return `<div style="margin-bottom:2px">${label}${o.rework_of_rejection_id ? ` <span class="badge bb" style="font-size:9px">Rework #${o.rework_of_rejection_id}</span>` : ''}<br>${badge}</div>`;
                }).join('') || '—'}</td>
                <td>${r.created_by_name || '—'}</td>
                <td style="white-space:nowrap">
                  <button class="bs1 vap-edit" data-id="${r.id}"><i class="ti ti-edit"></i>Edit</button>
                  <button class="bs1 vap-del" data-id="${r.id}" style="color:var(--red)"><i class="ti ti-trash"></i></button>
                </td>
              </tr>`).join('')}
        </tbody>
      </table></div>
    </div>

    <div class="card" style="margin-top:1rem">
      <h3><i class="ti ti-recycle"></i>Rejection holds (value-added)</h3>
      <div id="vat-rh-list"><div style="padding:1rem;color:var(--t3);font-size:12px"><i class="ti ti-loader-2" style="animation:spin 1s linear infinite"></i> Loading…</div></div>
    </div>
    <div class="card" style="margin-top:1rem">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem">
        <h3 style="margin-bottom:0"><i class="ti ti-report"></i>Quality report</h3>
        <button class="bs1" id="vapExport" style="font-size:12px"><i class="ti ti-download"></i> Export CSV</button>
      </div>
      <div id="qr-report"><div style="padding:1rem;color:var(--t3);font-size:12px"><i class="ti ti-loader-2" style="animation:spin 1s linear infinite"></i> Loading…</div></div>
    </div>
    <div class="card" style="margin-top:1rem">
      <h3><i class="ti ti-scale"></i>Production reconciliation</h3>
      <div id="vap-reconciliation"><div style="padding:1rem;color:var(--t3);font-size:12px"><i class="ti ti-loader-2" style="animation:spin 1s linear infinite"></i> Loading…</div></div>
    </div>
    <div class="card" style="margin-top:1rem">
      <h3><i class="ti ti-chart-bar"></i>Input consumption / output production</h3>
      <div id="vap-report"><div style="padding:1rem;color:var(--t3);font-size:12px"><i class="ti ti-loader-2" style="animation:spin 1s linear infinite"></i> Loading…</div></div>
    </div>`;

  prependWorkshopBanner($(cid), workshops, () => renderValueAddedProduction(cid));
  await _loadRejectionHolds('vat-rh-list', 'value_added', () => renderValueAddedProduction(cid));
  await _loadQualityReport();
  let _lastVapReconciliation = null, _lastVapReport = null;
  await _loadVapReconciliation();
  await _loadVapReport();
  // ERP Final Enterprise Hardening Phase — Reporting Completion (Priority 6):
  // this page renders qualityReport (qr-report) but, unlike the Sawmill
  // Dashboard, never had any export button at all — VAT-only roles had no
  // way to export these figures. Combines Quality + Reconciliation +
  // Input/Output into one CSV, same "one combined export" pattern Sawmill's
  // own dashboard already established.
  const vapReconRes = await UFCL.valueAddedProductionReconciliation(STORAGE.user.id, WORKSHOP_FILTER);
  if (vapReconRes.ok) _lastVapReconciliation = vapReconRes;
  const vapReportRes = await UFCL.valueAddedProductionReport(STORAGE.user.id, WORKSHOP_FILTER);
  if (vapReportRes.ok) _lastVapReport = vapReportRes;
  const vapExportBtn = $('vapExport');
  if (vapExportBtn) vapExportBtn.onclick = () => {
    const lines = [];
    if (_lastQualityReport) {
      lines.push('Quality,Value',
        `Total Inspected,${_lastQualityReport.quality.totalProduced}`,
        `Accepted,${_lastQualityReport.quality.totalAccepted}`,
        `Rejected,${_lastQualityReport.quality.totalRejected}`,
        `Rejection Rate %,${_lastQualityReport.quality.rejectionRatePct ?? ''}`, '');
    }
    if (_lastVapReconciliation?.rows?.length) {
      lines.push('Reconciliation Date,Input Qty,Output Qty,Accepted,Rejected,Pending QC,Reconciled',
        ..._lastVapReconciliation.rows.map(r => `${r.batchDate},${r.inputQty},${r.outputQty},${r.outputAccepted},${r.outputRejected},${r.outputPendingQc},${r.unitsComparable ? (r.reconciled ? 'Yes' : 'No') : 'Not comparable'}`),
        '');
    }
    if (_lastVapReport) {
      lines.push('Input Item,Total Consumed', ..._lastVapReport.inputConsumption.map(i => `"${i.name.replace(/"/g,'""')}",${i.totalConsumed}`), '');
      lines.push('Output Product,Produced,Accepted', ..._lastVapReport.outputProduction.map(o => `"${(o.type + (o.subType?' '+o.subType:'') + ' ' + o.size).replace(/"/g,'""')}",${o.totalProduced},${o.totalAccepted}`));
    }
    if (!lines.length) { showToast('No report data loaded yet.', 'error'); return; }
    downloadCsv(lines.join('\n'), `vat-production-report-${new Date().toISOString().slice(0,10)}.csv`);
  };

  const wireInputRows = (container, opts) => {
    let idx = container.children.length;
    const addRow = () => { container.insertAdjacentHTML('beforeend', _vapInputRowHtml(idx++, opts)); wireRemove(); };
    const wireRemove = () => {
      container.querySelectorAll('.vap-in-remove').forEach(b => b.onclick = () => {
        if (container.children.length > 1) b.closest('.vap-input-row').remove();
      });
    };
    wireRemove();
    return addRow;
  };
  const wireOutputRows = (container, products) => {
    let idx = container.children.length;
    const addRow = () => { container.insertAdjacentHTML('beforeend', _vapOutputRowHtml(idx++, products)); wireRemove(); };
    const wireRemove = () => {
      container.querySelectorAll('.vap-out-remove').forEach(b => b.onclick = () => {
        if (container.children.length > 1) b.closest('.vap-output-row').remove();
      });
    };
    wireRemove();
    return addRow;
  };

  $('newVAP').onclick = () => {
    const wsPicker = workshopPickerHtml(workshops, 'vap-workshop');
    const custOpts = customers.map(c => `<option value="${c.id}">${c.name}</option>`).join('');
    openOverlay('New Value-Added Production Batch', null, `
      ${wsPicker ? `<div class="frow">${wsPicker}</div>` : ''}
      <div class="frow">
        <div class="fg"><label>Batch date *</label><input type="date" id="vap-date" value="${today}"></div>
        <div class="fg"><label>Production type</label><input type="text" id="vap-type" placeholder="e.g. Kiln-drying, Pallet manufacturing"></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Customer (optional)</label><select id="vap-customer"><option value="">— None —</option>${custOpts}</select></div>
        <div class="fg"><label>Order reference (optional)</label><input type="text" id="vap-order-ref" placeholder="e.g. Customer PO #"></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Operator</label><input type="text" id="vap-operator"></div>
        <div class="fg"><label>Supervisor</label><input type="text" id="vap-supervisor"></div>
      </div>
      <div class="fg full"><label>Notes</label><textarea id="vap-notes" rows="2"></textarea></div>
      <h4 style="margin:.75rem 0 .25rem">Input material (consumed from stock)</h4>
      <div id="vap-input-rows">${_vapInputRowHtml(0, availableInputs)}</div>
      <button type="button" class="bs1" id="vap-add-input" style="margin-bottom:.75rem"><i class="ti ti-plus"></i> Add input</button>
      <h4 style="margin:.75rem 0 .25rem">Output product(s)</h4>
      <div id="vap-output-rows">${_vapOutputRowHtml(0, activeProducts)}</div>
      <button type="button" class="bs1" id="vap-add-output" style="margin-bottom:.75rem"><i class="ti ti-plus"></i> Add output</button>
      <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-device-floppy"></i>Save</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
      async () => {
        const inputs = [...document.querySelectorAll('.vap-input-row')].map(row => ({
          stock_item_id: row.querySelector('.vap-in-item').value,
          quantity: row.querySelector('.vap-in-qty').value,
        })).filter(i => i.stock_item_id && i.quantity);
        const outputs = [...document.querySelectorAll('.vap-output-row')].map(row => ({
          output_product_id: row.querySelector('.vap-out-product').value,
          quantity: row.querySelector('.vap-out-qty').value,
        })).filter(o => o.output_product_id && o.quantity);
        const r = await UFCL.valueAddedProductionCreate(STORAGE.user.id, {
          batch_date: $('vap-date').value,
          production_type: $('vap-type').value.trim() || null,
          customer_id: $('vap-customer')?.value || null,
          order_reference: $('vap-order-ref').value.trim() || null,
          operator: $('vap-operator').value.trim() || null,
          supervisor: $('vap-supervisor').value.trim() || null,
          notes: $('vap-notes').value.trim() || null,
          workshop_id: $('vap-workshop')?.value || null,
          inputs, outputs,
        });
        if (!r.ok) { showOverlayError(r.error); return; }
        showOverlaySuccess('Production batch saved.'); await renderValueAddedProduction(cid);
      }
    );
    setTimeout(() => {
      const inputRowsEl = document.getElementById('vap-input-rows');
      const outputRowsEl = document.getElementById('vap-output-rows');
      if (inputRowsEl) { const add = wireInputRows(inputRowsEl, availableInputs); document.getElementById('vap-add-input').onclick = add; }
      if (outputRowsEl) { const add = wireOutputRows(outputRowsEl, activeProducts); document.getElementById('vap-add-output').onclick = add; }
    }, 50);
  };

  document.querySelectorAll('.vap-edit').forEach(btn => {
    btn.onclick = async () => {
      const r = rows.find(x => x.id === btn.dataset.id);
      if (!r) return;
      const isoDate = r.date_fmt.split('/').reverse().join('-');
      const custOpts = customers.map(c => `<option value="${c.id}" ${String(r.customer_id) === String(c.id) ? 'selected' : ''}>${c.name}</option>`).join('');
      openOverlay('Edit Production Batch', r.date_fmt, `
        <div class="frow">
          <div class="fg"><label>Batch date *</label><input type="date" id="vap-date" value="${isoDate}"></div>
          <div class="fg"><label>Production type</label><input type="text" id="vap-type" value="${r.production_type || ''}"></div>
        </div>
        <div class="frow">
          <div class="fg"><label>Customer</label><select id="vap-customer"><option value="">— None —</option>${custOpts}</select></div>
          <div class="fg"><label>Order reference</label><input type="text" id="vap-order-ref" value="${r.order_reference || ''}"></div>
        </div>
        <div class="frow">
          <div class="fg"><label>Operator</label><input type="text" id="vap-operator" value="${r.operator || ''}"></div>
          <div class="fg"><label>Supervisor</label><input type="text" id="vap-supervisor" value="${r.supervisor || ''}"></div>
        </div>
        <div class="fg full"><label>Notes</label><textarea id="vap-notes" rows="2">${r.notes || ''}</textarea></div>
        <div style="font-size:12px;color:var(--t3);margin-bottom:.5rem">Input/output lines cannot be edited here (they already have real stock/QC consequences) — delete and recreate the batch if a line was wrong.</div>
        <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-device-floppy"></i>Save</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
        async () => {
          const payload = {
            batch_date: $('vap-date').value,
            production_type: $('vap-type').value.trim() || null,
            customer_id: $('vap-customer').value || null,
            order_reference: $('vap-order-ref').value.trim() || null,
            operator: $('vap-operator').value.trim() || null,
            supervisor: $('vap-supervisor').value.trim() || null,
            notes: $('vap-notes').value.trim() || null,
          };
          if (isSupervisor()) {
            const r2 = await UFCL.pendingEditsCreate(STORAGE.user.id, {
              action_type: 'edit', entity_type: 'value_added_production_batch',
              entity_id: r.id, entity_ref: `Batch ${r.date_fmt}`, payload
            });
            if (!r2.ok) { showOverlayError(r2.error); return; }
            showOverlaySuccess('Change submitted for approval.'); closeOverlay(); await renderValueAddedProduction(cid);
          } else {
            const res2 = await UFCL.valueAddedProductionUpdate(STORAGE.user.id, r.id, payload);
            if (!res2.ok) { showOverlayError(res2.error); return; }
            showOverlaySuccess('Batch updated.'); await renderValueAddedProduction(cid);
          }
        }
      );
    };
  });

  document.querySelectorAll('.vap-del').forEach(btn => {
    btn.onclick = () => {
      const r = rows.find(x => x.id === btn.dataset.id);
      if (!r) return;
      if (isSupervisor()) {
        confirmDeleteSoft(`Submit delete request for production batch <strong>${r.date_fmt}</strong>? A manager must approve before it is moved to Trash and its input stock reversed.`, async (reason) => {
          const r2 = await UFCL.deletionRequestCreate(STORAGE.user.id, 'value_added_production_batch', r.id, 'value_added_production_batch', `Batch ${r.date_fmt}`, reason);
          if (!r2.ok) { showOverlayError(r2.error); return; }
          showOverlaySuccess('Deletion request submitted for approval.'); await renderValueAddedProduction(cid);
        });
      } else {
        confirmDeleteSoft(`Move production batch <strong>${r.date_fmt}</strong> to Trash? Its input stock consumption will be reversed.`, async (reason) => {
          const res2 = await UFCL.valueAddedProductionDelete(STORAGE.user.id, btn.dataset.id, reason);
          if (!res2.ok) { showOverlayError(res2.error); return; }
          showOverlaySuccess('Batch moved to Trash — input stock reversed.'); await renderValueAddedProduction(cid);
        });
      }
    };
  });

  document.querySelectorAll('.vap-inspect').forEach(btn => {
    btn.onclick = () => {
      const outputId = Number(btn.dataset.id);
      const maxQty = Number(btn.dataset.qty);
      openOverlay('Value-Added Quality Inspection', `${btn.dataset.label} — quantity to inspect: ${maxQty}`, `
        <div class="frow">
          <div class="fg"><label>Approved Quantity *</label><input type="number" id="qi-approved" min="0" max="${maxQty}" value="${maxQty}"></div>
        </div>
        <div class="frow full"><div class="fg"><label>Rejection Reason (if any)</label><input type="text" id="qi-reason" placeholder="Optional"></div></div>
        <div class="frow full"><div class="fg"><label>Notes</label><textarea id="qi-notes" rows="2"></textarea></div></div>
        <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-circle-check"></i>Complete Inspection</button><button class="bs1" id="ovCancel">Cancel</button></div>
      `, async () => {
        const approved = Number($('qi-approved').value);
        if (approved < 0 || approved > maxQty) return showOverlayError(`Approved quantity must be between 0 and ${maxQty}.`);
        const r = await UFCL.valueAddedProductionInspect(STORAGE.user.id, outputId, {
          approved_qty: approved, rejection_reason: $('qi-reason').value.trim() || undefined, notes: $('qi-notes').value.trim() || undefined,
        });
        if (!r.ok) return showOverlayError(r.error || 'Failed to complete inspection.');
        closeOverlay();
        const msgParts = [];
        if (r.approvedPosted) msgParts.push(`${approved} accepted → posted to inventory`);
        else if (approved > 0) msgParts.push(`${approved} accepted (no catalog stock link — not posted)`);
        if (r.rejectionHoldId) msgParts.push(`${maxQty - approved} rejected → Rejection Hold #${r.rejectionHoldId}`);
        showToast(`Quality inspection completed. ${msgParts.join('; ')}.`, 'success');
        await renderValueAddedProduction(cid);
      });
    };
  });

  await insertPendingPanel($(cid), ['value_added_production_batch'], () => renderValueAddedProduction(cid));
  await insertDeletionPanel($(cid), ['value_added_production_batch'], () => renderValueAddedProduction(cid));
}

// Input Consumption / Output Production report — deliberately separate from
// _loadQualityReport (rejection/rework/downgrade already generically covers
// Nyanza when workshop-filtered); this covers what that report doesn't: raw
// material consumed and finished output produced, by item/product.
// ERP Enterprise Completion Phase 9 (Workstream 1) — a fresh backend-to-UI
// audit found valueAddedProductionReconciliation fully built (backend + IPC
// + REST + a mobile hook) but never actually wired into any screen on
// either platform since the Nyanza Value-Added Production phase built it —
// wiring it in now on both desktop and mobile.
async function _loadVapReconciliation() {
  const el = $('vap-reconciliation');
  if (!el) return;
  const res = await UFCL.valueAddedProductionReconciliation(STORAGE.user.id, WORKSHOP_FILTER);
  if (!res.ok) { el.innerHTML = `<div style="color:var(--red);font-size:12px">${res.error}</div>`; return; }
  const rows = res.rows || [];
  el.innerHTML = `
    <div class="cards" style="margin:0 0 .75rem">
      <div class="mc"><div class="mclbl">Batches checked</div><div class="mcval">${rows.length.toLocaleString()}</div></div>
      <div class="mc"><div class="mclbl">Unreconciled</div><div class="mcval" style="color:${res.unreconciledCount>0?'var(--red)':'var(--green)'}">${res.unreconciledCount.toLocaleString()}</div></div>
    </div>
    ${rows.length ? `<div class="tw"><table class="dt">
      <thead><tr><th>Date</th><th>Input qty</th><th>Output qty</th><th>Accepted</th><th>Rejected</th><th>Pending QC</th><th>Status</th></tr></thead>
      <tbody>${rows.map(r => `<tr>
        <td style="font-family:var(--fm)">${r.batchDate}</td>
        <td style="font-family:var(--fm)">${r.inputQty.toLocaleString()}</td>
        <td style="font-family:var(--fm)">${r.outputQty.toLocaleString()}</td>
        <td style="font-family:var(--fm);color:var(--green)">${r.outputAccepted.toLocaleString()}</td>
        <td style="font-family:var(--fm);color:${r.outputRejected>0?'var(--red)':'inherit'}">${r.outputRejected.toLocaleString()}</td>
        <td style="font-family:var(--fm);color:${r.outputPendingQc>0?'var(--amber)':'inherit'}">${r.outputPendingQc.toLocaleString()}</td>
        <td>${!r.unitsComparable
          ? `<span class="badge bt" title="${r.note}">Not comparable</span>`
          : (r.reconciled ? '<span class="badge bg">Reconciled</span>' : '<span class="badge br">Different units</span>')}
        </td>
      </tr>`).join('')}</tbody>
    </table></div>` : '<div style="font-size:12px;color:var(--t3)">No production batches to reconcile yet.</div>'}
  `;
}

async function _loadVapReport() {
  const el = $('vap-report');
  if (!el) return;
  const res = await UFCL.valueAddedProductionReport(STORAGE.user.id, WORKSHOP_FILTER);
  if (!res.ok) { el.innerHTML = `<div style="color:var(--red);font-size:12px">${res.error}</div>`; return; }
  el.innerHTML = `
    <div class="cards" style="margin:0 0 .75rem">
      <div class="mc"><div class="mclbl">Production batches</div><div class="mcval">${res.batchCount.toLocaleString()}</div></div>
    </div>
    <div class="frow">
      <div style="flex:1;min-width:280px">
        <h4 style="margin-bottom:.5rem">Input consumed</h4>
        <div class="tw"><table class="dt">
          <thead><tr><th>Item</th><th>Total consumed</th></tr></thead>
          <tbody>${res.inputConsumption.length ? res.inputConsumption.map(i => `<tr><td>${i.name}</td><td style="font-family:var(--fm);font-weight:600">${i.totalConsumed.toLocaleString()}</td></tr>`).join('') : '<tr><td colspan="2" style="color:var(--t3)">No input consumption yet.</td></tr>'}</tbody>
        </table></div>
      </div>
      <div style="flex:1;min-width:280px">
        <h4 style="margin-bottom:.5rem">Output produced</h4>
        <div class="tw"><table class="dt">
          <thead><tr><th>Product</th><th>Produced</th><th>Accepted</th></tr></thead>
          <tbody>${res.outputProduction.length ? res.outputProduction.map(o => `<tr><td>${o.type}${o.subType ? ' '+o.subType : ''} ${o.size}</td><td style="font-family:var(--fm);font-weight:600">${o.totalProduced.toLocaleString()}</td><td style="font-family:var(--fm);color:var(--green)">${o.totalAccepted.toLocaleString()}</td></tr>`).join('') : '<tr><td colspan="3" style="color:var(--t3)">No output produced yet.</td></tr>'}</tbody>
        </table></div>
      </div>
    </div>`;
}

// ── Showroom ───────────────────────────────────────────────────────────────────
// Timber Lifecycle Phase 3 (Workstream 12/13) — the audit found NO existing
// Showroom-specific backend/UI beyond a warehouse row, a role, and a
// read-only "Available at Showroom" figure on Timber Inventory. This page is
// therefore genuinely new: inventory (reusing the existing stock_catalog/
// stock_levels bridge, warehouse_id=5, no new inventory system), Damage
// reporting (Workstream 12's Condition Check -> GOOD/DAMAGED -> Resolution,
// deliberately NOT a second write-off mechanism — reuses openResolutionModal,
// the same Resolution Engine every other waste/rejection path uses), and a
// link to Sales Orders rather than a duplicate sale form — that page already
// works generically for any workshop, Showroom included.
async function renderShowroom(cid='page-showroom') {
  $(cid).innerHTML = `<div style="padding:2rem;color:var(--t3);font-size:13px"><i class="ti ti-loader-2" style="font-size:18px;animation:spin 1s linear infinite"></i> Loading…</div>`;
  const [invRes, dmgRes] = await Promise.all([
    UFCL.showroomInventoryList(STORAGE.user.id),
    UFCL.showroomDamageList(STORAGE.user.id, null),
  ]);
  if (!invRes.ok) return renderDenied('showroom', invRes.error);
  const rows = invRes.rows || [];
  const dmgRows = dmgRes.ok ? dmgRes.rows : [];
  const totalUnits = rows.reduce((s, r) => s + Number(r.stock), 0);
  const totalValue = rows.reduce((s, r) => s + Number(r.stock) * Number(r.unit_cost || 0), 0);
  const pendingDamage = dmgRows.filter(d => d.status === 'pending');

  $(cid).innerHTML = `
    <div class="ptitle"><i class="ti ti-building-store" style="color:var(--g-soft)"></i> Showroom</div>
    <div class="psub">Showroom stock, condition/damage checks, and sales. Direct sale happens on the Sales Orders page — select "Showroom" as the workshop there.</div>

    <div class="cards">
      <div class="mc"><div class="mclbl">Items in stock</div><div class="mcval">${rows.length.toLocaleString()}</div><div class="mcsub cg"><i class="ti ti-package"></i>catalogue lines</div></div>
      <div class="mc"><div class="mclbl">Total units</div><div class="mcval" style="color:var(--green)">${totalUnits.toLocaleString()}</div><div class="mcsub cg"><i class="ti ti-stack"></i>pieces</div></div>
      <div class="mc"><div class="mclbl">Stock value</div><div class="mcval">${_fmtCur(totalValue)}</div><div class="mcsub cg"><i class="ti ti-coin"></i>at unit cost</div></div>
      <div class="mc"><div class="mclbl">Pending damage reports</div><div class="mcval" style="color:${pendingDamage.length ? 'var(--red)' : 'inherit'}">${pendingDamage.length}</div><div class="mcsub ${pendingDamage.length ? 'ca' : 'cg'}"><i class="ti ti-alert-triangle"></i>awaiting resolution</div></div>
    </div>

    <div class="card">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem">
        <h3 style="margin-bottom:0"><i class="ti ti-package"></i>Showroom inventory</h3>
        <button class="appbtn" id="newDamage"><i class="ti ti-alert-triangle" style="font-size:12px;vertical-align:-1px"></i> Report damage</button>
      </div>
      <div class="tw"><table class="dt">
        <thead><tr><th>Item</th><th>Category</th><th>SKU</th><th>Stock</th><th>Unit cost (RWF)</th><th>Value (RWF)</th></tr></thead>
        <tbody>
          ${rows.length === 0
            ? '<tr><td colspan="6" style="text-align:center;color:var(--t3);padding:2rem">No stock at the Showroom yet — receive a Stock Transfer first.</td></tr>'
            : rows.map(r => `<tr>
                <td style="font-weight:600;color:var(--g-dark)">${r.name}</td>
                <td>${r.category}</td>
                <td style="color:var(--t3);font-size:12px">${r.sku || '—'}</td>
                <td style="font-family:var(--fm);font-weight:600">${Number(r.stock).toLocaleString()}</td>
                <td style="font-family:var(--fm)">${Number(r.unit_cost || 0).toLocaleString()}</td>
                <td style="font-family:var(--fm)">${Math.round(Number(r.stock) * Number(r.unit_cost || 0)).toLocaleString()}</td>
              </tr>`).join('')}
        </tbody>
      </table></div>
    </div>

    <div class="card" style="margin-top:1rem">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.5rem">
        <h3 style="margin-bottom:0"><i class="ti ti-alert-triangle"></i>Damage reports</h3>
        <button class="bs1 sd-history" style="font-size:11px;padding:3px 8px"><i class="ti ti-history"></i> Resolution History</button>
      </div>
      <div class="tw"><table class="dt">
        <thead><tr><th>Reported</th><th>Item</th><th>Qty</th><th>Reason</th><th>Status</th><th></th></tr></thead>
        <tbody>
          ${dmgRows.length === 0
            ? '<tr><td colspan="6" style="text-align:center;color:var(--t3);padding:1.5rem">No damage reported.</td></tr>'
            : dmgRows.map(d => `<tr>
                <td style="font-family:var(--fm);font-size:12px">${new Date(d.created_at).toLocaleDateString()}</td>
                <td>${d.stock_item_name || '—'}</td>
                <td style="font-family:var(--fm);font-weight:600">${d.quantity}</td>
                <td style="color:var(--t3);max-width:200px">${d.reason}</td>
                <td>${d.status === 'pending' ? '<span class="badge br">Pending</span>' : '<span class="badge bg">Resolved</span>'}</td>
                <td style="white-space:nowrap">${d.status === 'pending' ? `<button class="bs1 dmg-resolve" data-id="${d.id}" data-qty="${d.quantity}" style="font-size:11px;padding:3px 6px"><i class="ti ti-recycle"></i> Resolve</button>` : ''}</td>
              </tr>`).join('')}
        </tbody>
      </table></div>
    </div>`;

  document.querySelectorAll('.sd-history').forEach(btn => {
    btn.onclick = () => openResolutionHistoryModal('showroom_damage');
  });

  $('newDamage').onclick = () => {
    if (!rows.length) return showToast('No showroom stock to report as damaged.', 'error');
    openOverlay('Report Damaged Stock', 'Removes the reported quantity from sellable Showroom stock immediately.', `
      <div class="frow full"><div class="fg"><label>Item *</label><select id="dmg-item">${rows.map(r => `<option value="${r.id}" data-avail="${r.stock}">${r.name} — ${Number(r.stock).toLocaleString()} available</option>`).join('')}</select></div></div>
      <div class="frow full"><div class="fg"><label>Quantity *</label><input type="number" id="dmg-qty" min="1" value="1"></div></div>
      <div class="frow full"><div class="fg"><label>Reason *</label><textarea id="dmg-reason" rows="2" placeholder="e.g. water damage, cracked, mishandled"></textarea></div></div>
      <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-alert-triangle"></i>Report Damage</button><button class="bs1" id="ovCancel">Cancel</button></div>
    `, async () => {
      const itemSel = $('dmg-item');
      const avail = Number(itemSel.selectedOptions[0].dataset.avail);
      const qty = Number($('dmg-qty').value);
      const reason = $('dmg-reason').value.trim();
      if (!qty || qty <= 0 || qty > avail) return showOverlayError(`Quantity must be between 1 and ${avail}.`);
      if (!reason) return showOverlayError('A reason is required.');
      const r = await UFCL.showroomDamageCreate(STORAGE.user.id, { stock_item_id: itemSel.value, warehouse_id: 5, quantity: qty, reason });
      if (!r.ok) return showOverlayError(r.error || 'Failed to report damage.');
      closeOverlay();
      showToast('Damage reported — removed from sellable stock, pending resolution.', 'success');
      await renderShowroom(cid);
    });
  };

  document.querySelectorAll('.dmg-resolve').forEach(btn => {
    btn.onclick = () => openResolutionModal('showroom_damage', Number(btn.dataset.id), Number(btn.dataset.qty), () => renderShowroom(cid));
  });
}

// ── Machine Maintenance Schedule ────────────────────────────────────────────────
// Mechanician Phase 2 (Priority 3) — the missing cross-machine Maintenance
// Schedule screen identified in MECHANICIAN_PHASE2_OPERATIONAL_AUDIT.md §8.
// Creation (with its machine picker) stays on the existing per-machine
// overlay in Machine Registry, unchanged — this page adds the visibility
// that never existed, plus quick edit/delete for users who already hold
// 'machines' (reusing the exact same machineMaintUpdate/Delete calls that
// overlay already uses).

const MACHINE_DUE_STATUS_META = {
  overdue:   { cls: 'br', label: 'Overdue' },
  'due-soon': { cls: 'ba', label: 'Due Soon' },
  ok:        { cls: 'bg', label: 'OK' },
};
async function renderMachineMaintenance() {
  const pg = $('page-machine-maintenance');
  pg.innerHTML = `<div style="padding:2rem;color:var(--t3);font-size:13px"><i class="ti ti-loader-2" style="font-size:18px;animation:spin 1s linear infinite"></i> Loading…</div>`;

  const res = await UFCL.machineMaintListAll(STORAGE.user.id);
  if (!res.ok) return renderDenied('machine-maintenance', res.error);

  const rows = res.rows || [];
  const canManage = !!res.canManage;
  const today = new Date(); today.setHours(0,0,0,0);
  const soon = new Date(today.getTime() + 14 * 86400000);

  const rowStatus = (r) => {
    if (!r.next_due) return 'ok';
    const due = new Date(r.next_due);
    if (due < today) return 'overdue';
    if (due <= soon) return 'due-soon';
    return 'ok';
  };
  const statusBadge = (s) => badgeHtml(MACHINE_DUE_STATUS_META, s, MACHINE_DUE_STATUS_META.ok);

  const overdueCount = rows.filter(r => rowStatus(r) === 'overdue').length;
  const dueSoonCount = rows.filter(r => rowStatus(r) === 'due-soon').length;

  const mmState = { search: '', status: '', selected: new Set() };
  const mmSort = { key: null, dir: 'asc' };
  function mmFiltered() {
    const withStatus = rows.map(r => ({ ...r, _statusKey: rowStatus(r) }));
    return applyProcListFilters(withStatus, {
      search: mmState.search, searchFields: ['machine_name', 'machine_code', 'maintenance_type', 'notes'],
      status: mmState.status, statusField: '_statusKey',
    });
  }

  pg.innerHTML = `
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;margin-bottom:1.5rem">
      <div>
        <div class="ptitle"><i class="ti ti-calendar-time" style="color:var(--g-soft)"></i> Maintenance Schedule</div>
        <div class="psub">Recurring maintenance across every machine in scope.</div>
      </div>
    </div>
    <div class="cards" style="margin-bottom:1.25rem">
      <div class="mc"><div class="mclbl">Total Schedules</div><div class="mcval">${rows.length}</div><div class="mcsub cg"><i class="ti ti-calendar-time"></i>tracked</div></div>
      <div class="mc"><div class="mclbl">Overdue</div><div class="mcval" style="${overdueCount>0?'color:var(--red)':''}">${overdueCount}</div><div class="mcsub ${overdueCount>0?'cr':''}"><i class="ti ti-alert-triangle"></i>past due date</div></div>
      <div class="mc"><div class="mclbl">Due Soon</div><div class="mcval" style="${dueSoonCount>0?'color:var(--amber)':''}">${dueSoonCount}</div><div class="mcsub ${dueSoonCount>0?'ca':'cg'}"><i class="ti ti-clock"></i>next 14 days</div></div>
    </div>
    ${procFilterBarHtml({
      searchId: 'mm-search', searchPlaceholder: 'Search machine, type, notes…',
      clearId: 'mm-clear',
      extraHtml: `<select id="mm-status-filter" class="filter-select">
        <option value="">All statuses</option>
        <option value="overdue">Overdue</option>
        <option value="due-soon">Due Soon</option>
        <option value="ok">OK</option>
      </select>`,
    })}
    <div class="card" style="padding:0">
      <div style="display:flex;align-items:center;justify-content:space-between;padding:1rem 1.25rem;border-bottom:1px solid var(--bdr)">
        <h3 style="margin:0"><i class="ti ti-calendar-time"></i>Schedules</h3>
        <span id="mm-count-label" style="font-size:12px;color:var(--t3)">${rows.length} schedule${rows.length!==1?'s':''}</span>
      </div>
      <div class="tw"><table class="dt" id="mm-table">
        <thead><tr>
          <th data-sort-key="machine_name">Machine</th>
          <th data-sort-key="maintenance_type">Type</th>
          <th data-sort-key="frequency_days">Frequency</th>
          <th data-sort-key="last_performed">Last Performed</th>
          <th data-sort-key="next_due">Next Due</th>
          <th data-sort-key="estimated_hours">Est. Hrs</th>
          <th>Status</th>
          ${canManage ? '<th></th>' : ''}
        </tr></thead>
        <tbody id="mm-tbody"></tbody>
      </table></div>
    </div>
  `;

  function renderMmRows(list) {
    const tbody = $('mm-tbody');
    if (!list.length) {
      tbody.innerHTML = `<tr><td colspan="${canManage?8:7}" style="text-align:center;color:var(--t3);padding:3rem"><i class="ti ti-calendar-time" style="font-size:2rem;display:block;margin-bottom:.5rem;opacity:.35"></i>No maintenance schedules match these filters.</td></tr>`;
      $('mm-count-label').textContent = '0 schedules';
      return;
    }
    $('mm-count-label').textContent = `${list.length} schedule${list.length!==1?'s':''}`;
    tbody.innerHTML = list.map(r => `<tr>
      <td style="font-weight:500">${r.machine_code} — ${r.machine_name}</td>
      <td>${r.maintenance_type}</td>
      <td>${r.frequency_days}d</td>
      <td>${r.last_performed ? new Date(r.last_performed).toLocaleDateString('en-GB') : '—'}</td>
      <td style="${r._statusKey==='overdue'?'color:var(--red);font-weight:600':r._statusKey==='due-soon'?'color:var(--amber);font-weight:600':''}">${r.next_due ? new Date(r.next_due).toLocaleDateString('en-GB') : '—'}</td>
      <td>${r.estimated_hours}h</td>
      <td>${statusBadge(r._statusKey)}</td>
      ${canManage ? `<td style="white-space:nowrap">
        <button class="bs1 mm-edit" data-id="${r.id}" style="padding:3px 7px;font-size:12px"><i class="ti ti-edit"></i></button>
        <button class="bs1 mm-del" data-id="${r.id}" style="padding:3px 7px;font-size:12px;color:var(--red)"><i class="ti ti-trash"></i></button>
      </td>` : ''}
    </tr>`).join('');

    if (canManage) {
      tbody.querySelectorAll('.mm-edit').forEach(btn => {
        btn.onclick = () => {
          const r = list.find(x => String(x.id) === btn.dataset.id);
          if (!r) return;
          openOverlay('Edit maintenance schedule', `${r.machine_code} — ${r.machine_name}`, `
            <div class="frow">
              <div class="fg"><label>Type *</label><input id="mme-type" type="text" value="${r.maintenance_type}"></div>
              <div class="fg"><label>Frequency (days)</label><input id="mme-freq" type="number" min="1" value="${r.frequency_days}"></div>
            </div>
            <div class="frow">
              <div class="fg"><label>Last Performed</label><input id="mme-last" type="date" value="${r.last_performed?String(r.last_performed).slice(0,10):''}"></div>
              <div class="fg"><label>Next Due</label><input id="mme-next" type="date" value="${r.next_due?String(r.next_due).slice(0,10):''}"></div>
            </div>
            <div class="frow">
              <div class="fg"><label>Est. Hours</label><input id="mme-hours" type="number" min="0.5" step="0.5" value="${r.estimated_hours}"></div>
              <div class="fg"><label>Notes</label><input id="mme-notes" type="text" value="${r.notes||''}"></div>
            </div>
            <div class="brow"><button class="bp1" id="ovSave">Save</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
            async () => {
              const r2 = await UFCL.machineMaintUpdate(STORAGE.user.id, r.id, {
                maintenance_type: $('mme-type').value.trim(),
                frequency_days: $('mme-freq').value || 30,
                last_performed: $('mme-last').value || null,
                next_due: $('mme-next').value || null,
                estimated_hours: $('mme-hours').value || 1,
                notes: $('mme-notes').value.trim(),
              });
              if (!r2.ok) { showOverlayError(r2.error); return; }
              showOverlaySuccess('Schedule updated.');
              await renderMachineMaintenance();
            });
        };
      });
      tbody.querySelectorAll('.mm-del').forEach(btn => {
        btn.onclick = () => {
          confirmDelete('Delete this maintenance schedule entry?', async () => {
            const r2 = await UFCL.machineMaintDelete(STORAGE.user.id, Number(btn.dataset.id));
            if (!r2.ok) { showOverlayError(r2.error); return; }
            showOverlaySuccess('Schedule deleted.');
            await renderMachineMaintenance();
          });
        };
      });
    }
  }

  renderMmRows(mmFiltered());
  wireSortableTable($('mm-table'), mmSort, mmFiltered, renderMmRows);
  $('mm-search').oninput = (e) => { mmState.search = e.target.value; renderMmRows(mmFiltered()); };
  $('mm-status-filter').onchange = (e) => { mmState.status = e.target.value; renderMmRows(mmFiltered()); };
  $('mm-clear').onclick = () => { mmState.search=''; mmState.status=''; $('mm-search').value=''; $('mm-status-filter').value=''; renderMmRows(mmFiltered()); };
}

// ── Maintenance Jobs (Mechanician Phase 3) ──────────────────────────────────────
// Genuine job lifecycle over the existing machines table — integrates with
// (not duplicating) Material Requests -> Stock Transfers -> Inventory
// consumption, which is completely untouched by this section.

// Shared status-badge renderer (Enterprise UI/UX Standardization Phase 1,
// Workstream A) — every status-meta registry uses the {cls, icon, label}
// shape; icon is optional (omit it to render a plain text badge, matching
// registries that never had icons, e.g. MAINT_JOB_STATUS_META).
function badgeHtml(metaMap, status, fallbackMeta) {
  const meta = metaMap[status] ?? fallbackMeta;
  const icon = meta.icon ? `<i class="ti ${meta.icon}"></i>` : '';
  const cls = meta.icon ? `${meta.cls} badge-ic` : meta.cls;
  return `<span class="badge ${cls}">${icon}${meta.label}</span>`;
}

const MAINT_JOB_STATUS_META = {
  inspection:          { label: 'Inspection',          cls: 'bt' },
  diagnosis:           { label: 'Diagnosis',            cls: 'bp' },
  assigned:            { label: 'Assigned',             cls: 'bb' },
  in_progress:         { label: 'In Progress',          cls: 'ba' },
  waiting_parts:       { label: 'Waiting for Parts',    cls: 'br' },
  external_repair:     { label: 'External Repair',      cls: 'br' },
  testing:             { label: 'Testing',              cls: 'bp' },
  returned_to_service: { label: 'Returned to Service',  cls: 'bg' },
  closed:              { label: 'Closed',               cls: 'bg' },
  cancelled:           { label: 'Cancelled',             cls: 'br' },
};
function _mjStatusBadge(status) {
  return badgeHtml(MAINT_JOB_STATUS_META, status, { label: status, cls: 'bt' });
}

// Mechanician Phase 4 (Priority 5) — reuses _statusTimelineHtml's existing
// linear-stage visual language as-is for the normal path; the two "detour"
// states (waiting_parts / external_repair) don't have a linear index, so
// they're spliced in as an extra badge right after In Progress rather than
// building a whole new timeline component.
const MAINT_TIMELINE_STAGES = ['inspection', 'diagnosis', 'assigned', 'in_progress', 'testing', 'returned_to_service', 'closed'];
function _mjTimelineHtml(status) {
  if (status === 'cancelled') {
    return `<div class="frow" style="gap:.5rem;align-items:center">
      <span class="badge br">Cancelled</span>
      <span style="font-size:12px;color:var(--t3)">This job left the normal flow.</span>
    </div>`;
  }
  const labels = MAINT_TIMELINE_STAGES.map(s => MAINT_JOB_STATUS_META[s].label);
  if (!['waiting_parts', 'external_repair'].includes(status)) {
    return _statusTimelineHtml(labels, MAINT_JOB_STATUS_META[status]?.label || status, []);
  }
  const detourIdx = MAINT_TIMELINE_STAGES.indexOf('in_progress');
  const meta = MAINT_JOB_STATUS_META[status];
  const nodes = MAINT_TIMELINE_STAGES.map((s, i) =>
    `<span class="badge ${i <= detourIdx ? 'bg' : 'bn'}">${i <= detourIdx ? '<i class="ti ti-check" style="font-size:10px"></i> ' : ''}${labels[i]}</span>`);
  nodes.splice(detourIdx + 1, 0, `<span class="badge ${status === 'waiting_parts' ? 'ca' : 'cr'}">${meta.label}</span>`);
  return `<div class="frow" style="gap:.35rem;align-items:center;flex-wrap:wrap">
    ${nodes.join('<i class="ti ti-arrow-right" style="color:var(--t4);font-size:12px"></i>')}
  </div>`;
}

// Mechanician Phase 4 (Priority 2) — Work Queue is now the default landing
// view (jobs grouped by operational state, "which jobs are waiting/blocked"
// answered at a glance) with the existing search/filter/sort table kept as a
// one-click toggle, not removed — Priority 12 explicitly forbids removing
// existing capability. `initialStatus` supports deep-linking from the
// dashboard's status strip straight into a filtered table view.
const MAINT_QUEUE_ORDER = ['inspection', 'diagnosis', 'assigned', 'in_progress', 'waiting_parts', 'external_repair', 'testing', 'returned_to_service'];

async function renderMaintenanceJobs(initialStatus) {
  const pg = $('page-maintenance-jobs');
  pg.innerHTML = `<div style="padding:2rem;color:var(--t3);font-size:13px"><i class="ti ti-loader-2" style="font-size:18px;animation:spin 1s linear infinite"></i> Loading…</div>`;

  const res = await UFCL.maintenanceJobsList(STORAGE.user.id, {});
  if (!res.ok) return renderDenied('maintenance-jobs', res.error);
  const rows = res.rows || [];
  const canManage = !!res.canManage;

  const openCount = rows.filter(r => !['closed', 'cancelled'].includes(r.status)).length;
  const waitingCount = rows.filter(r => r.status === 'waiting_parts').length;
  const externalCount = rows.filter(r => r.status === 'external_repair').length;
  const mineCount = rows.filter(r => String(r.assigned_to) === String(STORAGE.user.id) && !['closed', 'cancelled'].includes(r.status)).length;

  const mjState = { search: '', status: initialStatus || '', selected: new Set() };
  const mjSort = { key: null, dir: 'asc' };
  const viewState = { mode: initialStatus ? 'table' : 'queue' };
  function mjFiltered() {
    return applyProcListFilters(rows, {
      search: mjState.search, searchFields: ['title', 'machine_code', 'machine_name', 'assigned_to_name'],
      status: mjState.status, statusField: 'status',
    });
  }

  pg.innerHTML = `
    <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:1rem;margin-bottom:1.5rem">
      <div>
        <div class="ptitle"><i class="ti ti-clipboard-list" style="color:var(--g-soft)"></i> Maintenance Jobs</div>
        <div class="psub">Full maintenance lifecycle — inspection through return to service.</div>
      </div>
      <div style="display:flex;gap:.5rem;flex-shrink:0;flex-wrap:wrap">
        <div class="brow" style="gap:0;border:1px solid var(--bdr);border-radius:7px;overflow:hidden">
          <button class="bs1" id="mjViewQueue" style="border-radius:0;${viewState.mode==='queue'?'background:var(--bg2)':''}"><i class="ti ti-layout-kanban"></i>Work Queue</button>
          <button class="bs1" id="mjViewTable" style="border-radius:0;border-left:1px solid var(--bdr);${viewState.mode==='table'?'background:var(--bg2)':''}"><i class="ti ti-table"></i>Table</button>
          <button class="bs1" id="mjViewWaiting" style="border-radius:0;border-left:1px solid var(--bdr);${viewState.mode==='waiting'?'background:var(--bg2)':''}"><i class="ti ti-hourglass"></i>Waiting for Parts</button>
          <button class="bs1" id="mjViewExternal" style="border-radius:0;border-left:1px solid var(--bdr);${viewState.mode==='external'?'background:var(--bg2)':''}"><i class="ti ti-truck-delivery"></i>External Repair</button>
        </div>
        ${canManage ? `<button class="bp1" id="mjAdd"><i class="ti ti-plus"></i>New job</button>` : ''}
      </div>
    </div>
    <div class="cards" style="margin-bottom:1.25rem">
      <div class="mc"><div class="mclbl">Open Jobs</div><div class="mcval">${openCount}</div><div class="mcsub cg"><i class="ti ti-clipboard-list"></i>active</div></div>
      <div class="mc"><div class="mclbl">My Jobs</div><div class="mcval">${mineCount}</div><div class="mcsub cg"><i class="ti ti-user"></i>assigned to me</div></div>
      <div class="mc"><div class="mclbl">Waiting for Parts</div><div class="mcval" style="${waitingCount>0?'color:var(--red)':''}">${waitingCount}</div><div class="mcsub ${waitingCount>0?'cr':''}"><i class="ti ti-hourglass"></i>blocked</div></div>
      <div class="mc"><div class="mclbl">External Repair</div><div class="mcval" style="${externalCount>0?'color:var(--red)':''}">${externalCount}</div><div class="mcsub ${externalCount>0?'cr':''}"><i class="ti ti-truck-delivery"></i>with vendor</div></div>
    </div>
    <div id="mj-queue-view" style="${viewState.mode==='queue'?'':'display:none'}"></div>
    <div id="mj-waiting-view" style="${viewState.mode==='waiting'?'':'display:none'}"></div>
    <div id="mj-external-view" style="${viewState.mode==='external'?'':'display:none'}"></div>
    <div id="mj-table-view" style="${viewState.mode==='table'?'':'display:none'}">
      ${procFilterBarHtml({
        searchId: 'mj-search', searchPlaceholder: 'Search title, machine, technician…',
        clearId: 'mj-clear',
        extraHtml: `<select id="mj-status-filter" class="filter-select">
          <option value="">All statuses</option>
          ${Object.entries(MAINT_JOB_STATUS_META).map(([k, m]) => `<option value="${k}">${m.label}</option>`).join('')}
        </select>`,
      })}
      <div class="card" style="padding:0">
        <div style="display:flex;align-items:center;justify-content:space-between;padding:1rem 1.25rem;border-bottom:1px solid var(--bdr)">
          <h3 style="margin:0"><i class="ti ti-tool"></i>Jobs</h3>
          <span id="mj-count-label" style="font-size:12px;color:var(--t3)">${rows.length} job${rows.length!==1?'s':''}</span>
        </div>
        <div class="tw"><table class="dt" id="mj-table">
          <thead><tr>
            <th data-sort-key="title">Title</th>
            <th data-sort-key="machine_name">Machine</th>
            <th data-sort-key="priority">Priority</th>
            <th data-sort-key="assigned_to_name">Assigned To</th>
            <th>Status</th>
            <th data-sort-key="created_at">Created</th>
            <th></th>
          </tr></thead>
          <tbody id="mj-tbody"></tbody>
        </table></div>
      </div>
    </div>
  `;

  function renderQueueView() {
    const el = $('mj-queue-view');
    const groups = MAINT_QUEUE_ORDER.map(status => ({
      status, meta: MAINT_JOB_STATUS_META[status],
      jobs: rows.filter(r => r.status === status),
    })).filter(g => g.jobs.length > 0);
    if (!groups.length) {
      el.innerHTML = `<div class="card" style="text-align:center;color:var(--t3);padding:3rem"><i class="ti ti-clipboard-list" style="font-size:2rem;display:block;margin-bottom:.5rem;opacity:.35"></i>No open maintenance jobs right now.</div>`;
      return;
    }
    el.innerHTML = `<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:1rem">
      ${groups.map(g => `
        <div class="card">
          <h3 style="margin:0 0 .6rem;display:flex;align-items:center;justify-content:space-between">
            <span>${_mjStatusBadge(g.status)}</span>
            <span style="font-size:12px;color:var(--t3);font-weight:400">${g.jobs.length}</span>
          </h3>
          ${g.jobs.map(j => `
            <div class="mj-queue-item" data-id="${j.id}" style="cursor:pointer;padding:.5rem 0;border-top:1px solid var(--bdr)">
              <div style="font-size:13px;font-weight:500">${j.title}</div>
              <div style="font-size:11px;color:var(--t3)">${j.machine_code} — ${j.machine_name}${j.assigned_to_name ? ' · ' + j.assigned_to_name : ''}</div>
            </div>
          `).join('')}
        </div>
      `).join('')}
    </div>`;
    el.querySelectorAll('.mj-queue-item').forEach(item => {
      item.onclick = () => openMaintenanceJobDetailOverlay(Number(item.dataset.id));
    });
  }

  function renderMjRows(list) {
    const tbody = $('mj-tbody');
    if (!list.length) {
      tbody.innerHTML = `<tr><td colspan="7" style="text-align:center;color:var(--t3);padding:3rem"><i class="ti ti-clipboard-list" style="font-size:2rem;display:block;margin-bottom:.5rem;opacity:.35"></i>No maintenance jobs match these filters.</td></tr>`;
      $('mj-count-label').textContent = '0 jobs';
      return;
    }
    $('mj-count-label').textContent = `${list.length} job${list.length!==1?'s':''}`;
    tbody.innerHTML = list.map(r => `<tr>
      <td style="font-weight:500">${r.title}</td>
      <td>${r.machine_code} — ${r.machine_name}</td>
      <td style="text-transform:capitalize">${r.priority}</td>
      <td style="color:var(--t3)">${r.assigned_to_name || '—'}</td>
      <td>${_mjStatusBadge(r.status)}</td>
      <td style="white-space:nowrap;color:var(--t3)">${new Date(r.created_at).toLocaleDateString('en-GB')}</td>
      <td><button class="bs1 mj-view" data-id="${r.id}" style="padding:3px 7px;font-size:12px"><i class="ti ti-eye"></i></button></td>
    </tr>`).join('');
    tbody.querySelectorAll('.mj-view').forEach(btn => {
      btn.onclick = () => openMaintenanceJobDetailOverlay(Number(btn.dataset.id));
    });
  }

  // Priority 6 — Waiting for Parts dedicated view. Reuses maintenanceWaitingForPartsList
  // (the enriched read added earlier this phase) so a blocked job's linked
  // material request + transfer status show inline, no need to open each job.
  let waitingLoaded = false;
  async function renderWaitingView() {
    const el = $('mj-waiting-view');
    el.innerHTML = `<div style="padding:2rem;color:var(--t3);font-size:13px"><i class="ti ti-loader-2" style="font-size:18px;animation:spin 1s linear infinite"></i> Loading…</div>`;
    const wRes = await UFCL.maintenanceWaitingParts(STORAGE.user.id);
    if (!wRes.ok) { el.innerHTML = `<div class="card" style="color:var(--red);padding:1.5rem">${wRes.error}</div>`; return; }
    const wRows = wRes.rows || [];
    if (!wRows.length) {
      el.innerHTML = `<div class="card" style="text-align:center;color:var(--t3);padding:3rem"><i class="ti ti-hourglass" style="font-size:2rem;display:block;margin-bottom:.5rem;opacity:.35"></i>No jobs waiting for parts.</div>`;
      return;
    }
    el.innerHTML = wRows.map(j => `
      <div class="card mj-waiting-item" data-id="${j.id}" style="cursor:pointer;margin-bottom:.75rem">
        <div class="frow" style="justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:.5rem">
          <div>
            <div style="font-weight:600;font-size:13px">${j.title}</div>
            <div style="font-size:11px;color:var(--t3)">${j.machine_code} — ${j.machine_name}${j.assigned_to_name ? ' · ' + j.assigned_to_name : ''}</div>
          </div>
          ${_mjStatusBadge('waiting_parts')}
        </div>
        ${j.delay_reason ? `<div style="font-size:12px;color:var(--amber);margin-top:.4rem"><strong>Reason:</strong> ${j.delay_reason}</div>` : ''}
        ${j.item_name ? `<div style="font-size:12px;color:var(--t2);margin-top:.4rem"><strong>Part:</strong> ${j.item_name} · Requested ${j.requested_qty}${j.approved_qty != null ? ' · Approved ' + j.approved_qty : ''} · Request: ${j.request_status}${j.transfer_status ? ' · Transfer: ' + j.transfer_status : ''}</div>` : `<div style="font-size:12px;color:var(--t3);margin-top:.4rem">No material request linked yet.</div>`}
      </div>
    `).join('');
    el.querySelectorAll('.mj-waiting-item').forEach(item => {
      item.onclick = () => openMaintenanceJobDetailOverlay(Number(item.dataset.id));
    });
  }

  // Priority 7 — External Repair dedicated view. All fields (vendor/dates/cost)
  // already come back on the job-list rows (mj.* includes them), so this is a
  // pure client-side filter — no new backend call.
  function renderExternalView() {
    const el = $('mj-external-view');
    const extRows = rows.filter(r => r.status === 'external_repair');
    if (!extRows.length) {
      el.innerHTML = `<div class="card" style="text-align:center;color:var(--t3);padding:3rem"><i class="ti ti-truck-delivery" style="font-size:2rem;display:block;margin-bottom:.5rem;opacity:.35"></i>No jobs currently at an external vendor.</div>`;
      return;
    }
    el.innerHTML = extRows.map(j => `
      <div class="card mj-external-item" data-id="${j.id}" style="cursor:pointer;margin-bottom:.75rem">
        <div class="frow" style="justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:.5rem">
          <div>
            <div style="font-weight:600;font-size:13px">${j.title}</div>
            <div style="font-size:11px;color:var(--t3)">${j.machine_code} — ${j.machine_name}</div>
          </div>
          ${_mjStatusBadge('external_repair')}
        </div>
        <div class="frow" style="flex-wrap:wrap;gap:1rem;font-size:12px;color:var(--t2);margin-top:.4rem">
          <div><strong>Vendor:</strong> ${j.external_repair_vendor || '—'}</div>
          <div><strong>Sent:</strong> ${j.external_repair_sent_at ? new Date(j.external_repair_sent_at).toLocaleDateString('en-GB') : '—'}</div>
          ${j.external_repair_cost ? `<div><strong>Cost:</strong> RWF ${Number(j.external_repair_cost).toLocaleString()}</div>` : ''}
        </div>
        ${j.external_repair_reason ? `<div style="font-size:12px;color:var(--t3);margin-top:.3rem">${j.external_repair_reason}</div>` : ''}
      </div>
    `).join('');
    el.querySelectorAll('.mj-external-item').forEach(item => {
      item.onclick = () => openMaintenanceJobDetailOverlay(Number(item.dataset.id));
    });
  }

  function setView(mode) {
    viewState.mode = mode;
    $('mj-queue-view').style.display = mode === 'queue' ? '' : 'none';
    $('mj-table-view').style.display = mode === 'table' ? '' : 'none';
    $('mj-waiting-view').style.display = mode === 'waiting' ? '' : 'none';
    $('mj-external-view').style.display = mode === 'external' ? '' : 'none';
    $('mjViewQueue').style.background = mode === 'queue' ? 'var(--bg2)' : '';
    $('mjViewTable').style.background = mode === 'table' ? 'var(--bg2)' : '';
    $('mjViewWaiting').style.background = mode === 'waiting' ? 'var(--bg2)' : '';
    $('mjViewExternal').style.background = mode === 'external' ? 'var(--bg2)' : '';
    if (mode === 'waiting' && !waitingLoaded) { waitingLoaded = true; renderWaitingView(); }
    if (mode === 'external') renderExternalView();
  }
  $('mjViewQueue').onclick = () => setView('queue');
  $('mjViewTable').onclick = () => setView('table');
  $('mjViewWaiting').onclick = () => setView('waiting');
  $('mjViewExternal').onclick = () => setView('external');

  renderQueueView();
  renderMjRows(mjFiltered());
  if (initialStatus) $('mj-status-filter').value = initialStatus;
  wireSortableTable($('mj-table'), mjSort, mjFiltered, renderMjRows);
  $('mj-search').oninput = (e) => { mjState.search = e.target.value; renderMjRows(mjFiltered()); };
  $('mj-status-filter').onchange = (e) => { mjState.status = e.target.value; renderMjRows(mjFiltered()); };
  $('mj-clear').onclick = () => { mjState.search=''; mjState.status=''; $('mj-search').value=''; $('mj-status-filter').value=''; renderMjRows(mjFiltered()); };

  if (canManage) {
    $('mjAdd').onclick = async () => {
      const machRes = await UFCL.machinesList(STORAGE.user.id);
      const machines = machRes.ok ? (machRes.rows || []) : [];
      const machOpts = machines.map(m => `<option value="${m.id}">${m.machine_code} — ${m.name}</option>`).join('');
      openOverlay('New Maintenance Job', 'Create and optionally assign', `
        <div class="fg"><label>Machine *</label><select id="mj-new-machine">${machOpts}</select></div>
        <div class="fg"><label>Title *</label><input id="mj-new-title" type="text" placeholder="e.g. Hydraulic leak repair"></div>
        <div class="fg"><label>Description</label><input id="mj-new-desc" type="text"></div>
        <div class="frow">
          <div class="fg"><label>Priority</label><select id="mj-new-priority"><option value="normal">Normal</option><option value="high">High</option><option value="urgent">Urgent</option></select></div>
        </div>
        <div class="brow"><button class="bp1" id="ovSave">Create</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
        async () => {
          const r2 = await UFCL.maintenanceJobCreate(STORAGE.user.id, {
            machine_id: Number($('mj-new-machine').value),
            title: $('mj-new-title').value.trim(),
            description: $('mj-new-desc').value.trim() || null,
            priority: $('mj-new-priority').value,
          });
          if (!r2.ok) { showOverlayError(r2.error); return; }
          showOverlaySuccess('Maintenance job created.');
          await renderMaintenanceJobs();
        });
    };
  }
}

// Tabbed detail overlay — Overview (status + transitions), Labour, Parts,
// External Repair, Production Impact, History. Read-only for roles without
// 'machines' beyond the transitions their own assignment permits.
async function openMaintenanceJobDetailOverlay(jobId) {
  const res = await UFCL.maintenanceJobDetail(STORAGE.user.id, jobId);
  if (!res.ok) { showToast(res.error || 'Failed to load job', 'error'); return; }
  const { job: r, labour, parts, productionImpact, canManage, cost } = res;
  const isAssignee = String(r.assigned_to) === String(STORAGE.user.id);
  const canAct = canManage || isAssignee;

  const TAB_META = {
    overview: { label: 'Overview', icon: 'ti-info-circle' },
    timeline: { label: 'Timeline', icon: 'ti-timeline' },
    labour: { label: 'Labour', icon: 'ti-clock' },
    parts: { label: 'Parts', icon: 'ti-package' },
    external: { label: 'External Repair', icon: 'ti-truck-delivery' },
    impact: { label: 'Production Impact', icon: 'ti-chart-line' },
    history: { label: 'Audit History', icon: 'ti-history' },
  };
  openOverlay(r.title, `${r.machine_code} — ${r.machine_name}`, `
    <div id="mjd-asset-strip"></div>
    <div class="smo-tabs" id="mjd-tabs">
      ${Object.entries(TAB_META).map(([t, m]) => `<button type="button" class="smo-tab ${t==='overview'?'active':''}" data-tab="${t}"><i class="ti ${m.icon}"></i>${m.label}</button>`).join('')}
    </div>
    <div id="mjd-body"></div>
    <div class="brow" style="margin-top:1rem"><button class="bs1" id="ovCancel">Close</button></div>
  `, null, 'ow-wide');

  // Priority 4's "Asset Summary" strip — same composed read used by the
  // dedicated per-machine card, shown compactly here so a technician doesn't
  // have to leave the job to see the machine's overall maintenance picture.
  UFCL.maintenanceAssetSummary(STORAGE.user.id, r.machine_id).then(asRes => {
    const el = $('mjd-asset-strip');
    if (!el || !asRes.ok) { if (el) el.innerHTML = ''; return; }
    const a = asRes;
    el.innerHTML = `
      <div class="card" style="padding:10px 14px;margin-bottom:12px;background:var(--bg2)">
        <div class="frow" style="flex-wrap:wrap;gap:1.25rem;font-size:12px;color:var(--t2)">
          <div><strong>Machine Status</strong><br>${a.machine.status}</div>
          <div><strong>Open Maintenance</strong><br>${a.openMaintenance}</div>
          <div><strong>Last Maintenance</strong><br>${a.lastMaintenance ? new Date(a.lastMaintenance).toLocaleDateString('en-GB') : '—'}</div>
          <div><strong>Next PM Due</strong><br>${a.nextPreventiveMaintenance ? new Date(a.nextPreventiveMaintenance).toLocaleDateString('en-GB') : '—'}</div>
          <div><strong>Downtime This Month</strong><br>${a.downtimeHoursThisMonth.toFixed(1)}h</div>
          <div><strong>Failures (90d)</strong><br>${a.recentFailures90d}</div>
          ${a.externalRepairActive ? `<div><span class="badge br"><i class="ti ti-truck-delivery"></i> External Repair Active</span></div>` : ''}
        </div>
      </div>`;
  });

  async function reload() { closeOverlay(); await openMaintenanceJobDetailOverlay(jobId); await renderMaintenanceJobs(); }

  function actionButton(action, label, cls) {
    return `<button type="button" class="bs1 mjd-action" data-action="${action}" style="${cls||''}">${label}</button>`;
  }

  function renderOverviewTab(body) {
    const actions = [];
    if (canAct) {
      if (r.status === 'inspection') actions.push(actionButton('diagnose', 'Diagnose'));
      if (canManage && ['inspection', 'diagnosis'].includes(r.status)) actions.push(actionButton('__assign', 'Assign Technician'));
      if (r.status === 'assigned') actions.push(actionButton('start', 'Start Work', 'color:var(--green)'));
      if (r.status === 'in_progress') {
        actions.push(actionButton('request_parts', 'Request Parts', 'color:var(--amber)'));
        actions.push(actionButton('test', 'Send to Testing'));
        if (canManage) actions.push(actionButton('send_external', 'Send for External Repair', 'color:var(--red)'));
      }
      if (r.status === 'waiting_parts') {
        actions.push(actionButton('resume', 'Resume Work', 'color:var(--green)'));
        if (canManage) actions.push(actionButton('send_external', 'Send for External Repair', 'color:var(--red)'));
      }
      if (r.status === 'testing') actions.push(actionButton('return_to_service', 'Return to Service', 'color:var(--green)'));
      if (r.status === 'returned_to_service') actions.push(actionButton('close', 'Close Job', 'color:var(--green)'));
      if (!['closed', 'cancelled'].includes(r.status)) actions.push(actionButton('cancel', 'Cancel Job', 'color:var(--red)'));
    }
    body.innerHTML = `
      <div class="frow" style="margin-bottom:10px">${_mjStatusBadge(r.status)} <span class="badge bt" style="text-transform:capitalize">${r.priority}</span></div>
      <div class="card" style="padding:12px 14px;margin-bottom:12px;background:var(--bg2)">
        <div class="frow" style="flex-wrap:wrap;gap:1.25rem;font-size:13px">
          <div><strong>Machine</strong><br>${r.machine_code} — ${r.machine_name}</div>
          <div><strong>Workshop</strong><br>${r.workshop_name||'—'}</div>
          <div><strong>Assigned To</strong><br>${r.assigned_to_name||'—'}</div>
          <div><strong>Assigned</strong><br>${r.assigned_at ? new Date(r.assigned_at).toLocaleDateString('en-GB') : '—'}</div>
          <div><strong>Started</strong><br>${r.started_at ? new Date(r.started_at).toLocaleDateString('en-GB') : '—'}</div>
          <div><strong>Returned to Service</strong><br>${r.returned_to_service_at ? new Date(r.returned_to_service_at).toLocaleDateString('en-GB') : '—'}</div>
          <div><strong>Closed</strong><br>${r.completed_at ? new Date(r.completed_at).toLocaleDateString('en-GB') : '—'}</div>
        </div>
        ${r.description ? `<div style="margin-top:8px;font-size:13px"><strong>Description:</strong> ${r.description}</div>` : ''}
        ${r.delay_reason ? `<div style="margin-top:8px;font-size:13px;color:var(--amber)"><strong>Delay reason:</strong> ${r.delay_reason}</div>` : ''}
        ${r.cancelled_reason ? `<div style="margin-top:8px;font-size:13px;color:var(--red)"><strong>Cancelled:</strong> ${r.cancelled_reason}</div>` : ''}
      </div>
      <div class="card" style="padding:12px 14px;margin-bottom:12px;background:var(--bg2)">
        <div style="font-size:12px;font-weight:700;color:var(--t3);margin-bottom:8px;text-transform:uppercase;letter-spacing:.03em">Cost (parts + external repair — labour has no monetary rate in this system)</div>
        <div class="frow" style="flex-wrap:wrap;gap:1.25rem;font-size:13px">
          <div><strong>Parts (received)</strong><br>RWF ${Math.round(cost.partsCostActual).toLocaleString()}</div>
          <div><strong>Parts (pending)</strong><br>RWF ${Math.round(cost.partsCostPending).toLocaleString()}</div>
          <div><strong>External Repair</strong><br>RWF ${Math.round(cost.externalRepairCost).toLocaleString()}</div>
          <div><strong>Labour Hours</strong><br>${cost.labourHours.toFixed(1)}h</div>
          <div><strong>Total (parts + external)</strong><br>RWF ${Math.round(cost.totalCost).toLocaleString()}</div>
        </div>
      </div>
      ${actions.length ? `<div class="frow" style="flex-wrap:wrap;gap:.5rem">${actions.join('')}</div>` : ''}
      <div id="mjd-action-area" style="margin-top:.75rem"></div>
    `;
    body.querySelectorAll('.mjd-action').forEach(btn => {
      btn.onclick = () => {
        const action = btn.dataset.action;
        if (action === '__assign') return renderAssignForm();
        renderTransitionForm(action);
      };
    });

    function renderAssignForm() {
      const area = $('mjd-action-area');
      area.innerHTML = `
        <div class="card" style="padding:12px 14px;background:var(--bg2)">
          <div class="fg"><label>Technician user ID *</label><input id="mjd-assign-tech" type="number" placeholder="User ID"></div>
          <div class="brow"><button class="bp1" id="mjd-assign-save">Assign</button><button class="bs1" id="mjd-assign-cancel">Cancel</button></div>
        </div>`;
      $('mjd-assign-cancel').onclick = () => { area.innerHTML = ''; };
      $('mjd-assign-save').onclick = async () => {
        const techId = Number($('mjd-assign-tech').value);
        if (!techId) { showOverlayError('A technician user ID is required'); return; }
        const r2 = await UFCL.maintenanceJobAssign(STORAGE.user.id, jobId, techId);
        if (!r2.ok) { showOverlayError(r2.error); return; }
        showOverlaySuccess('Technician assigned.');
        await reload();
      };
    }

    function renderTransitionForm(action) {
      const area = $('mjd-action-area');
      const needsReason = ['request_parts', 'send_external', 'cancel'].includes(action);
      const isExternal = action === 'send_external';
      area.innerHTML = `
        <div class="card" style="padding:12px 14px;background:var(--bg2)">
          ${isExternal ? `<div class="fg"><label>Vendor</label><input id="mjd-t-vendor" type="text"></div>` : ''}
          ${needsReason ? `<div class="fg"><label>Reason *</label><input id="mjd-t-reason" type="text"></div>` : ''}
          <div class="brow"><button class="bp1" id="mjd-t-save">Confirm</button><button class="bs1" id="mjd-t-cancel">Cancel</button></div>
        </div>`;
      $('mjd-t-cancel').onclick = () => { area.innerHTML = ''; };
      $('mjd-t-save').onclick = async () => {
        const payload = {};
        if (needsReason) {
          const reason = $('mjd-t-reason').value.trim();
          if (!reason) { showOverlayError('A reason is required'); return; }
          payload.reason = reason;
        }
        if (isExternal) payload.vendor = $('mjd-t-vendor').value.trim() || null;
        const r2 = await UFCL.maintenanceJobTransition(STORAGE.user.id, jobId, action, payload);
        if (!r2.ok) { showOverlayError(r2.error); return; }
        showOverlaySuccess('Updated.');
        await reload();
      };
    }
  }

  function renderLabourTab(body) {
    body.innerHTML = `
      <div class="tw"><table class="dt" style="font-size:12px">
        <thead><tr><th>Technician</th><th>Start</th><th>Finish</th><th>Hours</th><th>Notes</th></tr></thead>
        <tbody>${labour.length ? labour.map(l => `<tr>
          <td>${l.technician_name||'—'}</td>
          <td style="white-space:nowrap">${l.start_time ? new Date(l.start_time).toLocaleString('en-GB') : '—'}</td>
          <td style="white-space:nowrap">${l.finish_time ? new Date(l.finish_time).toLocaleString('en-GB') : 'In progress'}</td>
          <td>${l.hours_worked != null ? Number(l.hours_worked).toFixed(1) : '—'}</td>
          <td style="color:var(--t3)">${l.notes||l.delay_reason||'—'}</td>
        </tr>`).join('') : '<tr><td colspan="5" style="text-align:center;color:var(--t3);padding:2rem">No labour sessions yet.</td></tr>'}</tbody>
      </table></div>
      ${canAct ? `
      <div class="card" style="padding:12px 14px;margin-top:12px;background:var(--bg2)">
        <div style="font-weight:600;font-size:13px;margin-bottom:.5rem">Add note / manual hours</div>
        <div class="frow">
          <div class="fg"><label>Hours</label><input id="mjd-lab-hours" type="number" min="0" step="0.25"></div>
          <div class="fg" style="flex:2"><label>Notes</label><input id="mjd-lab-notes" type="text"></div>
        </div>
        <button class="bp1" id="mjd-lab-save">Add Entry</button>
      </div>` : ''}
    `;
    if (canAct) {
      $('mjd-lab-save').onclick = async () => {
        const r2 = await UFCL.maintenanceJobLabourAdd(STORAGE.user.id, jobId, {
          hours: $('mjd-lab-hours').value || null,
          notes: $('mjd-lab-notes').value.trim() || null,
        });
        if (!r2.ok) { showOverlayError(r2.error); return; }
        showOverlaySuccess('Labour entry added.');
        await reload();
      };
    }
  }

  async function renderPartsTab(body) {
    body.innerHTML = `
      <div class="tw"><table class="dt" style="font-size:12px">
        <thead><tr><th>Item</th><th>Requested</th><th>Approved</th><th>Status</th><th>Transfer</th></tr></thead>
        <tbody>${parts.length ? parts.map(p => `<tr>
          <td style="font-weight:500">${p.item_name}</td>
          <td>${p.requested_qty}</td>
          <td>${p.approved_qty ?? '—'}</td>
          <td>${p.status}</td>
          <td style="color:var(--t3)">${p.transfer_status || '—'}</td>
        </tr>`).join('') : '<tr><td colspan="5" style="text-align:center;color:var(--t3);padding:2rem">No material requests linked yet.</td></tr>'}</tbody>
      </table></div>
      <div style="margin-top:12px"><button class="bp1" id="mjd-parts-request"><i class="ti ti-plus"></i>Request Materials</button></div>
      <div id="mjd-parts-form" style="margin-top:.75rem"></div>
    `;
    $('mjd-parts-request').onclick = async () => {
      const mrRes = await UFCL.materialRequestsList(STORAGE.user.id);
      const items = mrRes.ok ? (mrRes.items || []) : [];
      const area = $('mjd-parts-form');
      area.innerHTML = `
        <div class="card" style="padding:12px 14px;background:var(--bg2)">
          <div class="fg"><label>Item *</label><select id="mjd-p-item">${items.map(i => `<option value="${i.id}">[${i.category}] ${i.name} (${i.uom}) — available: ${i.total_stock}</option>`).join('')}</select></div>
          <div class="frow">
            <div class="fg"><label>Quantity *</label><input id="mjd-p-qty" type="number" min="1" step="1"></div>
            <div class="fg"><label>Priority</label><select id="mjd-p-priority"><option value="normal">Normal</option><option value="high">High</option><option value="urgent">Urgent</option></select></div>
          </div>
          <div class="fg"><label>Reason</label><input id="mjd-p-reason" type="text" value="For maintenance job: ${r.title}"></div>
          <div class="brow"><button class="bp1" id="mjd-p-save">Submit Request</button><button class="bs1" id="mjd-p-cancel">Cancel</button></div>
        </div>`;
      $('mjd-p-cancel').onclick = () => { area.innerHTML = ''; };
      $('mjd-p-save').onclick = async () => {
        const qty = Number($('mjd-p-qty').value);
        if (!qty || qty <= 0) { showOverlayError('Quantity must be greater than zero'); return; }
        const r2 = await UFCL.materialRequestsCreate(STORAGE.user.id, {
          item_id: Number($('mjd-p-item').value), requested_qty: qty,
          priority: $('mjd-p-priority').value, reason: $('mjd-p-reason').value.trim(),
          maintenance_job_id: jobId,
        });
        if (!r2.ok) { showOverlayError(r2.error); return; }
        showOverlaySuccess('Material request submitted, linked to this job.');
        await reload();
      };
    };
  }

  function renderExternalTab(body) {
    body.innerHTML = `
      <div class="card" style="padding:12px 14px;background:var(--bg2)">
        <div class="frow" style="flex-wrap:wrap;gap:1.25rem;font-size:13px">
          <div><strong>Vendor</strong><br>${r.external_repair_vendor||'—'}</div>
          <div><strong>Reason</strong><br>${r.external_repair_reason||'—'}</div>
          <div><strong>Sent</strong><br>${r.external_repair_sent_at ? new Date(r.external_repair_sent_at).toLocaleDateString('en-GB') : '—'}</div>
          <div><strong>Returned</strong><br>${r.external_repair_returned_at ? new Date(r.external_repair_returned_at).toLocaleDateString('en-GB') : '—'}</div>
          <div><strong>Cost</strong><br>${r.external_repair_cost ? 'RWF '+Number(r.external_repair_cost).toLocaleString() : '—'}</div>
        </div>
        ${r.external_repair_notes ? `<div style="margin-top:8px;font-size:13px">${r.external_repair_notes}</div>` : ''}
      </div>
      ${canAct && r.status === 'external_repair' ? `
      <div class="card" style="padding:12px 14px;margin-top:12px;background:var(--bg2)">
        <div style="font-weight:600;font-size:13px;margin-bottom:.5rem">Record Vendor Return</div>
        <div class="frow">
          <div class="fg"><label>Cost (RWF)</label><input id="mjd-ext-cost" type="number" min="0" step="0.01"></div>
          <div class="fg" style="flex:2"><label>Notes</label><input id="mjd-ext-notes" type="text"></div>
        </div>
        <button class="bp1" id="mjd-ext-save">Record Return &amp; Move to Testing</button>
      </div>` : ''}
    `;
    if (canAct && r.status === 'external_repair') {
      $('mjd-ext-save').onclick = async () => {
        const r2 = await UFCL.maintenanceJobTransition(STORAGE.user.id, jobId, 'return_external', {
          cost: $('mjd-ext-cost').value || null, notes: $('mjd-ext-notes').value.trim() || null,
        });
        if (!r2.ok) { showOverlayError(r2.error); return; }
        showOverlaySuccess('Vendor return recorded — job moved to Testing.');
        await reload();
      };
    }
  }

  function renderImpactTab(body) {
    body.innerHTML = `
      <div class="tw"><table class="dt" style="font-size:12px">
        <thead><tr><th>Date</th><th>Downtime</th><th>Reason</th><th>Est. Loss</th><th>By</th></tr></thead>
        <tbody>${productionImpact.length ? productionImpact.map(pi => `<tr>
          <td style="white-space:nowrap">${pi.log_date}</td>
          <td>${pi.downtime_hours ?? '—'}h</td>
          <td style="color:var(--t3)">${pi.reason||'—'}</td>
          <td>${pi.estimated_production_loss ?? '—'}</td>
          <td style="color:var(--t3)">${pi.recorded_by_name||'—'}</td>
        </tr>`).join('') : '<tr><td colspan="5" style="text-align:center;color:var(--t3);padding:2rem">No production impact recorded.</td></tr>'}</tbody>
      </table></div>
      <div class="card" style="padding:12px 14px;margin-top:12px;background:var(--bg2)">
        <div style="font-weight:600;font-size:13px;margin-bottom:.5rem">Log Production Impact</div>
        <div class="frow">
          <div class="fg"><label>Downtime (hrs)</label><input id="mjd-pi-downtime" type="number" min="0" step="0.5"></div>
          <div class="fg"><label>Estimated Loss</label><input id="mjd-pi-loss" type="number" min="0" step="0.5"></div>
        </div>
        <div class="fg"><label>Reason</label><input id="mjd-pi-reason" type="text"></div>
        <div class="fg"><label>Comments</label><input id="mjd-pi-comments" type="text"></div>
        <button class="bp1" id="mjd-pi-save">Log Impact</button>
      </div>
    `;
    $('mjd-pi-save').onclick = async () => {
      const r2 = await UFCL.maintenanceImpactAdd(STORAGE.user.id, {
        job_id: jobId,
        downtime_hours: $('mjd-pi-downtime').value || null,
        estimated_production_loss: $('mjd-pi-loss').value || null,
        reason: $('mjd-pi-reason').value.trim() || null,
        comments: $('mjd-pi-comments').value.trim() || null,
      });
      if (!r2.ok) { showOverlayError(r2.error); return; }
      showOverlaySuccess('Production impact logged.');
      await reload();
    };
  }

  function renderHistoryTab(body) {
    body.innerHTML = `<div id="mjd-history"></div>`;
    _loadLogisticsHistoryInto('mjd-history', 'maintenance_jobs', r.id);
  }

  function renderTimelineTab(body) {
    body.innerHTML = `
      <div class="card" style="padding:14px;margin-bottom:12px">
        ${_mjTimelineHtml(r.status)}
      </div>
      <div class="tw"><table class="dt" style="font-size:12px">
        <thead><tr><th>Milestone</th><th>Date</th></tr></thead>
        <tbody>
          <tr><td>Created</td><td style="white-space:nowrap">${r.created_at ? new Date(r.created_at).toLocaleString('en-GB') : '—'}</td></tr>
          <tr><td>Assigned</td><td style="white-space:nowrap">${r.assigned_at ? new Date(r.assigned_at).toLocaleString('en-GB') : '—'}</td></tr>
          <tr><td>Started</td><td style="white-space:nowrap">${r.started_at ? new Date(r.started_at).toLocaleString('en-GB') : '—'}</td></tr>
          ${r.external_repair_sent_at ? `<tr><td>Sent for External Repair</td><td style="white-space:nowrap">${new Date(r.external_repair_sent_at).toLocaleString('en-GB')}</td></tr>` : ''}
          ${r.external_repair_returned_at ? `<tr><td>Returned from Vendor</td><td style="white-space:nowrap">${new Date(r.external_repair_returned_at).toLocaleString('en-GB')}</td></tr>` : ''}
          <tr><td>Returned to Service</td><td style="white-space:nowrap">${r.returned_to_service_at ? new Date(r.returned_to_service_at).toLocaleString('en-GB') : '—'}</td></tr>
          <tr><td>Closed</td><td style="white-space:nowrap">${r.completed_at ? new Date(r.completed_at).toLocaleString('en-GB') : '—'}</td></tr>
        </tbody>
      </table></div>
    `;
  }

  function loadTab(tab) {
    const body = $('mjd-body');
    if (tab === 'overview') return renderOverviewTab(body);
    if (tab === 'timeline') return renderTimelineTab(body);
    if (tab === 'labour') return renderLabourTab(body);
    if (tab === 'parts') return renderPartsTab(body);
    if (tab === 'external') return renderExternalTab(body);
    if (tab === 'impact') return renderImpactTab(body);
    if (tab === 'history') return renderHistoryTab(body);
  }
  document.querySelectorAll('#mjd-tabs .smo-tab').forEach(btn => {
    btn.onclick = () => {
      document.querySelectorAll('#mjd-tabs .smo-tab').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      loadTab(btn.dataset.tab);
    };
  });
  loadTab('overview');
}

// ── Maintenance Overview (company-wide "Mechanician Officer" supervision) ──────
// Delivered to the existing 'logistics' role (Logistics Manager) per the
// confirmed scope decision — no new role. Deliberately company-wide, no
// workshop filter, unlike every other dashboard in this app.

async function renderMaintenanceOfficerDashboard() {
  const pg = $('page-maintenance-officer-dashboard');
  pg.innerHTML = `<div style="padding:2rem;color:var(--t3);font-size:13px"><i class="ti ti-loader-2" style="font-size:18px;animation:spin 1s linear infinite"></i> Loading…</div>`;

  const res = await UFCL.maintenanceOfficerDashboard(STORAGE.user.id);
  if (!res.ok) return renderDenied('maintenance-officer-dashboard', res.error);
  const { kpi, workshopComparison, repeatedFailures, technicianWorkload, recentJobs, machineHealth, trendMonths } = res;

  pg.innerHTML = `
    <div class="ptitle"><i class="ti ti-building-factory-2" style="color:var(--g-soft)"></i> Maintenance Overview</div>
    <div class="psub" style="margin-bottom:1.25rem">Company-wide maintenance supervision across every workshop.</div>
    <div class="cards" style="margin-bottom:1.25rem">
      <div class="mc"><div class="mclbl">Open Jobs</div><div class="mcval">${kpi.openJobs}</div><div class="mcsub cg"><i class="ti ti-clipboard-list"></i>company-wide</div></div>
      <div class="mc"><div class="mclbl">In Progress</div><div class="mcval">${kpi.inProgress}</div><div class="mcsub cg"><i class="ti ti-tool"></i>active work</div></div>
      <div class="mc"><div class="mclbl">Waiting for Parts</div><div class="mcval" style="${kpi.waitingForParts>0?'color:var(--red)':''}">${kpi.waitingForParts}</div><div class="mcsub ${kpi.waitingForParts>0?'cr':''}"><i class="ti ti-hourglass"></i>blocked</div></div>
      <div class="mc"><div class="mclbl">External Repairs</div><div class="mcval" style="${kpi.externalRepairs>0?'color:var(--red)':''}">${kpi.externalRepairs}</div><div class="mcsub ${kpi.externalRepairs>0?'cr':''}"><i class="ti ti-truck-delivery"></i>with vendor</div></div>
      <div class="mc"><div class="mclbl">Downtime This Month</div><div class="mcval">${kpi.downtimeHoursThisMonth.toFixed(1)}h</div><div class="mcsub bp"><i class="ti ti-clock-pause"></i>all machines</div></div>
      <div class="mc"><div class="mclbl">Overdue Maintenance</div><div class="mcval" style="${kpi.overdueMaintenanceCount>0?'color:var(--red)':''}">${kpi.overdueMaintenanceCount}</div><div class="mcsub ${kpi.overdueMaintenanceCount>0?'cr':''}"><i class="ti ti-calendar-exclamation"></i>past due</div></div>
    </div>

    <div style="display:grid;grid-template-columns:1.1fr 1.4fr;gap:1rem;margin-bottom:1.25rem">
      <div class="card">
        <h3 style="margin:0 0 .75rem"><i class="ti ti-heart-rate-monitor"></i>Machine Health</h3>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:.6rem">
          <div><div style="font-size:11px;color:var(--t3)">Available</div><div style="font-size:20px;font-weight:700;color:var(--green)">${machineHealth.available}</div></div>
          <div><div style="font-size:11px;color:var(--t3)">Running</div><div style="font-size:20px;font-weight:700;color:var(--blue,#1D4ED8)">${machineHealth.running}</div></div>
          <div><div style="font-size:11px;color:var(--t3)">Maintenance</div><div style="font-size:20px;font-weight:700;color:var(--amber)">${machineHealth.maintenance}</div></div>
          <div><div style="font-size:11px;color:var(--t3)">Breakdown</div><div style="font-size:20px;font-weight:700;color:var(--red)">${machineHealth.breakdown}</div></div>
        </div>
      </div>
      <div class="card">
        <h3 style="margin:0 0 .5rem"><i class="ti ti-chart-line"></i>6-Month Trend <span style="font-weight:400;color:var(--t3);font-size:11px">· jobs (green) vs external repair cost (blue)</span></h3>
        ${_svgDualBar(trendMonths, 'jobs', 'externalCost', { h: 90 })}
        <div class="frow" style="justify-content:space-between;font-size:10px;color:var(--t4);margin-top:.3rem">
          ${trendMonths.map(m => `<span>${new Date(m.month).toLocaleDateString('en-GB',{month:'short'})}</span>`).join('')}
        </div>
      </div>
    </div>

    <div style="font-weight:600;font-size:13px;color:var(--t1);margin-bottom:.75rem"><i class="ti ti-scale" style="color:var(--g-soft)"></i> Workshop Comparison <span style="font-weight:400;color:var(--t3)">· last 90 days</span></div>
    <div class="card" style="padding:0;margin-bottom:1.25rem">
      <div class="tw"><table class="dt" style="font-size:12px">
        <thead><tr><th>Workshop</th><th>Open Jobs</th><th>Closed Jobs</th></tr></thead>
        <tbody>${workshopComparison.map(w => `<tr>
          <td style="font-weight:500">${w.workshop_name}</td>
          <td style="${w.open_jobs>0?'color:var(--amber);font-weight:600':''}">${w.open_jobs}</td>
          <td style="color:var(--green)">${w.closed_jobs}</td>
        </tr>`).join('')}</tbody>
      </table></div>
    </div>

    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:1rem;margin-bottom:1.25rem">
      ${_lgdWidget('Repeated Failures', 'ti-repeat', repeatedFailures.map(m => ({ label: `${m.machine_code} — ${m.name}`, sub: 'Last 90 days', badge: `${m.job_count} jobs`, warn: true })), 'No machines with 3+ jobs in the last 90 days.')}
      ${_lgdWidget('Technician Workload', 'ti-users', technicianWorkload.map(t => ({ label: t.name, sub: 'Open jobs assigned', badge: t.open_jobs, warn: t.open_jobs >= 5 })), 'No technicians currently assigned to open jobs.')}
      ${_lgdWidget('Recent Jobs', 'ti-activity', recentJobs.map(j => ({ label: j.title, sub: `${j.machine_code} — ${j.workshop_name||'—'}`, badge: MAINT_JOB_STATUS_META[j.status]?.label || j.status })), 'No maintenance jobs recorded yet.')}
    </div>
  `;
}

// ── Maintenance Reports (CSV export only, reusing the existing execExport pattern) ──

async function renderMaintenanceReports() {
  const pg = $('page-maintenance-reports');
  pg.innerHTML = `<div style="padding:2rem;color:var(--t3);font-size:13px"><i class="ti ti-loader-2" style="font-size:18px;animation:spin 1s linear infinite"></i> Loading…</div>`;

  const res = await UFCL.maintenanceReports(STORAGE.user.id, {});
  if (!res.ok) return renderDenied('maintenance-reports', res.error);

  const sections = [
    { key: 'maintenanceHistory', label: 'Maintenance History', icon: 'ti-history' },
    { key: 'downtimeSummary', label: 'Downtime Summary', icon: 'ti-clock-pause' },
    { key: 'externalRepairs', label: 'External Repair Report', icon: 'ti-truck-delivery' },
    { key: 'technicianActivity', label: 'Technician Activity', icon: 'ti-users' },
    { key: 'workshopPerformance', label: 'Workshop Performance', icon: 'ti-building-factory-2' },
    { key: 'assetReliability', label: 'Asset Reliability', icon: 'ti-shield-check' },
    { key: 'inventoryConsumption', label: 'Inventory Consumption Summary', icon: 'ti-package' },
  ];

  pg.innerHTML = `
    <div class="ptitle"><i class="ti ti-report-analytics" style="color:var(--g-soft)"></i> Maintenance Reports</div>
    <div class="psub" style="margin-bottom:1.25rem">Range: ${res.range.from} to ${res.range.to} · <strong>Total parts cost: RWF ${Math.round(res.costSummary.totalPartsCost).toLocaleString()}</strong></div>
    <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:1rem">
      ${sections.map(s => `
        <div class="card">
          <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.5rem">
            <h3 style="margin:0"><i class="ti ${s.icon}"></i> ${s.label}</h3>
            <span style="font-size:12px;color:var(--t3)">${(res[s.key]||[]).length} rows</span>
          </div>
          <button class="bs1 mr-export" data-key="${s.key}" data-label="${s.label}"><i class="ti ti-file-download"></i>Export CSV</button>
        </div>
      `).join('')}
    </div>
  `;

  document.querySelectorAll('.mr-export').forEach(btn => {
    btn.onclick = async () => {
      const key = btn.dataset.key;
      const rows = res[key] || [];
      if (!rows.length) { showToast('No rows to export for this section', 'error'); return; }
      const headers = Object.keys(rows[0]);
      const lines = [headers, ...rows.map(r => headers.map(h => r[h]))];
      const csv = lines.map(row => row.map(c => `"${String(c ?? '').replace(/"/g, '""')}"`).join(',')).join('\r\n');
      const filename = `${key}_${new Date().toISOString().slice(0, 10)}.csv`;
      const res2 = await UFCL.execExport(STORAGE.user.id, { csv, filename });
      if (!res2?.ok && res2?.error !== undefined) showToast('Export cancelled or failed', 'error');
    };
  });
}

