async function _finLoadReport() {
  const key = $('fin-rep-select').value;
  const bodyEl = $('fin-rep-body');
  bodyEl.innerHTML = `<p style="color:var(--t3);font-size:12px">Loading…</p>`;
  const filters = {
    date_from: $('fin-rep-datefrom').value || undefined, date_to: $('fin-rep-dateto').value || undefined,
    workshop_id: WORKSHOP_FILTER || undefined,
  };
  const label = FIN_REPORT_META[key].label;
  let res, columns = [], rows = [];

  if (key === 'revenue_summary') {
    res = await UFCL.financeDashboard(STORAGE.user.id, filters);
    if (res.ok) { rows = res.revenue.byWorkshop.map(w => ({ workshop_name: w.workshop_name || 'Unassigned', revenue: w.v })); columns = [['workshop_name', 'Workshop'], ['revenue', 'Revenue (Month)']]; }
  } else if (key === 'inventory_value') {
    res = await UFCL.financeInventoryOverview(STORAGE.user.id, filters);
    if (res.ok) { rows = res.topByValue; columns = [['name', 'Item'], ['category', 'Category'], ['total_qty', 'Qty'], ['unit_cost', 'Unit Cost'], ['total_value', 'Value (est.)']]; }
  } else if (key === 'stock_movement') {
    res = await UFCL.financeStockMovements(STORAGE.user.id, filters);
    if (res.ok) { rows = res.rows; columns = [['item_name', 'Item'], ['movement_type', 'Type'], ['quantity', 'Qty'], ['financial_impact', 'Financial Impact'], ['workshop_name', 'Workshop'], ['created_at', 'Date']]; }
  } else if (key === 'stock_variance') {
    res = await UFCL.financeStockVarianceReport(STORAGE.user.id, filters);
    if (res.ok) { rows = res.rows; columns = [['item_name', 'Item'], ['workshop_name', 'Workshop'], ['system_qty_snapshot', 'System Qty'], ['physical_qty', 'Physical Qty'], ['variance', 'Variance'], ['financial_variance', 'Financial Impact']]; }
  } else if (key === 'stock_count') {
    res = await UFCL.financeStockCountList(STORAGE.user.id, filters);
    if (res.ok) { rows = res.rows; columns = [['id', 'ID'], ['workshop_name', 'Workshop'], ['status', 'Status'], ['line_count', 'Lines'], ['variance_count', 'Variances'], ['initiated_at', 'Initiated']]; }
  } else if (key === 'inventory_adjustment') {
    res = await UFCL.financeInventoryAdjustmentReport(STORAGE.user.id, filters);
    if (res.ok) { rows = res.rows; columns = [['entity_ref', 'Adjustment'], ['status', 'Status'], ['submitted_by_name', 'Submitted By'], ['submitted_at', 'Submitted'], ['reviewed_by_name', 'Reviewed By'], ['reviewed_at', 'Reviewed']]; }
  } else if (key === 'workshop_cost') {
    res = await UFCL.financeWorkshopCostSummary(STORAGE.user.id, filters);
    if (res.ok) { rows = res.rows; columns = [['workshop_name', 'Workshop'], ['payroll_cost', 'Payroll Cost'], ['procurement_cost', 'Procurement Cost'], ['total_cost', 'Total Cost']]; }
  } else if (key === 'department_cost') {
    res = await UFCL.financeDepartmentCostSummary(STORAGE.user.id, filters);
    if (res.ok) { rows = res.rows; columns = [['department', 'Department'], ['po_count', 'PO Count'], ['procurement_cost', 'Procurement Cost']]; }
  } else if (key === 'approvals') {
    res = await UFCL.financeApprovalReport(STORAGE.user.id, filters);
    if (res.ok) { rows = res.rows; columns = [['entity_type', 'Type'], ['entity_id', 'ID'], ['stage_key', 'Stage'], ['status', 'Status'], ['assigned_role', 'Assigned Role'], ['approved_by_name', 'Decided By'], ['approved_at', 'Decided At'], ['notes', 'Notes']]; }
  } else if (key === 'exceptions') {
    res = await UFCL.financeExceptionReport(STORAGE.user.id);
    if (res.ok) { bodyEl.innerHTML = _finExceptionsHtml(res); _finLastReport = { columns: [], rows: [], label }; return; }
  } else if (key === 'audit') {
    res = await UFCL.financeAuditReport(STORAGE.user.id, filters);
    if (res.ok) { rows = res.rows; columns = [['created_at', 'When'], ['module', 'Module'], ['action_type', 'Action'], ['action', 'Description'], ['user_name', 'By'], ['role', 'Role']]; }
  } else if (key === 'ar') {
    res = await UFCL.financeCustomerOutstanding(STORAGE.user.id, filters);
    if (res.ok) { rows = res.rows; columns = [['customer_name', 'Customer'], ['unpaid_orders', 'Unpaid Orders'], ['outstanding', 'Outstanding']]; }
  } else if (key === 'ap') {
    res = await UFCL.financeSupplierOutstanding(STORAGE.user.id, filters);
    if (res.ok) { rows = res.rows; columns = [['supplier_name', 'Supplier'], ['invoice_count', 'Invoices'], ['invoiced', 'Invoiced'], ['paid', 'Paid'], ['outstanding', 'Outstanding']]; }
  }

  if (!res || !res.ok) { bodyEl.innerHTML = `<p style="color:var(--red);font-size:12px">${res?.error || 'Could not load report.'}</p>`; return; }
  _finLastReport = { columns, rows, label };
  if (!rows.length) { bodyEl.innerHTML = `<p style="color:var(--t3);font-size:12px">No data for this report.</p>`; return; }
  const NUM_KEYS = new Set([
    'outstanding', 'total_cost', 'procurement_cost', 'payroll_cost', 'invoiced', 'paid', 'po_count', 'unpaid_orders', 'invoice_count', 'entity_id',
    'revenue', 'total_qty', 'unit_cost', 'total_value', 'quantity', 'financial_impact', 'system_qty_snapshot', 'physical_qty', 'variance',
    'financial_variance', 'id', 'line_count', 'variance_count',
  ]);
  bodyEl.innerHTML = `<div class="tw"><table class="dt">
    <thead><tr>${columns.map(([, l]) => `<th>${l}</th>`).join('')}</tr></thead>
    <tbody>${rows.map(r => `<tr>${columns.map(([k]) => {
      const v = r[k];
      const isNum = NUM_KEYS.has(k);
      const isDate = k.endsWith('_at');
      return `<td style="${isNum ? 'font-family:var(--fm)' : ''}">${v == null ? '—' : (isNum ? Number(v).toLocaleString() : (isDate ? new Date(v).toLocaleString() : v))}</td>`;
    }).join('')}</tr>`).join('')}</tbody>
  </table></div>`;
}

// Surfaces exactly what Phase 1's audit found evidence for — never a
// fabricated risk score (mirrors financeExceptionReport's own comment).
function _finExceptionsHtml(res) {
  const sec = (title, rows, renderRow, headers) => `
    <h4 style="margin:1.1rem 0 .4rem">${title} (${rows.length})</h4>
    ${rows.length ? `<div class="tw"><table class="dt"><thead><tr>${headers.map(h => `<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(renderRow).join('')}</tbody></table></div>` : '<p style="color:var(--t3);font-size:12px">None.</p>'}`;
  return `
    <div style="display:flex;gap:2rem;flex-wrap:wrap;margin-bottom:.5rem;font-size:13px">
      <div><div style="color:var(--t3);font-size:11px">Total Exceptions</div><div style="font-weight:700;font-size:18px">${res.totalExceptions}</div></div>
    </div>
    ${sec('Stock Items Missing Cost', res.missingCostInfo, x => `<tr><td>${x.name}</td><td>${x.category || '—'}</td></tr>`, ['Item', 'Category'])}
    ${sec('Disputed Supplier Invoices', res.disputedInvoices, x => `<tr><td>${x.invoice_number}</td><td>${x.supplier_name}</td><td style="font-family:var(--fm)">${Number(x.invoice_amount).toLocaleString()}</td><td>${new Date(x.created_at).toLocaleDateString()}</td></tr>`, ['Invoice', 'Supplier', 'Amount', 'Date'])}
    ${sec('Rejected Payroll Periods', res.rejectedPayrollPeriods, x => `<tr><td>${x.start_date}</td><td>${x.end_date}</td></tr>`, ['Start', 'End'])}
    ${sec('Stale Approvals — pending &gt;5 days', res.staleApprovals, x => `<tr><td>${x.entity_type}</td><td>${x.entity_id}</td><td>${x.assigned_role}</td><td>${x.days_pending}</td></tr>`, ['Type', 'ID', 'Assigned Role', 'Days Pending'])}
    ${sec('Unpriced / Unapproved Active Products', res.unpricedProducts, x => `<tr><td>${[x.type, x.sub_type, x.size].filter(Boolean).join(' / ')}</td><td style="font-family:var(--fm)">${x.standard_cost != null ? Number(x.standard_cost).toLocaleString() : '—'}</td><td style="font-family:var(--fm)">${x.default_price != null ? Number(x.default_price).toLocaleString() : '—'}</td><td>${x.standard_cost_approved_by && !/^PENDING/i.test(x.standard_cost_approved_by) ? '<span class="badge bg">Yes</span>' : '<span class="badge br">No</span>'}</td><td>${x.default_price_approved_by && !/^PENDING/i.test(x.default_price_approved_by) ? '<span class="badge bg">Yes</span>' : '<span class="badge br">No</span>'}</td></tr>`, ['Product', 'Std Cost', 'Default Price', 'Cost Approved?', 'Price Approved?'])}
  `;
}

function _finExportReportCsv() {
  const { columns, rows, label } = _finLastReport;
  if (!columns.length || !rows.length) { showToast('Nothing to export for this report (exceptions report is not a flat table — use the on-screen sections).', 'info'); return; }
  const esc = (v) => `"${String(v == null ? '' : v).replace(/"/g, '""')}"`;
  const lines = [columns.map(([, l]) => esc(l)).join(','), ...rows.map(r => columns.map(([k]) => esc(r[k])).join(','))];
  downloadCsv(lines.join('\n'), `finance_${label.toLowerCase().replace(/[^a-z0-9]+/g, '_')}_${new Date().toISOString().slice(0, 10)}.csv`);
}

