async function _finSagePreview() {
  const el = $('fin-sage-preview-body');
  el.innerHTML = `<p style="color:var(--t3);font-size:12px">Loading…</p>`;
  const res = await UFCL.financeSageExportPreview(STORAGE.user.id, {
    date_from: $('fin-sage-from').value || undefined, date_to: $('fin-sage-to').value || undefined,
  });
  if (!res.ok) { el.innerHTML = `<p style="color:var(--red);font-size:12px">${res.error}</p>`; return; }
  const rows = res.rows || [];
  if (!rows.length) { el.innerHTML = `<p style="color:var(--t3);font-size:12px">No eligible transactions for this range.</p>`; return; }
  el.innerHTML = `<div class="tw"><table class="dt">
    <thead><tr><th>Date</th><th>Type</th><th>Reference</th><th>Party</th><th>Workshop</th><th>Amount</th><th>Already Exported</th></tr></thead>
    <tbody>${rows.map(r => `<tr>
      <td style="font-size:12px">${new Date(r.tx_date).toLocaleDateString()}</td>
      <td style="font-size:12px">${r.transaction_type}</td>
      <td style="font-family:var(--fm)">${r.reference}</td>
      <td>${r.party}</td>
      <td style="color:var(--t3);font-size:12px">${r.workshop_name || 'Company-wide'}</td>
      <td style="font-family:var(--fm);font-weight:600">${Number(r.amount).toLocaleString()}</td>
      <td>${r.already_exported ? '<span class="badge bg">Yes</span>' : '<span class="badge bt">No</span>'}</td>
    </tr>`).join('')}</tbody>
  </table></div><p style="color:var(--t3);font-size:11px;margin-top:.5rem">${rows.filter(r => !r.already_exported).length} new record(s) will be included if you export now.</p>`;
}

async function _finSageRun() {
  showToast('Generating Sage export…', 'info');
  const res = await UFCL.financeSageExportRun(STORAGE.user.id, {
    date_from: $('fin-sage-from').value || undefined, date_to: $('fin-sage-to').value || undefined,
  });
  if (!res.ok) { showToast(res.error || 'Could not generate export.', 'error'); return; }
  const byteChars = atob(res.base64);
  const byteNumbers = new Array(byteChars.length);
  for (let i = 0; i < byteChars.length; i++) byteNumbers[i] = byteChars.charCodeAt(i);
  const blob = new Blob([new Uint8Array(byteNumbers)], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = res.filename;
  document.body.appendChild(a); a.click(); a.remove();
  URL.revokeObjectURL(url);
  showToast(`Exported ${res.rowCount} record(s) to ${res.filename}.`, 'success');
  await _finSagePreview();
  await _finSageHistory();
}

async function _finSageHistory() {
  const el = $('fin-sage-history');
  if (!el) return;
  const res = await UFCL.financeSageExportHistory(STORAGE.user.id, {});
  if (!res.ok) { el.innerHTML = `<p style="color:var(--red);font-size:12px">${res.error}</p>`; return; }
  const rows = res.rows || [];
  if (!rows.length) { el.innerHTML = `<p style="color:var(--t3);font-size:12px">No exports recorded yet.</p>`; return; }
  el.innerHTML = `<div class="tw"><table class="dt">
    <thead><tr><th>Exported At</th><th>Module</th><th>Record</th><th>Type</th><th>By</th><th>Status</th></tr></thead>
    <tbody>${rows.map(r => `<tr>
      <td style="font-size:12px">${new Date(r.exported_at).toLocaleString()}</td>
      <td style="font-size:12px">${r.source_module}</td>
      <td>${r.source_record_id}</td>
      <td style="font-size:12px">${r.transaction_type || '—'}</td>
      <td>${r.exported_by_name || '—'}</td>
      <td><span class="badge ${r.reconciliation_status === 'reconciled' ? 'bg' : r.reconciliation_status === 'disputed' ? 'br' : 'bt'}">${r.reconciliation_status}</span></td>
    </tr>`).join('')}</tbody>
  </table></div>`;
}

