async function renderTrash() {
  const pg = $('page-trash');
  pg.innerHTML = `<div style="padding:2rem;color:var(--t3);font-size:13px"><i class="ti ti-loader-2" style="font-size:18px;animation:spin 1s linear infinite"></i> Loading…</div>`;

  if (!canManageTrash()) {
    pg.innerHTML = `<div class="ptitle"><i class="ti ti-trash" style="color:var(--red)"></i> Trash</div>
      <div class="psub" style="color:var(--t3)">Only Admin, CEO, and Operations roles can view and manage the Trash.</div>`;
    return;
  }

  const res = await UFCL.trashList(STORAGE.user.id);
  if (!res.ok) return renderDenied('trash', res.error);

  const rows = res.rows || [];

  pg.innerHTML = `
    <div class="ptitle"><i class="ti ti-trash" style="color:var(--red)"></i> Trash</div>
    <div class="psub">Soft-deleted records are kept for 30 days. Restore to undo, or Purge to permanently remove.</div>
    <div class="card" style="padding:0">
      <div style="padding:1rem 1.25rem;border-bottom:1px solid var(--bdr)">
        <h3 style="margin:0"><i class="ti ti-trash"></i>Deleted Records (${rows.length})</h3>
      </div>
      <div class="tw"><table class="dt">
        <thead><tr>
          <th>Type</th><th>Record</th><th>Deleted By</th><th>Deleted At</th><th>Reason</th><th>Days Left</th><th>Actions</th>
        </tr></thead>
        <tbody>
          ${rows.length === 0
            ? `<tr><td colspan="7" style="text-align:center;color:var(--t3);padding:2rem">Trash is empty.</td></tr>`
            : rows.map(r => `<tr>
                <td><span class="badge bt" style="font-size:11px">${r.label}</span></td>
                <td style="font-weight:600">${r.entity_ref || '#' + r.record_id}</td>
                <td style="color:var(--t3);font-size:12px">${r.deleted_by_name || '—'}</td>
                <td style="font-family:var(--fm);font-size:12px;color:var(--t3)">${r.deleted_at}</td>
                <td style="font-size:12px;color:var(--t3);max-width:200px">${r.deletion_reason || '—'}</td>
                <td>
                  <span class="badge ${Number(r.days_remaining) <= 3 ? 'br' : Number(r.days_remaining) <= 7 ? 'ba' : 'bg'}">
                    ${r.days_remaining}d
                  </span>
                </td>
                <td style="white-space:nowrap;display:flex;gap:4px">
                  <button class="bp1 tr-restore" data-table="${r.table_name}" data-id="${r.record_id}" style="padding:4px 10px;font-size:12px;background:var(--green,#22c55e);border-color:var(--green,#22c55e)">
                    <i class="ti ti-arrow-back-up"></i>Restore
                  </button>
                  <button class="bs1 tr-purge" data-table="${r.table_name}" data-id="${r.record_id}" style="padding:4px 10px;font-size:12px;color:var(--red)">
                    <i class="ti ti-flame"></i>Purge
                  </button>
                </td>
              </tr>`).join('')}
        </tbody>
      </table></div>
    </div>`;

  pg.querySelectorAll('.tr-restore').forEach(btn => {
    btn.onclick = async () => {
      if (!confirm(`Restore this record? It will reappear in its original list.`)) return;
      const r = await UFCL.trashRestore(STORAGE.user.id, btn.dataset.table, btn.dataset.id);
      if (!r.ok) { alert(r.error); return; }
      await renderTrash();
    };
  });

  pg.querySelectorAll('.tr-purge').forEach(btn => {
    btn.onclick = () => {
      if (STORAGE.user?.role !== 'admin' && STORAGE.user?.role !== 'ceo') {
        alert('Only Admin or CEO can permanently purge records.');
        return;
      }
      confirmDelete('Permanently delete this record? This cannot be undone.', async () => {
        const r = await UFCL.trashPurge(STORAGE.user.id, btn.dataset.table, btn.dataset.id);
        if (!r.ok) { alert(r.error); return; }
        showOverlaySuccess('Record permanently deleted.');
        await renderTrash();
      });
    };
  });
}

function wireLogin() {
  const uname = $('uname');
  const upass = $('upass');
  const lerr = $('lerr');

  function strength(v) {
    const s = $('pwStrength');
    const p = String(v || '');
    let score = 0;
    if (p.length >= 8) score += 25;
    if (/[A-Z]/.test(p)) score += 25;
    if (/[0-9]/.test(p)) score += 25;
    if (/[^A-Za-z0-9]/.test(p)) score += 25;
    s.style.width = `${score}%`;
    s.style.background = score >= 75 ? '#22C55E' : score >= 50 ? '#F59E0B' : '#EF4444';
  }

  upass.addEventListener('input', () => strength(upass.value));

  async function doLogin() {
    console.log('[renderer] Starting login');
    lerr.style.display = 'none';
    try {
      const res = await UFCL.login(uname.value, upass.value);
      if (!res.ok) {
        lerr.textContent = res.error || 'Invalid username or password';
        lerr.style.display = 'block';
        return;
      }
      STORAGE.user = res.user;
      // Keep the login view visible while the app bootstraps to avoid
      console.log('[renderer] Login successful, starting bootstrap');
      // showing an empty shell if bootstrap fails or times out.
      const loginBtn = $('loginBtn');
      if (loginBtn) loginBtn.disabled = true;
      const timeoutMs = 10_000;
      const t = new Promise((_, rej) => setTimeout(() => rej(new Error('Startup timed out (DB connection?)')), timeoutMs));
      await Promise.race([bootstrap(), t]);

      if (loginBtn) loginBtn.disabled = false;
      show($('loginView'), false);
      // Ensure the shell is shown as a flex container (overrides CSS display:none).
      const shellEl = $('shell');
      if (shellEl) shellEl.style.display = 'flex';
    } catch (e) {
      const msg = e?.message || String(e);
      lerr.textContent = `Login OK, but app failed to load: ${msg}`;
      lerr.style.display = 'block';
      // revert UI
      const loginBtn = $('loginBtn');
      if (loginBtn) loginBtn.disabled = false;
      const shellEl = $('shell');
      if (shellEl) shellEl.style.display = 'none';
      show($('loginView'), true);
      STORAGE.user = null;
    }
  }

  const loginBtn = $('loginBtn');
  if (loginBtn) {
    loginBtn.disabled = false;
    loginBtn.onclick = doLogin;
    loginBtn.addEventListener('click', doLogin);
  }
  upass.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') doLogin();
  });
  uname.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') upass.focus();
  });
}

function wireUpdateBanner() {
  if (!window.UFCL || typeof UFCL.onUpdateAvailable !== 'function') return;

  const BANNER_STYLE = `
    position:fixed;top:0;left:0;right:0;z-index:9999;
    background:linear-gradient(135deg,#1a6b3c,#145c33);
    color:#fff;padding:14px 20px;
    display:flex;align-items:center;gap:16px;flex-wrap:wrap;
    box-shadow:0 2px 12px rgba(0,0,0,.35);
    font-family:var(--ff,system-ui);font-size:14px;line-height:1.4;
    animation:slideDown .3s ease;
  `;
  const BTN = `background:rgba(255,255,255,.18);border:1px solid rgba(255,255,255,.35);color:#fff;border-radius:6px;padding:6px 14px;cursor:pointer;font-size:13px;white-space:nowrap`;
  const BTN_PRIMARY = `background:rgba(255,255,255,.95);border:1px solid rgba(255,255,255,.95);color:#145c33;border-radius:6px;padding:6px 14px;cursor:pointer;font-size:13px;font-weight:600;white-space:nowrap`;

  function injectStyle() {
    if (document.getElementById('update-banner-style')) return;
    const s = document.createElement('style');
    s.id = 'update-banner-style';
    s.textContent = `@keyframes slideDown{from{transform:translateY(-100%);opacity:0}to{transform:translateY(0);opacity:1}}`;
    document.head.appendChild(s);
  }

  function showBanner(html) {
    let banner = $('update-banner');
    if (!banner) {
      banner = document.createElement('div');
      banner.id = 'update-banner';
      banner.style.cssText = BANNER_STYLE;
      injectStyle();
      document.body.prepend(banner);
    }
    banner.innerHTML = html;
    const shell = $('shell');
    if (shell) shell.style.marginTop = banner.offsetHeight + 'px';
    return banner;
  }

  function removeBanner() {
    const b = $('update-banner');
    if (b) b.remove();
    const shell = $('shell');
    if (shell) shell.style.marginTop = '';
  }

  function fmtBytes(n) {
    if (n > 1048576) return (n / 1048576).toFixed(1) + ' MB';
    return (n / 1024).toFixed(0) + ' KB';
  }

  UFCL.onUpdateAvailable((data) => {
    if (!data || !data.latest) return;
    // Check snooze
    try {
      const snooze = localStorage.getItem('update-snooze');
      if (snooze && Date.now() < Number(snooze)) return;
      const skip = localStorage.getItem('update-skip');
      if (skip === data.latest) return;
    } catch {}

    const notes = (data.notes || []).map(n => `<li style="margin-top:3px">${n}</li>`).join('');
    showBanner(`
      <i class="ti ti-arrow-up-circle" style="font-size:22px;flex-shrink:0"></i>
      <div style="flex:1;min-width:0">
        <strong>Version ${data.latest} is available</strong>
        <span style="opacity:.65;margin-left:8px;font-size:12px">you have v${data.current}</span>
        ${notes ? `<ul style="margin:5px 0 0 16px;padding:0;font-size:12px;opacity:.9">${notes}</ul>` : ''}
      </div>
      <div style="display:flex;gap:8px;flex-shrink:0;flex-wrap:wrap">
        <button id="upd-now" style="${BTN_PRIMARY}"><i class="ti ti-download"></i> Update Now</button>
        <button id="upd-later" style="${BTN}">Remind Me Later</button>
        <button id="upd-skip" style="${BTN}">Skip This Version</button>
      </div>`);

    $('upd-now').onclick = async () => {
      showBanner(`
        <i class="ti ti-download" style="font-size:22px;flex-shrink:0"></i>
        <div style="flex:1;min-width:200px">
          <strong>Downloading version ${data.latest}…</strong>
          <div id="upd-bar-wrap" style="background:rgba(255,255,255,.25);border-radius:4px;height:6px;margin-top:8px;overflow:hidden">
            <div id="upd-bar" style="background:#fff;height:100%;width:0%;transition:width .3s ease"></div>
          </div>
          <div id="upd-bar-label" style="font-size:12px;opacity:.8;margin-top:4px">Starting…</div>
        </div>`);

      const res = await UFCL.startUpdateDownload();
      if (!res || !res.ok) {
        showBanner(`
          <i class="ti ti-alert-circle" style="font-size:22px;flex-shrink:0"></i>
          <div style="flex:1">
            <strong>Download failed</strong>
            <div style="font-size:12px;opacity:.85;margin-top:3px">${res?.error || 'Unknown error'} — the current version is still running normally.</div>
          </div>
          <button id="upd-dismiss-err" style="${BTN}">Dismiss</button>`);
        const d = $('upd-dismiss-err'); if (d) d.onclick = removeBanner;
      }
    };

    $('upd-later').onclick = () => {
      try { localStorage.setItem('update-snooze', String(Date.now() + 86400000)); } catch {}
      removeBanner();
    };

    $('upd-skip').onclick = () => {
      try { localStorage.setItem('update-skip', data.latest); } catch {}
      removeBanner();
    };
  });

  UFCL.onUpdateProgress((p) => {
    const bar = $('upd-bar');
    const label = $('upd-bar-label');
    if (bar) bar.style.width = p.percent + '%';
    if (label) label.textContent = `${p.percent}%  —  ${fmtBytes(p.transferred)} / ${fmtBytes(p.total)}`;
  });

  UFCL.onUpdateDownloaded((d) => {
    showBanner(`
      <i class="ti ti-circle-check" style="font-size:22px;flex-shrink:0"></i>
      <div style="flex:1">
        <strong>Version ${d.version} is ready to install</strong>
        <div style="font-size:12px;opacity:.85;margin-top:3px">Your data will not be affected. The app will restart automatically.</div>
      </div>
      <div style="display:flex;gap:8px;flex-shrink:0;flex-wrap:wrap">
        <button id="upd-install" style="${BTN_PRIMARY}"><i class="ti ti-refresh"></i> Restart &amp; Install</button>
        <button id="upd-later2" style="${BTN}">Install on Next Launch</button>
      </div>`);
    $('upd-install').onclick = () => UFCL.installUpdate();
    $('upd-later2').onclick = removeBanner;
  });

  UFCL.onUpdateError((e) => {
    if (!$('update-banner')) return;
    showBanner(`
      <i class="ti ti-alert-circle" style="font-size:22px;flex-shrink:0"></i>
      <div style="flex:1">
        <strong>Update error</strong>
        <div style="font-size:12px;opacity:.85;margin-top:3px">${e.message || 'Unknown error'} — running current version normally.</div>
      </div>
      <button id="upd-dismiss-err2" style="${BTN}">Dismiss</button>`);
    const d = $('upd-dismiss-err2'); if (d) d.onclick = removeBanner;
  });
}

function wireTopbar() {
  $('logoutBtn').onclick = async () => {
    stopNotificationPoll();
    await UFCL.logout();
    STORAGE.user = null;
    show($('shell'), false);
    show($('loginView'), true);
    $('upass').value = '';
  };
  $('searchBtn').onclick = () => openGlobalSearch();
  $('notifBtn').onclick = () => showPage('notifications');
  $('refreshBtn').onclick = () => showPage(CURRENT_PAGE);

  // Ctrl+K (Cmd+K on macOS) opens Global Search from anywhere; Escape returns
  // to whatever page was active before search was opened. No prior keydown
  // infrastructure existed in this app — this is the first global shortcut.
  document.addEventListener('keydown', (e) => {
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') {
      e.preventDefault();
      if (CURRENT_PAGE === 'search') { const q = $('gs-q'); if (q) q.focus(); }
      else openGlobalSearch();
    } else if (e.key === 'Escape' && CURRENT_PAGE === 'search' && _SEARCH.returnPage) {
      const back = _SEARCH.returnPage;
      _SEARCH.returnPage = null;
      showPage(back);
    }
  });

  const sidebar = $('sidebar');
  const toggleBtn = $('sidebarToggle');
  const toggleIcon = $('sidebarToggleIcon');

  function setSidebarCollapsed(collapsed) {
    sidebar.classList.toggle('collapsed', collapsed);
    if (toggleIcon) {
      toggleIcon.className = collapsed
        ? 'ti ti-layout-sidebar-left-expand'
        : 'ti ti-layout-sidebar-left-collapse';
    }
    try { localStorage.setItem('sidebarCollapsed', collapsed ? '1' : '0'); } catch {}
  }

  if (toggleBtn) {
    toggleBtn.onclick = () => setSidebarCollapsed(!sidebar.classList.contains('collapsed'));
    try {
      if (localStorage.getItem('sidebarCollapsed') === '1') setSidebarCollapsed(true);
    } catch {}
  }
}

window.addEventListener('DOMContentLoaded', () => {
  // Global error handlers to capture renderer exceptions during bootstrap/login.
  window.addEventListener('error', (ev) => {
    try { console.error('[renderer:error]', ev.message || ev); } catch (e) {}
  });
  window.addEventListener('unhandledrejection', (ev) => {
    try { console.error('[renderer:unhandledrejection]', ev.reason || ev); } catch (e) {}
  });

  try {
    if (!window.UFCL) {
      document.body.innerHTML = `<div style="font-family:Arial;padding:24px">
        <h2>UFCL app failed to load</h2>
        <p>Preload bridge <code>UFCL</code> is missing. Please restart the app.</p>
      </div>`;
      return;
    }
    wireLogin();
    wireTopbar();
    wireUpdateBanner();
    window.addEventListener('unload', stopNotificationPoll);
  } catch (e) {
    const msg = e?.message || String(e);
    document.body.innerHTML = `<div style="font-family:Arial;padding:24px">
      <h2>UFCL app error</h2>
      <pre style="white-space:pre-wrap;background:#f3f4f6;padding:12px;border-radius:8px">${msg}</pre>
    </div>`;
  }
});

// ── Phase 8 Parts 5-11 — Automation Center ───────────────────────────────────

// 7-day SVG bar chart for automation activity
function _acBarChart(activityByDay) {
  const days = [];
  for (let i = 6; i >= 0; i--) {
    const d   = new Date(Date.now() - i * 86_400_000);
    const key = d.toISOString().slice(0, 10);
    const hit = (activityByDay || []).find(x => x.day === key);
    days.push({ label: d.toLocaleDateString('en-GB', { weekday: 'short' }), count: Number(hit?.count) || 0 });
  }
  const maxC = Math.max(...days.map(d => d.count), 1);
  const W = 300, H = 72, barW = Math.floor(W / 7) - 5;
  const bars = days.map((d, i) => {
    const bh = Math.max(2, Math.round((d.count / maxC) * (H - 22)));
    const x  = i * (barW + 5) + 2;
    const y  = H - 18 - bh;
    return `<rect x="${x}" y="${y}" width="${barW}" height="${bh}" fill="${d.count > 0 ? '#3b82f6' : '#e5e7eb'}" rx="2"/>
      <text x="${x + barW / 2}" y="${H - 2}" text-anchor="middle" font-size="8" fill="#9ca3af">${d.label}</text>
      ${d.count > 0 ? `<text x="${x + barW / 2}" y="${y - 3}" text-anchor="middle" font-size="9" fill="#1d4ed8" font-weight="600">${d.count}</text>` : ''}`;
  }).join('');
  return `<svg width="${W}" height="${H}" style="display:block;overflow:visible;margin:0 auto">${bars}</svg>`;
}

function _acExportHistoryCsv(logRows) {
  const header = 'Rule,Module,Record ID,Action,Fired At';
  const csv = (logRows || []).map(r => [
    `"${(r.rule_key        || '').replace(/"/g, '""')}"`,
    `"${(r.related_module  || '').replace(/"/g, '""')}"`,
    `"${(r.related_id      || '').replace(/"/g, '""')}"`,
    `"${(r.action_taken    || '').replace(/"/g, '""')}"`,
    `"${(r.fired_at        || '').replace(/"/g, '""')}"`,
  ].join(',')).join('\n');
  downloadCsv(`${header}\n${csv}`, `automation_history_${new Date().toISOString().slice(0, 10)}.csv`);
}

function _acPrintReport(res) {
  const { summary: sm, scheduler: sch, rules, automation_log } = res;
  const ts = new Date().toLocaleString();
  const win = window.open('', '_blank', 'width=900,height=700');
  if (!win) { showToast('Allow pop-ups to print the report.', 'warning'); return; }
  win.document.write(`<!DOCTYPE html><html><head>
  <title>UFCL Automation Report</title>
  <style>
    body{font-family:Arial,sans-serif;font-size:12px;color:#111;padding:24px}
    h1{font-size:18px;margin-bottom:4px} h2{font-size:13px;margin:14px 0 5px;border-bottom:1px solid #ccc;padding-bottom:3px}
    .krow{display:flex;gap:12px;margin-bottom:14px} .kpi{background:#f9fafb;border:1px solid #e5e7eb;border-radius:6px;padding:8px 12px}
    .kn{font-size:20px;font-weight:700} .kl{font-size:11px;color:#6b7280}
    table{width:100%;border-collapse:collapse} th{background:#f3f4f6;text-align:left;padding:4px 8px;font-size:11px}
    td{padding:3px 8px;border-bottom:1px solid #f0f0f0;font-size:11px}
    @media print{body{padding:0}}
  </style></head><body>
  <h1>UFCL Automation Center Report</h1>
  <div style="color:#6b7280;margin-bottom:14px">Generated: ${ts}</div>
  <h2>Summary</h2>
  <div class="krow">
    <div class="kpi"><div class="kn">${sm.rules_enabled}/${sm.rules_total}</div><div class="kl">Rules Active</div></div>
    <div class="kpi"><div class="kn">${sm.active_escalations}</div><div class="kl">Active Escalations</div></div>
    <div class="kpi"><div class="kn">${sm.failed_jobs}</div><div class="kl">Failed Jobs</div></div>
    <div class="kpi"><div class="kn">${sm.automations_24h}</div><div class="kl">Automations (24h)</div></div>
    <div class="kpi"><div class="kn">${sm.ticks_24h}</div><div class="kl">Scheduler Ticks (24h)</div></div>
  </div>
  <h2>Scheduler</h2>
  <p>Last run: ${sch.last_automation ? new Date(sch.last_automation).toLocaleString() : 'N/A'} ·
     Avg tick: ${sm.avg_tick_ms != null ? sm.avg_tick_ms + 'ms' : 'N/A'}</p>
  <h2>Rule Status</h2>
  <table><tr><th>Rule</th><th>Key</th><th>Enabled</th><th>Severity</th><th>Action</th><th>Last Fired</th></tr>
  ${(rules || []).map(r => `<tr>
    <td>${r.label}</td><td>${r.rule_key}</td>
    <td>${r.enabled ? 'Yes' : 'No'}</td><td>${r.severity}</td><td>${r.auto_action}</td>
    <td>${r.last_fired ? new Date(r.last_fired).toLocaleString() : 'Never'}</td>
  </tr>`).join('')}</table>
  <h2>Automation Log</h2>
  <table><tr><th>Rule</th><th>Module</th><th>Action</th><th>Time</th></tr>
  ${(automation_log || []).map(l => `<tr>
    <td>${l.rule_key}</td><td>${l.related_module || '—'}</td>
    <td>${l.action_taken}</td><td>${l.fired_at ? new Date(l.fired_at).toLocaleString() : '—'}</td>
  </tr>`).join('')}</table>
  <script>window.onload=()=>window.print();</script></body></html>`);
  win.document.close();
}

async function renderAutomationCenter() {
  _autoLastLoad = Date.now();
  const el = $('page-automation');
  el.innerHTML = `<div class="ptitle"><i class="ti ti-robot"></i> Automation Center</div>
    <div class="card" style="padding:32px;text-align:center">
      <i class="ti ti-loader-2 spin"></i> Loading automation data…</div>`;

  const res = await UFCL.automationDashboard(STORAGE.user.id);
  if (!res?.ok) {
    el.innerHTML = `<div class="ptitle"><i class="ti ti-robot"></i> Automation Center</div>
      <div class="card" style="padding:24px;color:var(--red)">
        <i class="ti ti-alert-circle"></i> ${res?.error || 'Load failed'}</div>`;
    return;
  }

  // Stash full response on the page element so export/print can access it
  el._acData = res;

  const { summary: sm, scheduler: sch, rules, automation_log, pending_jobs,
          failed_jobs, escalations, activity_by_day } = res;
  const active      = escalations?.active      || [];
  const levelCounts = escalations?.level_counts || {};
  const recentRuns  = sch.recent_runs           || [];
  const ts = new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });

  const fmtAgo = (iso) => {
    if (!iso) return '—';
    const mins = Math.floor((Date.now() - new Date(iso)) / 60000);
    if (mins < 1)    return 'just now';
    if (mins < 60)   return `${mins}m ago`;
    if (mins < 1440) return `${Math.floor(mins / 60)}h ago`;
    return `${Math.floor(mins / 1440)}d ago`;
  };

  const sevColor = { critical:'#dc2626', high:'#d97706', medium:'#2563eb', low:'#16a34a', info:'#6366f1' };
  const sevBg    = { critical:'#fee2e2', high:'#fef3c7', medium:'#dbeafe', low:'#dcfce7', info:'#e0e7ff' };
  const lvlColor = { leader:'#0369a1', manager:'#b45309', director:'#9a3412', ceo:'#991b1b' };
  const lvlBg    = { leader:'#e0f2fe', manager:'#fef3c7', director:'#fed7aa', ceo:'#fee2e2' };

  const sevBadge = (sev) =>
    `<span style="background:${sevBg[sev]||'#f3f4f6'};color:${sevColor[sev]||'#374151'};padding:2px 7px;border-radius:12px;font-size:11px;font-weight:600">${(sev||'—').toUpperCase()}</span>`;

  const actionBadge = (action) => {
    const map = { notify:['#dbeafe','#1d4ed8'], draft_request:['#dcfce7','#166534'], escalate:['#fef3c7','#92400e'], log_only:['#f3f4f6','#6b7280'] };
    const [bg, fg] = map[action] || ['#f3f4f6','#6b7280'];
    return `<span style="background:${bg};color:${fg};padding:2px 7px;border-radius:12px;font-size:11px;font-weight:600">${(action||'—').replace('_',' ')}</span>`;
  };

  const lvlBadge = (lvl) =>
    `<span style="background:${lvlBg[lvl]||'#f3f4f6'};color:${lvlColor[lvl]||'#374151'};padding:2px 7px;border-radius:12px;font-size:11px;font-weight:700;text-transform:uppercase">${lvl||'—'}</span>`;

  // ── KPI cards ─────────────────────────────────────────────────────────────────
  const kpiHtml = `
    <div class="sg-grid4" style="margin-bottom:1rem">
      <div class="sg-kpi${sm.rules_disabled > 0 ? ' sg-kpi-amber' : ' sg-kpi-green'}">
        <div class="sg-kpi-n">${sm.rules_enabled}<span style="font-size:14px;color:var(--t3);font-weight:500"> / ${sm.rules_total}</span></div>
        <div class="sg-kpi-l">Rules Active</div>
        <div class="sg-kpi-s">${sm.rules_disabled} disabled</div>
      </div>
      <div class="sg-kpi${sm.active_escalations > 0 ? ' sg-kpi-red' : ' sg-kpi-green'}">
        <div class="sg-kpi-n">${sm.active_escalations}</div>
        <div class="sg-kpi-l">Active Escalations</div>
        <div class="sg-kpi-s">CEO:${levelCounts.ceo||0} · Dir:${levelCounts.director||0} · Mgr:${levelCounts.manager||0}</div>
      </div>
      <div class="sg-kpi${sm.failed_jobs > 0 ? ' sg-kpi-red' : ' sg-kpi-green'}">
        <div class="sg-kpi-n">${sm.failed_jobs}</div>
        <div class="sg-kpi-l">Failed Jobs</div>
        <div class="sg-kpi-s">${sm.pending_jobs} pending</div>
      </div>
      <div class="sg-kpi">
        <div class="sg-kpi-n">${sm.automations_24h}</div>
        <div class="sg-kpi-l">Automations (24h)</div>
        <div class="sg-kpi-s">${sm.ticks_24h} ticks · avg ${sm.avg_tick_ms != null ? sm.avg_tick_ms + 'ms' : '—'}</div>
      </div>
    </div>`;

  // ── System Status — health + activity chart ────────────────────────────────────
  const lastRun   = recentRuns[0];
  const totalRuns = recentRuns.length;
  const errRuns   = recentRuns.filter(r => r.errors > 0).length;
  const healthClr = !totalRuns ? '#9ca3af' : errRuns === 0 ? 'var(--green)' : errRuns < totalRuns / 2 ? '#d97706' : 'var(--red)';
  const healthTxt = !totalRuns ? 'No data' : errRuns === 0 ? 'Healthy' : `${errRuns}/${totalRuns} ticks had errors`;

  const recentRunsRows = recentRuns.length === 0
    ? `<div style="padding:.75rem;text-align:center;color:var(--t3);font-size:12px">No runs recorded yet.</div>`
    : recentRuns.map(r => {
        const dot = r.errors > 0 ? 'var(--amber)' : 'var(--green)';
        return `<div style="display:grid;grid-template-columns:8px 1fr auto auto;align-items:center;gap:.375rem .75rem;padding:.3rem 0;border-bottom:1px solid var(--bd)">
          <span style="width:7px;height:7px;border-radius:50%;background:${dot};display:inline-block;flex-shrink:0"></span>
          <span style="font-size:11px;color:var(--t2)">${fmtAgo(r.started_at)}</span>
          <span style="font-size:11px;color:var(--t3)">${r.duration_ms != null ? r.duration_ms + 'ms' : '—'}</span>
          <span style="font-size:11px;color:${r.errors > 0 ? 'var(--red)' : 'var(--t3)'}">${r.errors > 0 ? r.errors + ' err' : '✓'}</span>
        </div>`;
      }).join('');

  const statusPanel = `
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin-bottom:1rem">
      <div class="card" style="padding:1rem">
        <div style="font-weight:700;font-size:13px;margin-bottom:.75rem"><i class="ti ti-heart-rate-monitor" style="color:var(--blue);margin-right:5px"></i>System Status</div>
        <div style="display:flex;align-items:center;gap:.5rem;margin-bottom:.75rem">
          <span style="width:11px;height:11px;border-radius:50%;background:${healthClr};flex-shrink:0"></span>
          <span style="font-weight:600;font-size:13px">${healthTxt}</span>
        </div>
        <div style="font-size:12px;color:var(--t2);line-height:1.9;margin-bottom:.75rem">
          <div>Interval: <strong>15 min</strong> · Last run: <strong>${fmtAgo(sch.last_automation)}</strong></div>
          <div>Last security scan: <strong>${fmtAgo(sch.last_security)}</strong></div>
          <div>Avg tick: <strong>${sm.avg_tick_ms != null ? sm.avg_tick_ms + 'ms' : '—'}</strong> · Ticks 24h: <strong>${sm.ticks_24h}</strong></div>
        </div>
        <div style="font-weight:600;font-size:11px;color:var(--t3);text-transform:uppercase;letter-spacing:.05em;margin-bottom:.25rem">Recent Runs</div>
        <div>${recentRunsRows}</div>
      </div>
      <div class="card" style="padding:1rem">
        <div style="font-weight:700;font-size:13px;margin-bottom:.5rem"><i class="ti ti-chart-bar" style="color:var(--blue);margin-right:5px"></i>Automation Activity — Last 7 Days</div>
        <div style="margin:.75rem 0">${_acBarChart(activity_by_day)}</div>
        <div style="display:flex;justify-content:space-between;margin-top:.75rem">
          ${['leader','manager','director','ceo'].map(lvl => `
            <div style="text-align:center">
              ${lvlBadge(lvl)}
              <div style="font-weight:700;font-size:14px;margin-top:3px;color:${levelCounts[lvl] > 0 ? lvlColor[lvl] : 'var(--t3)'}">${levelCounts[lvl] || 0}</div>
            </div>`).join('')}
        </div>
      </div>
    </div>`;

  // ── Rule status table ─────────────────────────────────────────────────────────
  const ruleRows = (rules || []).map(r => `
    <div style="display:grid;grid-template-columns:10px 1fr auto auto auto auto;align-items:center;gap:.4rem .9rem;padding:.5rem 0;border-bottom:1px solid var(--bd)">
      <span style="width:8px;height:8px;border-radius:50%;background:${r.enabled ? 'var(--green)' : 'var(--red)'};display:inline-block;flex-shrink:0"></span>
      <div>
        <div style="font-weight:600;font-size:13px">${r.label}</div>
        <div style="font-size:11px;color:var(--t3)">${r.rule_key} · cooldown ${r.cooldown_hours}h · last: ${fmtAgo(r.last_fired)}</div>
      </div>
      ${sevBadge(r.severity)}
      ${actionBadge(r.auto_action)}
      <button class="bs1" style="font-size:11px;padding:3px 10px" onclick="_acToggleRule('${r.rule_key}',${!r.enabled})">${r.enabled ? 'Disable' : 'Enable'}</button>
      <button class="bs1" style="font-size:11px;padding:3px 10px" onclick="_acEditRule('${r.rule_key}')"><i class="ti ti-edit" style="font-size:11px"></i> Edit</button>
      <button class="bs1" style="font-size:11px;padding:3px 10px;color:var(--red)" onclick="_acDeleteRule('${r.rule_key}','${(r.label||r.rule_key).replace(/'/g,"\\'")}')"><i class="ti ti-trash" style="font-size:11px"></i></button>
    </div>`).join('');

  // Master Professionalization Phase C3 (PR-22/23) — createAutomationRule/
  // deleteAutomationRule were both already fully built, validated, IPC-wired,
  // and preload-exposed (UFCL.automationCreate/automationDelete) with zero UI
  // call site anywhere — the one genuine "backend exists, no UI" finding out
  // of 407 functions audited in the Master Professionalization Phase 1 pass.
  const rulesPanel = `
    <div class="card" style="padding:1rem">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem">
        <div style="font-weight:700;font-size:13px"><i class="ti ti-cpu" style="color:var(--blue);margin-right:5px"></i>Rule Status</div>
        <button class="bs1" id="ac-new-rule-btn" style="font-size:11px;padding:3px 10px"><i class="ti ti-plus" style="font-size:11px"></i> New Rule</button>
      </div>
      <div style="display:grid;grid-template-columns:10px 1fr auto auto auto auto auto;gap:.25rem .9rem;padding:.375rem 0;border-bottom:2px solid var(--bd);margin-bottom:.125rem">
        <span></span>
        <span style="font-size:11px;font-weight:600;color:var(--t3);text-transform:uppercase;letter-spacing:.05em">Rule</span>
        <span style="font-size:11px;font-weight:600;color:var(--t3);text-transform:uppercase;letter-spacing:.05em">Severity</span>
        <span style="font-size:11px;font-weight:600;color:var(--t3);text-transform:uppercase;letter-spacing:.05em">Action</span>
        <span></span><span></span><span></span>
      </div>
      ${ruleRows || '<div style="padding:1rem;text-align:center;color:var(--t3);font-size:13px">No rules found.</div>'}
    </div>`;

  // ── Scheduler sidebar ─────────────────────────────────────────────────────────
  const sidePanel = `
    <div style="display:flex;flex-direction:column;gap:1rem">
      <div class="card" style="padding:1rem">
        <div style="font-weight:700;font-size:13px;margin-bottom:.5rem"><i class="ti ti-clock" style="color:var(--blue);margin-right:5px"></i>Scheduler</div>
        <div style="font-size:12px;color:var(--t2);line-height:2">
          <div>Interval: <strong>15 min</strong></div>
          <div>Last automation: <strong>${fmtAgo(sch.last_automation)}</strong></div>
          <div>Last security: <strong>${fmtAgo(sch.last_security)}</strong></div>
          <div>Failed jobs: <strong style="color:${sm.failed_jobs > 0 ? 'var(--red)' : 'inherit'}">${sm.failed_jobs}</strong></div>
          <div>Pending jobs: <strong>${sm.pending_jobs}</strong></div>
        </div>
      </div>
    </div>`;

  // ── Active escalations ─────────────────────────────────────────────────────────
  const entityIcon = { maintenance:'ti-engine', delivery:'ti-truck-delivery', workflow:'ti-cpu',
    security:'ti-shield-exclamation', approval_edit:'ti-edit', approval_del:'ti-trash' };
  const isAdmin = ['admin','ceo','director','manager','operations'].includes(STORAGE.user?.role);
  const escRows = active.length === 0
    ? `<div style="padding:1.5rem;text-align:center;color:var(--t3);font-size:13px">
         <i class="ti ti-circle-check" style="font-size:24px;display:block;margin-bottom:.5rem;opacity:.3"></i>No active escalations.</div>`
    : active.map(e => {
        const icon = entityIcon[e.entity_type] || 'ti-alert-circle';
        const ageH = Number(e.age_hours) || 0;
        return `<div style="display:grid;grid-template-columns:auto 1fr auto auto ${isAdmin ? 'auto' : ''} auto;align-items:center;gap:.5rem 1rem;padding:.5rem .75rem;border-bottom:1px solid var(--bd)">
          <i class="ti ${icon}" style="color:${lvlColor[e.current_level]||'var(--t3)'}"></i>
          <div>
            <div style="font-weight:600;font-size:13px">${e.entity_ref || e.entity_id}</div>
            <div style="font-size:11px;color:var(--t3)">${(e.entity_type||'').replace('_',' ')} · rule: ${e.triggered_by}</div>
          </div>
          ${lvlBadge(e.current_level)}
          <span style="font-size:12px;color:var(--t3)">${ageH < 1 ? '<1h' : Math.round(ageH) + 'h'}</span>
          ${isAdmin ? `<button class="bs1" style="font-size:11px;padding:3px 10px" onclick="_acResolveEsc(${e.id})"><i class="ti ti-check" style="font-size:11px"></i> Resolve</button>` : ''}
          <button class="bs1" style="font-size:11px;padding:3px 10px" onclick="_acAckEsc(${e.id})"><i class="ti ti-eye" style="font-size:11px"></i> Ack</button>
        </div>`;
      }).join('');

  const escalPanel = `
    <div class="card" style="padding:1rem;margin-bottom:1rem">
      <div style="font-weight:700;font-size:13px;margin-bottom:.5rem">
        <i class="ti ti-arrows-up" style="color:${sm.active_escalations > 0 ? 'var(--red)' : 'var(--t3)'};margin-right:5px"></i>
        Active Escalations (${sm.active_escalations})
      </div>
      ${escRows}
    </div>`;

  // ── History with filters ──────────────────────────────────────────────────────
  const ruleKeys = [...new Set((automation_log || []).map(l => l.rule_key))].sort();
  const filterOpts = ruleKeys.map(k => `<option value="${k}">${k}</option>`).join('');

  const logRowsHtml = (automation_log || []).length === 0
    ? `<div style="padding:1rem;text-align:center;color:var(--t3);font-size:12px">No log entries.</div>`
    : automation_log.map(l => `
        <div class="ac-log-row" data-rule="${l.rule_key}" style="padding:.375rem 0;border-bottom:1px solid var(--bd)">
          <div style="font-size:12px;font-weight:600;color:var(--t2)">${l.rule_key}</div>
          <div style="font-size:11px;color:var(--t3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${l.action_taken}</div>
          <div style="font-size:10px;color:var(--t3);opacity:.7">${fmtAgo(l.fired_at)}</div>
        </div>`).join('');

  const logPanel = `
    <div class="card" style="padding:1rem">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:.75rem;gap:.5rem;flex-wrap:wrap">
        <div style="font-weight:700;font-size:13px"><i class="ti ti-history" style="color:var(--blue);margin-right:5px"></i>History (${(automation_log||[]).length})</div>
        <div style="display:flex;align-items:center;gap:.375rem">
          <select id="ac-log-filter" class="finput" style="font-size:11px;padding:2px 6px;height:auto">
            <option value="">All rules</option>${filterOpts}
          </select>
          <button class="bs1" id="ac-export-btn" style="font-size:11px;padding:3px 8px"><i class="ti ti-download" style="font-size:11px"></i> CSV</button>
        </div>
      </div>
      <div id="ac-log-list" style="max-height:360px;overflow-y:auto">${logRowsHtml}</div>
    </div>`;

  // ── Upcoming jobs ─────────────────────────────────────────────────────────────
  const pendRows = (pending_jobs || []).length === 0
    ? `<div style="padding:1rem;text-align:center;color:var(--t3);font-size:12px">No pending jobs.</div>`
    : pending_jobs.map(j => `
        <div style="padding:.375rem 0;border-bottom:1px solid var(--bd)">
          <div style="font-size:12px;font-weight:600;color:var(--t2)">${j.type}</div>
          <div style="font-size:11px;color:var(--t3)">Run at: ${j.run_at ? new Date(j.run_at).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'}) : '—'} · ${j.attempts}/${j.max_attempts} attempts</div>
        </div>`).join('');

  const pendPanel = `
    <div class="card" style="padding:1rem">
      <div style="font-weight:700;font-size:13px;margin-bottom:.75rem"><i class="ti ti-clock-play" style="color:var(--blue);margin-right:5px"></i>Upcoming Jobs (${sm.pending_jobs})</div>
      <div style="max-height:360px;overflow-y:auto">${pendRows}</div>
    </div>`;

  // ── Failed jobs ───────────────────────────────────────────────────────────────
  const failRows = (failed_jobs || []).length === 0
    ? `<div style="padding:1rem;text-align:center;color:var(--t3);font-size:12px">No failed jobs.</div>`
    : failed_jobs.map(j => `
        <div style="padding:.375rem 0;border-bottom:1px solid var(--bd)">
          <div style="font-size:12px;font-weight:600;color:var(--red)">${j.type}</div>
          <div style="font-size:11px;color:var(--t3)">Attempts: ${j.attempts}/${j.max_attempts} · ${fmtAgo(j.processed_at)}</div>
          ${j.last_error ? `<div style="font-size:10px;color:var(--red);opacity:.8;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${String(j.last_error).slice(0, 80)}</div>` : ''}
        </div>`).join('');

  const failPanel = `
    <div class="card" style="padding:1rem">
      <div style="font-weight:700;font-size:13px;margin-bottom:.75rem"><i class="ti ti-alert-triangle" style="color:${sm.failed_jobs > 0 ? 'var(--red)' : 'var(--t3)'};margin-right:5px"></i>Failed Jobs (${sm.failed_jobs})</div>
      <div style="max-height:360px;overflow-y:auto">${failRows}</div>
    </div>`;

  // ── Assemble ──────────────────────────────────────────────────────────────────
  el.innerHTML = `
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:1rem;flex-wrap:wrap;gap:.5rem">
      <div class="ptitle" style="margin:0"><i class="ti ti-robot" style="margin-right:6px"></i>Automation Center</div>
      <div style="display:flex;align-items:center;gap:.5rem;flex-wrap:wrap">
        <span style="font-size:12px;color:var(--t3)">Updated: ${ts}</span>
        <button class="bs1" id="ac-run-btn"     style="font-size:12px"><i class="ti ti-player-play"></i> Run Now</button>
        <button class="bs1" id="ac-print-btn"   style="font-size:12px"><i class="ti ti-printer"></i> Print</button>
        <button class="bs1" id="ac-refresh-btn" style="font-size:12px"><i class="ti ti-refresh"></i> Refresh</button>
      </div>
    </div>
    ${kpiHtml}
    ${statusPanel}
    <div style="display:grid;grid-template-columns:1fr 220px;gap:1rem;margin-bottom:1rem">
      ${rulesPanel}
      ${sidePanel}
    </div>
    ${escalPanel}
    <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:1rem">
      ${logPanel}
      ${pendPanel}
      ${failPanel}
    </div>`;

  // ── Event handlers ────────────────────────────────────────────────────────────
  $('ac-refresh-btn').onclick = () => renderAutomationCenter();

  $('ac-run-btn').onclick = async () => {
    const btn = $('ac-run-btn');
    btn.disabled = true;
    btn.innerHTML = '<i class="ti ti-loader-2 spin"></i> Running…';
    const r = await UFCL.automationRun(STORAGE.user.id);
    if (r?.ok) {
      setTimeout(() => renderAutomationCenter(), 2000);
    } else {
      btn.disabled = false;
      btn.innerHTML = '<i class="ti ti-player-play"></i> Run Now';
      alert(r?.error || 'Failed to trigger automation run');
    }
  };

  $('ac-print-btn').onclick = () => _acPrintReport($('page-automation')._acData);

  $('ac-export-btn').onclick = () => _acExportHistoryCsv($('page-automation')._acData?.automation_log || []);

  $('ac-log-filter').onchange = function () {
    const val = this.value;
    document.querySelectorAll('#page-automation .ac-log-row').forEach(row => {
      row.style.display = (!val || row.dataset.rule === val) ? '' : 'none';
    });
  };

  $('ac-new-rule-btn').onclick = () => _acNewRule();
}

async function _acToggleRule(ruleKey, enabled) {
  const r = await UFCL.automationToggle(STORAGE.user.id, ruleKey, enabled);
  if (r?.ok) renderAutomationCenter();
  else alert(r?.error || 'Toggle failed');
}

async function _acEditRule(ruleKey) {
  const r = await UFCL.automationRule(STORAGE.user.id, ruleKey);
  if (!r?.ok) return alert(r?.error || 'Failed to load rule');
  const rule = r.rule;
  openOverlay(`Edit Rule — ${rule.label}`, null, `
    <div style="display:grid;gap:.75rem">
      <label style="font-size:12px;color:var(--t3)">Severity
        <select id="ov-sev" class="finput" style="display:block;width:100%;margin-top:3px">
          ${['critical','high','medium','low','info'].map(s =>
            `<option value="${s}"${s === rule.severity ? ' selected' : ''}>${s.charAt(0).toUpperCase() + s.slice(1)}</option>`
          ).join('')}
        </select>
      </label>
      <label style="font-size:12px;color:var(--t3)">Auto Action
        <select id="ov-action" class="finput" style="display:block;width:100%;margin-top:3px">
          ${['notify','draft_request','escalate','log_only'].map(a =>
            `<option value="${a}"${a === rule.auto_action ? ' selected' : ''}>${a.replace('_', ' ')}</option>`
          ).join('')}
        </select>
      </label>
      <label style="font-size:12px;color:var(--t3)">Cooldown (hours)
        <input id="ov-cd" type="number" min="0" class="finput" style="display:block;width:100%;margin-top:3px" value="${rule.cooldown_hours}">
      </label>
      <label style="font-size:12px;color:var(--t3)">Notify Roles (comma-separated)
        <input id="ov-roles" type="text" class="finput" style="display:block;width:100%;margin-top:3px" value="${(rule.notify_roles || []).join(', ')}">
      </label>
      <label style="font-size:12px;color:var(--t3)">Threshold (JSON)
        <textarea id="ov-thr" class="finput" rows="5" style="display:block;width:100%;margin-top:3px;font-family:monospace;font-size:11px">${JSON.stringify(rule.threshold || {}, null, 2)}</textarea>
      </label>
    </div>
    <div class="brow" style="margin-top:1rem">
      <button class="bp1" id="ovSave"><i class="ti ti-device-floppy"></i> Save</button>
      <button class="bs1" id="ovCancel">Cancel</button>
    </div>`,
    async () => {
      const sev    = $('ov-sev').value;
      const action = $('ov-action').value;
      const cd     = Number($('ov-cd').value);
      const roles  = $('ov-roles').value.split(',').map(s => s.trim()).filter(Boolean);
      let thr;
      try { thr = JSON.parse($('ov-thr').value); }
      catch {
        const e = $('ovErr');
        e.textContent = 'Invalid JSON in threshold field.';
        e.style.display = 'block';
        return;
      }
      const res = await UFCL.automationUpdate(STORAGE.user.id, ruleKey, {
        severity: sev, auto_action: action, cooldown_hours: cd,
        notify_roles: roles, threshold: thr,
      });
      if (res?.ok) { closeOverlay(); renderAutomationCenter(); }
      else {
        const e = $('ovErr');
        e.textContent = res?.error || 'Save failed';
        e.style.display = 'block';
      }
    }
  );
}

// Master Professionalization Phase C3 (PR-22/23) — the create/delete counterpart
// to _acEditRule above, same overlay shape plus the 3 identity fields
// (rule_key/label/description) an update can't touch but a create must supply.
function _acNewRule() {
  openOverlay('New Automation Rule', null, `
    <div style="display:grid;gap:.75rem">
      <label style="font-size:12px;color:var(--t3)">Rule Key (lowercase, letters/digits/underscore, 2-64 chars)
        <input id="ov-key" type="text" class="finput" style="display:block;width:100%;margin-top:3px" placeholder="e.g. custom_low_fuel_alert">
      </label>
      <label style="font-size:12px;color:var(--t3)">Label
        <input id="ov-label" type="text" class="finput" style="display:block;width:100%;margin-top:3px" placeholder="e.g. Custom Low Fuel Alert">
      </label>
      <label style="font-size:12px;color:var(--t3)">Description (optional)
        <input id="ov-desc" type="text" class="finput" style="display:block;width:100%;margin-top:3px">
      </label>
      <label style="font-size:12px;color:var(--t3)">Severity
        <select id="ov-sev" class="finput" style="display:block;width:100%;margin-top:3px">
          ${['critical','high','medium','low','info'].map(s =>
            `<option value="${s}"${s === 'medium' ? ' selected' : ''}>${s.charAt(0).toUpperCase() + s.slice(1)}</option>`
          ).join('')}
        </select>
      </label>
      <label style="font-size:12px;color:var(--t3)">Auto Action
        <select id="ov-action" class="finput" style="display:block;width:100%;margin-top:3px">
          ${['notify','draft_request','escalate','log_only'].map(a =>
            `<option value="${a}"${a === 'notify' ? ' selected' : ''}>${a.replace('_', ' ')}</option>`
          ).join('')}
        </select>
      </label>
      <label style="font-size:12px;color:var(--t3)">Cooldown (hours)
        <input id="ov-cd" type="number" min="0" class="finput" style="display:block;width:100%;margin-top:3px" value="4">
      </label>
      <label style="font-size:12px;color:var(--t3)">Notify Roles (comma-separated)
        <input id="ov-roles" type="text" class="finput" style="display:block;width:100%;margin-top:3px" placeholder="admin, ceo, operations">
      </label>
      <label style="font-size:12px;color:var(--t3)">Threshold (JSON)
        <textarea id="ov-thr" class="finput" rows="5" style="display:block;width:100%;margin-top:3px;font-family:monospace;font-size:11px">{}</textarea>
      </label>
    </div>
    <div class="brow" style="margin-top:1rem">
      <button class="bp1" id="ovSave"><i class="ti ti-device-floppy"></i> Create Rule</button>
      <button class="bs1" id="ovCancel">Cancel</button>
    </div>`,
    async () => {
      const ruleKey = $('ov-key').value.trim();
      const label   = $('ov-label').value.trim();
      if (!ruleKey || !label) {
        const e = $('ovErr');
        e.textContent = 'Rule key and label are both required.';
        e.style.display = 'block';
        return;
      }
      const cd    = Number($('ov-cd').value);
      const roles = $('ov-roles').value.split(',').map(s => s.trim()).filter(Boolean);
      let thr;
      try { thr = JSON.parse($('ov-thr').value || '{}'); }
      catch {
        const e = $('ovErr');
        e.textContent = 'Invalid JSON in threshold field.';
        e.style.display = 'block';
        return;
      }
      const res = await UFCL.automationCreate(STORAGE.user.id, {
        rule_key: ruleKey, label, description: $('ov-desc').value.trim() || null,
        severity: $('ov-sev').value, auto_action: $('ov-action').value,
        cooldown_hours: cd, notify_roles: roles, threshold: thr,
      });
      if (res?.ok) { closeOverlay(); renderAutomationCenter(); }
      else {
        const e = $('ovErr');
        e.textContent = res?.error || 'Create failed';
        e.style.display = 'block';
      }
    }
  );
}

async function _acDeleteRule(ruleKey, label) {
  if (!confirm(`Delete automation rule "${label}"? This cannot be undone. Built-in rules cannot be deleted — disable them instead.`)) return;
  const r = await UFCL.automationDelete(STORAGE.user.id, ruleKey);
  if (r?.ok) renderAutomationCenter();
  else alert(r?.error || 'Delete failed');
}

async function _acResolveEsc(escalationId) {
  const reason = prompt('Resolution reason:');
  if (!reason) return;
  const r = await UFCL.escalationResolve(STORAGE.user.id, escalationId, reason);
  if (r?.ok) renderAutomationCenter();
  else alert(r?.error || 'Resolve failed');
}

async function _acAckEsc(escalationId) {
  const r = await UFCL.escalationAck(STORAGE.user.id, escalationId);
  if (r?.ok) renderAutomationCenter();
  else alert(r?.error || 'Acknowledge failed');
}

// ╔══════════════════════════════════════════════════════════════════════════════╗
// ║  PHASE 9 — ENTERPRISE PERFORMANCE MANAGEMENT                                ║
// ╚══════════════════════════════════════════════════════════════════════════════╝

function _epmRagBadge(status) {
  const m = { 'on-track': ['epm-badge-green','On Track'], 'at-risk': ['epm-badge-amber','At Risk'],
               'off-track': ['epm-badge-red','Off Track'], 'green': ['epm-badge-green','Green'],
               'amber': ['epm-badge-amber','Amber'], 'red': ['epm-badge-red','Red'],
               'no-data': ['epm-badge-grey','No Data'] };
  const [cls, lbl] = m[status] || ['epm-badge-grey', status];
  return `<span class="epm-badge ${cls}">${lbl}</span>`;
}

function _epmScoreDial(score, size = 72) {
  const r = size / 2 - 6;
  const c = 2 * Math.PI * r;
  const pct = Math.min(100, Math.max(0, score));
  const filled = (pct / 100) * c;
  const color = pct >= 80 ? '#22c55e' : pct >= 60 ? '#f59e0b' : '#ef4444';
  return `<svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}">
    <circle cx="${size/2}" cy="${size/2}" r="${r}" fill="none" stroke="var(--bdr)" stroke-width="6"/>
    <circle cx="${size/2}" cy="${size/2}" r="${r}" fill="none" stroke="${color}" stroke-width="6"
      stroke-dasharray="${filled} ${c}" stroke-dashoffset="${c/4}"
      stroke-linecap="round" transform="rotate(-90 ${size/2} ${size/2})"/>
    <text x="${size/2}" y="${size/2+5}" text-anchor="middle" font-size="14" font-weight="600"
      fill="${color}" font-family="DM Sans">${pct}</text>
  </svg>`;
}

function _epmTrendIcon(trend) {
  return trend === 'improving' ? '<i class="ti ti-trending-up" style="color:#22c55e"></i>'
    : trend === 'declining'   ? '<i class="ti ti-trending-down" style="color:#ef4444"></i>'
    : '<i class="ti ti-minus" style="color:#94a3b8"></i>';
}

function _epmAchBar(pct) {
  const w = Math.min(100, Math.max(0, pct || 0));
  const c = w >= 90 ? '#22c55e' : w >= 70 ? '#f59e0b' : '#ef4444';
  return `<div style="display:flex;align-items:center;gap:6px">
    <div style="flex:1;height:6px;background:var(--bdr);border-radius:3px;overflow:hidden">
      <div style="width:${w}%;height:100%;background:${c};border-radius:3px;transition:width .4s"></div>
    </div>
    <span style="font-size:11px;font-weight:600;color:${c};width:30px;text-align:right">${w}%</span>
  </div>`;
}

let _epmKpiFilter  = '';
let _epmDeptFilter = '';
let _epmStatFilter = '';

async function renderEPM() {
  _epmLastLoad = Date.now();
  const el = $('page-epm');
  if (!el) return;
  el.innerHTML = `<div class="pload"><i class="ti ti-loader-2 spin"></i> Loading Enterprise Performance data…</div>`;

  const [dashRes, execRes, deptRes, planRes, trendRes] = await Promise.all([
    UFCL.performanceDashboard(STORAGE.user.id),
    UFCL.executiveScorecard(STORAGE.user.id),
    UFCL.departmentScorecards(STORAGE.user.id),
    UFCL.performanceActionPlans(STORAGE.user.id),
    UFCL.performanceTrends(STORAGE.user.id),
  ]);

  if (!dashRes?.ok) {
    el.innerHTML = `<div class="pload" style="color:#ef4444"><i class="ti ti-lock"></i> ${dashRes?.error || 'Access denied'}</div>`;
    return;
  }

  const sm     = dashRes.summary;
  const kpis   = dashRes.kpis || [];
  const exec   = execRes?.ok ? execRes : null;
  const depts  = deptRes?.ok ? deptRes.scorecards || [] : [];
  const plans  = planRes?.ok ? planRes.plans || [] : [];
  const planSm = planRes?.ok ? planRes.summary : {};
  const trends = trendRes?.ok ? trendRes.trends : {};

  const now   = new Date().toLocaleString('en-GB', { dateStyle:'medium', timeStyle:'short' });
  const month = sm.period || new Date().toISOString().slice(0, 7);

  // ── Company Score Gauge ────────────────────────────────────────────────────
  const cScore    = sm.company_score || 0;
  const cColor    = cScore >= 80 ? '#22c55e' : cScore >= 60 ? '#f59e0b' : '#ef4444';
  const cStatus   = cScore >= 80 ? 'Strong' : cScore >= 60 ? 'Moderate' : 'Critical';
  const cRag      = cScore >= 80 ? 'green' : cScore >= 60 ? 'amber' : 'red';

  // ── Executive Scorecard rows ────────────────────────────────────────────────
  const execRows = exec ? exec.dimensions.map(d => `
    <tr>
      <td><i class="ti ${d.icon}" style="color:${d.status==='green'?'#22c55e':d.status==='amber'?'#f59e0b':'#ef4444'}"></i> ${d.name}</td>
      <td>${_epmScoreDial(d.score, 48)}</td>
      <td>${_epmRagBadge(d.status)}</td>
      <td style="color:var(--t3);font-size:12px">${d.detail}</td>
    </tr>`).join('') : '';

  // ── Department Scorecard cards ─────────────────────────────────────────────
  const deptCards = depts.map(d => {
    const rag = d.risk_level === 'high' ? '#ef4444' : d.risk_level === 'medium' ? '#f59e0b' : '#22c55e';
    return `<div class="epm-dept-card" style="border-top:3px solid ${d.color||'#2e8b57'}">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px">
        <div style="display:flex;align-items:center;gap:8px">
          <i class="ti ${d.icon||'ti-chart-bar'}" style="font-size:18px;color:${d.color||'#2e8b57'}"></i>
          <strong style="font-size:14px">${d.department}</strong>
        </div>
        ${_epmScoreDial(d.score, 52)}
      </div>
      <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:8px">
        <span class="epm-badge epm-badge-green" title="On Track">${d.on_track} <i class="ti ti-check"></i></span>
        <span class="epm-badge epm-badge-amber" title="At Risk">${d.at_risk} <i class="ti ti-alert-triangle"></i></span>
        <span class="epm-badge epm-badge-red"   title="Off Track">${d.off_track} <i class="ti ti-x"></i></span>
      </div>
      <div style="font-size:11px;color:var(--t3);display:flex;gap:10px">
        <span>Risk: <strong style="color:${rag}">${d.risk_level}</strong></span>
        <span>Actions: <strong>${d.open_actions}</strong> open</span>
        ${_epmTrendIcon(d.trend)}
      </div>
    </div>`;
  }).join('');

  // ── KPI Table ──────────────────────────────────────────────────────────────
  const depts_unique = [...new Set(kpis.map(k => k.department))].sort();
  const filteredKPIs = kpis.filter(k => {
    const q = _epmKpiFilter.toLowerCase();
    if (q && !k.name.toLowerCase().includes(q) && !k.department.toLowerCase().includes(q)) return false;
    if (_epmDeptFilter && k.department !== _epmDeptFilter) return false;
    if (_epmStatFilter && k.status !== _epmStatFilter) return false;
    return true;
  });

  const kpiRows = filteredKPIs.map(k => `
    <tr>
      <td><strong>${k.name}</strong><div style="font-size:11px;color:var(--t3)">${k.description||''}</div></td>
      <td>${k.department}</td>
      <td style="font-size:12px;color:var(--t3)">${k.owner||'—'}</td>
      <td style="text-align:right"><strong>${k.current !== null ? Number(k.current).toLocaleString() : '—'}</strong> <span style="color:var(--t3);font-size:11px">${k.unit}</span></td>
      <td style="text-align:right;color:var(--t3)">${Number(k.target).toLocaleString()} ${k.unit}</td>
      <td style="min-width:120px">${_epmAchBar(k.achievement)}</td>
      <td>${_epmRagBadge(k.status)}</td>
      <td>${_epmTrendIcon(k.trend)}</td>
      <td style="font-size:11px;color:var(--t3)">${k.review_freq}</td>
    </tr>`).join('');

  // ── Action Plans ───────────────────────────────────────────────────────────
  const prioColor = { critical:'#ef4444', high:'#f97316', medium:'#f59e0b', low:'#22c55e' };
  const planRows = plans.slice(0, 20).map(p => `
    <tr>
      <td><strong>${p.problem}</strong><div style="font-size:11px;color:var(--t3)">${p.kpi_name||'General'}</div></td>
      <td>${p.responsible_dept}</td>
      <td><span class="epm-badge" style="background:${prioColor[p.priority]||'#6b7280'}20;color:${prioColor[p.priority]||'#6b7280'};border:1px solid ${prioColor[p.priority]||'#6b7280'}40">${p.priority}</span></td>
      <td>${p.due_date ? new Date(p.due_date).toLocaleDateString('en-GB') : '—'}</td>
      <td>${_epmRagBadge(p.status === 'draft' ? 'no-data' : p.status === 'approved' || p.status === 'in_progress' ? 'amber' : p.status === 'completed' ? 'green' : 'no-data')}<span style="font-size:11px;margin-left:4px">${p.status.replace(/_/g,' ')}</span></td>
      <td style="font-size:11px;color:var(--t3)">${p.auto_generated ? '<i class="ti ti-robot" title="Auto-generated"></i>' : '<i class="ti ti-user"></i>'}</td>
    </tr>`).join('');

  // ── Trend Sparklines ───────────────────────────────────────────────────────
  function miniChart(rows, label, color) {
    if (!rows || !rows.length) return `<div class="epm-mini-chart"><div style="color:var(--t3);font-size:12px">No data</div><div class="epm-chart-lbl">${label}</div></div>`;
    const vals = rows.map(r => Number(r.value) || 0);
    const mx   = Math.max(...vals, 1);
    const mn   = Math.min(...vals, 0);
    const rng  = mx - mn || 1;
    const W = 160, H = 48, p = 4;
    const pts = vals.map((v, i) => {
      const x = p + (i / Math.max(vals.length - 1, 1)) * (W - 2*p);
      const y = H - p - ((v - mn) / rng) * (H - 2*p);
      return `${x},${y}`;
    }).join(' ');
    const lastVal = vals[vals.length - 1];
    return `<div class="epm-mini-chart">
      <svg width="${W}" height="${H}" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none">
        <polyline points="${pts}" fill="none" stroke="${color}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
        <circle cx="${pts.split(' ').pop().split(',')[0]}" cy="${pts.split(' ').pop().split(',')[1]}" r="3" fill="${color}"/>
      </svg>
      <div style="display:flex;justify-content:space-between;margin-top:2px">
        <div class="epm-chart-lbl">${label}</div>
        <div style="font-size:11px;font-weight:600;color:${color}">${lastVal.toLocaleString()}</div>
      </div>
    </div>`;
  }

  const trendBlock = `
    <div class="epm-trend-grid">
      ${miniChart(trends.revenue,    'Revenue (weekly)',     '#2e8b57')}
      ${miniChart(trends.production, 'Production (weekly)',  '#7C3AED')}
      ${miniChart(trends.harvest,    'Harvest (weekly)',     '#15803D')}
      ${miniChart(trends.fuel,       'Fuel consumed (daily)','#f59e0b')}
      ${miniChart(trends.stock,      'Stock issues (daily)', '#2563EB')}
      ${miniChart(trends.approvals,  'Approvals (weekly)',   '#EA580C')}
    </div>`;

  el.innerHTML = `
  <style>
    .epm-hdr { display:flex; justify-content:space-between; align-items:center; margin-bottom:1.5rem; flex-wrap:wrap; gap:10px }
    .epm-score-hero { display:flex; align-items:center; gap:1.5rem; background:var(--surf); border:1px solid var(--bdr); border-radius:14px; padding:1.25rem 1.5rem; margin-bottom:1.25rem }
    .epm-score-big { font-size:64px; font-weight:700; line-height:1; color:${cColor} }
    .epm-score-info { flex:1 }
    .epm-score-info h2 { font-size:1.1rem; margin:0 0 4px }
    .epm-kpi-row { display:flex; gap:.75rem; flex-wrap:wrap; margin-bottom:1.25rem }
    .epm-kpi-tile { flex:1; min-width:120px; background:var(--surf); border:1px solid var(--bdr); border-radius:10px; padding:.9rem 1rem; text-align:center }
    .epm-kpi-tile .kn { font-size:1.8rem; font-weight:700 }
    .epm-kpi-tile .kl { font-size:11px; color:var(--t3); margin-top:2px }
    .epm-section { background:var(--surf); border:1px solid var(--bdr); border-radius:12px; padding:1.25rem; margin-bottom:1.25rem }
    .epm-section h3 { font-size:.95rem; font-weight:600; margin:0 0 1rem; display:flex; align-items:center; gap:.5rem }
    .epm-dept-grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(220px,1fr)); gap:12px }
    .epm-dept-card { background:var(--bg); border:1px solid var(--bdr); border-radius:10px; padding:1rem }
    .epm-badge { display:inline-flex; align-items:center; gap:3px; font-size:11px; font-weight:600; padding:2px 8px; border-radius:20px }
    .epm-badge-green { background:#22c55e20; color:#16a34a; border:1px solid #22c55e40 }
    .epm-badge-amber { background:#f59e0b20; color:#b45309; border:1px solid #f59e0b40 }
    .epm-badge-red   { background:#ef444420; color:#dc2626; border:1px solid #ef444440 }
    .epm-badge-grey  { background:var(--bdr); color:var(--t3); border:1px solid var(--bdr) }
    .epm-filters { display:flex; gap:8px; flex-wrap:wrap; margin-bottom:.75rem }
    .epm-filters input, .epm-filters select { padding:6px 10px; border:1px solid var(--bdr); border-radius:8px; background:var(--bg); color:var(--t1); font-size:13px }
    .epm-trend-grid { display:grid; grid-template-columns:repeat(auto-fill,minmax(160px,1fr)); gap:12px }
    .epm-mini-chart { background:var(--bg); border:1px solid var(--bdr); border-radius:8px; padding:10px }
    .epm-chart-lbl { font-size:11px; color:var(--t3) }
    .epm-plans-summary { display:flex; gap:.5rem; flex-wrap:wrap; margin-bottom:1rem }
  </style>

  <div class="epm-hdr">
    <div>
      <div class="ptitle"><i class="ti ti-chart-radar"></i> Enterprise Performance Management</div>
      <div class="psub">Period: ${month} · Refreshed: ${now}</div>
    </div>
    <div style="display:flex;gap:8px">
      <button class="sbtn2" id="epm-refresh-btn"><i class="ti ti-refresh"></i> Refresh</button>
      <button class="sbtn2" id="epm-export-btn"><i class="ti ti-file-download"></i> Export CSV</button>
    </div>
  </div>

  <!-- Company Score Hero -->
  <div class="epm-score-hero">
    <div>${_epmScoreDial(cScore, 96)}</div>
    <div class="epm-score-info">
      <h2>Company Performance Score</h2>
      <div style="display:flex;align-items:center;gap:10px;margin-bottom:6px">
        <div class="epm-score-big">${cScore}</div>
        <div>
          ${_epmRagBadge(cRag)}
          <div style="font-size:13px;color:var(--t3);margin-top:4px">${cStatus} performance across all departments</div>
        </div>
      </div>
      <div style="font-size:12px;color:var(--t3)">
        ${sm.on_track} on-track &nbsp;·&nbsp; ${sm.at_risk} at-risk &nbsp;·&nbsp; ${sm.off_track} off-track
        &nbsp;·&nbsp; ${sm.total_kpis} KPIs across ${sm.departments} departments
        &nbsp;·&nbsp; ${sm.open_plans} open improvement plans
      </div>
    </div>
  </div>

  <!-- Executive Scorecard -->
  ${exec ? `
  <div class="epm-section">
    <h3><i class="ti ti-shield-star"></i> Executive Scorecard
      <span style="margin-left:auto">${_epmRagBadge(exec.overall.status)} <strong style="margin-left:6px">${exec.overall.score}</strong> overall</span>
    </h3>
    <table class="dtable" style="font-size:13px">
      <thead><tr><th>Dimension</th><th>Score</th><th>Status</th><th>Detail</th></tr></thead>
      <tbody>${execRows}</tbody>
    </table>
  </div>` : ''}

  <!-- Department Scorecards -->
  <div class="epm-section">
    <h3><i class="ti ti-building-community"></i> Department Scorecards</h3>
    <div class="epm-dept-grid">${deptCards || '<div style="color:var(--t3)">No department data</div>'}</div>
  </div>

  <!-- KPI Dashboard -->
  <div class="epm-section">
    <h3><i class="ti ti-target-arrow"></i> KPI Dashboard <span style="font-size:12px;font-weight:400;margin-left:6px;color:var(--t3)">${filteredKPIs.length} of ${kpis.length} KPIs shown</span></h3>
    <div class="epm-filters">
      <input id="epm-search" type="text" placeholder="Search KPIs…" value="${_epmKpiFilter}" style="min-width:180px">
      <select id="epm-dept-filter">
        <option value="">All Departments</option>
        ${depts_unique.map(d => `<option value="${d}" ${_epmDeptFilter===d?'selected':''}>${d}</option>`).join('')}
      </select>
      <select id="epm-stat-filter">
        <option value="">All Statuses</option>
        <option value="on-track"  ${_epmStatFilter==='on-track'?'selected':''}>On Track</option>
        <option value="at-risk"   ${_epmStatFilter==='at-risk'?'selected':''}>At Risk</option>
        <option value="off-track" ${_epmStatFilter==='off-track'?'selected':''}>Off Track</option>
      </select>
    </div>
    <div class="tscroll">
      <table class="dtable" style="font-size:13px">
        <thead><tr>
          <th>KPI Name</th><th>Department</th><th>Owner</th>
          <th style="text-align:right">Current</th><th style="text-align:right">Target</th>
          <th style="min-width:130px">Achievement</th><th>Status</th><th>Trend</th><th>Frequency</th>
        </tr></thead>
        <tbody id="epm-kpi-tbody">${kpiRows || '<tr><td colspan="9" style="text-align:center;color:var(--t3);padding:2rem">No KPIs match your filters</td></tr>'}</tbody>
      </table>
    </div>
  </div>

  <!-- Performance Trends -->
  <div class="epm-section">
    <h3><i class="ti ti-chart-line"></i> Performance Trends <span style="font-size:12px;font-weight:400;margin-left:6px;color:var(--t3)">Last 12 weeks</span></h3>
    ${trendBlock}
  </div>

  <!-- Action Plans -->
  <div class="epm-section">
    <h3><i class="ti ti-list-check"></i> Improvement Action Plans</h3>
    <div class="epm-plans-summary">
      <span class="epm-badge epm-badge-grey">${planSm.draft||0} Draft</span>
      <span class="epm-badge epm-badge-amber">${planSm.pending_approval||0} Pending Approval</span>
      <span class="epm-badge epm-badge-green">${planSm.approved||0} Approved</span>
      <span class="epm-badge epm-badge-amber">${planSm.in_progress||0} In Progress</span>
      <span class="epm-badge epm-badge-green">${planSm.completed||0} Completed</span>
    </div>
    ${plans.length ? `<div class="tscroll"><table class="dtable" style="font-size:13px">
      <thead><tr><th>Problem / KPI</th><th>Department</th><th>Priority</th><th>Due Date</th><th>Status</th><th>Source</th></tr></thead>
      <tbody>${planRows}</tbody>
    </table></div>` : `<div style="color:var(--t3);padding:1rem;text-align:center"><i class="ti ti-check"></i> No improvement plans — all KPIs within acceptable range</div>`}
  </div>`;

  // Wire up controls
  $('epm-refresh-btn').onclick = () => renderEPM();
  $('epm-export-btn').onclick  = async () => {
    const hdr  = 'KPI Key,Name,Department,Owner,Target,Current,Unit,Achievement %,Status,Trend,Review Freq';
    const rows = kpis.map(k =>
      [k.kpi_key, `"${k.name}"`, k.department, `"${k.owner||''}"`,
       k.target, k.current, k.unit, k.achievement, k.status, k.trend, k.review_freq].join(',')
    );
    const csv      = [hdr, ...rows].join('\n');
    const filename = `ufcl_epm_${month}.csv`;
    const res = await UFCL.performanceExport(STORAGE.user.id, csv, filename);
    if (res?.ok) showToast(`Saved: ${res.filePath}`, 'success');
    else alert(res?.error || 'Export failed');
  };
  const searchEl = $('epm-search');
  const deptEl   = $('epm-dept-filter');
  const statEl   = $('epm-stat-filter');

  searchEl.oninput = () => { _epmKpiFilter  = searchEl.value; _epmRefilter(kpis); };
  deptEl.onchange  = () => { _epmDeptFilter = deptEl.value;   _epmRefilter(kpis); };
  statEl.onchange  = () => { _epmStatFilter = statEl.value;   _epmRefilter(kpis); };
}

function _epmRefilter(kpis) {
  const filtered = kpis.filter(k => {
    const q = _epmKpiFilter.toLowerCase();
    if (q && !k.name.toLowerCase().includes(q) && !k.department.toLowerCase().includes(q)) return false;
    if (_epmDeptFilter && k.department !== _epmDeptFilter) return false;
    if (_epmStatFilter && k.status !== _epmStatFilter) return false;
    return true;
  });
  const prioColor = { critical:'#ef4444', high:'#f97316', medium:'#f59e0b', low:'#22c55e' };
  const tbody = $('epm-kpi-tbody');
  if (!tbody) return;
  tbody.innerHTML = filtered.length
    ? filtered.map(k => `
      <tr>
        <td><strong>${k.name}</strong><div style="font-size:11px;color:var(--t3)">${k.description||''}</div></td>
        <td>${k.department}</td>
        <td style="font-size:12px;color:var(--t3)">${k.owner||'—'}</td>
        <td style="text-align:right"><strong>${k.current !== null ? Number(k.current).toLocaleString() : '—'}</strong> <span style="color:var(--t3);font-size:11px">${k.unit}</span></td>
        <td style="text-align:right;color:var(--t3)">${Number(k.target).toLocaleString()} ${k.unit}</td>
        <td style="min-width:120px">${_epmAchBar(k.achievement)}</td>
        <td>${_epmRagBadge(k.status)}</td>
        <td>${_epmTrendIcon(k.trend)}</td>
        <td style="font-size:11px;color:var(--t3)">${k.review_freq}</td>
      </tr>`).join('')
    : '<tr><td colspan="9" style="text-align:center;color:var(--t3);padding:2rem">No KPIs match your filters</td></tr>';
}


// ══════════════════════════════════════════════════════════════════════════
// ── Procurement Management ───────────────────────────────────────────────────
// ══════════════════════════════════════════════════════════════════════════

const PROC_STAGE_LABEL = {
  supervisor: 'Supervisor', department_manager: 'Department Manager',
  procurement_review: 'Procurement Review', finance: 'Finance', ceo: 'CEO',
};

// Standardized status→(color, icon, label) lookup covering the full status
// vocabulary actually used across requisitions/POs/RFQs/quotations/receipts/
// invoices/payments/approval-steps. Reuses the existing 6 badge colors plus
// one neutral gray (.bn — see styles.css) rather than introducing new hues.
const PROC_STATUS_META = {
  draft:              { cls: 'bn', icon: 'ti-file-text',      label: 'Draft' },
  submitted:          { cls: 'bb', icon: 'ti-send',           label: 'Submitted' },
  in_approval:        { cls: 'ba', icon: 'ti-clock',          label: 'Pending Approval' },
  pending:            { cls: 'ba', icon: 'ti-clock',          label: 'Pending' },
  approved:           { cls: 'bg', icon: 'ti-circle-check',   label: 'Approved' },
  rejected:           { cls: 'br', icon: 'ti-circle-x',       label: 'Rejected' },
  returned_for_revision: { cls: 'ba', icon: 'ti-arrow-back-up', label: 'Returned for Revision' },
  cancelled:          { cls: 'bn', icon: 'ti-ban',            label: 'Cancelled' },
  po_issued:          { cls: 'bp', icon: 'ti-file-invoice',   label: 'PO Issued' },
  completed:          { cls: 'bt', icon: 'ti-checks',         label: 'Completed' },
  issued:             { cls: 'bp', icon: 'ti-file-invoice',   label: 'Issued' },
  acknowledged:       { cls: 'bb', icon: 'ti-check',          label: 'Acknowledged' },
  partially_received: { cls: 'ba', icon: 'ti-package-import', label: 'Partially Received' },
  shortage_pending_approval: { cls: 'ba', icon: 'ti-clock',   label: 'Shortage Closure Pending' },
  closed_with_shortage: { cls: 'br', icon: 'ti-alert-triangle', label: 'Closed with Shortage' },
  received:           { cls: 'bt', icon: 'ti-package',        label: 'Received' },
  closed:             { cls: 'bn', icon: 'ti-lock',           label: 'Closed' },
  pending_match:      { cls: 'ba', icon: 'ti-scale',          label: 'Pending Match' },
  matched:            { cls: 'bb', icon: 'ti-check',          label: 'Matched' },
  disputed:           { cls: 'br', icon: 'ti-alert-triangle', label: 'Disputed' },
  paid:               { cls: 'bg', icon: 'ti-cash',           label: 'Paid' },
  sent:               { cls: 'bb', icon: 'ti-send',           label: 'Sent' },
  invited:            { cls: 'bb', icon: 'ti-mail',           label: 'Invited' },
  responded:          { cls: 'bg', icon: 'ti-message-check',  label: 'Responded' },
  declined:           { cls: 'br', icon: 'ti-x',              label: 'Declined' },
  selected:           { cls: 'bg', icon: 'ti-star',           label: 'Selected' },
  partial:            { cls: 'ba', icon: 'ti-package-import', label: 'Partial' },
  complete:           { cls: 'bt', icon: 'ti-package',        label: 'Complete' },
  skipped:            { cls: 'bn', icon: 'ti-arrow-bar-right',label: 'Skipped' },
  // Phase 3B — supplier lifecycle statuses. 'pending_approval' is a distinct
  // key from 'in_approval' (a requisition-chain concept) even though the
  // label/styling happen to match.
  pending_approval:   { cls: 'ba', icon: 'ti-clock',          label: 'Pending Approval' },
  active:             { cls: 'bg', icon: 'ti-circle-check',   label: 'Active' },
  suspended:          { cls: 'ba', icon: 'ti-player-pause',   label: 'Suspended' },
  blacklisted:        { cls: 'br', icon: 'ti-ban',            label: 'Blacklisted' },
  archived:           { cls: 'bn', icon: 'ti-archive',        label: 'Archived' },
};

function procStatusBadge(s) {
  if (!s) return '<span class="badge bn">—</span>';
  // Unknown status value falls back to a plain label rather than guessing a color.
  const label = String(s).replace(/_/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
  return badgeHtml(PROC_STATUS_META, String(s).toLowerCase(), { cls: 'bn', label });
}

// ── Shared UI helpers (toast, skeleton, filter/sort) — used identically
// across every procurement list page to avoid duplicating this logic 8x. ──

function showToast(message, type = 'success') {
  let host = document.getElementById('toast-host');
  if (!host) {
    host = document.createElement('div');
    host.id = 'toast-host';
    host.className = 'toast-host';
    document.body.appendChild(host);
  }
  const el = document.createElement('div');
  el.className = `toast toast-${type}`;
  // Enterprise UI/UX Standardization Phase 3 — warning/info added alongside
  // the existing success/error/pending, matching alertHtml()'s 4-severity
  // language so toasts and banners read consistently across the app.
  const icon = { success: 'ti-circle-check', pending: 'ti-clock', warning: 'ti-alert-triangle', info: 'ti-info-circle' }[type] || 'ti-alert-circle';
  el.innerHTML = `<i class="ti ${icon}"></i><span>${message}</span>`;
  host.appendChild(el);
  setTimeout(() => { el.style.opacity = '0'; el.style.transition = 'opacity .25s'; setTimeout(() => el.remove(), 250); }, 2600);
}

function skeletonTableRows(cols, rows = 5) {
  const widths = ['w-80', 'w-60', 'w-40', 'w-25'];
  return Array.from({ length: rows }).map(() =>
    `<tr>${Array.from({ length: cols }).map((_, i) => `<td><div class="skel-row ${widths[i % widths.length]}"></div></td>`).join('')}</tr>`
  ).join('');
}

// Generic client-side search + status filter, shared so every list page
// filters identically rather than 8 slightly-different implementations.
function applyProcListFilters(rows, { search, searchFields, status, statusField }) {
  let out = rows;
  if (status) out = out.filter((r) => String(r[statusField || 'status']) === status);
  if (search && search.trim()) {
    const q = search.trim().toLowerCase();
    out = out.filter((r) => (searchFields || []).some((f) => String(r[f] || '').toLowerCase().includes(q)));
  }
  return out;
}

function procFilterBarHtml({ searchId, searchPlaceholder, statusId, statusOptions, clearId, extraHtml = '' }) {
  const statusSelect = statusId ? `
    <select id="${statusId}" class="filter-select">
      <option value="">All statuses</option>
      ${statusOptions.map((s) => `<option value="${s}">${PROC_STATUS_META[s]?.label || s}</option>`).join('')}
    </select>` : '';
  return `<div class="filter-bar">
    <div class="filter-search"><i class="ti ti-search"></i><input id="${searchId}" type="text" placeholder="${searchPlaceholder}"></div>
    ${statusSelect}
    ${extraHtml}
    <button type="button" class="filter-clear" id="${clearId}"><i class="ti ti-x"></i>Clear</button>
  </div>`;
}

// Attaches click-to-sort behavior to <th data-sort-key> headers inside
// tableEl. `getRows`/`onChange` let the caller own the actual data + re-render.
function wireSortableTable(tableEl, state, getRows, onChange) {
  tableEl.querySelectorAll('th[data-sort-key]').forEach((th) => {
    th.onclick = () => {
      const key = th.dataset.sortKey;
      if (state.key === key) state.dir = state.dir === 'asc' ? 'desc' : 'asc';
      else { state.key = key; state.dir = 'asc'; }
      tableEl.querySelectorAll('th[data-sort-key]').forEach((h) => h.removeAttribute('data-sort'));
      th.setAttribute('data-sort', state.dir);
      const rows = getRows().slice().sort((a, b) => {
        const av = a[key], bv = b[key];
        const cmp = typeof av === 'number' && typeof bv === 'number' ? av - bv : String(av || '').localeCompare(String(bv || ''));
        return state.dir === 'asc' ? cmp : -cmp;
      });
      onChange(rows);
    };
  });
}

function procApprovalStepsHtml(steps) {
  if (!steps || !steps.length) return '<p style="color:var(--t3);font-size:13px">No approval steps.</p>';
  let firstPendingSeen = false;
  return `<div class="tw"><table class="dt">
    <thead><tr><th>Stage</th><th>Status</th><th>By</th><th>Notes</th></tr></thead>
    <tbody>${steps.map((s) => {
      let badge;
      if (s.status === 'approved') badge = '<span class="badge bg">Approved</span>';
      else if (s.status === 'rejected') badge = '<span class="badge br">Rejected</span>';
      else if (s.status === 'returned') badge = '<span class="badge ba">Returned for Revision</span>';
      else if (s.status === 'skipped') badge = '<span class="badge bt">Skipped</span>';
      else if (s.status === 'pending' && !firstPendingSeen) { badge = '<span class="badge ba">Current</span>'; firstPendingSeen = true; }
      else badge = '<span class="badge bt">Pending</span>';
      return `<tr>
        <td>${PROC_STAGE_LABEL[s.stage_key] || s.stage_key}</td>
        <td>${badge}</td>
        <td style="font-size:12px">${s.approved_by_name || '—'}${s.approved_at ? '<br>' + new Date(s.approved_at).toLocaleString() : ''}</td>
        <td style="font-size:12px;color:var(--t3)">${s.notes || ''}</td>
      </tr>`;
    }).join('')}</tbody>
  </table></div>`;
}

function procItemRowHtml(idx, it, canRemove, stockItems) {
  const esc = (v) => String(v == null ? '' : v).replace(/"/g, '&quot;');
  // Optional stock-catalog link (Phase 2B, Priority 4) — nullable by design;
  // free-text-only lines (no stock_item_id) behave exactly as before. Only
  // rendered when the caller could actually load the dropdown (empty/omitted
  // stockItems means the current user doesn't have access to it — see
  // stockItemsForDropdown, an intentionally unrestricted lookup; its absence
  // here just means this picker degrades to hidden, not an error).
  const stockPicker = (stockItems && stockItems.length) ? `
    <div class="fg" style="margin-top:-.35rem;margin-bottom:.5rem">
      <label style="text-transform:none;letter-spacing:0;font-weight:400;color:var(--t4)">Link to stock item (optional — enables automatic inventory update on receipt)</label>
      <select class="pi-stock-item">
        <option value="">— Not linked (free text only) —</option>
        ${stockItems.map((si) => `<option value="${si.id}" ${Number(it.stock_item_id) === Number(si.id) ? 'selected' : ''}>${si.category ? si.category + ' — ' : ''}${si.name} (${si.uom || ''})</option>`).join('')}
      </select>
    </div>` : '';
  return `<div class="proc-item-row" data-idx="${idx}">
    <div class="frow" style="align-items:flex-end;gap:.5rem;margin-bottom:${stockPicker ? '.25rem' : '.75rem'}">
      <div class="fg" style="flex:2;margin-bottom:0"><label>${idx === 0 ? 'Description *' : ''}</label><input class="pi-desc" type="text" value="${esc(it.description)}" placeholder="Item description"></div>
      <div class="fg" style="flex:1;margin-bottom:0"><label>${idx === 0 ? 'Qty *' : ''}</label><input class="pi-qty" type="number" min="1" value="${it.quantity || 1}"></div>
      <div class="fg" style="flex:1;margin-bottom:0"><label>${idx === 0 ? 'Unit' : ''}</label><input class="pi-unit" type="text" value="${esc(it.unit)}" placeholder="pcs"></div>
      <div class="fg" style="flex:1;margin-bottom:0"><label>${idx === 0 ? 'Unit Price' : ''}</label><input class="pi-price" type="number" min="0" step="0.01" value="${it.estimated_unit_price || 0}"></div>
      ${canRemove ? '<button type="button" class="bs1 pi-remove" style="height:34px" title="Remove"><i class="ti ti-x"></i></button>' : '<div style="width:34px;flex-shrink:0"></div>'}
    </div>
    ${stockPicker}
  </div>`;
}

// ── Requisitions ──────────────────────────────────────────────────────────────

// Procurement Exception Management Phase 2 — one shared form for both
// "New Purchase Requisition" (existing=null) and "Edit" (existing set,
// reachable when status is draft or returned_for_revision), per the brief's
// explicit "do not create a second requisition page." `existingItems` is the
// requisition's current line items (from procurementRequisitionDetail),
// separate from `existing` since the requisition row itself doesn't carry them.
async function openRequisitionEditOverlay(existing, existingItems, onDone) {
  // Phase 2B, Priority 4: stock-item + workshop lookups are intentionally
  // unrestricted (see stockItemsForDropdown/workshopsForDropdown in
  // data.js) so every role that can raise a requisition can see them —
  // failure here just means the pickers degrade to hidden, never blocks
  // requisition creation itself.
  const [stockRes, whRes] = await Promise.all([
    UFCL.stockItemsForDropdown(STORAGE.user.id).catch(() => ({ ok: false })),
    UFCL.workshopsForDropdown(STORAGE.user.id).catch(() => ({ ok: false })),
  ]);
  const stockItems = stockRes.ok ? stockRes.rows : [];
  const workshops = whRes.ok ? whRes.rows : [];
  // A user already assigned to a workshop is workshop-restricted server-side
  // (procurementRequisitionCreate always uses their own workshop_id and
  // ignores anything submitted) — showing the picker to them would be
  // misleading, so it's only shown to users with no fixed workshop.
  const showWorkshopPicker = !STORAGE.user.workshop_id && workshops.length > 0;

  let items = (existingItems && existingItems.length)
    ? existingItems.map((it) => ({ description: it.description, quantity: Number(it.quantity), unit: it.unit || '', estimated_unit_price: Number(it.estimated_unit_price || 0), stock_item_id: it.stock_item_id || null }))
    : [{ description: '', quantity: 1, unit: '', estimated_unit_price: 0, stock_item_id: null }];

  openOverlay(existing ? `Edit Requisition ${existing.requisition_number || '#' + existing.id}` : 'New Purchase Requisition', null, `
    ${existing && existing.status === 'returned_for_revision' ? `<div class="fg" style="color:var(--amber);font-size:12px"><i class="ti ti-arrow-back-up"></i> This requisition was returned for revision. Correct the items below, then save and resubmit.</div>` : ''}
    <div class="frow">
      <div class="fg"><label>Title *</label><input id="pr-title" type="text" placeholder="e.g. Workshop hand tools" value="${existing ? String(existing.title || '').replace(/"/g,'&quot;') : ''}"></div>
      <div class="fg"><label>Priority</label>
        <select id="pr-priority">
          <option value="low" ${existing?.priority==='low'?'selected':''}>Low</option>
          <option value="medium" ${!existing || existing.priority==='medium'?'selected':''}>Medium</option>
          <option value="high" ${existing?.priority==='high'?'selected':''}>High</option>
          <option value="urgent" ${existing?.priority==='urgent'?'selected':''}>Urgent</option>
        </select>
      </div>
    </div>
    <div class="frow">
      <div class="fg"><label>Department</label><input id="pr-dept" type="text" value="${existing ? String(existing.department || '').replace(/"/g,'&quot;') : ''}"></div>
      <div class="fg"><label>Budget Code</label><input id="pr-budget" type="text" value="${existing ? String(existing.budget_code || '').replace(/"/g,'&quot;') : ''}"></div>
    </div>
    ${showWorkshopPicker && !existing ? `
    <div class="fg"><label>Workshop</label>
      <select id="pr-workshop">
        <option value="">— None / not workshop-specific —</option>
        ${workshops.map((w) => `<option value="${w.id}">${w.name}</option>`).join('')}
      </select>
    </div>` : ''}
    <div class="fg"><label>Description</label><input id="pr-desc" type="text" placeholder="Purpose / justification (optional)" value="${existing ? String(existing.description || '').replace(/"/g,'&quot;') : ''}"></div>
    <div class="section-hdr"><h4><i class="ti ti-list"></i>Line Items</h4></div>
    <div id="pr-items"></div>
    <button type="button" class="bs1" id="pr-additem" style="margin-bottom:.75rem"><i class="ti ti-plus"></i>Add line item</button>
    <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>${existing ? 'Save Changes' : 'Create Requisition'}</button><button class="bs1" id="ovCancel">Cancel</button></div>
  `, async () => {
    const validItems = items.filter((it) => it.description && it.description.trim());
    if (!validItems.length) { showOverlayError('Add at least one line item — enter a description for at least one row.'); return; }
    const title = $('pr-title').value.trim();
    if (!title) { showOverlayError('Title is required.'); return; }
    const payload = {
      title,
      description: $('pr-desc').value.trim() || undefined,
      department: $('pr-dept').value.trim() || undefined,
      budget_code: $('pr-budget').value.trim() || undefined,
      priority: $('pr-priority').value,
      items: validItems.map((it) => ({ ...it, stock_item_id: it.stock_item_id || undefined })),
    };
    if (existing) {
      const res2 = await UFCL.procurementRequisitionUpdate(STORAGE.user.id, existing.id, payload);
      if (!res2.ok) { showOverlayError(res2.error); return; }
      closeOverlay();
      showToast('Requisition updated.');
      openRequisitionDetailOverlay(existing.id, onDone);
    } else {
      const workshopField = $('pr-workshop');
      const res2 = await UFCL.procurementRequisitionCreate(STORAGE.user.id, {
        ...payload,
        workshop_id: workshopField && workshopField.value ? Number(workshopField.value) : undefined,
      });
      if (!res2.ok) { showOverlayError(res2.error); return; }
      closeOverlay();
      showToast('Requisition created.');
      // Navigation-consistency fix (Phase 2A): land on the new record's
      // detail view, matching mobile's existing behavior, instead of the list.
      if (res2.id) openRequisitionDetailOverlay(res2.id, onDone);
    }
  });

  function refreshItemsUI() {
    $('pr-items').innerHTML = items.map((it, i) => procItemRowHtml(i, it, items.length > 1, stockItems)).join('');
    $('pr-items').querySelectorAll('.proc-item-row').forEach((row) => {
      const idx = Number(row.dataset.idx);
      row.querySelector('.pi-desc').oninput  = (e) => { items[idx].description = e.target.value; };
      row.querySelector('.pi-qty').oninput   = (e) => { items[idx].quantity = Number(e.target.value) || 1; };
      row.querySelector('.pi-unit').oninput  = (e) => { items[idx].unit = e.target.value; };
      row.querySelector('.pi-price').oninput = (e) => { items[idx].estimated_unit_price = Number(e.target.value) || 0; };
      const stockSel = row.querySelector('.pi-stock-item');
      if (stockSel) stockSel.onchange = (e) => { items[idx].stock_item_id = e.target.value ? Number(e.target.value) : null; };
      const rmBtn = row.querySelector('.pi-remove');
      if (rmBtn) rmBtn.onclick = () => { if (items.length > 1) { items.splice(idx, 1); refreshItemsUI(); } };
    });
  }
  refreshItemsUI();
  $('pr-additem').onclick = () => { items.push({ description: '', quantity: 1, unit: '', estimated_unit_price: 0, stock_item_id: null }); refreshItemsUI(); };
}

// Procurement Exception Management Phase 2 — before/after item diff for the
// Revision Timeline. Matches items by stock_item_id when linked, otherwise
// by description (the only stable identity a free-text line has), so an
// edited quantity/price highlights as changed rather than reading as an
// unrelated add+remove.
function _procRevisionItemDiffHtml(itemsBefore, itemsAfter) {
  if (!itemsAfter) return '<p style="color:var(--t3);font-size:12px">Not yet resubmitted.</p>';
  const keyOf = (it) => it.stock_item_id ? `s:${it.stock_item_id}` : `d:${(it.description||'').trim().toLowerCase()}`;
  const beforeMap = new Map(itemsBefore.map((it) => [keyOf(it), it]));
  const afterMap = new Map(itemsAfter.map((it) => [keyOf(it), it]));
  const allKeys = Array.from(new Set([...beforeMap.keys(), ...afterMap.keys()]));
  const rows = allKeys.map((k) => {
    const b = beforeMap.get(k), a = afterMap.get(k);
    const changed = b && a && (Number(b.quantity) !== Number(a.quantity) || Number(b.estimated_unit_price||0) !== Number(a.estimated_unit_price||0) || b.description !== a.description);
    const added = !b && a, removed = b && !a;
    const style = added ? 'color:var(--green)' : removed ? 'color:var(--red);text-decoration:line-through' : changed ? 'color:var(--amber);font-weight:600' : '';
    const cur = a || b;
    return `<tr style="${style}">
      <td>${cur.description}${added ? ' <span class="badge bg" style="font-size:10px">Added</span>' : ''}${removed ? ' <span class="badge br" style="font-size:10px">Removed</span>' : ''}</td>
      <td>${b ? b.quantity : '—'}${changed && a ? ` → ${a.quantity}` : ''}</td>
      <td>${Number((b||a).estimated_unit_price||0).toLocaleString()}${changed && a && Number(b.estimated_unit_price||0) !== Number(a.estimated_unit_price||0) ? ` → ${Number(a.estimated_unit_price||0).toLocaleString()}` : ''}</td>
    </tr>`;
  }).join('');
  return `<div class="tw"><table class="dt" style="font-size:12px"><thead><tr><th>Item</th><th>Qty</th><th>Est. Price</th></tr></thead><tbody>${rows}</tbody></table></div>`;
}

function _procRevisionTimelineHtml(revisions) {
  if (!revisions || !revisions.length) return '<p style="color:var(--t3);font-size:13px">Never returned for revision.</p>';
  return revisions.map((rv) => `
    <div class="card" style="padding:12px 14px;margin-bottom:.75rem;background:var(--bg2)">
      <div class="frow" style="justify-content:space-between;align-items:flex-start">
        <div><strong>Revision ${rv.revision_number}</strong> — returned by ${rv.returned_by_name || '—'} on ${new Date(rv.returned_at).toLocaleString()}</div>
        ${rv.resubmitted_at ? `<span class="badge bg">Resubmitted</span>` : `<span class="badge ba">Awaiting revision</span>`}
      </div>
      <div style="font-size:13px;color:var(--t2);margin:.4rem 0"><strong>Reviewer comments:</strong> ${rv.reviewer_notes}</div>
      ${rv.resubmitted_at ? `<div style="font-size:12px;color:var(--t3);margin-bottom:.4rem">Resubmitted by ${rv.resubmitted_by_name || '—'} on ${new Date(rv.resubmitted_at).toLocaleString()}</div>` : ''}
      <div style="font-size:12px;font-weight:600;color:var(--t3);margin-bottom:.3rem;text-transform:uppercase;letter-spacing:.03em">Changed Items</div>
      ${_procRevisionItemDiffHtml(rv.items_before, rv.items_after)}
    </div>
  `).join('');
}

async function openRequisitionDetailOverlay(id, onDone) {
  const res = await UFCL.procurementRequisitionDetail(STORAGE.user.id, id);
  if (!res.ok) { showToast(res.error || 'Failed to load requisition', 'error'); return; }
  const { requisition: r, items, steps, revisions } = res;
  const currentStep = steps.find((s) => s.status === 'pending');
  const canAct = !!currentStep && (currentStep.assigned_role === STORAGE.user.role || STORAGE.user.role === 'admin');
  const canEdit = ['draft', 'returned_for_revision'].includes(r.status) && (r.requester_id === STORAGE.user.id || ['admin', 'ceo'].includes(STORAGE.user.role));
  const canSubmit = ['draft', 'returned_for_revision'].includes(r.status);
  const canCancel = ['draft', 'submitted', 'in_approval', 'returned_for_revision'].includes(r.status);
  const canCreateRfq = r.status === 'approved';

  // Enterprise UI/UX Standardization Phase 3 — Recently Viewed reference
  // implementation; see pushRecentlyViewed()/recentlyViewedWidgetHtml() above.
  pushRecentlyViewed('requisition', String(r.id), r.requisition_number || `#${r.id}`);

  openOverlay(`Requisition ${r.requisition_number || '#' + r.id}`, r.title, `
    <div style="margin-bottom:.75rem">${procStatusBadge(r.status)} ${r.revision_number > 0 ? `<span class="badge ba">Revision ${r.revision_number}</span>` : ''} <span style="font-size:12px;color:var(--t3)">Requested by ${r.requester_name || '—'} · ${r.department || '—'}</span></div>
    ${r.description ? `<p style="font-size:13px;color:var(--t2);margin-bottom:.75rem">${r.description}</p>` : ''}
    <div class="tw"><table class="dt"><thead><tr><th>Description</th><th>Qty</th><th>Unit</th><th>Est. Price</th></tr></thead>
    <tbody>${items.map((it) => `<tr><td>${it.description}</td><td>${it.quantity}</td><td>${it.unit || '—'}</td><td>${Number(it.estimated_unit_price).toLocaleString()}</td></tr>`).join('')}</tbody></table></div>
    <div class="section-hdr"><h4><i class="ti ti-timeline"></i>Approval Progress</h4></div>
    ${procApprovalStepsHtml(steps)}
    ${canAct ? `
      <div style="margin-top:1rem">
        <div class="fg"><label>Notes</label><input id="pr-dec-notes" type="text" placeholder="Required for Return for Revision, optional otherwise"></div>
        <div class="brow">
          <button class="bp1" id="pr-approve-btn" style="background:var(--green)"><i class="ti ti-check"></i>Approve (${PROC_STAGE_LABEL[currentStep.stage_key] || currentStep.stage_key})</button>
          <button class="bs1" id="pr-return-btn" style="color:var(--amber)"><i class="ti ti-arrow-back-up"></i>Return for Revision</button>
          <button class="bs1" id="pr-reject-btn" style="color:var(--red)"><i class="ti ti-x"></i>Reject</button>
        </div>
      </div>` : ''}
    <div class="section-hdr"><h4><i class="ti ti-history"></i>Revision Timeline</h4></div>
    ${_procRevisionTimelineHtml(revisions)}
    <div class="brow" style="margin-top:1rem">
      ${canEdit ? `<button class="bs1" id="pr-edit-btn"><i class="ti ti-edit"></i>Edit</button>` : ''}
      ${canSubmit ? `<button class="bp1" id="pr-submit-btn"><i class="ti ti-send"></i>${r.status === 'returned_for_revision' ? 'Resubmit for Approval' : 'Submit for Approval'}</button>` : ''}
      ${canCancel ? '<button class="bs1" id="pr-cancel-btn" style="color:var(--red)"><i class="ti ti-ban"></i>Cancel Requisition</button>' : ''}
      ${canCreateRfq ? '<button class="bp1" id="pr-rfq-btn"><i class="ti ti-mail-forward"></i>Create RFQ</button>' : ''}
      <button class="bs1" id="ovCancel">Close</button>
    </div>
  `, null);

  if (canAct) {
    $('pr-approve-btn').onclick = async () => {
      const res2 = await UFCL.procurementApprovalAction(STORAGE.user.id, 'requisition', r.id, 'approved', $('pr-dec-notes').value.trim() || null);
      if (!res2.ok) { showOverlayError(res2.error); return; }
      closeOverlay(); onDone?.();
    };
    $('pr-reject-btn').onclick = async () => {
      const res2 = await UFCL.procurementApprovalAction(STORAGE.user.id, 'requisition', r.id, 'rejected', $('pr-dec-notes').value.trim() || null);
      if (!res2.ok) { showOverlayError(res2.error); return; }
      closeOverlay(); onDone?.();
    };
    $('pr-return-btn').onclick = async () => {
      const notes = $('pr-dec-notes').value.trim();
      if (!notes) { showOverlayError('A reason is required to return this requisition for revision.'); return; }
      const res2 = await UFCL.procurementApprovalAction(STORAGE.user.id, 'requisition', r.id, 'returned_for_revision', notes);
      if (!res2.ok) { showOverlayError(res2.error); return; }
      showToast('Requisition returned for revision.');
      closeOverlay(); onDone?.();
    };
  }
  const editBtn = $('pr-edit-btn');
  if (editBtn) editBtn.onclick = () => { closeOverlay(); openRequisitionEditOverlay(r, items, onDone); };
  const submitBtn = $('pr-submit-btn');
  if (submitBtn) submitBtn.onclick = async () => {
    const res2 = await UFCL.procurementRequisitionSubmit(STORAGE.user.id, r.id);
    if (!res2.ok) { showOverlayError(res2.error); return; }
    closeOverlay(); onDone?.();
  };
  const cancelBtn = $('pr-cancel-btn');
  if (cancelBtn) cancelBtn.onclick = async () => {
    const reason = prompt('Reason for cancelling this requisition (optional):') || '';
    const res2 = await UFCL.procurementRequisitionCancel(STORAGE.user.id, r.id, reason);
    if (!res2.ok) { showOverlayError(res2.error); return; }
    closeOverlay(); onDone?.();
  };
  const rfqBtn = $('pr-rfq-btn');
  if (rfqBtn) rfqBtn.onclick = () => { closeOverlay(); openRfqCreateOverlay(r.id); };
}

async function renderProcurementRequisitions() {
  const page = $('page-procurement-requisitions');
  page.innerHTML = `
    <div class="page-head"><div class="page-head-text">
      <div class="ptitle"><i class="ti ti-file-invoice" style="color:var(--g-soft)"></i> Purchase Requisitions</div>
      <div class="psub">Raise requests for goods or services and track them through approval.</div>
    </div></div>
    <div class="card" style="padding:0"><table class="tbl"><thead><tr><th>Number</th><th>Title</th><th>Requester</th><th>Priority</th><th>Total Est.</th><th>Status</th><th></th></tr></thead>
    <tbody>${skeletonTableRows(7)}</tbody></table></div>`;

  const res = await UFCL.procurementRequisitionsList(STORAGE.user.id, {});
  if (!res.ok) return renderDenied('procurement-requisitions', res.error);
  const allRows = res.rows || [];
  const priBadge = { low: '<span class="badge bn">Low</span>', medium: '<span class="badge bb">Medium</span>', high: '<span class="badge ba">High</span>', urgent: '<span class="badge br">Urgent</span>' };
  const sortState = { key: null, dir: 'asc' };
  let filters = { search: '', status: '' };

  // Enterprise UI/UX Standardization Phase 2 — KPI strip, computed client-side
  // from the already-fetched allRows (same pattern renderMaterialRequests
  // already uses), no new backend query needed.
  const prSubmitted = allRows.filter(r => r.status === 'submitted').length;
  const prReturned = allRows.filter(r => r.status === 'returned_for_revision').length;
  const prApproved = allRows.filter(r => r.status === 'approved').length;
  const prRejected = allRows.filter(r => r.status === 'rejected').length;
  const prPoIssued = allRows.filter(r => r.status === 'po_issued').length;

  function rowHtml(r) {
    return `<tr>
      <td style="font-family:var(--fm)">${r.requisition_number || '#' + r.id}</td>
      <td>${r.title}</td>
      <td style="font-size:12px">${r.requester_name || '—'}</td>
      <td>${priBadge[r.priority] || r.priority}</td>
      <td style="font-family:var(--fm)">${Number(r.total_estimated_amount).toLocaleString()}</td>
      <td>${procStatusBadge(r.status)}</td>
      <td class="row-actions"><button class="bs1 pr-view" data-id="${r.id}" style="font-size:12px"><i class="ti ti-eye"></i>View</button></td>
    </tr>`;
  }

  function renderRows(rows) {
    $('pr-tbody').innerHTML = rows.length ? rows.map(rowHtml).join('') : `<tr><td colspan="7" style="text-align:center;color:var(--t3);padding:3rem">No requisitions match your filters.</td></tr>`;
    document.querySelectorAll('.pr-view').forEach((btn) => {
      btn.onclick = () => openRequisitionDetailOverlay(Number(btn.dataset.id), renderProcurementRequisitions);
    });
  }

  function currentFiltered() {
    return applyProcListFilters(allRows, { search: filters.search, searchFields: ['requisition_number', 'title', 'requester_name'], status: filters.status });
  }

  page.innerHTML = `
    <div class="page-head">
      <div class="page-head-text">
        <div class="ptitle"><i class="ti ti-file-invoice" style="color:var(--g-soft)"></i> Purchase Requisitions</div>
        <div class="psub">Raise requests for goods or services and track them through approval.</div>
      </div>
      <div class="toolbar">
        <button class="bs1" id="pr-export"><i class="ti ti-file-spreadsheet"></i>Export Excel</button>
        <button class="bp1" id="pr-add"><i class="ti ti-plus"></i>New requisition</button>
      </div>
    </div>
    <div class="cards" style="margin-bottom:1.25rem">
      ${kpiTileHtml({ label: 'Total', value: allRows.length, sub: '<i class="ti ti-file-invoice"></i>all requisitions', subCls: 'cg' })}
      ${kpiTileHtml({ label: 'Awaiting Approval', value: prSubmitted, valueColor: prSubmitted > 0 ? 'var(--amber)' : '', sub: '<i class="ti ti-clock"></i>submitted', subCls: prSubmitted > 0 ? 'ca' : 'cg' })}
      ${kpiTileHtml({ label: 'Returned for Revision', value: prReturned, valueColor: prReturned > 0 ? 'var(--amber)' : '', sub: '<i class="ti ti-arrow-back-up"></i>needs edits', subCls: prReturned > 0 ? 'ca' : 'cg' })}
      ${kpiTileHtml({ label: 'Approved', value: prApproved, valueColor: 'var(--green)', sub: '<i class="ti ti-circle-check"></i>authorized', subCls: 'cg' })}
      ${kpiTileHtml({ label: 'Rejected', value: prRejected, valueColor: prRejected > 0 ? 'var(--red)' : '', sub: '<i class="ti ti-circle-x"></i>declined', subCls: prRejected > 0 ? 'cr' : '' })}
      ${kpiTileHtml({ label: 'PO Issued', value: prPoIssued, sub: '<i class="ti ti-file-invoice"></i>converted to PO', subCls: 'bp' })}
    </div>
    ${recentlyViewedWidgetHtml('requisition')}
    ${procFilterBarHtml({ searchId: 'pr-search', searchPlaceholder: 'Search number, title, requester…', statusId: 'pr-status-filter', statusOptions: ['draft', 'submitted', 'returned_for_revision', 'approved', 'rejected', 'cancelled', 'po_issued'], clearId: 'pr-clear' })}
    ${savedFiltersBarHtml('procurement-requisitions')}
    <div class="card" style="padding:0">
      <table class="tbl" id="pr-table">
        <thead><tr>
          <th data-sort-key="requisition_number">Number</th><th data-sort-key="title">Title</th><th data-sort-key="requester_name">Requester</th>
          <th>Priority</th><th data-sort-key="total_estimated_amount">Total Est.</th><th data-sort-key="status">Status</th><th></th>
        </tr></thead>
        <tbody id="pr-tbody"></tbody>
      </table>
    </div>`;

  renderRows(allRows);
  wireSortableTable($('pr-table'), sortState, currentFiltered, renderRows);
  $('pr-search').oninput = (e) => { filters.search = e.target.value; renderRows(currentFiltered()); };
  $('pr-status-filter').onchange = (e) => { filters.status = e.target.value; renderRows(currentFiltered()); };
  $('pr-clear').onclick = () => { filters = { search: '', status: '' }; $('pr-search').value = ''; $('pr-status-filter').value = ''; renderRows(allRows); };
  $('pr-export').onclick = () => _procExportExcel('requisitions', { status: filters.status || undefined });
  // Enterprise UI/UX Standardization Phase 3 — Saved Filters reference
  // implementation; see savedFiltersBarHtml()/wireSavedFiltersBar() above.
  wireSavedFiltersBar('procurement-requisitions', {
    getValues: () => ({ search: filters.search, status: filters.status }),
    setValues: (v) => { filters.search = v.search || ''; filters.status = v.status || ''; $('pr-search').value = filters.search; $('pr-status-filter').value = filters.status; },
    onApply: () => renderRows(currentFiltered()),
  });

  $('pr-add').onclick = () => openRequisitionEditOverlay(null, null, renderProcurementRequisitions);

  document.querySelectorAll('.pr-view').forEach((btn) => {
    btn.onclick = () => openRequisitionDetailOverlay(Number(btn.dataset.id), renderProcurementRequisitions);
  });
  wireRecentlyViewedWidget('requisition', (id) => openRequisitionDetailOverlay(Number(id), renderProcurementRequisitions));
}

// ── Suppliers ─────────────────────────────────────────────────────────────────

// Phase 3C — a compact 0-100 horizontal meter for one sub-score, reused 5x
// per supplier profile (Delivery/Quality/Cost/Compliance/Responsiveness).
function subScoreBar(label, value) {
  const col = value >= 80 ? 'var(--g-soft)' : value >= 60 ? 'var(--blue)' : value >= 40 ? 'var(--amber)' : 'var(--red)';
  return `<div style="margin-bottom:.4rem">
    <div style="display:flex;justify-content:space-between;font-size:11px;color:var(--t3);margin-bottom:2px"><span>${label}</span><span style="font-weight:600;color:var(--t1)">${value}</span></div>
    <div style="height:6px;background:var(--border);border-radius:99px;overflow:hidden"><div style="height:100%;width:${value}%;background:${col}"></div></div>
  </div>`;
}

const SRM_COMPLIANCE_STATUS_COLOR = { active: 'var(--green)', expiring: 'var(--amber)', expired: 'var(--red)', missing: 'var(--t3)', waived: 'var(--blue)' };

// pg returns DATE columns as JS Date objects (no custom type parser is
// registered in db/pool.js), so interpolating them directly into a template
// literal or an <input type="date"> value produces a verbose toString() —
// this normalizes either a Date object or an already-string value to
// 'YYYY-MM-DD'. pg's built-in DATE parser constructs the Date at *local*
// midnight (confirmed empirically — not UTC midnight), so local getters are
// the correct inverse; UTC getters would shift the day back by one in any
// positive-UTC-offset timezone (e.g. 2026-08-15 → 2026-08-14 in SAST).
function _fmtDate(v) {
  if (!v) return null;
  if (v instanceof Date) return `${v.getFullYear()}-${String(v.getMonth() + 1).padStart(2, '0')}-${String(v.getDate()).padStart(2, '0')}`;
  return String(v).slice(0, 10);
}

// Supplier profile — Phase 4 SRM. Restructured from one long scrolling
// overlay into tabs (Overview/Contracts/Compliance/Documents/Communications/
// Improvements/Intelligence) per SUPPLIER_RELATIONSHIP_PHASE4 spec §7 — each
// tab lazy-loads its own data via loadTab(), matching the pattern already
// used by renderProcurementReports's report tabs, rather than fetching all
// seven endpoints up front.
async function openSupplierManageOverlay(id, supplierName, initialTab = 'overview') {
  const canGovern = (STORAGE.pages || []).includes('procurement-suppliers-governance');
  const TAB_META = {
    overview: { label: 'Overview', icon: 'ti-address-book' },
    contracts: { label: 'Contracts', icon: 'ti-file-text' },
    compliance: { label: 'Compliance', icon: 'ti-shield-check' },
    documents: { label: 'Documents', icon: 'ti-folder' },
    communications: { label: 'Communications', icon: 'ti-messages' },
    improvements: { label: 'Improvements', icon: 'ti-tool' },
    intelligence: { label: 'Intelligence', icon: 'ti-brain' },
  };

  openOverlay('Manage Supplier', supplierName || null, `
    <div class="smo-tabs" id="smo-tabs">
      ${Object.entries(TAB_META).map(([t, m]) => `<button type="button" class="smo-tab ${t === initialTab ? 'active' : ''}" data-tab="${t}"><i class="ti ${m.icon}"></i>${m.label}</button>`).join('')}
    </div>
    <div id="smo-body"></div>
    <div class="brow" style="margin-top:1rem"><button class="bs1" id="ovCancel">Close</button></div>
  `, null, 'ow-wide');

  async function loadTab(tab) {
    const body = $('smo-body');
    body.innerHTML = `<div class="card" style="padding:0"><table class="tbl"><thead><tr><th></th><th></th><th></th></tr></thead><tbody>${skeletonTableRows(3)}</tbody></table></div>`;
    if (tab === 'overview') return renderOverviewTab(body);
    if (tab === 'contracts') return renderContractsTab(body);
    if (tab === 'compliance') return renderComplianceTab(body);
    if (tab === 'documents') return renderDocumentsTab(body);
    if (tab === 'communications') return renderCommunicationsTab(body);
    if (tab === 'improvements') return renderImprovementsTab(body);
    if (tab === 'intelligence') return renderIntelligenceTab(body);
  }

  // ── Overview: contacts ──────────────────────────────────────────────────
  async function renderOverviewTab(body) {
    const res = await UFCL.procurementSupplierContactsList(STORAGE.user.id, id);
    const contacts = res.ok ? res.rows : [];
    body.innerHTML = `
      <div class="section-hdr"><h4><i class="ti ti-address-book"></i>Contacts</h4></div>
      <div class="tw"><table class="dt"><thead><tr><th>Name</th><th>Role</th><th>Phone</th><th>Email</th><th></th></tr></thead>
      <tbody>${contacts.length ? contacts.map((c) => `<tr>
        <td>${c.name}${c.is_primary ? ' (Primary)' : ''}</td><td>${c.role || '—'}</td><td>${c.phone || '—'}</td><td>${c.email || '—'}</td>
        <td class="row-actions">
          <button class="bs1 sc-edit" data-id="${c.id}" title="Edit"><i class="ti ti-edit"></i></button>
          <button class="bs1 sc-del" data-id="${c.id}" title="Delete" style="color:var(--red)"><i class="ti ti-trash"></i></button>
        </td>
      </tr>`).join('') : '<tr><td colspan="5" style="text-align:center;color:var(--t3)">No contacts yet.</td></tr>'}</tbody></table></div>
      <div class="frow" style="margin-top:.5rem">
        <div class="fg"><label>Name</label><input id="sc-name" type="text"></div>
        <div class="fg"><label>Role</label><input id="sc-role" type="text"></div>
        <div class="fg"><label>Phone</label><input id="sc-phone" type="text"></div>
      </div>
      <button type="button" class="bs1" id="sc-add"><i class="ti ti-plus"></i>Add Contact</button>`;

    $('sc-add').onclick = async () => {
      const name = $('sc-name').value.trim();
      if (!name) { showOverlayError('Contact name is required.'); return; }
      const res2 = await UFCL.procurementSupplierContactCreate(STORAGE.user.id, id, {
        name, role: $('sc-role').value.trim() || undefined, phone: $('sc-phone').value.trim() || undefined,
      });
      if (!res2.ok) { showOverlayError(res2.error); return; }
      showToast('Contact added.');
      renderOverviewTab(body);
    };
    document.querySelectorAll('.sc-edit').forEach((btn) => {
      btn.onclick = () => {
        const c = contacts.find((r) => Number(r.id) === Number(btn.dataset.id));
        openOverlay('Edit Contact', null, `
          <div class="frow">
            <div class="fg"><label>Name *</label><input id="ec-name" type="text" value="${c.name || ''}"></div>
            <div class="fg"><label>Role</label><input id="ec-role" type="text" value="${c.role || ''}"></div>
          </div>
          <div class="frow">
            <div class="fg"><label>Phone</label><input id="ec-phone" type="text" value="${c.phone || ''}"></div>
            <div class="fg"><label>Email</label><input id="ec-email" type="text" value="${c.email || ''}"></div>
          </div>
          <div class="fg"><label><input type="checkbox" id="ec-primary" ${c.is_primary ? 'checked' : ''}> Primary contact</label></div>
          <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Save Changes</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
        async () => {
          const name = $('ec-name').value.trim();
          if (!name) { showOverlayError('Contact name is required.'); return; }
          const res2 = await UFCL.procurementSupplierContactUpdate(STORAGE.user.id, c.id, {
            name, role: $('ec-role').value.trim() || null, phone: $('ec-phone').value.trim() || null,
            email: $('ec-email').value.trim() || null, is_primary: $('ec-primary').checked,
          });
          if (!res2.ok) { showOverlayError(res2.error); return; }
          showToast('Contact updated.');
          openSupplierManageOverlay(id, supplierName, 'overview');
        });
      };
    });
    document.querySelectorAll('.sc-del').forEach((btn) => {
      btn.onclick = () => {
        const c = contacts.find((r) => Number(r.id) === Number(btn.dataset.id));
        confirmDelete(`Delete contact "${c.name}"?`, async () => {
          const res2 = await UFCL.procurementSupplierContactDelete(STORAGE.user.id, c.id);
          if (!res2.ok) { showOverlayError(res2.error); return; }
          showToast('Contact deleted.');
          openSupplierManageOverlay(id, supplierName, 'overview');
        });
      };
    });
  }

  // ── Contracts: register + approve/renew ─────────────────────────────────
  async function renderContractsTab(body) {
    const res = await UFCL.procurementSupplierContractsList(STORAGE.user.id, id);
    const contracts = res.ok ? res.rows : [];
    body.innerHTML = `
      <div class="section-hdr"><h4><i class="ti ti-file-text"></i>Contracts</h4></div>
      <div class="tw"><table class="dt"><thead><tr><th>Ref</th><th>Category</th><th>Start</th><th>End</th><th>Value</th><th>Status</th><th></th></tr></thead>
      <tbody>${contracts.length ? contracts.map((c) => `<tr>
        <td>${c.contract_ref}</td><td style="font-size:12px">${c.category || '—'}</td>
        <td style="font-size:12px">${_fmtDate(c.start_date) || '—'}</td><td style="font-size:12px">${_fmtDate(c.end_date) || '—'}</td>
        <td style="font-family:var(--fm)">${c.contract_value != null ? Number(c.contract_value).toLocaleString() : '—'}</td>
        <td>${procStatusBadge(c.status)}</td>
        <td class="row-actions">
          <button class="bs1 scn-edit" data-id="${c.id}" title="Edit"><i class="ti ti-edit"></i></button>
          ${canGovern && c.status === 'draft' ? `<button class="bs1 scn-approve" data-id="${c.id}" title="Approve"><i class="ti ti-circle-check" style="color:var(--green)"></i></button>` : ''}
          ${!['renewed', 'cancelled', 'draft'].includes(c.status) ? `<button class="bs1 scn-renew" data-id="${c.id}" title="Renew"><i class="ti ti-refresh"></i></button>` : ''}
        </td>
      </tr>`).join('') : '<tr><td colspan="7" style="text-align:center;color:var(--t3)">No contracts yet.</td></tr>'}</tbody></table></div>
      <div class="frow" style="margin-top:.5rem">
        <div class="fg"><label>Contract Ref *</label><input id="scn-ref" type="text"></div>
        <div class="fg"><label>Category</label><input id="scn-category" type="text"></div>
        <div class="fg"><label>Start Date</label><input id="scn-start" type="date"></div>
        <div class="fg"><label>End Date</label><input id="scn-end" type="date"></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Contract Value</label><input id="scn-value" type="number" step="0.01"></div>
        <div class="fg"><label>Renewal Notice (days)</label><input id="scn-notice" type="number" placeholder="90"></div>
      </div>
      <button type="button" class="bs1" id="scn-add"><i class="ti ti-plus"></i>Add Contract (starts as Draft)</button>`;

    $('scn-add').onclick = async () => {
      const ref = $('scn-ref').value.trim();
      if (!ref) { showOverlayError('Contract reference is required.'); return; }
      const res2 = await UFCL.procurementSupplierContractCreate(STORAGE.user.id, id, {
        contract_ref: ref, category: $('scn-category').value.trim() || undefined,
        start_date: $('scn-start').value || undefined, end_date: $('scn-end').value || undefined,
        contract_value: $('scn-value').value ? Number($('scn-value').value) : undefined,
        renewal_notice_days: $('scn-notice').value ? Number($('scn-notice').value) : undefined,
      });
      if (!res2.ok) { showOverlayError(res2.error); return; }
      showToast('Contract added — pending approval.');
      renderContractsTab(body);
    };
    document.querySelectorAll('.scn-edit').forEach((btn) => {
      btn.onclick = () => {
        const c = contracts.find((r) => Number(r.id) === Number(btn.dataset.id));
        openOverlay('Edit Contract', null, `
          <div class="fg"><label>Contract Ref *</label><input id="ecn-ref" type="text" value="${c.contract_ref || ''}"></div>
          <div class="frow">
            <div class="fg"><label>Start Date</label><input id="ecn-start" type="date" value="${_fmtDate(c.start_date) || ''}"></div>
            <div class="fg"><label>End Date</label><input id="ecn-end" type="date" value="${_fmtDate(c.end_date) || ''}"></div>
          </div>
          <div class="fg"><label>Contract Value</label><input id="ecn-value" type="number" step="0.01" value="${c.contract_value ?? ''}"></div>
          <div class="fg"><label>Terms</label><input id="ecn-terms" type="text" value="${c.terms || ''}"></div>
          <div class="fg"><label>Notes</label><input id="ecn-notes" type="text" value="${c.notes || ''}"></div>
          <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Save Changes</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
        async () => {
          const ref = $('ecn-ref').value.trim();
          if (!ref) { showOverlayError('Contract reference is required.'); return; }
          const res2 = await UFCL.procurementSupplierContractUpdate(STORAGE.user.id, c.id, {
            contract_ref: ref, start_date: $('ecn-start').value || null, end_date: $('ecn-end').value || null,
            contract_value: $('ecn-value').value ? Number($('ecn-value').value) : null,
            terms: $('ecn-terms').value.trim() || null, notes: $('ecn-notes').value.trim() || null,
          });
          if (!res2.ok) { showOverlayError(res2.error); return; }
          showToast('Contract updated.');
          openSupplierManageOverlay(id, supplierName, 'contracts');
        });
      };
    });
    document.querySelectorAll('.scn-approve').forEach((btn) => {
      btn.onclick = () => {
        const c = contracts.find((r) => Number(r.id) === Number(btn.dataset.id));
        openOverlay(`Approve ${c.contract_ref}`, null, `
          <div class="fg"><label>Reason *</label><textarea id="ap-reason" rows="3"></textarea></div>
          <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Approve Contract</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
        async () => {
          const reason = $('ap-reason').value.trim();
          if (!reason) { showOverlayError('A reason is required.'); return; }
          const res2 = await UFCL.srmContractApprove(STORAGE.user.id, c.id, reason);
          if (!res2.ok) { showOverlayError(res2.error); return; }
          showToast('Contract approved.');
          openSupplierManageOverlay(id, supplierName, 'contracts');
        });
      };
    });
    document.querySelectorAll('.scn-renew').forEach((btn) => {
      btn.onclick = () => {
        const c = contracts.find((r) => Number(r.id) === Number(btn.dataset.id));
        openOverlay(`Renew ${c.contract_ref}`, null, `
          <div class="fg"><label>New End Date *</label><input id="rn-end" type="date"></div>
          <div class="fg"><label>Contract Value</label><input id="rn-value" type="number" step="0.01" value="${c.contract_value ?? ''}"></div>
          <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Renew Contract</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
        async () => {
          const endDate = $('rn-end').value;
          if (!endDate) { showOverlayError('A new end date is required.'); return; }
          const res2 = await UFCL.srmContractRenew(STORAGE.user.id, c.id, {
            end_date: endDate, contract_value: $('rn-value').value ? Number($('rn-value').value) : undefined,
          });
          if (!res2.ok) { showOverlayError(res2.error); return; }
          showToast('Contract renewed.');
          openSupplierManageOverlay(id, supplierName, 'contracts');
        });
      };
    });
  }

  // ── Compliance: fixed 7-type checklist ──────────────────────────────────
  async function renderComplianceTab(body) {
    const res = await UFCL.srmComplianceList(STORAGE.user.id, id);
    const rows = res.ok ? res.rows : [];
    body.innerHTML = `
      <div class="section-hdr"><h4><i class="ti ti-shield-check"></i>Compliance Checklist</h4></div>
      <div class="tw"><table class="dt"><thead><tr><th>Type</th><th>Issue Date</th><th>Expiry Date</th><th>Status</th><th>Notes</th><th></th></tr></thead>
      <tbody>${rows.map((c) => {
        const computed = c.computedStatus || c.status;
        const color = SRM_COMPLIANCE_STATUS_COLOR[computed] || 'var(--t3)';
        return `<tr>
          <td>${c.compliance_type}</td><td style="font-size:12px">${_fmtDate(c.issue_date) || '—'}</td><td style="font-size:12px">${_fmtDate(c.expiry_date) || '—'}</td>
          <td><span class="badge" style="background:${color}22;color:${color};text-transform:capitalize">${computed}</span></td>
          <td style="font-size:12px">${c.notes || '—'}</td>
          <td class="row-actions"><button class="bs1 sco-edit" data-type="${c.compliance_type}" title="Update"><i class="ti ti-edit"></i></button></td>
        </tr>`;
      }).join('')}</tbody></table></div>`;

    document.querySelectorAll('.sco-edit').forEach((btn) => {
      btn.onclick = () => {
        const c = rows.find((r) => r.compliance_type === btn.dataset.type);
        openOverlay(c.compliance_type, null, `
          <div class="frow">
            <div class="fg"><label>Issue Date</label><input id="co-issue" type="date" value="${_fmtDate(c.issue_date) || ''}"></div>
            <div class="fg"><label>Expiry Date</label><input id="co-expiry" type="date" value="${_fmtDate(c.expiry_date) || ''}"></div>
          </div>
          ${canGovern ? `<div class="fg"><label><input type="checkbox" id="co-waived" ${c.status === 'waived' ? 'checked' : ''}> Waive this requirement</label></div>` : ''}
          <div class="fg"><label>Notes</label><textarea id="co-notes" rows="2">${c.notes || ''}</textarea></div>
          <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Save</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
        async () => {
          const waived = canGovern && $('co-waived') ? $('co-waived').checked : c.status === 'waived';
          const res2 = await UFCL.srmComplianceUpsert(STORAGE.user.id, id, {
            compliance_type: c.compliance_type, issue_date: $('co-issue').value || undefined, expiry_date: $('co-expiry').value || undefined,
            status: waived ? 'waived' : 'valid', notes: $('co-notes').value.trim() || undefined,
          });
          if (!res2.ok) { showOverlayError(res2.error); return; }
          showToast('Compliance record updated.');
          openSupplierManageOverlay(id, supplierName, 'compliance');
        });
      };
    });
  }

  // ── Documents ─────────────────────────────────────────────────────────────
  async function renderDocumentsTab(body) {
    const res = await UFCL.srmDocumentsList(STORAGE.user.id, id);
    const docs = res.ok ? res.rows : [];
    body.innerHTML = `
      <div class="section-hdr"><h4><i class="ti ti-folder"></i>Documents</h4></div>
      <div class="tw"><table class="dt"><thead><tr><th>Filename</th><th>Type</th><th>Version</th><th>Expiry</th><th>Uploaded</th><th></th></tr></thead>
      <tbody>${docs.length ? docs.map((d) => `<tr>
        <td>${d.original_filename}</td><td style="font-size:12px">${d.document_type}</td><td>v${d.version}</td>
        <td style="font-size:12px">${_fmtDate(d.expiry_date) || '—'}</td>
        <td style="font-size:12px">${d.uploaded_by_name || '—'}${d.uploaded_at ? ' · ' + new Date(d.uploaded_at).toLocaleDateString() : ''}</td>
        <td class="row-actions">
          <button class="bs1 sd-download" data-id="${d.id}" data-name="${String(d.original_filename).replace(/"/g, '&quot;')}" title="Download"><i class="ti ti-download"></i></button>
          <button class="bs1 sd-del" data-id="${d.id}" title="Delete" style="color:var(--red)"><i class="ti ti-trash"></i></button>
        </td>
      </tr>`).join('') : '<tr><td colspan="6" style="text-align:center;color:var(--t3)">No documents uploaded yet.</td></tr>'}</tbody></table></div>
      <button type="button" class="bs1" id="sd-upload" style="margin-top:.5rem"><i class="ti ti-cloud-upload"></i>Upload Document</button>`;

    $('sd-upload').onclick = async () => {
      const picked = await UFCL.srmDocumentsPickFile();
      if (!picked.ok) return;
      openOverlay('Upload Document', picked.fileName, `
        <div class="fg"><label>Document Type</label>
          <select id="ud-type">
            <option>Contract Document</option><option>Compliance Certificate</option><option>Insurance</option>
            <option>Tax Document</option><option>Quality Certificate</option><option>Attachment</option>
          </select>
        </div>
        <div class="fg"><label>Expiry Date (optional)</label><input id="ud-expiry" type="date"></div>
        <div class="fg"><label>Notes</label><textarea id="ud-notes" rows="2"></textarea></div>
        <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-cloud-upload"></i>Upload</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
      async () => {
        const res2 = await UFCL.srmDocumentsUpload(STORAGE.user.id, {
          supplierId: id, filePath: picked.filePath, documentType: $('ud-type').value,
          expiryDate: $('ud-expiry').value || undefined, notes: $('ud-notes').value.trim() || undefined,
        });
        if (!res2.ok) { showOverlayError(res2.error); return; }
        showToast('Document uploaded.');
        openSupplierManageOverlay(id, supplierName, 'documents');
      });
    };
    document.querySelectorAll('.sd-download').forEach((btn) => {
      btn.onclick = async () => {
        const res2 = await UFCL.srmDocumentsDownload(STORAGE.user.id, Number(btn.dataset.id), btn.dataset.name);
        if (!res2.ok) { showToast(res2.error || 'Download failed', 'error'); return; }
        if (res2.filePath) showToast('Document saved.');
      };
    });
    document.querySelectorAll('.sd-del').forEach((btn) => {
      btn.onclick = () => {
        const d = docs.find((r) => Number(r.id) === Number(btn.dataset.id));
        confirmDelete(`Delete document "${d.original_filename}"?`, async () => {
          const res2 = await UFCL.srmDocumentsDeactivate(STORAGE.user.id, d.id);
          if (!res2.ok) { showOverlayError(res2.error); return; }
          showToast('Document deleted.');
          openSupplierManageOverlay(id, supplierName, 'documents');
        });
      };
    });
  }

  // ── Communications ────────────────────────────────────────────────────────
  async function renderCommunicationsTab(body) {
    const res = await UFCL.srmCommunicationsList(STORAGE.user.id, id);
    const rows = res.ok ? res.rows : [];
    body.innerHTML = `
      <div class="section-hdr"><h4><i class="ti ti-messages"></i>Communications</h4></div>
      <div class="tw"><table class="dt"><thead><tr><th>Date</th><th>Type</th><th>Subject</th><th>Next Action</th><th></th></tr></thead>
      <tbody>${rows.length ? rows.map((c) => `<tr>
        <td style="font-size:12px">${_fmtDate(c.date)}</td><td>${c.communication_type}</td><td>${c.subject}</td>
        <td style="font-size:12px">${c.next_action || '—'}${c.next_action_date ? ` (${c.next_action_date})` : ''}</td>
        <td class="row-actions"><button class="bs1 sm-edit" data-id="${c.id}" title="Edit"><i class="ti ti-edit"></i></button></td>
      </tr>`).join('') : '<tr><td colspan="5" style="text-align:center;color:var(--t3)">No communications logged yet.</td></tr>'}</tbody></table></div>
      <button type="button" class="bs1" id="sm-add" style="margin-top:.5rem"><i class="ti ti-plus"></i>Log Communication</button>`;

    function openCommForm(existing) {
      openOverlay(existing ? 'Edit Communication' : 'Log Communication', null, `
        <div class="frow">
          <div class="fg"><label>Type *</label>
            <select id="cm-type">${['Meeting', 'Call', 'Email', 'Site Visit', 'Negotiation', 'Complaint'].map((t) => `<option ${existing?.communication_type === t ? 'selected' : ''}>${t}</option>`).join('')}</select>
          </div>
          <div class="fg"><label>Date</label><input id="cm-date" type="date" value="${_fmtDate(existing?.date) || new Date().toISOString().slice(0, 10)}"></div>
        </div>
        <div class="fg"><label>Subject *</label><input id="cm-subject" type="text" value="${existing?.subject || ''}"></div>
        <div class="fg"><label>Notes</label><textarea id="cm-notes" rows="2">${existing?.notes || ''}</textarea></div>
        <div class="frow">
          <div class="fg"><label>Next Action</label><input id="cm-next" type="text" value="${existing?.next_action || ''}"></div>
          <div class="fg"><label>Next Action Date</label><input id="cm-nextdate" type="date" value="${existing?.next_action_date ? String(existing.next_action_date).slice(0, 10) : ''}"></div>
        </div>
        <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>${existing ? 'Save Changes' : 'Log Entry'}</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
      async () => {
        const subject = $('cm-subject').value.trim();
        if (!subject) { showOverlayError('Subject is required.'); return; }
        const payload = {
          communication_type: $('cm-type').value, subject, date: $('cm-date').value || undefined,
          notes: $('cm-notes').value.trim() || undefined, next_action: $('cm-next').value.trim() || undefined,
          next_action_date: $('cm-nextdate').value || undefined,
        };
        const res2 = existing ? await UFCL.srmCommunicationUpdate(STORAGE.user.id, existing.id, payload) : await UFCL.srmCommunicationCreate(STORAGE.user.id, id, payload);
        if (!res2.ok) { showOverlayError(res2.error); return; }
        showToast(existing ? 'Communication updated.' : 'Communication logged.');
        openSupplierManageOverlay(id, supplierName, 'communications');
      });
    }
    $('sm-add').onclick = () => openCommForm(null);
    document.querySelectorAll('.sm-edit').forEach((btn) => {
      btn.onclick = () => openCommForm(rows.find((r) => Number(r.id) === Number(btn.dataset.id)));
    });
  }

  // ── Improvement Plans ────────────────────────────────────────────────────
  async function renderImprovementsTab(body) {
    const res = await UFCL.srmImprovementPlansList(STORAGE.user.id, id);
    const rows = res.ok ? res.rows : [];
    body.innerHTML = `
      <div class="section-hdr"><h4><i class="ti ti-tool"></i>Improvement Plans</h4></div>
      <div class="tw"><table class="dt"><thead><tr><th>Title</th><th>Type</th><th>Status</th><th>Due</th><th>Completion</th><th></th></tr></thead>
      <tbody>${rows.length ? rows.map((p) => `<tr>
        <td>${p.title}</td><td style="font-size:12px">${String(p.plan_type).replace('_', ' ')}</td><td>${procStatusBadge(p.status)}</td>
        <td style="font-size:12px">${_fmtDate(p.due_date) || '—'}</td><td>${p.completion_percent}%</td>
        <td class="row-actions"><button class="bs1 sip-edit" data-id="${p.id}" title="Edit"><i class="ti ti-edit"></i></button></td>
      </tr>`).join('') : '<tr><td colspan="6" style="text-align:center;color:var(--t3)">No improvement plans yet.</td></tr>'}</tbody></table></div>
      <button type="button" class="bs1" id="sip-add" style="margin-top:.5rem"><i class="ti ti-plus"></i>New Improvement Plan</button>`;

    function openPlanForm(existing) {
      openOverlay(existing ? 'Edit Improvement Plan' : 'New Improvement Plan', null, `
        <div class="fg"><label>Title *</label><input id="ip-title" type="text" value="${existing?.title || ''}"></div>
        <div class="fg"><label>Description</label><textarea id="ip-desc" rows="2">${existing?.description || ''}</textarea></div>
        <div class="frow">
          <div class="fg"><label>Plan Type</label>
            <select id="ip-type">${['corrective_action', 'development', 'training', 'review'].map((t) => `<option value="${t}" ${existing?.plan_type === t ? 'selected' : ''}>${t.replace('_', ' ')}</option>`).join('')}</select>
          </div>
          ${existing ? `<div class="fg"><label>Status</label>
            <select id="ip-status">${['open', 'in_progress', 'closed', 'completed'].map((s) => `<option value="${s}" ${existing?.status === s ? 'selected' : ''}>${s.replace('_', ' ')}</option>`).join('')}</select>
          </div>` : ''}
        </div>
        <div class="frow">
          <div class="fg"><label>Due Date</label><input id="ip-due" type="date" value="${_fmtDate(existing?.due_date) || ''}"></div>
          <div class="fg"><label>Completion %</label><input id="ip-pct" type="number" min="0" max="100" value="${existing?.completion_percent ?? 0}"></div>
        </div>
        <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>${existing ? 'Save Changes' : 'Create Plan'}</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
      async () => {
        const title = $('ip-title').value.trim();
        if (!title) { showOverlayError('Title is required.'); return; }
        const payload = {
          title, description: $('ip-desc').value.trim() || undefined, plan_type: $('ip-type').value,
          status: existing ? $('ip-status').value : undefined,
          due_date: $('ip-due').value || undefined, completion_percent: Math.max(0, Math.min(100, Number($('ip-pct').value) || 0)),
        };
        const res2 = existing ? await UFCL.srmImprovementPlanUpdate(STORAGE.user.id, existing.id, payload) : await UFCL.srmImprovementPlanCreate(STORAGE.user.id, id, payload);
        if (!res2.ok) { showOverlayError(res2.error); return; }
        showToast(existing ? 'Plan updated.' : 'Improvement plan created.');
        openSupplierManageOverlay(id, supplierName, 'improvements');
      });
    }
    $('sip-add').onclick = () => openPlanForm(null);
    document.querySelectorAll('.sip-edit').forEach((btn) => {
      btn.onclick = () => openPlanForm(rows.find((r) => Number(r.id) === Number(btn.dataset.id)));
    });
  }

  // ── Intelligence (Phase 3C, unchanged — moved into its own tab) ─────────
  async function renderIntelligenceTab(body) {
    const intelRes = await UFCL.supplierIntelligenceProfile(STORAGE.user.id, id);
    if (!intelRes.ok) { body.innerHTML = `<div class="lerr" style="display:block">${intelRes.error || 'Could not load supplier intelligence.'}</div>`; return; }
    const intel = intelRes;
    const s = intel.supplier;
    body.innerHTML = `
    <div class="frow" style="align-items:center;gap:1.25rem;margin-bottom:1rem">
      <div style="flex-shrink:0">${_svgGauge(s.overallScore, s.tier)}</div>
      <div style="flex:1;min-width:220px">
        ${subScoreBar('Delivery', s.scores.delivery)}
        ${subScoreBar('Quality', s.scores.quality)}
        ${subScoreBar('Cost', s.scores.cost)}
        ${subScoreBar('Compliance', s.scores.compliance)}
        ${subScoreBar('Responsiveness', s.scores.responsiveness)}
      </div>
    </div>
    <div class="cards" style="margin-bottom:1rem">
      <div class="mc"><div class="mclbl">Purchase Orders</div><div class="mcval">${s.totalPos}</div></div>
      <div class="mc"><div class="mclbl">Total Spend</div><div class="mcval" style="font-size:16px">${Number(s.totalSpend).toLocaleString()}</div></div>
      <div class="mc"><div class="mclbl">Reject Rate</div><div class="mcval">${s.rejectRatePct}%</div></div>
      <div class="mc"><div class="mclbl">On-Time Rate</div><div class="mcval">${s.onTimeRatePct ?? '—'}${s.onTimeRatePct != null ? '%' : ''}</div></div>
      <div class="mc"><div class="mclbl">Last Purchase</div><div class="mcval" style="font-size:14px">${s.lastPurchaseDate ? new Date(s.lastPurchaseDate).toLocaleDateString() : '—'}</div></div>
    </div>
    ${s.riskIndicators.length ? `<div class="lerr" style="display:block"><i class="ti ti-alert-triangle"></i> ${s.riskIndicators.join(' · ')}</div>` : ''}
    <div style="background:var(--g-pale);border:1px solid var(--border);border-radius:var(--r-md);padding:.6rem .8rem;font-size:12.5px;color:var(--t2);margin-bottom:1rem">
      <i class="ti ti-bulb" style="color:var(--g-soft)"></i> ${s.recommendation}
    </div>

    ${intel.trend.length > 1 ? `<div class="section-hdr"><h4><i class="ti ti-chart-line"></i>Performance Trend (6 months)</h4></div>
    <div class="card" style="margin-bottom:1rem">
      <div style="font-size:11px;color:var(--t3);margin-bottom:2px">Spend</div>
      ${_svgLine(intel.trend, 'spend', { h: 60, color: '#1D4ED8' })}
      <div style="font-size:11px;color:var(--t3);margin:.5rem 0 2px">Reject Rate %</div>
      ${_svgLine(intel.trend, 'rejectRatePct', { h: 60, color: '#DC2626', fill: false })}
      <div style="display:flex;justify-content:space-between;margin-top:.3rem;font-size:10px;color:var(--t3)">
        ${intel.trend.map((t) => `<span>${t.month}</span>`).join('')}
      </div>
    </div>` : ''}

    <div class="section-hdr"><h4><i class="ti ti-history"></i>Purchase History</h4></div>
    <div class="tw"><table class="dt"><thead><tr><th>Type</th><th>Ref</th><th>Date</th><th>Status</th><th>Amount</th></tr></thead>
    <tbody>${intel.purchaseHistory.length ? intel.purchaseHistory.slice(0, 10).map((h) => `<tr>
      <td style="font-size:12px">${h.kind === 'purchase_order' ? 'PO' : h.kind === 'invoice' ? 'Invoice' : 'Goods Receipt'}</td>
      <td>${h.ref || '#' + h.id}</td><td style="font-size:12px">${new Date(h.date).toLocaleDateString()}</td>
      <td>${procStatusBadge(h.status)}</td><td style="font-family:var(--fm)">${h.amount != null ? Number(h.amount).toLocaleString() : '—'}</td>
    </tr>`).join('') : '<tr><td colspan="5" style="text-align:center;color:var(--t3)">No purchase history yet.</td></tr>'}</tbody></table></div>

    <div class="section-hdr"><h4><i class="ti ti-timeline"></i>Timeline</h4></div>
    <div style="max-height:220px;overflow-y:auto;margin-bottom:.5rem">
      ${intel.timeline.length ? intel.timeline.map((t) => `
        <div style="display:flex;gap:.6rem;padding:.35rem 0;border-bottom:1px solid var(--border);font-size:12px">
          <div style="width:78px;flex-shrink:0;color:var(--t3)">${new Date(t.date).toLocaleDateString()}</div>
          <div style="flex:1;color:var(--t1)">${t.label}${t.reason ? ` <span style="color:var(--t3)">— ${t.reason}</span>` : ''}</div>
        </div>`).join('') : '<p style="color:var(--t3);font-size:12px">No activity recorded yet.</p>'}
    </div>`;
  }

  document.querySelectorAll('.smo-tab').forEach((btn) => {
    btn.onclick = () => {
      document.querySelectorAll('.smo-tab').forEach((b) => b.classList.remove('active'));
      btn.classList.add('active');
      loadTab(btn.dataset.tab);
    };
  });
  await loadTab(initialTab);
}

// ── Phase 4 — Contract Register (cross-supplier). Reached from a link on the
// Procurement Dashboard rather than its own NAV entry, so it reuses the
// already-granted 'procurement-suppliers' permission instead of requiring a
// new permission page-id (see SUPPLIER_RELATIONSHIP_PHASE4_COMPLETION_
// REPORT.md "Architecture Decisions").
async function openContractRegisterOverlay() {
  const canGovern = (STORAGE.pages || []).includes('procurement-suppliers-governance');
  const res = await UFCL.srmContractsRegister(STORAGE.user.id, {});
  if (!res.ok) { showToast(res.error, 'error'); return; }
  const allRows = res.rows;
  let state = { search: '', status: '' };

  function filtered() {
    let out = allRows;
    if (state.search.trim()) {
      const q = state.search.trim().toLowerCase();
      out = out.filter((c) => c.contract_ref.toLowerCase().includes(q) || (c.supplier_name || '').toLowerCase().includes(q));
    }
    if (state.status) out = out.filter((c) => c.computedStatus === state.status);
    return out;
  }

  function rowHtml(c) {
    return `<tr>
      <td>${c.contract_ref}</td><td>${c.supplier_name}</td><td style="font-size:12px">${c.category || '—'}</td>
      <td style="font-size:12px">${_fmtDate(c.end_date) || '—'}</td>
      <td style="font-family:var(--fm)">${c.contract_value != null ? Number(c.contract_value).toLocaleString() : '—'}</td>
      <td>${procStatusBadge(c.computedStatus || c.status)}</td>
      <td class="row-actions">
        ${canGovern && c.status === 'draft' ? `<button class="bs1 cr-approve" data-id="${c.id}" title="Approve"><i class="ti ti-circle-check" style="color:var(--green)"></i></button>` : ''}
        ${!['renewed', 'cancelled', 'draft'].includes(c.status) ? `<button class="bs1 cr-renew" data-id="${c.id}" title="Renew"><i class="ti ti-refresh"></i></button>` : ''}
        <button class="bs1 cr-open" data-id="${c.supplier_id}" data-name="${String(c.supplier_name).replace(/"/g, '&quot;')}" title="Open Supplier"><i class="ti ti-arrow-right"></i></button>
      </td>
    </tr>`;
  }

  openOverlay('Contract Register', `${allRows.length} contracts across all suppliers`, `
    <div class="filter-bar">
      <div class="filter-search"><i class="ti ti-search"></i><input id="cr-search" type="text" placeholder="Search contract ref, supplier…"></div>
      <select id="cr-status" class="filter-select">
        <option value="">All statuses</option><option value="draft">Draft</option><option value="active">Active</option>
        <option value="expiring">Expiring</option><option value="expired">Expired</option><option value="renewed">Renewed</option>
      </select>
    </div>
    <div class="tw"><table class="dt" id="cr-table"><thead><tr><th>Ref</th><th>Supplier</th><th>Category</th><th>End Date</th><th>Value</th><th>Status</th><th></th></tr></thead>
    <tbody id="cr-tbody">${filtered().map(rowHtml).join('') || '<tr><td colspan="7" style="text-align:center;color:var(--t3)">No contracts found.</td></tr>'}</tbody></table></div>
    <div class="brow" style="margin-top:1rem"><button class="bs1" id="ovCancel">Close</button></div>
  `, null, 'ow-wide');

  function wireRowActions() {
    document.querySelectorAll('.cr-approve').forEach((btn) => {
      btn.onclick = () => {
        const c = allRows.find((r) => Number(r.id) === Number(btn.dataset.id));
        openOverlay(`Approve ${c.contract_ref}`, null, `
          <div class="fg"><label>Reason *</label><textarea id="ap-reason" rows="3"></textarea></div>
          <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Approve Contract</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
        async () => {
          const reason = $('ap-reason').value.trim();
          if (!reason) { showOverlayError('A reason is required.'); return; }
          const res2 = await UFCL.srmContractApprove(STORAGE.user.id, c.id, reason);
          if (!res2.ok) { showOverlayError(res2.error); return; }
          showToast('Contract approved.');
          openContractRegisterOverlay();
        });
      };
    });
    document.querySelectorAll('.cr-renew').forEach((btn) => {
      btn.onclick = () => {
        const c = allRows.find((r) => Number(r.id) === Number(btn.dataset.id));
        openOverlay(`Renew ${c.contract_ref}`, null, `
          <div class="fg"><label>New End Date *</label><input id="rn-end" type="date"></div>
          <div class="fg"><label>Contract Value</label><input id="rn-value" type="number" step="0.01" value="${c.contract_value ?? ''}"></div>
          <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Renew Contract</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
        async () => {
          const endDate = $('rn-end').value;
          if (!endDate) { showOverlayError('A new end date is required.'); return; }
          const res2 = await UFCL.srmContractRenew(STORAGE.user.id, c.id, { end_date: endDate, contract_value: $('rn-value').value ? Number($('rn-value').value) : undefined });
          if (!res2.ok) { showOverlayError(res2.error); return; }
          showToast('Contract renewed.');
          openContractRegisterOverlay();
        });
      };
    });
    document.querySelectorAll('.cr-open').forEach((btn) => {
      btn.onclick = () => openSupplierManageOverlay(Number(btn.dataset.id), btn.dataset.name, 'contracts');
    });
  }
  wireRowActions();
  $('cr-search').oninput = (e) => { state.search = e.target.value; $('cr-tbody').innerHTML = filtered().map(rowHtml).join('') || '<tr><td colspan="7" style="text-align:center;color:var(--t3)">No contracts found.</td></tr>'; wireRowActions(); };
  $('cr-status').onchange = (e) => { state.status = e.target.value; $('cr-tbody').innerHTML = filtered().map(rowHtml).join('') || '<tr><td colspan="7" style="text-align:center;color:var(--t3)">No contracts found.</td></tr>'; wireRowActions(); };
}

// ── Phase 4 — Compliance Center (cross-supplier matrix). Same reasoning as
// the Contract Register above — reused permission, no new NAV/page.
async function openComplianceCenterOverlay() {
  const res = await UFCL.srmComplianceRegister(STORAGE.user.id, {});
  if (!res.ok) { showToast(res.error, 'error'); return; }
  const allRows = res.rows;
  let state = { search: '', status: '' };

  function filtered() {
    let out = allRows;
    if (state.search.trim()) {
      const q = state.search.trim().toLowerCase();
      out = out.filter((r) => r.supplier_name.toLowerCase().includes(q) || r.compliance_type.toLowerCase().includes(q));
    }
    if (state.status) out = out.filter((r) => r.status === state.status);
    return out;
  }

  function rowHtml(r) {
    const color = SRM_COMPLIANCE_STATUS_COLOR[r.status] || 'var(--t3)';
    return `<tr>
      <td>${r.supplier_name}</td><td>${r.compliance_type}</td><td style="font-size:12px">${_fmtDate(r.expiry_date) || '—'}</td>
      <td><span class="badge" style="background:${color}22;color:${color};text-transform:capitalize">${r.status}</span></td>
      <td class="row-actions"><button class="bs1 cc-open" data-id="${r.supplier_id}" data-name="${String(r.supplier_name).replace(/"/g, '&quot;')}" title="Open Supplier"><i class="ti ti-arrow-right"></i></button></td>
    </tr>`;
  }

  const complianceTypeCount = new Set(allRows.map((r) => r.compliance_type)).size;
  openOverlay('Compliance Center', `${allRows.length} records across all suppliers × ${complianceTypeCount} compliance types`, `
    <div class="filter-bar">
      <div class="filter-search"><i class="ti ti-search"></i><input id="cc-search" type="text" placeholder="Search supplier, compliance type…"></div>
      <select id="cc-status" class="filter-select">
        <option value="">All statuses</option><option value="active">Active</option><option value="expiring">Expiring</option>
        <option value="expired">Expired</option><option value="missing">Missing</option><option value="waived">Waived</option>
      </select>
    </div>
    <div class="tw"><table class="dt" id="cc-table"><thead><tr><th>Supplier</th><th>Type</th><th>Expiry</th><th>Status</th><th></th></tr></thead>
    <tbody id="cc-tbody">${filtered().map(rowHtml).join('') || '<tr><td colspan="5" style="text-align:center;color:var(--t3)">No records found.</td></tr>'}</tbody></table></div>
    <div class="brow" style="margin-top:1rem"><button class="bs1" id="ovCancel">Close</button></div>
  `, null, 'ow-wide');

  function wireRowActions() {
    document.querySelectorAll('.cc-open').forEach((btn) => {
      btn.onclick = () => openSupplierManageOverlay(Number(btn.dataset.id), btn.dataset.name, 'compliance');
    });
  }
  wireRowActions();
  $('cc-search').oninput = (e) => { state.search = e.target.value; $('cc-tbody').innerHTML = filtered().map(rowHtml).join('') || '<tr><td colspan="5" style="text-align:center;color:var(--t3)">No records found.</td></tr>'; wireRowActions(); };
  $('cc-status').onchange = (e) => { state.status = e.target.value; $('cc-tbody').innerHTML = filtered().map(rowHtml).join('') || '<tr><td colspan="5" style="text-align:center;color:var(--t3)">No records found.</td></tr>'; wireRowActions(); };
}

// Phase 3C — Supplier Comparison. `selected` = [{id, name}, ...], 2+ items.
async function openSupplierComparisonOverlay(selected) {
  if (selected.length < 2) { showToast('Select at least two suppliers to compare.', 'error'); return; }
  const res = await UFCL.supplierIntelligenceCompare(STORAGE.user.id, selected.map((s) => s.id));
  if (!res.ok) { showToast(res.error, 'error'); return; }
  const rows = res.suppliers;

  // Each metric row: label, accessor, formatter, and whether a higher raw
  // value is "better" (drives which cell gets the winner highlight — null
  // means don't highlight a winner for this row, e.g. Risk/Contract Status).
  const metrics = [
    { label: 'Overall Score', get: (s) => s.overallScore, fmt: (v) => v, higherBetter: true },
    { label: 'Rating', get: (s) => s.tier, fmt: (v, s) => supplierTierBadge(v), higherBetter: null },
    { label: 'Total Spend', get: (s) => s.totalSpend, fmt: (v) => Number(v).toLocaleString(), higherBetter: null },
    { label: 'Purchase Orders', get: (s) => s.totalPos, fmt: (v) => v, higherBetter: null },
    { label: 'Goods Receipts', get: (s) => s.totalReceipts, fmt: (v) => v, higherBetter: null },
    { label: 'Delivery Score', get: (s) => s.scores.delivery, fmt: (v) => v, higherBetter: true },
    { label: 'Quality Score', get: (s) => s.scores.quality, fmt: (v) => v, higherBetter: true },
    { label: 'Cost Score', get: (s) => s.scores.cost, fmt: (v) => v, higherBetter: true },
    { label: 'Compliance Score', get: (s) => s.scores.compliance, fmt: (v) => v, higherBetter: true },
    { label: 'Responsiveness Score', get: (s) => s.scores.responsiveness, fmt: (v) => v, higherBetter: true },
    { label: 'Risk', get: (s) => s.tier === 'High Risk' ? 'High' : s.riskIndicators.length ? 'Moderate' : 'Low', fmt: (v) => v, higherBetter: null },
    { label: 'Contract Status', get: (s) => s.activeContracts > 0 ? `${s.activeContracts} active` : s.expiredContracts > 0 ? 'Expired' : 'None on file', fmt: (v) => v, higherBetter: null },
    { label: 'Last Purchase', get: (s) => s.lastPurchaseDate, fmt: (v) => v ? new Date(v).toLocaleDateString() : '—', higherBetter: null },
  ];

  openOverlay(`Compare Suppliers (${rows.length})`, null, `
    <div class="tw"><table class="dt">
      <thead><tr><th>Metric</th>${rows.map((s) => `<th>${s.name}</th>`).join('')}</tr></thead>
      <tbody>
        ${metrics.map((m) => {
          const vals = rows.map((s) => m.get(s));
          const best = m.higherBetter === true ? Math.max(...vals.map((v) => Number(v) || 0)) : null;
          return `<tr><td style="font-weight:600;color:var(--t2)">${m.label}</td>${rows.map((s, i) => {
            const raw = vals[i];
            const isWinner = best !== null && Number(raw) === best && best > 0;
            return `<td style="${isWinner ? 'color:var(--g-soft);font-weight:700' : ''}">${m.fmt(raw, s)}${isWinner ? ' <i class="ti ti-trophy" style="color:var(--amber)"></i>' : ''}</td>`;
          }).join('')}</tr>`;
        }).join('')}
      </tbody>
    </table></div>
    <div class="brow" style="margin-top:1rem"><button class="bs1" id="ovCancel">Close</button></div>
  `, null);
}

async function renderProcurementSuppliers() {
  const page = $('page-procurement-suppliers');
  page.innerHTML = `
    <div class="page-head"><div class="page-head-text">
      <div class="ptitle"><i class="ti ti-building-store" style="color:var(--g-soft)"></i> Suppliers</div>
      <div class="psub">Supplier registry — contacts, contracts and performance.</div>
    </div></div>
    <div class="card" style="padding:0"><table class="tbl"><thead><tr><th>Name</th><th>Category</th><th>Phone</th><th>Rating</th><th>Status</th><th></th></tr></thead>
    <tbody>${skeletonTableRows(6)}</tbody></table></div>`;

  const res = await UFCL.procurementSuppliersList(STORAGE.user.id, {});
  if (!res.ok) return renderDenied('procurement-suppliers', res.error);
  const allRows = res.rows || [];
  // Phase 3B permission cleanup: replaces the hardcoded
  // ['admin','ceo','procurement-manager'] role array with the centralized
  // permission system — STORAGE.pages is the same resolved-permissions list
  // NAV/other pages already gate on (see e.g. the stock-movements check).
  const canGovern = (STORAGE.pages || []).includes('procurement-suppliers-governance');
  const sortState = { key: null, dir: 'asc' };
  const categories = Array.from(new Set(allRows.map((s) => s.category).filter(Boolean))).sort();
  let filters = { search: '', status: '', category: '', preferred: false, blacklistedOnly: false };

  const compareSelection = new Map(); // id -> name

  function rowHtml(s) {
    return `<tr>
      <td><input type="checkbox" class="sup-compare-chk" data-id="${s.id}" data-name="${String(s.name).replace(/"/g, '&quot;')}" ${compareSelection.has(String(s.id)) ? 'checked' : ''}></td>
      <td>${s.name}${s.preferred ? ' <i class="ti ti-star" style="color:var(--amber)" title="Preferred"></i>' : ''}</td>
      <td style="font-size:12px">${s.category || '—'}</td>
      <td style="font-size:12px">${s.phone || '—'}</td>
      <td>${s.rating ?? '—'}</td>
      <td>${procStatusBadge(s.status)}</td>
      <td class="row-actions">
        <button class="bs1 sup-manage" data-id="${s.id}" title="Manage"><i class="ti ti-settings"></i></button>
        <button class="bs1 sup-edit" data-id="${s.id}" title="Edit"><i class="ti ti-edit"></i></button>
        ${canGovern ? supplierGovernanceButtons(s) : ''}
      </td>
    </tr>`;
  }

  // The action set changes with lifecycle status — e.g. an already-
  // blacklisted supplier gets "Restore", not "Blacklist" again.
  function supplierGovernanceButtons(s) {
    const st = s.status || 'active';
    const btns = [];
    if (st === 'blacklisted') {
      btns.push(`<button class="bs1 sup-status" data-id="${s.id}" data-target="active" data-title="Restore Supplier" data-action="Restore" title="Restore"><i class="ti ti-rotate"></i></button>`);
    } else {
      if (st === 'active') {
        btns.push(`<button class="bs1 sup-status" data-id="${s.id}" data-target="suspended" data-title="Deactivate Supplier" data-action="Deactivate" title="Deactivate"><i class="ti ti-player-pause"></i></button>`);
      } else {
        btns.push(`<button class="bs1 sup-status" data-id="${s.id}" data-target="active" data-title="Activate Supplier" data-action="Activate" title="Activate"><i class="ti ti-circle-check"></i></button>`);
      }
      btns.push(`<button class="bs1 sup-status" data-id="${s.id}" data-target="blacklisted" data-title="Blacklist Supplier" data-action="Blacklist" title="Blacklist" style="color:var(--red)"><i class="ti ti-ban"></i></button>`);
    }
    btns.push(`<button class="bs1 sup-del" data-id="${s.id}" title="Delete" style="color:var(--red)"><i class="ti ti-trash"></i></button>`);
    return btns.join('');
  }

  function renderRows(rows) {
    $('sup-tbody').innerHTML = rows.length ? rows.map(rowHtml).join('') : `<tr><td colspan="7" style="text-align:center;color:var(--t3);padding:3rem">No suppliers match your filters.</td></tr>`;
    wireSupplierRowActions();
    document.querySelectorAll('.sup-compare-chk').forEach((chk) => {
      chk.onchange = () => {
        if (chk.checked) compareSelection.set(chk.dataset.id, chk.dataset.name);
        else compareSelection.delete(chk.dataset.id);
        updateCompareButton();
      };
    });
  }
  function updateCompareButton() {
    const btn = $('sup-compare-btn');
    if (!btn) return;
    btn.disabled = compareSelection.size < 2;
    $('sup-compare-count').textContent = compareSelection.size;
  }
  function currentFiltered() {
    let out = applyProcListFilters(allRows, { search: filters.search, searchFields: ['name', 'category', 'phone'], status: filters.status });
    if (filters.category) out = out.filter((s) => s.category === filters.category);
    if (filters.preferred) out = out.filter((s) => s.preferred);
    if (filters.blacklistedOnly) out = out.filter((s) => s.blacklisted);
    return out;
  }

  page.innerHTML = `
    <div class="page-head">
      <div class="page-head-text">
        <div class="ptitle"><i class="ti ti-building-store" style="color:var(--g-soft)"></i> Suppliers</div>
        <div class="psub">Supplier registry — lifecycle, contacts, contracts and performance.</div>
      </div>
      <div class="toolbar">
        <button class="bs1" id="sup-compare-btn" disabled title="Select 2 or more suppliers to compare"><i class="ti ti-scale"></i>Compare (<span id="sup-compare-count">0</span>)</button>
        <button class="bs1" id="sup-export"><i class="ti ti-file-spreadsheet"></i>Export Excel</button>
        <button class="bp1" id="sup-add"><i class="ti ti-plus"></i>Register supplier</button>
      </div>
    </div>
    ${procFilterBarHtml({
      searchId: 'sup-search', searchPlaceholder: 'Search name, category, phone…',
      statusId: 'sup-status-filter',
      statusOptions: ['draft', 'pending_approval', 'active', 'suspended', 'blacklisted', 'archived'],
      clearId: 'sup-clear',
      extraHtml: `
        ${categories.length ? `<select id="sup-category-filter" class="filter-select"><option value="">All categories</option>${categories.map((c) => `<option value="${c}">${c}</option>`).join('')}</select>` : ''}
        <button type="button" class="filter-chip" id="sup-chip-preferred"><i class="ti ti-star"></i>Preferred</button>
        <button type="button" class="filter-chip" id="sup-chip-blacklisted"><i class="ti ti-ban"></i>Blacklisted</button>
      `,
    })}
    <div class="card" style="padding:0">
      <table class="tbl" id="sup-table">
        <thead><tr><th style="width:32px"></th><th data-sort-key="name">Name</th><th data-sort-key="category">Category</th><th>Phone</th><th data-sort-key="rating">Rating</th><th>Status</th><th></th></tr></thead>
        <tbody id="sup-tbody"></tbody>
      </table>
    </div>`;

  renderRows(allRows);
  $('sup-export').onclick = () => _procExportExcel('suppliers', {});
  $('sup-compare-btn').onclick = () => openSupplierComparisonOverlay(Array.from(compareSelection.entries()).map(([id, name]) => ({ id: Number(id), name })));
  wireSortableTable($('sup-table'), sortState, currentFiltered, renderRows);
  $('sup-search').oninput = (e) => { filters.search = e.target.value; renderRows(currentFiltered()); };
  const supStatusSel = $('sup-status-filter');
  supStatusSel.onchange = (e) => { filters.status = e.target.value; renderRows(currentFiltered()); };
  const supCategorySel = $('sup-category-filter');
  if (supCategorySel) supCategorySel.onchange = (e) => { filters.category = e.target.value; renderRows(currentFiltered()); };
  const chipPreferred = $('sup-chip-preferred');
  const chipBlacklisted = $('sup-chip-blacklisted');
  chipPreferred.onclick = () => { filters.preferred = !filters.preferred; chipPreferred.classList.toggle('active', filters.preferred); renderRows(currentFiltered()); };
  chipBlacklisted.onclick = () => { filters.blacklistedOnly = !filters.blacklistedOnly; chipBlacklisted.classList.toggle('active', filters.blacklistedOnly); renderRows(currentFiltered()); };
  $('sup-clear').onclick = () => {
    filters = { search: '', status: '', category: '', preferred: false, blacklistedOnly: false };
    $('sup-search').value = ''; supStatusSel.value = ''; if (supCategorySel) supCategorySel.value = '';
    chipPreferred.classList.remove('active'); chipBlacklisted.classList.remove('active');
    renderRows(allRows);
  };

  function supplierForm(s) {
    const esc = (v) => String(v == null ? '' : v).replace(/"/g, '&quot;');
    return `
      <div class="frow">
        <div class="fg"><label>Name *</label><input id="sf-name" type="text" value="${esc(s?.name)}"></div>
        <div class="fg"><label>Category</label><input id="sf-category" type="text" value="${esc(s?.category)}"></div>
      </div>
      <div class="frow">
        <div class="fg"><label>Phone</label><input id="sf-phone" type="text" value="${esc(s?.phone)}"></div>
        <div class="fg"><label>Email</label><input id="sf-email" type="text" value="${esc(s?.email)}"></div>
      </div>
      <div class="fg"><label>Address</label><input id="sf-address" type="text" value="${esc(s?.address)}"></div>
      <div class="frow">
        <div class="fg"><label>Tax Number</label><input id="sf-tax" type="text" value="${esc(s?.tax_number)}"></div>
        <div class="fg"><label>Bank Name</label><input id="sf-bank" type="text" value="${esc(s?.bank_name)}"></div>
        <div class="fg"><label>Bank Account</label><input id="sf-acct" type="text" value="${esc(s?.bank_account)}"></div>
      </div>
      <div class="fg"><label><input type="checkbox" id="sf-preferred" ${s?.preferred ? 'checked' : ''}> Preferred supplier</label></div>
      <div class="fg"><label>Notes</label><input id="sf-notes" type="text" value="${esc(s?.notes)}"></div>
    `;
  }

  $('sup-add').onclick = () => {
    openOverlay('Register Supplier', null, `${supplierForm(null)}
      <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Create Supplier</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
    async () => {
      const name = $('sf-name').value.trim();
      if (!name) { showOverlayError('Supplier name is required.'); return; }
      const res2 = await UFCL.procurementSupplierCreate(STORAGE.user.id, {
        name, category: $('sf-category').value.trim() || undefined, phone: $('sf-phone').value.trim() || undefined,
        email: $('sf-email').value.trim() || undefined, address: $('sf-address').value.trim() || undefined,
        tax_number: $('sf-tax').value.trim() || undefined, bank_name: $('sf-bank').value.trim() || undefined,
        bank_account: $('sf-acct').value.trim() || undefined, preferred: $('sf-preferred').checked,
        notes: $('sf-notes').value.trim() || undefined,
      });
      if (!res2.ok) { showOverlayError(res2.error); return; }
      closeOverlay();
      showToast('Supplier registered.');
      await renderProcurementSuppliers();
    });
  };

  function wireSupplierRowActions() {
    document.querySelectorAll('.sup-edit').forEach((btn) => {
      btn.onclick = () => {
        const s = allRows.find((r) => Number(r.id) === Number(btn.dataset.id));
        openOverlay('Edit Supplier', s.name, `${supplierForm(s)}
          <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Save Changes</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
        async () => {
          const res2 = await UFCL.procurementSupplierUpdate(STORAGE.user.id, s.id, {
            name: $('sf-name').value.trim(), category: $('sf-category').value.trim() || null, phone: $('sf-phone').value.trim() || null,
            email: $('sf-email').value.trim() || null, address: $('sf-address').value.trim() || null,
            tax_number: $('sf-tax').value.trim() || null, bank_name: $('sf-bank').value.trim() || null,
            bank_account: $('sf-acct').value.trim() || null, preferred: $('sf-preferred').checked,
            notes: $('sf-notes').value.trim() || null,
          });
          if (!res2.ok) { showOverlayError(res2.error); return; }
          closeOverlay();
          showToast('Supplier updated.');
          await renderProcurementSuppliers();
        });
      };
    });

    // Every lifecycle transition (Activate, Deactivate, Blacklist, Restore)
    // goes through the same reason-required overlay and the same
    // procurementSupplierSetStatus call — one code path, not one per action.
    document.querySelectorAll('.sup-status').forEach((btn) => {
      btn.onclick = () => {
        const supplierId = Number(btn.dataset.id);
        const target = btn.dataset.target;
        const title = btn.dataset.title;
        const actionLabel = btn.dataset.action;
        const danger = target === 'blacklisted' || target === 'suspended';
        openOverlay(title, null, `
          <div class="fg"><label>Reason *</label><input id="ssc-reason" type="text"></div>
          <div class="brow"><button class="bp1" id="ovSave" ${danger ? 'style="background:var(--red)"' : ''}><i class="ti ti-check"></i>${actionLabel}</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
        async () => {
          const reason = $('ssc-reason').value.trim();
          if (!reason) { showOverlayError('Reason is required.'); return; }
          const res2 = await UFCL.procurementSupplierSetStatus(STORAGE.user.id, supplierId, target, reason);
          if (!res2.ok) { showOverlayError(res2.error); return; }
          closeOverlay();
          showToast('Supplier status updated.');
          await renderProcurementSuppliers();
        });
      };
    });

    document.querySelectorAll('.sup-del').forEach((btn) => {
      btn.onclick = () => {
        const s = allRows.find((r) => Number(r.id) === Number(btn.dataset.id));
        confirmDelete(`Delete supplier "${s.name}"?`, async () => {
          const res2 = await UFCL.procurementSupplierDelete(STORAGE.user.id, s.id);
          if (res2.ok) {
            closeOverlay();
            showToast('Supplier deleted.');
            await renderProcurementSuppliers();
            return;
          }
          // Deletion blocked by procurement history — offer Archive as the
          // safe alternative instead of just showing a dead-end error.
          if (/procurement history exists/i.test(res2.error || '')) {
            openOverlay('Cannot Delete Supplier', null, `
              <p style="color:var(--t1);margin-bottom:.75rem">${res2.error}</p>
              <div class="fg"><label>Reason to archive instead *</label><input id="ssc-reason" type="text"></div>
              <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-archive"></i>Archive Instead</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
            async () => {
              const reason = $('ssc-reason').value.trim();
              if (!reason) { showOverlayError('Reason is required.'); return; }
              const res3 = await UFCL.procurementSupplierSetStatus(STORAGE.user.id, s.id, 'archived', reason);
              if (!res3.ok) { showOverlayError(res3.error); return; }
              closeOverlay();
              showToast('Supplier archived.');
              await renderProcurementSuppliers();
            });
            return;
          }
          showOverlayError(res2.error);
        });
      };
    });

    document.querySelectorAll('.sup-manage').forEach((btn) => {
      btn.onclick = () => {
        const s = allRows.find((r) => Number(r.id) === Number(btn.dataset.id));
        openSupplierManageOverlay(Number(btn.dataset.id), s?.name);
      };
    });
  }
}

// ── RFQ / Quotations ──────────────────────────────────────────────────────────

async function openRfqCreateOverlay(requisitionId) {
  openOverlay('New RFQ', null, `
    <div class="fg"><label>Title</label><input id="rfq-title" type="text" placeholder="Optional — defaults to requisition title"></div>
    <div class="fg"><label>Due Date</label><input id="rfq-due" type="date"></div>
    <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Create RFQ</button><button class="bs1" id="ovCancel">Cancel</button></div>
  `, async () => {
    const res = await UFCL.procurementRfqCreate(STORAGE.user.id, requisitionId, {
      title: $('rfq-title').value.trim() || undefined,
      due_date: $('rfq-due').value || undefined,
    });
    if (!res.ok) { showOverlayError(res.error); return; }
    closeOverlay();
    showToast('RFQ created.');
    // Navigation-consistency fix (Phase 2A): open the new RFQ's detail view
    // directly, matching mobile's existing behavior, instead of the list.
    await showPage('procurement-rfq');
    if (res.id) openRfqDetailOverlay(res.id);
  });
}

async function openRfqDetailOverlay(id) {
  const res = await UFCL.procurementRfqDetail(STORAGE.user.id, id);
  if (!res.ok) { showToast(res.error, 'error'); return; }
  const { rfq, suppliers, quotations } = res;
  const suppliersRes = await UFCL.procurementSuppliersList(STORAGE.user.id, {});
  const invitedIds = new Set(suppliers.map((s) => s.supplier_id));
  const available = (suppliersRes.ok ? suppliersRes.rows : []).filter((s) => !invitedIds.has(s.id) && !s.blacklisted);
  const selected = quotations.find((q) => q.status === 'selected');

  openOverlay(`RFQ ${rfq.rfq_number || '#' + rfq.id}`, rfq.title, `
    <div style="margin-bottom:.75rem">${procStatusBadge(rfq.status)} ${rfq.due_date ? `<span style="font-size:12px;color:var(--t3)">Due ${new Date(rfq.due_date).toLocaleDateString()}</span>` : ''}</div>

    <div class="section-hdr"><h4><i class="ti ti-mail"></i>Invited Suppliers</h4></div>
    <div class="tw"><table class="dt"><thead><tr><th>Supplier</th><th>Status</th></tr></thead>
    <tbody>${suppliers.length ? suppliers.map((s) => `<tr><td>${s.supplier_name}${s.blacklisted ? ' <span class="badge br badge-ic" style="font-size:10px"><i class="ti ti-ban"></i>Blacklisted</span>' : ''}</td><td>${procStatusBadge(s.status)}</td></tr>`).join('') : '<tr><td colspan="2" style="text-align:center;color:var(--t3)">None invited yet.</td></tr>'}</tbody></table></div>

    <div class="frow" style="margin-top:.6rem">
      <div class="fg" style="flex:2"><label>Invite Supplier</label><select id="rfq-inv-supplier"><option value="">— Select —</option>${available.map((s) => `<option value="${s.id}">${s.name}</option>`).join('')}</select></div>
      <button type="button" class="bs1" id="rfq-invite-btn" style="height:34px;align-self:flex-end">Invite</button>
    </div>

    <div class="section-hdr"><h4><i class="ti ti-clipboard-plus"></i>Record Quotation (on supplier's behalf)</h4></div>
    <div class="frow">
      <div class="fg"><label>Supplier</label><select id="rfq-q-supplier"><option value="">— Select —</option>${suppliers.filter((s) => !s.blacklisted).map((s) => `<option value="${s.supplier_id}">${s.supplier_name}</option>`).join('')}</select></div>
      <div class="fg"><label>Quoted Amount</label><input id="rfq-q-amount" type="number" min="0"></div>
      <div class="fg"><label>Delivery Days</label><input id="rfq-q-days" type="number" min="0"></div>
    </div>
    <div class="fg"><label>Terms</label><input id="rfq-q-terms" type="text"></div>
    <button type="button" class="bp1" id="rfq-q-submit" style="margin-bottom:1rem"><i class="ti ti-plus"></i>Add Quotation</button>

    <div class="section-hdr"><h4><i class="ti ti-scale"></i>Quotation Comparison</h4></div>
    <div class="tw"><table class="dt"><thead><tr><th>Supplier</th><th>Amount</th><th>Delivery</th><th>Status</th><th></th></tr></thead>
    <tbody>${quotations.length ? quotations.map((q) => `<tr>
      <td>${q.supplier_name}${q.preferred ? ' ★' : ''}${q.blacklisted ? ' <span class="badge br badge-ic" style="font-size:10px"><i class="ti ti-ban"></i>Blacklisted</span>' : ''}</td>
      <td style="font-family:var(--fm)">${Number(q.quoted_amount).toLocaleString()}</td>
      <td>${q.delivery_days ?? '—'}</td>
      <td>${procStatusBadge(q.status)}</td>
      <td>${q.status === 'received' && !selected ? (q.blacklisted ? '<span style="font-size:11px;color:var(--red)">Blacklisted</span>' : `<button class="bs1 rfq-select-btn" data-id="${q.id}" style="font-size:12px">Select</button>`) : ''}</td>
    </tr>`).join('') : '<tr><td colspan="5" style="text-align:center;color:var(--t3)">No quotations yet.</td></tr>'}</tbody></table></div>

    ${selected && selected.blacklisted ? `<div class="lerr" style="display:block;margin-top:1rem"><i class="ti ti-alert-triangle"></i> This supplier is blacklisted and cannot participate in procurement. Purchase order generation is disabled.</div>` : ''}
    ${selected && !selected.blacklisted ? '<button type="button" class="bp1" id="rfq-genpo-btn" style="margin-top:1rem;background:var(--green)"><i class="ti ti-file-invoice"></i>Generate Purchase Order</button>' : ''}
    <div class="brow" style="margin-top:1rem"><button class="bs1" id="ovCancel">Close</button></div>
  `, null);

  $('rfq-invite-btn').onclick = async () => {
    const sid = $('rfq-inv-supplier').value;
    if (!sid) { showOverlayError('Select a supplier first.'); return; }
    const res2 = await UFCL.procurementRfqSend(STORAGE.user.id, rfq.id, [Number(sid)]);
    if (!res2.ok) { showOverlayError(res2.error); return; }
    showToast('Supplier invited.');
    openRfqDetailOverlay(id);
  };
  $('rfq-q-submit').onclick = async () => {
    const sid = $('rfq-q-supplier').value;
    const amt = $('rfq-q-amount').value;
    if (!sid || !amt) { showOverlayError('Supplier and quoted amount are required.'); return; }
    const res2 = await UFCL.procurementQuotationSubmit(STORAGE.user.id, rfq.id, Number(sid), {
      quoted_amount: Number(amt), delivery_days: $('rfq-q-days').value || undefined, terms: $('rfq-q-terms').value.trim() || undefined,
    });
    if (!res2.ok) { showOverlayError(res2.error); return; }
    showToast('Quotation recorded.');
    openRfqDetailOverlay(id);
  };
  document.querySelectorAll('.rfq-select-btn').forEach((btn) => {
    btn.onclick = async () => {
      const res2 = await UFCL.procurementQuotationSelect(STORAGE.user.id, Number(btn.dataset.id));
      if (!res2.ok) { showToast(res2.error, 'error'); return; }
      showToast('Quotation selected.');
      openRfqDetailOverlay(id);
    };
  });
  const genBtn = $('rfq-genpo-btn');
  if (genBtn) genBtn.onclick = async () => {
    const res2 = await UFCL.procurementPoGenerate(STORAGE.user.id, rfq.requisition_id, selected.id);
    if (!res2.ok) { showToast(res2.error, 'error'); return; }
    closeOverlay();
    showToast('Purchase order generated.');
    // Navigation-consistency fix (Phase 2A): open the new PO's detail view
    // directly, matching mobile's existing behavior, instead of the list.
    await showPage('procurement-orders');
    if (res2.id) openPoDetailOverlay(res2.id);
  };
}

async function renderProcurementRfq() {
  const page = $('page-procurement-rfq');
  page.innerHTML = `
    <div class="page-head"><div class="page-head-text">
      <div class="ptitle"><i class="ti ti-file-text" style="color:var(--g-soft)"></i> RFQ / Quotations</div>
      <div class="psub">Send requests for quotation to suppliers and compare their bids.</div>
    </div></div>
    <div class="card" style="padding:0"><table class="tbl"><thead><tr><th>RFQ #</th><th>Title</th><th>Requisition</th><th>Status</th><th>Due Date</th><th></th></tr></thead>
    <tbody>${skeletonTableRows(6)}</tbody></table></div>`;

  const [res, reqRes] = await Promise.all([
    UFCL.procurementRfqList(STORAGE.user.id),
    UFCL.procurementRequisitionsList(STORAGE.user.id, { status: 'approved' }),
  ]);
  if (!res.ok) return renderDenied('procurement-rfq', res.error);
  const allRows = res.rows || [];
  const approvedReqs = reqRes.ok ? reqRes.rows : [];
  const sortState = { key: null, dir: 'asc' };
  let filters = { search: '', status: '' };

  function rowHtml(r) {
    return `<tr>
      <td style="font-family:var(--fm)">${r.rfq_number || '#' + r.id}</td>
      <td>${r.title}</td>
      <td style="font-size:12px">${r.requisition_number || '—'}</td>
      <td>${procStatusBadge(r.status)}</td>
      <td style="font-size:12px">${r.due_date ? new Date(r.due_date).toLocaleDateString() : '—'}</td>
      <td class="row-actions"><button class="bs1 rfq-view" data-id="${r.id}" style="font-size:12px"><i class="ti ti-eye"></i>View</button></td>
    </tr>`;
  }
  function renderRows(rows) {
    $('rfq-tbody').innerHTML = rows.length ? rows.map(rowHtml).join('') : `<tr><td colspan="6" style="text-align:center;color:var(--t3);padding:3rem">No RFQs match your filters.</td></tr>`;
    document.querySelectorAll('.rfq-view').forEach((btn) => btn.onclick = () => openRfqDetailOverlay(Number(btn.dataset.id)));
  }
  function currentFiltered() {
    return applyProcListFilters(allRows, { search: filters.search, searchFields: ['rfq_number', 'title', 'requisition_number'], status: filters.status });
  }

  page.innerHTML = `
    <div class="page-head">
      <div class="page-head-text">
        <div class="ptitle"><i class="ti ti-file-text" style="color:var(--g-soft)"></i> RFQ / Quotations</div>
        <div class="psub">Send requests for quotation to suppliers and compare their bids.</div>
      </div>
      <div class="toolbar">
        <button class="bs1" id="rfq-export"><i class="ti ti-file-spreadsheet"></i>Export Excel</button>
        <select id="rfq-new-req" class="filter-select">
          <option value="">— New RFQ from requisition —</option>
          ${approvedReqs.map((r) => `<option value="${r.id}">${r.requisition_number || '#' + r.id} — ${r.title}</option>`).join('')}
        </select>
      </div>
    </div>
    ${procFilterBarHtml({ searchId: 'rfq-search', searchPlaceholder: 'Search RFQ #, title, requisition…', statusId: 'rfq-status-filter', statusOptions: ['draft', 'sent', 'closed'], clearId: 'rfq-clear' })}
    <div class="card" style="padding:0">
      <table class="tbl" id="rfq-table">
        <thead><tr><th data-sort-key="rfq_number">RFQ #</th><th data-sort-key="title">Title</th><th>Requisition</th><th data-sort-key="status">Status</th><th data-sort-key="due_date">Due Date</th><th></th></tr></thead>
        <tbody id="rfq-tbody"></tbody>
      </table>
    </div>`;

  renderRows(allRows);
  wireSortableTable($('rfq-table'), sortState, currentFiltered, renderRows);
  $('rfq-search').oninput = (e) => { filters.search = e.target.value; renderRows(currentFiltered()); };
  $('rfq-status-filter').onchange = (e) => { filters.status = e.target.value; renderRows(currentFiltered()); };
  $('rfq-clear').onclick = () => { filters = { search: '', status: '' }; $('rfq-search').value = ''; $('rfq-status-filter').value = ''; renderRows(allRows); };
  $('rfq-export').onclick = () => _procExportExcel('rfqs', {});

  $('rfq-new-req').onchange = (e) => {
    const reqId = Number(e.target.value);
    if (!reqId) return;
    e.target.value = '';
    openRfqCreateOverlay(reqId);
  };
}

// ── Purchase Orders / Goods Receipt ──────────────────────────────────────────

async function openGoodsReceiptCreateOverlay(poId) {
  const res = await UFCL.procurementPoDetail(STORAGE.user.id, poId);
  if (!res.ok) { showToast(res.error, 'error'); return; }
  const { po, items } = res;
  const blacklisted = !!po.supplier_blacklisted;
  const state = {};
  items.forEach((it) => { state[it.id] = { received: '', rejected: '0', reason: '' }; });

  function rowsHtml() {
    return items.map((it) => `
      <div class="frow gr-row" data-id="${it.id}" style="align-items:flex-end">
        <div class="fg" style="flex:2"><label>${it.description} (ordered ${it.quantity})</label></div>
        <div class="fg" style="flex:1"><label>Received</label><input class="gr-recv" type="number" min="0" value="${state[it.id].received}" ${blacklisted ? 'disabled' : ''}></div>
        <div class="fg" style="flex:1"><label>Rejected</label><input class="gr-rej" type="number" min="0" value="${state[it.id].rejected}" ${blacklisted ? 'disabled' : ''}></div>
        <div class="fg" style="flex:2"><label>Rejection reason</label><input class="gr-reason" type="text" value="${state[it.id].reason}" ${blacklisted ? 'disabled' : ''}></div>
      </div>`).join('');
  }

  openOverlay('Record Goods Receipt', po.supplier_name, `
    ${blacklisted ? `<div class="lerr" style="display:block"><i class="ti ti-alert-triangle"></i> This supplier is blacklisted and cannot participate in procurement.</div>` : ''}
    <div id="gr-items">${rowsHtml()}</div>
    <div class="fg"><label>Notes</label><input id="gr-notes" type="text" placeholder="Condition notes, delivery reference, etc." ${blacklisted ? 'disabled' : ''}></div>
    <div class="brow"><button class="bp1" id="ovSave" ${blacklisted ? 'disabled' : ''}><i class="ti ti-check"></i>Record Receipt</button><button class="bs1" id="ovCancel">Cancel</button></div>
  `, async () => {
    if (blacklisted) { showOverlayError('This supplier is blacklisted and cannot participate in procurement.'); return; }
    document.querySelectorAll('.gr-row').forEach((row) => {
      const id = Number(row.dataset.id);
      state[id].received = row.querySelector('.gr-recv').value;
      state[id].rejected = row.querySelector('.gr-rej').value;
      state[id].reason   = row.querySelector('.gr-reason').value;
    });
    const payloadItems = items
      .map((it) => ({
        po_item_id: it.id,
        quantity_received: Number(state[it.id].received) || 0,
        quantity_rejected: Number(state[it.id].rejected) || 0,
        rejection_reason: state[it.id].reason.trim() || undefined,
      }))
      .filter((x) => x.quantity_received > 0 || x.quantity_rejected > 0);
    if (!payloadItems.length) { showOverlayError('Enter received or rejected quantity for at least one item.'); return; }
    const res2 = await UFCL.procurementGoodsReceiptCreate(STORAGE.user.id, poId, { items: payloadItems, notes: $('gr-notes').value.trim() || undefined });
    if (!res2.ok) { showOverlayError(res2.error); return; }
    closeOverlay();
    showToast('Goods receipt recorded.');
    // Navigation-consistency fix (Phase 2A): open the new receipt's detail
    // view directly instead of returning to the list. No detail view existed
    // for goods receipts before this phase — see openGoodsReceiptDetailOverlay,
    // which is pure UI wired to the existing procurementGoodsReceiptDetail
    // backend function (no new business logic).
    await showPage('procurement-goods-receipt');
    if (res2.id) openGoodsReceiptDetailOverlay(res2.id);
  });
}

async function openGoodsReceiptDetailOverlay(id) {
  const res = await UFCL.procurementGoodsReceiptDetail(STORAGE.user.id, id);
  if (!res.ok) { showToast(res.error, 'error'); return; }
  const { receipt: r, items } = res;
  const qcBadge = (s) => ({
    not_required: '',
    pending_qc:   '<span class="badge bp" style="font-size:10px">Pending Pole QC</span>',
    inspected:    '<span class="badge bg" style="font-size:10px">Pole QC Complete</span>',
  }[s] || '');
  openOverlay(`Goods Receipt ${r.receipt_number || '#' + r.id}`, r.po_number, `
    <div style="margin-bottom:.75rem">${procStatusBadge(r.status)} <span style="font-size:12px;color:var(--t3)">Received ${new Date(r.received_at).toLocaleString()}</span></div>
    <div class="tw"><table class="dt"><thead><tr><th>Description</th><th>Received</th><th>Rejected</th><th>Rejection Reason</th><th>Quality Status</th></tr></thead>
    <tbody>${items.map((it) => `<tr>
      <td>${it.description || '—'}</td>
      <td style="font-family:var(--fm)">${it.quantity_received}</td>
      <td style="font-family:var(--fm);${Number(it.quantity_rejected) > 0 ? 'color:var(--red)' : ''}">${it.quantity_rejected}</td>
      <td style="font-size:12px;color:var(--t3)">${it.rejection_reason || '—'}</td>
      <td>${qcBadge(it.qc_status)}</td>
    </tr>`).join('')}</tbody></table></div>
    ${items.some(it => it.qc_status === 'pending_qc') ? `<p style="font-size:11px;color:var(--t3);margin-top:.5rem"><i class="ti ti-info-circle"></i> Pole line(s) on this receipt are held pending Quality Inspection — see "Purchased Finished Pole QC" on the Daily Poles page. They will not appear in sellable stock until inspected.</p>` : ''}
    ${r.notes ? `<div class="section-hdr"><h4><i class="ti ti-note"></i>Notes</h4></div><p style="font-size:13px;color:var(--t2)">${r.notes}</p>` : ''}
    <div class="brow" style="margin-top:1rem"><button class="bs1" id="ovCancel">Close</button></div>
  `, null);
}

async function openInvoiceCreateOverlay(po) {
  const blacklisted = !!po.supplier_blacklisted;
  openOverlay('Raise Invoice', po.po_number, `
    ${blacklisted ? `<div class="lerr" style="display:block"><i class="ti ti-alert-triangle"></i> This supplier is blacklisted and cannot participate in procurement.</div>` : ''}
    <div class="fg"><label>Invoice Number *</label><input id="inv-num" type="text" ${blacklisted ? 'disabled' : ''}></div>
    <div class="frow">
      <div class="fg"><label>Invoice Date</label><input id="inv-date" type="date" ${blacklisted ? 'disabled' : ''}></div>
      <div class="fg"><label>Amount</label><input id="inv-amount" type="number" min="0" value="${(Number(po.total_amount) + Number(po.tax_amount)).toFixed(2)}" ${blacklisted ? 'disabled' : ''}></div>
    </div>
    <div class="brow"><button class="bp1" id="ovSave" ${blacklisted ? 'disabled' : ''}><i class="ti ti-check"></i>Create Invoice</button><button class="bs1" id="ovCancel">Cancel</button></div>
  `, async () => {
    if (blacklisted) { showOverlayError('This supplier is blacklisted and cannot participate in procurement.'); return; }
    const num = $('inv-num').value.trim();
    if (!num) { showOverlayError('Invoice number is required.'); return; }
    const res2 = await UFCL.procurementInvoiceCreate(STORAGE.user.id, po.id, {
      invoice_number: num, invoice_date: $('inv-date').value || undefined, invoice_amount: Number($('inv-amount').value) || 0,
    });
    if (!res2.ok) { showOverlayError(res2.error); return; }
    closeOverlay();
    showToast('Invoice created.');
    // Navigation-consistency fix (Phase 2A): open the new invoice's detail
    // view directly instead of returning to the list.
    await showPage('procurement-invoices');
    if (res2.id) openInvoiceDetailOverlay(res2.id);
  });
}

async function openPoDetailOverlay(id, onDone) {
  const res = await UFCL.procurementPoDetail(STORAGE.user.id, id);
  if (!res.ok) { showToast(res.error, 'error'); return; }
  const { po, items, fulfillment, steps } = res;
  const canReceive = ['issued', 'acknowledged', 'partially_received'].includes(po.status);
  const canInvoice = po.status === 'received';
  // Procurement Exception Management Phase 3 — "Waiting for Delivery" (still
  // partially_received, nobody has said the supplier won't finish) vs
  // "Supplier Will Not Deliver" (a shortage closure has been requested or
  // finalized) — distinguished via status/badge language, not a new visual
  // language.
  const canCloseShortage = po.status === 'partially_received' && fulfillment.outstandingQty > 0;
  const currentStep = (steps || []).find((s) => s.status === 'pending');
  const canAct = po.status === 'shortage_pending_approval' && !!currentStep && (currentStep.assigned_role === STORAGE.user.role || STORAGE.user.role === 'admin');
  // Stabilization Phase 5 (F-2) — procurementPoUpdate had full backend/IPC
  // readiness but no "Edit PO" UI anywhere; scoped to the 3 fields the
  // function actually allows (delivery date/terms/tax), matching its own
  // role gate exactly (not reusing a broader desktop permission).
  const canEditPo = ['admin', 'ceo', 'procurement-officer', 'procurement-manager'].includes(STORAGE.user.role);

  openOverlay(`Purchase Order ${po.po_number || '#' + po.id}`, po.supplier_name, `
    <div style="margin-bottom:.75rem">${procStatusBadge(po.status)}</div>
    ${po.supplier_blacklisted ? `<div class="lerr" style="display:block"><i class="ti ti-alert-triangle"></i> This supplier is blacklisted and cannot participate in further procurement — goods receipt and invoicing are disabled.</div>` : ''}
    <div class="card" style="padding:12px 14px;margin-bottom:.75rem;background:var(--bg2)">
      <div class="frow" style="flex-wrap:wrap;gap:1.25rem;font-size:13px">
        <div><strong>Ordered</strong><br>${fulfillment.ordered}</div>
        <div><strong>Received</strong><br>${fulfillment.received}</div>
        <div><strong>Outstanding</strong><br><span style="${fulfillment.outstandingQty>0?'color:var(--red);font-weight:600':''}">${fulfillment.outstandingQty}</span></div>
        <div><strong>Fulfillment</strong><br>${fulfillment.fulfillmentPct}%</div>
      </div>
      ${fulfillment.outstandingQty > 0 && po.status === 'partially_received' ? `<div style="margin-top:8px;font-size:12px;color:var(--amber)"><i class="ti ti-clock"></i> Waiting for delivery — ${fulfillment.outstandingQty} unit(s) still expected.</div>` : ''}
      ${['shortage_pending_approval', 'closed_with_shortage'].includes(po.status) ? `<div style="margin-top:8px;font-size:12px;color:var(--red)"><i class="ti ti-truck-off"></i> Supplier will not deliver the remainder.</div>` : ''}
    </div>
    <div class="tw"><table class="dt"><thead><tr><th>Description</th><th>Qty</th><th>Unit Price</th><th>Tax %</th></tr></thead>
    <tbody>${items.map((it) => `<tr><td>${it.description}</td><td>${it.quantity}</td><td>${Number(it.unit_price).toLocaleString()}</td><td>${it.tax_rate || 0}</td></tr>`).join('')}</tbody></table></div>
    ${po.shortage_reason ? `
      <div class="section-hdr"><h4><i class="ti ti-alert-triangle"></i>Shortage Information</h4></div>
      <div class="card" style="padding:12px 14px;margin-bottom:.75rem;background:var(--bg2)">
        <div style="font-size:13px"><strong>Reason:</strong> ${po.shortage_reason}</div>
        ${po.shortage_supplier_explanation ? `<div style="font-size:13px;margin-top:4px"><strong>Supplier Explanation:</strong> ${po.shortage_supplier_explanation}</div>` : ''}
        <div style="font-size:12px;color:var(--t3);margin-top:6px">Requested ${po.shortage_requested_at ? new Date(po.shortage_requested_at).toLocaleString() : '—'}${po.shortage_closed_at ? ' · Closed ' + new Date(po.shortage_closed_at).toLocaleString() : ''}</div>
      </div>` : ''}
    ${steps && steps.length ? `
      <div class="section-hdr"><h4><i class="ti ti-timeline"></i>Shortage Approval Timeline</h4></div>
      ${procApprovalStepsHtml(steps)}` : ''}
    ${canAct ? `
      <div style="margin-top:1rem">
        <div class="fg"><label>Notes</label><input id="po-dec-notes" type="text" placeholder="Optional"></div>
        <div class="brow">
          <button class="bp1" id="po-approve-btn" style="background:var(--green)"><i class="ti ti-check"></i>Approve (${PROC_STAGE_LABEL[currentStep.stage_key] || currentStep.stage_key})</button>
          <button class="bs1" id="po-reject-btn" style="color:var(--red)"><i class="ti ti-x"></i>Reject</button>
        </div>
      </div>` : ''}
    <div class="brow" style="margin-top:1rem">
      <button class="bp1" id="po-pdf-btn"><i class="ti ti-file-download"></i>Download PDF</button>
      ${canEditPo ? '<button class="bs1" id="po-edit-btn"><i class="ti ti-edit"></i>Edit</button>' : ''}
      ${canReceive ? '<button class="bp1" id="po-receive-btn"><i class="ti ti-package"></i>Record Goods Receipt</button>' : ''}
      ${canInvoice ? '<button class="bp1" id="po-invoice-btn"><i class="ti ti-receipt"></i>Raise Invoice</button>' : ''}
      ${canCloseShortage ? '<button class="bs1" id="po-close-shortage-btn" style="color:var(--red)"><i class="ti ti-alert-triangle"></i>Close with Shortage</button>' : ''}
      <button class="bs1" id="ovCancel">Close</button>
    </div>
  `, null);

  $('po-pdf-btn').onclick = async () => {
    const htmlRes = await UFCL.procurementPoPdfHtml(STORAGE.user.id, po.id);
    if (!htmlRes.ok) { showToast(htmlRes.error, 'error'); return; }
    const printRes = await UFCL.procurementPoPrint(htmlRes.html, `${po.po_number || 'PO_' + po.id}.pdf`);
    if (printRes.ok) showToast(`Saved: ${printRes.filePath}`);
    else if (printRes.error !== 'Save cancelled') showToast(printRes.error || 'PDF export failed', 'error');
  };
  const editBtn = $('po-edit-btn');
  if (editBtn) editBtn.onclick = () => { closeOverlay(); openPoEditOverlay(po, onDone); };
  const recvBtn = $('po-receive-btn');
  if (recvBtn) recvBtn.onclick = () => { closeOverlay(); openGoodsReceiptCreateOverlay(po.id); };
  const invBtn = $('po-invoice-btn');
  if (invBtn) invBtn.onclick = () => { closeOverlay(); openInvoiceCreateOverlay(po); };

  const closeShortageBtn = $('po-close-shortage-btn');
  if (closeShortageBtn) closeShortageBtn.onclick = () => {
    openOverlay('Close With Shortage', `PO ${po.po_number || '#' + po.id}`, `
      <div class="fg" style="color:var(--red);font-size:12px">This finalizes delivery for this order — ${fulfillment.outstandingQty} unit(s) will be recorded as never delivered, pending approval. Goods Receipt records are never modified.</div>
      <div class="fg"><label>Business Reason *</label><input id="po-shortage-reason" type="text" placeholder="e.g. Supplier confirmed remaining stock is unavailable"></div>
      <div class="fg"><label>Supplier Explanation</label><input id="po-shortage-supplier-exp" type="text" placeholder="Optional — what the supplier said"></div>
      <div class="brow"><button class="bp1" id="ovSave" style="background:var(--red)"><i class="ti ti-alert-triangle"></i>Request Closure</button><button class="bs1" id="ovCancel">Cancel</button></div>
    `, async () => {
      const reason = $('po-shortage-reason').value.trim();
      if (!reason) { showOverlayError('A business reason is required.'); return; }
      const supplierExplanation = $('po-shortage-supplier-exp').value.trim();
      const r2 = await UFCL.procurementPoCloseWithShortage(STORAGE.user.id, po.id, reason, supplierExplanation);
      if (!r2.ok) { showOverlayError(r2.error); return; }
      showToast(`Shortage closure requested — ${r2.stages.join(' → ')} approval pending.`);
      closeOverlay();
      openPoDetailOverlay(po.id, onDone);
    });
  };

  if (canAct) {
    $('po-approve-btn').onclick = async () => {
      const r2 = await UFCL.procurementPoApprove(STORAGE.user.id, po.id, 'approved', $('po-dec-notes').value.trim() || null);
      if (!r2.ok) { showOverlayError(r2.error); return; }
      closeOverlay(); onDone?.();
    };
    $('po-reject-btn').onclick = async () => {
      const r2 = await UFCL.procurementPoApprove(STORAGE.user.id, po.id, 'rejected', $('po-dec-notes').value.trim() || null);
      if (!r2.ok) { showOverlayError(r2.error); return; }
      closeOverlay(); onDone?.();
    };
  }
}

// Stabilization Phase 5 (F-2) — procurementPoUpdate had full backend/IPC
// readiness (procurementPoUpdate/data.js:15683) with zero UI caller on
// either platform; scoped to exactly the 3 fields the function allows
// (expected delivery date, terms, tax amount) — no line items, quantities,
// or supplier can be changed here, matching the backend exactly. Desktop
// only, per the audit's own recommendation (narrow administrative-correction
// field set, not warranting new mobile screens/routes).
function openPoEditOverlay(po, onDone) {
  const dateVal = po.expected_delivery_date ? new Date(po.expected_delivery_date).toISOString().slice(0, 10) : '';
  openOverlay('Edit Purchase Order', po.po_number || `#${po.id}`, `
    <div class="fg"><label>Expected Delivery Date</label><input id="po-e-date" type="date" value="${dateVal}"></div>
    <div class="fg"><label>Terms</label><input id="po-e-terms" type="text" value="${(po.terms || '').replace(/"/g, '&quot;')}" placeholder="Payment/delivery terms"></div>
    <div class="fg"><label>Tax Amount</label><input id="po-e-tax" type="number" min="0" step="0.01" value="${po.tax_amount ?? 0}"></div>
    <div class="brow"><button class="bp1" id="ovSave"><i class="ti ti-check"></i>Save</button><button class="bs1" id="ovCancel">Cancel</button></div>`,
    async () => {
      const res2 = await UFCL.procurementPoUpdate(STORAGE.user.id, po.id, {
        expected_delivery_date: $('po-e-date').value || null,
        terms: $('po-e-terms').value.trim() || null,
        tax_amount: Number($('po-e-tax').value || 0),
      });
      if (!res2.ok) { showOverlayError(res2.error); return; }
      showOverlaySuccess('Purchase order updated.');
      openPoDetailOverlay(po.id, onDone);
    });
}

// Phase 5B — one-shot preset consumed by renderProcurementOrders() the next
// time it renders, then cleared. Lets the Budget & Spend report's Workshop
// Analysis table drill into the existing Orders list without a new detail
// screen (per the approved design) or any change to PO business logic.
let _procOrdersPresetWorkshopId = null;
let _procOrdersPresetWorkshopName = null;
function drillIntoOrdersByWorkshop(workshopId, workshopName) {
  _procOrdersPresetWorkshopId = workshopId;
  _procOrdersPresetWorkshopName = workshopName;
  showPage('procurement-orders');
}

async function renderProcurementOrders() {
  const page = $('page-procurement-orders');
  page.innerHTML = `
    <div class="page-head"><div class="page-head-text">
      <div class="ptitle"><i class="ti ti-truck-delivery" style="color:var(--g-soft)"></i> Purchase Orders</div>
      <div class="psub">Purchase orders generated from approved requisitions and selected quotations.</div>
    </div></div>
    <div class="card" style="padding:0"><table class="tbl"><thead><tr><th>PO #</th><th>Supplier</th><th>Total</th><th>Status</th><th>Expected Delivery</th><th></th></tr></thead>
    <tbody>${skeletonTableRows(6)}</tbody></table></div>`;

  const res = await UFCL.procurementPoList(STORAGE.user.id, {});
  if (!res.ok) return renderDenied('procurement-orders', res.error);
  const allRows = (res.rows || []).map((po) => ({ ...po, total_with_tax: Number(po.total_amount) + Number(po.tax_amount) }));
  // Enterprise UI/UX Standardization Phase 2 — KPI strip, computed client-side
  // from the already-fetched allRows, no new backend query needed.
  const poOpen = allRows.filter((po) => ['issued', 'acknowledged', 'partially_received'].includes(po.status)).length;
  const poShortagePending = allRows.filter((po) => po.status === 'shortage_pending_approval').length;
  const poClosedShortage = allRows.filter((po) => po.status === 'closed_with_shortage').length;
  const poCompleted = allRows.filter((po) => ['received', 'closed'].includes(po.status)).length;
  const sortState = { key: null, dir: 'asc' };
  let filters = { search: '', status: '', workshopId: null };
  let presetWorkshopName = null;
  if (_procOrdersPresetWorkshopId !== null) {
    filters.workshopId = _procOrdersPresetWorkshopId;
    presetWorkshopName = _procOrdersPresetWorkshopName;
    _procOrdersPresetWorkshopId = null;
    _procOrdersPresetWorkshopName = null;
  }

  function rowHtml(po) {
    return `<tr>
      <td style="font-family:var(--fm)">${po.po_number || '#' + po.id}</td>
      <td>${po.supplier_name}</td>
      <td style="font-family:var(--fm)">${po.total_with_tax.toLocaleString()}</td>
      <td>${procStatusBadge(po.status)}</td>
      <td style="font-size:12px">${po.expected_delivery_date ? new Date(po.expected_delivery_date).toLocaleDateString() : '—'}</td>
      <td class="row-actions"><button class="bs1 po-view" data-id="${po.id}" style="font-size:12px"><i class="ti ti-eye"></i>View</button></td>
    </tr>`;
  }
  function renderRows(rows) {
    $('po-tbody').innerHTML = rows.length ? rows.map(rowHtml).join('') : `<tr><td colspan="6" style="text-align:center;color:var(--t3);padding:3rem">No purchase orders match your filters.</td></tr>`;
    document.querySelectorAll('.po-view').forEach((btn) => btn.onclick = () => openPoDetailOverlay(Number(btn.dataset.id), renderProcurementOrders));
  }
  function currentFiltered() {
    let out = applyProcListFilters(allRows, { search: filters.search, searchFields: ['po_number', 'supplier_name'], status: filters.status });
    if (filters.workshopId !== null) out = out.filter((po) => po.workshop_id === filters.workshopId);
    return out;
  }

  page.innerHTML = `
    <div class="page-head">
      <div class="page-head-text">
        <div class="ptitle"><i class="ti ti-truck-delivery" style="color:var(--g-soft)"></i> Purchase Orders</div>
        <div class="psub">Purchase orders generated from approved requisitions and selected quotations.</div>
      </div>
      <div class="toolbar"><button class="bs1" id="po-export"><i class="ti ti-file-spreadsheet"></i>Export Excel</button></div>
    </div>
    <div class="cards" style="margin-bottom:1.25rem">
      ${kpiTileHtml({ label: 'Total', value: allRows.length, sub: '<i class="ti ti-truck-delivery"></i>all purchase orders', subCls: 'cg' })}
      ${kpiTileHtml({ label: 'Open', value: poOpen, sub: '<i class="ti ti-clock"></i>issued/acknowledged/partial', subCls: 'bp' })}
      ${kpiTileHtml({ label: 'Shortage Pending Approval', value: poShortagePending, valueColor: poShortagePending > 0 ? 'var(--amber)' : '', sub: '<i class="ti ti-clock"></i>closure requested', subCls: poShortagePending > 0 ? 'ca' : 'cg' })}
      ${kpiTileHtml({ label: 'Closed with Shortage', value: poClosedShortage, valueColor: poClosedShortage > 0 ? 'var(--red)' : '', sub: '<i class="ti ti-alert-triangle"></i>never fully delivered', subCls: poClosedShortage > 0 ? 'cr' : '' })}
      ${kpiTileHtml({ label: 'Completed', value: poCompleted, valueColor: 'var(--green)', sub: '<i class="ti ti-circle-check"></i>received/closed', subCls: 'cg' })}
    </div>
    ${presetWorkshopName ? alertHtml('info', `Filtered to workshop: <strong>${presetWorkshopName}</strong> — <a href="#" id="po-clear-workshop">clear</a>`) : ''}
    ${procFilterBarHtml({ searchId: 'po-search', searchPlaceholder: 'Search PO #, supplier…', statusId: 'po-status-filter', statusOptions: ['issued', 'acknowledged', 'partially_received', 'shortage_pending_approval', 'closed_with_shortage', 'received', 'closed', 'cancelled'], clearId: 'po-clear' })}
    <div class="card" style="padding:0">
      <table class="tbl" id="po-table">
        <thead><tr><th data-sort-key="po_number">PO #</th><th data-sort-key="supplier_name">Supplier</th><th data-sort-key="total_with_tax">Total</th><th data-sort-key="status">Status</th><th data-sort-key="expected_delivery_date">Expected Delivery</th><th></th></tr></thead>
        <tbody id="po-tbody"></tbody>
      </table>
    </div>`;

  renderRows(currentFiltered());
  wireSortableTable($('po-table'), sortState, currentFiltered, renderRows);
  $('po-search').oninput = (e) => { filters.search = e.target.value; renderRows(currentFiltered()); };
  $('po-status-filter').onchange = (e) => { filters.status = e.target.value; renderRows(currentFiltered()); };
  const clearWorkshopLink = $('po-clear-workshop');
  if (clearWorkshopLink) clearWorkshopLink.onclick = (e) => { e.preventDefault(); filters.workshopId = null; renderRows(currentFiltered()); e.target.closest('.ent-alert').style.display = 'none'; };
  $('po-clear').onclick = () => { filters = { search: '', status: '', workshopId: null }; $('po-search').value = ''; $('po-status-filter').value = ''; const b = document.querySelector('.ent-alert'); if (b) b.style.display = 'none'; renderRows(allRows); };
  $('po-export').onclick = () => _procExportExcel('purchase-orders', { status: filters.status || undefined });
}

async function renderProcurementGoodsReceipt() {
  const page = $('page-procurement-goods-receipt');
  page.innerHTML = `
    <div class="page-head"><div class="page-head-text">
      <div class="ptitle"><i class="ti ti-package-import" style="color:var(--g-soft)"></i> Goods Receipt</div>
      <div class="psub">Confirm delivered quantities against purchase orders — inventory updates automatically.</div>
    </div></div>
    <div class="card" style="padding:0"><table class="tbl"><thead><tr><th>Receipt #</th><th>PO #</th><th>Supplier</th><th>Received By</th><th>Status</th><th>Date</th><th></th></tr></thead>
    <tbody>${skeletonTableRows(7)}</tbody></table></div>`;

  const [res, poRes] = await Promise.all([
    UFCL.procurementGoodsReceiptList(STORAGE.user.id),
    UFCL.procurementPoList(STORAGE.user.id, {}),
  ]);
  if (!res.ok) return renderDenied('procurement-goods-receipt', res.error);
  const allRows = res.rows || [];
  const receivablePos = (poRes.ok ? poRes.rows : []).filter((po) => ['issued', 'acknowledged', 'partially_received'].includes(po.status));
  const sortState = { key: null, dir: 'asc' };
  let filters = { search: '', status: '' };

  // Enterprise UI/UX Standardization Phase 2 — KPI strip, computed client-side
  // from the already-fetched allRows/receivablePos, no new backend query needed.
  const grPartial = allRows.filter((r) => r.status === 'partial').length;
  const grComplete = allRows.filter((r) => r.status === 'complete').length;
  const grRejected = allRows.filter((r) => r.status === 'rejected').length;

  function rowHtml(r) {
    return `<tr>
      <td style="font-family:var(--fm)">${r.receipt_number || '#' + r.id}</td>
      <td>${r.po_number}</td>
      <td>${r.supplier_name}</td>
      <td style="font-size:12px">${r.received_by_name || '—'}</td>
      <td>${procStatusBadge(r.status)}</td>
      <td style="font-size:12px">${new Date(r.received_at).toLocaleDateString()}</td>
      <td class="row-actions"><button class="bs1 gr-view" data-id="${r.id}" style="font-size:12px"><i class="ti ti-eye"></i>View</button></td>
    </tr>`;
  }
  function renderRows(rows) {
    $('gr-tbody').innerHTML = rows.length ? rows.map(rowHtml).join('') : `<tr><td colspan="7" style="text-align:center;color:var(--t3);padding:3rem">No goods receipts match your filters.</td></tr>`;
    document.querySelectorAll('.gr-view').forEach((btn) => btn.onclick = () => openGoodsReceiptDetailOverlay(Number(btn.dataset.id)));
  }
  function currentFiltered() {
    return applyProcListFilters(allRows, { search: filters.search, searchFields: ['receipt_number', 'po_number', 'supplier_name'], status: filters.status });
  }

  page.innerHTML = `
    <div class="page-head">
      <div class="page-head-text">
        <div class="ptitle"><i class="ti ti-package-import" style="color:var(--g-soft)"></i> Goods Receipt</div>
        <div class="psub">Confirm delivered quantities against purchase orders — inventory updates automatically.</div>
      </div>
      <div class="toolbar">
        <button class="bs1" id="gr-export"><i class="ti ti-file-spreadsheet"></i>Export Excel</button>
        <select id="gr-new-po" class="filter-select">
          <option value="">— Record receipt for PO —</option>
          ${receivablePos.map((po) => `<option value="${po.id}">${po.po_number || '#' + po.id} — ${po.supplier_name}</option>`).join('')}
        </select>
      </div>
    </div>
    <div class="cards" style="margin-bottom:1.25rem">
      ${kpiTileHtml({ label: 'Total', value: allRows.length, sub: '<i class="ti ti-package-import"></i>all receipts', subCls: 'cg' })}
      ${kpiTileHtml({ label: 'Awaiting Receipt', value: receivablePos.length, sub: '<i class="ti ti-clock"></i>open purchase orders', subCls: 'bp' })}
      ${kpiTileHtml({ label: 'Partial', value: grPartial, valueColor: grPartial > 0 ? 'var(--amber)' : '', sub: '<i class="ti ti-package"></i>short-received', subCls: grPartial > 0 ? 'ca' : 'cg' })}
      ${kpiTileHtml({ label: 'Complete', value: grComplete, valueColor: 'var(--green)', sub: '<i class="ti ti-circle-check"></i>fully received', subCls: 'cg' })}
      ${kpiTileHtml({ label: 'Rejected', value: grRejected, valueColor: grRejected > 0 ? 'var(--red)' : '', sub: '<i class="ti ti-circle-x"></i>declined', subCls: grRejected > 0 ? 'cr' : '' })}
    </div>
    ${procFilterBarHtml({ searchId: 'gr-search', searchPlaceholder: 'Search receipt #, PO #, supplier…', statusId: 'gr-status-filter', statusOptions: ['partial', 'complete', 'rejected'], clearId: 'gr-clear' })}
    <div class="card" style="padding:0">
      <table class="tbl" id="gr-table">
        <thead><tr><th data-sort-key="receipt_number">Receipt #</th><th data-sort-key="po_number">PO #</th><th data-sort-key="supplier_name">Supplier</th><th>Received By</th><th data-sort-key="status">Status</th><th data-sort-key="received_at">Date</th><th></th></tr></thead>
        <tbody id="gr-tbody"></tbody>
      </table>
    </div>`;

  renderRows(allRows);
  wireSortableTable($('gr-table'), sortState, currentFiltered, renderRows);
  $('gr-search').oninput = (e) => { filters.search = e.target.value; renderRows(currentFiltered()); };
  $('gr-status-filter').onchange = (e) => { filters.status = e.target.value; renderRows(currentFiltered()); };
  $('gr-clear').onclick = () => { filters = { search: '', status: '' }; $('gr-search').value = ''; $('gr-status-filter').value = ''; renderRows(allRows); };
  $('gr-export').onclick = () => _procExportExcel('goods-receipts', {});

  $('gr-new-po').onchange = (e) => {
    const poId = Number(e.target.value);
    if (!poId) return;
    e.target.value = '';
    openGoodsReceiptCreateOverlay(poId);
  };
}

// ── Invoices & Payments ───────────────────────────────────────────────────────

async function openInvoiceDetailOverlay(id) {
  const [res, payRes] = await Promise.all([
    UFCL.procurementInvoiceList(STORAGE.user.id, {}),
    UFCL.procurementPaymentList(STORAGE.user.id),
  ]);
  if (!res.ok) { showToast(res.error, 'error'); return; }
  const inv = (res.rows || []).find((i) => Number(i.id) === Number(id));
  if (!inv) { showToast('Invoice not found.', 'error'); return; }
  const payment = (payRes.ok ? payRes.rows : []).find((p) => Number(p.invoice_id) === Number(id));

  const canMatch = inv.status === 'pending_match';
  const canDecide = ['matched', 'disputed'].includes(inv.status);
  const canPay = inv.status === 'approved' && !payment;
  const canApprovePayment = payment && payment.status === 'pending';

  openOverlay(`Invoice ${inv.invoice_number}`, inv.supplier_name, `
    <div style="margin-bottom:.75rem">${procStatusBadge(inv.status)}</div>
    <div class="fg"><label>Amount</label><div style="font-family:var(--fm);font-weight:600">${Number(inv.invoice_amount).toLocaleString()}</div></div>
    ${payment ? `<div class="fg"><label>Payment</label><div>${procStatusBadge(payment.status)} — ${Number(payment.amount).toLocaleString()}</div></div>` : ''}
    ${canDecide || canApprovePayment ? '<div class="fg"><label>Notes</label><input id="inv-notes" type="text" placeholder="Optional"></div>' : ''}
    <div class="brow" style="margin-top:1rem">
      ${canMatch ? '<button class="bp1" id="inv-match-btn"><i class="ti ti-scale"></i>Run 3-Way Match</button>' : ''}
      ${canDecide ? '<button class="bp1" id="inv-approve-btn" style="background:var(--green)"><i class="ti ti-check"></i>Approve</button><button class="bs1" id="inv-reject-btn" style="color:var(--red)"><i class="ti ti-x"></i>Reject</button>' : ''}
      ${canPay ? '<button class="bp1" id="inv-pay-btn"><i class="ti ti-cash"></i>Initiate Payment</button>' : ''}
      ${canApprovePayment ? '<button class="bp1" id="pay-approve-btn" style="background:var(--green)">Approve Payment</button><button class="bs1" id="pay-reject-btn" style="color:var(--red)">Reject Payment</button>' : ''}
      <button class="bs1" id="ovCancel">Close</button>
    </div>
  `, null);

  const matchBtn = $('inv-match-btn');
  if (matchBtn) matchBtn.onclick = async () => {
    const res2 = await UFCL.procurementInvoiceMatch(STORAGE.user.id, id);
    if (!res2.ok) { showOverlayError(res2.error); return; }
    closeOverlay();
    showToast(
      `${res2.matched ? 'Matched' : 'Variance detected'} — PO ${res2.poTotal.toLocaleString()} · Received ${res2.receivedValue.toLocaleString()} · Invoice ${res2.invoiceAmount.toLocaleString()} (${res2.variancePct.toFixed(1)}% variance)`,
      res2.matched ? 'success' : 'error'
    );
    if (CURRENT_PAGE === 'procurement-invoices') await renderProcurementInvoices();
    openInvoiceDetailOverlay(id);
  };
  const apprBtn = $('inv-approve-btn');
  if (apprBtn) apprBtn.onclick = async () => {
    const res2 = await UFCL.procurementInvoiceApprove(STORAGE.user.id, id, 'approved', $('inv-notes').value.trim() || null);
    if (!res2.ok) { showOverlayError(res2.error); return; }
    closeOverlay(); showToast('Invoice approved.'); await renderProcurementInvoices();
  };
  const rejBtn = $('inv-reject-btn');
  if (rejBtn) rejBtn.onclick = async () => {
    const res2 = await UFCL.procurementInvoiceApprove(STORAGE.user.id, id, 'rejected', $('inv-notes').value.trim() || null);
    if (!res2.ok) { showOverlayError(res2.error); return; }
    closeOverlay(); showToast('Invoice rejected.'); await renderProcurementInvoices();
  };
  const payBtn = $('inv-pay-btn');
  if (payBtn) payBtn.onclick = async () => {
    const res2 = await UFCL.procurementPaymentCreate(STORAGE.user.id, id, {});
    if (!res2.ok) { showOverlayError(res2.error); return; }
    closeOverlay(); showToast('Payment initiated.'); await renderProcurementInvoices();
  };
  const payApprBtn = $('pay-approve-btn');
  if (payApprBtn) payApprBtn.onclick = async () => {
    const res2 = await UFCL.procurementPaymentApprove(STORAGE.user.id, payment.id, 'approved', $('inv-notes').value.trim() || null);
    if (!res2.ok) { showOverlayError(res2.error); return; }
    closeOverlay(); showToast('Payment approved.'); await renderProcurementInvoices();
  };
  const payRejBtn = $('pay-reject-btn');
  if (payRejBtn) payRejBtn.onclick = async () => {
    const res2 = await UFCL.procurementPaymentApprove(STORAGE.user.id, payment.id, 'rejected', $('inv-notes').value.trim() || null);
    if (!res2.ok) { showOverlayError(res2.error); return; }
    closeOverlay(); showToast('Payment rejected.'); await renderProcurementInvoices();
  };
}

async function renderProcurementInvoices() {
  const page = $('page-procurement-invoices');
  page.innerHTML = `
    <div class="page-head"><div class="page-head-text">
      <div class="ptitle"><i class="ti ti-receipt" style="color:var(--g-soft)"></i> Invoices & Payments</div>
      <div class="psub">Match supplier invoices against purchase orders and goods receipts, then approve payment.</div>
    </div></div>
    <div class="card" style="padding:0"><table class="tbl"><thead><tr><th>Invoice #</th><th>Supplier</th><th>PO #</th><th>Amount</th><th>Status</th><th>Payment</th><th></th></tr></thead>
    <tbody>${skeletonTableRows(7)}</tbody></table></div>`;

  const [res, payRes] = await Promise.all([
    UFCL.procurementInvoiceList(STORAGE.user.id, {}),
    UFCL.procurementPaymentList(STORAGE.user.id),
  ]);
  if (!res.ok) return renderDenied('procurement-invoices', res.error);
  const payments = payRes.ok ? payRes.rows : [];
  const paymentByInvoice = new Map(payments.map((p) => [p.invoice_id, p]));
  const allRows = (res.rows || []).map((inv) => ({ ...inv, payment_status: paymentByInvoice.get(inv.id)?.status || '' }));
  const sortState = { key: null, dir: 'asc' };
  let filters = { search: '', status: '' };

  function rowHtml(inv) {
    return `<tr>
      <td style="font-family:var(--fm)">${inv.invoice_number}</td>
      <td>${inv.supplier_name}</td>
      <td>${inv.po_number}</td>
      <td style="font-family:var(--fm)">${Number(inv.invoice_amount).toLocaleString()}</td>
      <td>${procStatusBadge(inv.status)}</td>
      <td>${inv.payment_status ? procStatusBadge(inv.payment_status) : '—'}</td>
      <td class="row-actions"><button class="bs1 inv-view" data-id="${inv.id}" style="font-size:12px"><i class="ti ti-eye"></i>View</button></td>
    </tr>`;
  }
  function renderRows(rows) {
    $('inv-tbody').innerHTML = rows.length ? rows.map(rowHtml).join('') : `<tr><td colspan="7" style="text-align:center;color:var(--t3);padding:3rem">No invoices match your filters. Raise one from a received Purchase Order.</td></tr>`;
    document.querySelectorAll('.inv-view').forEach((btn) => btn.onclick = () => openInvoiceDetailOverlay(Number(btn.dataset.id)));
  }
  function currentFiltered() {
    return applyProcListFilters(allRows, { search: filters.search, searchFields: ['invoice_number', 'supplier_name', 'po_number'], status: filters.status });
  }

  page.innerHTML = `
    <div class="page-head">
      <div class="page-head-text">
        <div class="ptitle"><i class="ti ti-receipt" style="color:var(--g-soft)"></i> Invoices & Payments</div>
        <div class="psub">Match supplier invoices against purchase orders and goods receipts, then approve payment.</div>
      </div>
      <div class="toolbar"><button class="bs1" id="inv-export"><i class="ti ti-file-spreadsheet"></i>Export Excel</button></div>
    </div>
    ${procFilterBarHtml({ searchId: 'inv-search', searchPlaceholder: 'Search invoice #, supplier, PO #…', statusId: 'inv-status-filter', statusOptions: ['pending_match', 'matched', 'disputed', 'approved', 'rejected', 'paid'], clearId: 'inv-clear' })}
    <div class="card" style="padding:0">
      <table class="tbl" id="inv-table">
        <thead><tr><th data-sort-key="invoice_number">Invoice #</th><th data-sort-key="supplier_name">Supplier</th><th>PO #</th><th data-sort-key="invoice_amount">Amount</th><th data-sort-key="status">Status</th><th>Payment</th><th></th></tr></thead>
        <tbody id="inv-tbody"></tbody>
      </table>
    </div>`;

  renderRows(allRows);
  wireSortableTable($('inv-table'), sortState, currentFiltered, renderRows);
  $('inv-search').oninput = (e) => { filters.search = e.target.value; renderRows(currentFiltered()); };
  $('inv-status-filter').onchange = (e) => { filters.status = e.target.value; renderRows(currentFiltered()); };
  $('inv-clear').onclick = () => { filters = { search: '', status: '' }; $('inv-search').value = ''; $('inv-status-filter').value = ''; renderRows(allRows); };
  $('inv-export').onclick = () => _procExportExcel('invoices', { status: filters.status || undefined });
}

// ── Dashboard / Reports ───────────────────────────────────────────────────────

// Phase 3C — shared across the Dashboard, Supplier Profile, Comparison and
// Executive Reports so tier styling is defined exactly once.
function supplierTierBadge(tier) {
  const map = { 'Excellent': 'bg', 'Good': 'bb', 'Average': 'ba', 'High Risk': 'br' };
  const icon = { 'Excellent': 'ti-trophy', 'Good': 'ti-thumb-up', 'Average': 'ti-minus', 'High Risk': 'ti-alert-triangle' };
  return `<span class="badge ${map[tier] || 'bn'} badge-ic"><i class="ti ${icon[tier] || 'ti-help'}"></i>${tier}</span>`;
}
function spendTrendIcon(t) {
  if (t === 'up') return '<i class="ti ti-trending-up" style="color:var(--g-soft)" title="Spend trending up"></i>';
  if (t === 'down') return '<i class="ti ti-trending-down" style="color:var(--red)" title="Spend trending down"></i>';
  return '<i class="ti ti-minus" style="color:var(--t4)" title="Spend flat"></i>';
}

async function renderProcurementDashboard() {
  const page = $('page-procurement-dashboard');
  page.innerHTML = `
    <div class="page-head"><div class="page-head-text">
      <div class="ptitle"><i class="ti ti-shopping-bag" style="color:var(--g-soft)"></i> Procurement Dashboard</div>
      <div class="psub">End-to-end purchasing overview — requisitions, orders, receipts and invoices.</div>
    </div></div>
    <div class="cards" style="margin-bottom:1.25rem">${Array.from({ length: 4 }).map(() => `<div class="kpi-card"><div class="skel-row w-60"></div><div class="skel-row w-25" style="height:24px"></div></div>`).join('')}</div>
    <div class="cards" style="margin-bottom:1.25rem">${Array.from({ length: 8 }).map(() => `<div class="kpi-card"><div class="skel-row w-60"></div><div class="skel-row w-25" style="height:24px"></div></div>`).join('')}</div>`;

  const [res, intelRes, srmRes, execRes] = await Promise.all([
    UFCL.procurementDashboard(STORAGE.user.id),
    UFCL.supplierIntelligenceDashboard(STORAGE.user.id, {}),
    UFCL.srmDashboard(STORAGE.user.id),
    UFCL.procurementExecutiveDashboard(STORAGE.user.id),
  ]);
  if (!res.ok) return renderDenied('procurement-dashboard', res.error);
  const srm = srmRes.ok ? srmRes : null;
  const exec = execRes.ok ? execRes : null;

  // Phase C8 — this comment previously (incorrectly) claimed the backend
  // never persists the 'in_approval' status. Re-verified live this phase:
  // procurementApprovalAction's own "Phase 2B fix" already writes it
  // (ENTITY_MID_STATUS), confirmed against production data showing real
  // in_approval rows counted correctly here. The stale claim is removed —
  // this was master-register bookkeeping drift, not an active defect.
  const byStatus = (arr, key) => (arr || []).find((x) => x.status === key)?.n || 0;
  const pendingReq = byStatus(res.requisitionsByStatus, 'in_approval');
  const openPos = (res.posByStatus || []).filter((s) => ['issued', 'acknowledged', 'partially_received'].includes(s.status)).reduce((a, b) => a + b.n, 0);
  const pendingInv = (res.invoicesByStatus || []).filter((s) => ['pending_match', 'disputed'].includes(s.status)).reduce((a, b) => a + b.n, 0);

  const intel = intelRes.ok ? intelRes : null;
  const kpis = intel?.kpis || {};
  const topPerformers = intel?.topPerformers || [];
  const highRisk = intel?.highRiskSuppliers || [];
  const contractSummary = intel?.contractSummary || { active: 0, expiringSoon: 0, expired: 0 };
  const spendDist = intel?.spendDistribution || [];

  // Phase C8 — KPI tile drill-down (PR-20's Procurement instance). Live
  // permission audit found `procurement-dashboard` is held by many roles
  // (sales, finance, department heads, production leaders) that do NOT hold
  // the underlying list-page permissions (procurement-orders/invoices/
  // goods-receipt/suppliers are procurement-team-only) — this dashboard is
  // intentionally a broad visibility summary, not a gateway into
  // procurement's own restricted operational pages. So each tile is only
  // made clickable for a viewer who actually holds that target page's own
  // permission (STORAGE.pages, the same resolved-permission list
  // renderProcurementSuppliers already checks) — never unconditionally,
  // which would just be a wall of "Access Denied" clicks for most viewers.
  const _pages = STORAGE.pages || [];
  const dpAttr = (target) => _pages.includes(target) ? `data-page="${target}" style="cursor:pointer" title="View details"` : '';

  page.innerHTML = `
    <div class="page-head"><div class="page-head-text">
      <div class="ptitle"><i class="ti ti-shopping-bag" style="color:var(--g-soft)"></i> Procurement Dashboard</div>
      <div class="psub">End-to-end purchasing overview — requisitions, orders, receipts and invoices.</div>
    </div></div>
    <div class="cards" style="margin-bottom:1.25rem">
      <div class="kpi-card ${pendingReq > 0 ? 'kpi-amber' : ''}" ${dpAttr('procurement-requisitions')}><div class="kpi-lbl">Pending Approvals</div><div class="kpi-val">${pendingReq}</div><div class="kpi-sub"><i class="ti ti-clock"></i>requisitions</div></div>
      <div class="kpi-card kpi-blue" ${dpAttr('procurement-orders')}><div class="kpi-lbl">Open Purchase Orders</div><div class="kpi-val">${openPos}</div><div class="kpi-sub"><i class="ti ti-truck-delivery"></i>in progress</div></div>
      <div class="kpi-card ${pendingInv > 0 ? 'kpi-amber' : ''}" ${dpAttr('procurement-invoices')}><div class="kpi-lbl">Invoices to Review</div><div class="kpi-val">${pendingInv}</div><div class="kpi-sub"><i class="ti ti-receipt"></i>awaiting</div></div>
      <div class="kpi-card kpi-green" ${dpAttr('procurement-goods-receipt')}><div class="kpi-lbl">Receipts (7 days)</div><div class="kpi-val">${res.goodsReceiptsLast7Days || 0}</div><div class="kpi-sub"><i class="ti ti-package"></i>received</div></div>
    </div>

    <div class="brow" style="margin-bottom:1.25rem">
      <button class="bs1" id="qa-view-suppliers"><i class="ti ti-building-store"></i>View Suppliers</button>
      <button class="bs1" id="qa-view-contracts"><i class="ti ti-file-text"></i>Contract Register</button>
      <button class="bs1" id="qa-view-compliance"><i class="ti ti-shield-check"></i>Compliance Center</button>
    </div>

    <div class="section-hdr"><h4><i class="ti ti-brain"></i>Supplier Intelligence</h4></div>
    ${!intel ? alertHtml('critical', intelRes.error || 'Could not load supplier intelligence.') : `
    <div class="cards" style="margin-bottom:1.25rem">
      <div class="kpi-card" ${dpAttr('procurement-suppliers')}><div class="kpi-lbl">Total Suppliers</div><div class="kpi-val">${kpis.totalSuppliers || 0}</div><div class="kpi-sub"><i class="ti ti-building-store"></i>registered</div></div>
      <div class="kpi-card kpi-green" ${dpAttr('procurement-suppliers')}><div class="kpi-lbl">Active Suppliers</div><div class="kpi-val">${kpis.activeSuppliers || 0}</div><div class="kpi-sub"><i class="ti ti-circle-check"></i>ready to trade</div></div>
      <div class="kpi-card" ${dpAttr('procurement-suppliers')}><div class="kpi-lbl">Preferred Suppliers</div><div class="kpi-val">${kpis.preferredSuppliers || 0}</div><div class="kpi-sub"><i class="ti ti-star"></i>flagged preferred</div></div>
      <div class="kpi-card ${kpis.blacklistedSuppliers > 0 ? 'kpi-amber' : ''}" ${dpAttr('procurement-suppliers')}><div class="kpi-lbl">Blacklisted</div><div class="kpi-val" style="${kpis.blacklistedSuppliers > 0 ? 'color:var(--red)' : ''}">${kpis.blacklistedSuppliers || 0}</div><div class="kpi-sub"><i class="ti ti-ban"></i>cannot transact</div></div>
      <div class="kpi-card ${kpis.highRiskSuppliers > 0 ? 'kpi-amber' : ''}" ${dpAttr('procurement-suppliers')}><div class="kpi-lbl">High Risk Suppliers</div><div class="kpi-val" style="${kpis.highRiskSuppliers > 0 ? 'color:var(--red)' : ''}">${kpis.highRiskSuppliers || 0}</div><div class="kpi-sub"><i class="ti ti-alert-triangle"></i>need review</div></div>
      <div class="kpi-card ${kpis.contractsExpiring > 0 ? 'kpi-amber' : ''} kpi-contracts-link" style="cursor:pointer" title="View Contract Register"><div class="kpi-lbl">Contracts Expiring</div><div class="kpi-val">${kpis.contractsExpiring || 0}</div><div class="kpi-sub"><i class="ti ti-file-alert"></i>within 30 days</div></div>
      <div class="kpi-card kpi-blue"><div class="kpi-lbl">Total Procurement Spend</div><div class="kpi-val" style="font-size:19px">${Number(kpis.totalProcurementSpend || 0).toLocaleString()}</div><div class="kpi-sub"><i class="ti ti-cash"></i>all suppliers</div></div>
      <div class="kpi-card kpi-green"><div class="kpi-lbl">Average Supplier Score</div><div class="kpi-val">${kpis.averageSupplierScore || 0}</div><div class="kpi-sub"><i class="ti ti-gauge"></i>out of 100</div></div>
    </div>

    <div class="frow" style="align-items:flex-start;gap:1rem">
      <div style="flex:1;min-width:320px">
        <div class="section-hdr"><h4><i class="ti ti-trophy"></i>Top Performing Suppliers</h4></div>
        <div class="card" style="padding:0">
          <table class="tbl"><thead><tr><th>Supplier</th><th>Score</th><th>Rating</th><th>Trend</th><th>Spend</th></tr></thead>
          <tbody>${topPerformers.length ? topPerformers.map((s) => `
            <tr><td>${s.name}${s.preferred ? ' <i class="ti ti-star" style="color:var(--amber)"></i>' : ''}</td>
            <td style="font-family:var(--fm);font-weight:600">${s.score}</td><td>${supplierTierBadge(s.tier)}</td>
            <td style="text-align:center">${spendTrendIcon(s.spendTrend)}</td>
            <td style="font-family:var(--fm)">${Number(s.totalSpend).toLocaleString()}</td></tr>
          `).join('') : '<tr><td colspan="5" style="text-align:center;color:var(--t3);padding:2rem">No purchase history yet.</td></tr>'}</tbody></table>
        </div>
      </div>
      <div style="flex:1;min-width:320px">
        <div class="section-hdr"><h4><i class="ti ti-alert-triangle"></i>High Risk Suppliers</h4></div>
        <div class="card" style="padding:0">
          <table class="tbl"><thead><tr><th>Supplier</th><th>Score</th><th>Primary Issue</th><th>Recommended Action</th></tr></thead>
          <tbody>${highRisk.length ? highRisk.map((s) => `
            <tr><td>${s.name}</td><td style="font-family:var(--fm);color:var(--red);font-weight:600">${s.score}</td>
            <td style="font-size:12px">${s.primaryIssue}</td><td style="font-size:12px;color:var(--t3)">${s.recommendation}</td></tr>
          `).join('') : '<tr><td colspan="4" style="text-align:center;color:var(--t3);padding:2rem">No high-risk suppliers.</td></tr>'}</tbody></table>
        </div>
      </div>
    </div>

    <div class="frow" style="align-items:flex-start;gap:1rem;margin-top:1rem">
      <div style="flex:1;min-width:280px">
        <div class="section-hdr"><h4><i class="ti ti-file-text"></i>Contract Summary</h4></div>
        <div class="cards">
          <div class="mc"><div class="mclbl">Active</div><div class="mcval" style="color:var(--g-soft)">${contractSummary.active}</div></div>
          <div class="mc"><div class="mclbl">Expiring Soon</div><div class="mcval" style="color:var(--amber)">${contractSummary.expiringSoon}</div></div>
          <div class="mc"><div class="mclbl">Expired</div><div class="mcval" style="color:var(--red)">${contractSummary.expired}</div></div>
        </div>
      </div>
      <div style="flex:1;min-width:280px">
        <div class="section-hdr"><h4><i class="ti ti-chart-bar"></i>Spend Distribution (Top 8)</h4></div>
        <div class="card">
          ${_svgBar(spendDist, 'value', { h: 90, color: '#1D4ED8' })}
          <div style="display:flex;justify-content:space-between;margin-top:.4rem;font-size:10px;color:var(--t3)">
            ${spendDist.slice(0, 8).map((s) => `<span title="${s.name}: ${Number(s.value).toLocaleString()}">${s.name.length > 8 ? s.name.slice(0, 7) + '…' : s.name}</span>`).join('')}
          </div>
        </div>
      </div>
    </div>

    <div class="section-hdr"><h4><i class="ti ti-chart-line"></i>Procurement Spend Trend (6 months)</h4></div>
    <div class="card" style="margin-bottom:1.25rem">
      ${_svgLine(res.monthlySpend || [], 'total', { h: 90 })}
      <div style="display:flex;justify-content:space-between;margin-top:.4rem;font-size:10px;color:var(--t3)">
        ${(res.monthlySpend || []).map((m) => `<span>${m.month}</span>`).join('')}
      </div>
    </div>
    `}

    <div class="section-hdr"><h4><i class="ti ti-users-group"></i>Supplier Relationship Management</h4></div>
    ${!srm ? alertHtml('critical', srmRes.error || 'Could not load SRM overview.') : `
    <div class="cards" style="margin-bottom:1.25rem">
      <div class="kpi-card"><div class="kpi-lbl">Active Contracts</div><div class="kpi-val">${srm.kpis.activeContracts}</div><div class="kpi-sub"><i class="ti ti-file-text"></i>on file</div></div>
      <div class="kpi-card ${srm.kpis.expiringContracts > 0 ? 'kpi-amber' : ''}"><div class="kpi-lbl">Expiring Contracts</div><div class="kpi-val">${srm.kpis.expiringContracts}</div><div class="kpi-sub"><i class="ti ti-clock"></i>within 90 days</div></div>
      <div class="kpi-card ${srm.kpis.expiredContracts > 0 ? 'kpi-amber' : ''}"><div class="kpi-lbl">Expired Contracts</div><div class="kpi-val" style="${srm.kpis.expiredContracts > 0 ? 'color:var(--red)' : ''}">${srm.kpis.expiredContracts}</div><div class="kpi-sub"><i class="ti ti-file-alert"></i>need renewal</div></div>
      <div class="kpi-card ${srm.kpis.compliancePct < 80 ? 'kpi-amber' : 'kpi-green'}"><div class="kpi-lbl">Compliance</div><div class="kpi-val">${srm.kpis.compliancePct}%</div><div class="kpi-sub"><i class="ti ti-shield-check"></i>fleet-wide</div></div>
      <div class="kpi-card ${srm.kpis.missingDocuments > 0 ? 'kpi-amber' : ''}"><div class="kpi-lbl">Missing Documents</div><div class="kpi-val">${srm.kpis.missingDocuments}</div><div class="kpi-sub"><i class="ti ti-folder-x"></i>gaps</div></div>
      <div class="kpi-card"><div class="kpi-lbl">Open Improvement Plans</div><div class="kpi-val">${srm.kpis.openImprovementPlans}</div><div class="kpi-sub"><i class="ti ti-tool"></i>${srm.improvementProgress.avgCompletion}% avg complete</div></div>
    </div>`}

    <div class="section-hdr"><h4><i class="ti ti-chart-infographic"></i>Procurement Analytics</h4></div>
    ${!exec ? alertHtml('critical', execRes.error || 'Could not load procurement analytics.') : _procExecAnalyticsHtml(exec, srm?.contractTimeline || [])}

    <div class="section-hdr"><h4><i class="ti ti-activity"></i>Recent Activity</h4></div>
    <div class="card" style="padding:0">
      <table class="tbl"><thead><tr><th>Ref</th><th>Description</th><th>Status</th><th>Date</th></tr></thead>
      <tbody>${(res.recentActivity || []).length ? res.recentActivity.slice(0, 15).map((a) => `
        <tr><td style="font-family:var(--fm)">${a.ref || '—'}</td><td>${a.label}</td><td>${procStatusBadge(a.status)}</td><td style="font-size:12px;color:var(--t3)">${new Date(a.created_at).toLocaleString()}</td></tr>
      `).join('') : `<tr><td colspan="4" style="text-align:center;color:var(--t3);padding:2rem">No recent activity.</td></tr>`}</tbody></table>
    </div>`;

  $('qa-view-suppliers').onclick = () => showPage('procurement-suppliers');
  $('qa-view-contracts').onclick = () => openContractRegisterOverlay();
  $('qa-view-compliance').onclick = () => openComplianceCenterOverlay();

  // Phase C8 — KPI tile drill-down (PR-20's Procurement instance). Routes to
  // the existing page/overlay that already owns each figure's underlying
  // records; "Total Procurement Spend"/"Average Supplier Score" are
  // dimensionless and deliberately left non-interactive, matching this
  // app's own established precedent (CEO Overview, Inventory Dashboard,
  // Executive Dashboard) of not inventing a destination for those.
  page.querySelectorAll('[data-page]').forEach(el => { el.onclick = () => showPage(el.dataset.page); });
  page.querySelectorAll('.kpi-contracts-link').forEach(el => { el.onclick = () => openContractRegisterOverlay(); });
}

// Phase 5A — shared executive-analytics HTML, reused by both the Procurement
// Dashboard's "Procurement Analytics" section and the Procurement Reports
// "Analytics" tab, so the two surfaces never drift or duplicate this markup.
function _procExecAnalyticsHtml(exec, contractTimelineRows) {
  return `
    <div class="cards" style="margin-bottom:1.25rem">
      <div class="kpi-card kpi-blue"><div class="kpi-lbl">Total Procurement Spend</div><div class="kpi-val" style="font-size:18px">${_fmtCur(exec.kpis.totalSpend)}</div><div class="kpi-sub"><i class="ti ti-cash"></i>all time</div></div>
      <div class="kpi-card"><div class="kpi-lbl">Spend This Month</div><div class="kpi-val" style="font-size:17px">${_fmtCur(exec.kpis.spendThisMonth)}</div></div>
      <div class="kpi-card"><div class="kpi-lbl">Spend This Quarter</div><div class="kpi-val" style="font-size:17px">${_fmtCur(exec.kpis.spendThisQuarter)}</div></div>
      <div class="kpi-card"><div class="kpi-lbl">Spend This Year</div><div class="kpi-val" style="font-size:17px">${_fmtCur(exec.kpis.spendThisYear)}</div></div>
    </div>
    <div class="cards" style="margin-bottom:1.25rem">
      <div class="kpi-card kpi-green"><div class="kpi-lbl">Active Suppliers</div><div class="kpi-val">${exec.kpis.activeSuppliers}</div></div>
      <div class="kpi-card kpi-green"><div class="kpi-lbl">Active Contracts</div><div class="kpi-val">${exec.kpis.activeContracts}</div></div>
      <div class="kpi-card"><div class="kpi-lbl">Purchase Orders</div><div class="kpi-val">${_fmtN(exec.kpis.purchaseOrders)}</div></div>
      <div class="kpi-card"><div class="kpi-lbl">Goods Receipts</div><div class="kpi-val">${_fmtN(exec.kpis.goodsReceipts)}</div></div>
      <div class="kpi-card"><div class="kpi-lbl">Avg Procurement Cycle</div><div class="kpi-val">${exec.kpis.avgProcurementCycleDays}d</div><div class="kpi-sub"><i class="ti ti-clock"></i>requisition → PO</div></div>
      <div class="kpi-card"><div class="kpi-lbl">Avg Approval Time</div><div class="kpi-val">${exec.kpis.avgApprovalDays}d</div><div class="kpi-sub"><i class="ti ti-checklist"></i>per stage</div></div>
    </div>

    <div class="frow" style="align-items:flex-start;gap:1rem;margin-bottom:1.25rem">
      <div style="flex:1.4;min-width:300px">
        <div class="section-hdr"><h4><i class="ti ti-wallet"></i>Estimated Budget Utilization</h4></div>
        <div class="card">
          <div class="frow" style="gap:1.5rem;margin-bottom:.5rem">
            <div><div class="mclbl">Estimated Budget</div><div class="mcval" style="font-size:16px">${_fmtCur(exec.kpis.budgetUtilization.estimatedBudget)}</div></div>
            <div><div class="mclbl">Actual Spend</div><div class="mcval" style="font-size:16px">${_fmtCur(exec.kpis.budgetUtilization.actualSpend)}</div></div>
            <div><div class="mclbl">Variance</div><div class="mcval" style="font-size:16px;color:${exec.kpis.budgetUtilization.variance >= 0 ? 'var(--g-soft)' : 'var(--red)'}">${exec.kpis.budgetUtilization.variance >= 0 ? '+' : ''}${_fmtCur(exec.kpis.budgetUtilization.variance)}</div></div>
          </div>
          ${_pbar(exec.kpis.budgetUtilization.utilizationPct, exec.kpis.budgetUtilization.utilizationPct > 100 ? 'ex-pbar-red' : '')}
          <div style="font-size:11px;color:var(--t3);margin-top:.35rem">${exec.kpis.budgetUtilization.utilizationPct}% of estimated budget spent — sum of requisition estimates vs. actual PO totals (pre-tax)</div>
        </div>
      </div>
      <div style="flex:1;min-width:220px">
        <div class="section-hdr"><h4><i class="ti ti-target-arrow"></i>Planning Savings</h4></div>
        <div class="card" style="text-align:center">
          <div class="mcval" style="font-size:20px;color:${exec.kpis.planningSavings.total >= 0 ? 'var(--g-soft)' : 'var(--red)'}">${exec.kpis.planningSavings.total >= 0 ? '+' : ''}${_fmtCur(exec.kpis.planningSavings.total)}</div>
          <div style="font-size:11px;color:var(--t3);margin-top:.35rem">Estimated vs. actual cost across ${exec.kpis.planningSavings.matchedCount} completed purchase order${exec.kpis.planningSavings.matchedCount === 1 ? '' : 's'}</div>
        </div>
      </div>
      <div style="flex:1;min-width:220px">
        <div class="section-hdr"><h4><i class="ti ti-gavel"></i>Negotiation Savings</h4></div>
        <div class="card" style="text-align:center">
          <div class="mcval" style="font-size:20px;color:${exec.kpis.negotiationSavings.total >= 0 ? 'var(--g-soft)' : 'var(--red)'}">${exec.kpis.negotiationSavings.total >= 0 ? '+' : ''}${_fmtCur(exec.kpis.negotiationSavings.total)}</div>
          <div style="font-size:11px;color:var(--t3);margin-top:.35rem">Highest qualified quote vs. awarded quote across ${exec.kpis.negotiationSavings.rfqCount} competitive RFQ${exec.kpis.negotiationSavings.rfqCount === 1 ? '' : 's'}</div>
        </div>
      </div>
    </div>

    <div class="frow" style="align-items:flex-start;gap:1rem">
      <div style="flex:1;min-width:280px">
        <div class="section-hdr"><h4><i class="ti ti-chart-line"></i>Monthly Spend Trend (12 months)</h4></div>
        <div class="card">
          ${_svgLine(exec.charts.monthlySpendTrend, 'total', { h: 80 })}
          <div style="display:flex;justify-content:space-between;margin-top:.4rem;font-size:10px;color:var(--t3)">${_clabels(exec.charts.monthlySpendTrend, 'month', 6)}</div>
        </div>
      </div>
      <div style="flex:1;min-width:280px">
        <div class="section-hdr"><h4><i class="ti ti-chart-line"></i>Procurement Cycle Trend</h4></div>
        <div class="card">
          ${_svgLine(exec.charts.procurementCycleTrend, 'avgDays', { h: 80, color: '#1D4ED8' })}
          <div style="display:flex;justify-content:space-between;margin-top:.4rem;font-size:10px;color:var(--t3)">${_clabels(exec.charts.procurementCycleTrend, 'month', 6)}</div>
        </div>
      </div>
    </div>

    <div class="frow" style="align-items:flex-start;gap:1rem;margin-top:1rem">
      <div style="flex:1;min-width:260px">
        <div class="section-hdr"><h4><i class="ti ti-building-store"></i>Supplier Spend Distribution</h4></div>
        <div class="card">
          ${_svgBar(exec.charts.supplierSpendDistribution, 'value', { h: 80 })}
          <div style="display:flex;justify-content:space-between;margin-top:.4rem;font-size:10px;color:var(--t3)">
            ${exec.charts.supplierSpendDistribution.slice(0, 8).map((s) => `<span title="${s.name}: ${_fmtCur(s.value)}">${s.name.length > 8 ? s.name.slice(0, 7) + '…' : s.name}</span>`).join('')}
          </div>
        </div>
      </div>
      <div style="flex:1;min-width:260px">
        <div class="section-hdr"><h4><i class="ti ti-building"></i>Department Spend</h4></div>
        <div class="card">
          ${_svgBar(exec.charts.departmentSpend, 'total', { h: 80, color: '#7C3AED' })}
          <div style="display:flex;justify-content:space-between;margin-top:.4rem;font-size:10px;color:var(--t3)">
            ${exec.charts.departmentSpend.slice(0, 8).map((d) => `<span title="${d.department}: ${_fmtCur(d.total)}">${String(d.department).length > 8 ? String(d.department).slice(0, 7) + '…' : d.department}</span>`).join('')}
          </div>
        </div>
      </div>
      <div style="flex:1;min-width:260px">
        <div class="section-hdr"><h4><i class="ti ti-tools-kitchen-2"></i>Workshop Spend</h4></div>
        <div class="card">
          ${_svgBar(exec.charts.workshopSpend, 'total', { h: 80, color: '#EA580C' })}
          <div style="display:flex;justify-content:space-between;margin-top:.4rem;font-size:10px;color:var(--t3)">
            ${exec.charts.workshopSpend.slice(0, 8).map((w) => `<span title="${w.workshop}: ${_fmtCur(w.total)}">${String(w.workshop).length > 8 ? String(w.workshop).slice(0, 7) + '…' : w.workshop}</span>`).join('')}
          </div>
        </div>
      </div>
    </div>

    <div class="frow" style="align-items:flex-start;gap:1rem;margin-top:1rem">
      <div style="flex:1;min-width:260px">
        <div class="section-hdr"><h4><i class="ti ti-checklist"></i>Approval Timeline (avg days per stage)</h4></div>
        <div class="card">
          ${exec.charts.approvalTimeline.length ? _svgBar(exec.charts.approvalTimeline, 'avgDays', { h: 70, color: '#DC2626' }) : `<div style="height:70px;display:flex;align-items:center;justify-content:center;color:var(--t4);font-size:11px">No approved requisitions yet</div>`}
          <div style="display:flex;justify-content:space-between;margin-top:.4rem;font-size:10px;color:var(--t3)">
            ${exec.charts.approvalTimeline.map((a) => `<span title="${a.stage}: ${a.avgDays}d">${String(a.stage).replace('_', ' ')}</span>`).join('')}
          </div>
        </div>
      </div>
      <div style="flex:1;min-width:260px">
        <div class="section-hdr"><h4><i class="ti ti-file-alert"></i>Contract Expiry Timeline</h4></div>
        <div class="card">
          ${contractTimelineRows.length ? _svgDualBar(contractTimelineRows, 'expiring', 'expired', { h: 70, c1: '#F59E0B', c2: '#DC2626' }) : `<div style="height:70px;display:flex;align-items:center;justify-content:center;color:var(--t4);font-size:11px">No data</div>`}
          <div style="font-size:10px;color:var(--t3);margin-top:.3rem"><span style="color:#F59E0B">■</span> Expiring &nbsp; <span style="color:#DC2626">■</span> Expired</div>
        </div>
      </div>
    </div>`;
}

async function renderProcurementReports() {
  const TAB_META = {
    spend: { label: 'Spend', icon: 'ti-currency-dollar' }, suppliers: { label: 'Suppliers', icon: 'ti-building-store' },
    delivery: { label: 'Delivery', icon: 'ti-truck-delivery' }, budget: { label: 'Budget', icon: 'ti-wallet' },
    // Phase 5A — Procurement Analytics & Forecasting. The pre-existing
    // "Analytics" tab (cycle days/late deliveries/top products/rankings) is
    // relabeled — same tab key, same function, zero logic change — since
    // "Analytics" is the more fitting name for this new executive tab.
    executive: { label: 'Analytics', icon: 'ti-chart-infographic' },
    budgetspend: { label: 'Budget & Spend', icon: 'ti-report-money' },
    forecasting: { label: 'Forecasting & Executive Reports', icon: 'ti-telescope' },
    analytics: { label: 'Cycle & Products', icon: 'ti-chart-line' },
    intelligence: { label: 'Intelligence', icon: 'ti-brain' },
    srm: { label: 'SRM', icon: 'ti-users-group' },
    // Phase 6 — Procurement Automation Engine. New tab, same
    // procurement-reports permission gate as every other tab on this page.
    automation: { label: 'Automation & Tasks', icon: 'ti-robot' },
    // Phase 7 — Procurement Performance Management. New tab, same gate.
    performance: { label: 'Performance', icon: 'ti-trophy' },
    // Procurement Exception Management Phase 2 — Return for Revision. New
    // tab, same gate, same per-tab fetch-and-render pattern as every other
    // tab on this page.
    revisions: { label: 'Requisition Revisions', icon: 'ti-history' },
    // Procurement Exception Management Phase 3 — Close with Shortage. New
    // tab, same gate, same per-tab pattern.
    poShortages: { label: 'PO Shortages', icon: 'ti-truck-off' },
  };
  // Phase 3C — the 9 executive report types, all served by the one
  // procurementSupplierIntelligenceReports function.
  const INTEL_REPORT_META = {
    best: 'Best Suppliers', worst: 'Worst Suppliers', preferred: 'Preferred Suppliers',
    high_risk: 'High Risk Suppliers', blacklisted: 'Blacklisted Suppliers', highest_spend: 'Highest Spend Suppliers',
    most_reliable: 'Most Reliable Suppliers', lowest_performing: 'Lowest Performing Suppliers',
    inactive: 'Inactive Suppliers', contracts_near_expiry: 'Contracts Near Expiry',
  };
  // Phase 4 — the 7 SRM report types, all served by the one srmReport
  // backend function. Row shapes differ per type, so the table is rendered
  // generically from whatever keys each row actually has (mirrors mobile's
  // ProcurementReportsScreen SRM tab).
  const SRM_REPORT_META = {
    contract_register: 'Contract Register', expiring_contracts: 'Expiring Contracts',
    compliance_status: 'Compliance Status', document_register: 'Document Register',
    communication_log: 'Communication Log', improvement_plans: 'Improvement Plans',
    executive_summary: 'Executive Summary',
  };
  // Phase 5D — the 13 executive report types, all served by the one
  // procurementExecutiveReport function.
  const PROC_EXEC_REPORT_META = {
    executive_summary: 'Executive Procurement Summary', spend: 'Procurement Spend Report',
    budget_utilization: 'Budget Utilization Report', forecast: 'Procurement Forecast Report',
    supplier_performance: 'Supplier Performance Report', supplier_spend: 'Supplier Spend Report',
    contract_performance: 'Contract Performance Report', department_spend: 'Department Spend Report',
    workshop_spend: 'Workshop Spend Report', savings: 'Procurement Savings Report',
    kpi_report: 'Procurement KPI Report', trend_report: 'Procurement Trend Report',
    executive_dashboard_report: 'Executive Dashboard Report',
  };
  $('page-procurement-reports').innerHTML = `
    <div class="page-head"><div class="page-head-text">
      <div class="ptitle"><i class="ti ti-report-money" style="color:var(--g-soft)"></i> Procurement Reports</div>
      <div class="psub">Spend analysis, supplier performance, delivery performance, budget utilization and analytics.</div>
    </div></div>
    <div style="display:flex;gap:.5rem;margin-bottom:1rem;flex-wrap:wrap" id="pr-rep-tabs">
      ${Object.entries(TAB_META).map(([t, m], i) => `<button class="filter-chip pr-rep-tab ${i === 0 ? 'active' : ''}" data-tab="${t}"><i class="ti ${m.icon}"></i>${m.label}</button>`).join('')}
    </div>
    <div id="pr-rep-body"></div>`;

  async function loadTab(tab) {
    const body = $('pr-rep-body');
    body.innerHTML = `<div class="card" style="padding:0"><table class="tbl"><thead><tr><th></th><th></th><th></th></tr></thead><tbody>${skeletonTableRows(3)}</tbody></table></div>`;
    if (tab === 'spend') {
      const r = await UFCL.procurementReportSpendAnalysis(STORAGE.user.id);
      const rows = r.ok ? r.rows : [];
      body.innerHTML = `<div class="card" style="padding:0"><table class="tbl"><thead><tr><th>Supplier</th><th>POs</th><th>Total Spend</th></tr></thead>
        <tbody>${rows.length ? rows.map((x) => `<tr><td>${x.supplier_name}</td><td>${x.po_count}</td><td style="font-family:var(--fm)">${Number(x.total_spend).toLocaleString()}</td></tr>`).join('') : '<tr><td colspan="3" style="text-align:center;color:var(--t3);padding:2rem">No spend data yet.</td></tr>'}</tbody></table></div>`;
    } else if (tab === 'suppliers') {
      const r = await UFCL.procurementReportSupplierPerf(STORAGE.user.id);
      const rows = r.ok ? r.rows : [];
      body.innerHTML = `<div class="card" style="padding:0"><table class="tbl"><thead><tr><th>Supplier</th><th>Rating</th><th>POs</th><th>Received</th><th>Rejected</th><th>Completed</th><th>Closed w/ Shortage</th><th>Delivered Qty %</th><th>Avg. Fulfillment %</th></tr></thead>
        <tbody>${rows.length ? rows.map((x) => `<tr><td>${x.name}${x.preferred ? ' ★' : ''}${x.blacklisted ? ' <span class="badge br" style="font-size:10px">Blacklisted</span>' : ''}</td><td>${x.rating ?? '—'}</td><td>${x.total_pos}</td><td>${x.total_received}</td><td>${x.total_rejected}</td><td>${x.orders_completed}</td><td style="${x.orders_closed_with_shortage>0?'color:var(--red)':''}">${x.orders_closed_with_shortage}</td><td>${x.delivered_qty_pct}%</td><td>${x.avg_fulfillment_pct}%</td></tr>`).join('') : '<tr><td colspan="9" style="text-align:center;color:var(--t3);padding:2rem">No supplier activity yet.</td></tr>'}</tbody></table></div>`;
    } else if (tab === 'delivery') {
      const r = await UFCL.procurementReportDeliveryPerf(STORAGE.user.id);
      const rows = r.ok ? r.rows : [];
      body.innerHTML = `<div class="card" style="padding:0"><table class="tbl"><thead><tr><th>PO #</th><th>Supplier</th><th>Expected</th><th>Received</th><th>On Time</th></tr></thead>
        <tbody>${rows.length ? rows.map((x) => `<tr><td>${x.po_number}</td><td>${x.supplier_name}</td><td style="font-size:12px">${x.expected_delivery_date ? new Date(x.expected_delivery_date).toLocaleDateString() : '—'}</td><td style="font-size:12px">${x.first_received_at ? new Date(x.first_received_at).toLocaleDateString() : '—'}</td><td>${x.on_time === null ? '—' : x.on_time ? '<span class="badge bg">Yes</span>' : '<span class="badge br">Late</span>'}</td></tr>`).join('') : '<tr><td colspan="5" style="text-align:center;color:var(--t3);padding:2rem">No delivery data yet.</td></tr>'}</tbody></table></div>`;
    } else if (tab === 'budget') {
      const r = await UFCL.procurementReportBudgetUtil(STORAGE.user.id);
      const rows = r.ok ? r.rows : [];
      body.innerHTML = `<div class="card" style="padding:0"><table class="tbl"><thead><tr><th>Budget Code</th><th>Requisitions</th><th>Total Estimated</th></tr></thead>
        <tbody>${rows.length ? rows.map((x) => `<tr><td>${x.budget_code}</td><td>${x.requisitions}</td><td style="font-family:var(--fm)">${Number(x.total_estimated).toLocaleString()}</td></tr>`).join('') : '<tr><td colspan="3" style="text-align:center;color:var(--t3);padding:2rem">No budget-coded requisitions yet.</td></tr>'}</tbody></table></div>`;
    } else if (tab === 'revisions') {
      const r = await UFCL.procurementRequisitionRevisionReports(STORAGE.user.id);
      if (!r.ok) { body.innerHTML = `<p style="color:var(--red)">${r.error}</p>`; return; }
      const outcomeMap = Object.fromEntries(r.outcomeCounts.map((x) => [x.status, x.n]));
      body.innerHTML = `
        <div class="cards" style="margin-bottom:1.25rem">
          <div class="mc"><div class="mclbl">Approved</div><div class="mcval" style="color:var(--green)">${outcomeMap.approved || 0}</div></div>
          <div class="mc"><div class="mclbl">Rejected</div><div class="mcval" style="color:var(--red)">${outcomeMap.rejected || 0}</div></div>
          <div class="mc"><div class="mclbl">Returned for Revision</div><div class="mcval" style="color:var(--amber)">${outcomeMap.returned_for_revision || 0}</div></div>
          <div class="mc"><div class="mclbl">Avg. Revision Time</div><div class="mcval">${r.avgRevisionTimeHours.toFixed(1)}h</div></div>
        </div>
        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:1rem">
          <div class="card" style="padding:0">
            <div style="padding:1rem 1.25rem;border-bottom:1px solid var(--bdr)"><h3 style="margin:0"><i class="ti ti-repeat"></i>Most Revised Requisitions</h3></div>
            <table class="tbl"><thead><tr><th>Number</th><th>Title</th><th>Revisions</th></tr></thead>
            <tbody>${r.revisionCount.length ? r.revisionCount.map((x) => `<tr><td style="font-family:var(--fm)">${x.requisition_number}</td><td>${x.title}</td><td>${x.revision_count}</td></tr>`).join('') : '<tr><td colspan="3" style="text-align:center;color:var(--t3);padding:2rem">No revisions yet.</td></tr>'}</tbody></table>
          </div>
          <div class="card" style="padding:0">
            <div style="padding:1rem 1.25rem;border-bottom:1px solid var(--bdr)"><h3 style="margin:0"><i class="ti ti-building"></i>Most Revised Departments</h3></div>
            <table class="tbl"><thead><tr><th>Department</th><th>Revisions</th></tr></thead>
            <tbody>${r.mostRevisedDepartments.length ? r.mostRevisedDepartments.map((x) => `<tr><td>${x.department}</td><td>${x.revisions}</td></tr>`).join('') : '<tr><td colspan="2" style="text-align:center;color:var(--t3);padding:2rem">No revisions yet.</td></tr>'}</tbody></table>
          </div>
          <div class="card" style="padding:0">
            <div style="padding:1rem 1.25rem;border-bottom:1px solid var(--bdr)"><h3 style="margin:0"><i class="ti ti-message-2"></i>Most Common Revision Reasons</h3></div>
            <table class="tbl"><thead><tr><th>Reviewer Comment</th><th>Count</th></tr></thead>
            <tbody>${r.mostCommonRevisionReasons.length ? r.mostCommonRevisionReasons.map((x) => `<tr><td style="font-size:12px">${x.reviewer_notes}</td><td>${x.n}</td></tr>`).join('') : '<tr><td colspan="2" style="text-align:center;color:var(--t3);padding:2rem">No revisions yet.</td></tr>'}</tbody></table>
          </div>
        </div>`;
    } else if (tab === 'poShortages') {
      const r = await UFCL.procurementPoShortageReports(STORAGE.user.id);
      if (!r.ok) { body.innerHTML = `<p style="color:var(--red)">${r.error}</p>`; return; }
      body.innerHTML = `
        <div class="cards" style="margin-bottom:1.25rem">
          <div class="mc"><div class="mclbl">Closed with Shortage</div><div class="mcval" style="color:var(--red)">${r.closedWithShortageOrders.length}</div></div>
        </div>
        <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(340px,1fr));gap:1rem">
          <div class="card" style="padding:0">
            <div style="padding:1rem 1.25rem;border-bottom:1px solid var(--bdr)"><h3 style="margin:0"><i class="ti ti-alert-triangle"></i>Closed with Shortage Orders</h3></div>
            <table class="tbl"><thead><tr><th>PO #</th><th>Supplier</th><th>Reason</th><th>Requested By</th><th>Closed</th></tr></thead>
            <tbody>${r.closedWithShortageOrders.length ? r.closedWithShortageOrders.map((x) => `<tr><td style="font-family:var(--fm)">${x.po_number}</td><td>${x.supplier_name}</td><td style="font-size:12px">${x.shortage_reason}</td><td>${x.requested_by_name || '—'}</td><td style="font-size:12px">${x.shortage_closed_at ? new Date(x.shortage_closed_at).toLocaleDateString() : '—'}</td></tr>`).join('') : '<tr><td colspan="5" style="text-align:center;color:var(--t3);padding:2rem">No orders closed with shortage yet.</td></tr>'}</tbody></table>
          </div>
          <div class="card" style="padding:0">
            <div style="padding:1rem 1.25rem;border-bottom:1px solid var(--bdr)"><h3 style="margin:0"><i class="ti ti-package"></i>Outstanding Quantity by Supplier</h3></div>
            <table class="tbl"><thead><tr><th>Supplier</th><th>Outstanding Qty</th></tr></thead>
            <tbody>${r.outstandingQtyBySupplier.length ? r.outstandingQtyBySupplier.map((x) => `<tr><td>${x.supplier_name}</td><td>${x.outstanding_qty}</td></tr>`).join('') : '<tr><td colspan="2" style="text-align:center;color:var(--t3);padding:2rem">No outstanding orders.</td></tr>'}</tbody></table>
          </div>
          <div class="card" style="padding:0">
            <div style="padding:1rem 1.25rem;border-bottom:1px solid var(--bdr)"><h3 style="margin:0"><i class="ti ti-chart-bar"></i>Supplier Fulfillment Rate</h3></div>
            <table class="tbl"><thead><tr><th>Supplier</th><th>Delivered Qty %</th></tr></thead>
            <tbody>${r.supplierFulfillmentRate.length ? r.supplierFulfillmentRate.map((x) => `<tr><td>${x.supplier_name}</td><td>${x.delivered_qty_pct}%</td></tr>`).join('') : '<tr><td colspan="2" style="text-align:center;color:var(--t3);padding:2rem">No data yet.</td></tr>'}</tbody></table>
          </div>
          <div class="card" style="padding:0">
            <div style="padding:1rem 1.25rem;border-bottom:1px solid var(--bdr)"><h3 style="margin:0"><i class="ti ti-gauge"></i>Average Supplier Completion Rate</h3></div>
            <table class="tbl"><thead><tr><th>Supplier</th><th>Avg. Fulfillment %</th></tr></thead>
            <tbody>${r.avgSupplierCompletionRate.length ? r.avgSupplierCompletionRate.map((x) => `<tr><td>${x.supplier_name}</td><td>${x.avg_fulfillment_pct}%</td></tr>`).join('') : '<tr><td colspan="2" style="text-align:center;color:var(--t3);padding:2rem">No data yet.</td></tr>'}</tbody></table>
          </div>
          <div class="card" style="padding:0">
            <div style="padding:1rem 1.25rem;border-bottom:1px solid var(--bdr)"><h3 style="margin:0"><i class="ti ti-message-2"></i>Most Common Shortage Reasons</h3></div>
            <table class="tbl"><thead><tr><th>Reason</th><th>Count</th></tr></thead>
            <tbody>${r.mostCommonShortageReasons.length ? r.mostCommonShortageReasons.map((x) => `<tr><td style="font-size:12px">${x.shortage_reason}</td><td>${x.n}</td></tr>`).join('') : '<tr><td colspan="2" style="text-align:center;color:var(--t3);padding:2rem">No data yet.</td></tr>'}</tbody></table>
          </div>
          <div class="card" style="padding:0">
            <div style="padding:1rem 1.25rem;border-bottom:1px solid var(--bdr)"><h3 style="margin:0"><i class="ti ti-trophy"></i>Top Suppliers by Shortage Value</h3></div>
            <table class="tbl"><thead><tr><th>Supplier</th><th>Shortage Value</th></tr></thead>
            <tbody>${r.topSuppliersByShortageValue.length ? r.topSuppliersByShortageValue.map((x) => `<tr><td>${x.supplier_name}</td><td style="font-family:var(--fm)">${Number(x.shortage_value).toLocaleString()}</td></tr>`).join('') : '<tr><td colspan="2" style="text-align:center;color:var(--t3);padding:2rem">No data yet.</td></tr>'}</tbody></table>
          </div>
          <div class="card" style="padding:0">
            <div style="padding:1rem 1.25rem;border-bottom:1px solid var(--bdr)"><h3 style="margin:0"><i class="ti ti-history"></i>Supplier Shortage History</h3></div>
            <table class="tbl"><thead><tr><th>PO #</th><th>Supplier</th><th>Status</th><th>Requested</th></tr></thead>
            <tbody>${r.supplierShortageHistory.length ? r.supplierShortageHistory.map((x) => `<tr><td style="font-family:var(--fm)">${x.po_number}</td><td>${x.supplier_name}</td><td>${procStatusBadge(x.status)}</td><td style="font-size:12px">${x.shortage_requested_at ? new Date(x.shortage_requested_at).toLocaleDateString() : '—'}</td></tr>`).join('') : '<tr><td colspan="4" style="text-align:center;color:var(--t3);padding:2rem">No shortage requests yet.</td></tr>'}</tbody></table>
          </div>
        </div>`;
    } else if (tab === 'executive') {
      // Phase 5A — Executive Procurement Dashboard, as a report tab. Same
      // backend function and the same shared _procExecAnalyticsHtml renderer
      // as the Procurement Dashboard page's "Procurement Analytics" section
      // — this tab is a standalone caller, so it uses the contract-expiry
      // timeline already included on `exec` rather than a second SRM fetch.
      const r = await UFCL.procurementExecutiveDashboard(STORAGE.user.id);
      if (!r.ok) { body.innerHTML = `<p style="color:var(--red)">${r.error}</p>`; return; }
      body.innerHTML = `
        <div class="frow" style="justify-content:flex-end;margin-bottom:.75rem">
          <button type="button" class="bs1" id="exec-export-btn"><i class="ti ti-file-download"></i>Export CSV</button>
        </div>
        ${_procExecAnalyticsHtml(r, r.charts.contractExpiryTimeline)}`;
      $('exec-export-btn').onclick = async () => {
        const k = r.kpis;
        const lines = [
          ['Metric', 'Value'],
          ['Total Procurement Spend', k.totalSpend], ['Spend This Month', k.spendThisMonth],
          ['Spend This Quarter', k.spendThisQuarter], ['Spend This Year', k.spendThisYear],
          ['Active Suppliers', k.activeSuppliers], ['Active Contracts', k.activeContracts],
          ['Purchase Orders', k.purchaseOrders], ['Goods Receipts', k.goodsReceipts],
          ['Avg Procurement Cycle (days)', k.avgProcurementCycleDays], ['Avg Approval Time (days)', k.avgApprovalDays],
          ['Estimated Budget', k.budgetUtilization.estimatedBudget], ['Actual Spend (Budget)', k.budgetUtilization.actualSpend],
          ['Budget Utilization %', k.budgetUtilization.utilizationPct], ['Budget Variance', k.budgetUtilization.variance],
          ['Planning Savings', k.planningSavings.total], ['Negotiation Savings', k.negotiationSavings.total],
          [], ['Monthly Spend Trend', ''], ['Month', 'Total'], ...r.charts.monthlySpendTrend.map((x) => [x.month, x.total]),
          [], ['Supplier Spend Distribution', ''], ['Supplier', 'Spend'], ...r.charts.supplierSpendDistribution.map((x) => [x.name, x.value]),
          [], ['Department Spend', ''], ['Department', 'Spend'], ...r.charts.departmentSpend.map((x) => [x.department, x.total]),
          [], ['Workshop Spend', ''], ['Workshop', 'Spend'], ...r.charts.workshopSpend.map((x) => [x.workshop, x.total]),
        ];
        const csv = lines.map((row) => row.map((c) => `"${String(c ?? '').replace(/"/g, '""')}"`).join(',')).join('\r\n');
        const filename = `procurement_executive_analytics_${new Date().toISOString().slice(0, 10)}.csv`;
        const res2 = await UFCL.execExport(STORAGE.user.id, { csv, filename });
        if (!res2?.ok && res2?.error !== undefined) showToast('Export cancelled or failed', 'error');
      };
    } else if (tab === 'budgetspend') {
      // Phase 5B — Spend & Budget Analytics. One backend call
      // (procurementSpendBudgetAnalytics) which itself reuses
      // procurementExecutiveDashboard()'s KPIs wholesale — every table below
      // uses wireSortableTable/applyProcListFilters-style local filtering,
      // the same reusable primitives every other report tab already uses.
      const r = await UFCL.procurementSpendBudgetAnalytics(STORAGE.user.id);
      if (!r.ok) { body.innerHTML = `<p style="color:var(--red)">${r.error}</p>`; return; }

      const budgetSort = { key: null, dir: 'asc' };
      const deptSort = { key: null, dir: 'asc' };
      const workshopSort = { key: null, dir: 'asc' };
      const supplierSort = { key: null, dir: 'asc' };
      const contractSort = { key: null, dir: 'asc' };
      let supplierSearch = '';

      function budgetRowHtml(x) {
        return `<tr><td>${x.budgetCode}</td><td>${x.requisitions}</td><td style="font-family:var(--fm)">${_fmtCur(x.estimated)}</td><td style="font-family:var(--fm)">${_fmtCur(x.actual)}</td>
          <td style="font-family:var(--fm);color:${x.variance >= 0 ? 'var(--g-soft)' : 'var(--red)'}">${x.variance >= 0 ? '+' : ''}${_fmtCur(x.variance)}</td><td>${x.utilizationPct}%</td></tr>`;
      }
      function renderBudgetRows(rows) {
        $('bs-budget-tbody').innerHTML = rows.length ? rows.map(budgetRowHtml).join('') : `<tr><td colspan="6" style="text-align:center;color:var(--t3);padding:2rem">No budget-coded requisitions yet.</td></tr>`;
      }

      function deptRowHtml(x) {
        return `<tr><td>${x.department}</td><td style="font-family:var(--fm)">${_fmtCur(x.total)}</td><td style="font-family:var(--fm)">${_fmtCur(x.estimated)}</td>
          <td style="font-family:var(--fm);color:${x.variance >= 0 ? 'var(--g-soft)' : 'var(--red)'}">${x.variance >= 0 ? '+' : ''}${_fmtCur(x.variance)}</td>
          <td>${_svgSparkline(x.trend.map((t) => t.total), { w: 70, h: 22 })}</td></tr>`;
      }
      function renderDeptRows(rows) {
        $('bs-dept-tbody').innerHTML = rows.length ? rows.map(deptRowHtml).join('') : `<tr><td colspan="5" style="text-align:center;color:var(--t3);padding:2rem">No department spend yet.</td></tr>`;
      }

      function workshopRowHtml(x) {
        return `<tr><td>${x.workshop}</td><td style="font-family:var(--fm)">${_fmtCur(x.total)}</td><td style="font-family:var(--fm)">${_fmtCur(x.estimated)}</td>
          <td style="font-family:var(--fm);color:${x.variance >= 0 ? 'var(--g-soft)' : 'var(--red)'}">${x.variance >= 0 ? '+' : ''}${_fmtCur(x.variance)}</td>
          <td>${_svgSparkline(x.trend.map((t) => t.total), { w: 70, h: 22 })}</td>
          <td class="row-actions">${x.workshopId != null ? `<button class="bs1 bs-ws-drill" data-id="${x.workshopId}" data-name="${String(x.workshop).replace(/"/g, '&quot;')}" title="View Orders"><i class="ti ti-arrow-right"></i></button>` : ''}</td></tr>`;
      }
      function renderWorkshopRows(rows) {
        $('bs-workshop-tbody').innerHTML = rows.length ? rows.map(workshopRowHtml).join('') : `<tr><td colspan="6" style="text-align:center;color:var(--t3);padding:2rem">No workshop spend yet.</td></tr>`;
        document.querySelectorAll('.bs-ws-drill').forEach((btn) => { btn.onclick = () => drillIntoOrdersByWorkshop(Number(btn.dataset.id), btn.dataset.name); });
      }

      function supplierFiltered() {
        let out = r.supplierSpend;
        if (supplierSearch.trim()) { const q = supplierSearch.trim().toLowerCase(); out = out.filter((s) => s.name.toLowerCase().includes(q)); }
        return out;
      }
      function supplierRowHtml(x) {
        return `<tr><td>${x.name}</td><td style="font-family:var(--fm)">${_fmtCur(x.totalSpend)}</td><td style="font-family:var(--fm)">${_fmtCur(x.monthSpend)}</td>
          <td style="font-family:var(--fm)">${_fmtCur(x.avgOrder)}</td><td>${x.procurementSharePct}%</td>
          <td class="row-actions"><button class="bs1 bs-sup-drill" data-id="${x.id}" data-name="${String(x.name).replace(/"/g, '&quot;')}" title="Open Supplier"><i class="ti ti-arrow-right"></i></button></td></tr>`;
      }
      function renderSupplierRows(rows) {
        $('bs-supplier-tbody').innerHTML = rows.length ? rows.map(supplierRowHtml).join('') : `<tr><td colspan="6" style="text-align:center;color:var(--t3);padding:2rem">No supplier spend yet.</td></tr>`;
        document.querySelectorAll('.bs-sup-drill').forEach((btn) => { btn.onclick = () => openSupplierManageOverlay(Number(btn.dataset.id), btn.dataset.name, 'intelligence'); });
      }

      const CONTRACT_INDICATOR_COLOR = { over: 'var(--red)', under: 'var(--amber)', 'on-track': 'var(--g-soft)', unknown: 'var(--t3)' };
      function contractRowHtml(x) {
        const color = CONTRACT_INDICATOR_COLOR[x.indicator] || 'var(--t3)';
        return `<tr><td>${x.contractRef}</td><td>${x.supplierName}</td><td>${procStatusBadge(x.status)}</td>
          <td style="font-family:var(--fm)">${x.contractValue != null ? _fmtCur(x.contractValue) : '—'}</td>
          <td style="font-family:var(--fm)">${_fmtCur(x.actualSpend)}</td>
          <td>${x.utilizationPct != null ? x.utilizationPct + '%' : '—'}</td>
          <td><span class="badge" style="background:${color}22;color:${color};text-transform:capitalize">${x.indicator}</span></td>
          <td class="row-actions"><button class="bs1 bs-contract-drill" data-id="${x.supplierId}" data-name="${String(x.supplierName).replace(/"/g, '&quot;')}" title="Open Supplier"><i class="ti ti-arrow-right"></i></button></td></tr>`;
      }
      function renderContractRows(rows) {
        $('bs-contract-tbody').innerHTML = rows.length ? rows.map(contractRowHtml).join('') : `<tr><td colspan="8" style="text-align:center;color:var(--t3);padding:2rem">No contracts yet.</td></tr>`;
        document.querySelectorAll('.bs-contract-drill').forEach((btn) => { btn.onclick = () => openSupplierManageOverlay(Number(btn.dataset.id), btn.dataset.name, 'contracts'); });
      }

      body.innerHTML = `
        <div class="frow" style="justify-content:flex-end;margin-bottom:.75rem">
          <button type="button" class="bs1" id="bs-export-btn"><i class="ti ti-file-download"></i>Export CSV</button>
        </div>
        <div class="cards" style="margin-bottom:1.25rem">
          <div class="kpi-card kpi-blue"><div class="kpi-lbl">Total Spend</div><div class="kpi-val" style="font-size:16px">${_fmtCur(r.kpis.totalSpend)}</div></div>
          <div class="kpi-card"><div class="kpi-lbl">This Month</div><div class="kpi-val" style="font-size:15px">${_fmtCur(r.kpis.spendThisMonth)}</div></div>
          <div class="kpi-card"><div class="kpi-lbl">This Quarter</div><div class="kpi-val" style="font-size:15px">${_fmtCur(r.kpis.spendThisQuarter)}</div></div>
          <div class="kpi-card"><div class="kpi-lbl">This Year</div><div class="kpi-val" style="font-size:15px">${_fmtCur(r.kpis.spendThisYear)}</div></div>
          <div class="kpi-card"><div class="kpi-lbl">Estimated Budget</div><div class="kpi-val" style="font-size:15px">${_fmtCur(r.kpis.budgetUtilization.estimatedBudget)}</div></div>
          <div class="kpi-card"><div class="kpi-lbl">Actual Spend</div><div class="kpi-val" style="font-size:15px">${_fmtCur(r.kpis.budgetUtilization.actualSpend)}</div></div>
          <div class="kpi-card ${r.kpis.budgetUtilization.utilizationPct > 100 ? 'kpi-amber' : 'kpi-green'}"><div class="kpi-lbl">Budget Utilization</div><div class="kpi-val">${r.kpis.budgetUtilization.utilizationPct}%</div></div>
          <div class="kpi-card"><div class="kpi-lbl">Procurement Variance</div><div class="kpi-val" style="font-size:15px;color:${r.kpis.budgetUtilization.variance >= 0 ? 'var(--g-soft)' : 'var(--red)'}">${r.kpis.budgetUtilization.variance >= 0 ? '+' : ''}${_fmtCur(r.kpis.budgetUtilization.variance)}</div></div>
          <div class="kpi-card"><div class="kpi-lbl">Planning Savings</div><div class="kpi-val" style="font-size:15px;color:${r.kpis.planningSavings.total >= 0 ? 'var(--g-soft)' : 'var(--red)'}">${r.kpis.planningSavings.total >= 0 ? '+' : ''}${_fmtCur(r.kpis.planningSavings.total)}</div></div>
          <div class="kpi-card"><div class="kpi-lbl">Negotiation Savings</div><div class="kpi-val" style="font-size:15px;color:${r.kpis.negotiationSavings.total >= 0 ? 'var(--g-soft)' : 'var(--red)'}">${r.kpis.negotiationSavings.total >= 0 ? '+' : ''}${_fmtCur(r.kpis.negotiationSavings.total)}</div></div>
        </div>

        <div class="frow" style="align-items:flex-start;gap:1rem;margin-bottom:1.25rem">
          <div style="flex:1;min-width:280px">
            <div class="section-hdr"><h4><i class="ti ti-chart-line"></i>Quarterly Spend Trend</h4></div>
            <div class="card">${_svgLine(r.trends.quarterly, 'total', { h: 80 })}<div style="display:flex;justify-content:space-between;margin-top:.4rem;font-size:10px;color:var(--t3)">${_clabels(r.trends.quarterly, 'quarter', 6)}</div></div>
          </div>
          <div style="flex:1;min-width:280px">
            <div class="section-hdr"><h4><i class="ti ti-chart-line"></i>Annual Spend Trend</h4></div>
            <div class="card">${_svgBar(r.trends.annual, 'total', { h: 80, color: '#7C3AED' })}<div style="display:flex;justify-content:space-between;margin-top:.4rem;font-size:10px;color:var(--t3)">${r.trends.annual.map((x) => `<span>${x.year}</span>`).join('')}</div></div>
          </div>
        </div>

        <div class="section-hdr"><h4><i class="ti ti-wallet"></i>Budget vs Actual (by Budget Code)</h4></div>
        <div class="card" style="padding:0;margin-bottom:1.25rem">
          <table class="tbl" id="bs-budget-table"><thead><tr><th data-sort-key="budgetCode">Budget Code</th><th data-sort-key="requisitions">Requisitions</th><th data-sort-key="estimated">Estimated</th><th data-sort-key="actual">Actual</th><th data-sort-key="variance">Variance</th><th data-sort-key="utilizationPct">Utilization</th></tr></thead>
          <tbody id="bs-budget-tbody"></tbody></table>
        </div>

        <div class="section-hdr"><h4><i class="ti ti-building"></i>Department Analysis</h4></div>
        <div class="card" style="padding:0;margin-bottom:1.25rem">
          <table class="tbl" id="bs-dept-table"><thead><tr><th data-sort-key="department">Department</th><th data-sort-key="total">Spend</th><th data-sort-key="estimated">Budget</th><th data-sort-key="variance">Variance</th><th>Trend</th></tr></thead>
          <tbody id="bs-dept-tbody"></tbody></table>
        </div>

        <div class="section-hdr"><h4><i class="ti ti-tools-kitchen-2"></i>Workshop Analysis</h4></div>
        <div class="card" style="padding:0;margin-bottom:1.25rem">
          <table class="tbl" id="bs-workshop-table"><thead><tr><th data-sort-key="workshop">Workshop</th><th data-sort-key="total">Spend</th><th data-sort-key="estimated">Budget</th><th data-sort-key="variance">Variance</th><th>Trend</th><th></th></tr></thead>
          <tbody id="bs-workshop-tbody"></tbody></table>
        </div>

        <div class="section-hdr"><h4><i class="ti ti-building-store"></i>Supplier Spend</h4></div>
        <div class="filter-bar"><div class="filter-search"><i class="ti ti-search"></i><input id="bs-supplier-search" type="text" placeholder="Search supplier…"></div></div>
        <div class="card" style="padding:0;margin-bottom:1.25rem">
          <table class="tbl" id="bs-supplier-table"><thead><tr><th data-sort-key="name">Supplier</th><th data-sort-key="totalSpend">Total Spend</th><th data-sort-key="monthSpend">This Month</th><th data-sort-key="avgOrder">Avg Order</th><th data-sort-key="procurementSharePct">Share</th><th></th></tr></thead>
          <tbody id="bs-supplier-tbody"></tbody></table>
        </div>

        <div class="section-hdr"><h4><i class="ti ti-file-text"></i>Contract Spend</h4></div>
        <div class="cards" style="margin-bottom:.75rem">
          <div class="kpi-card kpi-green"><div class="kpi-lbl">Under Contract</div><div class="kpi-val" style="font-size:15px">${_fmtCur(r.contractSpendSplit.underContract)}</div></div>
          <div class="kpi-card"><div class="kpi-lbl">Outside Contract</div><div class="kpi-val" style="font-size:15px">${_fmtCur(r.contractSpendSplit.outsideContract)}</div></div>
          <div class="kpi-card"><div class="kpi-lbl">Under Contract %</div><div class="kpi-val">${r.contractSpendSplit.underContractPct}%</div></div>
        </div>
        <div class="card" style="padding:0;margin-bottom:1.25rem">
          <table class="tbl" id="bs-contract-table"><thead><tr><th data-sort-key="contractRef">Contract</th><th data-sort-key="supplierName">Supplier</th><th>Contract Status</th><th data-sort-key="contractValue">Value</th><th data-sort-key="actualSpend">Actual Spend</th><th data-sort-key="utilizationPct">Utilization</th><th data-sort-key="indicator">Indicator</th><th></th></tr></thead>
          <tbody id="bs-contract-tbody"></tbody></table>
        </div>

        <div class="frow" style="align-items:flex-start;gap:1rem">
          <div style="flex:1;min-width:260px">
            <div class="section-hdr"><h4><i class="ti ti-building-store"></i>Supplier Spend Distribution</h4></div>
            <div class="card">${_svgBar(r.supplierSpend.slice(0, 10), 'totalSpend', { h: 80 })}<div style="display:flex;justify-content:space-between;margin-top:.4rem;font-size:10px;color:var(--t3)">${r.supplierSpend.slice(0, 8).map((s) => `<span title="${s.name}">${s.name.length > 8 ? s.name.slice(0, 7) + '…' : s.name}</span>`).join('')}</div></div>
          </div>
          <div style="flex:1;min-width:260px">
            <div class="section-hdr"><h4><i class="ti ti-scale"></i>Contract Utilization</h4></div>
            <div class="card">${_svgBar(r.contractUtilization.filter((c) => c.utilizationPct != null).slice(0, 10), 'utilizationPct', { h: 80, color: '#DC2626' })}</div>
          </div>
        </div>`;

      renderBudgetRows(r.budgetByCode);
      wireSortableTable($('bs-budget-table'), budgetSort, () => r.budgetByCode, renderBudgetRows);
      renderDeptRows(r.departmentSpend);
      wireSortableTable($('bs-dept-table'), deptSort, () => r.departmentSpend, renderDeptRows);
      renderWorkshopRows(r.workshopSpend);
      wireSortableTable($('bs-workshop-table'), workshopSort, () => r.workshopSpend, renderWorkshopRows);
      renderSupplierRows(supplierFiltered());
      wireSortableTable($('bs-supplier-table'), supplierSort, supplierFiltered, renderSupplierRows);
      $('bs-supplier-search').oninput = (e) => { supplierSearch = e.target.value; renderSupplierRows(supplierFiltered()); };
      renderContractRows(r.contractUtilization);
      wireSortableTable($('bs-contract-table'), contractSort, () => r.contractUtilization, renderContractRows);

      $('bs-export-btn').onclick = async () => {
        const lines = [
          ['Metric', 'Value'],
          ['Total Spend', r.kpis.totalSpend], ['Spend This Month', r.kpis.spendThisMonth], ['Spend This Quarter', r.kpis.spendThisQuarter], ['Spend This Year', r.kpis.spendThisYear],
          ['Estimated Budget', r.kpis.budgetUtilization.estimatedBudget], ['Actual Spend', r.kpis.budgetUtilization.actualSpend],
          ['Budget Utilization %', r.kpis.budgetUtilization.utilizationPct], ['Procurement Variance', r.kpis.budgetUtilization.variance],
          ['Planning Savings', r.kpis.planningSavings.total], ['Negotiation Savings', r.kpis.negotiationSavings.total],
          [], ['Budget by Code'], ['Budget Code', 'Requisitions', 'Estimated', 'Actual', 'Variance', 'Utilization %'],
          ...r.budgetByCode.map((x) => [x.budgetCode, x.requisitions, x.estimated, x.actual, x.variance, x.utilizationPct]),
          [], ['Department Spend'], ['Department', 'Spend', 'Budget', 'Variance'],
          ...r.departmentSpend.map((x) => [x.department, x.total, x.estimated, x.variance]),
          [], ['Workshop Spend'], ['Workshop', 'Spend', 'Budget', 'Variance'],
          ...r.workshopSpend.map((x) => [x.workshop, x.total, x.estimated, x.variance]),
          [], ['Supplier Spend'], ['Supplier', 'Total Spend', 'This Month', 'Avg Order', 'Share %'],
          ...r.supplierSpend.map((x) => [x.name, x.totalSpend, x.monthSpend, x.avgOrder, x.procurementSharePct]),
          [], ['Contract Utilization'], ['Contract', 'Supplier', 'Status', 'Value', 'Actual Spend', 'Utilization %', 'Indicator'],
          ...r.contractUtilization.map((x) => [x.contractRef, x.supplierName, x.status, x.contractValue, x.actualSpend, x.utilizationPct, x.indicator]),
        ];
        const csv = lines.map((row) => row.map((c) => `"${String(c ?? '').replace(/"/g, '""')}"`).join(',')).join('\r\n');
        const filename = `procurement_budget_spend_${new Date().toISOString().slice(0, 10)}.csv`;
        const res2 = await UFCL.execExport(STORAGE.user.id, { csv, filename });
        if (!res2?.ok && res2?.error !== undefined) showToast('Export cancelled or failed', 'error');
      };
    } else if (tab === 'forecasting') {
      // Phase 5C + 5D — Procurement Forecasting & Executive Reporting.
      // Forecasting Dashboard (KPIs + charts) always visible, then a
      // report-type dropdown for the 13 executive reports — mirrors the
      // established SRM/Intelligence report-tab pattern exactly.
      const f = await UFCL.procurementForecastingDashboard(STORAGE.user.id);
      if (!f.ok) { body.innerHTML = `<p style="color:var(--red)">${f.error}</p>`; return; }

      const CONTRACT_RENEWAL_MONTHS = {};
      for (const c of f.contractRenewalForecast) {
        const m = String(c.endDate).slice(0, 7);
        (CONTRACT_RENEWAL_MONTHS[m] ||= { month: m, count: 0, value: 0 }).count += 1;
        CONTRACT_RENEWAL_MONTHS[m].value += c.expectedRenewalValue || 0;
      }
      const renewalTimelineRows = Object.values(CONTRACT_RENEWAL_MONTHS).sort((a, b) => a.month.localeCompare(b.month));
      const fvaRows = f.charts.forecastVsActual.actual.map((v, i) => ({ period: i + 1, actual: v, predicted: f.charts.forecastVsActual.predicted[i] }));

      body.innerHTML = `
        <div class="section-hdr"><h4><i class="ti ti-telescope"></i>Forecasting Dashboard</h4></div>
        <div class="cards" style="margin-bottom:1.25rem">
          <div class="kpi-card kpi-blue"><div class="kpi-lbl">Expected Monthly Spend</div><div class="kpi-val" style="font-size:16px">${_fmtCur(f.kpis.expectedMonthlySpend)}</div></div>
          <div class="kpi-card"><div class="kpi-lbl">Expected Quarterly Spend</div><div class="kpi-val" style="font-size:15px">${_fmtCur(f.kpis.expectedQuarterlySpend)}</div></div>
          <div class="kpi-card"><div class="kpi-lbl">Expected Annual Spend</div><div class="kpi-val" style="font-size:15px">${_fmtCur(f.kpis.expectedAnnualSpend)}</div></div>
          <div class="kpi-card"><div class="kpi-lbl">Budget Projection</div><div class="kpi-val">${f.kpis.budgetProjection.projectedUtilizationPct}%</div><div class="kpi-sub"><i class="ti ti-wallet"></i>projected utilization</div></div>
          <div class="kpi-card ${f.kpis.forecastAccuracy == null ? '' : f.kpis.forecastAccuracy >= 80 ? 'kpi-green' : 'kpi-amber'}"><div class="kpi-lbl">Forecast Accuracy</div><div class="kpi-val">${f.kpis.forecastAccuracy != null ? f.kpis.forecastAccuracy + '%' : '—'}</div><div class="kpi-sub"><i class="ti ti-target"></i>${f.kpis.forecastAccuracy != null ? 'backtested' : 'not enough history'}</div></div>
          <div class="kpi-card ${f.kpis.upcomingContractRenewals > 0 ? 'kpi-amber' : ''}"><div class="kpi-lbl">Upcoming Contract Renewals</div><div class="kpi-val">${f.kpis.upcomingContractRenewals}</div><div class="kpi-sub"><i class="ti ti-file-alert"></i>next 12 months</div></div>
          <div class="kpi-card"><div class="kpi-lbl">Predicted Procurement Volume</div><div class="kpi-val">${f.kpis.expectedProcurementVolume}</div><div class="kpi-sub"><i class="ti ti-cart"></i>POs next month</div></div>
          <div class="kpi-card ${f.kpis.highDemandSuppliersCount > 0 ? 'kpi-amber' : ''}"><div class="kpi-lbl">High Demand Suppliers</div><div class="kpi-val">${f.kpis.highDemandSuppliersCount}</div></div>
          <div class="kpi-card"><div class="kpi-lbl">Procurement Capacity</div><div class="kpi-val">${f.kpis.procurementCapacity}</div><div class="kpi-sub"><i class="ti ti-gauge"></i>POs/month trend</div></div>
        </div>

        <div class="frow" style="align-items:flex-start;gap:1rem;margin-bottom:1.25rem">
          <div style="flex:1;min-width:280px">
            <div class="section-hdr"><h4><i class="ti ti-chart-line"></i>Forecast vs Actual (backtest)</h4></div>
            <div class="card">${fvaRows.length ? _svgDualBar(fvaRows, 'actual', 'predicted', { h: 80 }) : `<div style="height:80px;display:flex;align-items:center;justify-content:center;color:var(--t4);font-size:11px">Not enough history to backtest yet</div>`}
              <div style="font-size:10px;color:var(--t3);margin-top:.3rem"><span style="color:#2E8B57">■</span> Actual &nbsp; <span style="color:#1D4ED8">■</span> Predicted</div></div>
          </div>
          <div style="flex:1;min-width:280px">
            <div class="section-hdr"><h4><i class="ti ti-chart-line"></i>Monthly Projection Trend</h4></div>
            <div class="card">${_svgForecast(f.charts.monthlyProjectionTrend.historical, f.charts.monthlyProjectionTrend.forecast, { h: 80 })}
              <div style="font-size:10px;color:var(--t3);margin-top:.3rem"><span style="color:#2E8B57">■</span> Historical &nbsp; <span style="color:#94A3B8">┅</span> Forecast</div></div>
          </div>
        </div>

        <div class="frow" style="align-items:flex-start;gap:1rem;margin-bottom:1.25rem">
          <div style="flex:1;min-width:280px">
            <div class="section-hdr"><h4><i class="ti ti-chart-line"></i>Annual Projection</h4></div>
            <div class="card">${_svgForecast(f.charts.annualProjection.historical, f.charts.annualProjection.forecast, { h: 80, cf: '#7C3AED' })}</div>
          </div>
          <div style="flex:1;min-width:280px">
            <div class="section-hdr"><h4><i class="ti ti-wallet"></i>Budget Projection</h4></div>
            <div class="card">
              <div class="frow" style="gap:1.5rem;margin-bottom:.5rem">
                <div><div class="mclbl">Projected Annual Spend</div><div class="mcval" style="font-size:16px">${_fmtCur(f.kpis.budgetProjection.projectedAnnualSpend)}</div></div>
                <div><div class="mclbl">Estimated Budget</div><div class="mcval" style="font-size:16px">${_fmtCur(f.kpis.budgetProjection.estimatedBudget)}</div></div>
              </div>
              ${_pbar(f.kpis.budgetProjection.projectedUtilizationPct, f.kpis.budgetProjection.projectedUtilizationPct > 100 ? 'ex-pbar-red' : '')}
              <div style="font-size:11px;color:var(--t3);margin-top:.35rem">${f.kpis.budgetProjection.projectedUtilizationPct}% of estimated budget projected to be spent this year</div>
            </div>
          </div>
        </div>

        <div class="frow" style="align-items:flex-start;gap:1rem;margin-bottom:1.25rem">
          <div style="flex:1;min-width:260px">
            <div class="section-hdr"><h4><i class="ti ti-cart"></i>Procurement Demand</h4></div>
            <div class="card">${_svgForecast(f.charts.procurementDemand.historical, f.charts.procurementDemand.forecast, { h: 70, ch: '#7C3AED', cf: '#C4B5FD' })}</div>
          </div>
          <div style="flex:1;min-width:260px">
            <div class="section-hdr"><h4><i class="ti ti-building-store"></i>Supplier Demand Trend</h4></div>
            <div class="card">${f.charts.supplierDemandTrend.length ? _svgDualBar(f.charts.supplierDemandTrend, 'historicalAvgMonthly', 'forecastedNextMonth', { h: 70 }) : `<div style="height:70px;display:flex;align-items:center;justify-content:center;color:var(--t4);font-size:11px">No data</div>`}
              <div style="font-size:10px;color:var(--t3);margin-top:.3rem"><span style="color:#2E8B57">■</span> Historical Avg &nbsp; <span style="color:#1D4ED8">■</span> Forecasted Next Month</div></div>
          </div>
        </div>

        <div class="frow" style="align-items:flex-start;gap:1rem">
          <div style="flex:1;min-width:260px">
            <div class="section-hdr"><h4><i class="ti ti-sun"></i>Seasonal Procurement Trend</h4></div>
            <div class="card">${f.charts.seasonalTrend.length ? _svgBar(f.charts.seasonalTrend, 'avg', { h: 70, color: '#EA580C' }) : `<div style="height:70px;display:flex;align-items:center;justify-content:center;color:var(--t4);font-size:11px">No data</div>`}
              <div style="display:flex;justify-content:space-between;margin-top:.4rem;font-size:10px;color:var(--t3)">${f.charts.seasonalTrend.map((s) => `<span>${s.month}</span>`).join('')}</div></div>
          </div>
          <div style="flex:1;min-width:260px">
            <div class="section-hdr"><h4><i class="ti ti-file-alert"></i>Contract Renewal Timeline</h4></div>
            <div class="card">${renewalTimelineRows.length ? _svgBar(renewalTimelineRows, 'count', { h: 70, color: '#DC2626' }) : `<div style="height:70px;display:flex;align-items:center;justify-content:center;color:var(--t4);font-size:11px">No renewals due within 12 months</div>`}
              <div style="display:flex;justify-content:space-between;margin-top:.4rem;font-size:10px;color:var(--t3)">${_clabels(renewalTimelineRows, 'month', 6)}</div></div>
          </div>
        </div>

        <div class="section-hdr"><h4><i class="ti ti-calendar-event"></i>Procurement Calendar (next 90 days)</h4></div>
        <div class="card" style="padding:0;margin-bottom:1.25rem">
          <table class="tbl"><thead><tr><th>Date</th><th>Type</th><th>Event</th></tr></thead>
          <tbody>${f.calendar.length ? f.calendar.slice(0, 30).map((c) => `<tr><td style="font-size:12px">${_fmtDate(c.date) || c.date}</td><td>${c.type === 'contract_renewal' ? '<span class="badge ba">Renewal</span>' : '<span class="badge bb">Delivery</span>'}</td><td>${c.label}</td></tr>`).join('') : '<tr><td colspan="3" style="text-align:center;color:var(--t3);padding:2rem">No upcoming events.</td></tr>'}</tbody></table>
        </div>

        <div class="section-hdr" style="margin-top:1.5rem"><h4><i class="ti ti-file-report"></i>Executive Reports</h4></div>
        <div class="filter-bar">
          <select id="pfx-type-sel" class="filter-select">${Object.entries(PROC_EXEC_REPORT_META).map(([k, l]) => `<option value="${k}">${l}</option>`).join('')}</select>
          <button type="button" class="bs1" id="pfx-export-btn"><i class="ti ti-file-download"></i>Export CSV</button>
          <button type="button" class="bs1" id="pfx-print-btn"><i class="ti ti-printer"></i>Print</button>
        </div>
        <div class="lerr" id="pfx-err"></div>
        <div id="pfx-report-body"></div>`;

      let pfxRows = [];
      let pfxType = 'executive_summary';
      async function loadPfxReport() {
        const rbody = $('pfx-report-body');
        rbody.innerHTML = `<div class="card" style="padding:0"><table class="tbl"><thead><tr><th></th><th></th><th></th></tr></thead><tbody>${skeletonTableRows(6)}</tbody></table></div>`;
        const errEl = $('pfx-err');
        errEl.style.display = 'none';
        const r = await UFCL.procurementExecutiveReport(STORAGE.user.id, pfxType, {});
        if (!r.ok) { errEl.textContent = r.error; errEl.style.display = 'block'; rbody.innerHTML = ''; return; }
        if (r.rows) {
          pfxRows = r.rows;
          const keys = pfxRows.length ? Object.keys(pfxRows[0]) : [];
          rbody.innerHTML = `<div class="card" id="pfx-print-area" style="padding:0">
            <table class="tbl"><thead><tr>${keys.map((k) => `<th>${k.replace(/([A-Z])/g, ' $1').replace(/_/g, ' ')}</th>`).join('')}</tr></thead>
            <tbody>${pfxRows.length ? pfxRows.map((row) => `<tr>${keys.map((k) => `<td style="font-size:12px">${row[k] instanceof Date ? _fmtDate(row[k]) : (row[k] ?? '—')}</td>`).join('')}</tr>`).join('') : `<tr><td colspan="${keys.length || 1}" style="text-align:center;color:var(--t3);padding:2rem">No rows for this report.</td></tr>`}</tbody></table>
          </div>`;
        } else {
          pfxRows = [];
          const s = r.summary;
          rbody.innerHTML = `<div class="card" id="pfx-print-area"><pre style="white-space:pre-wrap;font-size:12px;color:var(--t2);font-family:var(--fm)">${JSON.stringify(s, null, 2)}</pre></div>`;
        }
      }
      $('pfx-type-sel').onchange = (e) => { pfxType = e.target.value; loadPfxReport(); };
      $('pfx-export-btn').onclick = async () => {
        if (!pfxRows.length) { showToast('This report has no exportable rows (summary-style report) — use Print instead.', 'error'); return; }
        const keys = Object.keys(pfxRows[0]);
        const lines = [keys, ...pfxRows.map((row) => keys.map((k) => (row[k] instanceof Date ? _fmtDate(row[k]) : row[k])))];
        const csv = lines.map((row) => row.map((c) => `"${String(c ?? '').replace(/"/g, '""')}"`).join(',')).join('\r\n');
        const filename = `procurement_${pfxType}_${new Date().toISOString().slice(0, 10)}.csv`;
        const res2 = await UFCL.execExport(STORAGE.user.id, { csv, filename });
        if (!res2?.ok && res2?.error !== undefined) showToast('Export cancelled or failed', 'error');
      };
      $('pfx-print-btn').onclick = () => window.print();
      await loadPfxReport();
    } else if (tab === 'analytics') {
      const r = await UFCL.procurementAnalytics(STORAGE.user.id);
      if (!r.ok) { body.innerHTML = `<p style="color:var(--red)">${r.error}</p>`; return; }
      body.innerHTML = `
        <div class="cards" style="margin-bottom:1.25rem">
          <div class="kpi-card kpi-blue"><div class="kpi-lbl">Avg Cycle Days</div><div class="kpi-val">${r.avgProcurementCycleDays}</div></div>
          <div class="kpi-card ${r.lateDeliveriesCount > 0 ? 'kpi-amber' : 'kpi-green'}"><div class="kpi-lbl">Late Deliveries</div><div class="kpi-val">${r.lateDeliveriesCount}</div></div>
        </div>
        <div class="section-hdr"><h4><i class="ti ti-package"></i>Top Purchased Products</h4></div>
        <div class="card" style="padding:0;margin-bottom:1rem">
          <table class="tbl"><thead><tr><th>Description</th><th>Times Ordered</th><th>Total Qty</th></tr></thead>
          <tbody>${r.topPurchasedProducts.length ? r.topPurchasedProducts.map((p) => `<tr><td>${p.description}</td><td>${p.times_ordered}</td><td>${p.total_qty}</td></tr>`).join('') : '<tr><td colspan="3" style="text-align:center;color:var(--t3);padding:2rem">No purchase history yet.</td></tr>'}</tbody></table>
        </div>
        <div class="section-hdr"><h4><i class="ti ti-trophy"></i>Supplier Rankings</h4></div>
        <div class="card" style="padding:0">
          <table class="tbl"><thead><tr><th>Supplier</th><th>POs</th><th>Total Spend</th></tr></thead>
          <tbody>${r.supplierRankings.length ? r.supplierRankings.map((s) => `<tr><td>${s.name}</td><td>${s.po_count}</td><td style="font-family:var(--fm)">${Number(s.total_spend).toLocaleString()}</td></tr>`).join('') : '<tr><td colspan="3" style="text-align:center;color:var(--t3);padding:2rem">No rankings yet.</td></tr>'}</tbody></table>
        </div>`;
    } else if (tab === 'srm') {
      // Phase 4 — SRM reports.
      let srmState = { type: 'contract_register' };
      body.innerHTML = `
        <div class="filter-bar">
          <select id="srm-type-sel" class="filter-select">${Object.entries(SRM_REPORT_META).map(([k, l]) => `<option value="${k}">${l}</option>`).join('')}</select>
          <button type="button" class="bs1" id="srm-export-btn"><i class="ti ti-file-download"></i>Export CSV</button>
        </div>
        <div class="lerr" id="srm-err"></div>
        <div id="srm-report-body"></div>`;

      let srmRows = [];
      async function loadSrmReport() {
        const rbody = $('srm-report-body');
        rbody.innerHTML = `<div class="card" style="padding:0"><table class="tbl"><thead><tr><th></th><th></th><th></th></tr></thead><tbody>${skeletonTableRows(6)}</tbody></table></div>`;
        const errEl = $('srm-err');
        errEl.style.display = 'none';
        const r = await UFCL.srmReport(STORAGE.user.id, srmState.type, {});
        if (!r.ok) { errEl.textContent = r.error; errEl.style.display = 'block'; rbody.innerHTML = ''; return; }
        $('srm-export-btn').style.display = srmState.type === 'executive_summary' ? 'none' : '';
        if (srmState.type === 'executive_summary') {
          const k = r.summary.kpis;
          rbody.innerHTML = `
            <div class="cards">
              <div class="kpi-card"><div class="kpi-lbl">Total Suppliers</div><div class="kpi-val">${k.totalSuppliers}</div></div>
              <div class="kpi-card kpi-green"><div class="kpi-lbl">Active Contracts</div><div class="kpi-val">${k.activeContracts}</div></div>
              <div class="kpi-card ${k.expiringContracts > 0 ? 'kpi-amber' : ''}"><div class="kpi-lbl">Expiring Contracts</div><div class="kpi-val">${k.expiringContracts}</div></div>
              <div class="kpi-card ${k.expiredContracts > 0 ? 'kpi-amber' : ''}"><div class="kpi-lbl">Expired Contracts</div><div class="kpi-val">${k.expiredContracts}</div></div>
              <div class="kpi-card"><div class="kpi-lbl">Compliance %</div><div class="kpi-val">${k.compliancePct}%</div></div>
              <div class="kpi-card ${k.missingDocuments > 0 ? 'kpi-amber' : ''}"><div class="kpi-lbl">Missing Documents</div><div class="kpi-val">${k.missingDocuments}</div></div>
              <div class="kpi-card"><div class="kpi-lbl">Open Improvement Plans</div><div class="kpi-val">${k.openImprovementPlans}</div></div>
              <div class="kpi-card ${k.highRiskSuppliers > 0 ? 'kpi-amber' : ''}"><div class="kpi-lbl">High Risk Suppliers</div><div class="kpi-val">${k.highRiskSuppliers}</div></div>
            </div>`;
          srmRows = [];
          return;
        }
        srmRows = r.rows || [];
        const keys = srmRows.length ? Object.keys(srmRows[0]) : [];
        rbody.innerHTML = `
          <div class="card" style="padding:0">
            <table class="tbl"><thead><tr>${keys.map((k) => `<th>${k.replace(/_/g, ' ')}</th>`).join('')}</tr></thead>
            <tbody>${srmRows.length ? srmRows.map((row) => `<tr>${keys.map((k) => `<td style="font-size:12px">${row[k] instanceof Date ? _fmtDate(row[k]) : (row[k] ?? '—')}</td>`).join('')}</tr>`).join('') : `<tr><td colspan="${keys.length || 1}" style="text-align:center;color:var(--t3);padding:2rem">No rows for this report.</td></tr>`}</tbody></table>
          </div>`;
      }
      $('srm-type-sel').onchange = (e) => { srmState.type = e.target.value; loadSrmReport(); };
      $('srm-export-btn').onclick = async () => {
        if (!srmRows.length) { showToast('Nothing to export.', 'error'); return; }
        const keys = Object.keys(srmRows[0]);
        const lines = [keys, ...srmRows.map((row) => keys.map((k) => (row[k] instanceof Date ? _fmtDate(row[k]) : row[k])))];
        const csv = lines.map((row) => row.map((c) => `"${String(c ?? '').replace(/"/g, '""')}"`).join(',')).join('\r\n');
        const filename = `srm_${srmState.type}_${new Date().toISOString().slice(0, 10)}.csv`;
        const r = await UFCL.execExport(STORAGE.user.id, { csv, filename });
        if (!r?.ok && r?.error !== undefined) showToast('Export cancelled or failed', 'error');
      };
      await loadSrmReport();
    } else if (tab === 'intelligence') {
      // Phase 3C — Executive (Supplier Intelligence) reports.
      let intelState = { type: 'best', search: '', category: '' };
      body.innerHTML = `
        <div class="filter-bar">
          <select id="intel-type-sel" class="filter-select">${Object.entries(INTEL_REPORT_META).map(([k, l]) => `<option value="${k}">${l}</option>`).join('')}</select>
          <div class="filter-search"><i class="ti ti-search"></i><input id="intel-search" type="text" placeholder="Search supplier or category…"></div>
          <button type="button" class="bs1" id="intel-export-btn"><i class="ti ti-file-download"></i>Export CSV</button>
        </div>
        <div class="lerr" id="intel-err"></div>
        <div class="card" style="padding:0">
          <table class="tbl" id="intel-table">
            <thead><tr>
              <th data-sort-key="name">Supplier</th><th data-sort-key="overallScore">Score</th><th>Rating</th>
              <th data-sort-key="totalSpend">Spend</th><th data-sort-key="rejectRatePct">Reject Rate</th>
              <th data-sort-key="onTimeRatePct">On-Time</th><th data-sort-key="lastPurchaseDate">Last Purchase</th><th>Risk</th>
            </tr></thead>
            <tbody id="intel-tbody">${skeletonTableRows(8)}</tbody>
          </table>
        </div>`;

      let intelRows = [];
      const intelSort = { key: null, dir: 'asc' };
      function intelRowHtml(s) {
        return `<tr>
          <td>${s.name}${s.preferred ? ' <i class="ti ti-star" style="color:var(--amber)"></i>' : ''}</td>
          <td style="font-family:var(--fm);font-weight:600">${s.overallScore}</td>
          <td>${supplierTierBadge(s.tier)}</td>
          <td style="font-family:var(--fm)">${Number(s.totalSpend).toLocaleString()}</td>
          <td>${s.rejectRatePct}%</td>
          <td>${s.onTimeRatePct ?? '—'}${s.onTimeRatePct != null ? '%' : ''}</td>
          <td style="font-size:12px">${s.lastPurchaseDate ? new Date(s.lastPurchaseDate).toLocaleDateString() : '—'}</td>
          <td style="font-size:12px">${s.riskIndicators[0] || '—'}</td>
        </tr>`;
      }
      function renderIntelRows(rows) {
        $('intel-tbody').innerHTML = rows.length ? rows.map(intelRowHtml).join('') : `<tr><td colspan="8" style="text-align:center;color:var(--t3);padding:2rem">No suppliers match this report.</td></tr>`;
      }
      function intelFiltered() {
        let out = intelRows;
        if (intelState.search.trim()) {
          const q = intelState.search.trim().toLowerCase();
          out = out.filter((s) => s.name.toLowerCase().includes(q) || (s.category || '').toLowerCase().includes(q));
        }
        return out;
      }
      async function loadIntelReport() {
        $('intel-tbody').innerHTML = skeletonTableRows(8);
        const errEl = $('intel-err');
        errEl.style.display = 'none';
        const r = await UFCL.supplierIntelligenceReport(STORAGE.user.id, intelState.type, {});
        intelRows = r.ok ? r.rows : [];
        if (!r.ok) { errEl.textContent = r.error; errEl.style.display = 'block'; }
        renderIntelRows(intelFiltered());
        wireSortableTable($('intel-table'), intelSort, intelFiltered, renderIntelRows);
      }
      $('intel-type-sel').onchange = (e) => { intelState.type = e.target.value; loadIntelReport(); };
      $('intel-search').oninput = (e) => { intelState.search = e.target.value; renderIntelRows(intelFiltered()); };
      $('intel-export-btn').onclick = async () => {
        const lines = [['Supplier', 'Score', 'Rating', 'Spend', 'Reject Rate %', 'On-Time %', 'Last Purchase', 'Primary Risk']];
        for (const s of intelFiltered()) lines.push([s.name, s.overallScore, s.tier, s.totalSpend, s.rejectRatePct, s.onTimeRatePct ?? '', s.lastPurchaseDate ? new Date(s.lastPurchaseDate).toLocaleDateString() : '', s.riskIndicators[0] || '']);
        const csv = lines.map((row) => row.map((c) => `"${String(c ?? '').replace(/"/g, '""')}"`).join(',')).join('\r\n');
        const filename = `supplier_${intelState.type}_${new Date().toISOString().slice(0, 10)}.csv`;
        const r = await UFCL.execExport(STORAGE.user.id, { csv, filename });
        if (!r?.ok && r?.error !== undefined) showToast('Export cancelled or failed', 'error');
      };
      await loadIntelReport();
    } else if (tab === 'automation') {
      // Phase 6 — Procurement Automation Engine: dashboard summary +
      // escalations (reusing the existing generic escalation:resolve IPC —
      // see main.js/preload.js comment) + Task Center.
      const [dashRes, taskRes] = await Promise.all([
        UFCL.procurementAutomationDashboard(STORAGE.user.id),
        UFCL.procurementTasksList(STORAGE.user.id, { status: 'open' }),
      ]);
      if (!dashRes.ok) { body.innerHTML = `<p style="color:var(--red)">${dashRes.error}</p>`; return; }
      const d = dashRes;
      let taskRows = taskRes.ok ? taskRes.rows : [];
      const autoState = { category: '', priority: '', search: '' };
      const CAT_LABELS = {
        pending_approvals: 'Pending Approvals', rfqs: 'RFQs', purchase_orders: 'Purchase Orders',
        goods_receipts: 'Goods Receipts', supplier_invoices: 'Supplier Invoices', contracts: 'Contracts',
        compliance: 'Compliance', corrective_actions: 'Corrective Actions',
        improvement_plans: 'Improvement Plans', supplier_reviews: 'Supplier Reviews',
      };
      const PRIORITY_BADGE = { high: 'br', medium: 'ba', low: 'bn' };

      function autoTaskFiltered() {
        let out = taskRows;
        if (autoState.category) out = out.filter((t) => t.category === autoState.category);
        if (autoState.priority) out = out.filter((t) => t.priority === autoState.priority);
        if (autoState.search.trim()) {
          const q = autoState.search.trim().toLowerCase();
          out = out.filter((t) => t.title.toLowerCase().includes(q));
        }
        return out;
      }
      function autoTaskRowHtml(t) {
        const overdue = t.due_date && new Date(t.due_date) < new Date(new Date().toDateString());
        return `<tr>
          <td><span class="badge ${PRIORITY_BADGE[t.priority] || 'bn'}">${t.priority}</span></td>
          <td>${t.title}</td>
          <td style="font-size:12px">${CAT_LABELS[t.category] || t.category}</td>
          <td style="font-size:12px">${t.owner_role}</td>
          <td style="font-size:12px${overdue ? ';color:var(--red);font-weight:600' : ''}">${t.due_date ? new Date(t.due_date).toLocaleDateString() : '—'}${overdue ? ' <i class="ti ti-alert-triangle"></i>' : ''}</td>
          <td>${t.deep_link ? `<button type="button" class="bs1 auto-task-open" data-page="${t.deep_link}">Open</button>` : ''}</td>
          <td><button type="button" class="bs1 auto-task-complete" data-id="${t.id}">Complete</button></td>
        </tr>`;
      }
      function renderAutoTaskRows() {
        const rows = autoTaskFiltered();
        $('auto-task-tbody').innerHTML = rows.length ? rows.map(autoTaskRowHtml).join('')
          : `<tr><td colspan="7" style="text-align:center;color:var(--t3);padding:2rem">No open tasks match these filters.</td></tr>`;
        document.querySelectorAll('.auto-task-open').forEach((btn) => {
          btn.onclick = () => showPage(btn.dataset.page);
        });
        document.querySelectorAll('.auto-task-complete').forEach((btn) => {
          btn.onclick = async () => {
            const r = await UFCL.procurementTaskComplete(STORAGE.user.id, Number(btn.dataset.id));
            if (!r.ok) { showToast(r.error || 'Could not complete task', 'error'); return; }
            taskRows = taskRows.filter((t) => t.id !== Number(btn.dataset.id));
            renderAutoTaskRows();
            showToast('Task completed', 'success');
          };
        });
      }

      const esc = d.escalations.active;
      const s = d.summary;
      body.innerHTML = `
        <div class="cards" style="margin-bottom:1.25rem">
          <div class="kpi-card ${s.pending_tasks > 0 ? 'kpi-blue' : ''}"><div class="kpi-lbl">Pending Tasks</div><div class="kpi-val">${s.pending_tasks}</div></div>
          <div class="kpi-card ${s.overdue_tasks > 0 ? 'kpi-red' : ''}"><div class="kpi-lbl">Overdue Tasks</div><div class="kpi-val">${s.overdue_tasks}</div></div>
          <div class="kpi-card ${s.pending_approvals > 0 ? 'kpi-amber' : ''}"><div class="kpi-lbl">Pending Approvals</div><div class="kpi-val">${s.pending_approvals}</div></div>
          <div class="kpi-card ${s.active_escalations > 0 ? 'kpi-red' : ''}"><div class="kpi-lbl">Escalations</div><div class="kpi-val">${s.active_escalations}</div></div>
          <div class="kpi-card ${s.contracts_expiring > 0 ? 'kpi-amber' : ''}"><div class="kpi-lbl">Contracts Expiring</div><div class="kpi-val">${s.contracts_expiring}</div></div>
          <div class="kpi-card ${s.compliance_expiring > 0 ? 'kpi-amber' : ''}"><div class="kpi-lbl">Compliance Expiring</div><div class="kpi-val">${s.compliance_expiring}</div></div>
          <div class="kpi-card ${s.outstanding_deliveries > 0 ? 'kpi-amber' : ''}"><div class="kpi-lbl">Outstanding Deliveries</div><div class="kpi-val">${s.outstanding_deliveries}</div></div>
          <div class="kpi-card ${s.outstanding_invoices > 0 ? 'kpi-amber' : ''}"><div class="kpi-lbl">Outstanding Invoices</div><div class="kpi-val">${s.outstanding_invoices}</div></div>
        </div>

        <div class="section-hdr"><h4><i class="ti ti-alert-triangle"></i>Active Escalations</h4></div>
        <div class="card" style="padding:0;margin-bottom:1.25rem">
          <table class="tbl"><thead><tr><th>Type</th><th>Reference</th><th>Level</th><th>Age</th><th></th></tr></thead>
          <tbody>${esc.length ? esc.map((e) => `<tr>
            <td style="font-size:12px">${(e.entity_type || '').replace('procurement_', '').replace('_', ' ')}</td>
            <td>${e.entity_ref || e.entity_id}</td>
            <td><span class="badge ${e.current_level === 'ceo' ? 'br' : e.current_level === 'director' ? 'ba' : 'bb'}">${e.current_level}</span></td>
            <td style="font-size:12px">${e.age_hours}h</td>
            <td><button type="button" class="bs1 auto-esc-resolve" data-id="${e.id}">Resolve</button></td>
          </tr>`).join('') : `<tr><td colspan="5" style="text-align:center;color:var(--t3);padding:1.5rem">No active procurement escalations — nothing is stuck.</td></tr>`}</tbody></table>
        </div>

        <div class="section-hdr"><h4><i class="ti ti-list-check"></i>Procurement Task Center</h4></div>
        <div class="filter-bar">
          <select id="auto-cat-sel" class="filter-select"><option value="">All Categories</option>${Object.entries(CAT_LABELS).map(([k, l]) => `<option value="${k}">${l}</option>`).join('')}</select>
          <select id="auto-pri-sel" class="filter-select"><option value="">All Priorities</option><option value="high">High</option><option value="medium">Medium</option><option value="low">Low</option></select>
          <div class="filter-search"><i class="ti ti-search"></i><input id="auto-search" type="text" placeholder="Search tasks…"></div>
        </div>
        <div class="card" style="padding:0">
          <table class="tbl" id="auto-task-table">
            <thead><tr><th>Priority</th><th>Task</th><th>Category</th><th>Owner Role</th><th>Due</th><th></th><th></th></tr></thead>
            <tbody id="auto-task-tbody">${taskRes.ok ? '' : skeletonTableRows(5)}</tbody>
          </table>
        </div>`;

      renderAutoTaskRows();
      $('auto-cat-sel').onchange = (e) => { autoState.category = e.target.value; renderAutoTaskRows(); };
      $('auto-pri-sel').onchange = (e) => { autoState.priority = e.target.value; renderAutoTaskRows(); };
      $('auto-search').oninput = (e) => { autoState.search = e.target.value; renderAutoTaskRows(); };
      document.querySelectorAll('.auto-esc-resolve').forEach((btn) => {
        btn.onclick = async () => {
          const reason = prompt('Resolution reason:', 'Manually resolved');
          if (!reason) return;
          const r = await UFCL.escalationResolve(STORAGE.user.id, Number(btn.dataset.id), reason);
          if (!r?.ok) { showToast(r?.error || 'Could not resolve escalation', 'error'); return; }
          showToast('Escalation resolved', 'success');
          loadTab('automation');
        };
      });
    } else if (tab === 'performance') {
      // Phase 7 — Procurement Performance Management: Scorecard / Buyers /
      // Departments / Workshops / Executive / Risk, all composed from the
      // existing Analytics/Forecasting/Supplier Intelligence/Automation
      // engines (no duplicated SQL — see PROCUREMENT_PERFORMANCE_PHASE7_
      // COMPLETION_REPORT.md).
      const SUBVIEWS = [
        ['scorecard', 'Scorecard'], ['buyers', 'Buyers'], ['departments', 'Departments'],
        ['workshops', 'Workshops'], ['executive', 'Executive'], ['risk', 'Risk'],
      ];
      const perfState = { view: 'scorecard' };
      const perfCache = {};
      const KPI_UNIT = (u, v) => v == null ? '—' : u === 'days' ? `${v}d` : u === 'currency' ? _fmtCur(v) : u === 'score' ? v : `${v}%`;
      const TREND_ICON = { up: 'ti-trending-up', down: 'ti-trending-down', flat: 'ti-minus' };

      body.innerHTML = `
        <div style="display:flex;gap:.5rem;margin-bottom:1rem;flex-wrap:wrap" id="perf-subnav">
          ${SUBVIEWS.map(([k, l], i) => `<button class="filter-chip perf-sub-tab ${i === 0 ? 'active' : ''}" data-sub="${k}">${l}</button>`).join('')}
        </div>
        <div id="perf-body"><div class="card" style="padding:0"><table class="tbl"><thead><tr><th></th><th></th><th></th></tr></thead><tbody>${skeletonTableRows(4)}</tbody></table></div></div>`;

      async function loadPerfSub(view) {
        const pbody = $('perf-body');
        pbody.innerHTML = `<div class="card" style="padding:0"><table class="tbl"><thead><tr><th></th><th></th><th></th></tr></thead><tbody>${skeletonTableRows(4)}</tbody></table></div>`;

        if (view === 'scorecard') {
          if (!perfCache.scorecard) perfCache.scorecard = await UFCL.procurementPerformanceScorecard(STORAGE.user.id);
          const r = perfCache.scorecard;
          if (!r.ok) { pbody.innerHTML = `<p style="color:var(--red)">${r.error}</p>`; return; }
          const cards = Object.values(r.kpis).map((k) => {
            const variantCls = k.variance == null ? '' : k.variance >= 0 ? 'kpi-green' : 'kpi-red';
            return `<div class="kpi-card ${variantCls}">
              <div class="kpi-lbl">${k.label}</div>
              <div class="kpi-val">${KPI_UNIT(k.unit, k.current)}</div>
              <div style="font-size:11px;color:var(--t3);display:flex;align-items:center;gap:4px;margin-top:4px">
                <i class="ti ${TREND_ICON[k.trend]}"></i>${k.previous != null ? `prev ${KPI_UNIT(k.unit, k.previous)}` : 'no prior period'}
                ${k.target != null ? ` · target ${KPI_UNIT(k.unit === 'currency' ? undefined : k.unit, k.target)}` : ''}
              </div>
            </div>`;
          }).join('');
          pbody.innerHTML = `<div class="cards">${cards}</div>`;
        } else if (view === 'buyers') {
          if (!perfCache.buyers) perfCache.buyers = await UFCL.procurementPerformanceBuyers(STORAGE.user.id);
          const r = perfCache.buyers;
          if (!r.ok) { pbody.innerHTML = `<p style="color:var(--red)">${r.error}</p>`; return; }
          pbody.innerHTML = `<div class="card" style="padding:0"><table class="tbl">
            <thead><tr><th>#</th><th>Buyer</th><th>Requisitions</th><th>RFQs</th><th>POs</th><th>Avg Cycle</th><th>Savings</th><th>Contract %</th><th>Budget %</th><th>Escalations</th><th>Tasks Done</th><th>Score</th></tr></thead>
            <tbody>${r.buyers.length ? r.buyers.map((b) => `<tr>
              <td class="${_rankCls(b.rank - 1)}">${b.rank}</td>
              <td>${b.name}</td><td>${b.requisitionsProcessed}</td><td>${b.rfqsManaged}</td><td>${b.purchaseOrdersIssued}</td>
              <td>${b.avgProcurementCycleDays ?? '—'}${b.avgProcurementCycleDays != null ? 'd' : ''}</td>
              <td style="font-family:var(--fm)">${_fmtCur(b.procurementSavingsGenerated)}</td>
              <td>${b.contractCompliancePct ?? '—'}${b.contractCompliancePct != null ? '%' : ''}</td>
              <td>${b.budgetCompliancePct ?? '—'}${b.budgetCompliancePct != null ? '%' : ''}</td>
              <td>${b.escalationsReceived}</td><td>${b.tasksCompleted}</td>
              <td style="font-weight:600">${b.overallScore ?? '—'}</td>
            </tr>`).join('') : '<tr><td colspan="12" style="text-align:center;color:var(--t3);padding:2rem">No buyer activity yet.</td></tr>'}</tbody></table></div>`;
        } else if (view === 'departments') {
          if (!perfCache.departments) perfCache.departments = await UFCL.procurementPerformanceDepartments(STORAGE.user.id);
          const r = perfCache.departments;
          if (!r.ok) { pbody.innerHTML = `<p style="color:var(--red)">${r.error}</p>`; return; }
          pbody.innerHTML = `<div class="card" style="padding:0"><table class="tbl">
            <thead><tr><th>Department</th><th>Spend</th><th>Budget Usage</th><th>Variance</th><th>Volume</th><th>Avg Cycle</th><th>Efficiency</th><th>Risk</th></tr></thead>
            <tbody>${r.departments.length ? r.departments.map((d) => `<tr>
              <td>${d.department}</td><td style="font-family:var(--fm)">${_fmtCur(d.procurementSpend)}</td>
              <td>${d.budgetUsagePct ?? '—'}${d.budgetUsagePct != null ? '%' : ''}</td>
              <td style="color:${d.budgetVariance >= 0 ? 'var(--green)' : 'var(--red)'}">${_fmtCur(d.budgetVariance)}</td>
              <td>${d.procurementVolume}</td><td>${d.avgCycleDays ?? '—'}${d.avgCycleDays != null ? 'd' : ''}</td>
              <td>${d.efficiency ?? '—'}${d.efficiency != null ? '%' : ''}</td>
              <td><span class="badge ${d.procurementRisk === 'high' ? 'br' : d.procurementRisk === 'medium' ? 'ba' : 'bg'}">${d.procurementRisk}</span></td>
            </tr>`).join('') : '<tr><td colspan="8" style="text-align:center;color:var(--t3);padding:2rem">No department spend yet.</td></tr>'}</tbody></table></div>`;
        } else if (view === 'workshops') {
          if (!perfCache.workshops) perfCache.workshops = await UFCL.procurementPerformanceWorkshops(STORAGE.user.id);
          const r = perfCache.workshops;
          if (!r.ok) { pbody.innerHTML = `<p style="color:var(--red)">${r.error}</p>`; return; }
          pbody.innerHTML = `<div class="card" style="padding:0"><table class="tbl">
            <thead><tr><th>Workshop</th><th>Requests</th><th>Cost</th><th>Outstanding</th><th>Lead Time</th><th>Efficiency</th><th>Budget %</th><th></th></tr></thead>
            <tbody>${r.workshops.length ? r.workshops.map((w) => `<tr>
              <td>${w.workshop}</td><td>${w.procurementRequests}</td><td style="font-family:var(--fm)">${_fmtCur(w.procurementCost)}</td>
              <td>${w.outstandingDeliveries}</td><td>${w.procurementLeadTimeDays ?? '—'}${w.procurementLeadTimeDays != null ? 'd' : ''}</td>
              <td>${w.efficiency ?? '—'}${w.efficiency != null ? '%' : ''}</td>
              <td>${w.budgetCompliancePct ?? '—'}${w.budgetCompliancePct != null ? '%' : ''}</td>
              <td>${w.workshopId != null ? `<button type="button" class="bs1 perf-ws-drill" data-id="${w.workshopId}" data-name="${w.workshop}">Orders</button>` : ''}</td>
            </tr>`).join('') : '<tr><td colspan="8" style="text-align:center;color:var(--t3);padding:2rem">No workshop spend yet.</td></tr>'}</tbody></table></div>`;
          document.querySelectorAll('.perf-ws-drill').forEach((btn) => {
            btn.onclick = () => drillIntoOrdersByWorkshop(Number(btn.dataset.id), btn.dataset.name);
          });
        } else if (view === 'executive') {
          if (!perfCache.executive) perfCache.executive = await UFCL.procurementPerformanceExecutive(STORAGE.user.id);
          const r = perfCache.executive;
          if (!r.ok) { pbody.innerHTML = `<p style="color:var(--red)">${r.error}</p>`; return; }
          const k = r.kpis;
          pbody.innerHTML = `
            <div class="cards" style="margin-bottom:1.25rem">
              <div class="kpi-card kpi-blue"><div class="kpi-lbl">Procurement Health</div><div class="kpi-val">${k.procurementHealth ?? '—'}</div></div>
              <div class="kpi-card"><div class="kpi-lbl">Total Spend</div><div class="kpi-val">${_fmtCur(k.totalProcurementSpend)}</div></div>
              <div class="kpi-card ${k.budgetUtilization > 100 ? 'kpi-red' : 'kpi-green'}"><div class="kpi-lbl">Budget Utilization</div><div class="kpi-val">${k.budgetUtilization ?? '—'}%</div></div>
              <div class="kpi-card kpi-green"><div class="kpi-lbl">Procurement Savings</div><div class="kpi-val">${_fmtCur(k.procurementSavings)}</div></div>
              <div class="kpi-card"><div class="kpi-lbl">Forecast Accuracy</div><div class="kpi-val">${k.forecastAccuracy ?? '—'}${k.forecastAccuracy != null ? '%' : ''}</div></div>
              <div class="kpi-card"><div class="kpi-lbl">Supplier Performance</div><div class="kpi-val">${k.supplierPerformance ?? '—'}</div></div>
              <div class="kpi-card ${k.contractsExpiring > 0 ? 'kpi-amber' : ''}"><div class="kpi-lbl">Contracts Expiring</div><div class="kpi-val">${k.contractsExpiring}</div></div>
              <div class="kpi-card ${k.complianceStatus > 0 ? 'kpi-amber' : ''}"><div class="kpi-lbl">Compliance Issues</div><div class="kpi-val">${k.complianceStatus}</div></div>
              <div class="kpi-card"><div class="kpi-lbl">Automation Performance</div><div class="kpi-val">${k.automationPerformance ?? '—'}%</div></div>
              <div class="kpi-card ${k.outstandingRisks > 40 ? 'kpi-red' : k.outstandingRisks > 20 ? 'kpi-amber' : 'kpi-green'}"><div class="kpi-lbl">Outstanding Risk</div><div class="kpi-val">${k.outstandingRisks ?? '—'}</div></div>
            </div>
            <div class="section-hdr"><h4><i class="ti ti-chart-line"></i>Procurement Spend Trend</h4></div>
            <div class="card" style="margin-bottom:1rem">${r.charts.procurementTrend.length ? _svgLine(r.charts.procurementTrend, 'total', { h: 120 }) : '<p style="color:var(--t3);font-size:12px">No trend data yet.</p>'}</div>
            <div class="section-hdr"><h4><i class="ti ti-building"></i>Department Comparison</h4></div>
            <div class="card" style="margin-bottom:1rem">
              ${r.charts.departmentComparison.length ? _svgBar(r.charts.departmentComparison, 'spend', { h: 140 }) : '<p style="color:var(--t3);font-size:12px">No department data yet.</p>'}
              ${r.charts.departmentComparison.length ? `<div class="frow" style="justify-content:space-between;font-size:11px;color:var(--t3);margin-top:4px">${r.charts.departmentComparison.map((d) => `<span>${d.department}</span>`).join('')}</div>` : ''}
            </div>
            <div class="section-hdr"><h4><i class="ti ti-tools"></i>Workshop Comparison</h4></div>
            <div class="card" style="margin-bottom:1rem">
              ${r.charts.workshopComparison.length ? _svgBar(r.charts.workshopComparison, 'cost', { h: 140 }) : '<p style="color:var(--t3);font-size:12px">No workshop data yet.</p>'}
              ${r.charts.workshopComparison.length ? `<div class="frow" style="justify-content:space-between;font-size:11px;color:var(--t3);margin-top:4px">${r.charts.workshopComparison.map((w) => `<span>${w.workshop}</span>`).join('')}</div>` : ''}
            </div>
            <div class="section-hdr"><h4><i class="ti ti-award"></i>Buyer Ranking</h4></div>
            <div class="card">${r.charts.buyerRanking.length ? r.charts.buyerRanking.map((b, i) => `<div class="frow" style="justify-content:space-between;padding:4px 0"><span>${i + 1}. ${b.name}</span><strong>${b.score ?? '—'}</strong></div>`).join('') : '<p style="color:var(--t3);font-size:12px">No buyer ranking yet.</p>'}</div>`;
        } else if (view === 'risk') {
          if (!perfCache.risk) perfCache.risk = await UFCL.procurementPerformanceRisk(STORAGE.user.id);
          const r = perfCache.risk;
          if (!r.ok) { pbody.innerHTML = `<p style="color:var(--red)">${r.error}</p>`; return; }
          pbody.innerHTML = `
            <div class="cards" style="margin-bottom:1.25rem">
              <div class="kpi-card ${r.highRiskSuppliers.length ? 'kpi-red' : ''}"><div class="kpi-lbl">High Risk Suppliers</div><div class="kpi-val">${r.highRiskSuppliers.length}</div></div>
              <div class="kpi-card ${r.budgetRisk.length ? 'kpi-red' : ''}"><div class="kpi-lbl">Budget Codes Over</div><div class="kpi-val">${r.budgetRisk.length}</div></div>
              <div class="kpi-card ${r.outstandingApprovals > 0 ? 'kpi-amber' : ''}"><div class="kpi-lbl">Outstanding Approvals</div><div class="kpi-val">${r.outstandingApprovals}</div></div>
              <div class="kpi-card ${r.expiringContracts > 0 ? 'kpi-amber' : ''}"><div class="kpi-lbl">Contracts Expiring</div><div class="kpi-val">${r.expiringContracts}</div></div>
              <div class="kpi-card ${r.complianceRisks > 0 ? 'kpi-amber' : ''}"><div class="kpi-lbl">Compliance Risks</div><div class="kpi-val">${r.complianceRisks}</div></div>
              <div class="kpi-card ${r.escalationVolume > 0 ? 'kpi-red' : ''}"><div class="kpi-lbl">Active Escalations</div><div class="kpi-val">${r.escalationVolume}</div></div>
              <div class="kpi-card ${r.automationFailedTicks > 0 ? 'kpi-amber' : ''}"><div class="kpi-lbl">Automation Failures (recent)</div><div class="kpi-val">${r.automationFailedTicks}/${r.automationTicksChecked}</div></div>
            </div>
            <div class="section-hdr"><h4><i class="ti ti-alert-octagon"></i>High Risk Suppliers</h4></div>
            <div class="card" style="padding:0;margin-bottom:1rem"><table class="tbl"><thead><tr><th>Supplier</th><th>Score</th><th>Primary Issue</th><th>Recommendation</th></tr></thead>
            <tbody>${r.highRiskSuppliers.length ? r.highRiskSuppliers.map((s) => `<tr><td>${s.name}</td><td>${s.score}</td><td>${s.primaryIssue}</td><td style="font-size:12px">${s.recommendation}</td></tr>`).join('') : '<tr><td colspan="4" style="text-align:center;color:var(--t3);padding:1.5rem">No high risk suppliers.</td></tr>'}</tbody></table></div>
            <div class="section-hdr"><h4><i class="ti ti-wallet"></i>Budget Risk</h4></div>
            <div class="card" style="padding:0"><table class="tbl"><thead><tr><th>Budget Code</th><th>Utilization</th><th>Overspend</th></tr></thead>
            <tbody>${r.budgetRisk.length ? r.budgetRisk.map((b) => `<tr><td>${b.budgetCode}</td><td>${b.utilizationPct}%</td><td style="color:var(--red)">${_fmtCur(b.overspend)}</td></tr>`).join('') : '<tr><td colspan="3" style="text-align:center;color:var(--t3);padding:1.5rem">No budget codes over 100% utilization.</td></tr>'}</tbody></table></div>`;
        }
      }

      document.querySelectorAll('.perf-sub-tab').forEach((btn) => {
        btn.onclick = () => {
          document.querySelectorAll('.perf-sub-tab').forEach((b) => b.classList.remove('active'));
          btn.classList.add('active');
          perfState.view = btn.dataset.sub;
          loadPerfSub(perfState.view);
        };
      });
      await loadPerfSub('scorecard');
    }
  }

  document.querySelectorAll('.pr-rep-tab').forEach((btn) => {
    btn.onclick = () => {
      document.querySelectorAll('.pr-rep-tab').forEach((b) => b.classList.remove('active'));
      btn.classList.add('active');
      loadTab(btn.dataset.tab);
    };
  });
  await loadTab('spend');
}

// ── Settings (Phase 2B, Priority 1) ──────────────────────────────────────────
// Page itself is only visible to admin/ceo (see db/migrate.js
// grantProcurementPermissions — procurement-settings is granted to admin/ceo
// only, so the sidebar never shows this to anyone else). The `canEdit` check
// below is a second, defense-in-depth layer matching the same pattern used
// elsewhere in this app; the real enforcement is procurementConfigUpdate's
// own existing admin/ceo check in data.js, which this screen does not alter.

async function renderProcurementSettings() {
  const page = $('page-procurement-settings');
  const canEdit = ['admin', 'ceo'].includes(STORAGE.user?.role);

  page.innerHTML = `
    <div class="page-head"><div class="page-head-text">
      <div class="ptitle"><i class="ti ti-settings" style="color:var(--g-soft)"></i> Procurement Settings</div>
      <div class="psub">Configure approval thresholds and module-wide procurement behavior.</div>
    </div></div>
    <div class="card"><div class="skel-row w-40"></div><div class="skel-row w-60"></div><div class="skel-row w-25"></div></div>`;

  const res = await UFCL.procurementConfigGet(STORAGE.user.id);
  if (!res.ok) return renderDenied('procurement-settings', res.error);
  const cfg = res.config || {};

  page.innerHTML = `
    <div class="page-head"><div class="page-head-text">
      <div class="ptitle"><i class="ti ti-settings" style="color:var(--g-soft)"></i> Procurement Settings</div>
      <div class="psub">Configure approval thresholds and module-wide procurement behavior.</div>
    </div></div>

    ${!canEdit ? `<div class="appbar" style="background:var(--amber-l);border-color:rgba(217,119,6,.25)"><p style="color:#92400E"><i class="ti ti-lock"></i>You have read-only access to Procurement Settings — only Admin/CEO can make changes.</p></div>` : ''}

    <div class="section-hdr"><h4><i class="ti ti-crown"></i>Approval Thresholds</h4></div>
    <div class="card">
      <div class="frow full">
        <div class="fg">
          <label>CEO Approval Threshold (RWF) *</label>
          <input id="ps-threshold" type="number" min="0" step="0.01" value="${Number(cfg.ceo_threshold || 0)}" ${canEdit ? '' : 'disabled'}>
        </div>
      </div>
      <p style="font-size:12px;color:var(--t3);margin:-.25rem 0 .75rem;line-height:1.6">
        Purchase requisitions with an estimated total <strong>above</strong> this amount require an additional
        <strong>CEO</strong> approval stage, on top of the standard Supervisor → Department Manager → Procurement
        Review → Finance chain. Requisitions at or below this amount skip the CEO stage. This does not change who
        can approve each existing stage — only whether the CEO stage is added.
      </p>
      <div id="ps-err" class="lerr"></div>
      <div id="ps-ok" class="lerr" style="display:none;background:var(--g-light);color:var(--g-dark);border-color:rgba(30,95,54,.25)"></div>
      ${cfg.updated_at ? `<p style="font-size:11px;color:var(--t4);margin-bottom:.5rem"><i class="ti ti-history"></i> Last updated ${new Date(cfg.updated_at).toLocaleString()}${cfg.updated_by_name ? ' by ' + cfg.updated_by_name : ''}</p>` : ''}
      ${canEdit ? `
      <div class="brow">
        <button class="bp1" id="ps-save"><i class="ti ti-check"></i>Save Changes</button>
        <button class="bs1" id="ps-cancel">Cancel</button>
      </div>` : ''}
    </div>`;

  if (!canEdit) return;

  const originalValue = String(Number(cfg.ceo_threshold || 0));

  $('ps-save').onclick = async () => {
    const errEl = $('ps-err'), okEl = $('ps-ok');
    errEl.style.display = 'none'; okEl.style.display = 'none';
    const raw = $('ps-threshold').value.trim();
    const val = Number(raw);
    if (raw === '' || Number.isNaN(val) || val < 0) {
      errEl.textContent = 'Enter a valid non-negative amount.';
      errEl.style.display = 'block';
      return;
    }
    const res2 = await UFCL.procurementConfigUpdate(STORAGE.user.id, val);
    if (!res2.ok) {
      errEl.textContent = res2.error || 'Could not save settings.';
      errEl.style.display = 'block';
      return;
    }
    showToast('Procurement settings saved.');
    await renderProcurementSettings();
  };

  $('ps-cancel').onclick = () => {
    $('ps-threshold').value = originalValue;
    $('ps-err').style.display = 'none';
  };
}